static ds4_gpu_qwen35_expert_pack_state *ds4_gpu_expert_pack_for_store(
        ds4_gpu_expert_store_id store_id) {
    switch (store_id) {
    case DS4_GPU_EXPERT_STORE_TARGET:
        return &g_qwen35_expert_pack;
    case DS4_GPU_EXPERT_STORE_SUPPORT:
        return g_dspark_expert_pack;
    case DS4_GPU_EXPERT_STORE_COUNT:
        break;
    }
    return NULL;
}

static int ds4_gpu_expert_store_layer_index(
        const ds4_gpu_qwen35_expert_pack_state *pack,
        uint32_t                                layer,
        uint32_t                               *index_out) {
    if (!pack || !index_out || pack->n_layer == 0 ||
        layer > DS4_EXPERT_STORE_MAX_MODEL_LAYER) {
        return 0;
    }
    if (layer < pack->n_layer && pack->layers[layer].layer == layer) {
        *index_out = layer;
        return 1;
    }
    uint32_t lo = 0;
    uint32_t hi = pack->n_layer;
    while (lo < hi) {
        const uint32_t mid = lo + (hi - lo) / 2u;
        if (pack->layers[mid].layer < layer) lo = mid + 1u;
        else hi = mid;
    }
    if (lo >= pack->n_layer || pack->layers[lo].layer != layer) return 0;
    *index_out = lo;
    return 1;
}
