static int ds4_gpu_stream_expert_timing_has_data(
        ds4_gpu_stream_expert_timing_snapshot s) {
    return s.selected_calls != 0 ||
           s.overlap_route_calls != 0 ||
           s.overlap_finish_calls != 0 ||
           s.split_layers != 0 ||
           s.load_calls != 0 ||
           s.cache_all_resident_layers != 0 ||
           s.cache_all_missing_layers != 0 ||
           s.cache_mixed_layers != 0;
}

static void ds4_gpu_stream_expert_timing_print(
        const char *scope,
        ds4_gpu_stream_expert_timing_snapshot s) {
    if (!ds4_gpu_stream_expert_timing_has_data(s)) return;
    const double selected_calls = (double)s.selected_calls;
    const double split_layers = (double)s.split_layers;
    const double selected_read_avg =
        selected_calls != 0.0 ? s.selected_read_ms / selected_calls : 0.0;
    const double selected_sync_avg =
        selected_calls != 0.0 ? s.selected_sync_ms / selected_calls : 0.0;
    const double selected_copy_avg =
        selected_calls != 0.0 ? s.selected_copy_ms / selected_calls : 0.0;
    const double selected_bind_avg =
        selected_calls != 0.0 ? s.selected_bind_ms / selected_calls : 0.0;
    const double overlap_route_calls = (double)s.overlap_route_calls;
    const double overlap_route_wait_avg =
        overlap_route_calls != 0.0 ?
            s.overlap_route_wait_ms / overlap_route_calls : 0.0;
    const double overlap_route_copy_avg =
        overlap_route_calls != 0.0 ?
            s.overlap_route_copy_ms / overlap_route_calls : 0.0;
    const double overlap_route_plan_avg =
        overlap_route_calls != 0.0 ?
            s.overlap_route_plan_ms / overlap_route_calls : 0.0;
    const double overlap_finish_calls = (double)s.overlap_finish_calls;
    const double overlap_finish_publish_avg =
        overlap_finish_calls != 0.0 ?
            s.overlap_finish_publish_ms / overlap_finish_calls : 0.0;
    const double overlap_finish_wait_avg =
        overlap_finish_calls != 0.0 ?
            s.overlap_finish_wait_ms / overlap_finish_calls : 0.0;
    const double overlap_finish_modify_avg =
        overlap_finish_calls != 0.0 ?
            s.overlap_finish_modify_ms / overlap_finish_calls : 0.0;
    const double overlap_finish_install_avg =
        overlap_finish_calls != 0.0 ?
            s.overlap_finish_install_ms / overlap_finish_calls : 0.0;
    const double split_resident_avg =
        split_layers != 0.0 ? s.split_resident_ms / split_layers : 0.0;
    const double split_missing_avg =
        split_layers != 0.0 ? s.split_missing_ms / split_layers : 0.0;
    const double split_missing_load_avg =
        split_layers != 0.0 ?
            s.split_missing_load_ms / split_layers : 0.0;
    const double split_missing_slot_avg =
        split_layers != 0.0 ?
            s.split_missing_slot_ms / split_layers : 0.0;
    const double split_missing_prune_avg =
        split_layers != 0.0 ?
            s.split_missing_prune_ms / split_layers : 0.0;
    const double split_missing_addr_avg =
        split_layers != 0.0 ?
            s.split_missing_addr_ms / split_layers : 0.0;
    const double split_missing_wait_avg =
        split_layers != 0.0 ?
            s.split_missing_wait_ms / split_layers : 0.0;
    const double load_calls = (double)s.load_calls;
    const double load_prepare_avg =
        load_calls != 0.0 ? s.load_prepare_ms / load_calls : 0.0;
    const double load_pread_avg =
        load_calls != 0.0 ? s.load_pread_ms / load_calls : 0.0;
    const double load_modify_avg =
        load_calls != 0.0 ? s.load_modify_ms / load_calls : 0.0;
    const double load_install_avg =
        load_calls != 0.0 ? s.load_install_ms / load_calls : 0.0;
    const double prepare_batch_reuse_avg =
        s.prepare_batch_reuse_calls != 0 ?
            s.prepare_batch_reuse_ms /
                (double)s.prepare_batch_reuse_calls : 0.0;
    const double prepare_buffer_avg =
        s.prepare_buffer_calls != 0 ?
            s.prepare_buffer_ms / (double)s.prepare_buffer_calls : 0.0;
    const double prepare_task_avg =
        s.prepare_task_experts != 0 ?
            s.prepare_task_ms / (double)s.prepare_task_experts : 0.0;
    const double reuse_scan_avg =
        s.reuse_scan_calls != 0 ?
            s.reuse_scan_ms / (double)s.reuse_scan_calls : 0.0;
    const double reuse_scan_entries_avg =
        s.reuse_scan_calls != 0 ?
            (double)s.reuse_scan_entries / (double)s.reuse_scan_calls : 0.0;
    const double readahead_avg =
        s.readahead_calls != 0 ?
            s.readahead_ms / (double)s.readahead_calls : 0.0;
    const double split_resident_experts_avg =
        split_layers != 0.0 ?
            (double)s.split_resident_experts / split_layers : 0.0;
    const double split_missing_experts_avg =
        split_layers != 0.0 ?
            (double)s.split_missing_experts / split_layers : 0.0;
    const uint64_t cache_layers =
        s.cache_all_resident_layers +
        s.cache_all_missing_layers +
        s.cache_mixed_layers;
    const double cache_layer_count = (double)cache_layers;
    const double cache_resident_experts_avg =
        cache_layer_count != 0.0 ?
            (double)s.cache_resident_experts / cache_layer_count : 0.0;
    const double cache_missing_experts_avg =
        cache_layer_count != 0.0 ?
            (double)s.cache_missing_experts / cache_layer_count : 0.0;
    fprintf(stderr,
            "ds4:   streaming expert timing %s selected_calls=%llu read_avg=%.3f ms sync_avg=%.3f ms copy_avg=%.3f ms bind_avg=%.3f ms read_total=%.3f ms sync_total=%.3f ms copy_total=%.3f ms bind_total=%.3f ms split_layers=%llu resident_experts_avg=%.2f missing_experts_avg=%.2f resident_submit_avg=%.3f ms missing_bind_avg=%.3f ms resident_submit_total=%.3f ms missing_bind_total=%.3f ms missing_load_avg=%.3f ms missing_slot_avg=%.3f ms missing_prune_avg=%.3f ms missing_addr_avg=%.3f ms missing_wait_avg=%.3f ms missing_wait_total=%.3f ms load_calls=%llu load_prepare_avg=%.3f ms load_pread_avg=%.3f ms load_modify_avg=%.3f ms load_install_avg=%.3f ms prepare_batch_reuse_calls=%llu prepare_batch_reuse_avg=%.3f ms prepare_batch_reuse_total=%.3f ms prepare_buffer_calls=%llu prepare_buffer_avg=%.3f ms prepare_buffer_total=%.3f ms prepare_task_experts=%llu prepare_task_avg=%.3f ms prepare_task_total=%.3f ms reuse_scan_calls=%llu reuse_scan_entries_avg=%.1f reuse_scan_avg=%.3f ms reuse_scan_total=%.3f ms reuse_clear_total=%.3f ms readahead_calls=%llu readahead_avg=%.3f ms readahead_total=%.3f ms readahead_gib=%.2f cache_all_resident=%llu cache_all_missing=%llu cache_mixed=%llu cache_resident_avg=%.2f cache_missing_avg=%.2f\n",
            scope ? scope : "total",
            (unsigned long long)s.selected_calls,
            selected_read_avg,
            selected_sync_avg,
            selected_copy_avg,
            selected_bind_avg,
            s.selected_read_ms,
            s.selected_sync_ms,
            s.selected_copy_ms,
            s.selected_bind_ms,
            (unsigned long long)s.split_layers,
            split_resident_experts_avg,
            split_missing_experts_avg,
            split_resident_avg,
            split_missing_avg,
            s.split_resident_ms,
            s.split_missing_ms,
            split_missing_load_avg,
            split_missing_slot_avg,
            split_missing_prune_avg,
            split_missing_addr_avg,
            split_missing_wait_avg,
            s.split_missing_wait_ms,
            (unsigned long long)s.load_calls,
            load_prepare_avg,
            load_pread_avg,
            load_modify_avg,
            load_install_avg,
            (unsigned long long)s.prepare_batch_reuse_calls,
            prepare_batch_reuse_avg,
            s.prepare_batch_reuse_ms,
            (unsigned long long)s.prepare_buffer_calls,
            prepare_buffer_avg,
            s.prepare_buffer_ms,
            (unsigned long long)s.prepare_task_experts,
            prepare_task_avg,
            s.prepare_task_ms,
            (unsigned long long)s.reuse_scan_calls,
            reuse_scan_entries_avg,
            reuse_scan_avg,
            s.reuse_scan_ms,
            s.reuse_clear_ms,
            (unsigned long long)s.readahead_calls,
            readahead_avg,
            s.readahead_ms,
            ds4_gpu_gib(s.readahead_bytes),
            (unsigned long long)s.cache_all_resident_layers,
            (unsigned long long)s.cache_all_missing_layers,
            (unsigned long long)s.cache_mixed_layers,
            cache_resident_experts_avg,
            cache_missing_experts_avg);
    if (s.overlap_route_calls != 0 || s.overlap_finish_calls != 0) {
        fprintf(stderr,
                "ds4:   streaming expert overlap %s route_calls=%llu "
                "route_wait_avg=%.3f ms route_copy_avg=%.3f ms "
                "route_plan_avg=%.3f ms route_wait_total=%.3f ms "
                "route_copy_total=%.3f ms route_plan_total=%.3f ms "
                "finish_calls=%llu finish_publish_avg=%.3f ms "
                "finish_wait_avg=%.3f ms finish_modify_avg=%.3f ms "
                "finish_install_avg=%.3f ms "
                "finish_publish_total=%.3f ms finish_wait_total=%.3f ms "
                "finish_modify_total=%.3f ms finish_install_total=%.3f ms\n",
                scope ? scope : "total",
                (unsigned long long)s.overlap_route_calls,
                overlap_route_wait_avg,
                overlap_route_copy_avg,
                overlap_route_plan_avg,
                s.overlap_route_wait_ms,
                s.overlap_route_copy_ms,
                s.overlap_route_plan_ms,
                (unsigned long long)s.overlap_finish_calls,
                overlap_finish_publish_avg,
                overlap_finish_wait_avg,
                overlap_finish_modify_avg,
                overlap_finish_install_avg,
                s.overlap_finish_publish_ms,
                s.overlap_finish_wait_ms,
                s.overlap_finish_modify_ms,
                s.overlap_finish_install_ms);
    }
}

static void ds4_gpu_print_task_memory_report(void) {
    task_vm_info_data_t info;
    mach_msg_type_number_t count = TASK_VM_INFO_COUNT;
    const kern_return_t kr = task_info(mach_task_self(),
                                       TASK_VM_INFO,
                                       (task_info_t)&info,
                                       &count);
    if (kr != KERN_SUCCESS) return;

    fprintf(stderr,
            "ds4:   macOS task memory footprint %.2f GiB, resident %.2f GiB, virtual %.2f GiB\n",
            ds4_gpu_gib((uint64_t)info.phys_footprint),
            ds4_gpu_gib((uint64_t)info.resident_size),
            ds4_gpu_gib((uint64_t)info.virtual_size));
}

void ds4_gpu_print_memory_report(const char *label) {
    const uint64_t scratch =
        (uint64_t)g_flash_attn_mask_bytes +
        (uint64_t)g_flash_attn_pad_bytes +
        (uint64_t)g_flash_attn_tmp_bytes +
        (uint64_t)g_flash_attn_blk_bytes +
        (uint64_t)g_flash_attn_ring_bytes +
        (uint64_t)g_flash_attn_kv_bytes +
        (uint64_t)g_qwen35_gqa_split_k_pad_bytes +
        (uint64_t)g_glm_flash_attn_mask_bytes +
        (uint64_t)g_compressor_pool_kv_bytes +
        (uint64_t)g_compressor_pool_score_bytes +
        (uint64_t)g_compressor_pool_score_cont_bytes +
        (uint64_t)g_compressor_pool_softmax_bytes +
        (uint64_t)g_compressor_pool_product_bytes +
        (uint64_t)g_compressor_store_ape_bytes +
        (uint64_t)g_compressor_store_score_bytes +
        (uint64_t)g_embed_rows_bytes +
        (uint64_t)g_router_selection_bytes +
        (uint64_t)g_router_weight_sum_bytes +
        (uint64_t)g_indexer_head_scores_bytes +
        (uint64_t)g_indexer_topk_bytes +
        (uint64_t)g_indexed_topk_bytes +
        (uint64_t)g_f16_round_scratch_bytes +
        (uint64_t)g_raw_store_round_bytes +
        (uint64_t)g_moe_gate_scratch_bytes +
        (uint64_t)g_moe_down_scratch_bytes +
        (uint64_t)g_moe_id_map_bytes +
        (uint64_t)g_moe_q4_gate_slots_bytes +
        (uint64_t)g_moe_q4_up_slots_bytes +
        (uint64_t)g_moe_q4_down_slots_bytes;

    pthread_mutex_lock(&g_tensor_mu);
    const uint64_t tensor_live_snap = g_tensor_alloc_live_bytes;
    const uint64_t tensor_peak_snap = g_tensor_alloc_peak_bytes;
    pthread_mutex_unlock(&g_tensor_mu);

    uint64_t streaming_live = g_stream_expert_cache_bytes;
    if (streaming_live > UINT64_MAX - g_dspark_support_cache_bytes) {
        streaming_live = UINT64_MAX;
    } else {
        streaming_live += g_dspark_support_cache_bytes;
    }
    uint64_t tracked_live = tensor_live_snap;
    if (tracked_live > UINT64_MAX - streaming_live) {
        tracked_live = UINT64_MAX;
    } else {
        tracked_live += streaming_live;
    }

    const bool color = ds4_log_is_tty(stderr);
    const char *green = color ? "\x1b[32m" : "";
    const char *bright_green = color ? "\x1b[1;32m" : "";
    const char *reset = color ? "\x1b[0m" : "";
    fprintf(stderr,
            "%sds4: Metal memory%s%s: runtime %.2f GiB + streaming experts %.2f GiB = %s%.2f GiB tracked live%s\n",
            green,
            label && label[0] ? " " : "",
            label && label[0] ? label : "",
            ds4_gpu_gib(tensor_live_snap),
            ds4_gpu_gib(streaming_live),
            bright_green,
            ds4_gpu_gib(tracked_live),
            reset);
    if (color) fputs(green, stderr);
    fprintf(stderr,
            "ds4:   runtime tensors live %.2f MiB peak %.2f MiB\n",
            ds4_gpu_mib(tensor_live_snap),
            ds4_gpu_mib(tensor_peak_snap));
    ds4_gpu_print_task_memory_report();
    fprintf(stderr,
            "ds4:   mmap model wrapper spans %llu buffers %.2f GiB total, %.2f GiB max (not copied)\n",
            (unsigned long long)g_model_wrap_count,
            ds4_gpu_gib(g_model_wrap_bytes),
            ds4_gpu_gib(g_model_wrap_max_bytes));
    if (g_model_buffer_cache && [g_model_buffer_cache count] != 0) {
        const uint64_t limit = ds4_gpu_exact_view_cache_limit_bytes();
        if (limit == 0) {
            fprintf(stderr,
                    "ds4:   exact model view cache %lu buffers %.2f GiB unlimited, %llu evictions (not copied)\n",
                    (unsigned long)[g_model_buffer_cache count],
                    ds4_gpu_gib(g_model_buffer_cache_bytes),
                    (unsigned long long)g_model_buffer_cache_evictions);
        } else {
            fprintf(stderr,
                    "ds4:   exact model view cache %lu buffers %.2f GiB / %.2f GiB, %llu evictions (not copied)\n",
                    (unsigned long)[g_model_buffer_cache count],
                    ds4_gpu_gib(g_model_buffer_cache_bytes),
                    ds4_gpu_gib(limit),
                    (unsigned long long)g_model_buffer_cache_evictions);
        }
    }
    if (g_stream_expert_cache_hits != 0 ||
        g_stream_expert_cache_misses != 0 ||
        g_stream_expert_cache_bytes != 0) {
        const uint64_t budget = ds4_gpu_stream_expert_cache_configured_budget();
        uint64_t target_bytes = 0;
        if (budget != 0 && g_stream_expert_cache_expert_bytes != 0) {
            target_bytes =
                budget > UINT64_MAX / g_stream_expert_cache_expert_bytes ?
                    UINT64_MAX :
                    budget * g_stream_expert_cache_expert_bytes;
        }
        const uint64_t lookups = g_stream_expert_cache_hits + g_stream_expert_cache_misses;
        const double hit_rate = lookups ?
            (double)g_stream_expert_cache_hits / (double)lookups : 0.0;
        if (g_stream_expert_cache_willneed_advise_bytes != 0 ||
            g_stream_expert_cache_pread_bytes != 0) {
            fprintf(stderr,
                    "ds4:   streaming expert cache budget=%llu experts entries=%u expert=%.2f MiB target=%.2f GiB live=%.2f GiB, hits=%llu misses=%llu hit_rate=%.3f wraps=%llu evictions=%llu buffer_allocs=%llu buffer_reuses=%llu expert_loads=%llu pread_syscalls=%llu miss_willneed=%.2f GiB miss_pread=%.2f GiB pread_ms=%.3f\n",
                    (unsigned long long)budget,
                    g_stream_expert_cache_entry_count,
                    ds4_gpu_mib(g_stream_expert_cache_expert_bytes),
                    ds4_gpu_gib(target_bytes),
                    ds4_gpu_gib(g_stream_expert_cache_bytes),
                    (unsigned long long)g_stream_expert_cache_hits,
                    (unsigned long long)g_stream_expert_cache_misses,
                    hit_rate,
                    (unsigned long long)g_stream_expert_cache_wraps,
                    (unsigned long long)g_stream_expert_cache_evictions,
                    (unsigned long long)g_stream_expert_cache_buffer_allocs,
                    (unsigned long long)g_stream_expert_cache_buffer_reuses,
                    (unsigned long long)g_stream_expert_cache_expert_loads,
                    (unsigned long long)g_stream_expert_cache_pread_syscalls,
                    ds4_gpu_gib(g_stream_expert_cache_willneed_advise_bytes),
                    ds4_gpu_gib(g_stream_expert_cache_pread_bytes),
                    g_stream_expert_cache_pread_ms);
        } else {
            fprintf(stderr,
                    "ds4:   streaming expert cache budget=%llu experts entries=%u expert=%.2f MiB target=%.2f GiB live=%.2f GiB, hits=%llu misses=%llu hit_rate=%.3f wraps=%llu evictions=%llu buffer_allocs=%llu buffer_reuses=%llu expert_loads=%llu pread_syscalls=%llu\n",
                    (unsigned long long)budget,
                    g_stream_expert_cache_entry_count,
                    ds4_gpu_mib(g_stream_expert_cache_expert_bytes),
                    ds4_gpu_gib(target_bytes),
                    ds4_gpu_gib(g_stream_expert_cache_bytes),
                    (unsigned long long)g_stream_expert_cache_hits,
                    (unsigned long long)g_stream_expert_cache_misses,
                    hit_rate,
                    (unsigned long long)g_stream_expert_cache_wraps,
                    (unsigned long long)g_stream_expert_cache_evictions,
                    (unsigned long long)g_stream_expert_cache_buffer_allocs,
                    (unsigned long long)g_stream_expert_cache_buffer_reuses,
                    (unsigned long long)g_stream_expert_cache_expert_loads,
                    (unsigned long long)g_stream_expert_cache_pread_syscalls);
        }
        if (g_glm_prefetch_hint_experts != 0 ||
            g_glm_prefetch_pred_compared != 0) {
            const double pred_acc = g_glm_prefetch_pred_compared ?
                (double)g_glm_prefetch_pred_matched /
                (double)g_glm_prefetch_pred_compared : 0.0;
            fprintf(stderr,
                    "ds4:   router-ahead prefetch hinted=%llu skip_cached=%llu predicted_match=%llu/%llu acc=%.3f hint_ms=%.3f\n",
                    (unsigned long long)g_glm_prefetch_hint_experts,
                    (unsigned long long)g_glm_prefetch_skip_cached,
                    (unsigned long long)g_glm_prefetch_pred_matched,
                    (unsigned long long)g_glm_prefetch_pred_compared,
                    pred_acc,
                    g_glm_prefetch_hint_ms);
        }
        if (ds4_gpu_stream_expert_timing_summary_enabled()) {
            const ds4_gpu_stream_expert_timing_snapshot total =
                ds4_gpu_stream_expert_timing_current();
            if (ds4_gpu_stream_expert_timing_has_data(total)) {
                const ds4_gpu_stream_expert_timing_snapshot delta =
                    ds4_gpu_stream_expert_timing_delta(
                            total,
                            g_stream_expert_timing_last_report);
                ds4_gpu_stream_expert_timing_print("total", total);
                ds4_gpu_stream_expert_timing_print("delta", delta);
                g_stream_expert_timing_last_report = total;
            }
        }
        if (getenv("DS4_METAL_STREAMING_EXPERT_LAYER_STATS") != NULL) {
            fprintf(stderr, "ds4:   streaming expert cache per-layer stats:\n");
            for (uint32_t layer = 0;
                 layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
                 layer++) {
                const uint64_t hits = g_stream_expert_cache_layer_hits[layer];
                const uint64_t misses = g_stream_expert_cache_layer_misses[layer];
                const uint64_t lookups = hits + misses;
                const uint64_t evictions =
                    g_stream_expert_cache_layer_evictions[layer];
                const uint64_t pread_bytes =
                    g_stream_expert_cache_layer_pread_bytes[layer];
                const double pread_ms =
                    g_stream_expert_cache_layer_pread_ms[layer];
                const uint32_t cached =
                    g_stream_expert_cache_layer_count[layer];
                const uint32_t layer_slots =
                    ds4_gpu_stream_expert_cache_configured_count() != 0 ?
                        DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT : 0;
                if (lookups == 0 && evictions == 0 && pread_bytes == 0 &&
                    cached == 0) {
                    continue;
                }
                const double layer_hit_rate = lookups ?
                    (double)hits / (double)lookups : 0.0;
                fprintf(stderr,
                        "ds4:     layer=%u layer_slots=%u cached=%u hits=%llu misses=%llu hit_rate=%.3f evictions=%llu miss_pread=%.2f GiB pread_ms=%.3f\n",
                        layer,
                        layer_slots,
                        cached,
                        (unsigned long long)hits,
                        (unsigned long long)misses,
                        layer_hit_rate,
                        (unsigned long long)evictions,
                        ds4_gpu_gib(pread_bytes),
                        pread_ms);
            }
            if (getenv("DS4_METAL_STREAMING_EXPERT_LAYER_STATS_DELTA") != NULL) {
                fprintf(stderr, "ds4:   streaming expert cache per-layer delta:\n");
                for (uint32_t layer = 0;
                     layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
                     layer++) {
                    const uint64_t hits =
                        g_stream_expert_cache_layer_hits[layer];
                    const uint64_t misses =
                        g_stream_expert_cache_layer_misses[layer];
                    const uint64_t evictions =
                        g_stream_expert_cache_layer_evictions[layer];
                    const uint64_t pread_bytes =
                        g_stream_expert_cache_layer_pread_bytes[layer];
                    const double pread_ms =
                        g_stream_expert_cache_layer_pread_ms[layer];
                    const uint64_t delta_hits =
                        hits - g_stream_expert_cache_layer_last_hits[layer];
                    const uint64_t delta_misses =
                        misses - g_stream_expert_cache_layer_last_misses[layer];
                    const uint64_t delta_evictions =
                        evictions -
                        g_stream_expert_cache_layer_last_evictions[layer];
                    const uint64_t delta_pread_bytes =
                        pread_bytes -
                        g_stream_expert_cache_layer_last_pread_bytes[layer];
                    const double delta_pread_ms =
                        pread_ms -
                        g_stream_expert_cache_layer_last_pread_ms[layer];
                    const uint64_t lookups = delta_hits + delta_misses;
                    if (lookups == 0 && delta_evictions == 0 &&
                        delta_pread_bytes == 0) {
                        continue;
                    }
                    const double hit_rate = lookups ?
                        (double)delta_hits / (double)lookups : 0.0;
                    fprintf(stderr,
                            "ds4:     layer=%u cached=%u hits=%llu misses=%llu hit_rate=%.3f evictions=%llu miss_pread=%.2f GiB pread_ms=%.3f\n",
                            layer,
                            g_stream_expert_cache_layer_count[layer],
                            (unsigned long long)delta_hits,
                            (unsigned long long)delta_misses,
                            hit_rate,
                            (unsigned long long)delta_evictions,
                            ds4_gpu_gib(delta_pread_bytes),
                            delta_pread_ms);
                    g_stream_expert_cache_layer_last_hits[layer] = hits;
                    g_stream_expert_cache_layer_last_misses[layer] = misses;
                    g_stream_expert_cache_layer_last_evictions[layer] =
                        evictions;
                    g_stream_expert_cache_layer_last_pread_bytes[layer] =
                        pread_bytes;
                    g_stream_expert_cache_layer_last_pread_ms[layer] =
                        pread_ms;
                }
            }
        }
    }
    if (g_dspark_support_cache_hits != 0 ||
        g_dspark_support_cache_misses != 0 ||
        g_dspark_support_cache_bytes != 0 ||
        g_dspark_support_cache_lease_acquires != 0 ||
        g_dspark_support_cache_lease_failures != 0) {
        const uint64_t lookups = g_dspark_support_cache_hits +
                                 g_dspark_support_cache_misses;
        const double hit_rate = lookups != 0 ?
            (double)g_dspark_support_cache_hits / (double)lookups : 0.0;
        fprintf(stderr,
                "ds4:   DSpark SUPPORT expert cache parent_budget=%u "
                "target_budget=%u support_budget=%u entries=%u "
                "live=%.2f GiB hits=%llu misses=%llu hit_rate=%.3f "
                "evictions=%llu expert_loads=%llu pread_syscalls=%llu "
                "pread=%.2f GiB pread_ms=%.3f leases=%llu/%llu "
                "lease_failures=%llu rollbacks=%llu peak_pinned=%u "
                "release_fences=already_completed:%llu,sync:%llu "
                "fence_ms=%.3f\n",
                ds4_gpu_stream_expert_cache_parent_budget(0),
                ds4_gpu_stream_expert_cache_configured_budget(),
                ds4_gpu_dspark_support_cache_configured_budget(),
                g_dspark_support_cache_entry_count,
                ds4_gpu_gib(g_dspark_support_cache_bytes),
                (unsigned long long)g_dspark_support_cache_hits,
                (unsigned long long)g_dspark_support_cache_misses,
                hit_rate,
                (unsigned long long)g_dspark_support_cache_evictions,
                (unsigned long long)g_dspark_support_cache_expert_loads,
                (unsigned long long)g_dspark_support_cache_pread_syscalls,
                ds4_gpu_gib(g_dspark_support_cache_pread_bytes),
                g_dspark_support_cache_pread_ms,
                (unsigned long long)g_dspark_support_cache_lease_acquires,
                (unsigned long long)g_dspark_support_cache_lease_releases,
                (unsigned long long)g_dspark_support_cache_lease_failures,
                (unsigned long long)g_dspark_support_cache_batch_rollbacks,
                g_dspark_support_cache_peak_pinned,
                (unsigned long long)
                    g_dspark_support_cache_release_already_completed_fences,
                (unsigned long long)
                    g_dspark_support_cache_release_sync_fences,
                g_dspark_support_cache_release_fence_ms);
    }
    fprintf(stderr,
            "ds4:   model residency requests %llu%s\n",
            (unsigned long long)g_model_residency_count,
            g_ssd_streaming_mode ? " (ssd-streaming)" :
            (getenv("DS4_METAL_NO_RESIDENCY") != NULL ? " (disabled)" : ""));
    if (g_qwen35_resident_gpu_route_calls != 0 ||
        g_qwen35_resident_host_readbacks != 0) {
        fprintf(stderr,
                "ds4:   Qwen resident routing GPU-only=%llu host-readbacks=%llu\n",
                (unsigned long long)g_qwen35_resident_gpu_route_calls,
                (unsigned long long)g_qwen35_resident_host_readbacks);
    }
    if (g_qwen35_gdn128_parallel_calls != 0) {
        fprintf(stderr,
                "ds4:   Qwen GDN-128 parallel calls=%llu\n",
                (unsigned long long)g_qwen35_gdn128_parallel_calls);
    }
    fprintf(stderr,
            "ds4:   device %s, Metal 4 runtime %s, family %s, MTL4 queue %s, tensor API %s, M5 neural accelerators %s\n",
            g_metal_device_name[0] ? g_metal_device_name : "(unknown)",
            g_metal4_runtime_available ? "yes" : "no",
            g_metal4_family_supported ? "yes" : "no",
            g_metal4_queue_supported ? "yes" : "no",
            g_metal4_tensor_api_enabled ? "enabled" :
                (g_metal4_tensor_api_compile_supported ? "available" : "disabled"),
            g_metal4_m5_neural_accelerators_hint ? "likely" : "not detected");
    fprintf(stderr,
            "ds4:   accelerated Metal path %s%s\n",
            ds4_gpu_mpp_available() ? "enabled" : "disabled",
            g_quality_mode ? " by --quality" :
                (!g_metal4_tensor_api_enabled ? " (tensor API unavailable)" : ""));
    fprintf(stderr,
            "ds4:   scratch %.2f MiB (flash mask %.2f, pad %.2f, tmp %.2f, blk %.2f, ring %.2f, kv %.2f, compressor %.2f, router %.2f, indexer %.2f, moe %.2f, f16 %.2f, raw-store %.2f)\n",
            ds4_gpu_mib(scratch),
            ds4_gpu_mib((uint64_t)g_flash_attn_mask_bytes +
                          (uint64_t)g_glm_flash_attn_mask_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_pad_bytes +
                          (uint64_t)g_qwen35_gqa_split_k_pad_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_tmp_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_blk_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_ring_bytes),
            ds4_gpu_mib((uint64_t)g_flash_attn_kv_bytes),
            ds4_gpu_mib((uint64_t)g_compressor_pool_kv_bytes +
                          (uint64_t)g_compressor_pool_score_bytes +
                          (uint64_t)g_compressor_pool_score_cont_bytes +
                          (uint64_t)g_compressor_pool_softmax_bytes +
                          (uint64_t)g_compressor_pool_product_bytes +
                          (uint64_t)g_compressor_store_ape_bytes +
                          (uint64_t)g_compressor_store_score_bytes +
                          (uint64_t)g_embed_rows_bytes),
            ds4_gpu_mib((uint64_t)g_router_selection_bytes +
                          (uint64_t)g_router_weight_sum_bytes),
            ds4_gpu_mib((uint64_t)g_indexer_head_scores_bytes +
                          (uint64_t)g_indexer_topk_bytes +
                          (uint64_t)g_indexed_topk_bytes),
            ds4_gpu_mib((uint64_t)g_moe_gate_scratch_bytes +
                          (uint64_t)g_moe_down_scratch_bytes +
                          (uint64_t)g_moe_id_map_bytes +
                          (uint64_t)g_moe_q4_gate_slots_bytes +
                          (uint64_t)g_moe_q4_up_slots_bytes +
                          (uint64_t)g_moe_q4_down_slots_bytes),
            ds4_gpu_mib((uint64_t)g_f16_round_scratch_bytes),
            ds4_gpu_mib((uint64_t)g_raw_store_round_bytes));
    if (color) fputs(reset, stderr);
}

void ds4_gpu_set_quality(bool quality) {
    g_quality_mode = quality ? 1 : 0;
}

void ds4_gpu_internal_force_qwen35_exact_router_for_test(bool enabled) {
    g_test_force_qwen35_exact_router = enabled ? 1 : 0;
}

void ds4_gpu_set_glm_model(bool enabled) {
    if (ds4_gpu_dspark_support_lease_active()) {
        fprintf(stderr,
                "ds4: cannot change Metal model mode while a DSpark SUPPORT lease is active\n");
        return;
    }
    const int previous_mode = g_glm_model_mode;
    const int combined_before =
        ds4_gpu_dspark_support_cache_combined_available();
    g_glm_model_mode = enabled ? 1 : 0;
    const int combined_after =
        ds4_gpu_dspark_support_cache_combined_available();
    const int transition_ok = combined_before == combined_after ||
        (combined_after ?
            ds4_gpu_dspark_support_cache_activate_combined() :
            ds4_gpu_dspark_support_cache_reconcile_transition(1));
    if (!transition_ok) {
        /* Preserve the last fully reconciled state. A void model-mode setter
         * cannot publish a half-transition whose cache still belongs to the
         * previous identity/budget. Normal target-only calls never enter this
         * path because availability remains false on both sides. */
        g_glm_model_mode = previous_mode;
        fprintf(stderr,
                "ds4: Metal model-mode transition could not reconcile "
                "the combined TARGET/SUPPORT cache\n");
    }
}

void ds4_gpu_set_ssd_streaming(bool enabled) {
    if (g_stream_expert_cache_lease.active) {
        fprintf(stderr,
                "ds4: cannot change Metal SSD streaming mode while a layer lease is active\n");
        return;
    }
    g_ssd_streaming_mode = enabled ? 1 : 0;
    g_stream_expert_cache_required_floor = 0;
    g_stream_expert_cache_growth_guard_enabled = 0;
    g_stream_expert_cache_growth_guard_runtime_bytes = 0;
    g_stream_expert_cache_growth_guard_static_page_bytes = 0;
    g_stream_expert_cache_growth_budget_cap = 0;
    g_stream_expert_cache_growth_budget_cap_active = 0;
    g_stream_expert_cache_growth_guard_warned = 0;
#ifdef DS4_TEST_HOOKS
    g_stream_expert_cache_test_growth_guard_fail_after = -1;
#endif
    if (!g_ssd_streaming_mode) {
        g_stream_expert_cache_slab_target_bytes_override = 0;
    }
    ds4_gpu_stream_expert_cache_clear_all(1);
    ds4_gpu_dspark_support_cache_clear(1);
    if (g_ssd_streaming_mode) {
        fprintf(stderr,
                "ds4: Metal SSD streaming mode enabled; full model residency and warmup are skipped\n");
    }
}

void ds4_gpu_set_streaming_expert_readahead(bool enabled) {
    g_streaming_expert_readahead_mode = enabled ? 1 : 0;
}

void ds4_gpu_set_glm_streaming_prefill_full_layer(bool enabled) {
    g_glm_streaming_prefill_full_layer_runtime = enabled ? 1 : 0;
}

void ds4_gpu_set_streaming_expert_cache_budget(uint32_t experts) {
    if (g_stream_expert_cache_lease.active) {
        fprintf(stderr,
                "ds4: cannot reset Metal streaming expert cache while a layer lease is active\n");
        return;
    }
    if (experts > DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        experts = DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES;
    }
    g_stream_expert_cache_budget_override = experts;
    ds4_gpu_stream_expert_cache_clear_all(1);
    ds4_gpu_dspark_support_cache_clear(1);
}

int ds4_gpu_grow_streaming_expert_cache_budget(uint32_t experts) {
    if (!g_ssd_streaming_mode ||
        ds4_gpu_dspark_support_lease_active()) return 0;
    if (experts > DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        experts = DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES;
    }
    const uint32_t current = g_stream_expert_cache_budget_override;
    const uint32_t support =
        ds4_gpu_dspark_support_cache_budget_for_parent(experts);
    const uint32_t target =
        ds4_gpu_stream_expert_cache_apply_target_caps(
            experts >= support ? experts - support : 0, 0);
    const uint32_t effective_parent =
        target > UINT32_MAX - support ? UINT32_MAX : target + support;
    if (target < g_stream_expert_cache_required_floor ||
        experts < current || target < g_stream_expert_cache_entry_count ||
        g_stream_expert_cache_entry_count > UINT32_MAX -
            g_dspark_support_cache_entry_count ||
        effective_parent < g_stream_expert_cache_entry_count +
                               g_dspark_support_cache_entry_count) {
        return 0;
    }
    g_stream_expert_cache_budget_override = experts;
    return 1;
}

void ds4_gpu_set_streaming_expert_cache_required_floor(uint32_t experts) {
    if (ds4_gpu_dspark_support_lease_active()) {
        fprintf(stderr,
                "ds4: cannot change Metal streaming expert floor while a DSpark SUPPORT lease is active\n");
        return;
    }
    /* Budget changes preserve this model contract; SSD-mode reset/cleanup
     * clears it before another model can reuse the process-global backend. */
    g_stream_expert_cache_required_floor = experts;
    ds4_gpu_dspark_support_cache_target_cap_changed();
}

void ds4_gpu_set_streaming_expert_cache_expert_bytes(uint64_t bytes) {
    if (ds4_gpu_dspark_support_lease_active()) {
        fprintf(stderr,
                "ds4: cannot change Metal streaming expert size while a DSpark SUPPORT lease is active\n");
        return;
    }
    /*
     * Pre-seed the cache's physical slot size with the model's largest routed
     * record. Logical component sizes remain per-layer, so smaller records use
     * the same slabs without reading padding or changing their address layout.
     */
    g_stream_expert_cache_expert_bytes = bytes;
}

void ds4_gpu_set_streaming_expert_cache_slab_target_bytes(uint64_t bytes) {
    if (g_stream_expert_cache_lease.active) {
        fprintf(stderr,
                "ds4: cannot reset Metal streaming expert slabs while a layer lease is active\n");
        return;
    }
    g_stream_expert_cache_slab_target_bytes_override = bytes;
    /* A target change cannot share existing slabs without making growth
     * dependent on call order. Apply it as a model-lifetime configuration. */
    ds4_gpu_stream_expert_cache_clear_all(1);
}

void ds4_gpu_set_streaming_expert_cache_growth_guard(
        bool     enabled,
        uint64_t runtime_bytes,
        uint64_t static_page_bytes) {
    if (g_stream_expert_cache_lease.active) {
        fprintf(stderr,
                "ds4: cannot change Metal streaming expert growth guard "
                "while a layer lease is active\n");
        return;
    }
    g_stream_expert_cache_growth_guard_enabled =
        enabled && runtime_bytes != 0 && static_page_bytes != 0 ? 1 : 0;
    g_stream_expert_cache_growth_guard_runtime_bytes =
        g_stream_expert_cache_growth_guard_enabled ? runtime_bytes : 0;
    g_stream_expert_cache_growth_guard_static_page_bytes =
        g_stream_expert_cache_growth_guard_enabled ? static_page_bytes : 0;
    g_stream_expert_cache_growth_budget_cap = 0;
    g_stream_expert_cache_growth_budget_cap_active = 0;
    g_stream_expert_cache_growth_guard_warned = 0;
#ifdef DS4_TEST_HOOKS
    g_stream_expert_cache_test_growth_guard_fail_after = -1;
#endif
}

uint64_t ds4_gpu_recommended_working_set_size(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!g_device) return 0;
    return (uint64_t)[g_device recommendedMaxWorkingSetSize];
}

static int ds4_gpu_page_count_bytes(uint64_t pages,
                                    uint64_t page_bytes,
                                    uint64_t *bytes_out) {
    if (!bytes_out || page_bytes == 0 || pages > UINT64_MAX / page_bytes) {
        return 0;
    }
    *bytes_out = pages * page_bytes;
    return 1;
}

int ds4_gpu_host_memory_snapshot(ds4_ssd_host_memory *out) {
    if (!out) return 0;
    memset(out, 0, sizeof(*out));
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!g_device) return 0;

    const uint64_t physical_bytes = ds4_gpu_system_memory_bytes();
    const uint64_t recommended_bytes =
        (uint64_t)[g_device recommendedMaxWorkingSetSize];
    if (physical_bytes == 0 || recommended_bytes == 0) return 0;

    mach_port_t host = mach_host_self();
    vm_size_t page_size = 0;
    vm_statistics64_data_t vm = {0};
    mach_msg_type_number_t vm_count = HOST_VM_INFO64_COUNT;
    const kern_return_t page_kr = host_page_size(host, &page_size);
    const kern_return_t vm_kr = host_statistics64(
        host,
        HOST_VM_INFO64,
        (host_info64_t)&vm,
        &vm_count);
    (void)mach_port_deallocate(mach_task_self(), host);
    if (page_kr != KERN_SUCCESS ||
        vm_kr != KERN_SUCCESS ||
        page_size == 0 ||
        vm_count < HOST_VM_INFO64_COUNT) {
        return 0;
    }

    task_vm_info_data_t task_vm = {0};
    mach_msg_type_number_t task_count = TASK_VM_INFO_COUNT;
    if (task_info(mach_task_self(),
                  TASK_VM_INFO,
                  (task_info_t)&task_vm,
                  &task_count) != KERN_SUCCESS ||
        task_count < TASK_VM_INFO_REV1_COUNT) {
        return 0;
    }

    /* Mach already includes speculative pages in free_count.  Adding
     * speculative_count again can materially overstate reclaimable RAM after
     * streaming I/O and select a cache one full working-set tier too large. */
    const uint64_t free_pages = (uint64_t)vm.free_count;

    ds4_ssd_host_memory snapshot = {
        .physical_bytes = physical_bytes,
        .recommended_bytes = recommended_bytes,
        .task_footprint_bytes = (uint64_t)task_vm.phys_footprint,
    };
    int pressure_level = 0;
    size_t pressure_level_bytes = sizeof(pressure_level);
    if (sysctlbyname("kern.memorystatus_vm_pressure_level",
                     &pressure_level,
                     &pressure_level_bytes,
                     NULL,
                     0) == 0 &&
        pressure_level_bytes == sizeof(pressure_level)) {
        snapshot.pressure_status_available = true;
        snapshot.pressure_normal =
            pressure_level == DISPATCH_MEMORYPRESSURE_NORMAL;
    }
    const uint64_t page_bytes = (uint64_t)page_size;
    if (!ds4_gpu_page_count_bytes(free_pages,
                                  page_bytes,
                                  &snapshot.free_bytes) ||
        !ds4_gpu_page_count_bytes((uint64_t)vm.purgeable_count,
                                  page_bytes,
                                  &snapshot.purgeable_bytes) ||
        !ds4_gpu_page_count_bytes((uint64_t)vm.inactive_count,
                                  page_bytes,
                                  &snapshot.inactive_bytes) ||
        !ds4_gpu_page_count_bytes((uint64_t)vm.external_page_count,
                                  page_bytes,
                                  &snapshot.file_backed_bytes)) {
        return 0;
    }

    *out = snapshot;
    return 1;
}

static int ds4_gpu_model_map_log_enabled(void) {
    if (!g_ssd_streaming_mode) return 1;
    const char *trace = getenv("DS4_METAL_STREAMING_MAP_TRACE");
    return trace && trace[0] && strcmp(trace, "0") != 0;
}

