        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> tokbuf = ds4_gpu_tensor_buffer(tokens);
        const uint64_t out_bytes = (uint64_t)n_tokens * n_embd * sizeof(float);
        const uint64_t token_bytes = (uint64_t)n_tokens * sizeof(int32_t);
        if (!outbuf || !tokbuf ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(tokens) < token_bytes) {
            fprintf(stderr, "ds4: Metal Q8_0 batched embedding received undersized buffers\n");
            return 0;
        }

        uint64_t weight_bytes = 0;
        if (!ds4_gpu_q8_0_table_bytes(n_vocab, n_embd, &weight_bytes) ||
            weight_offset > model_size ||
            weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal Q8_0 batched embedding range is outside the mapped model\n");
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf =
            ds4_gpu_wrap_model_range(model_map,
                                     model_size,
                                     weight_offset,
                                     weight_bytes,
                                     &inner_offset);
        if (!wbuf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (!ds4_gpu_encode_get_rows_q8_0(cb,
                                           wbuf,
                                           (NSUInteger)inner_offset,
                                           tokbuf,
                                           ds4_gpu_tensor_offset(tokens),
                                           NULL,
                                           outbuf,
                                           ds4_gpu_tensor_offset(out),
                                           n_vocab,
                                           n_tokens,
                                           n_embd)) {
            return 0;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "q8_0 embed tokens")) return 0;
    }

    return 1;
}

int ds4_gpu_embed_token_hc_tensor(
        ds4_gpu_tensor *out_hc,
        const void       *model_map,
        uint64_t          model_size,
        uint64_t          weight_offset,
        uint32_t          n_vocab,
        uint32_t          token,
        uint32_t          n_embd,
        uint32_t          n_hc) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out_hc || !model_map || n_vocab == 0 || token >= n_vocab || n_embd == 0 || n_hc == 0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out_hc);
        const uint64_t out_bytes = (uint64_t)n_embd * n_hc * sizeof(float);
        if (!outbuf || ds4_gpu_tensor_bytes(out_hc) < out_bytes) {
            fprintf(stderr, "ds4: Metal graph embedding received undersized HC output buffer\n");
            return 0;
        }

        const uint64_t weight_bytes = (uint64_t)n_vocab * n_embd * sizeof(uint16_t);
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal graph embedding range is outside the mapped model\n");
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf =
            ds4_gpu_wrap_model_range(model_map,
                                     model_size,
                                     weight_offset,
                                     weight_bytes,
                                     &inner_offset);
        if (!wbuf) return 0;

        const NSUInteger row_bytes = (NSUInteger)n_embd * sizeof(float);
        if (!ds4_gpu_ensure_scratch_buffer(&g_embed_rows_buffer,
                                             &g_embed_rows_bytes,
                                             row_bytes,
                                             "ds4_embed_rows")) {
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const int32_t token_i32 = (int32_t)token;
        const uint64_t src_row_bytes = (uint64_t)n_embd * sizeof(uint16_t);
        const uint64_t dst_row_bytes = (uint64_t)n_embd * sizeof(float);
        ds4_gpu_get_rows_args args = {
            .ne00t = (int32_t)n_embd,
            .ne00 = (int32_t)n_embd,
            .nb01 = src_row_bytes,
            .nb02 = (uint64_t)n_vocab * src_row_bytes,
            .nb03 = (uint64_t)n_vocab * src_row_bytes,
            .ne10 = 1,
            .nb10 = sizeof(int32_t),
            .nb11 = sizeof(int32_t),
            .nb12 = sizeof(int32_t),
            .nb1 = dst_row_bytes,
            .nb2 = dst_row_bytes,
            .nb3 = dst_row_bytes,
        };
        NSUInteger nth = (NSUInteger)n_embd;
        const NSUInteger max_threads = g_get_rows_f16_pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > max_threads) nth = max_threads;
        if (nth == 0) nth = 1;
        const NSUInteger nw0 = ((NSUInteger)n_embd + nth - 1u) / nth;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_get_rows_f16_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
        [enc setBytes:&token_i32 length:sizeof(token_i32) atIndex:2];
        [enc setBuffer:g_embed_rows_buffer offset:0 atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake(nw0, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_encode_repeat_hc_embedding(cb,
                                                  g_embed_rows_buffer,
                                                  0,
                                                  outbuf,
                                                  ds4_gpu_tensor_offset(out_hc),
                                                  1,
                                                  n_embd,
                                                  n_hc)) {
            return 0;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "graph embed token")) return 0;
    }

    return 1;
}

int ds4_gpu_embed_tokens_hc_tensor(
        ds4_gpu_tensor       *out_hc,
        const ds4_gpu_tensor *tokens,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint32_t                n_vocab,
        uint32_t                n_tokens,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out_hc || !tokens || !model_map || n_vocab == 0 || n_tokens == 0 || n_embd == 0 || n_hc == 0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out_hc);
        id<MTLBuffer> tokbuf = ds4_gpu_tensor_buffer(tokens);
        const uint64_t out_bytes = (uint64_t)n_tokens * n_embd * n_hc * sizeof(float);
        const uint64_t token_bytes = (uint64_t)n_tokens * sizeof(int32_t);
        if (!outbuf || !tokbuf ||
            ds4_gpu_tensor_bytes(out_hc) < out_bytes ||
            ds4_gpu_tensor_bytes(tokens) < token_bytes) {
            fprintf(stderr, "ds4: Metal graph batched embedding received undersized buffers\n");
            return 0;
        }

        const uint64_t weight_bytes = (uint64_t)n_vocab * n_embd * sizeof(uint16_t);
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal graph batched embedding range is outside the mapped model\n");
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf =
            ds4_gpu_wrap_model_range(model_map,
                                     model_size,
                                     weight_offset,
                                     weight_bytes,
                                     &inner_offset);
        if (!wbuf) return 0;

        const NSUInteger rows_bytes = (NSUInteger)n_tokens * n_embd * sizeof(float);
        if (!ds4_gpu_ensure_scratch_buffer(&g_embed_rows_buffer,
                                             &g_embed_rows_bytes,
                                             rows_bytes,
                                             "ds4_embed_rows")) {
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (!ds4_gpu_encode_get_rows_f16(cb,
                                           wbuf,
                                           (NSUInteger)inner_offset,
                                           tokbuf,
                                           ds4_gpu_tensor_offset(tokens),
                                           g_embed_rows_buffer,
                                           0,
                                           n_vocab,
                                           n_tokens,
                                           n_embd) ||
            !ds4_gpu_encode_repeat_hc_embedding(cb,
                                                  g_embed_rows_buffer,
                                                  0,
                                                  outbuf,
                                                  ds4_gpu_tensor_offset(out_hc),
                                                  n_tokens,
                                                  n_embd,
                                                  n_hc)) {
            return 0;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "graph embed tokens")) return 0;
    }

    return 1;
}

int ds4_gpu_set_model_map_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size, uint64_t max_tensor_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!model_map || model_size == 0) return 0;
    if (map_offset > model_size || map_size == 0 || map_size > model_size - map_offset) return 0;
    max_tensor_bytes = ds4_gpu_effective_model_max_tensor_bytes(map_size, max_tensor_bytes);

    @autoreleasepool {
        if (g_model_map_ptr == model_map &&
            g_model_map_size == model_size &&
            g_model_mapped_offset == map_offset &&
            g_model_mapped_size == map_size &&
            g_model_mapped_max_tensor_bytes == max_tensor_bytes) {
            return 1;
        }

        for (uint32_t i = 0; i < g_model_view_count; i++) {
            if (g_model_views[i].model_map == model_map &&
                g_model_views[i].model_size == model_size &&
                map_offset >= g_model_views[i].model_offset &&
                map_offset + map_size <= g_model_views[i].model_offset + g_model_views[i].bytes) {
                return 1;
            }
        }

        ds4_gpu_model_residency_clear();
        if (!ds4_gpu_map_model_views(model_map, model_size, map_offset, map_size, max_tensor_bytes)) {
            ds4_gpu_model_residency_clear();
            return 0;
        }
        g_model_map_ptr = model_map;
        g_model_map_size = model_size;
        g_model_mapped_offset = map_offset;
        g_model_mapped_size = map_size;
        g_model_mapped_max_tensor_bytes = max_tensor_bytes;
        if (ds4_gpu_model_map_log_enabled()) {
            fprintf(stderr,
                    "ds4: Metal mapped mmaped model as %u overlapping shared buffers\n",
                    g_model_view_count);
        }
        return 1;
    }
}

static int ds4_gpu_model_views_cover_spans(
        const void     *model_map,
        uint64_t        model_size,
        const uint64_t *offsets,
        const uint64_t *sizes,
        uint32_t        count);

int ds4_gpu_set_model_map_spans(
        const void *model_map,
        uint64_t model_size,
        const uint64_t *offsets,
        const uint64_t *sizes,
        uint32_t count,
        uint64_t max_tensor_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!model_map || model_size == 0 || !offsets || !sizes || count == 0) return 0;
    if (count == 1) {
        return ds4_gpu_set_model_map_range(model_map,
                                           model_size,
                                           offsets[0],
                                           sizes[0],
                                           max_tensor_bytes);
    }
    if (ds4_gpu_model_views_cover_spans(model_map, model_size, offsets, sizes, count)) {
        return 1;
    }

    @autoreleasepool {
        const double t0 = ds4_gpu_now_ms();
        max_tensor_bytes = ds4_gpu_effective_model_max_tensor_bytes(model_size, max_tensor_bytes);

        ds4_gpu_model_residency_clear();
        ds4_gpu_model_views_clear();

        uint64_t mapped_total = 0;
        uint64_t first_offset = UINT64_MAX;
        for (uint32_t i = 0; i < count; i++) {
            if (offsets[i] > model_size || sizes[i] == 0 || sizes[i] > model_size - offsets[i]) {
                fprintf(stderr, "ds4: Metal model span %u is outside the GGUF mapping\n", i);
                ds4_gpu_model_residency_clear();
                ds4_gpu_model_views_clear();
                return 0;
            }
            if (offsets[i] < first_offset) first_offset = offsets[i];
            uint64_t effective_max = max_tensor_bytes;
            if (effective_max > sizes[i]) effective_max = sizes[i];
            if (!ds4_gpu_add_model_view_range(model_map,
                                              model_size,
                                              offsets[i],
                                              sizes[i],
                                              effective_max,
                                              true,
                                              &mapped_total)) {
                ds4_gpu_model_residency_clear();
                ds4_gpu_model_views_clear();
                return 0;
            }
        }
        if (!ds4_gpu_finish_model_views(t0, mapped_total, first_offset)) {
            ds4_gpu_model_residency_clear();
            ds4_gpu_model_views_clear();
            return 0;
        }
        g_model_map_ptr = model_map;
        g_model_map_size = model_size;
        g_model_mapped_offset = first_offset == UINT64_MAX ? 0 : first_offset;
        g_model_mapped_size = mapped_total;
        g_model_mapped_max_tensor_bytes = max_tensor_bytes;
        if (ds4_gpu_model_map_log_enabled()) {
            fprintf(stderr,
                    "ds4: Metal mapped mmaped model as %u disjoint shared buffers across %u tensor spans\n",
                    g_model_view_count,
                    count);
        }
        return 1;
    }
}

int ds4_gpu_set_model_map(const void *model_map, uint64_t model_size) {
    return ds4_gpu_set_model_map_range(model_map, model_size, 0, model_size, 0);
}

int ds4_gpu_set_model_fd(int fd) {
    g_model_fd = fd;
    return 1;
}

static int ds4_gpu_qwen35_expert_pack_add_u64(
        uint64_t a,
        uint64_t b,
        uint64_t *out) {
    if (!out || a > UINT64_MAX - b) return 0;
    *out = a + b;
    return 1;
}

static int ds4_gpu_qwen35_expert_pack_mul_u64(
        uint64_t a,
        uint64_t b,
        uint64_t *out) {
    if (!out || (a != 0 && b > UINT64_MAX / a)) return 0;
    *out = a * b;
    return 1;
}

static int ds4_gpu_qwen35_expert_pack_align_up_u64(
        uint64_t value,
        uint64_t alignment,
        uint64_t *out) {
    if (!out || alignment == 0) return 0;
    const uint64_t remainder = value % alignment;
    if (remainder == 0) {
        *out = value;
        return 1;
    }
    return ds4_gpu_qwen35_expert_pack_add_u64(
        value, alignment - remainder, out);
}

static int ds4_gpu_qwen35_expert_pack_range_valid(
        uint64_t offset,
        uint64_t bytes,
        uint64_t limit) {
    return bytes != 0 && offset <= limit && bytes <= limit - offset;
}

static int ds4_gpu_qwen35_expert_pack_ranges_overlap(
        uint64_t a_offset,
        uint64_t a_bytes,
        uint64_t b_offset,
        uint64_t b_bytes) {
    /* Both ranges have already been checked against one model_size, so their
     * additions cannot overflow. */
    return a_offset < b_offset + b_bytes &&
           b_offset < a_offset + a_bytes;
}

static void ds4_gpu_qwen35_expert_pack_resident_reset(void) {
    for (uint32_t layer = 0;
         layer < DS4_EXPERT_STORE_MAX_LAYER;
         layer++) {
        /* Release the no-copy Metal wrapper before unmapping its bytes. */
        g_qwen35_expert_pack_resident_buffers[layer] = nil;
        if (g_qwen35_expert_pack.resident_maps[layer] &&
            g_qwen35_expert_pack.resident_map_bytes[layer] != 0) {
            (void)munmap(
                g_qwen35_expert_pack.resident_maps[layer],
                (size_t)g_qwen35_expert_pack.resident_map_bytes[layer]);
        }
        g_qwen35_expert_pack.resident_maps[layer] = NULL;
        g_qwen35_expert_pack.resident_map_bytes[layer] = 0;
        g_qwen35_expert_pack.resident_data_inner[layer] = 0;
    }
    g_qwen35_expert_pack.resident_active = 0;
}

static void ds4_gpu_qwen35_expert_pack_state_reset(void) {
    ds4_gpu_qwen35_expert_pack_resident_reset();
    memset(&g_qwen35_expert_pack, 0, sizeof(g_qwen35_expert_pack));
    g_qwen35_expert_pack.fd = -1;
}

static void ds4_gpu_target_expert_pack_advance_generation(void) {
    g_target_expert_pack_generation =
        g_target_expert_pack_generation == UINT64_MAX ?
            1 : g_target_expert_pack_generation + 1;
    if (g_target_expert_pack_generation == 0) {
        g_target_expert_pack_generation = 1;
    }
}

static void ds4_gpu_dspark_support_pack_advance_generation(void) {
    g_dspark_support_pack_generation =
        g_dspark_support_pack_generation == UINT64_MAX ?
            1 : g_dspark_support_pack_generation + 1;
    if (g_dspark_support_pack_generation == 0) {
        g_dspark_support_pack_generation = 1;
    }
}

static void ds4_gpu_qwen35_expert_pack_clear(void) {
    if (ds4_gpu_dspark_support_lease_active()) {
        fprintf(stderr,
                "ds4: cannot clear Metal expert store while a DSpark SUPPORT lease is active\n");
        return;
    }
    if (!g_qwen35_expert_pack.active) {
        ds4_gpu_qwen35_expert_pack_state_reset();
        return;
    }

    /* The descriptor is engine-owned and may be closed immediately after this
     * call. First fence GPU consumers, then drain every asynchronous pread
     * generation and discard cache entries while the expert-store fd is still
     * valid. No worker can retain the old descriptor after clear() returns. */
    if (g_initialized) {
        if (!ds4_gpu_synchronize()) {
            fprintf(stderr,
                    "ds4: Metal Qwen expert-pack clear could not synchronize GPU work\n");
        }
        ds4_gpu_stream_expert_cache_clear_all(0);
        ds4_gpu_dspark_support_cache_clear(1);
        /* A resident pack is part of the model residency set. End that set
         * before releasing its no-copy buffers and unmapping their storage. */
        ds4_gpu_model_residency_clear();
    }
    ds4_gpu_target_expert_pack_advance_generation();
    ds4_gpu_qwen35_expert_pack_state_reset();
}

void ds4_gpu_expert_store_v2_clear(void) {
    ds4_gpu_qwen35_expert_pack_clear();
}

void ds4_gpu_expert_store_v2_clear_for_store(
        ds4_gpu_expert_store_id store_id) {
    if (ds4_gpu_dspark_support_lease_active()) {
        fprintf(stderr,
                "ds4: cannot clear Metal expert store while a DSpark SUPPORT lease is active\n");
        return;
    }
    ds4_gpu_qwen35_expert_pack_state *pack =
        ds4_gpu_expert_pack_for_store(store_id);
    if (!pack) return;
    if (store_id == DS4_GPU_EXPERT_STORE_TARGET) {
        ds4_gpu_qwen35_expert_pack_clear();
        return;
    }
    /* The white-box SUPPORT transaction is synchronous and fenced, while
     * product DSpark execution remains disconnected and fail-closed.  Fence
     * any retained shared test record again before descriptor teardown. */
    if (g_initialized && g_dspark_support_cache_entry_count != 0 &&
        !ds4_gpu_synchronize()) {
        fprintf(stderr,
                "ds4: Metal DSpark SUPPORT clear could not synchronize GPU work\n");
    }
    ds4_gpu_dspark_support_cache_clear(1);
    ds4_gpu_dspark_support_pack_advance_generation();
    free(pack);
    g_dspark_expert_pack = NULL;
    g_dspark_support_target_generation = 0;
}

int ds4_gpu_expert_store_v2_layer_span_for_store(
        ds4_gpu_expert_store_id store_id,
        uint32_t layer,
        uint64_t model_size,
        uint64_t *offset,
        uint64_t *size) {
    const ds4_gpu_qwen35_expert_pack_state *pack =
        ds4_gpu_expert_pack_for_store(store_id);
    uint32_t index = 0;
    if (!pack || !pack->active || !pack->embedded_v2 ||
        !ds4_gpu_expert_store_layer_index(pack, layer, &index) ||
        !pack->layers[index].valid ||
        pack->model_size != model_size || !offset || !size) {
        return 0;
    }
    const ds4_gpu_qwen35_expert_pack_layer *entry = &pack->layers[index];
    if (!ds4_gpu_qwen35_expert_pack_range_valid(
            entry->data_offset, entry->data_size, model_size)) {
        return 0;
    }
    *offset = entry->data_offset;
    *size = entry->data_size;
    return 1;
}

int ds4_gpu_expert_store_v2_layer_span(
        uint32_t layer,
        uint64_t model_size,
        uint64_t *offset,
        uint64_t *size) {
    return ds4_gpu_expert_store_v2_layer_span_for_store(
        DS4_GPU_EXPERT_STORE_TARGET, layer, model_size, offset, size);
}

int ds4_gpu_expert_store_v2_install_for_store(
        ds4_gpu_expert_store_id              store_id,
        int                                  fd,
        uint64_t                             file_size,
        uint32_t                             n_layer,
        uint32_t                             n_expert,
        uint32_t                             storage_format,
        uint32_t                             group_size,
        const ds4_gpu_expert_store_layer_v2 *layers) {
    if (ds4_gpu_dspark_support_lease_active()) return 0;
    struct stat st;
    int flags = -1;
    ds4_gpu_qwen35_expert_pack_state *pack =
        ds4_gpu_expert_pack_for_store(store_id);
    const bool support_store = store_id == DS4_GPU_EXPERT_STORE_SUPPORT;
    if (store_id != DS4_GPU_EXPERT_STORE_TARGET && !support_store) return 0;
    const bool storage_valid =
        (storage_format == DS4_EXPERT_STORE_STORAGE_GGML &&
         group_size == 0u) ||
        (storage_format == DS4_EXPERT_STORE_STORAGE_MLX_AFFINE4 &&
         group_size == 64u);
    if (fd < 0 || !layers || n_layer == 0 ||
        n_layer > DS4_EXPERT_STORE_MAX_LAYER || n_expert == 0 ||
        n_expert > DS4_EXPERT_STORE_MAX_EXPERT ||
        !storage_valid ||
        file_size > (uint64_t)LLONG_MAX ||
        fstat(fd, &st) != 0 || st.st_size < 0 || !S_ISREG(st.st_mode) ||
        (uint64_t)st.st_size != file_size ||
        (flags = fcntl(fd, F_GETFL)) < 0 ||
        (flags & O_ACCMODE) == O_WRONLY) {
        return 0;
    }
    uint32_t previous_layer = 0;
    for (uint32_t index = 0; index < n_layer; index++) {
        const ds4_gpu_expert_store_layer_v2 *entry = &layers[index];
        uint64_t expected_record = 0;
        uint64_t expected_layer = 0;
        if (entry->reserved != 0 ||
            entry->layer > DS4_EXPERT_STORE_MAX_MODEL_LAYER ||
            (index != 0 && entry->layer <= previous_layer) ||
            entry->record_bytes == 0 || entry->data_size == 0 ||
            entry->component_offset[0] != 0) {
            return 0;
        }
        for (uint32_t role = 0; role < 3; role++) {
            if (entry->component_bytes[role] == 0 ||
                entry->component_offset[role] != expected_record ||
                !ds4_gpu_qwen35_expert_pack_add_u64(
                    expected_record, entry->component_bytes[role],
                    &expected_record)) {
                return 0;
            }
        }
        if (expected_record != entry->record_bytes ||
            !ds4_gpu_qwen35_expert_pack_mul_u64(
                entry->record_bytes, n_expert, &expected_layer) ||
            expected_layer != entry->data_size ||
            !ds4_gpu_qwen35_expert_pack_range_valid(
                entry->data_offset, entry->data_size, file_size)) {
            return 0;
        }
        if (index != 0) {
            const ds4_gpu_expert_store_layer_v2 *previous = &layers[index - 1];
            if (entry->data_offset < previous->data_offset + previous->data_size) {
                return 0;
            }
        }
        previous_layer = entry->layer;
    }
    ds4_gpu_qwen35_expert_pack_state *support_pack = NULL;
    if (support_store) {
        if (n_layer > DS4_DSPARK_SUPPORT_LAYER_COUNT ||
            n_expert > DS4_DSPARK_SUPPORT_EXPERT_COUNT) {
            return 0;
        }
        support_pack = calloc(1, sizeof(*support_pack));
        if (!support_pack) return 0;
        if (pack) ds4_gpu_expert_store_v2_clear_for_store(store_id);
        pack = support_pack;
    } else if (pack->active) {
        ds4_gpu_expert_store_v2_clear_for_store(store_id);
    }
    memset(pack, 0, sizeof(*pack));
    pack->fd = fd;
    pack->file_device = st.st_dev;
    pack->file_inode = st.st_ino;
    pack->file_size = file_size;
    pack->n_layer = n_layer;
    pack->n_expert = n_expert;
    pack->storage_format = storage_format;
    pack->group_size = group_size;
    pack->embedded_v2 = 1;
    for (uint32_t index = 0; index < n_layer; index++) {
        ds4_gpu_qwen35_expert_pack_layer *destination =
            &pack->layers[index];
        destination->layer = layers[index].layer;
        destination->data_offset = layers[index].data_offset;
        destination->data_size = layers[index].data_size;
        destination->record_bytes = layers[index].record_bytes;
        memcpy(destination->component_offset, layers[index].component_offset,
               sizeof(destination->component_offset));
        memcpy(destination->component_bytes, layers[index].component_bytes,
               sizeof(destination->component_bytes));
    }
    pack->active = 1;
    if (support_store) {
        ds4_gpu_dspark_support_pack_advance_generation();
        g_dspark_expert_pack = support_pack;
        g_dspark_support_target_generation =
            g_qwen35_expert_pack.active ?
                g_target_expert_pack_generation : 0;
    } else {
        ds4_gpu_target_expert_pack_advance_generation();
    }
    return 1;
}

int ds4_gpu_expert_store_v2_install(
        int                                  fd,
        uint64_t                             file_size,
        uint32_t                             n_layer,
        uint32_t                             n_expert,
        uint32_t                             storage_format,
        uint32_t                             group_size,
        const ds4_gpu_expert_store_layer_v2 *layers) {
    return ds4_gpu_expert_store_v2_install_for_store(
        DS4_GPU_EXPERT_STORE_TARGET, fd, file_size, n_layer, n_expert,
        storage_format, group_size, layers);
}

static int ds4_gpu_expert_store_bind_layer_internal(
        ds4_gpu_qwen35_expert_pack_state *pack,
        uint32_t layer,
        uint64_t model_size,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset) {
    uint32_t index = 0;
    if (!pack->active || model_size == 0 ||
        !ds4_gpu_expert_store_layer_index(pack, layer, &index)) return 0;

    const uint64_t offsets[3] = {gate_offset, up_offset, down_offset};
    uint64_t totals[3] = {0, 0, 0};
    for (uint32_t role = 0; role < 3; role++) {
        if (!ds4_gpu_qwen35_expert_pack_mul_u64(
                pack->layers[index].component_bytes[role],
                pack->n_expert, &totals[role]) ||
            !ds4_gpu_qwen35_expert_pack_range_valid(
                offsets[role], totals[role], model_size)) {
            return 0;
        }
        for (uint32_t previous = 0; previous < role; previous++) {
            if (ds4_gpu_qwen35_expert_pack_ranges_overlap(
                    offsets[role], totals[role], offsets[previous],
                    totals[previous])) {
                return 0;
            }
        }
    }

    ds4_gpu_qwen35_expert_pack_layer *binding = &pack->layers[index];
    if (binding->valid) {
        return pack->model_size == model_size &&
               binding->gate_offset == gate_offset &&
               binding->up_offset == up_offset &&
               binding->down_offset == down_offset;
    }
    if (pack->bound_layers != 0 && pack->model_size != model_size) return 0;

    /* Canonical identity ranges must be globally unique even though their
     * bytes are virtual in a native GGUF. This keeps every cache key and
     * translated read deterministic. */
    for (uint32_t other = 0; other < pack->n_layer; other++) {
        const ds4_gpu_qwen35_expert_pack_layer *old = &pack->layers[other];
        if (!old->valid) continue;
        const uint64_t old_offsets[3] = {
            old->gate_offset, old->up_offset, old->down_offset,
        };
        for (uint32_t role = 0; role < 3; role++) {
            for (uint32_t old_role = 0; old_role < 3; old_role++) {
                uint64_t old_total = 0;
                if (!ds4_gpu_qwen35_expert_pack_mul_u64(
                        old->component_bytes[old_role], pack->n_expert,
                        &old_total) ||
                    ds4_gpu_qwen35_expert_pack_ranges_overlap(
                        offsets[role], totals[role], old_offsets[old_role],
                        old_total)) {
                    return 0;
                }
            }
        }
    }
    if (pack->bound_layers == 0) pack->model_size = model_size;
    binding->gate_offset = gate_offset;
    binding->up_offset = up_offset;
    binding->down_offset = down_offset;
    binding->valid = 1;
    pack->bound_layers++;
    return 1;
}

int ds4_gpu_expert_store_v2_bind_layer(
        uint32_t layer,
        uint64_t model_size,
        uint64_t gate_offset,
    uint64_t up_offset,
    uint64_t down_offset) {
    if (ds4_gpu_dspark_support_lease_active()) return 0;
    return ds4_gpu_expert_store_bind_layer_internal(
        &g_qwen35_expert_pack, layer, model_size,
        gate_offset, up_offset, down_offset);
}

int ds4_gpu_expert_store_v2_bind_layer_for_store(
        ds4_gpu_expert_store_id store_id,
        uint32_t layer,
        uint64_t model_size,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset) {
    if (ds4_gpu_dspark_support_lease_active()) return 0;
    ds4_gpu_qwen35_expert_pack_state *pack =
        ds4_gpu_expert_pack_for_store(store_id);
    const int combined_before =
        ds4_gpu_dspark_support_cache_combined_available();
    if (!pack || !ds4_gpu_expert_store_bind_layer_internal(
            pack, layer, model_size,
            gate_offset, up_offset, down_offset)) {
        return 0;
    }
    if (!combined_before &&
        ds4_gpu_dspark_support_cache_combined_available() &&
        (store_id != DS4_GPU_EXPERT_STORE_SUPPORT ||
         !ds4_gpu_dspark_support_cache_activate_combined())) {
        if (g_dspark_expert_pack) {
            ds4_gpu_expert_store_v2_clear_for_store(
                DS4_GPU_EXPERT_STORE_SUPPORT);
        }
        return 0;
    }
    return 1;
}

static int ds4_gpu_qwen35_expert_pack_enable_resident(void) {
    ds4_gpu_qwen35_expert_pack_state *pack = &g_qwen35_expert_pack;
    if (!pack->active || !g_initialized || !g_device ||
        pack->bound_layers != pack->n_layer || pack->n_layer == 0 ||
        pack->resident_active) {
        return pack->resident_active ? 1 : 0;
    }

    const long page_long = sysconf(_SC_PAGESIZE);
    if (page_long <= 0) return 0;
    const uint64_t page = (uint64_t)page_long;
    for (uint32_t layer = 0;
         layer < pack->n_layer;
         layer++) {
        const ds4_gpu_qwen35_expert_pack_layer *entry =
            &pack->layers[layer];
        const uint64_t file_offset = entry->data_offset;
        const uint64_t layer_bytes = entry->data_size;
        if (!entry->valid || layer_bytes == 0 ||
            layer_bytes > NSUIntegerMax ||
            layer_bytes > (uint64_t)[g_device maxBufferLength]) {
            ds4_gpu_qwen35_expert_pack_resident_reset();
            return 0;
        }
        const uint64_t map_offset = file_offset - (file_offset % page);
        const uint64_t data_inner = file_offset - map_offset;
        uint64_t required_bytes = 0;
        uint64_t map_bytes = 0;
        if (!ds4_gpu_qwen35_expert_pack_add_u64(
                data_inner, layer_bytes, &required_bytes) ||
            !ds4_gpu_qwen35_expert_pack_align_up_u64(
                required_bytes, page, &map_bytes) ||
            map_bytes == 0 ||
            map_offset > (uint64_t)LLONG_MAX ||
            map_bytes > NSUIntegerMax ||
            map_bytes > (uint64_t)[g_device maxBufferLength]) {
            ds4_gpu_qwen35_expert_pack_resident_reset();
            return 0;
        }

        void *mapping = mmap(NULL,
                             (size_t)map_bytes,
                             PROT_READ,
                             MAP_PRIVATE,
                             pack->fd,
                             (off_t)map_offset);
        if (mapping == MAP_FAILED) {
            fprintf(stderr,
                    "ds4: Metal could not mmap expert-major layer %u: %s\n",
                    entry->layer,
                    strerror(errno));
            ds4_gpu_qwen35_expert_pack_resident_reset();
            return 0;
        }
        pack->resident_maps[layer] = mapping;
        pack->resident_map_bytes[layer] = map_bytes;
        pack->resident_data_inner[layer] = data_inner;

        id<MTLBuffer> buffer =
            [g_device newBufferWithBytesNoCopy:mapping
                                         length:(NSUInteger)map_bytes
                                        options:ds4_gpu_model_resource_options()
                                    deallocator:nil];
        if (!buffer) {
            fprintf(stderr,
                    "ds4: Metal could not wrap expert-major layer %u\n",
                    entry->layer);
            ds4_gpu_qwen35_expert_pack_resident_reset();
            return 0;
        }
        buffer.label = [NSString stringWithFormat:
            @"ds4_expert_major_layer_%u", entry->layer];
        g_qwen35_expert_pack_resident_buffers[layer] = buffer;
    }

    pack->resident_active = 1;
    return 1;
}

int ds4_gpu_expert_store_v2_enable_resident(void) {
    if (ds4_gpu_dspark_support_lease_active()) return 0;
    return ds4_gpu_qwen35_expert_pack_enable_resident();
}

/* Resolve only an exact canonical layer binding.  The caller keeps the
 * canonical offsets as model identity, while the returned bases and stride
 * describe the expert-major buffer consumed by the existing ID kernels. */
static int ds4_gpu_qwen35_expert_pack_resident_layer(
        uint32_t       layer,
        uint64_t       model_size,
        uint64_t       gate_offset,
        uint64_t       up_offset,
        uint64_t       down_offset,
        id<MTLBuffer> *buffer,
        uint64_t      *gate_inner,
        uint64_t      *up_inner,
        uint64_t      *down_inner,
        uint64_t      *expert_stride) {
    const ds4_gpu_qwen35_expert_pack_state *pack = &g_qwen35_expert_pack;
    uint32_t index = 0;
    if (!pack->active || !pack->resident_active ||
        !ds4_gpu_expert_store_layer_index(pack, layer, &index) ||
        !pack->layers[index].valid ||
        pack->model_size != model_size ||
        pack->layers[index].gate_offset != gate_offset ||
        pack->layers[index].up_offset != up_offset ||
        pack->layers[index].down_offset != down_offset ||
        !g_qwen35_expert_pack_resident_buffers[index] ||
        !buffer || !gate_inner || !up_inner || !down_inner ||
        !expert_stride) {
        return 0;
    }
    const ds4_gpu_qwen35_expert_pack_layer *entry = &pack->layers[index];
    *buffer = g_qwen35_expert_pack_resident_buffers[index];
    *gate_inner = pack->resident_data_inner[index] +
        entry->component_offset[0];
    *up_inner = pack->resident_data_inner[index] +
        entry->component_offset[1];
    *down_inner = pack->resident_data_inner[index] +
        entry->component_offset[2];
    *expert_stride = entry->record_bytes;
    return 1;
}

/* The same logical binding can be backed either by all resident layer
 * buffers or, in SSD mode, by the one physical v2 layer span installed in the
 * current model views.  Keeping the selection here prevents native GGUF
 * addressing rules from leaking into the routed-MoE encoder. */
static int ds4_gpu_qwen35_expert_pack_resolve_layer(
        const void    *model_map,
        uint32_t       layer,
        uint64_t       model_size,
        uint64_t       gate_offset,
        uint64_t       up_offset,
        uint64_t       down_offset,
        id<MTLBuffer> *buffer,
        uint64_t      *gate_inner,
        uint64_t      *up_inner,
        uint64_t      *down_inner,
        uint64_t      *expert_stride) {
    if (!g_ssd_streaming_mode) {
        return ds4_gpu_qwen35_expert_pack_resident_layer(
            layer, model_size, gate_offset, up_offset, down_offset,
            buffer, gate_inner, up_inner, down_inner, expert_stride);
    }

    const ds4_gpu_qwen35_expert_pack_state *pack = &g_qwen35_expert_pack;
    uint32_t index = 0;
    if (!pack->active || !pack->embedded_v2 ||
        !ds4_gpu_expert_store_layer_index(pack, layer, &index) ||
        !pack->layers[index].valid ||
        pack->model_size != model_size ||
        pack->layers[index].gate_offset != gate_offset ||
        pack->layers[index].up_offset != up_offset ||
        pack->layers[index].down_offset != down_offset ||
        !buffer || !gate_inner || !up_inner || !down_inner ||
        !expert_stride) {
        return 0;
    }
    const ds4_gpu_qwen35_expert_pack_layer *entry = &pack->layers[index];
    uint64_t physical_inner = 0;
    id<MTLBuffer> physical = ds4_gpu_wrap_model_range(
        model_map, model_size, entry->data_offset, entry->data_size,
        &physical_inner);
    if (!physical) return 0;
    *buffer = physical;
    *gate_inner = physical_inner + entry->component_offset[0];
    *up_inner = physical_inner + entry->component_offset[1];
    *down_inner = physical_inner + entry->component_offset[2];
    *expert_stride = entry->record_bytes;
    return 1;
}

/* Return 0 when no pack is installed, 1 for a translated expert slice, and
 * -1 when a pack is active but the canonical read is not exactly mappable. */
static int ds4_gpu_qwen35_expert_pack_resolve_for_store(
        ds4_gpu_expert_store_id store_id,
        uint64_t canonical_offset,
        uint64_t len,
        int     *source_fd,
        uint64_t *source_offset) {
    const ds4_gpu_qwen35_expert_pack_state *pack =
        ds4_gpu_expert_pack_for_store(store_id);
    if (!pack || !pack->active) return 0;
    if (!source_fd || !source_offset || len == 0) return -1;

    for (uint32_t layer = 0; layer < pack->n_layer; layer++) {
        const ds4_gpu_qwen35_expert_pack_layer *binding =
            &pack->layers[layer];
        if (!binding->valid) continue;
        const uint64_t offsets[3] = {
            binding->gate_offset,
            binding->up_offset,
            binding->down_offset,
        };
        for (uint32_t kind = 0; kind < 3; kind++) {
            uint64_t total = 0;
            if (!ds4_gpu_qwen35_expert_pack_mul_u64(
                    binding->component_bytes[kind], pack->n_expert,
                    &total)) {
                return -1;
            }
            if (canonical_offset < offsets[kind]) continue;
            const uint64_t relative = canonical_offset - offsets[kind];
            if (relative >= total) continue;
            if (len != binding->component_bytes[kind] ||
                relative % binding->component_bytes[kind] != 0) {
                return -1;
            }
            const uint64_t expert =
                relative / binding->component_bytes[kind];
            uint64_t translated = 0;
            if (!ds4_gpu_qwen35_expert_pack_mul_u64(
                    expert, binding->record_bytes, &translated) ||
                !ds4_gpu_qwen35_expert_pack_add_u64(
                    binding->data_offset, translated, &translated) ||
                !ds4_gpu_qwen35_expert_pack_add_u64(
                    translated, binding->component_offset[kind],
                    &translated) ||
                translated > pack->file_size ||
                len > pack->file_size - translated) {
                return -1;
            }
            *source_fd = pack->fd;
            *source_offset = translated;
            return 1;
        }
    }
    return -1;
}

static int ds4_gpu_qwen35_expert_pack_resolve(
        uint64_t canonical_offset,
        uint64_t len,
        int     *source_fd,
        uint64_t *source_offset) {
    return ds4_gpu_qwen35_expert_pack_resolve_for_store(
        DS4_GPU_EXPERT_STORE_TARGET, canonical_offset, len,
        source_fd, source_offset);
}

/* Resolve one complete embedded-v2 expert record.  The cache stores gate,
 * up, and down contiguously in the same order as the native GGUF, so one
 * direct pread can fill the whole slab slot.  On the measured M5 SSD, three
 * parallel component reads were faster than one 6.75 MiB read; full-record
 * coalescing is therefore diagnostic opt-in while normal v2 execution keeps
 * the established three-task pool. */
static int ds4_gpu_expert_store_v2_resolve_record(
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_bytes,
        uint64_t down_bytes,
        int     *source_fd,
        uint64_t *source_offset,
        uint64_t *record_bytes) {
    const ds4_gpu_qwen35_expert_pack_state *pack = &g_qwen35_expert_pack;
    if (!pack->active || !pack->embedded_v2) return 0;
    if (!source_fd || !source_offset || !record_bytes ||
        gate_bytes == 0 || down_bytes == 0 ||
        gate_bytes > (UINT64_MAX - down_bytes) / 2u) {
        return -1;
    }

    int gate_fd = -1;
    int up_fd = -1;
    int down_fd = -1;
    uint64_t gate_source = 0;
    uint64_t up_source = 0;
    uint64_t down_source = 0;
    if (ds4_gpu_qwen35_expert_pack_resolve(
            gate_offset, gate_bytes, &gate_fd, &gate_source) != 1 ||
        ds4_gpu_qwen35_expert_pack_resolve(
            up_offset, gate_bytes, &up_fd, &up_source) != 1 ||
        ds4_gpu_qwen35_expert_pack_resolve(
            down_offset, down_bytes, &down_fd, &down_source) != 1 ||
        gate_fd != up_fd || gate_fd != down_fd ||
        up_source != gate_source + gate_bytes ||
        down_source != up_source + gate_bytes) {
        return -1;
    }
    *source_fd = gate_fd;
    *source_offset = gate_source;
    *record_bytes = gate_bytes * 2u + down_bytes;
    return 1;
}

static int ds4_gpu_model_views_cover_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    size) {
    if (!model_map || model_size == 0 || size == 0 ||
        offset > model_size || size > model_size - offset) {
        return 0;
    }
    const uint64_t end = offset + size;
    for (uint32_t i = 0; i < g_model_view_count; i++) {
        if (g_model_views[i].model_map != model_map ||
            g_model_views[i].model_size != model_size) {
            continue;
        }
        const uint64_t view_start = g_model_views[i].model_offset;
        const uint64_t view_end = view_start + g_model_views[i].bytes;
        if (offset >= view_start && end <= view_end) return 1;
    }
    return 0;
}

static int ds4_gpu_model_views_cover_spans(
        const void     *model_map,
        uint64_t        model_size,
        const uint64_t *offsets,
        const uint64_t *sizes,
        uint32_t        count) {
    if (!offsets || !sizes || count == 0) return 0;
    for (uint32_t i = 0; i < count; i++) {
        if (!ds4_gpu_model_views_cover_range(model_map,
                                             model_size,
                                             offsets[i],
                                             sizes[i])) {
            return 0;
        }
    }
    return 1;
}

int ds4_gpu_set_model_fd_for_map(int fd, const void *model_map) {
    (void)fd;
    (void)model_map;
    return 1;
}

static id<MTLBuffer> ds4_gpu_wrap_model_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset) {
    (void)model_map;
    if (model_size == 0 || offset > model_size || len > model_size - offset) {
        fprintf(stderr, "ds4: Metal model range is outside the mapped model\n");
        return nil;
    }

    const uint64_t end = offset + len;
    for (uint32_t i = 0; i < g_model_view_count; i++) {
        if (g_model_views[i].model_map != model_map ||
            g_model_views[i].model_size != model_size) {
            continue;
        }
        const uint64_t view_start = g_model_views[i].model_offset;
        const uint64_t view_end = view_start + g_model_views[i].bytes;
        if (offset >= view_start && end <= view_end) {
            *inner_offset = offset - view_start;
            return g_model_views[i].buffer;
        }
    }

    fprintf(stderr,
            "ds4: Metal model range %.2f..%.2f GiB is not covered by mapped model views\n",
            ds4_gpu_gib(offset),
            ds4_gpu_gib(end));
    return nil;
}

typedef enum {
    DS4_GPU_EXACT_VIEW_CACHED,
    DS4_GPU_EXACT_VIEW_TRANSIENT,
    DS4_GPU_EXACT_VIEW_OWNED,
} ds4_gpu_exact_view_lifetime;

static id<MTLBuffer> ds4_gpu_wrap_model_exact_range_impl(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset,
        ds4_gpu_exact_view_lifetime lifetime) {
    const bool cache_view = lifetime == DS4_GPU_EXACT_VIEW_CACHED;
    const bool transient_view = lifetime == DS4_GPU_EXACT_VIEW_TRANSIENT;
    if (!model_map || !g_device ||
        (cache_view && !g_model_buffer_cache) ||
        (transient_view && !g_transient_buffers) ||
        model_size == 0 || offset > model_size || len > model_size - offset) {
        fprintf(stderr, "ds4: Metal exact model range is outside the mapped model\n");
        return nil;
    }

    const uint64_t page = (uint64_t)getpagesize();
    const uint64_t page_offset = offset & ~(page - 1);
    const uint64_t leading = offset - page_offset;
    if (len > UINT64_MAX - leading ||
        leading + len > UINT64_MAX - (page - 1)) {
        fprintf(stderr, "ds4: Metal exact model range overflows page alignment\n");
        return nil;
    }
    uint64_t view_bytes = round_up_u64(leading + len, page);
    if (view_bytes > model_size - page_offset) view_bytes = model_size - page_offset;
    if (leading + len > view_bytes) {
        fprintf(stderr, "ds4: Metal exact model range alignment exceeds mapped model\n");
        return nil;
    }
    if (view_bytes > (uint64_t)[g_device maxBufferLength]) {
        fprintf(stderr,
                "ds4: Metal exact model range %.2f GiB exceeds maxBufferLength %.2f GiB\n",
                ds4_gpu_gib(view_bytes),
                ds4_gpu_gib((uint64_t)[g_device maxBufferLength]));
        return nil;
    }

    NSString *key = nil;
    id<MTLBuffer> buffer = nil;
    if (cache_view) {
        key = [NSString stringWithFormat:@"%p:%llu:%llu:%llu",
               model_map,
               (unsigned long long)model_size,
               (unsigned long long)page_offset,
               (unsigned long long)view_bytes];
        buffer = [g_model_buffer_cache objectForKey:key];
    }
    if (!buffer) {
        const uintptr_t base = (uintptr_t)model_map;
        buffer = [g_device newBufferWithBytesNoCopy:(void *)(base + page_offset)
                                             length:(NSUInteger)view_bytes
                                            options:ds4_gpu_model_resource_options()
                                        deallocator:nil];
        if (!buffer) {
            fprintf(stderr,
                    "ds4: Metal could not wrap exact mmaped model range at %.2f GiB, size %.2f MiB\n",
                    ds4_gpu_gib(page_offset),
                    ds4_gpu_mib(view_bytes));
            return nil;
        }
        if (cache_view) {
            buffer.label = @"ds4_model_exact_view";
        } else if (transient_view) {
            buffer.label = @"ds4_model_exact_transient_view";
        } else {
            buffer.label = @"ds4_model_exact_owned_view";
        }
        if (cache_view) {
            [g_model_buffer_cache setObject:buffer forKey:key];
            ds4_gpu_model_buffer_cache_note_insert(view_bytes);
        } else if (transient_view) {
            [g_transient_buffers addObject:buffer];
        }
    }

    if (inner_offset) *inner_offset = leading;
    return buffer;
}

static id<MTLBuffer> ds4_gpu_wrap_model_exact_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset) {
    return ds4_gpu_wrap_model_exact_range_impl(model_map,
                                               model_size,
                                               offset,
                                               len,
                                               inner_offset,
                                               DS4_GPU_EXACT_VIEW_CACHED);
}

static id<MTLBuffer> ds4_gpu_wrap_model_exact_range_transient(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset) {
    return ds4_gpu_wrap_model_exact_range_impl(model_map,
                                               model_size,
                                               offset,
                                               len,
                                               inner_offset,
                                               DS4_GPU_EXACT_VIEW_TRANSIENT);
}

static id<MTLBuffer> ds4_gpu_wrap_model_exact_range_owned(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t   *inner_offset) {
    return ds4_gpu_wrap_model_exact_range_impl(model_map,
                                               model_size,
                                               offset,
                                               len,
                                               inner_offset,
                                               DS4_GPU_EXACT_VIEW_OWNED);
}

static id<MTLBuffer> ds4_gpu_wrap_q8_decode_model_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len,
        uint64_t    n_tokens,
        uint64_t   *inner_offset) {
    const uint64_t exact_decode_max_mib =
        ds4_gpu_env_u64("DS4_METAL_Q8_DECODE_EXACT_VIEW_MAX_MIB",
                        1024u,
                        1u,
                        4096u);
    const uint64_t exact_decode_max_bytes =
        exact_decode_max_mib * 1024ull * 1024ull;
    const bool exact_decode_weight_view =
        n_tokens == 1u &&
        len <= exact_decode_max_bytes &&
        getenv("DS4_METAL_ENABLE_Q8_DECODE_EXACT_VIEWS") != NULL &&
        getenv("DS4_METAL_DISABLE_Q8_DECODE_EXACT_VIEWS") == NULL;
    return exact_decode_weight_view ?
        ds4_gpu_wrap_model_exact_range(model_map,
                                       model_size,
                                       offset,
                                       len,
                                       inner_offset) :
        ds4_gpu_wrap_model_range(model_map,
                                 model_size,
                                 offset,
                                 len,
                                 inner_offset);
}

