        getenv("DS4_METAL_ENABLE_F32_DECODE_EXACT_VIEWS") != NULL &&
        getenv("DS4_METAL_DISABLE_F32_DECODE_EXACT_VIEWS") == NULL;
    return exact_decode_weight_view ?
        ds4_gpu_wrap_model_exact_range(model_map,
