/* Test-only fault injection for the incremental slab guard. */
#ifdef DS4_TEST_HOOKS
void ds4_gpu_internal_stream_expert_cache_fail_growth_guard_after(
        int64_t calls) {
    g_stream_expert_cache_test_growth_guard_fail_after =
        calls < 0 ? -1 : calls;
}
#endif

uint32_t ds4_gpu_stream_expert_cache_budget_for_expert_size(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (!ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes)) {
        return 0;
    }
    return ds4_gpu_stream_expert_cache_configured_budget();
}

static int ds4_gpu_stream_expert_cache_note_expert_size(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (gate_expert_bytes == 0 || down_expert_bytes == 0) return 0;
    if (gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        fprintf(stderr, "ds4: Metal streaming expert cache byte size overflow\n");
        return 0;
    }
    /* The configured value is the physical slot ceiling. Actual reads and
     * cache accounting continue to use each layer's logical record size. */
    const uint64_t bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    if (g_stream_expert_cache_expert_bytes == 0) {
        g_stream_expert_cache_expert_bytes = bytes;
        return 1;
    }
    return bytes <= g_stream_expert_cache_expert_bytes;
}

static uint32_t ds4_gpu_stream_expert_cache_requested_budget(void) {
    if (!g_ssd_streaming_mode) return 0;
    if (g_stream_expert_cache_budget_override != 0) {
        return g_stream_expert_cache_budget_override;
    }
    return 0;
}

static int ds4_gpu_dspark_support_cache_combined_available(void) {
    if (!g_ssd_streaming_mode ||
        !g_qwen35_expert_pack.active ||
        !g_qwen35_expert_pack.embedded_v2 ||
        g_glm_model_mode ||
        g_qwen35_expert_pack.storage_format !=
            DS4_EXPERT_STORE_STORAGE_GGML ||
        g_qwen35_expert_pack.group_size != 0 ||
        g_qwen35_expert_pack.n_layer !=
            DS4_DSPARK_TARGET_LAYER_COUNT ||
        g_qwen35_expert_pack.n_expert != DS4_DSPARK_SUPPORT_EXPERT_COUNT ||
        (g_qwen35_expert_pack.n_layer == QWEN35_N_LAYER &&
         g_qwen35_expert_pack.n_expert == QWEN35_N_EXPERT) ||
        g_qwen35_expert_pack.bound_layers !=
            g_qwen35_expert_pack.n_layer ||
        !g_dspark_expert_pack ||
        !g_dspark_expert_pack->active ||
        !g_dspark_expert_pack->embedded_v2 ||
        g_dspark_expert_pack->storage_format != DS4_EXPERT_STORE_STORAGE_GGML ||
        g_dspark_expert_pack->group_size != 0 ||
        g_dspark_expert_pack->n_layer != DS4_DSPARK_SUPPORT_LAYER_COUNT ||
        g_dspark_expert_pack->n_expert != DS4_DSPARK_SUPPORT_EXPERT_COUNT ||
        g_dspark_expert_pack->bound_layers !=
            g_dspark_expert_pack->n_layer ||
        g_target_expert_pack_generation == 0 ||
        g_dspark_support_target_generation !=
            g_target_expert_pack_generation ||
        g_qwen35_expert_pack.file_device !=
            g_dspark_expert_pack->file_device ||
        g_qwen35_expert_pack.file_inode !=
            g_dspark_expert_pack->file_inode ||
        g_qwen35_expert_pack.file_size !=
            g_dspark_expert_pack->file_size ||
        g_qwen35_expert_pack.model_size == 0 ||
        g_qwen35_expert_pack.model_size !=
            g_dspark_expert_pack->model_size) {
        return 0;
    }
    uint64_t target_record_bytes = 0;
    for (uint32_t layer = 0;
         layer < g_qwen35_expert_pack.n_layer;
         layer++) {
        const ds4_gpu_qwen35_expert_pack_layer *entry =
            &g_qwen35_expert_pack.layers[layer];
        if (!entry->valid || entry->record_bytes == 0) return 0;
        if (layer == 0) target_record_bytes = entry->record_bytes;
        else if (entry->record_bytes != target_record_bytes) return 0;
    }
    uint64_t support_record_bytes = 0;
    for (uint32_t stage = 0; stage < DS4_DSPARK_SUPPORT_LAYER_COUNT; stage++) {
        const ds4_gpu_qwen35_expert_pack_layer *entry =
            &g_dspark_expert_pack->layers[stage];
        if (!entry->valid || entry->layer != stage) return 0;
        if (stage == 0) support_record_bytes = entry->record_bytes;
        else if (entry->record_bytes != support_record_bytes) return 0;
    }
    if (support_record_bytes == 0 ||
        support_record_bytes != target_record_bytes) {
        fprintf(stderr,
                "ds4: DSpark TARGET/SUPPORT record mismatch "
                "(TARGET=%llu, SUPPORT=%llu)\n",
                (unsigned long long)target_record_bytes,
                (unsigned long long)support_record_bytes);
        return 0;
    }
    return 1;
}

static uint32_t ds4_gpu_stream_expert_cache_apply_target_caps(
        uint32_t target_budget,
        int      locked) {
    if (target_budget != 0 &&
        g_stream_expert_cache_growth_budget_cap_active &&
        target_budget > g_stream_expert_cache_growth_budget_cap) {
        target_budget = g_stream_expert_cache_growth_budget_cap;
    }
    if (target_budget != 0 &&
        g_stream_expert_cache_mlock_budget_cap_active &&
        (locked || g_stream_expert_cache_mlock_budget_cap != 0 ||
         g_stream_expert_cache_required_floor != 0) &&
        target_budget > g_stream_expert_cache_mlock_budget_cap) {
        target_budget = g_stream_expert_cache_mlock_budget_cap;
    }
    return target_budget;
}

static uint32_t ds4_gpu_dspark_support_cache_budget_for_parent_mode(
        uint32_t parent_budget,
        int      locked) {
    if (!ds4_gpu_dspark_support_cache_combined_available() ||
        parent_budget < DS4_DSPARK_COMBINED_CACHE_FLOOR) {
        return 0;
    }
    const uint32_t target_candidate = parent_budget -
        DS4_DSPARK_SUPPORT_CACHE_FLOOR;
    return ds4_gpu_stream_expert_cache_apply_target_caps(
               target_candidate, locked) >= DS4_DSPARK_TARGET_CACHE_FLOOR ?
        DS4_DSPARK_SUPPORT_CACHE_FLOOR : 0;
}

static uint32_t ds4_gpu_dspark_support_cache_budget_for_parent(
        uint32_t parent_budget) {
    return ds4_gpu_dspark_support_cache_budget_for_parent_mode(
        parent_budget, 0);
}

static uint32_t ds4_gpu_dspark_support_cache_configured_budget(void) {
    const uint32_t parent = ds4_gpu_stream_expert_cache_requested_budget();
    return ds4_gpu_dspark_support_cache_budget_for_parent(parent);
}

static void ds4_gpu_dspark_support_cache_target_cap_changed(void) {
    if (ds4_gpu_dspark_support_lease_active()) {
        fprintf(stderr,
                "ds4: cannot change DSpark SUPPORT quota while its lease is active\n");
        return;
    }
    if (ds4_gpu_dspark_support_cache_configured_budget() == 0) {
        ds4_gpu_dspark_support_cache_clear(0);
    }
}

static uint32_t ds4_gpu_stream_expert_cache_configured_budget(void) {
    const uint32_t parent = ds4_gpu_stream_expert_cache_requested_budget();
    const uint32_t support =
        ds4_gpu_dspark_support_cache_budget_for_parent(parent);
    const uint32_t target = parent >= support ? parent - support : 0;
    return ds4_gpu_stream_expert_cache_apply_target_caps(target, 0);
}

static uint32_t ds4_gpu_stream_expert_cache_locked_budget(void) {
    const uint32_t parent = ds4_gpu_stream_expert_cache_requested_budget();
    const uint32_t support =
        ds4_gpu_dspark_support_cache_budget_for_parent_mode(parent, 1);
    const uint32_t target = parent >= support ? parent - support : 0;
    return ds4_gpu_stream_expert_cache_apply_target_caps(target, 1);
}

static uint32_t ds4_gpu_stream_expert_cache_parent_budget(int locked) {
    const uint32_t parent = ds4_gpu_stream_expert_cache_requested_budget();
    const uint32_t support =
        ds4_gpu_dspark_support_cache_budget_for_parent_mode(parent, locked);
    const uint32_t target = ds4_gpu_stream_expert_cache_apply_target_caps(
        parent >= support ? parent - support : 0, locked);
    return target > UINT32_MAX - support ? UINT32_MAX : target + support;
}

static int ds4_gpu_stream_expert_cache_required_floor_satisfied(void) {
    return g_stream_expert_cache_required_floor == 0 ||
           ds4_gpu_stream_expert_cache_locked_budget() >=
               g_stream_expert_cache_required_floor;
}

static uint32_t ds4_gpu_stream_expert_cache_effective_cap(
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t n_selected) {
    (void)layer;
    if (ds4_gpu_stream_expert_cache_configured_budget() == 0) return 0;

    /*
     * The residency policy is global: every layer can use any expert slot it
     * routes to, and global pruning decides which existing entry is least
     * valuable.  A per-layer cap made cache size depend on model depth rather
     * than the actual byte budget.
     */
    uint32_t cap = n_total_expert;
    if (cap < n_selected) cap = n_selected;
    if (cap > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        cap = DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
    }
    return cap;
}

static int ds4_gpu_stream_expert_timing_summary_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    if (!checked) {
        enabled =
            (getenv("DS4_METAL_STREAMING_EXPERT_TIMING_SUMMARY") != NULL ||
             getenv("DS4_METAL_STREAMING_EXPERT_PROFILE_SUMMARY") != NULL) &&
            getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_TIMING_SUMMARY") == NULL;
        checked = 1;
    }
    return enabled;
}

static uint32_t ds4_gpu_stream_expert_popcount(uint32_t mask) {
    return (uint32_t)__builtin_popcount(mask);
}

static int ds4_gpu_stream_expert_split_worthwhile(
        uint32_t resident_mask,
        uint32_t missing_mask) {
    if (resident_mask == 0 || missing_mask == 0) return 0;
    /*
     * The split path pays an extra command stage and a second routed-expert
     * bind.  It is worthwhile when several experts are missing and their SSD
     * reads can be hidden by resident expert work.  With one or two misses,
     * especially in large caches, a single unsplit routed pass is faster.
     */
    return ds4_gpu_stream_expert_popcount(missing_mask) >= 3u;
}

static void ds4_gpu_stream_expert_timing_note_selected(
        double sync_ms,
        double copy_ms,
        double bind_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_selected_calls++;
    g_stream_expert_timing_selected_sync_ms += sync_ms;
    g_stream_expert_timing_selected_copy_ms += copy_ms;
    g_stream_expert_timing_selected_read_ms += sync_ms + copy_ms;
    g_stream_expert_timing_selected_bind_ms += bind_ms;
}

static void ds4_gpu_stream_expert_timing_note_overlap_route(
        double wait_ms,
        double copy_ms,
        double plan_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_overlap_route_calls++;
    g_stream_expert_timing_overlap_route_wait_ms += wait_ms;
    g_stream_expert_timing_overlap_route_copy_ms += copy_ms;
    g_stream_expert_timing_overlap_route_plan_ms += plan_ms;
}

static void ds4_gpu_stream_expert_timing_note_overlap_finish(
        double publish_ms,
        double wait_ms,
        double modify_ms,
        double install_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_overlap_finish_calls++;
    g_stream_expert_timing_overlap_finish_publish_ms += publish_ms;
    g_stream_expert_timing_overlap_finish_wait_ms += wait_ms;
    g_stream_expert_timing_overlap_finish_modify_ms += modify_ms;
    g_stream_expert_timing_overlap_finish_install_ms += install_ms;
}

static void ds4_gpu_stream_expert_timing_note_split(
        uint32_t resident_mask,
        uint32_t missing_mask,
        double   resident_ms,
        double   missing_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_split_layers++;
    g_stream_expert_timing_split_resident_experts +=
        ds4_gpu_stream_expert_popcount(resident_mask);
    g_stream_expert_timing_split_missing_experts +=
        ds4_gpu_stream_expert_popcount(missing_mask);
    g_stream_expert_timing_split_resident_ms += resident_ms;
    g_stream_expert_timing_split_missing_ms += missing_ms;
}

static void ds4_gpu_stream_expert_timing_note_split_missing_detail(
        double load_ms,
        double slot_ms,
        double prune_ms,
        double addr_ms,
        double wait_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_split_missing_load_ms += load_ms;
    g_stream_expert_timing_split_missing_slot_ms += slot_ms;
    g_stream_expert_timing_split_missing_prune_ms += prune_ms;
    g_stream_expert_timing_split_missing_addr_ms += addr_ms;
    g_stream_expert_timing_split_missing_wait_ms += wait_ms;
}

static void ds4_gpu_stream_expert_timing_note_load_detail(
        double prepare_ms,
        double pread_ms,
        double modify_ms,
        double install_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_load_calls++;
    g_stream_expert_timing_load_prepare_ms += prepare_ms;
    g_stream_expert_timing_load_pread_ms += pread_ms;
    g_stream_expert_timing_load_modify_ms += modify_ms;
    g_stream_expert_timing_load_install_ms += install_ms;
}

static void ds4_gpu_stream_expert_timing_note_prepare_batch_reuse(double ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_batch_reuse_calls++;
    g_stream_expert_timing_prepare_batch_reuse_ms += ms;
}

