    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_buffer_calls++;
    g_stream_expert_timing_prepare_buffer_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_prepare_task(
        uint32_t experts,
        double   ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_task_experts += experts;
    g_stream_expert_timing_prepare_task_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_reuse_scan(
        uint64_t entries,
        double   ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_reuse_scan_calls++;
    g_stream_expert_timing_reuse_scan_entries += entries;
    g_stream_expert_timing_reuse_scan_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_reuse_clear(double ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_reuse_clear_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_cache_class(
        uint32_t resident_mask,
        uint32_t missing_mask) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    const uint32_t resident = ds4_gpu_stream_expert_popcount(resident_mask);
    const uint32_t missing = ds4_gpu_stream_expert_popcount(missing_mask);
    if (missing == 0) {
        g_stream_expert_timing_cache_all_resident_layers++;
    } else if (resident == 0) {
        g_stream_expert_timing_cache_all_missing_layers++;
    } else {
        g_stream_expert_timing_cache_mixed_layers++;
    }
    g_stream_expert_timing_cache_resident_experts += resident;
    g_stream_expert_timing_cache_missing_experts += missing;
}

static int ds4_gpu_stream_expert_readahead_enabled(void) {
    return g_ssd_streaming_mode && g_streaming_expert_readahead_mode;
}

static void ds4_gpu_stream_expert_readahead_range(uint64_t offset, uint64_t len) {
    if (!ds4_gpu_stream_expert_readahead_enabled() || len == 0) {
        return;
    }

    int source_fd = g_model_fd;
    uint64_t source_offset = offset;
    const int resolved = ds4_gpu_qwen35_expert_pack_resolve(
        offset, len, &source_fd, &source_offset);
    /* Readahead is advisory, so an unmappable active-pack request is simply
     * not advised here. The authoritative pread below rejects the same request
     * and cannot fall through to the GGUF descriptor. */
    if (resolved < 0 || source_fd < 0) return;

#if defined(F_RDADVISE)
    const int timing = ds4_gpu_stream_expert_timing_summary_enabled();
    const double t0 = timing ? ds4_gpu_now_ms() : 0.0;
    uint64_t pos = source_offset;
    uint64_t rem = len;
    while (rem > 0) {
        const uint64_t chunk64 =
            rem > (uint64_t)INT_MAX ? (uint64_t)INT_MAX : rem;
        if (pos > (uint64_t)LLONG_MAX) break;

        struct radvisory ra;
        ra.ra_offset = (off_t)pos;
        ra.ra_count = (int)chunk64;
        (void)fcntl(source_fd, F_RDADVISE, &ra);

        pos += chunk64;
        rem -= chunk64;
    }
    if (timing) {
        g_stream_expert_timing_readahead_calls++;
        g_stream_expert_timing_readahead_bytes += len;
        g_stream_expert_timing_readahead_ms += ds4_gpu_now_ms() - t0;
    }
#else
    (void)offset;
    (void)len;
#endif
}

typedef struct {
    uint64_t offset;
    uint64_t len;
    uint8_t *dst;
    int source_fd;
    uint64_t source_offset;
    uint8_t direct_source;
    uint64_t read_bytes;
    uint64_t successful_syscalls;
    double ms;
    int ok;
} ds4_gpu_stream_expert_pread_task;

typedef enum {
    DS4_GPU_STREAM_EXPERT_RECORD_COMPONENTS = 0,
    DS4_GPU_STREAM_EXPERT_RECORD_FULL,
    DS4_GPU_STREAM_EXPERT_RECORD_BALANCED3,
    HEBRUS_GPU_STREAM_EXPERT_RECORD_PAIRED2,
} ds4_gpu_stream_expert_record_read_mode;

static int ds4_gpu_stream_expert_coalesced_record_pread_enabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        enabled = getenv("DS4_METAL_ENABLE_COALESCED_EXPERT_RECORD_PREAD") != NULL;
    }
    return enabled;
}

static int ds4_gpu_stream_expert_glm_full_record_default(void) {
    /*
     * GLM ExpertMajor v2 has 11.81 MiB records and its qualified decode path
     * uses one contiguous pread per missing expert.  Keep that distinction
     * explicit instead of applying another model's I/O policy to every
     * embedded-v2 store.
     */
    return g_glm_model_mode &&
           g_qwen35_expert_pack.active &&
           g_qwen35_expert_pack.embedded_v2;
}

static int hebrus_gpu_stream_expert_qwen35_model_value(
        int      glm_model,
        int      active,
        int      embedded_v2,
        uint32_t n_layer,
        uint32_t n_expert) {
    return !glm_model && active && embedded_v2 &&
           n_layer == QWEN35_N_LAYER &&
           n_expert == QWEN35_N_EXPERT;
}

static int hebrus_gpu_stream_expert_qwen35_model(void) {
    return hebrus_gpu_stream_expert_qwen35_model_value(
        g_glm_model_mode,
        g_qwen35_expert_pack.active,
        g_qwen35_expert_pack.embedded_v2,
        g_qwen35_expert_pack.n_layer,
        g_qwen35_expert_pack.n_expert);
}

static ds4_gpu_stream_expert_record_read_mode
ds4_gpu_stream_expert_record_read_plan(void) {
    if (ds4_gpu_stream_expert_coalesced_record_pread_enabled() ||
        ds4_gpu_stream_expert_glm_full_record_default()) {
        return DS4_GPU_STREAM_EXPERT_RECORD_FULL;
    }
    /*
     * Qwen's 1.30 MiB ExpertMajor v2 records benefit from joining gate+up:
     * clean 2K/8K A/B/B/A cohorts cut pread syscall count by one third and
     * improved end-to-end time by 7.78%/4.10%.  DeepSeek's 6.75 MiB records
     * made the larger reads 8.68%/10.37% slower inside pread and regressed
     * end-to-end time by 0.44%/0.40%, so retain its three-way parallel plan.
     */
    if (hebrus_gpu_stream_expert_qwen35_model()) {
        return HEBRUS_GPU_STREAM_EXPERT_RECORD_PAIRED2;
    }
    /* Environment policy is immutable after process startup, like the
     * coalesced mode above.  Cache it so every expert/task planning call does
     * not add two libc getenv scans to the default SSD hot path. */
    static int balanced_enabled = -1;
    if (balanced_enabled < 0) {
        balanced_enabled =
            getenv("DS4_METAL_ENABLE_BALANCED_EXPERT_RECORD_PREAD") != NULL &&
            getenv("DS4_METAL_DISABLE_BALANCED_EXPERT_RECORD_PREAD") == NULL;
    }
    if (balanced_enabled) {
        return DS4_GPU_STREAM_EXPERT_RECORD_BALANCED3;
    }
    return DS4_GPU_STREAM_EXPERT_RECORD_COMPONENTS;
}

static int ds4_gpu_stream_expert_append_record_tasks(
        ds4_gpu_stream_expert_pread_task *tasks,
        uint32_t                         capacity,
        uint32_t                        *n_tasks,
        uint64_t                         gate_offset,
        uint64_t                         up_offset,
        uint64_t                         down_offset,
        uint64_t                         gate_bytes,
        uint64_t                         down_bytes,
        uint8_t                         *gate_dst,
        uint8_t                         *up_dst,
        uint8_t                         *down_dst,
        ds4_gpu_stream_expert_record_read_mode record_mode) {
    if (!tasks || !n_tasks || !gate_dst || !up_dst || !down_dst) return 0;
    int source_fd = -1;
    uint64_t source_offset = 0;
    uint64_t record_bytes = 0;
    const int record =
        record_mode != DS4_GPU_STREAM_EXPERT_RECORD_COMPONENTS ?
        ds4_gpu_expert_store_v2_resolve_record(
            gate_offset, up_offset, down_offset, gate_bytes, down_bytes,
            &source_fd, &source_offset, &record_bytes) : 0;
    const bool contiguous_dst =
        up_dst == gate_dst + gate_bytes &&
        down_dst == up_dst + gate_bytes;
    if (record < 0) return 0;
    if (record == 1 && contiguous_dst &&
        record_mode == DS4_GPU_STREAM_EXPERT_RECORD_FULL) {
        if (*n_tasks >= capacity) return 0;
        tasks[(*n_tasks)++] = (ds4_gpu_stream_expert_pread_task) {
            .offset = gate_offset,
            .len = record_bytes,
            .dst = gate_dst,
            .source_fd = source_fd,
            .source_offset = source_offset,
            .direct_source = 1,
        };
        return 1;
    }
    if (record == 1 && contiguous_dst &&
        record_mode == DS4_GPU_STREAM_EXPERT_RECORD_BALANCED3 &&
        record_bytes >= 3u) {
        if (*n_tasks > capacity || capacity - *n_tasks < 3u) return 0;
        const uint64_t chunk_bytes = record_bytes / 3u;
        const uint64_t extra_bytes = record_bytes % 3u;
        for (uint32_t chunk = 0; chunk < 3u; chunk++) {
            const uint64_t begin =
                chunk_bytes * chunk +
                (chunk < extra_bytes ? chunk : extra_bytes);
            const uint64_t next = chunk + 1u;
            const uint64_t end =
                chunk_bytes * next +
                (next < extra_bytes ? next : extra_bytes);
            if (end <= begin || gate_offset > UINT64_MAX - begin ||
                source_offset > UINT64_MAX - begin) {
                return 0;
            }
            tasks[(*n_tasks)++] = (ds4_gpu_stream_expert_pread_task) {
                .offset = gate_offset + begin,
                .len = end - begin,
                .dst = gate_dst + begin,
                .source_fd = source_fd,
                .source_offset = source_offset + begin,
                .direct_source = 1,
            };
        }
        return 1;
    }
    if (record == 1 && contiguous_dst &&
        record_mode == HEBRUS_GPU_STREAM_EXPERT_RECORD_PAIRED2) {
        if (*n_tasks > capacity || capacity - *n_tasks < 2u ||
            gate_bytes > UINT64_MAX - gate_bytes ||
            source_offset > UINT64_MAX - gate_bytes * 2u) {
            return 0;
        }
        tasks[(*n_tasks)++] = (ds4_gpu_stream_expert_pread_task) {
            .offset = gate_offset,
            .len = gate_bytes * 2u,
            .dst = gate_dst,
            .source_fd = source_fd,
            .source_offset = source_offset,
            .direct_source = 1,
        };
        tasks[(*n_tasks)++] = (ds4_gpu_stream_expert_pread_task) {
            .offset = down_offset,
            .len = down_bytes,
            .dst = down_dst,
            .source_fd = source_fd,
            .source_offset = source_offset + gate_bytes * 2u,
            .direct_source = 1,
        };
        return 1;
    }
    if (*n_tasks > capacity || capacity - *n_tasks < 3u) return 0;
    tasks[(*n_tasks)++] = (ds4_gpu_stream_expert_pread_task) {
        .offset = gate_offset, .len = gate_bytes, .dst = gate_dst,
    };
    tasks[(*n_tasks)++] = (ds4_gpu_stream_expert_pread_task) {
        .offset = up_offset, .len = gate_bytes, .dst = up_dst,
    };
    tasks[(*n_tasks)++] = (ds4_gpu_stream_expert_pread_task) {
        .offset = down_offset, .len = down_bytes, .dst = down_dst,
    };
    return 1;
}

