typedef struct {
    ds4_gpu_stream_expert_pread_task *tasks;
    uint32_t n_tasks;
    uint32_t worker_index;
    uint32_t n_workers;
} ds4_gpu_stream_expert_pread_worker_args;

static void ds4_gpu_stream_expert_counter_add(
        uint64_t *counter,
        uint64_t delta) {
    if (!counter) return;
    *counter = *counter > UINT64_MAX - delta ?
        UINT64_MAX : *counter + delta;
}

static uint64_t ds4_gpu_stream_expert_pread_successful_syscalls(
        const ds4_gpu_stream_expert_pread_task *tasks,
        uint32_t n_tasks) {
    uint64_t total = 0;
    if (!tasks) return 0;
    for (uint32_t i = 0; i < n_tasks; i++) {
        total = total > UINT64_MAX - tasks[i].successful_syscalls ?
            UINT64_MAX : total + tasks[i].successful_syscalls;
    }
    return total;
}

static void ds4_gpu_stream_expert_cache_note_pread(
        uint32_t layer,
        uint64_t completed_expert_loads,
        uint64_t successful_syscalls,
        uint64_t bytes,
        double   ms) {
    /* Expert loads and OS activity are intentionally distinct. The production
     * loader completes one logical record with three parallel spans; a native
     * diagnostic may coalesce them. Every partial pread that returned bytes is
     * still a real syscall. Saturation preserves monotonic campaign deltas over
     * arbitrarily long server lifetimes. */
    ds4_gpu_stream_expert_counter_add(
        &g_stream_expert_cache_expert_loads, completed_expert_loads);
    ds4_gpu_stream_expert_counter_add(
        &g_stream_expert_cache_pread_syscalls, successful_syscalls);
    ds4_gpu_stream_expert_counter_add(
        &g_stream_expert_cache_pread_bytes, bytes);
    g_stream_expert_cache_pread_ms += ms;
    if (layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) {
        if (g_stream_expert_cache_layer_pread_bytes[layer] > UINT64_MAX - bytes) {
            g_stream_expert_cache_layer_pread_bytes[layer] = UINT64_MAX;
        } else {
            g_stream_expert_cache_layer_pread_bytes[layer] += bytes;
        }
        g_stream_expert_cache_layer_pread_ms[layer] += ms;
    }
}

static uint32_t ds4_gpu_stream_expert_pread_thread_limit(void) {
    uint32_t threads = 9;
    const char *env = getenv("DS4_METAL_STREAMING_EXPERT_PREAD_THREADS");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long v = strtoul(env, &end, 10);
        if (end != env && *end == '\0') {
            threads = v > UINT32_MAX ? UINT32_MAX : (uint32_t)v;
        }
    }
    if (threads == 0) threads = 1;
    if (threads > 18) threads = 18;
    return threads;
}

static uint32_t ds4_gpu_stream_expert_pread_thread_count(uint32_t n_tasks) {
    if (n_tasks <= 1) return n_tasks;
    uint32_t threads = ds4_gpu_stream_expert_pread_thread_limit();
    if (threads > n_tasks) threads = n_tasks;
    return threads;
}

static int ds4_gpu_stream_expert_pread_source_into(
        uint64_t  canonical_offset,
        int       source_fd,
        uint64_t  source_offset,
        uint64_t  len,
        uint8_t  *dst,
        uint64_t *read_bytes,
        uint64_t *successful_syscalls,
        double   *ms_out) {
    if (read_bytes) *read_bytes = 0;
    if (successful_syscalls) *successful_syscalls = 0;
    if (ms_out) *ms_out = 0.0;
    if (!dst || len == 0) {
        return 0;
    }

    if (source_fd < 0 ||
        source_offset > (uint64_t)LLONG_MAX ||
        len > (uint64_t)LLONG_MAX - source_offset) {
        return 0;
    }

    const double t0 = ds4_gpu_now_ms();
    uint64_t pos = 0;
    uint64_t syscalls = 0;
    int ok = 1;
    while (pos < len) {
        const uint64_t rem = len - pos;
        const size_t want = rem > (uint64_t)SSIZE_MAX ? (size_t)SSIZE_MAX : (size_t)rem;
        ssize_t nread;
        do {
            nread = pread(source_fd,
                          dst + pos,
                          want,
                          (off_t)(source_offset + pos));
        } while (nread < 0 && errno == EINTR);
        if (nread <= 0) {
            ok = 0;
            break;
        }
        if (syscalls != UINT64_MAX) syscalls++;
        pos += (uint64_t)nread;
    }
    const double dt = ds4_gpu_now_ms() - t0;
    if (read_bytes) *read_bytes = pos;
    if (successful_syscalls) *successful_syscalls = syscalls;
    if (ms_out) *ms_out = dt;
    if (!ok || pos != len) {
        fprintf(stderr,
                "ds4: Metal streaming expert explicit pread failed canonical=%.2f GiB source=%.2f GiB len=%.2f MiB read=%.2f MiB\n",
                ds4_gpu_gib(canonical_offset),
                ds4_gpu_gib(source_offset),
                ds4_gpu_mib(len),
                ds4_gpu_mib(pos));
        return 0;
    }
    return 1;
}

static int ds4_gpu_stream_expert_pread_into(
        uint64_t  offset,
        uint64_t  len,
        uint8_t  *dst,
        uint64_t *read_bytes,
        uint64_t *successful_syscalls,
        double   *ms_out) {
    int source_fd = g_model_fd;
    uint64_t source_offset = offset;
    const int resolved = ds4_gpu_qwen35_expert_pack_resolve(
        offset, len, &source_fd, &source_offset);
    if (resolved < 0) {
        /* Once installed, the pack is a strict model contract. Falling back to
         * the old GGUF layout here would make corruption look like a harmless
         * performance miss and could mix bytes from two different layouts. */
        fprintf(stderr,
                "ds4: Metal expert pack rejected unmappable canonical read offset=%llu len=%llu\n",
                (unsigned long long)offset,
                (unsigned long long)len);
        return 0;
    }
    return ds4_gpu_stream_expert_pread_source_into(
        offset, source_fd, source_offset, len, dst,
        read_bytes, successful_syscalls, ms_out);
}

static int ds4_gpu_stream_expert_pread_task_run(
        ds4_gpu_stream_expert_pread_task *task) {
    if (!task) return 0;
    if (task->direct_source) {
        return ds4_gpu_stream_expert_pread_source_into(
            task->offset, task->source_fd, task->source_offset,
            task->len, task->dst, &task->read_bytes,
            &task->successful_syscalls, &task->ms);
    }
    return ds4_gpu_stream_expert_pread_into(
        task->offset, task->len, task->dst, &task->read_bytes,
        &task->successful_syscalls, &task->ms);
}

static void *ds4_gpu_stream_expert_pread_worker(void *arg) {
    ds4_gpu_stream_expert_pread_worker_args *wa =
        (ds4_gpu_stream_expert_pread_worker_args *)arg;
    for (uint32_t i = wa->worker_index; i < wa->n_tasks; i += wa->n_workers) {
        ds4_gpu_stream_expert_pread_task *task = &wa->tasks[i];
        task->ok = ds4_gpu_stream_expert_pread_task_run(task);
    }
    return NULL;
}

static pthread_mutex_t g_stream_expert_pread_pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_stream_expert_pread_pool_start_cond = PTHREAD_COND_INITIALIZER;
static pthread_cond_t g_stream_expert_pread_pool_done_cond = PTHREAD_COND_INITIALIZER;
static pthread_t g_stream_expert_pread_pool_threads[18];
static uint32_t g_stream_expert_pread_pool_thread_count;
static uint32_t g_stream_expert_pread_pool_active_workers;
static uint32_t g_stream_expert_pread_pool_remaining_workers;
static uint32_t g_stream_expert_pread_pool_n_tasks;
static uint32_t g_stream_expert_pread_pool_next_task;
static uint64_t g_stream_expert_pread_pool_generation;
static double g_stream_expert_pread_pool_done_ms;
static ds4_gpu_stream_expert_pread_task *g_stream_expert_pread_pool_tasks;
static int g_stream_expert_pread_pool_initialized;
static int g_stream_expert_pread_pool_stopping;

static int ds4_gpu_stream_expert_pread_pool_enabled(void) {
    const char *env = getenv("DS4_METAL_STREAMING_EXPERT_PREAD_POOL");
    return !(env && strcmp(env, "0") == 0);
}

static void *ds4_gpu_stream_expert_pread_pool_worker(void *arg) {
    const uint32_t worker_index = (uint32_t)(uintptr_t)arg;
    uint64_t seen_generation = 0;

    for (;;) {
        pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
        while (!g_stream_expert_pread_pool_stopping &&
               g_stream_expert_pread_pool_generation == seen_generation) {
            pthread_cond_wait(&g_stream_expert_pread_pool_start_cond,
                              &g_stream_expert_pread_pool_mutex);
        }
        if (g_stream_expert_pread_pool_stopping) {
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
            break;
        }

        seen_generation = g_stream_expert_pread_pool_generation;
        if (worker_index >= g_stream_expert_pread_pool_active_workers) {
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
            continue;
        }

        for (;;) {
            const uint32_t task_index =
                g_stream_expert_pread_pool_next_task++;
            if (task_index >= g_stream_expert_pread_pool_n_tasks) break;

            ds4_gpu_stream_expert_pread_task *task =
                &g_stream_expert_pread_pool_tasks[task_index];
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);

            task->ok = ds4_gpu_stream_expert_pread_task_run(task);

            pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
        }

        if (g_stream_expert_pread_pool_remaining_workers > 0 &&
            --g_stream_expert_pread_pool_remaining_workers == 0) {
            g_stream_expert_pread_pool_done_ms = ds4_gpu_now_ms();
            g_stream_expert_pread_pool_tasks = NULL;
            g_stream_expert_pread_pool_n_tasks = 0;
            g_stream_expert_pread_pool_active_workers = 0;
            pthread_cond_signal(&g_stream_expert_pread_pool_done_cond);
        }
        pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
    }

    return NULL;
}

static int ds4_gpu_stream_expert_pread_pool_init(uint32_t n_threads) {
    if (g_stream_expert_pread_pool_initialized) return 1;
    if (!ds4_gpu_stream_expert_pread_pool_enabled() || n_threads <= 1) return 0;
    if (n_threads > 18) n_threads = 18;

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    g_stream_expert_pread_pool_thread_count = n_threads;
    g_stream_expert_pread_pool_stopping = 0;
    g_stream_expert_pread_pool_generation = 0;
    g_stream_expert_pread_pool_done_ms = 0.0;
    g_stream_expert_pread_pool_tasks = NULL;
    g_stream_expert_pread_pool_n_tasks = 0;
    g_stream_expert_pread_pool_next_task = 0;
    g_stream_expert_pread_pool_active_workers = 0;
    g_stream_expert_pread_pool_remaining_workers = 0;
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);

    uint32_t started = 0;
    for (uint32_t i = 0; i < n_threads; i++) {
        const int rc = pthread_create(&g_stream_expert_pread_pool_threads[i],
                                      NULL,
                                      ds4_gpu_stream_expert_pread_pool_worker,
                                      (void *)(uintptr_t)i);
        if (rc != 0) {
            fprintf(stderr,
                    "ds4: Metal streaming expert pread pool thread creation failed: %s\n",
                    strerror(rc));
            pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
            g_stream_expert_pread_pool_stopping = 1;
            g_stream_expert_pread_pool_generation++;
            pthread_cond_broadcast(&g_stream_expert_pread_pool_start_cond);
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
            for (uint32_t j = 0; j < started; j++) {
                (void)pthread_join(g_stream_expert_pread_pool_threads[j], NULL);
            }
            pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
            g_stream_expert_pread_pool_thread_count = 0;
            g_stream_expert_pread_pool_stopping = 0;
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
            return 0;
        }
        started++;
    }

    g_stream_expert_pread_pool_initialized = 1;
    return 1;
}

static int ds4_gpu_stream_expert_pread_pool_begin(
        ds4_gpu_stream_expert_pread_task *tasks,
        uint32_t n_tasks,
        uint32_t n_workers) {
    if (n_workers <= 1) return 0;
    const uint32_t limit = ds4_gpu_stream_expert_pread_thread_limit();
    if (!ds4_gpu_stream_expert_pread_pool_init(limit)) return 0;

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    if (!g_stream_expert_pread_pool_initialized ||
        g_stream_expert_pread_pool_stopping ||
        g_stream_expert_pread_pool_thread_count == 0) {
        pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
        return 0;
    }
    if (n_workers > g_stream_expert_pread_pool_thread_count) {
        n_workers = g_stream_expert_pread_pool_thread_count;
    }
    if (n_workers == 0) {
        pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
        return 0;
    }

    if (g_stream_expert_pread_pool_remaining_workers != 0 ||
        g_stream_expert_pread_pool_tasks != NULL) {
        pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
        return 0;
    }

    g_stream_expert_pread_pool_tasks = tasks;
    g_stream_expert_pread_pool_n_tasks = n_tasks;
    g_stream_expert_pread_pool_next_task = 0;
    g_stream_expert_pread_pool_active_workers = n_workers;
    g_stream_expert_pread_pool_remaining_workers = n_workers;
    g_stream_expert_pread_pool_done_ms = 0.0;
    g_stream_expert_pread_pool_generation++;
    pthread_cond_broadcast(&g_stream_expert_pread_pool_start_cond);
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
    return 1;
}

static int ds4_gpu_stream_expert_pread_pool_wait(void) {
    if (!g_stream_expert_pread_pool_initialized) return 0;

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    while (g_stream_expert_pread_pool_remaining_workers != 0) {
        pthread_cond_wait(&g_stream_expert_pread_pool_done_cond,
                          &g_stream_expert_pread_pool_mutex);
    }
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
    return 1;
}

static double ds4_gpu_stream_expert_pread_pool_elapsed_ms(double start_ms) {
    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    const double done_ms = g_stream_expert_pread_pool_done_ms;
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
    return done_ms >= start_ms ? done_ms - start_ms :
                                 ds4_gpu_now_ms() - start_ms;
}

static int ds4_gpu_stream_expert_pread_pool_dispatch(
        ds4_gpu_stream_expert_pread_task *tasks,
        uint32_t n_tasks,
        uint32_t n_workers) {
    if (!ds4_gpu_stream_expert_pread_pool_begin(tasks, n_tasks, n_workers)) {
        return 0;
    }
    return ds4_gpu_stream_expert_pread_pool_wait();
}

static void ds4_gpu_stream_expert_pread_pool_shutdown(void) {
    if (!g_stream_expert_pread_pool_initialized) return;

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    g_stream_expert_pread_pool_stopping = 1;
    g_stream_expert_pread_pool_generation++;
    pthread_cond_broadcast(&g_stream_expert_pread_pool_start_cond);
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);

    const uint32_t n_threads = g_stream_expert_pread_pool_thread_count;
    for (uint32_t i = 0; i < n_threads; i++) {
        (void)pthread_join(g_stream_expert_pread_pool_threads[i], NULL);
    }

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    g_stream_expert_pread_pool_thread_count = 0;
    g_stream_expert_pread_pool_active_workers = 0;
    g_stream_expert_pread_pool_remaining_workers = 0;
    g_stream_expert_pread_pool_n_tasks = 0;
    g_stream_expert_pread_pool_next_task = 0;
    g_stream_expert_pread_pool_done_ms = 0.0;
    g_stream_expert_pread_pool_tasks = NULL;
    g_stream_expert_pread_pool_initialized = 0;
    g_stream_expert_pread_pool_stopping = 0;
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
}

static int ds4_gpu_stream_expert_pread_tasks(
        ds4_gpu_stream_expert_pread_task *tasks,
        uint32_t n_tasks,
        uint64_t *total_bytes,
        double *wall_ms) {
    if (total_bytes) *total_bytes = 0;
    if (wall_ms) *wall_ms = 0.0;
    if (!tasks || n_tasks == 0) return 1;

    const uint32_t n_workers =
        ds4_gpu_stream_expert_pread_thread_count(n_tasks);
    const double t0 = ds4_gpu_now_ms();
    int ok = 1;
    if (n_workers <= 1) {
        ds4_gpu_stream_expert_pread_worker_args wa = {
            .tasks = tasks,
            .n_tasks = n_tasks,
            .worker_index = 0,
            .n_workers = 1,
        };
        (void)ds4_gpu_stream_expert_pread_worker(&wa);
    } else if (!ds4_gpu_stream_expert_pread_pool_dispatch(tasks,
                                                          n_tasks,
                                                          n_workers)) {
        pthread_t threads[18];
        ds4_gpu_stream_expert_pread_worker_args args[18];
        uint32_t started = 0;
        for (uint32_t i = 0; i < n_workers; i++) {
            args[i].tasks = tasks;
            args[i].n_tasks = n_tasks;
            args[i].worker_index = i;
            args[i].n_workers = n_workers;
            const int rc = pthread_create(&threads[i],
                                          NULL,
                                          ds4_gpu_stream_expert_pread_worker,
                                          &args[i]);
            if (rc != 0) {
                fprintf(stderr,
                        "ds4: Metal streaming expert pread thread creation failed: %s\n",
                        strerror(rc));
                ok = 0;
                break;
            }
            started++;
        }
        for (uint32_t i = 0; i < started; i++) {
            if (pthread_join(threads[i], NULL) != 0) ok = 0;
        }
    }
    const double dt = ds4_gpu_now_ms() - t0;

    uint64_t bytes = 0;
    for (uint32_t i = 0; i < n_tasks; i++) {
        if (!tasks[i].ok) ok = 0;
        if (bytes > UINT64_MAX - tasks[i].read_bytes) {
            bytes = UINT64_MAX;
        } else {
            bytes += tasks[i].read_bytes;
        }
    }
    if (total_bytes) *total_bytes = bytes;
    if (wall_ms) *wall_ms = dt;
    return ok;
}

static void ds4_gpu_stream_expert_cache_warn_mlock_failure(
        uint64_t failed_len,
        int      err) {
    if (g_stream_expert_cache_mlock_warned) return;
    g_stream_expert_cache_mlock_warned = 1;

    const uint64_t gib = 1024ull * 1024ull * 1024ull;
    const uint32_t budget = ds4_gpu_stream_expert_cache_requested_budget();
    uint64_t requested = 0;
    if (budget != 0 && g_stream_expert_cache_expert_bytes != 0) {
        requested =
            budget > UINT64_MAX / g_stream_expert_cache_expert_bytes ?
                UINT64_MAX :
                (uint64_t)budget * g_stream_expert_cache_expert_bytes;
    }

    uint64_t suggested_gib = g_stream_expert_cache_mlock_bytes / gib;
    if (suggested_gib > 1) suggested_gib--;

    fprintf(stderr,
            "ds4: warning: streaming expert cache could not mlock all buffers\n");
    if (requested != 0) {
        fprintf(stderr,
                "ds4:   requested cache: %u experts / %.2f GiB\n",
                budget,
                ds4_gpu_gib(requested));
    } else {
        fprintf(stderr,
                "ds4:   requested cache: %u experts\n",
                budget);
    }
    fprintf(stderr,
            "ds4:   locked so far:   %.2f GiB\n",
            ds4_gpu_gib(g_stream_expert_cache_mlock_bytes));
    fprintf(stderr,
            "ds4:   failed buffer:   %.2f MiB (%s)\n",
            ds4_gpu_mib(failed_len),
            err != 0 ? strerror(err) : "mlock unavailable");
    fprintf(stderr,
            "ds4:   macOS may page unlocked expert buffers, causing poor or unstable speed\n");
    if (g_stream_expert_cache_mlock_budget_cap_active &&
        g_stream_expert_cache_expert_bytes != 0) {
        const uint64_t capped_bytes =
            g_stream_expert_cache_mlock_budget_cap >
                UINT64_MAX / g_stream_expert_cache_expert_bytes ?
                    UINT64_MAX :
                    (uint64_t)g_stream_expert_cache_mlock_budget_cap *
                        g_stream_expert_cache_expert_bytes;
        fprintf(stderr,
                "ds4:   using locked cache cap: %u experts / %.2f GiB\n",
                g_stream_expert_cache_mlock_budget_cap,
                ds4_gpu_gib(capped_bytes));
    }
    if (suggested_gib != 0) {
        fprintf(stderr,
                "ds4:   try: --ssd-streaming-cache-experts %" PRIu64 "GB\n",
                suggested_gib);
    } else {
        fprintf(stderr,
                "ds4:   try a smaller --ssd-streaming-cache-experts NGB budget\n");
    }
}

static uint32_t ds4_gpu_stream_expert_slab_locked_slot_count(void) {
    uint32_t count = 0;
    uint32_t total = g_stream_expert_cache_slab_total_slots;
    if (total > DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        total = DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES;
    }
    for (uint32_t slot = 0; slot < total; slot++) {
        if (g_stream_expert_cache_slab_slot_locked[slot]) count++;
    }
    return count;
}

static void ds4_gpu_stream_expert_cache_cap_budget_to_locked(void) {
    uint32_t cap = g_stream_expert_cache_entry_count;
    const uint32_t locked_slots = ds4_gpu_stream_expert_slab_locked_slot_count();
    if (locked_slots != 0 && locked_slots < cap) cap = locked_slots;
    const uint64_t gib = 1024ull * 1024ull * 1024ull;
    uint64_t safe_gib = g_stream_expert_cache_mlock_bytes / gib;
    if (safe_gib > 1) safe_gib--;
    if (safe_gib != 0 && g_stream_expert_cache_expert_bytes != 0) {
        uint64_t safe_bytes =
            safe_gib > UINT64_MAX / gib ? UINT64_MAX : safe_gib * gib;
        uint64_t safe_cap64 = safe_bytes / g_stream_expert_cache_expert_bytes;
        if (safe_cap64 > UINT32_MAX) safe_cap64 = UINT32_MAX;
        if (safe_cap64 != 0 && safe_cap64 < cap) {
            cap = (uint32_t)safe_cap64;
        }
    }
    if (!g_stream_expert_cache_mlock_budget_cap_active ||
        cap < g_stream_expert_cache_mlock_budget_cap) {
        g_stream_expert_cache_mlock_budget_cap = cap;
    }
    g_stream_expert_cache_mlock_budget_cap_active = 1;
    ds4_gpu_dspark_support_cache_target_cap_changed();
}

static int ds4_gpu_stream_expert_cache_mlock(void *ptr, size_t len) {
    if (g_stream_expert_cache_test_mlock_fail_after >= 0) {
        if (g_stream_expert_cache_test_mlock_fail_after == 0) {
            g_stream_expert_cache_test_mlock_fail_after = -1;
            errno = ENOMEM;
            return -1;
        }
        g_stream_expert_cache_test_mlock_fail_after--;
    }
    return mlock(ptr, len);
}

static int ds4_gpu_stream_expert_cache_should_mlock(void) {
    /* GLM ExpertMajor is qualified on 64 GiB+ Metal hosts and keeps a small
     * explicit cache relative to available unified memory.  Wiring each new
     * 11.81 MiB slot adds measurable decode admission latency without helping
     * residency on that profile; Metal already retains every in-flight shared
     * buffer.  Other streamed models keep the pressure cap provided by mlock. */
    return !(g_glm_model_mode &&
             g_qwen35_expert_pack.active &&
             g_qwen35_expert_pack.embedded_v2);
}

static id<MTLBuffer> ds4_gpu_stream_expert_alloc_buffer(
        uint64_t  len,
        NSString *label) {
    if (!g_device ||
        len == 0 ||
        len > (uint64_t)NSUIntegerMax) {
        return nil;
    }

    id<MTLBuffer> buffer = [g_device newBufferWithLength:(NSUInteger)len
                                                 options:MTLResourceStorageModeShared];
    if (!buffer) {
        fprintf(stderr,
                "ds4: Metal streaming expert explicit buffer allocation failed (%.2f MiB)\n",
                ds4_gpu_mib(len));
        return nil;
    }
    buffer.label = label;
    g_stream_expert_cache_buffer_allocs++;
    if (g_ssd_streaming_mode &&
        ds4_gpu_stream_expert_cache_should_mlock()) {
        void *ptr = [buffer contents];
        const NSUInteger n = [buffer length];
        const double t0 = ds4_gpu_now_ms();
        if (ptr && n != 0 &&
            ds4_gpu_stream_expert_cache_mlock(ptr, (size_t)n) == 0) {
            const double dt = ds4_gpu_now_ms() - t0;
            g_stream_expert_cache_mlock_ms += dt;
            if (g_stream_expert_cache_mlock_bytes > UINT64_MAX - (uint64_t)n) {
                g_stream_expert_cache_mlock_bytes = UINT64_MAX;
            } else {
                g_stream_expert_cache_mlock_bytes += (uint64_t)n;
            }
        } else {
            const double dt = ds4_gpu_now_ms() - t0;
            g_stream_expert_cache_mlock_ms += dt;
            g_stream_expert_cache_mlock_failures++;
            if (g_stream_expert_cache_mlock_fail_bytes > UINT64_MAX - (uint64_t)n) {
                g_stream_expert_cache_mlock_fail_bytes = UINT64_MAX;
            } else {
                g_stream_expert_cache_mlock_fail_bytes += (uint64_t)n;
            }
            const int err = ptr && n != 0 ? errno : 0;
            ds4_gpu_stream_expert_cache_cap_budget_to_locked();
            ds4_gpu_stream_expert_cache_warn_mlock_failure((uint64_t)n, err);
            if (getenv("DS4_METAL_STREAMING_EXPERT_BUFFER_MLOCK_PROFILE") != NULL) {
                fprintf(stderr,
                        "ds4: Metal streaming expert buffer mlock failed len=%.2f MiB: %s\n",
                        ds4_gpu_mib((uint64_t)n),
                        err != 0 ? strerror(err) : "mlock unavailable");
            }
        }
    }
    return buffer;
}

static int ds4_gpu_stream_expert_combined_buffer_enabled(void) {
    return g_ssd_streaming_mode &&
           (g_stream_expert_cache_growth_guard_enabled ||
            getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_COMBINED_BUFFER") == NULL);
}

static int ds4_gpu_stream_expert_slab_enabled(void) {
    return ds4_gpu_stream_expert_combined_buffer_enabled() &&
           (g_stream_expert_cache_growth_guard_enabled ||
            getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_SLABS") == NULL);
}

/*
 * Large PRO caches otherwise create thousands of small shared Metal buffers.
 * Slabs keep the buffer object set small while locking pages only for slots
 * that actually hold a streamed expert.
 */
static uint64_t ds4_gpu_stream_expert_slab_target_bytes(void) {
    const uint64_t mib = 1024ull * 1024ull;
    uint64_t target = g_stream_expert_cache_slab_target_bytes_override != 0 ?
        g_stream_expert_cache_slab_target_bytes_override : 4096ull * mib;
    const char *env = g_stream_expert_cache_growth_guard_enabled ?
        NULL : getenv("DS4_METAL_STREAMING_EXPERT_SLAB_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env && *end == '\0' && v != 0) {
            target = v > UINT64_MAX / mib ? UINT64_MAX : (uint64_t)v * mib;
        }
    }
    return target;
}

static id<MTLBuffer> ds4_gpu_stream_expert_alloc_slab_buffer(
        uint64_t  len,
        NSString *label) {
    if (!g_device ||
        len == 0 ||
        len > (uint64_t)NSUIntegerMax) {
        return nil;
    }

    id<MTLBuffer> buffer = [g_device newBufferWithLength:(NSUInteger)len
                                                 options:MTLResourceStorageModeShared];
    if (!buffer) {
        fprintf(stderr,
                "ds4: Metal streaming expert slab allocation failed (%.2f MiB)\n",
                ds4_gpu_mib(len));
        return nil;
    }
    buffer.label = label;
    g_stream_expert_cache_buffer_allocs++;
    return buffer;
}

static int ds4_gpu_stream_expert_slab_slot_range(
        uint32_t slot,
        uint32_t *slab_index,
        uint64_t *slot_base) {
    for (uint32_t i = 0; i < g_stream_expert_cache_slab_count; i++) {
        const uint32_t start = g_stream_expert_cache_slab_start_slot[i];
        const uint32_t count = g_stream_expert_cache_slab_slot_count[i];
        if (slot < start || slot >= start + count) continue;
        if (slab_index) *slab_index = i;
        if (slot_base) {
            *slot_base =
                (uint64_t)(slot - start) * g_stream_expert_cache_slab_slot_bytes;
        }
        return 1;
    }
    return 0;
}

static int ds4_gpu_stream_expert_slab_slot_for_buffer(
        id<MTLBuffer> buffer,
        NSUInteger    gate_inner,
        uint32_t     *slot_out) {
    if (!buffer || g_stream_expert_cache_slab_slot_bytes == 0 || !slot_out) {
        return 0;
    }
    for (uint32_t i = 0; i < g_stream_expert_cache_slab_count; i++) {
        if (g_stream_expert_cache_slabs[i] != buffer) continue;
        const uint64_t inner = (uint64_t)gate_inner;
        const uint64_t slot_bytes = g_stream_expert_cache_slab_slot_bytes;
        if (slot_bytes == 0 || inner % slot_bytes != 0) return 0;
        const uint64_t local_slot = inner / slot_bytes;
        if (local_slot >= g_stream_expert_cache_slab_slot_count[i]) return 0;
        const uint64_t slot =
            (uint64_t)g_stream_expert_cache_slab_start_slot[i] + local_slot;
        if (slot > UINT32_MAX) return 0;
        *slot_out = (uint32_t)slot;
        return 1;
    }
    return 0;
}

static void ds4_gpu_stream_expert_slab_push_free_slot(uint32_t slot) {
    if (slot >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES ||
        g_stream_expert_cache_free_slot_count >=
            DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        return;
    }
    g_stream_expert_cache_free_slots[g_stream_expert_cache_free_slot_count++] =
        slot;
}

static int ds4_gpu_stream_expert_slab_lock_slot(uint32_t slot) {
    if (slot >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES ||
        g_stream_expert_cache_slab_slot_locked[slot]) {
        return 1;
    }
    if (!ds4_gpu_stream_expert_cache_should_mlock()) return 1;
    uint32_t slab = UINT32_MAX;
    uint64_t base = 0;
    if (!ds4_gpu_stream_expert_slab_slot_range(slot, &slab, &base) ||
        slab >= g_stream_expert_cache_slab_count ||
        !g_stream_expert_cache_slabs[slab] ||
        g_stream_expert_cache_slab_slot_bytes == 0 ||
        base > (uint64_t)NSUIntegerMax) {
        return 0;
    }

    void *contents = [g_stream_expert_cache_slabs[slab] contents];
    if (!contents) return 0;
    const double t0 = ds4_gpu_now_ms();
    void *ptr = (uint8_t *)contents + (NSUInteger)base;
    const size_t n = (size_t)g_stream_expert_cache_slab_slot_bytes;
    if (ds4_gpu_stream_expert_cache_mlock(ptr, n) == 0) {
        const double dt = ds4_gpu_now_ms() - t0;
        g_stream_expert_cache_mlock_ms += dt;
        if (g_stream_expert_cache_mlock_bytes >
            UINT64_MAX - g_stream_expert_cache_slab_slot_bytes) {
            g_stream_expert_cache_mlock_bytes = UINT64_MAX;
        } else {
            g_stream_expert_cache_mlock_bytes +=
                g_stream_expert_cache_slab_slot_bytes;
        }
        g_stream_expert_cache_slab_slot_locked[slot] = 1;
        return 1;
    }

    const double dt = ds4_gpu_now_ms() - t0;
    g_stream_expert_cache_mlock_ms += dt;
    g_stream_expert_cache_mlock_failures++;
    if (g_stream_expert_cache_mlock_fail_bytes >
        UINT64_MAX - g_stream_expert_cache_slab_slot_bytes) {
        g_stream_expert_cache_mlock_fail_bytes = UINT64_MAX;
    } else {
        g_stream_expert_cache_mlock_fail_bytes +=
            g_stream_expert_cache_slab_slot_bytes;
    }
    ds4_gpu_stream_expert_cache_cap_budget_to_locked();
    ds4_gpu_stream_expert_cache_warn_mlock_failure(
            g_stream_expert_cache_slab_slot_bytes,
            errno);
    return 0;
}

static int ds4_gpu_stream_expert_slab_unlock_slot(uint32_t slot) {
    if (slot >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES ||
        !g_stream_expert_cache_slab_slot_locked[slot]) {
        return 1;
    }
    uint32_t slab = UINT32_MAX;
    uint64_t base = 0;
    if (!ds4_gpu_stream_expert_slab_slot_range(slot, &slab, &base) ||
        slab >= g_stream_expert_cache_slab_count ||
        !g_stream_expert_cache_slabs[slab] ||
        g_stream_expert_cache_slab_slot_bytes == 0 ||
        base > (uint64_t)NSUIntegerMax) {
        return 0;
    }

    void *contents = [g_stream_expert_cache_slabs[slab] contents];
    if (!contents) return 0;
    void *ptr = (uint8_t *)contents + (NSUInteger)base;
    const size_t n = (size_t)g_stream_expert_cache_slab_slot_bytes;
    if (munlock(ptr, n) != 0) return 0;

    g_stream_expert_cache_slab_slot_locked[slot] = 0;
    if (g_stream_expert_cache_mlock_bytes >= g_stream_expert_cache_slab_slot_bytes) {
        g_stream_expert_cache_mlock_bytes -= g_stream_expert_cache_slab_slot_bytes;
    } else {
        g_stream_expert_cache_mlock_bytes = 0;
    }
    return 1;
}

static int ds4_gpu_stream_expert_slab_slot_buffers(
        uint32_t slot,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        __strong id<MTLBuffer> *gate_buf,
        __strong id<MTLBuffer> *up_buf,
        __strong id<MTLBuffer> *down_buf,
        NSUInteger *gate_inner,
        NSUInteger *up_inner,
        NSUInteger *down_inner) {
    uint32_t slab = UINT32_MAX;
    uint64_t base = 0;
    if (!ds4_gpu_stream_expert_slab_slot_range(slot, &slab, &base) ||
        slab >= g_stream_expert_cache_slab_count ||
        !g_stream_expert_cache_slabs[slab]) {
        return 0;
    }
    if (gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull ||
        base > UINT64_MAX - (gate_expert_bytes * 2ull + down_expert_bytes) ||
        base + gate_expert_bytes * 2ull + down_expert_bytes >
            (uint64_t)NSUIntegerMax) {
        return 0;
    }
    id<MTLBuffer> b = g_stream_expert_cache_slabs[slab];
    if (!ds4_gpu_stream_expert_slab_lock_slot(slot)) return 0;
    *gate_buf = b;
    *up_buf = b;
    *down_buf = b;
    *gate_inner = (NSUInteger)base;
    *up_inner = (NSUInteger)(base + gate_expert_bytes);
    *down_inner = (NSUInteger)(base + gate_expert_bytes * 2ull);
    return 1;
}

typedef enum {
    DS4_STREAM_EXPERT_SLAB_NOT_APPLICABLE = 0,
    DS4_STREAM_EXPERT_SLAB_OK = 1,
    DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED = 2,
} ds4_stream_expert_slab_result;

static void ds4_gpu_stream_expert_cache_freeze_growth(
        const ds4_ssd_qwen_slab_growth_plan *plan,
        const char                          *reason) {
    uint32_t cap = g_stream_expert_cache_slab_total_slots;
    if (g_stream_expert_cache_growth_budget_cap_active &&
        g_stream_expert_cache_growth_budget_cap < cap) {
        cap = g_stream_expert_cache_growth_budget_cap;
    }
    g_stream_expert_cache_growth_budget_cap = cap;
    g_stream_expert_cache_growth_budget_cap_active = 1;
    ds4_gpu_dspark_support_cache_target_cap_changed();

    if (g_stream_expert_cache_growth_guard_warned) return;
    g_stream_expert_cache_growth_guard_warned = 1;
    if (plan) {
        fprintf(stderr,
                "ds4: guarded streaming cache froze at %u TARGET slots before "
                "%.2f MiB slab growth: pressure %s, host %.2f/%.2f GiB, "
                "Metal %.2f/%.2f GiB%s%s\n",
                cap,
                ds4_gpu_mib(plan->slab_bytes),
                plan->pressure_normal ? "normal" : "not-normal",
                ds4_gpu_gib(plan->host_required_bytes),
                ds4_gpu_gib(plan->reclaimable_bytes),
                ds4_gpu_gib(plan->platform_required_bytes),
                ds4_gpu_gib(plan->recommended_bytes),
                reason ? ": " : "",
                reason ? reason : "");
    } else {
        fprintf(stderr,
                "ds4: guarded streaming cache froze at %u TARGET slots%s%s\n",
                cap,
                reason ? ": " : "",
                reason ? reason : "");
    }
}

static int ds4_gpu_stream_expert_cache_admit_slab_growth(
        uint64_t slab_bytes) {
    if (!g_stream_expert_cache_growth_guard_enabled) return 1;

#ifdef DS4_TEST_HOOKS
    if (g_stream_expert_cache_test_growth_guard_fail_after >= 0) {
        if (g_stream_expert_cache_test_growth_guard_fail_after == 0) {
            g_stream_expert_cache_test_growth_guard_fail_after = -1;
            ds4_gpu_stream_expert_cache_freeze_growth(
                NULL, "test-injected slab admission denial");
            return 0;
        }
        g_stream_expert_cache_test_growth_guard_fail_after--;
        return 1;
    }
#endif

    ds4_ssd_host_memory memory = {0};
    ds4_ssd_qwen_slab_growth_plan plan = {0};
    const uint64_t current_capacity_bytes =
        g_stream_expert_cache_slab_slot_bytes != 0 &&
        g_stream_expert_cache_slab_total_slots >
            UINT64_MAX / g_stream_expert_cache_slab_slot_bytes ?
            UINT64_MAX :
            (uint64_t)g_stream_expert_cache_slab_total_slots *
                g_stream_expert_cache_slab_slot_bytes;
    const bool snapshot_available =
        ds4_gpu_host_memory_snapshot(&memory) != 0;
    const bool plan_available =
        snapshot_available &&
        ds4_ssd_qwen_slab_growth_plan_make(
            &memory,
            g_stream_expert_cache_growth_guard_runtime_bytes,
            g_stream_expert_cache_growth_guard_static_page_bytes,
            current_capacity_bytes,
            slab_bytes,
            &plan);
    if (plan_available && plan.allowed) {
        if (getenv("DS4_METAL_MEMORY_REPORT") != NULL) {
            fprintf(stderr,
                    "ds4: streaming TARGET slab admission=admit proposed=%.2f "
                    "MiB current_cache=%.2f GiB host=%.2f/%.2f GiB "
                    "Metal=%.2f/%.2f GiB pressure=normal\n",
                    ds4_gpu_mib(plan.slab_bytes),
                    ds4_gpu_gib(plan.current_cache_capacity_bytes),
                    ds4_gpu_gib(plan.host_required_bytes),
                    ds4_gpu_gib(plan.reclaimable_bytes),
                    ds4_gpu_gib(plan.platform_required_bytes),
                    ds4_gpu_gib(plan.recommended_bytes));
        }
        return 1;
    }

    char reason[192];
    if (!snapshot_available) {
        snprintf(reason, sizeof(reason),
                 "host-memory snapshot unavailable");
    } else if (!plan_available) {
        snprintf(reason, sizeof(reason),
                 "incremental memory plan unavailable");
    } else {
        snprintf(reason, sizeof(reason),
                 "live host or Metal headroom denied growth");
    }
    if (plan_available) {
        /* Preserve the fixed working-set limit in the diagnostic without
         * adding another global solely for logging. */
        fprintf(stderr,
                "ds4: streaming TARGET slab admission=deny proposed=%.2f MiB, "
                "current_cache=%.2f GiB, host %.2f/%.2f GiB, Metal "
                "%.2f/%.2f GiB, pressure %s\n",
                ds4_gpu_mib(plan.slab_bytes),
                ds4_gpu_gib(plan.current_cache_capacity_bytes),
                ds4_gpu_gib(plan.host_required_bytes),
                ds4_gpu_gib(plan.reclaimable_bytes),
                ds4_gpu_gib(plan.platform_required_bytes),
                ds4_gpu_gib(memory.recommended_bytes),
                plan.pressure_normal ? "normal" : "not-normal");
    }
    ds4_gpu_stream_expert_cache_freeze_growth(
        plan_available ? &plan : NULL, reason);
    return 0;
}

static ds4_stream_expert_slab_result
ds4_gpu_stream_expert_alloc_slab_slot(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        __strong id<MTLBuffer> *gate_buf,
        __strong id<MTLBuffer> *up_buf,
        __strong id<MTLBuffer> *down_buf,
        NSUInteger *gate_inner,
        NSUInteger *up_inner,
        NSUInteger *down_inner) {
    if (!ds4_gpu_stream_expert_slab_enabled() ||
        !gate_buf || !up_buf || !down_buf ||
        !gate_inner || !up_inner || !down_inner ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return g_stream_expert_cache_growth_guard_enabled ?
            DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED :
            DS4_STREAM_EXPERT_SLAB_NOT_APPLICABLE;
    }

    const uint64_t logical_slot_bytes =
        gate_expert_bytes * 2ull + down_expert_bytes;
    uint64_t slot_bytes = g_stream_expert_cache_expert_bytes != 0 ?
        g_stream_expert_cache_expert_bytes : logical_slot_bytes;
    if (logical_slot_bytes == 0 || logical_slot_bytes > slot_bytes ||
        slot_bytes > (uint64_t)NSUIntegerMax) {
        return g_stream_expert_cache_growth_guard_enabled ?
            DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED :
            DS4_STREAM_EXPERT_SLAB_NOT_APPLICABLE;
    }
    const uint64_t page = (uint64_t)getpagesize();
    if (page != 0) {
        slot_bytes = round_up_u64(slot_bytes, page);
        if (slot_bytes == 0 || slot_bytes > (uint64_t)NSUIntegerMax) {
            return g_stream_expert_cache_growth_guard_enabled ?
                DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED :
                DS4_STREAM_EXPERT_SLAB_NOT_APPLICABLE;
        }
    }
    if (g_stream_expert_cache_slab_slot_bytes != 0 &&
        g_stream_expert_cache_slab_slot_bytes != slot_bytes) {
        return g_stream_expert_cache_growth_guard_enabled ?
            DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED :
            DS4_STREAM_EXPERT_SLAB_NOT_APPLICABLE;
    }
    g_stream_expert_cache_slab_slot_bytes = slot_bytes;

    if (g_stream_expert_cache_free_slot_count != 0) {
        const uint32_t slot =
            g_stream_expert_cache_free_slots[--g_stream_expert_cache_free_slot_count];
        return ds4_gpu_stream_expert_slab_slot_buffers(slot,
                                                       gate_expert_bytes,
                                                       down_expert_bytes,
                                                       gate_buf,
                                                       up_buf,
                                                       down_buf,
                                                       gate_inner,
                                                       up_inner,
                                                       down_inner) ?
            DS4_STREAM_EXPERT_SLAB_OK :
            (g_stream_expert_cache_growth_guard_enabled ?
                DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED :
                DS4_STREAM_EXPERT_SLAB_NOT_APPLICABLE);
    }

    uint32_t slab = g_stream_expert_cache_slab_count;
    if (slab != 0 &&
        g_stream_expert_cache_slab_slots_used[slab - 1] <
            g_stream_expert_cache_slab_slot_count[slab - 1]) {
        slab--;
    } else {
        if (g_stream_expert_cache_slab_count >=
            DS4_METAL_STREAM_EXPERT_CACHE_MAX_SLABS) {
            return DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED;
        }
        if (g_stream_expert_cache_growth_budget_cap_active &&
            g_stream_expert_cache_slab_total_slots >=
                g_stream_expert_cache_growth_budget_cap) {
            return DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED;
        }
        const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
        if (budget != 0 && g_stream_expert_cache_slab_total_slots >= budget) {
            return DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED;
        }
        uint64_t target = ds4_gpu_stream_expert_slab_target_bytes();
        uint64_t slots64 = target / slot_bytes;
        if (slots64 == 0) slots64 = 1;
        if (slots64 > UINT32_MAX) slots64 = UINT32_MAX;
        uint32_t slots = (uint32_t)slots64;
        if (budget != 0) {
            const uint32_t remaining =
                budget - g_stream_expert_cache_slab_total_slots;
            if (slots > remaining) slots = remaining;
        }
        if (slots == 0) return DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED;
        if ((uint64_t)slots > UINT64_MAX / slot_bytes ||
            !ds4_gpu_stream_expert_cache_admit_slab_growth(
                (uint64_t)slots * slot_bytes)) {
            return DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED;
        }
        id<MTLBuffer> slab_buffer = nil;
        while (slots != 0) {
            if ((uint64_t)slots <= UINT64_MAX / slot_bytes &&
                (uint64_t)slots * slot_bytes <= (uint64_t)NSUIntegerMax) {
                slab_buffer =
                    ds4_gpu_stream_expert_alloc_slab_buffer(
                            (uint64_t)slots * slot_bytes,
                            @"ds4_stream_expert_slab");
                if (slab_buffer) break;
            }
            if (g_stream_expert_cache_growth_guard_enabled) break;
            slots /= 2u;
        }
        if (!slab_buffer || slots == 0) {
            if (g_stream_expert_cache_growth_guard_enabled) {
                ds4_gpu_stream_expert_cache_freeze_growth(
                    NULL, "Metal slab allocation failed");
                return DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED;
            }
            return DS4_STREAM_EXPERT_SLAB_NOT_APPLICABLE;
        }

        slab = g_stream_expert_cache_slab_count++;
        g_stream_expert_cache_slabs[slab] = slab_buffer;
        g_stream_expert_cache_slab_start_slot[slab] =
            g_stream_expert_cache_slab_total_slots;
        g_stream_expert_cache_slab_slot_count[slab] = slots;
        g_stream_expert_cache_slab_slots_used[slab] = 0;
        g_stream_expert_cache_slab_total_slots += slots;
    }

    const uint32_t local_slot = g_stream_expert_cache_slab_slots_used[slab]++;
    const uint32_t slot =
        g_stream_expert_cache_slab_start_slot[slab] + local_slot;
    return ds4_gpu_stream_expert_slab_slot_buffers(slot,
                                                   gate_expert_bytes,
                                                   down_expert_bytes,
                                                   gate_buf,
                                                   up_buf,
                                                   down_buf,
                                                   gate_inner,
                                                   up_inner,
                                                   down_inner) ?
        DS4_STREAM_EXPERT_SLAB_OK :
        (g_stream_expert_cache_growth_guard_enabled ?
            DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED :
            DS4_STREAM_EXPERT_SLAB_NOT_APPLICABLE);
}

static uint64_t ds4_gpu_stream_expert_buffer_object_count(
        id<MTLBuffer> gate,
        id<MTLBuffer> up,
        id<MTLBuffer> down) {
    if (!gate || !up || !down) return 0;
    if (gate == up && gate == down) return 1;
    if (gate == up || gate == down || up == down) return 2;
    return 3;
}

static int ds4_gpu_stream_expert_split_requested(void) {
    return g_ssd_streaming_mode;
}

static uint32_t ds4_gpu_stream_expert_split_min_decode_tokens(void) {
    return 4;
}

static uint32_t ds4_gpu_stream_expert_split_min_cached(void) {
    uint32_t min_cached = 1024;
    const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    if (budget != 0 && budget < min_cached * 2u) {
        min_cached = budget / 2u;
    }
    return min_cached;
}

static int ds4_gpu_stream_expert_split_ready(void) {
    if (!ds4_gpu_stream_expert_split_requested()) return 0;
    if (g_stream_expert_cache_decode_tokens <
        ds4_gpu_stream_expert_split_min_decode_tokens()) {
        return 0;
    }
    return g_stream_expert_cache_entry_count >=
           ds4_gpu_stream_expert_split_min_cached();
}

static void ds4_gpu_stream_expert_cache_decay_route_hotness(void) {
    for (uint32_t layer = 0;
         layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
         layer++) {
        for (uint32_t expert = 0;
             expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
             expert++) {
            g_stream_expert_cache_route_hotness[layer][expert] >>= 1;
        }
    }
}

void ds4_gpu_stream_expert_cache_reset_route_hotness(void) {
    memset(g_stream_expert_cache_route_hotness,
           0,
           sizeof(g_stream_expert_cache_route_hotness));
    g_stream_expert_cache_hotness_decay_token =
        g_stream_expert_cache_decode_tokens;
}

void ds4_gpu_stream_expert_cache_release_resident(void) {
    /* --ssd-streaming-cold drops only resident expert storage. Preserve the
     * process-wide counters so later diagnostics still describe all I/O and
     * cache activity performed by this engine. */
    if (g_stream_expert_cache_lease.active) {
        fprintf(stderr,
                "ds4: cannot release resident streaming experts while a layer lease is active\n");
        return;
    }
    ds4_gpu_stream_expert_cache_clear_all(0);
}

static void ds4_gpu_stream_expert_cache_maybe_decay_route_hotness(void) {
    if (g_stream_expert_cache_decode_tokens == 0) return;
    if (g_stream_expert_cache_hotness_decay_token == 0) {
        g_stream_expert_cache_hotness_decay_token =
            g_stream_expert_cache_decode_tokens;
        return;
    }
    while (g_stream_expert_cache_decode_tokens -
           g_stream_expert_cache_hotness_decay_token >=
           DS4_METAL_STREAM_EXPERT_HOTNESS_DECAY_TOKENS) {
        ds4_gpu_stream_expert_cache_decay_route_hotness();
        g_stream_expert_cache_hotness_decay_token +=
            DS4_METAL_STREAM_EXPERT_HOTNESS_DECAY_TOKENS;
    }
}

static void ds4_gpu_stream_expert_cache_note_route_hotness(
        uint32_t layer,
        uint32_t expert,
        uint32_t amount) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        amount == 0) {
        return;
    }
    uint32_t *hotness = &g_stream_expert_cache_route_hotness[layer][expert];
    if (*hotness > UINT32_MAX - amount) {
        *hotness = UINT32_MAX;
    } else {
        *hotness += amount;
    }
}

static void ds4_gpu_stream_expert_cache_note_selected_hotness(
        uint32_t       layer,
        const int32_t *selected_ids,
        uint32_t       n_selected) {
    if (!selected_ids ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_selected == 0) {
        return;
    }
    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
    for (uint32_t i = 0; i < n_selected; i++) {
        if (selected_ids[i] < 0 ||
            selected_ids[i] >=
                (int32_t)DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
            continue;
        }
        ds4_gpu_stream_expert_cache_note_route_hotness(
                layer,
                (uint32_t)selected_ids[i],
                1);
    }
}

static void ds4_gpu_stream_expert_cache_note_frequency_hotness(
        uint32_t        layer,
        const uint32_t *frequency,
        uint32_t        n_total_expert) {
    if (!frequency || layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) {
        return;
    }
    if (n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        n_total_expert = DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
    }
    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
    for (uint32_t expert = 0; expert < n_total_expert; expert++) {
        ds4_gpu_stream_expert_cache_note_route_hotness(layer,
                                                       expert,
                                                       frequency[expert]);
    }
}

static void ds4_gpu_stream_expert_cache_note_token(uint32_t layer_index) {
    if (!g_ssd_streaming_mode || layer_index != 0 ||
        g_stream_expert_cache_decode_tokens == UINT64_MAX) {
        return;
    }
    g_stream_expert_cache_decode_tokens++;
    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
}

static void ds4_gpu_stream_expert_cache_note_decode_token(void) {
    if (!g_ssd_streaming_mode ||
        g_stream_expert_cache_decode_tokens == UINT64_MAX) {
        return;
    }
    g_stream_expert_cache_decode_tokens++;
    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
}

static int ds4_gpu_stream_compact_addr_requested(void) {
    return g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_STREAMING_COMPACT_ADDR") != NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_COMPACT_ADDR") == NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_ADDR_TABLE") == NULL;
}

static int ds4_gpu_stream_expert_addr_table_requested(void) {
    return g_ssd_streaming_mode &&
           (getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_ADDR_TABLE") != NULL ||
            getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_HIT_VALIDATOR") != NULL ||
            getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_MASKED_ADDR") != NULL ||
            g_stream_prefill_batch_selected_addr_building ||
            g_glm_stream_expert_addr_table_building ||
            (getenv("DS4_METAL_ENABLE_STREAMING_PREFILL_BATCH_SELECTED_ADDR") != NULL &&
             getenv("DS4_METAL_DISABLE_STREAMING_PREFILL_BATCH_SELECTED_ADDR") == NULL) ||
            ds4_gpu_stream_expert_split_requested()) &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_ADDR_TABLE") == NULL;
}

static int ds4_gpu_stream_expert_addr_table_kernel_requested(void) {
    return g_ssd_streaming_mode &&
           (getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_ADDR_TABLE") != NULL ||
            getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_HIT_VALIDATOR") != NULL ||
            getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_MASKED_ADDR") != NULL ||
            ds4_gpu_stream_expert_split_ready()) &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_ADDR_TABLE") == NULL;
}

static int ds4_gpu_stream_expert_masked_addr_requested(void) {
    return g_ssd_streaming_mode &&
           (getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_MASKED_ADDR") != NULL ||
            ds4_gpu_stream_expert_split_ready()) &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_MASKED_ADDR") == NULL;
}

static int ds4_gpu_stream_expert_hit_validator_requested(void) {
    return g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_HIT_VALIDATOR") != NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_HIT_VALIDATOR") == NULL;
}

static uint32_t ds4_gpu_stream_prefill_batch_selected_addr_auto_max(
        uint32_t n_total_expert) {
    const char *env = getenv("DS4_METAL_STREAMING_PREFILL_BATCH_SELECTED_ADDR_MAX");
    if (env && env[0]) {
        char *end = NULL;
        const long v = strtol(env, &end, 10);
        if (end != env) {
            if (v <= 0) return 0;
            if ((unsigned long)v > (unsigned long)UINT32_MAX) return UINT32_MAX;
            return (uint32_t)v;
        }
    }
    if (n_total_expert == 384) return 800u;
    if (n_total_expert == 256) {
        return g_qwen35_expert_pack.active &&
               g_qwen35_expert_pack.storage_format ==
                   DS4_EXPERT_STORE_STORAGE_MLX_AFFINE4
            ? 2048u
            : 760u;
    }
    return 0;
}

static uint32_t ds4_gpu_stream_prefill_batch_selected_addr_auto_min(
        uint32_t n_total_expert) {
    const char *env = getenv("DS4_METAL_STREAMING_PREFILL_BATCH_SELECTED_ADDR_MIN");
    if (env && env[0]) {
        char *end = NULL;
        const long v = strtol(env, &end, 10);
        if (end != env) {
            if (v <= 0) return 0;
            if ((unsigned long)v > (unsigned long)UINT32_MAX) return UINT32_MAX;
            return (uint32_t)v;
        }
    }
    if (n_total_expert == 384 || n_total_expert == 256) return 2u;
    return 0;
}

static int ds4_gpu_stream_prefill_batch_selected_addr_enabled(
        uint32_t n_tokens,
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint32_t gate_type,
        uint32_t down_type) {
    const int iq2_top6 =
        n_expert == 6 &&
        gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
        down_type == DS4_METAL_TENSOR_Q2_K;
    const int qwen_q4_top8 =
        n_total_expert == 256 &&
        n_expert == 8 &&
        gate_type == DS4_METAL_TENSOR_Q4_K &&
        down_type == DS4_METAL_TENSOR_Q4_K;
    const int qwen_iq_top8 =
        n_total_expert == 256 &&
        n_expert == 8 &&
        ((gate_type == DS4_METAL_TENSOR_IQ2_XS &&
          (down_type == DS4_METAL_TENSOR_IQ3_XXS ||
           down_type == DS4_METAL_TENSOR_IQ4_XS)) ||
         (gate_type == DS4_METAL_TENSOR_IQ3_XXS &&
          down_type == DS4_METAL_TENSOR_IQ4_XS));
    if (!g_ssd_streaming_mode ||
        n_tokens <= 1 ||
        n_total_expert == 0 ||
        (!iq2_top6 && !qwen_q4_top8 && !qwen_iq_top8) ||
        g_quality_mode ||
        getenv("DS4_METAL_DISABLE_STREAMING_PREFILL_BATCH_SELECTED_ADDR") != NULL ||
        getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_ADDR_TABLE") != NULL ||
        getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL ||
        getenv("DS4_METAL_DISABLE_ROUTED_PAIR_SWIGLU_FUSION") != NULL) {
        return 0;
    }
    if (ds4_gpu_stream_expert_cache_configured_count() < n_total_expert) {
        return 0;
    }
    if (getenv("DS4_METAL_ENABLE_STREAMING_PREFILL_BATCH_SELECTED_ADDR") != NULL) {
        return 1;
    }
    /*
     * The legacy Q4 selected-address matvec stops scaling near 760 rows.
     * Qwen IQ uses the compact mm_id address-table kernels instead; those
     * retain their full SSD micro-batch geometry.  Keep the wider limit tied
     * to the actual tensor types so adding IQ support cannot silently widen
     * the older Q4 path.
     */
    const uint32_t max_tokens = qwen_iq_top8 ?
        2048u :
        ds4_gpu_stream_prefill_batch_selected_addr_auto_max(n_total_expert);
    const uint32_t min_tokens =
        ds4_gpu_stream_prefill_batch_selected_addr_auto_min(n_total_expert);
    return max_tokens != 0 && n_tokens >= min_tokens && n_tokens <= max_tokens;
}

static int ds4_gpu_glm_streaming_prefill_full_layer_active(void) {
    return g_glm_streaming_prefill_full_layer_runtime ||
           getenv("DS4_METAL_GLM_STREAMING_PREFILL_FULL_LAYER") != NULL;
}

static int ds4_gpu_stream_full_expert_addr_table_requested(void) {
    return g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_STREAMING_FULL_EXPERT_ADDR_TABLE") != NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_FULL_EXPERT_ADDR_TABLE") == NULL;
}

static uint64_t ds4_gpu_buffer_address(id<MTLBuffer> buffer, NSUInteger inner) {
    if (!buffer) return 0;
#if TARGET_OS_OSX
    if (@available(macOS 13.0, *)) {
        return (uint64_t)[buffer gpuAddress] + (uint64_t)inner;
    }
#endif
    return 0;
}

static int ds4_gpu_stream_compact_addr_ensure_buffers(uint32_t layer) {
    if (!g_device || layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return 0;

    const NSUInteger addr_bytes = 6u * sizeof(uint64_t);
    const NSUInteger ids_bytes = 6u * sizeof(int32_t);
    for (uint32_t i = 0; i < 4; i++) {
        id<MTLBuffer> current = nil;
        NSUInteger bytes = addr_bytes;
        NSString *label = @"ds4_stream_compact_gate_addresses";
        switch (i) {
        case 0:
            current = g_stream_compact_gate_addr_buffers[layer];
            label = @"ds4_stream_compact_gate_addresses";
            break;
        case 1:
            current = g_stream_compact_up_addr_buffers[layer];
            label = @"ds4_stream_compact_up_addresses";
            break;
        case 2:
            current = g_stream_compact_down_addr_buffers[layer];
            label = @"ds4_stream_compact_down_addresses";
            break;
        default:
            current = g_stream_compact_selected_buffers[layer];
            bytes = ids_bytes;
            label = @"ds4_stream_compact_selected_ids";
            break;
        }
        if (current) continue;
        id<MTLBuffer> b = [g_device newBufferWithLength:bytes
                                                options:MTLResourceStorageModeShared];
        if (!b) {
            fprintf(stderr, "ds4: Metal streaming compact address buffer allocation failed\n");
            return 0;
        }
        b.label = label;
        memset([b contents], 0, bytes);
        [b didModifyRange:NSMakeRange(0, bytes)];
        switch (i) {
        case 0:
            g_stream_compact_gate_addr_buffers[layer] = b;
            break;
        case 1:
            g_stream_compact_up_addr_buffers[layer] = b;
            break;
        case 2:
            g_stream_compact_down_addr_buffers[layer] = b;
            break;
        default:
            g_stream_compact_selected_buffers[layer] = b;
            break;
        }
    }
    return 1;
}

static int ds4_gpu_stream_compact_addr_prepare(
        uint32_t layer,
        ds4_gpu_stream_expert_cache_entry * const entries[6],
        uint32_t n_entries,
        id<MTLBuffer> *gate_addrs,
        id<MTLBuffer> *up_addrs,
        id<MTLBuffer> *down_addrs,
        id<MTLBuffer> *selected_ids) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        !entries || !gate_addrs || !up_addrs || !down_addrs || !selected_ids ||
        n_entries == 0 || n_entries > 6) {
        return 0;
    }
    if (!ds4_gpu_stream_compact_addr_ensure_buffers(layer)) return 0;

    uint64_t gate_values[6] = {0, 0, 0, 0, 0, 0};
    uint64_t up_values[6] = {0, 0, 0, 0, 0, 0};
    uint64_t down_values[6] = {0, 0, 0, 0, 0, 0};
    int32_t slot_ids[6] = {0, 1, 2, 3, 4, 5};

    for (uint32_t i = 0; i < n_entries; i++) {
        ds4_gpu_stream_expert_cache_entry *e = entries[i];
        if (!e || !e->gate_buffer || !e->up_buffer || !e->down_buffer) {
            return 0;
        }
        gate_values[i] = ds4_gpu_buffer_address(e->gate_buffer, e->gate_inner);
        up_values[i] = ds4_gpu_buffer_address(e->up_buffer, e->up_inner);
        down_values[i] = ds4_gpu_buffer_address(e->down_buffer, e->down_inner);
        if (gate_values[i] == 0 || up_values[i] == 0 || down_values[i] == 0) {
            fprintf(stderr, "ds4: Metal streaming compact address path requires GPU addresses\n");
            return 0;
        }
    }

    const NSUInteger addr_bytes = 6u * sizeof(uint64_t);
    const NSUInteger ids_bytes = 6u * sizeof(int32_t);
    id<MTLBuffer> gb = g_stream_compact_gate_addr_buffers[layer];
    id<MTLBuffer> ub = g_stream_compact_up_addr_buffers[layer];
    id<MTLBuffer> db = g_stream_compact_down_addr_buffers[layer];
    id<MTLBuffer> ib = g_stream_compact_selected_buffers[layer];
    memcpy([gb contents], gate_values, addr_bytes);
    memcpy([ub contents], up_values, addr_bytes);
    memcpy([db contents], down_values, addr_bytes);
    memcpy([ib contents], slot_ids, ids_bytes);
    [gb didModifyRange:NSMakeRange(0, addr_bytes)];
    [ub didModifyRange:NSMakeRange(0, addr_bytes)];
    [db didModifyRange:NSMakeRange(0, addr_bytes)];
    [ib didModifyRange:NSMakeRange(0, ids_bytes)];

    *gate_addrs = gb;
    *up_addrs = ub;
    *down_addrs = db;
    *selected_ids = ib;
    return 1;
}

static int ds4_gpu_stream_selected_ids_prepare(
        uint32_t       layer,
        const int32_t *selected_ids,
        uint32_t       n_selected,
        id<MTLBuffer> *selected_buf,
        NSUInteger    *selected_off) {
    if (!g_device ||
        !selected_ids ||
        !selected_buf ||
        !selected_off ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_selected == 0 ||
        n_selected > DS4_METAL_MAX_ROUTED_EXPERT_USED) {
        return 0;
    }

    const NSUInteger bytes =
        (NSUInteger)DS4_METAL_MAX_ROUTED_EXPERT_USED * sizeof(int32_t);
    id<MTLBuffer> b = g_stream_selected_id_buffers[layer];
    if (!b) {
        b = [g_device newBufferWithLength:bytes
                                  options:MTLResourceStorageModeShared];
        if (!b) {
            fprintf(stderr, "ds4: Metal streaming selected-id buffer allocation failed\n");
            return 0;
        }
        b.label = @"ds4_stream_selected_ids";
        g_stream_selected_id_buffers[layer] = b;
    }

    int32_t ids[DS4_METAL_MAX_ROUTED_EXPERT_USED] = {0};
    memcpy(ids, selected_ids, (size_t)n_selected * sizeof(ids[0]));
    memcpy([b contents], ids, bytes);
    [b didModifyRange:NSMakeRange(0, bytes)];

    *selected_buf = b;
    *selected_off = 0;
    return 1;
}

static int ds4_gpu_stream_expert_cache_ensure_addr_buffers(uint32_t layer) {
    if (!g_device ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) {
        return 0;
    }

    const NSUInteger bytes =
        (NSUInteger)DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT * sizeof(uint64_t);
    id<MTLBuffer> buffers[3] = {
        g_stream_expert_cache_gate_addr_buffers[layer],
        g_stream_expert_cache_up_addr_buffers[layer],
        g_stream_expert_cache_down_addr_buffers[layer],
    };
    for (uint32_t i = 0; i < 3; i++) {
        if (buffers[i]) continue;
        id<MTLBuffer> b = [g_device newBufferWithLength:bytes
                                                options:MTLResourceStorageModeShared];
        if (!b) {
            fprintf(stderr, "ds4: Metal streaming expert address table allocation failed\n");
            return 0;
        }
        b.label =
            i == 0 ? @"ds4_stream_expert_gate_addresses" :
            (i == 1 ? @"ds4_stream_expert_up_addresses" :
                      @"ds4_stream_expert_down_addresses");
        memset([b contents], 0, bytes);
        [b didModifyRange:NSMakeRange(0, bytes)];
        if (i == 0) {
            g_stream_expert_cache_gate_addr_buffers[layer] = b;
        } else if (i == 1) {
            g_stream_expert_cache_up_addr_buffers[layer] = b;
        } else {
            g_stream_expert_cache_down_addr_buffers[layer] = b;
        }
    }
    return 1;
}

static void ds4_gpu_stream_expert_cache_zero_addr_slot(uint32_t layer, uint32_t expert) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        return;
    }

    id<MTLBuffer> buffers[3] = {
        g_stream_expert_cache_gate_addr_buffers[layer],
        g_stream_expert_cache_up_addr_buffers[layer],
        g_stream_expert_cache_down_addr_buffers[layer],
    };
    const NSUInteger off = (NSUInteger)expert * sizeof(uint64_t);
    for (uint32_t i = 0; i < 3; i++) {
        if (!buffers[i]) continue;
        uint64_t *addr = (uint64_t *)((uint8_t *)[buffers[i] contents] + off);
        *addr = 0;
        [buffers[i] didModifyRange:NSMakeRange(off, sizeof(uint64_t))];
    }
}

static int ds4_gpu_stream_expert_cache_set_addr_slot_raw(
        uint32_t      layer,
        uint32_t      expert,
        id<MTLBuffer> gate_buffer,
        NSUInteger    gate_inner,
        id<MTLBuffer> up_buffer,
        NSUInteger    up_inner,
        id<MTLBuffer> down_buffer,
        NSUInteger    down_inner) {
    if (!ds4_gpu_stream_expert_cache_ensure_addr_buffers(layer)) return 0;

    const uint64_t values[3] = {
        ds4_gpu_buffer_address(gate_buffer, gate_inner),
        ds4_gpu_buffer_address(up_buffer, up_inner),
        ds4_gpu_buffer_address(down_buffer, down_inner),
    };
    if (values[0] == 0 || values[1] == 0 || values[2] == 0) {
        fprintf(stderr, "ds4: Metal streaming expert address table requires GPU addresses\n");
        return 0;
    }

    id<MTLBuffer> buffers[3] = {
        g_stream_expert_cache_gate_addr_buffers[layer],
        g_stream_expert_cache_up_addr_buffers[layer],
        g_stream_expert_cache_down_addr_buffers[layer],
    };
    const NSUInteger off = (NSUInteger)expert * sizeof(uint64_t);
    for (uint32_t i = 0; i < 3; i++) {
        uint64_t *addr = (uint64_t *)((uint8_t *)[buffers[i] contents] + off);
        *addr = values[i];
        [buffers[i] didModifyRange:NSMakeRange(off, sizeof(uint64_t))];
    }
    return 1;
}

static int ds4_gpu_stream_expert_cache_set_addr_slot(
        uint32_t      layer,
        uint32_t      expert,
        id<MTLBuffer> gate_buffer,
        NSUInteger    gate_inner,
        id<MTLBuffer> up_buffer,
        NSUInteger    up_inner,
        id<MTLBuffer> down_buffer,
        NSUInteger    down_inner) {
    if (!ds4_gpu_stream_expert_addr_table_requested()) return 1;
    return ds4_gpu_stream_expert_cache_set_addr_slot_raw(layer,
                                                         expert,
                                                         gate_buffer,
                                                         gate_inner,
                                                         up_buffer,
                                                         up_inner,
                                                         down_buffer,
                                                         down_inner);
}

static int ds4_gpu_stream_expert_cache_addr_buffers(
        uint32_t       layer,
        id<MTLBuffer> *gate,
        id<MTLBuffer> *up,
        id<MTLBuffer> *down) {
    if (!ds4_gpu_stream_expert_cache_ensure_addr_buffers(layer)) return 0;
    if (gate) *gate = g_stream_expert_cache_gate_addr_buffers[layer];
    if (up) *up = g_stream_expert_cache_up_addr_buffers[layer];
    if (down) *down = g_stream_expert_cache_down_addr_buffers[layer];
    return g_stream_expert_cache_gate_addr_buffers[layer] &&
           g_stream_expert_cache_up_addr_buffers[layer] &&
           g_stream_expert_cache_down_addr_buffers[layer];
}

static void ds4_gpu_stream_full_expert_addr_clear_layer(uint32_t layer) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return;
    ds4_gpu_stream_expert_cache_entry *e = &g_stream_full_expert_addr_entry[layer];
    e->gate_buffer = nil;
    e->up_buffer = nil;
    e->down_buffer = nil;
    e->model_map = NULL;
    e->model_size = 0;
    e->gate_abs_offset = 0;
    e->up_abs_offset = 0;
    e->down_abs_offset = 0;
    e->gate_expert_bytes = 0;
    e->down_expert_bytes = 0;
    e->logical_bytes = 0;
    e->last_used = 0;
    e->use_count = 0;
    e->gate_inner = 0;
    e->up_inner = 0;
    e->down_inner = 0;
    e->slab_slot = 0;
    e->valid = 0;
    e->slab_backed = 0;
}

static void ds4_gpu_stream_full_expert_addr_reap_completed(void) {
    for (uint32_t layer = 0;
         layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
         layer++) {
        ds4_gpu_stream_expert_cache_entry *entry =
            &g_stream_full_expert_addr_entry[layer];
        if (entry->valid &&
            !ds4_gpu_stream_expert_cache_entry_inflight(entry)) {
            ds4_gpu_stream_full_expert_addr_clear_layer(layer);
        }
    }
}

static int ds4_gpu_stream_full_expert_addr_table_prepare(
        const void    *model_map,
        uint64_t       model_size,
        uint32_t       layer,
        uint32_t       n_total_expert,
        uint64_t       gate_abs_offset,
        uint64_t       up_abs_offset,
        uint64_t       down_abs_offset,
        uint64_t       gate_expert_bytes,
        uint64_t       down_expert_bytes,
        id<MTLBuffer> *gate_addrs,
        id<MTLBuffer> *up_addrs,
        id<MTLBuffer> *down_addrs,
        ds4_gpu_stream_expert_cache_entry **entry_out) {
    if (!model_map || model_size == 0 ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        gate_expert_bytes == 0 ||
        down_expert_bytes == 0 ||
        n_total_expert > UINT64_MAX / gate_expert_bytes ||
        n_total_expert > UINT64_MAX / down_expert_bytes) {
        return 0;
    }

    id<MTLBuffer> expert_major_buffer = nil;
    uint64_t expert_major_gate_inner = 0;
    uint64_t expert_major_up_inner = 0;
    uint64_t expert_major_down_inner = 0;
    uint64_t expert_major_stride = 0;
    uint64_t expert_major_offset = 0;
    uint64_t expert_major_bytes = 0;
    const bool has_expert_major =
        ds4_gpu_expert_store_v2_layer_span(
            layer, model_size,
            &expert_major_offset, &expert_major_bytes) != 0;
    const bool use_expert_major =
        has_expert_major &&
        ds4_gpu_qwen35_expert_pack_resolve_layer(
            model_map,
            layer,
            model_size,
            gate_abs_offset,
            up_abs_offset,
            down_abs_offset,
            &expert_major_buffer,
            &expert_major_gate_inner,
            &expert_major_up_inner,
            &expert_major_down_inner,
            &expert_major_stride) != 0;
    if (has_expert_major && !use_expert_major) return 0;
    if (!has_expert_major &&
        !ds4_gpu_stream_full_expert_addr_table_requested()) {
        return 0;
    }
    if (use_expert_major &&
        (expert_major_up_inner !=
             expert_major_gate_inner + gate_expert_bytes ||
         expert_major_down_inner !=
             expert_major_up_inner + gate_expert_bytes ||
         expert_major_stride !=
             gate_expert_bytes * 2u + down_expert_bytes ||
         expert_major_bytes !=
             (uint64_t)n_total_expert * expert_major_stride)) {
        return 0;
    }

    const uint64_t gate_tensor_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_tensor_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_abs_offset > model_size ||
        up_abs_offset > model_size ||
        down_abs_offset > model_size ||
        gate_tensor_bytes > model_size - gate_abs_offset ||
        gate_tensor_bytes > model_size - up_abs_offset ||
        down_tensor_bytes > model_size - down_abs_offset) {
        return 0;
    }

    /* Full-layer wrappers can cover multiple GiB. Retain only resources still
     * referenced by an in-flight command buffer instead of accumulating one
     * wrapper for every routed layer in a long prompt. */
    ds4_gpu_stream_full_expert_addr_reap_completed();

    ds4_gpu_stream_expert_cache_entry *entry =
        &g_stream_full_expert_addr_entry[layer];
    if (!entry->valid ||
        entry->model_map != model_map ||
        entry->model_size != model_size ||
        entry->gate_abs_offset != gate_abs_offset ||
        entry->up_abs_offset != up_abs_offset ||
        entry->down_abs_offset != down_abs_offset ||
        entry->gate_expert_bytes != gate_expert_bytes ||
        entry->down_expert_bytes != down_expert_bytes ||
        !entry->gate_buffer ||
        !entry->up_buffer ||
        !entry->down_buffer) {
        ds4_gpu_stream_full_expert_addr_clear_layer(layer);

        uint64_t gate_inner = 0;
        uint64_t up_inner = 0;
        uint64_t down_inner = 0;
        id<MTLBuffer> gate_buf = nil;
        id<MTLBuffer> up_buf = nil;
        id<MTLBuffer> down_buf = nil;
        if (use_expert_major) {
            gate_buf = expert_major_buffer;
            up_buf = expert_major_buffer;
            down_buf = expert_major_buffer;
            gate_inner = expert_major_gate_inner;
            up_inner = expert_major_up_inner;
            down_inner = expert_major_down_inner;
        } else {
            gate_buf = ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                            model_size,
                                                            gate_abs_offset,
                                                            gate_tensor_bytes,
                                                            &gate_inner);
            up_buf = ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                          model_size,
                                                          up_abs_offset,
                                                          gate_tensor_bytes,
                                                          &up_inner);
            down_buf = ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                            model_size,
                                                            down_abs_offset,
                                                            down_tensor_bytes,
                                                            &down_inner);
        }
        if (!gate_buf || !up_buf || !down_buf) return 0;

        entry->gate_buffer = gate_buf;
        entry->up_buffer = up_buf;
        entry->down_buffer = down_buf;
        entry->model_map = model_map;
        entry->model_size = model_size;
        entry->gate_abs_offset = gate_abs_offset;
        entry->up_abs_offset = up_abs_offset;
        entry->down_abs_offset = down_abs_offset;
        entry->gate_expert_bytes = gate_expert_bytes;
        entry->down_expert_bytes = down_expert_bytes;
        entry->logical_bytes = use_expert_major ? expert_major_bytes :
                               gate_tensor_bytes * 2ull + down_tensor_bytes;
        entry->gate_inner = (NSUInteger)gate_inner;
        entry->up_inner = (NSUInteger)up_inner;
        entry->down_inner = (NSUInteger)down_inner;
        entry->valid = 1;

    }

    /* Decode-cache installs share these tables and can overwrite individual
     * slots. Rebuild all pointers for every full-layer dispatch. */
    if (!ds4_gpu_stream_expert_cache_ensure_addr_buffers(layer)) {
        ds4_gpu_stream_full_expert_addr_clear_layer(layer);
        return 0;
    }
    const uint64_t gate_base = ds4_gpu_buffer_address(entry->gate_buffer,
                                                      entry->gate_inner);
    const uint64_t up_base = ds4_gpu_buffer_address(entry->up_buffer,
                                                    entry->up_inner);
    const uint64_t down_base = ds4_gpu_buffer_address(entry->down_buffer,
                                                      entry->down_inner);
    if (gate_base == 0 || up_base == 0 || down_base == 0) {
        fprintf(stderr,
                "ds4: Metal full streaming expert address table requires GPU addresses\n");
        ds4_gpu_stream_full_expert_addr_clear_layer(layer);
        return 0;
    }
    id<MTLBuffer> buffers[3] = {
        g_stream_expert_cache_gate_addr_buffers[layer],
        g_stream_expert_cache_up_addr_buffers[layer],
        g_stream_expert_cache_down_addr_buffers[layer],
    };
    uint64_t *gate_addr = (uint64_t *)[buffers[0] contents];
    uint64_t *up_addr = (uint64_t *)[buffers[1] contents];
    uint64_t *down_addr = (uint64_t *)[buffers[2] contents];
    const uint64_t gate_stride =
        use_expert_major ? expert_major_stride : gate_expert_bytes;
    const uint64_t down_stride =
        use_expert_major ? expert_major_stride : down_expert_bytes;
    for (uint32_t expert = 0;
         expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
         expert++) {
        if (expert < n_total_expert) {
            gate_addr[expert] = gate_base + (uint64_t)expert * gate_stride;
            up_addr[expert] = up_base + (uint64_t)expert * gate_stride;
            down_addr[expert] = down_base + (uint64_t)expert * down_stride;
        } else {
            gate_addr[expert] = 0;
            up_addr[expert] = 0;
            down_addr[expert] = 0;
        }
    }
    const NSUInteger bytes =
        (NSUInteger)DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT * sizeof(uint64_t);
    for (uint32_t i = 0; i < 3; i++) {
        [buffers[i] didModifyRange:NSMakeRange(0, bytes)];
    }

    if (gate_addrs) *gate_addrs = g_stream_expert_cache_gate_addr_buffers[layer];
    if (up_addrs) *up_addrs = g_stream_expert_cache_up_addr_buffers[layer];
    if (down_addrs) *down_addrs = g_stream_expert_cache_down_addr_buffers[layer];
    if (entry_out) *entry_out = entry;
    return entry->valid &&
           g_stream_expert_cache_gate_addr_buffers[layer] &&
           g_stream_expert_cache_up_addr_buffers[layer] &&
           g_stream_expert_cache_down_addr_buffers[layer];
}

static id<MTLBuffer> ds4_gpu_stream_expert_validate_status_buffer(void) {
    if (!g_device) return nil;
    if (g_stream_expert_validate_status_buffer) {
        return g_stream_expert_validate_status_buffer;
    }

    const NSUInteger bytes =
        (NSUInteger)DS4_METAL_STREAM_EXPERT_VALIDATE_WORDS * sizeof(uint32_t);
    id<MTLBuffer> b = [g_device newBufferWithLength:bytes
                                            options:MTLResourceStorageModeShared];
    if (!b) {
        fprintf(stderr, "ds4: Metal streaming expert validator allocation failed\n");
        return nil;
    }
    b.label = @"ds4_stream_expert_validate_status";
    memset([b contents], 0, bytes);
    [b didModifyRange:NSMakeRange(0, bytes)];
    g_stream_expert_validate_status_buffer = b;
    return b;
}

static int ds4_gpu_encode_stream_expert_cache_validate(
        id<MTLCommandBuffer> cb,
        const ds4_gpu_stream_expert_validate_args *args,
        id<MTLBuffer> selected,
        NSUInteger selected_off,
        id<MTLBuffer> gate_addrs,
        id<MTLBuffer> up_addrs,
        id<MTLBuffer> down_addrs,
        id<MTLBuffer> status) {
    if (!cb || !args || !selected || !gate_addrs || !up_addrs || !down_addrs ||
        !status || !g_moe_stream_expert_cache_validate_pipeline ||
        args->n_total_expert == 0 || args->n_total_expert > 384 ||
        args->n_expert == 0 || args->n_expert > 6) {
        return 0;
    }

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_moe_stream_expert_cache_validate_pipeline];
    [enc setBytes:args length:sizeof(*args) atIndex:0];
    [enc setBuffer:selected offset:selected_off atIndex:1];
    [enc setBuffer:gate_addrs offset:0 atIndex:2];
    [enc setBuffer:up_addrs offset:0 atIndex:3];
    [enc setBuffer:down_addrs offset:0 atIndex:4];
    [enc setBuffer:status offset:0 atIndex:5];
    [enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_stream_expert_cache_validate_selected(
        const ds4_gpu_tensor *selected,
        id<MTLBuffer> gate_addrs,
        id<MTLBuffer> up_addrs,
        id<MTLBuffer> down_addrs,
        uint32_t n_total_expert,
        uint32_t n_expert,
        int32_t selected_ids[6],
        uint32_t *all_cached,
        uint32_t *miss_mask,
        uint32_t *invalid_mask) {
    if (!selected || !selected_ids || !all_cached || !miss_mask || !invalid_mask) {
        return 0;
    }
    id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
    id<MTLBuffer> status = ds4_gpu_stream_expert_validate_status_buffer();
    if (!selectedbuf || !status) return 0;

    const NSUInteger status_bytes =
        (NSUInteger)DS4_METAL_STREAM_EXPERT_VALIDATE_WORDS * sizeof(uint32_t);
    memset([status contents], 0, status_bytes);
    [status didModifyRange:NSMakeRange(0, status_bytes)];

    ds4_gpu_stream_expert_validate_args args = {
        .n_total_expert = n_total_expert,
        .n_expert = n_expert,
    };

    const int had_batch = g_batch_cb != nil;
    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    if (!cb) return 0;
    if (!ds4_gpu_encode_stream_expert_cache_validate(cb,
                                                     &args,
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     gate_addrs,
                                                     up_addrs,
                                                     down_addrs,
                                                     status)) {
        return 0;
    }

    if (had_batch) {
        if (ds4_gpu_end_commands() == 0) return 0;
    } else if (!ds4_gpu_finish_command_buffer(cb, owned,
                                              "streaming expert cache validator")) {
        return 0;
    }

    const uint32_t *words = (const uint32_t *)[status contents];
    *all_cached = words[0];
    *miss_mask = words[1];
    *invalid_mask = words[2];
    for (uint32_t i = 0; i < 6; i++) {
        selected_ids[i] = (int32_t)words[4 + i];
    }

    if (had_batch && ds4_gpu_begin_commands() == 0) return 0;
    return 1;
}

static uint64_t ds4_gpu_stream_expert_cache_lease_next_id(void) {
    /* Zero is the public invalid sentinel. A wrap is practically unreachable,
     * but skipping it keeps stale-id rejection correct by construction. */
    g_stream_expert_cache_lease.epoch++;
    if (g_stream_expert_cache_lease.epoch == 0) {
        g_stream_expert_cache_lease.epoch++;
    }
    return g_stream_expert_cache_lease.epoch;
}

static int ds4_gpu_stream_expert_cache_lease_protects(uint32_t layer) {
    return g_stream_expert_cache_lease.active &&
           g_stream_expert_cache_lease.domain ==
               DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
           layer == g_stream_expert_cache_lease.layer;
}

#ifdef DS4_TEST_HOOKS
static int ds4_gpu_dspark_support_lease_authenticates(
        uint64_t lease_id) {
    return g_stream_expert_cache_lease.active &&
           g_stream_expert_cache_lease.domain ==
               DS4_GPU_STREAM_EXPERT_LEASE_SUPPORT &&
           lease_id != 0 &&
           lease_id == g_stream_expert_cache_lease.id &&
           pthread_equal(g_stream_expert_cache_lease.owner, pthread_self());
}

static int ds4_gpu_dspark_support_lease_store_matches(void) {
    if (!g_stream_expert_cache_lease.active ||
        g_stream_expert_cache_lease.domain !=
            DS4_GPU_STREAM_EXPERT_LEASE_SUPPORT ||
        !g_dspark_expert_pack ||
        g_stream_expert_cache_lease.support_pack !=
            (const void *)g_dspark_expert_pack ||
        !g_dspark_expert_pack->active ||
        g_stream_expert_cache_lease.support_target_generation !=
            g_dspark_support_target_generation ||
        g_stream_expert_cache_lease.support_target_generation !=
            g_target_expert_pack_generation ||
        g_stream_expert_cache_lease.support_pack_generation !=
            g_dspark_support_pack_generation ||
        g_stream_expert_cache_lease.support_file_device !=
            g_dspark_expert_pack->file_device ||
        g_stream_expert_cache_lease.support_file_inode !=
            g_dspark_expert_pack->file_inode ||
        g_stream_expert_cache_lease.support_file_size !=
            g_dspark_expert_pack->file_size ||
        g_stream_expert_cache_lease.support_fd !=
            g_dspark_expert_pack->fd) {
        return 0;
    }
    struct stat st;
    return fstat(g_dspark_expert_pack->fd, &st) == 0 &&
           st.st_size >= 0 && S_ISREG(st.st_mode) &&
           st.st_dev == g_stream_expert_cache_lease.support_file_device &&
           st.st_ino == g_stream_expert_cache_lease.support_file_inode &&
           (uint64_t)st.st_size ==
               g_stream_expert_cache_lease.support_file_size;
}
#endif

static int ds4_gpu_dspark_support_lease_pins(
        uint32_t stage,
        uint32_t expert) {
    return g_stream_expert_cache_lease.active &&
           g_stream_expert_cache_lease.domain ==
               DS4_GPU_STREAM_EXPERT_LEASE_SUPPORT &&
           stage == g_stream_expert_cache_lease.layer &&
           expert < DS4_DSPARK_SUPPORT_EXPERT_COUNT &&
           (g_stream_expert_cache_lease.support_pins[expert / 64u] &
               (1ull << (expert % 64u))) != 0;
}

#ifdef DS4_TEST_HOOKS
/* A DSpark SUPPORT transaction calls this after its final Metal consumer and
 * before authenticated release.  The recorded sequence is the lifetime edge:
 * pinned records may not become evictable until that exact batch completes. */
static int ds4_gpu_dspark_support_lease_note_current_batch_use(void) {
    if (!g_stream_expert_cache_lease.active ||
        g_stream_expert_cache_lease.domain !=
            DS4_GPU_STREAM_EXPERT_LEASE_SUPPORT ||
        !pthread_equal(g_stream_expert_cache_lease.owner, pthread_self())) {
        return 0;
    }
    const uint64_t seq = g_stream_expert_cache_batch_seq ?
                         g_stream_expert_cache_batch_seq :
                         g_stream_expert_cache_owned_seq;
    if (seq == 0) return 0;
    if (seq > g_stream_expert_cache_lease.last_use_seq) {
        g_stream_expert_cache_lease.last_use_seq = seq;
    }
    return 1;
}

static uint32_t ds4_gpu_dspark_support_lease_pinned_count(void) {
    uint32_t count = 0;
    for (uint32_t word = 0;
         word < DS4_DSPARK_SUPPORT_EXPERT_COUNT / 64u;
         word++) {
        count += (uint32_t)__builtin_popcountll(
            g_stream_expert_cache_lease.support_pins[word]);
    }
    return count;
}
#endif

static void ds4_gpu_stream_expert_cache_lease_invalidate(void) {
    if (g_stream_expert_cache_lease.active) {
        (void)ds4_gpu_stream_expert_cache_lease_next_id();
    }
    g_stream_expert_cache_lease.id = 0;
    g_stream_expert_cache_lease.layer = UINT32_MAX;
    memset(g_stream_expert_cache_lease.support_pins,
           0,
           sizeof(g_stream_expert_cache_lease.support_pins));
    g_stream_expert_cache_lease.last_use_seq = 0;
    g_stream_expert_cache_lease.support_pack = NULL;
    g_stream_expert_cache_lease.support_target_generation = 0;
    g_stream_expert_cache_lease.support_pack_generation = 0;
    g_stream_expert_cache_lease.support_file_device = 0;
    g_stream_expert_cache_lease.support_file_inode = 0;
    g_stream_expert_cache_lease.support_file_size = 0;
    g_stream_expert_cache_lease.support_fd = -1;
    g_stream_expert_cache_lease.domain = DS4_GPU_STREAM_EXPERT_LEASE_NONE;
    g_stream_expert_cache_lease.active = 0;
    memset(&g_stream_expert_cache_lease.owner,
           0,
           sizeof(g_stream_expert_cache_lease.owner));
}

static void ds4_gpu_stream_expert_cache_clear_entry_internal(
        uint32_t                                  layer,
        uint32_t                                  expert,
        int                                       count_eviction,
        int                                       recycle_slab_slot,
        ds4_gpu_stream_expert_reusable_buffers   *reuse) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        return;
    }
    if (reuse) {
        reuse->gate_buffer = nil;
        reuse->up_buffer = nil;
        reuse->down_buffer = nil;
        reuse->gate_inner = 0;
        reuse->up_inner = 0;
        reuse->down_inner = 0;
    }
    ds4_gpu_stream_expert_cache_entry *e =
        &g_stream_expert_cache[layer][expert];
    if (!e->valid) return;
    /* A lease covers the set of entries that exists at each instant, not all
     * 256 possible experts. Therefore acquisition allocates nothing, while a
     * later on-demand install becomes protected automatically. */
    if (ds4_gpu_stream_expert_cache_lease_protects(layer)) return;
    if (ds4_gpu_stream_expert_cache_entry_inflight(e)) {
        return;
    }

    const uint64_t bytes = e->logical_bytes;
    ds4_gpu_stream_expert_cache_zero_addr_slot(layer, expert);
    if (reuse) {
        reuse->gate_buffer = e->gate_buffer;
        reuse->up_buffer = e->up_buffer;
        reuse->down_buffer = e->down_buffer;
        reuse->gate_inner = e->gate_inner;
        reuse->up_inner = e->up_inner;
        reuse->down_inner = e->down_inner;
    } else if (e->slab_backed && recycle_slab_slot) {
        ds4_gpu_stream_expert_slab_push_free_slot(e->slab_slot);
    }
    e->gate_buffer = nil;
    e->up_buffer = nil;
    e->down_buffer = nil;
    e->model_map = NULL;
    e->model_size = 0;
    e->gate_abs_offset = 0;
    e->up_abs_offset = 0;
    e->down_abs_offset = 0;
    e->gate_expert_bytes = 0;
    e->down_expert_bytes = 0;
    e->logical_bytes = 0;
    e->last_used = 0;
    e->use_count = 0;
    e->gate_inner = 0;
    e->up_inner = 0;
    e->down_inner = 0;
    e->inflight_seq = 0;
    e->slab_slot = 0;
    e->valid = 0;
    e->slab_backed = 0;

    const int qwen_cache_index =
        hebrus_gpu_stream_expert_qwen35_model();
    if (qwen_cache_index) {
        g_stream_expert_cache_layer_occupancy[layer][expert / 64u] &=
            ~(1ull << (expert % 64u));
    }
    if (g_stream_expert_cache_layer_count[layer] > 0) {
        g_stream_expert_cache_layer_count[layer]--;
    }
    if (qwen_cache_index &&
        g_stream_expert_cache_layer_count[layer] == 0) {
        g_stream_expert_cache_layer_expert_limit[layer] = 0;
    }
    if (g_stream_expert_cache_entry_count > 0) {
        g_stream_expert_cache_entry_count--;
    }
    if (g_stream_expert_cache_bytes >= bytes) {
        g_stream_expert_cache_bytes -= bytes;
    } else {
        g_stream_expert_cache_bytes = 0;
    }
    if (count_eviction) {
        ds4_gpu_stream_expert_counter_add(
            &g_stream_expert_cache_evictions, 1);
        g_stream_expert_cache_layer_evictions[layer]++;
    }
}

static void ds4_gpu_stream_expert_cache_clear_entry(
        uint32_t layer,
        uint32_t expert,
        int      count_eviction) {
    ds4_gpu_stream_expert_cache_clear_entry_internal(layer,
                                                     expert,
                                                     count_eviction,
                                                     1,
                                                     NULL);
}

static void ds4_gpu_stream_expert_cache_clear_all(int reset_stats) {
    /* Model teardown is the one operation allowed to revoke a lease without
     * its token. Bump the epoch first so a delayed release cannot match a
     * future model's lease. Normal phase changes reject an active lease. */
    ds4_gpu_stream_expert_cache_lease_invalidate();
    ds4_gpu_qwen35_stream_batch_pending_clear();
    ds4_gpu_stream_expert_pending_load_clear();
    g_stream_expert_cache_done_seq = g_stream_expert_cache_cb_seq;
    g_stream_expert_cache_batch_seq = 0;
    g_stream_expert_cache_owned_seq = 0;
    g_stream_expert_cache_pending_max_seq = 0;
    g_stream_expert_measure_enabled = 0;
    g_stream_expert_measure_unique_experts = 0;
    g_stream_expert_measure_unique_bytes = 0;
    memset(g_stream_expert_measure_seen, 0, sizeof(g_stream_expert_measure_seen));
    for (uint32_t layer = 0; layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER; layer++) {
        for (uint32_t expert = 0; expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT; expert++) {
            g_stream_expert_cache[layer][expert].inflight_seq = 0;
            ds4_gpu_stream_expert_cache_clear_entry(layer, expert, 0);
        }
        ds4_gpu_stream_full_expert_addr_clear_layer(layer);
        g_stream_expert_cache_layer_count[layer] = 0;
        g_stream_expert_cache_layer_expert_limit[layer] = 0;
        memset(g_stream_expert_cache_layer_occupancy[layer],
               0,
               sizeof(g_stream_expert_cache_layer_occupancy[layer]));
        id<MTLBuffer> buffers[3] = {
            g_stream_expert_cache_gate_addr_buffers[layer],
            g_stream_expert_cache_up_addr_buffers[layer],
            g_stream_expert_cache_down_addr_buffers[layer],
        };
        for (uint32_t i = 0; i < 3; i++) {
            if (!buffers[i]) continue;
            const NSUInteger bytes =
                (NSUInteger)DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT * sizeof(uint64_t);
            memset([buffers[i] contents], 0, bytes);
            [buffers[i] didModifyRange:NSMakeRange(0, bytes)];
        }
    }
    g_stream_expert_cache_bytes = 0;
    g_stream_expert_cache_entry_count = 0;
    /* Evicted slab slots normally stay locked for fast reuse. Clearing the
     * cache is different: unlock every slot before dropping the owning Metal
     * buffers so a phase shrink releases physical memory immediately. */
    for (uint32_t slot = 0;
         slot < g_stream_expert_cache_slab_total_slots &&
         slot < DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES;
         slot++) {
        (void)ds4_gpu_stream_expert_slab_unlock_slot(slot);
    }
    for (uint32_t i = 0; i < g_stream_expert_cache_slab_count; i++) {
        g_stream_expert_cache_slabs[i] = nil;
        g_stream_expert_cache_slab_start_slot[i] = 0;
        g_stream_expert_cache_slab_slot_count[i] = 0;
        g_stream_expert_cache_slab_slots_used[i] = 0;
    }
    g_stream_expert_cache_slab_count = 0;
    g_stream_expert_cache_slab_total_slots = 0;
    g_stream_expert_cache_free_slot_count = 0;
    g_stream_expert_cache_slab_slot_bytes = 0;
    memset(g_stream_expert_cache_slab_slot_locked,
           0,
           sizeof(g_stream_expert_cache_slab_slot_locked));
    /* Non-slab buffers are unlocked by deallocation above. This field is live
     * locked residency, unlike the cumulative hit/I/O counters. */
    g_stream_expert_cache_mlock_bytes = 0;
    if (reset_stats) {
        g_stream_expert_cache_hits = 0;
        g_stream_expert_cache_misses = 0;
        g_stream_expert_cache_evictions = 0;
        g_stream_expert_cache_wraps = 0;
        g_stream_expert_cache_clock = 0;
        g_stream_expert_cache_willneed_advise_bytes = 0;
        g_stream_expert_cache_expert_loads = 0;
        g_stream_expert_cache_pread_syscalls = 0;
        g_stream_expert_cache_pread_bytes = 0;
        g_stream_expert_cache_pread_ms = 0.0;
        g_stream_expert_cache_split_resident_wait_ms = 0.0;
        g_stream_expert_cache_mlock_fail_bytes = 0;
        g_stream_expert_cache_mlock_failures = 0;
        g_stream_expert_cache_mlock_ms = 0.0;
        g_stream_expert_cache_mlock_warned = 0;
        g_stream_expert_cache_mlock_budget_cap = 0;
        g_stream_expert_cache_mlock_budget_cap_active = 0;
        g_stream_expert_cache_mlock_relief_applied = 0;
        g_stream_expert_cache_test_mlock_fail_after = -1;
        g_stream_expert_cache_buffer_allocs = 0;
        g_stream_expert_cache_buffer_reuses = 0;
        g_stream_expert_cache_decode_tokens = 0;
        g_stream_expert_cache_hotness_decay_token = 0;
        memset(g_stream_expert_cache_route_hotness,
               0,
               sizeof(g_stream_expert_cache_route_hotness));
        g_stream_expert_timing_selected_calls = 0;
        g_stream_expert_timing_selected_read_ms = 0.0;
        g_stream_expert_timing_selected_sync_ms = 0.0;
        g_stream_expert_timing_selected_copy_ms = 0.0;
        g_stream_expert_timing_selected_bind_ms = 0.0;
        g_stream_expert_timing_overlap_route_calls = 0;
        g_stream_expert_timing_overlap_route_wait_ms = 0.0;
        g_stream_expert_timing_overlap_route_copy_ms = 0.0;
        g_stream_expert_timing_overlap_route_plan_ms = 0.0;
        g_stream_expert_timing_overlap_finish_calls = 0;
        g_stream_expert_timing_overlap_finish_publish_ms = 0.0;
        g_stream_expert_timing_overlap_finish_wait_ms = 0.0;
        g_stream_expert_timing_overlap_finish_modify_ms = 0.0;
        g_stream_expert_timing_overlap_finish_install_ms = 0.0;
        g_stream_expert_timing_split_layers = 0;
        g_stream_expert_timing_split_resident_experts = 0;
        g_stream_expert_timing_split_missing_experts = 0;
        g_stream_expert_timing_split_resident_ms = 0.0;
        g_stream_expert_timing_split_missing_ms = 0.0;
        g_stream_expert_timing_split_missing_load_ms = 0.0;
        g_stream_expert_timing_split_missing_slot_ms = 0.0;
        g_stream_expert_timing_split_missing_prune_ms = 0.0;
        g_stream_expert_timing_split_missing_addr_ms = 0.0;
        g_stream_expert_timing_split_missing_wait_ms = 0.0;
        g_stream_expert_timing_load_calls = 0;
        g_stream_expert_timing_load_prepare_ms = 0.0;
        g_stream_expert_timing_load_pread_ms = 0.0;
        g_stream_expert_timing_load_modify_ms = 0.0;
        g_stream_expert_timing_load_install_ms = 0.0;
        g_stream_expert_timing_prepare_batch_reuse_calls = 0;
        g_stream_expert_timing_prepare_batch_reuse_ms = 0.0;
        g_stream_expert_timing_prepare_buffer_calls = 0;
        g_stream_expert_timing_prepare_buffer_ms = 0.0;
        g_stream_expert_timing_prepare_task_experts = 0;
        g_stream_expert_timing_prepare_task_ms = 0.0;
        g_stream_expert_timing_reuse_scan_calls = 0;
        g_stream_expert_timing_reuse_scan_entries = 0;
        g_stream_expert_timing_reuse_scan_ms = 0.0;
        g_stream_expert_timing_reuse_clear_ms = 0.0;
        g_stream_expert_timing_readahead_calls = 0;
        g_stream_expert_timing_readahead_bytes = 0;
        g_stream_expert_timing_readahead_ms = 0.0;
        g_stream_expert_timing_cache_all_resident_layers = 0;
        g_stream_expert_timing_cache_all_missing_layers = 0;
        g_stream_expert_timing_cache_mixed_layers = 0;
        g_stream_expert_timing_cache_resident_experts = 0;
        g_stream_expert_timing_cache_missing_experts = 0;
        g_stream_expert_timing_last_report =
            (ds4_gpu_stream_expert_timing_snapshot){0};
        memset(g_stream_expert_cache_layer_hits,
               0,
               sizeof(g_stream_expert_cache_layer_hits));
        memset(g_stream_expert_cache_layer_misses,
               0,
               sizeof(g_stream_expert_cache_layer_misses));
        memset(g_stream_expert_cache_layer_evictions,
               0,
               sizeof(g_stream_expert_cache_layer_evictions));
        memset(g_stream_expert_cache_layer_pread_bytes,
               0,
               sizeof(g_stream_expert_cache_layer_pread_bytes));
        memset(g_stream_expert_cache_layer_pread_ms,
               0,
               sizeof(g_stream_expert_cache_layer_pread_ms));
    }
}

static void ds4_gpu_dspark_support_cache_clear_entry(
        uint32_t stage,
        uint32_t expert,
        int count_eviction) {
    if (stage >= DS4_DSPARK_SUPPORT_LAYER_COUNT ||
        expert >= DS4_DSPARK_SUPPORT_EXPERT_COUNT) {
        return;
    }
    ds4_gpu_dspark_support_cache_entry *entry =
        &g_dspark_support_cache[stage][expert];
    if (!entry->valid) return;
    if (ds4_gpu_dspark_support_lease_pins(stage, expert)) return;
    const uint64_t bytes = entry->record_bytes;
    entry->buffer = nil;
    entry->source_offset = 0;
    entry->record_bytes = 0;
    entry->last_used = 0;
    entry->source_fd = -1;
    entry->valid = 0;
    if (g_dspark_support_cache_entry_count != 0) {
        g_dspark_support_cache_entry_count--;
    }
    if (g_dspark_support_cache_bytes >= bytes) {
        g_dspark_support_cache_bytes -= bytes;
    } else {
        g_dspark_support_cache_bytes = 0;
    }
    if (count_eviction) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_evictions, 1);
    }
}

static void ds4_gpu_dspark_support_cache_clear(int reset_stats) {
    if (g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_SUPPORT) {
        fprintf(stderr,
                "ds4: cannot clear DSpark SUPPORT cache while its lease is active\n");
        return;
    }
    for (uint32_t stage = 0; stage < DS4_DSPARK_SUPPORT_LAYER_COUNT; stage++) {
        for (uint32_t expert = 0;
             expert < DS4_DSPARK_SUPPORT_EXPERT_COUNT;
             expert++) {
            ds4_gpu_dspark_support_cache_clear_entry(stage, expert, 0);
        }
    }
    g_dspark_support_cache_entry_count = 0;
    g_dspark_support_cache_bytes = 0;
    if (reset_stats) {
        g_dspark_support_cache_hits = 0;
        g_dspark_support_cache_misses = 0;
        g_dspark_support_cache_evictions = 0;
        g_dspark_support_cache_expert_loads = 0;
        g_dspark_support_cache_pread_syscalls = 0;
        g_dspark_support_cache_pread_bytes = 0;
        g_dspark_support_cache_pread_ms = 0.0;
        g_dspark_support_cache_clock = 0;
        g_dspark_support_cache_lease_acquires = 0;
        g_dspark_support_cache_lease_releases = 0;
        g_dspark_support_cache_lease_failures = 0;
        g_dspark_support_cache_batch_rollbacks = 0;
        g_dspark_support_cache_release_already_completed_fences = 0;
        g_dspark_support_cache_release_sync_fences = 0;
        g_dspark_support_cache_release_fence_ms = 0.0;
        g_dspark_support_cache_peak_pinned = 0;
    }
}

static int ds4_gpu_stream_expert_cache_is_protected(
        uint32_t expert,
        const int32_t *protect_ids,
        uint32_t n_protect) {
    if (!protect_ids) return 0;
    for (uint32_t i = 0; i < n_protect; i++) {
        if (protect_ids[i] >= 0 && (uint32_t)protect_ids[i] == expert) {
            return 1;
        }
    }
    return 0;
}

static int hebrus_gpu_stream_expert_cache_layer_occupancy_matches(
        uint32_t layer,
        uint32_t expert_limit);
static uint32_t hebrus_gpu_stream_expert_cache_next(
        uint32_t layer,
        uint32_t expert_limit,
        uint32_t cursor,
        int      sparse);

static void ds4_gpu_stream_expert_cache_prune_layer(
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t n_selected,
        const int32_t *protect_ids,
        uint32_t n_protect) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return;
    uint32_t cap = ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                             n_total_expert,
                                                             n_selected);
    if (cap == 0) return;

    /*
     * Route hotness counts selected experts even when they miss.  Hit-count
     * LFU penalizes experts that are repeatedly selected but evicted before a
     * second hit, which keeps too many decode layers in the mixed-cache path.
     */
    while (g_stream_expert_cache_layer_count[layer] > cap) {
        uint32_t victim = UINT32_MAX;
        uint32_t lowest_hotness = UINT32_MAX;
        uint64_t oldest = UINT64_MAX;
        const int sparse =
            hebrus_gpu_stream_expert_qwen35_model() &&
            hebrus_gpu_stream_expert_cache_layer_occupancy_matches(
                layer, n_total_expert);
        for (uint32_t cursor = 0;;) {
            const uint32_t expert =
                hebrus_gpu_stream_expert_cache_next(
                    layer, n_total_expert, cursor, sparse);
            if (expert == UINT32_MAX) break;
            cursor = expert + 1u;
            ds4_gpu_stream_expert_cache_entry *e =
                &g_stream_expert_cache[layer][expert];
            if (!e->valid ||
                ds4_gpu_stream_expert_cache_entry_protected(layer,
                                                            expert,
                                                            layer,
                                                            protect_ids,
                                                            n_protect)) {
                continue;
            }
            const uint32_t hotness =
                g_stream_expert_cache_route_hotness[layer][expert];
            if (hotness < lowest_hotness ||
                (hotness == lowest_hotness && e->last_used < oldest)) {
                lowest_hotness = hotness;
                oldest = e->last_used;
                victim = expert;
            }
        }
        if (victim == UINT32_MAX) break;
        ds4_gpu_stream_expert_cache_clear_entry(layer, victim, 1);
    }
}

static int ds4_gpu_stream_expert_cache_entry_protected(
        uint32_t layer,
        uint32_t expert,
        uint32_t protect_layer,
        const int32_t *protect_ids,
        uint32_t n_protect) {
    if (ds4_gpu_stream_expert_cache_lease_protects(layer)) return 1;
    if (layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER &&
        expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT &&
        ds4_gpu_stream_expert_cache_entry_inflight(
                &g_stream_expert_cache[layer][expert])) {
        return 1;
    }
    return layer == protect_layer &&
           ds4_gpu_stream_expert_cache_is_protected(expert,
                                                    protect_ids,
                                                    n_protect);
}

static int ds4_gpu_stream_expert_cache_entry_reusable(
        const ds4_gpu_stream_expert_cache_entry *e,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (!e ||
        !e->valid ||
        !e->gate_buffer ||
        !e->up_buffer ||
        !e->down_buffer) {
        return 0;
    }
    if (e->gate_expert_bytes == gate_expert_bytes &&
        e->down_expert_bytes == down_expert_bytes) {
        return 1;
    }
    if (!e->slab_backed ||
        e->gate_buffer != e->up_buffer ||
        e->gate_buffer != e->down_buffer ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return 0;
    }
    const uint64_t logical_bytes =
        gate_expert_bytes * 2ull + down_expert_bytes;
    return g_stream_expert_cache_slab_slot_bytes != 0 &&
           logical_bytes <= g_stream_expert_cache_slab_slot_bytes;
}

static int ds4_gpu_stream_expert_reusable_buffers_relayout(
        ds4_gpu_stream_expert_reusable_buffers *reuse,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (!reuse ||
        !reuse->gate_buffer ||
        !reuse->up_buffer ||
        !reuse->down_buffer) {
        return 0;
    }
    if (reuse->gate_buffer != reuse->up_buffer ||
        reuse->gate_buffer != reuse->down_buffer) {
        return 1;
    }
    uint32_t slab_slot = UINT32_MAX;
    if (!ds4_gpu_stream_expert_slab_slot_for_buffer(
            reuse->gate_buffer, reuse->gate_inner, &slab_slot)) {
        return 1;
    }
    return ds4_gpu_stream_expert_slab_slot_buffers(
        slab_slot,
        gate_expert_bytes,
        down_expert_bytes,
        &reuse->gate_buffer,
        &reuse->up_buffer,
        &reuse->down_buffer,
        &reuse->gate_inner,
        &reuse->up_inner,
        &reuse->down_inner);
}

static uint32_t ds4_gpu_stream_expert_evict_fwd_distance(
        uint32_t entry_layer,
        uint32_t current_layer) {
    if (current_layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return 0;
    return (entry_layer + DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER - current_layer) %
           DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
}

/* Returns nonzero when the candidate is a better eviction victim than the
 * incumbent.  Primary key stays route hotness.  Qwen decode replaces the
 * recency tie-break across layers with forward layer distance: decode sweeps
 * layers in order, so an expert of a just-passed layer is not needed for
 * ~n_layers more steps, while plain LRU under a cache smaller than one sweep
 * evicts exactly the upcoming layers.  Same-layer ties remain LRU. */
static int hebrus_gpu_stream_expert_evict_better(
        uint32_t hotness_c, uint32_t layer_c, uint64_t last_c,
        uint32_t hotness_i, uint32_t layer_i, uint64_t last_i,
        uint32_t current_layer,
        int layer_staleness) {
    if (hotness_c != hotness_i) return hotness_c < hotness_i;
    if (layer_staleness && layer_c != layer_i) {
        return ds4_gpu_stream_expert_evict_fwd_distance(layer_c, current_layer) >
               ds4_gpu_stream_expert_evict_fwd_distance(layer_i, current_layer);
    }
    return last_c < last_i;
}

static int hebrus_gpu_stream_expert_qwen_layer_staleness(void) {
    return hebrus_gpu_stream_expert_qwen35_model();
}

static uint32_t hebrus_gpu_stream_expert_cache_expert_capacity(void) {
    return (uint32_t)(sizeof(g_stream_expert_cache[0]) /
                      sizeof(g_stream_expert_cache[0][0]));
}

static uint32_t hebrus_gpu_stream_expert_cache_scan_limit_value(
        uint32_t expert_limit) {
    const uint32_t expert_capacity =
        hebrus_gpu_stream_expert_cache_expert_capacity();
    return expert_limit != 0 &&
           expert_limit <= expert_capacity ?
        expert_limit : expert_capacity;
}

static int hebrus_gpu_stream_expert_cache_layer_limit_matches_value(
        uint32_t entry_count,
        uint32_t expert_limit,
        uint32_t n_total_expert) {
    return entry_count == 0 || expert_limit == n_total_expert;
}

static uint32_t hebrus_gpu_stream_expert_cache_scan_limit(uint32_t layer) {
    const uint32_t layer_capacity =
        (uint32_t)(sizeof(g_stream_expert_cache_layer_expert_limit) /
                   sizeof(g_stream_expert_cache_layer_expert_limit[0]));
    if (layer >= layer_capacity) {
        return hebrus_gpu_stream_expert_cache_expert_capacity();
    }
    return hebrus_gpu_stream_expert_cache_scan_limit_value(
        g_stream_expert_cache_layer_expert_limit[layer]);
}

static uint64_t hebrus_gpu_stream_expert_cache_occupancy_mask(
        uint32_t word,
        uint32_t expert_limit) {
    const uint32_t first_expert = word * 64u;
    if (first_expert >= expert_limit) return 0;
    const uint32_t remaining = expert_limit - first_expert;
    return remaining >= 64u ? UINT64_MAX : (1ull << remaining) - 1ull;
}

static int hebrus_gpu_stream_expert_cache_occupancy_matches_value(
        const uint64_t *words,
        uint32_t        word_count,
        uint32_t        expert_limit,
        uint32_t        expected_count) {
    if (!words || word_count == 0 || expert_limit == 0 ||
        expert_limit > word_count * 64u ||
        expected_count > expert_limit) {
        return 0;
    }
    uint32_t actual_count = 0;
    for (uint32_t word = 0; word < word_count; word++) {
        const uint64_t allowed =
            hebrus_gpu_stream_expert_cache_occupancy_mask(
                word, expert_limit);
        if ((words[word] & ~allowed) != 0) return 0;
        const uint32_t word_count_set =
            (uint32_t)__builtin_popcountll(words[word]);
        if (actual_count > UINT32_MAX - word_count_set) return 0;
        actual_count += word_count_set;
    }
    return actual_count == expected_count;
}

static int hebrus_gpu_stream_expert_cache_layer_occupancy_matches(
        uint32_t layer,
        uint32_t expert_limit) {
    if (layer >= HEBRUS_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return 0;
    return hebrus_gpu_stream_expert_cache_occupancy_matches_value(
        g_stream_expert_cache_layer_occupancy[layer],
        HEBRUS_METAL_STREAM_EXPERT_CACHE_OCCUPANCY_WORDS,
        expert_limit,
        g_stream_expert_cache_layer_count[layer]);
}

static uint32_t hebrus_gpu_stream_expert_cache_next_value(
        const uint64_t *words,
        uint32_t        word_count,
        uint32_t        expert_limit,
        uint32_t        cursor,
        int             sparse) {
    if (cursor >= expert_limit) return UINT32_MAX;
    if (!sparse) return cursor;

    uint32_t word = cursor / 64u;
    if (!words || word >= word_count) return UINT32_MAX;
    uint64_t candidates =
        words[word] & (UINT64_MAX << (cursor % 64u));
    for (;;) {
        if (candidates != 0) {
            const uint32_t expert =
                word * 64u + (uint32_t)__builtin_ctzll(candidates);
            return expert < expert_limit ? expert : UINT32_MAX;
        }
        word++;
        if (word >= word_count || word * 64u >= expert_limit) {
            return UINT32_MAX;
        }
        candidates = words[word];
    }
}

static uint32_t hebrus_gpu_stream_expert_cache_next(
        uint32_t layer,
        uint32_t expert_limit,
        uint32_t cursor,
        int      sparse) {
    if (layer >= HEBRUS_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) {
        return UINT32_MAX;
    }
    return hebrus_gpu_stream_expert_cache_next_value(
        g_stream_expert_cache_layer_occupancy[layer],
        HEBRUS_METAL_STREAM_EXPERT_CACHE_OCCUPANCY_WORDS,
        expert_limit,
        cursor,
        sparse);
}

int hebrus_gpu_internal_stream_expert_cache_scan_limit_test(void) {
    const uint32_t expert_capacity =
        hebrus_gpu_stream_expert_cache_expert_capacity();
    const uint64_t occupied[] = {
        (1ull << 0u) | (1ull << 63u),
        (1ull << 1u),
        0,
        (1ull << 63u),
        0,
        0,
    };
    const uint64_t outside_limit[] = {
        0, 0, 0, 0, (1ull << 44u), 0,
    };
    const uint64_t partial_limit[] = {
        0, 0, (1ull << 1u), 0, 0, 0,
    };
    const uint64_t outside_partial_limit[] = {
        0, 0, (1ull << 2u), 0, 0, 0,
    };
    int ok =
        hebrus_gpu_stream_expert_qwen35_model_value(
            0, 1, 1, QWEN35_N_LAYER, QWEN35_N_EXPERT) &&
        !hebrus_gpu_stream_expert_qwen35_model_value(
            1, 1, 1, QWEN35_N_LAYER, QWEN35_N_EXPERT) &&
        !hebrus_gpu_stream_expert_qwen35_model_value(
            0, 1, 1, QWEN35_N_LAYER - 1u, QWEN35_N_EXPERT) &&
        !hebrus_gpu_stream_expert_qwen35_model_value(
            0, 1, 0, QWEN35_N_LAYER, QWEN35_N_EXPERT) &&
        hebrus_gpu_stream_expert_cache_scan_limit_value(128) == 128 &&
        hebrus_gpu_stream_expert_cache_scan_limit_value(256) == 256 &&
        hebrus_gpu_stream_expert_cache_scan_limit_value(384) == 384 &&
        hebrus_gpu_stream_expert_cache_scan_limit_value(0) ==
            expert_capacity &&
        hebrus_gpu_stream_expert_cache_scan_limit_value(
            expert_capacity + 1u) == expert_capacity &&
        hebrus_gpu_stream_expert_cache_layer_limit_matches_value(
            0, 0, 256) &&
        hebrus_gpu_stream_expert_cache_layer_limit_matches_value(
            1, 256, 256) &&
        !hebrus_gpu_stream_expert_cache_layer_limit_matches_value(
            1, 128, 256) &&
        hebrus_gpu_stream_expert_cache_occupancy_matches_value(
            occupied, 6, 256, 4) &&
        !hebrus_gpu_stream_expert_cache_occupancy_matches_value(
            occupied, 6, 256, 3) &&
        !hebrus_gpu_stream_expert_cache_occupancy_matches_value(
            outside_limit, 6, 256, 1) &&
        hebrus_gpu_stream_expert_cache_occupancy_matches_value(
            partial_limit, 6, 130, 1) &&
        !hebrus_gpu_stream_expert_cache_occupancy_matches_value(
            outside_partial_limit, 6, 130, 1) &&
        hebrus_gpu_stream_expert_evict_better(
            1, 19, 200, 2, 21, 100, 20, 0) &&
        !hebrus_gpu_stream_expert_evict_better(
            2, 19, 50, 1, 21, 100, 20, 1) &&
        !hebrus_gpu_stream_expert_evict_better(
            1, 19, 200, 1, 21, 100, 20, 0) &&
        hebrus_gpu_stream_expert_evict_better(
            1, 19, 200, 1, 21, 100, 20, 1) &&
        !hebrus_gpu_stream_expert_evict_better(
            1, 21, 100, 1, 19, 200, 20, 1) &&
        hebrus_gpu_stream_expert_evict_better(
            1, 20, 50, 1, 20, 100, 20, 1);
    uint32_t cursor = 0;
    const uint32_t expected[] = { 0, 63, 65, 255 };
    for (uint32_t i = 0;
         ok && i < sizeof(expected) / sizeof(expected[0]);
         i++) {
        const uint32_t expert =
            hebrus_gpu_stream_expert_cache_next_value(
                occupied, 6, 256, cursor, 1);
        ok = expert == expected[i];
        cursor = expert + 1u;
    }
    return ok &&
        hebrus_gpu_stream_expert_cache_next_value(
            occupied, 6, 256, cursor, 1) == UINT32_MAX &&
        hebrus_gpu_stream_expert_cache_next_value(
            occupied, 6, 256, 17, 0) == 17;
}

static int ds4_gpu_stream_expert_cache_take_reusable(
        int                                     force_reuse,
        uint32_t                                protect_layer,
        const int32_t                          *protect_ids,
        uint32_t                                n_protect,
        uint64_t                                gate_expert_bytes,
        uint64_t                                down_expert_bytes,
        ds4_gpu_stream_expert_reusable_buffers *reuse) {
    if (!reuse) return 0;
    reuse->gate_buffer = nil;
    reuse->up_buffer = nil;
    reuse->down_buffer = nil;
    reuse->gate_inner = 0;
    reuse->up_inner = 0;
    reuse->down_inner = 0;

    const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    if (budget == 0 ||
        (!force_reuse && g_stream_expert_cache_entry_count < budget)) {
        return 0;
    }

    int waited_inflight = 0;
retry:
    ;
    uint32_t victim_layer = UINT32_MAX;
    uint32_t victim_expert = UINT32_MAX;
    uint32_t lowest_hotness = UINT32_MAX;
    uint64_t oldest = UINT64_MAX;
    int skipped_inflight = 0;
    const int layer_staleness =
        hebrus_gpu_stream_expert_qwen_layer_staleness();
    const int qwen_cache_index =
        hebrus_gpu_stream_expert_qwen35_model();
    const int timing = ds4_gpu_stream_expert_timing_summary_enabled();
    const double scan_t0 = timing ? ds4_gpu_now_ms() : 0.0;
    uint64_t scan_entries = 0;
    for (uint32_t layer = 0;
         layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
         layer++) {
        if (qwen_cache_index &&
            g_stream_expert_cache_layer_count[layer] == 0) continue;
        const uint32_t expert_limit = qwen_cache_index ?
            hebrus_gpu_stream_expert_cache_scan_limit(layer) :
            HEBRUS_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
        const int sparse =
            qwen_cache_index &&
            hebrus_gpu_stream_expert_cache_layer_occupancy_matches(
                layer, expert_limit);
        for (uint32_t cursor = 0;;) {
            const uint32_t expert =
                hebrus_gpu_stream_expert_cache_next(
                    layer, expert_limit, cursor, sparse);
            if (expert == UINT32_MAX) break;
            cursor = expert + 1u;
            scan_entries++;
            ds4_gpu_stream_expert_cache_entry *e =
                &g_stream_expert_cache[layer][expert];
            if (!ds4_gpu_stream_expert_cache_entry_reusable(e,
                                                            gate_expert_bytes,
                                                            down_expert_bytes)) {
                continue;
            }
            if (ds4_gpu_stream_expert_cache_entry_inflight(e)) {
                skipped_inflight = 1;
                continue;
            }
            if (ds4_gpu_stream_expert_cache_entry_protected(layer,
                                                            expert,
                                                            protect_layer,
                                                            protect_ids,
                                                            n_protect)) {
                continue;
            }
            const uint32_t hotness =
                g_stream_expert_cache_route_hotness[layer][expert];
            if (victim_layer == UINT32_MAX ||
                hebrus_gpu_stream_expert_evict_better(hotness,
                                                   layer,
                                                   e->last_used,
                                                   lowest_hotness,
                                                   victim_layer,
                                                   oldest,
                                                   protect_layer,
                                                   layer_staleness)) {
                lowest_hotness = hotness;
                oldest = e->last_used;
                victim_layer = layer;
                victim_expert = expert;
            }
        }
    }
    if (timing) {
        ds4_gpu_stream_expert_timing_note_reuse_scan(scan_entries,
                                                     ds4_gpu_now_ms() - scan_t0);
    }

    if (victim_layer == UINT32_MAX || victim_expert == UINT32_MAX) {
        if (skipped_inflight && !waited_inflight) {
            waited_inflight = 1;
            if (!ds4_gpu_stream_expert_cache_wait_inflight(
                    "streaming expert cache reuse")) {
                return 0;
            }
            goto retry;
        }
        return 0;
    }
    const double clear_t0 = timing ? ds4_gpu_now_ms() : 0.0;
    ds4_gpu_stream_expert_cache_clear_entry_internal(victim_layer,
                                                     victim_expert,
                                                     1,
                                                     1,
                                                     reuse);
    if (timing) {
        ds4_gpu_stream_expert_timing_note_reuse_clear(ds4_gpu_now_ms() -
                                                      clear_t0);
    }
    if (!reuse->gate_buffer || !reuse->up_buffer || !reuse->down_buffer) {
        reuse->gate_buffer = nil;
        reuse->up_buffer = nil;
        reuse->down_buffer = nil;
        reuse->gate_inner = 0;
        reuse->up_inner = 0;
        reuse->down_inner = 0;
        return 0;
    }
    if (!ds4_gpu_stream_expert_reusable_buffers_relayout(
            reuse, gate_expert_bytes, down_expert_bytes)) {
        reuse->gate_buffer = nil;
        reuse->up_buffer = nil;
        reuse->down_buffer = nil;
        reuse->gate_inner = 0;
        reuse->up_inner = 0;
        reuse->down_inner = 0;
        return 0;
    }
    g_stream_expert_cache_buffer_reuses +=
        ds4_gpu_stream_expert_buffer_object_count(reuse->gate_buffer,
                                                  reuse->up_buffer,
                                                  reuse->down_buffer);
    return 1;
}

static uint32_t ds4_gpu_stream_expert_cache_release_mlock_margin(
        uint32_t       protect_layer,
        const int32_t *protect_ids,
        uint32_t       n_protect) {
    if (g_stream_expert_cache_mlock_relief_applied ||
        g_stream_expert_cache_slab_slot_bytes == 0) {
        return 0;
    }

    const uint32_t locked_before =
        ds4_gpu_stream_expert_slab_locked_slot_count();
    if (locked_before == 0) return 0;

    const uint32_t target_release = (locked_before + 9u) / 10u;
    uint32_t released = 0;
    const int qwen_cache_index =
        hebrus_gpu_stream_expert_qwen35_model();
    while (released < target_release) {
        uint32_t victim_layer = UINT32_MAX;
        uint32_t victim_expert = UINT32_MAX;
        uint32_t victim_slot = UINT32_MAX;
        uint32_t lowest_hotness = UINT32_MAX;
        uint64_t oldest = UINT64_MAX;

        for (uint32_t layer = 0;
             layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
             layer++) {
            if (qwen_cache_index &&
                g_stream_expert_cache_layer_count[layer] == 0) continue;
            const uint32_t expert_limit = qwen_cache_index ?
                hebrus_gpu_stream_expert_cache_scan_limit(layer) :
                HEBRUS_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
            const int sparse =
                qwen_cache_index &&
                hebrus_gpu_stream_expert_cache_layer_occupancy_matches(
                    layer, expert_limit);
            for (uint32_t cursor = 0;;) {
                const uint32_t expert =
                    hebrus_gpu_stream_expert_cache_next(
                        layer, expert_limit, cursor, sparse);
                if (expert == UINT32_MAX) break;
                cursor = expert + 1u;
                ds4_gpu_stream_expert_cache_entry *e =
                    &g_stream_expert_cache[layer][expert];
                if (!e->valid ||
                    !e->slab_backed ||
                    e->slab_slot >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES ||
                    !g_stream_expert_cache_slab_slot_locked[e->slab_slot] ||
                    ds4_gpu_stream_expert_cache_entry_protected(layer,
                                                                expert,
                                                                protect_layer,
                                                                protect_ids,
                                                                n_protect)) {
                    continue;
                }
                const uint32_t hotness =
                    g_stream_expert_cache_route_hotness[layer][expert];
                if (hotness < lowest_hotness ||
                    (hotness == lowest_hotness && e->last_used < oldest)) {
                    lowest_hotness = hotness;
                    oldest = e->last_used;
                    victim_layer = layer;
                    victim_expert = expert;
                    victim_slot = e->slab_slot;
                }
            }
        }

        if (victim_layer == UINT32_MAX ||
            victim_expert == UINT32_MAX ||
            victim_slot == UINT32_MAX) {
            break;
        }

        ds4_gpu_stream_expert_cache_clear_entry_internal(victim_layer,
                                                         victim_expert,
                                                         1,
                                                         0,
                                                         NULL);
        if (ds4_gpu_stream_expert_slab_unlock_slot(victim_slot)) {
            released++;
        }
    }

    if (released == 0) return 0;
    g_stream_expert_cache_mlock_relief_applied = 1;

    uint32_t cap = g_stream_expert_cache_entry_count;
    const uint32_t locked_after =
        ds4_gpu_stream_expert_slab_locked_slot_count();
    if (locked_after != 0 && locked_after < cap) cap = locked_after;
    if (!g_stream_expert_cache_mlock_budget_cap_active ||
        cap < g_stream_expert_cache_mlock_budget_cap) {
        g_stream_expert_cache_mlock_budget_cap = cap;
    }
    g_stream_expert_cache_mlock_budget_cap_active = 1;
    ds4_gpu_dspark_support_cache_target_cap_changed();

    const uint64_t released_bytes =
        (uint64_t)released * g_stream_expert_cache_slab_slot_bytes;
    fprintf(stderr,
            "ds4:   released locked cache margin: %u experts / %.2f GiB; "
            "runtime cache cap now %u experts\n",
            released,
            ds4_gpu_gib(released_bytes),
            g_stream_expert_cache_mlock_budget_cap);
    return released;
}

static uint32_t ds4_gpu_stream_expert_cache_take_reusable_batch(
        uint32_t                                n_needed,
        uint32_t                                protect_layer,
        const int32_t                          *protect_ids,
        uint32_t                                n_protect,
        uint64_t                                gate_expert_bytes,
        uint64_t                                down_expert_bytes,
        ds4_gpu_stream_expert_reusable_buffers *reuses) {
    if (!reuses || n_needed == 0) return 0;
    if (n_needed > DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED) {
        n_needed = DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED;
    }
    for (uint32_t i = 0; i < n_needed; i++) {
        reuses[i].gate_buffer = nil;
        reuses[i].up_buffer = nil;
        reuses[i].down_buffer = nil;
        reuses[i].gate_inner = 0;
        reuses[i].up_inner = 0;
        reuses[i].down_inner = 0;
    }

    const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    if (budget == 0 || g_stream_expert_cache_entry_count < budget) {
        return 0;
    }

    int waited_inflight = 0;
retry:
    ;
    uint32_t victim_layers[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint32_t victim_experts[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint32_t victim_hotness[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint64_t victim_last_used[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint32_t victim_count = 0;
    int skipped_inflight = 0;
    const int layer_staleness =
        hebrus_gpu_stream_expert_qwen_layer_staleness();
    const int qwen_cache_index =
        hebrus_gpu_stream_expert_qwen35_model();
    const int timing = ds4_gpu_stream_expert_timing_summary_enabled();
    const double scan_t0 = timing ? ds4_gpu_now_ms() : 0.0;
    uint64_t scan_entries = 0;
    for (uint32_t i = 0; i < n_needed; i++) {
        victim_layers[i] = UINT32_MAX;
        victim_experts[i] = UINT32_MAX;
        victim_hotness[i] = UINT32_MAX;
        victim_last_used[i] = UINT64_MAX;
    }

    for (uint32_t layer = 0;
         layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
         layer++) {
        if (qwen_cache_index &&
            g_stream_expert_cache_layer_count[layer] == 0) continue;
        const uint32_t expert_limit = qwen_cache_index ?
            hebrus_gpu_stream_expert_cache_scan_limit(layer) :
            HEBRUS_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
        const int sparse =
            qwen_cache_index &&
            hebrus_gpu_stream_expert_cache_layer_occupancy_matches(
                layer, expert_limit);
        for (uint32_t cursor = 0;;) {
            const uint32_t expert =
                hebrus_gpu_stream_expert_cache_next(
                    layer, expert_limit, cursor, sparse);
            if (expert == UINT32_MAX) break;
            cursor = expert + 1u;
            scan_entries++;
            ds4_gpu_stream_expert_cache_entry *e =
                &g_stream_expert_cache[layer][expert];
            if (!ds4_gpu_stream_expert_cache_entry_reusable(e,
                                                            gate_expert_bytes,
                                                            down_expert_bytes)) {
                continue;
            }
            if (ds4_gpu_stream_expert_cache_entry_inflight(e)) {
                skipped_inflight = 1;
                continue;
            }
            if (ds4_gpu_stream_expert_cache_entry_protected(layer,
                                                            expert,
                                                            protect_layer,
                                                            protect_ids,
                                                            n_protect)) {
                continue;
            }

            const uint32_t hotness =
                g_stream_expert_cache_route_hotness[layer][expert];
            const uint64_t last_used = e->last_used;
            if (victim_count < n_needed) {
                victim_layers[victim_count] = layer;
                victim_experts[victim_count] = expert;
                victim_hotness[victim_count] = hotness;
                victim_last_used[victim_count] = last_used;
                victim_count++;
                continue;
            }

            uint32_t worst = 0;
            for (uint32_t i = 1; i < victim_count; i++) {
                if (hebrus_gpu_stream_expert_evict_better(victim_hotness[worst],
                                                       victim_layers[worst],
                                                       victim_last_used[worst],
                                                       victim_hotness[i],
                                                       victim_layers[i],
                                                       victim_last_used[i],
                                                       protect_layer,
                                                       layer_staleness)) {
                    worst = i;
                }
            }
            if (hebrus_gpu_stream_expert_evict_better(hotness,
                                                   layer,
                                                   last_used,
                                                   victim_hotness[worst],
                                                   victim_layers[worst],
                                                   victim_last_used[worst],
                                                   protect_layer,
                                                   layer_staleness)) {
                victim_layers[worst] = layer;
                victim_experts[worst] = expert;
                victim_hotness[worst] = hotness;
                victim_last_used[worst] = last_used;
            }
        }
    }
    if (timing) {
        ds4_gpu_stream_expert_timing_note_reuse_scan(scan_entries,
                                                     ds4_gpu_now_ms() - scan_t0);
    }

    if (victim_count == 0) {
        if (skipped_inflight && !waited_inflight) {
            waited_inflight = 1;
            if (!ds4_gpu_stream_expert_cache_wait_inflight(
                    "streaming expert cache batch reuse")) {
                return 0;
            }
            goto retry;
        }
        return 0;
    }

    uint32_t reuse_count = 0;
    const double clear_t0 = timing ? ds4_gpu_now_ms() : 0.0;
    for (uint32_t i = 0; i < victim_count; i++) {
        if (victim_layers[i] == UINT32_MAX ||
            victim_experts[i] == UINT32_MAX) {
            continue;
        }
        ds4_gpu_stream_expert_cache_clear_entry_internal(victim_layers[i],
                                                         victim_experts[i],
                                                         1,
                                                         1,
                                                         &reuses[reuse_count]);
        if (!reuses[reuse_count].gate_buffer ||
            !reuses[reuse_count].up_buffer ||
            !reuses[reuse_count].down_buffer) {
            reuses[reuse_count].gate_buffer = nil;
            reuses[reuse_count].up_buffer = nil;
            reuses[reuse_count].down_buffer = nil;
            reuses[reuse_count].gate_inner = 0;
            reuses[reuse_count].up_inner = 0;
            reuses[reuse_count].down_inner = 0;
            continue;
        }
        if (!ds4_gpu_stream_expert_reusable_buffers_relayout(
                &reuses[reuse_count],
                gate_expert_bytes,
                down_expert_bytes)) {
            reuses[reuse_count].gate_buffer = nil;
            reuses[reuse_count].up_buffer = nil;
            reuses[reuse_count].down_buffer = nil;
            reuses[reuse_count].gate_inner = 0;
            reuses[reuse_count].up_inner = 0;
            reuses[reuse_count].down_inner = 0;
            continue;
        }
        g_stream_expert_cache_buffer_reuses +=
            ds4_gpu_stream_expert_buffer_object_count(
                    reuses[reuse_count].gate_buffer,
                    reuses[reuse_count].up_buffer,
                    reuses[reuse_count].down_buffer);
        reuse_count++;
    }

    if (timing) {
        ds4_gpu_stream_expert_timing_note_reuse_clear(ds4_gpu_now_ms() -
                                                      clear_t0);
    }
    return reuse_count;
}

static int ds4_gpu_stream_expert_batch_reuse_enabled(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    /*
     * One global victim scan per selected miss is measurable for GLM Q2-size
     * slots, but batching larger Q4-size slots regressed short decode on M5.
     * DeepSeek also regresses even though its smaller IQ2 record fits the byte
     * threshold, so the pure policy helper keeps this optimization GLM-only.
     */
    return ds4_ssd_glm_streaming_batch_reuse_allowed(
        g_glm_model_mode != 0,
        gate_expert_bytes,
        down_expert_bytes);
}

static int ds4_gpu_stream_expert_cache_prepare_load_buffers(
        uint32_t       layer,
        uint32_t       expert,
        uint32_t       protect_layer,
        const int32_t *protect_ids,
        uint32_t       n_protect,
        uint64_t       gate_expert_bytes,
        uint64_t       down_expert_bytes,
        int            force_reuse,
        __strong id<MTLBuffer> *gate_buf,
        __strong id<MTLBuffer> *up_buf,
        __strong id<MTLBuffer> *down_buf,
        NSUInteger    *gate_inner,
        NSUInteger    *up_inner,
        NSUInteger    *down_inner) {
    if (!gate_buf || !up_buf || !down_buf ||
        !gate_inner || !up_inner || !down_inner ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        return 0;
    }

    *gate_buf = nil;
    *up_buf = nil;
    *down_buf = nil;
    *gate_inner = 0;
    *up_inner = 0;
    *down_inner = 0;

    ds4_gpu_stream_expert_reusable_buffers reuse = { nil, nil, nil, 0, 0, 0 };
    ds4_gpu_stream_expert_cache_entry *e =
        &g_stream_expert_cache[layer][expert];
    if (e->valid && ds4_gpu_stream_expert_cache_entry_inflight(e)) {
        if (!ds4_gpu_stream_expert_cache_wait_inflight(
                "streaming expert cache replacement")) {
            return 0;
        }
        e = &g_stream_expert_cache[layer][expert];
    }
    if (ds4_gpu_stream_expert_cache_entry_reusable(e,
                                                   gate_expert_bytes,
                                                   down_expert_bytes)) {
        ds4_gpu_stream_expert_cache_clear_entry_internal(layer,
                                                         expert,
                                                         0,
                                                         1,
                                                         &reuse);
        if (reuse.gate_buffer && reuse.up_buffer && reuse.down_buffer) {
            g_stream_expert_cache_buffer_reuses +=
                ds4_gpu_stream_expert_buffer_object_count(reuse.gate_buffer,
                                                          reuse.up_buffer,
                                                          reuse.down_buffer);
        }
    } else if (e->valid) {
        ds4_gpu_stream_expert_cache_clear_entry(layer, expert, 0);
    }

    if (!reuse.gate_buffer || !reuse.up_buffer || !reuse.down_buffer) {
        if (!ds4_gpu_stream_expert_cache_take_reusable(force_reuse,
                                                       protect_layer,
                                                       protect_ids,
                                                       n_protect,
                                                       gate_expert_bytes,
                                                       down_expert_bytes,
                                                       &reuse)) {
            /* At the hard budget, inability to find an unleased victim is a
             * capacity failure. Falling through to a fresh buffer would make
             * a layer lease silently exceed the frozen request envelope. */
            if (force_reuse) return 0;
            reuse.gate_buffer = nil;
            reuse.up_buffer = nil;
            reuse.down_buffer = nil;
        }
    }

    if (reuse.gate_buffer && reuse.up_buffer && reuse.down_buffer) {
        if (!ds4_gpu_stream_expert_reusable_buffers_relayout(
                &reuse, gate_expert_bytes, down_expert_bytes)) {
            return 0;
        }
        *gate_buf = reuse.gate_buffer;
        *up_buf = reuse.up_buffer;
        *down_buf = reuse.down_buffer;
        *gate_inner = reuse.gate_inner;
        *up_inner = reuse.up_inner;
        *down_inner = reuse.down_inner;
        return 1;
    }

    if (ds4_gpu_stream_expert_combined_buffer_enabled()) {
        if (gate_expert_bytes > UINT64_MAX - gate_expert_bytes ||
            gate_expert_bytes * 2ull > UINT64_MAX - down_expert_bytes ||
            gate_expert_bytes > (uint64_t)NSUIntegerMax ||
            gate_expert_bytes * 2ull > (uint64_t)NSUIntegerMax ||
            gate_expert_bytes * 2ull + down_expert_bytes >
                (uint64_t)NSUIntegerMax) {
            return 0;
        }
        if (g_stream_expert_cache_mlock_budget_cap_active &&
            g_stream_expert_cache_mlock_budget_cap != 0) {
            ds4_gpu_stream_expert_cache_release_mlock_margin(protect_layer,
                                                             protect_ids,
                                                             n_protect);
            if (!ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
                return 0;
            }
            if (!ds4_gpu_stream_expert_cache_take_reusable(1,
                                                           protect_layer,
                                                           protect_ids,
                                                           n_protect,
                                                           gate_expert_bytes,
                                                           down_expert_bytes,
                                                           &reuse)) {
                return 0;
            }
            *gate_buf = reuse.gate_buffer;
            *up_buf = reuse.up_buffer;
            *down_buf = reuse.down_buffer;
            *gate_inner = reuse.gate_inner;
            *up_inner = reuse.up_inner;
            *down_inner = reuse.down_inner;
            return *gate_buf && *up_buf && *down_buf;
        }
        const ds4_stream_expert_slab_result slab_result =
            ds4_gpu_stream_expert_alloc_slab_slot(gate_expert_bytes,
                                                  down_expert_bytes,
                                                  gate_buf,
                                                  up_buf,
                                                  down_buf,
                                                  gate_inner,
                                                  up_inner,
                                                  down_inner);
        if (slab_result == DS4_STREAM_EXPERT_SLAB_OK) {
            return 1;
        }
        if (slab_result == DS4_STREAM_EXPERT_SLAB_REUSE_REQUIRED) {
            if (!ds4_gpu_stream_expert_cache_required_floor_satisfied() ||
                !ds4_gpu_stream_expert_cache_take_reusable(
                    1,
                    protect_layer,
                    protect_ids,
                    n_protect,
                    gate_expert_bytes,
                    down_expert_bytes,
                    &reuse)) {
                return 0;
            }
            *gate_buf = reuse.gate_buffer;
            *up_buf = reuse.up_buffer;
            *down_buf = reuse.down_buffer;
            *gate_inner = reuse.gate_inner;
            *up_inner = reuse.up_inner;
            *down_inner = reuse.down_inner;
            return *gate_buf && *up_buf && *down_buf;
        }
        if (!ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
            return 0;
        }
        if (g_stream_expert_cache_mlock_budget_cap_active &&
            g_stream_expert_cache_mlock_budget_cap != 0) {
            ds4_gpu_stream_expert_cache_release_mlock_margin(protect_layer,
                                                             protect_ids,
                                                             n_protect);
            if (!ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
                return 0;
            }
            if (!ds4_gpu_stream_expert_cache_take_reusable(1,
                                                           protect_layer,
                                                           protect_ids,
                                                           n_protect,
                                                           gate_expert_bytes,
                                                           down_expert_bytes,
                                                           &reuse)) {
                return 0;
            }
            *gate_buf = reuse.gate_buffer;
            *up_buf = reuse.up_buffer;
            *down_buf = reuse.down_buffer;
            *gate_inner = reuse.gate_inner;
            *up_inner = reuse.up_inner;
            *down_inner = reuse.down_inner;
            return *gate_buf && *up_buf && *down_buf;
        }
        const uint64_t up_off = gate_expert_bytes;
        const uint64_t down_off = gate_expert_bytes * 2ull;
        const uint64_t combined_bytes = down_off + down_expert_bytes;
        id<MTLBuffer> combined =
            ds4_gpu_stream_expert_alloc_buffer(combined_bytes,
                                               @"ds4_stream_expert_combined");
        if (!combined ||
            !ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
            return 0;
        }
        *gate_buf = combined;
        *up_buf = combined;
        *down_buf = combined;
        *gate_inner = 0;
        *up_inner = (NSUInteger)up_off;
        *down_inner = (NSUInteger)down_off;
        return 1;
    }

    *gate_buf = ds4_gpu_stream_expert_alloc_buffer(gate_expert_bytes,
                                                   @"ds4_stream_expert_gate");
    *up_buf = ds4_gpu_stream_expert_alloc_buffer(gate_expert_bytes,
                                                 @"ds4_stream_expert_up");
    *down_buf = ds4_gpu_stream_expert_alloc_buffer(down_expert_bytes,
                                                   @"ds4_stream_expert_down");
    if (!ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
        *gate_buf = nil;
        *up_buf = nil;
        *down_buf = nil;
        return 0;
    }
    return *gate_buf && *up_buf && *down_buf;
}

static void ds4_gpu_stream_expert_cache_prune_global(
        uint32_t protect_layer,
        const int32_t *protect_ids,
        uint32_t n_protect) {
    const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    if (budget == 0 || g_stream_expert_cache_entry_count <= budget) return;
    const int layer_staleness =
        hebrus_gpu_stream_expert_qwen_layer_staleness();
    const int qwen_cache_index =
        hebrus_gpu_stream_expert_qwen35_model();

    while (g_stream_expert_cache_entry_count > budget) {
        uint32_t victim_layer = UINT32_MAX;
        uint32_t victim_expert = UINT32_MAX;
        uint32_t lowest_hotness = UINT32_MAX;
        uint64_t oldest = UINT64_MAX;
        for (uint32_t layer = 0;
             layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
             layer++) {
            if (qwen_cache_index &&
                g_stream_expert_cache_layer_count[layer] == 0) continue;
            const uint32_t expert_limit = qwen_cache_index ?
                hebrus_gpu_stream_expert_cache_scan_limit(layer) :
                HEBRUS_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
            const int sparse =
                qwen_cache_index &&
                hebrus_gpu_stream_expert_cache_layer_occupancy_matches(
                    layer, expert_limit);
            for (uint32_t cursor = 0;;) {
                const uint32_t expert =
                    hebrus_gpu_stream_expert_cache_next(
                        layer, expert_limit, cursor, sparse);
                if (expert == UINT32_MAX) break;
                cursor = expert + 1u;
                ds4_gpu_stream_expert_cache_entry *e =
                    &g_stream_expert_cache[layer][expert];
                if (!e->valid ||
                    ds4_gpu_stream_expert_cache_entry_protected(layer,
                                                                expert,
                                                                protect_layer,
                                                                protect_ids,
                                                                n_protect)) {
                    continue;
                }
                const uint32_t hotness =
                    g_stream_expert_cache_route_hotness[layer][expert];
                if (victim_layer == UINT32_MAX ||
                    hebrus_gpu_stream_expert_evict_better(hotness,
                                                       layer,
                                                       e->last_used,
                                                       lowest_hotness,
                                                       victim_layer,
                                                       oldest,
                                                       protect_layer,
                                                       layer_staleness)) {
                    lowest_hotness = hotness;
                    oldest = e->last_used;
                    victim_layer = layer;
                    victim_expert = expert;
                }
            }
        }
        if (victim_layer == UINT32_MAX || victim_expert == UINT32_MAX) break;
        ds4_gpu_stream_expert_cache_clear_entry(victim_layer, victim_expert, 1);
    }
}

/* Reconcile a descriptor/budget transition before SUPPORT can become visible.
 * TARGET cache slots may still be referenced by queued Metal work, so a late
 * SUPPORT activation fences and drains the existing owner before pruning the
 * newly reserved SUPPORT share. */
static int ds4_gpu_dspark_reconcile_synchronize(void) {
#ifdef DS4_TEST_HOOKS
    g_dspark_reconcile_synchronize_calls++;
#endif
    return ds4_gpu_synchronize();
}

/* A false->true combined transition may change the physical TARGET share from
 * the parent budget to parent-31. Existing TARGET slabs cannot be resized, so
 * activation must fail without touching them; the caller rolls back the mode
 * or SUPPORT descriptor that made the pairing visible. */
static int ds4_gpu_dspark_support_cache_activate_combined(void) {
    if (!ds4_gpu_dspark_support_cache_combined_available() ||
        g_stream_expert_cache_slab_count != 0 ||
        g_stream_expert_cache_slab_total_slots != 0) {
        return 0;
    }
    /* With no physical slab geometry to resize, the generic transition can
     * safely drain and prune explicit/non-slab entries to the new envelope.
     * At startup parent==0 and both caches are empty, so this is a fence-only
     * descriptor activation before the later 290/4160 budget is configured. */
    return ds4_gpu_dspark_support_cache_reconcile_transition(1);
}

static int ds4_gpu_dspark_support_cache_reconcile_transition(int fence) {
    const uint32_t target_budget =
        ds4_gpu_stream_expert_cache_configured_budget();
    const uint32_t support_budget =
        ds4_gpu_dspark_support_cache_configured_budget();
    const uint32_t parent_budget =
        ds4_gpu_stream_expert_cache_parent_budget(0);
    const int target_over =
        g_stream_expert_cache_entry_count > target_budget;
    const int support_over =
        g_dspark_support_cache_entry_count > support_budget;
    const int total_over =
        g_stream_expert_cache_entry_count > UINT32_MAX -
            g_dspark_support_cache_entry_count ||
        g_stream_expert_cache_entry_count +
            g_dspark_support_cache_entry_count > parent_budget;
    if (fence) {
        if (g_stream_expert_cache_lease.active ||
            g_stream_expert_pending_load.active ||
            g_qwen35_stream_pending.state != DS4_QWEN35_STREAM_IO_EMPTY ||
            !ds4_gpu_dspark_reconcile_synchronize() ||
            !ds4_gpu_stream_expert_pending_load_finish(NULL) ||
            !ds4_gpu_dspark_reconcile_synchronize()) {
            return 0;
        }
    } else if (g_stream_expert_cache_lease.active ||
               g_stream_expert_pending_load.active ||
               g_qwen35_stream_pending.state !=
                   DS4_QWEN35_STREAM_IO_EMPTY) {
        return 0;
    }
    if (!target_over && !support_over && !total_over) return 1;
    if (g_stream_expert_cache_entry_count > target_budget) {
        if (target_budget == 0) {
            ds4_gpu_stream_expert_cache_clear_all(0);
        } else {
            ds4_gpu_stream_expert_cache_prune_global(
                UINT32_MAX, NULL, 0);
        }
    }
    if (g_stream_expert_cache_entry_count > target_budget) return 0;
    if (g_dspark_support_cache_entry_count > support_budget) {
        ds4_gpu_dspark_support_cache_clear(0);
    }
    if (g_stream_expert_cache_entry_count > UINT32_MAX -
            g_dspark_support_cache_entry_count ||
        g_stream_expert_cache_entry_count +
            g_dspark_support_cache_entry_count > parent_budget) {
        ds4_gpu_dspark_support_cache_clear(0);
    }
    return g_stream_expert_cache_entry_count <= target_budget &&
           g_dspark_support_cache_entry_count <= support_budget &&
           g_stream_expert_cache_entry_count <= UINT32_MAX -
               g_dspark_support_cache_entry_count &&
           g_stream_expert_cache_entry_count +
               g_dspark_support_cache_entry_count <= parent_budget;
}

static int ds4_gpu_stream_expert_cache_entry_matches(
        const ds4_gpu_stream_expert_cache_entry *e,
        const void *model_map,
        uint64_t    model_size,
        uint64_t    gate_abs_offset,
        uint64_t    up_abs_offset,
        uint64_t    down_abs_offset,
        uint64_t    gate_expert_bytes,
        uint64_t    down_expert_bytes) {
    return e &&
           e->valid &&
           e->model_map == model_map &&
           e->model_size == model_size &&
           e->gate_abs_offset == gate_abs_offset &&
           e->up_abs_offset == up_abs_offset &&
           e->down_abs_offset == down_abs_offset &&
           e->gate_expert_bytes == gate_expert_bytes &&
           e->down_expert_bytes == down_expert_bytes &&
           e->gate_buffer && e->up_buffer && e->down_buffer;
}

static ds4_gpu_stream_expert_cache_entry *ds4_gpu_stream_expert_cache_peek(
        const void *model_map,
        uint64_t    model_size,
        uint32_t    layer,
        uint32_t    expert,
        uint32_t    n_total_expert,
        uint32_t    n_selected,
        uint64_t    gate_abs_offset,
        uint64_t    up_abs_offset,
        uint64_t    down_abs_offset,
        uint64_t    gate_expert_bytes,
        uint64_t    down_expert_bytes) {
    if (!g_ssd_streaming_mode ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        expert >= n_total_expert ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes) ||
        ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                  n_total_expert,
                                                  n_selected) == 0) {
        return NULL;
    }

    ds4_gpu_stream_expert_cache_entry *e =
        &g_stream_expert_cache[layer][expert];
    if (!ds4_gpu_stream_expert_cache_entry_matches(e,
                                                   model_map,
                                                   model_size,
                                                   gate_abs_offset,
                                                   up_abs_offset,
                                                   down_abs_offset,
                                                   gate_expert_bytes,
                                                   down_expert_bytes)) {
        return NULL;
    }

    e->last_used = ++g_stream_expert_cache_clock;
    e->use_count++;
    ds4_gpu_stream_expert_counter_add(&g_stream_expert_cache_hits, 1);
    g_stream_expert_cache_layer_hits[layer]++;
    return e;
}

static ds4_gpu_stream_expert_cache_entry *
ds4_gpu_stream_expert_cache_install_loaded(
        const void    *model_map,
        uint64_t       model_size,
        uint32_t       layer,
        uint32_t       expert,
        uint32_t       n_total_expert,
        uint64_t       gate_abs_offset,
        uint64_t       up_abs_offset,
        uint64_t       down_abs_offset,
        uint64_t       gate_expert_bytes,
        uint64_t       down_expert_bytes,
        id<MTLBuffer>  gate_buf,
        id<MTLBuffer>  up_buf,
        id<MTLBuffer>  down_buf,
        NSUInteger     gate_inner,
        NSUInteger     up_inner,
        NSUInteger     down_inner) {
    if (!gate_buf || !up_buf || !down_buf ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_total_expert == 0 ||
        n_total_expert > HEBRUS_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        expert >= n_total_expert) {
        return NULL;
    }
    const int qwen_cache_index =
        hebrus_gpu_stream_expert_qwen35_model();
    if (qwen_cache_index &&
        !hebrus_gpu_stream_expert_cache_layer_limit_matches_value(
             g_stream_expert_cache_layer_count[layer],
             g_stream_expert_cache_layer_expert_limit[layer],
             n_total_expert)) {
        return NULL;
    }
    if (gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        fprintf(stderr, "ds4: Metal streaming expert cache byte size overflow\n");
        return NULL;
    }
    const uint64_t logical_bytes = gate_expert_bytes * 2ull + down_expert_bytes;

    ds4_gpu_stream_expert_cache_entry *e =
        &g_stream_expert_cache[layer][expert];
    if (e->valid) {
        if (ds4_gpu_stream_expert_cache_entry_inflight(e) &&
            !ds4_gpu_stream_expert_cache_wait_inflight(
                    "streaming expert cache install")) {
            return NULL;
        }
        if (ds4_gpu_stream_expert_cache_entry_inflight(e)) return NULL;
        ds4_gpu_stream_expert_cache_clear_entry(layer, expert, 0);
        if (e->valid) return NULL;
    }

    if (!ds4_gpu_stream_expert_cache_set_addr_slot(layer,
                                                   expert,
                                                   gate_buf,
                                                   gate_inner,
                                                   up_buf,
                                                   up_inner,
                                                   down_buf,
                                                   down_inner)) {
        return NULL;
    }

    e->gate_buffer = gate_buf;
    e->up_buffer = up_buf;
    e->down_buffer = down_buf;
    e->model_map = model_map;
    e->model_size = model_size;
    e->gate_abs_offset = gate_abs_offset;
    e->up_abs_offset = up_abs_offset;
    e->down_abs_offset = down_abs_offset;
    e->gate_expert_bytes = gate_expert_bytes;
    e->down_expert_bytes = down_expert_bytes;
    e->logical_bytes = logical_bytes;
    e->last_used = ++g_stream_expert_cache_clock;
    e->use_count = 1;
    e->gate_inner = gate_inner;
    e->up_inner = up_inner;
    e->down_inner = down_inner;
    e->inflight_seq = 0;
    uint32_t slab_slot = 0;
    if (gate_buf == up_buf &&
        gate_buf == down_buf &&
        ds4_gpu_stream_expert_slab_slot_for_buffer(gate_buf,
                                                   gate_inner,
                                                   &slab_slot)) {
        e->slab_backed = 1;
        e->slab_slot = slab_slot;
    } else {
        e->slab_backed = 0;
        e->slab_slot = 0;
    }
    e->valid = 1;
    if (qwen_cache_index) {
        g_stream_expert_cache_layer_occupancy[layer][expert / 64u] |=
            1ull << (expert % 64u);
        if (g_stream_expert_cache_layer_count[layer] == 0) {
            g_stream_expert_cache_layer_expert_limit[layer] =
                n_total_expert;
        }
    }
    g_stream_expert_cache_layer_count[layer]++;
    if (g_stream_expert_cache_entry_count < UINT32_MAX) {
        g_stream_expert_cache_entry_count++;
    }
    if (g_stream_expert_cache_bytes > UINT64_MAX - logical_bytes) {
        g_stream_expert_cache_bytes = UINT64_MAX;
    } else {
        g_stream_expert_cache_bytes += logical_bytes;
    }
    ds4_gpu_stream_expert_counter_add(&g_stream_expert_cache_misses, 1);
    g_stream_expert_cache_layer_misses[layer]++;
    g_stream_expert_cache_wraps += 3;
    if (g_stream_expert_measure_enabled) {
        /* Installs run on the Metal encoder owner after their reads complete,
         * so this bitmap needs neither atomics nor locks.  A reload of the same
         * expert increases actual pread_bytes but not unique_bytes, which is
         * precisely the storage read-amplification signal the campaign needs. */
        const uint32_t word = expert / 64u;
        const uint64_t mask = 1ull << (expert % 64u);
        uint64_t *seen = &g_stream_expert_measure_seen[layer][word];
        if ((*seen & mask) == 0) {
            *seen |= mask;
            ds4_gpu_stream_expert_counter_add(
                &g_stream_expert_measure_unique_experts, 1);
            ds4_gpu_stream_expert_counter_add(
                &g_stream_expert_measure_unique_bytes, logical_bytes);
        }
    }
    return e;
}

static ds4_gpu_stream_expert_cache_entry *ds4_gpu_stream_expert_cache_get_protected(
        const void *model_map,
        uint64_t    model_size,
        uint32_t    layer,
        uint32_t    expert,
        uint32_t    n_total_expert,
        uint32_t    n_selected,
        uint64_t    gate_abs_offset,
        uint64_t    up_abs_offset,
        uint64_t    down_abs_offset,
        uint64_t    gate_expert_bytes,
        uint64_t    down_expert_bytes,
        const int32_t *protect_ids,
        uint32_t    n_protect) {
    if (!g_ssd_streaming_mode ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        expert >= n_total_expert ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes) ||
        ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                  n_total_expert,
                                                  n_selected) == 0) {
        return NULL;
    }

    ds4_gpu_stream_expert_cache_entry *e =
        &g_stream_expert_cache[layer][expert];
    if (ds4_gpu_stream_expert_cache_entry_matches(e,
                                                  model_map,
                                                  model_size,
                                                  gate_abs_offset,
                                                  up_abs_offset,
                                                  down_abs_offset,
                                                  gate_expert_bytes,
                                                  down_expert_bytes)) {
        e->last_used = ++g_stream_expert_cache_clock;
        e->use_count++;
        ds4_gpu_stream_expert_counter_add(&g_stream_expert_cache_hits, 1);
        g_stream_expert_cache_layer_hits[layer]++;
        return e;
    }

    if (g_stream_expert_cache_required_floor == 0) {
        ds4_gpu_stream_expert_readahead_range(gate_abs_offset,
                                              gate_expert_bytes);
        ds4_gpu_stream_expert_readahead_range(up_abs_offset,
                                              gate_expert_bytes);
        ds4_gpu_stream_expert_readahead_range(down_abs_offset,
                                              down_expert_bytes);
    }

    id<MTLBuffer> gate_buf = nil;
    id<MTLBuffer> up_buf = nil;
    id<MTLBuffer> down_buf = nil;
    NSUInteger gate_inner = 0;
    NSUInteger up_inner = 0;
    NSUInteger down_inner = 0;
    const int32_t protect_one = (int32_t)expert;
    if (!protect_ids || n_protect == 0) {
        protect_ids = &protect_one;
        n_protect = 1;
    }
    const uint32_t cache_budget =
        ds4_gpu_stream_expert_cache_configured_budget();
    const int force_reuse =
        cache_budget != 0 && g_stream_expert_cache_entry_count >= cache_budget;
    if (!ds4_gpu_stream_expert_cache_prepare_load_buffers(layer,
                                                          expert,
                                                          layer,
                                                          protect_ids,
                                                          n_protect,
                                                          gate_expert_bytes,
                                                          down_expert_bytes,
                                                          force_reuse,
                                                          &gate_buf,
                                                          &up_buf,
                                                          &down_buf,
                                                          &gate_inner,
                                                          &up_inner,
                                                          &down_inner)) {
        return NULL;
    }
    if (!gate_buf || !up_buf || !down_buf ||
        !ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
        return NULL;
    }

    if (g_stream_expert_cache_required_floor != 0) {
        ds4_gpu_stream_expert_readahead_range(gate_abs_offset,
                                              gate_expert_bytes);
        ds4_gpu_stream_expert_readahead_range(up_abs_offset,
                                              gate_expert_bytes);
        ds4_gpu_stream_expert_readahead_range(down_abs_offset,
                                              down_expert_bytes);
    }

    uint8_t *gate_dst = (uint8_t *)[gate_buf contents] + gate_inner;
    uint8_t *up_dst = (uint8_t *)[up_buf contents] + up_inner;
    uint8_t *down_dst = (uint8_t *)[down_buf contents] + down_inner;
    if (!gate_dst || !up_dst || !down_dst) return NULL;

    ds4_gpu_stream_expert_pread_task tasks[3] = {0};
    uint32_t n_tasks = 0;
    if (!ds4_gpu_stream_expert_append_record_tasks(
            tasks, 3, &n_tasks,
            gate_abs_offset, up_abs_offset, down_abs_offset,
            gate_expert_bytes, down_expert_bytes,
            gate_dst, up_dst, down_dst,
            ds4_gpu_stream_expert_record_read_plan())) {
        return NULL;
    }
    uint64_t read_bytes = 0;
    double read_ms = 0.0;
    const int read_ok = ds4_gpu_stream_expert_pread_tasks(
        tasks, n_tasks, &read_bytes, &read_ms);
    const uint64_t pread_syscalls =
        ds4_gpu_stream_expert_pread_successful_syscalls(tasks, n_tasks);
    if (!read_ok) {
        ds4_gpu_stream_expert_cache_note_pread(
            layer, 0, pread_syscalls, read_bytes, read_ms);
        return NULL;
    }
    ds4_gpu_stream_expert_cache_note_pread(
        layer, 1, pread_syscalls, read_bytes, read_ms);

    [gate_buf didModifyRange:NSMakeRange(gate_inner, (NSUInteger)gate_expert_bytes)];
    [up_buf didModifyRange:NSMakeRange(up_inner, (NSUInteger)gate_expert_bytes)];
    [down_buf didModifyRange:NSMakeRange(down_inner, (NSUInteger)down_expert_bytes)];
    if (getenv("DS4_METAL_STREAMING_EXPERT_PREAD_PROFILE") != NULL) {
        fprintf(stderr,
                "ds4: Metal streaming expert parallel pread layer=%u experts=1 reads=%u "
                "threads=%u bytes=%.2f GiB wall=%.3f ms\n",
                layer,
                n_tasks,
                ds4_gpu_stream_expert_pread_thread_count(n_tasks),
                ds4_gpu_gib(read_bytes),
                read_ms);
    }
    return ds4_gpu_stream_expert_cache_install_loaded(model_map,
                                                      model_size,
                                                      layer,
                                                      expert,
                                                      n_total_expert,
                                                      gate_abs_offset,
                                                      up_abs_offset,
                                                      down_abs_offset,
                                                      gate_expert_bytes,
                                                      down_expert_bytes,
                                                      gate_buf,
                                                      up_buf,
                                                      down_buf,
                                                      gate_inner,
                                                      up_inner,
                                                      down_inner);
}

static ds4_gpu_stream_expert_cache_entry *ds4_gpu_stream_expert_cache_get(
        const void *model_map,
        uint64_t    model_size,
        uint32_t    layer,
        uint32_t    expert,
        uint32_t    n_total_expert,
        uint32_t    n_selected,
        uint64_t    gate_abs_offset,
        uint64_t    up_abs_offset,
        uint64_t    down_abs_offset,
        uint64_t    gate_expert_bytes,
        uint64_t    down_expert_bytes) {
    return ds4_gpu_stream_expert_cache_get_protected(model_map,
                                                     model_size,
                                                     layer,
                                                     expert,
                                                     n_total_expert,
                                                     n_selected,
                                                     gate_abs_offset,
                                                     up_abs_offset,
                                                     down_abs_offset,
                                                     gate_expert_bytes,
                                                     down_expert_bytes,
                                                     NULL,
                                                     0);
}

#ifdef DS4_TEST_HOOKS
/* This probe exercises SUPPORT cache ownership and SSD I/O without exposing a
 * DSpark execution path.  The production graph may reuse the mechanism only
 * after it has an explicit command-buffer lifetime and parity coverage. */
static ds4_gpu_dspark_support_cache_entry *
ds4_gpu_dspark_support_cache_get_for_test(
        uint32_t stage,
        uint32_t expert) {
    uint64_t lease_id = 0;
    uint32_t unique = 0;
    const int32_t requested = (int32_t)expert;
    if (!ds4_gpu_dspark_support_cache_acquire_stage_lease(
            stage, &lease_id)) {
        return NULL;
    }
    const int load_ok = ds4_gpu_dspark_support_cache_load_stage_lease(
        lease_id, &requested, 1, &unique);
    const int release_ok =
        ds4_gpu_dspark_support_cache_release_stage_lease(lease_id);
    return load_ok && release_ok && unique == 1 ?
        &g_dspark_support_cache[stage][expert] : NULL;

}
#endif

static int ds4_gpu_stream_expert_pending_load_profile_enabled(void) {
    return getenv("DS4_METAL_STREAMING_EXPERT_EARLY_LOAD_PROFILE") != NULL;
}

static void ds4_gpu_stream_expert_pending_load_release_buffers(
        ds4_gpu_stream_expert_pending_load *p) {
    if (!p) return;
    for (uint32_t i = 0; i < DS4_METAL_STREAM_SELECTED_MAX; i++) {
        p->gate_bufs[i] = nil;
        p->up_bufs[i] = nil;
        p->down_bufs[i] = nil;
        p->gate_inners[i] = 0;
        p->up_inners[i] = 0;
        p->down_inners[i] = 0;
    }
}

static int ds4_gpu_stream_expert_pending_load_install(
        ds4_gpu_stream_expert_pending_load *p,
        ds4_gpu_stream_expert_cache_entry **entries,
        double elapsed_ms) {
    if (!p || p->n_loads == 0) return 1;

    const int load_timing = ds4_gpu_stream_expert_timing_summary_enabled();
    double load_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
    double load_modify_ms = 0.0;
    double load_install_ms = 0.0;

    uint64_t read_bytes = 0;
    int ok = 1;
    for (uint32_t i = 0; i < p->n_tasks; i++) {
        if (!p->tasks[i].ok) ok = 0;
        if (read_bytes > UINT64_MAX - p->tasks[i].read_bytes) {
            read_bytes = UINT64_MAX;
        } else {
            read_bytes += p->tasks[i].read_bytes;
        }
    }
    const uint64_t pread_syscalls =
        ds4_gpu_stream_expert_pread_successful_syscalls(
            p->tasks, p->n_tasks);
    if (!ok) {
        ds4_gpu_stream_expert_cache_note_pread(
            p->layer, 0, pread_syscalls, read_bytes, elapsed_ms);
        return 0;
    }

    ds4_gpu_stream_expert_cache_note_pread(
        p->layer, p->n_loads, pread_syscalls, read_bytes, elapsed_ms);
    for (uint32_t load_i = 0; load_i < p->n_loads; load_i++) {
        [p->gate_bufs[load_i] didModifyRange:NSMakeRange(p->gate_inners[load_i], (NSUInteger)p->gate_expert_bytes)];
        [p->up_bufs[load_i] didModifyRange:NSMakeRange(p->up_inners[load_i], (NSUInteger)p->gate_expert_bytes)];
        [p->down_bufs[load_i] didModifyRange:NSMakeRange(p->down_inners[load_i], (NSUInteger)p->down_expert_bytes)];
    }
    if (load_timing) {
        const double now_ms = ds4_gpu_now_ms();
        load_modify_ms = now_ms - load_t0;
        load_t0 = now_ms;
    }

    ds4_gpu_stream_expert_cache_entry
        *loaded_entries[DS4_METAL_STREAM_SELECTED_MAX] = { NULL };
    for (uint32_t load_i = 0; load_i < p->n_loads; load_i++) {
        const uint32_t slot = p->load_slots[load_i];
        const uint32_t expert = (uint32_t)p->selected_ids[slot];
        ds4_gpu_stream_expert_cache_entry *entry =
            ds4_gpu_stream_expert_cache_install_loaded(p->model_map,
                                                       p->model_size,
                                                       p->layer,
                                                       expert,
                                                       p->n_total_expert,
                                                       p->gate_abs_offsets[slot],
                                                       p->up_abs_offsets[slot],
                                                       p->down_abs_offsets[slot],
                                                       p->gate_expert_bytes,
                                                       p->down_expert_bytes,
                                                       p->gate_bufs[load_i],
                                                       p->up_bufs[load_i],
                                                       p->down_bufs[load_i],
                                                       p->gate_inners[load_i],
                                                       p->up_inners[load_i],
                                                       p->down_inners[load_i]);
        if (!entry) return 0;
        loaded_entries[slot] = entry;
        if (entries) entries[slot] = entry;
    }
    for (uint32_t i = 0; i < p->n_selected; i++) {
        if ((p->missing_mask & (1u << i)) == 0) continue;
        if (entries && entries[i]) continue;
        const uint32_t source = p->source_slots[i];
        if (source >= p->n_selected) return 0;
        ds4_gpu_stream_expert_cache_entry *entry = entries && entries[source] ?
            entries[source] : loaded_entries[source];
        if (!entry) return 0;
        entry->use_count++;
        if (entries) entries[i] = entry;
    }
    if (load_timing) {
        load_install_ms = ds4_gpu_now_ms() - load_t0;
        ds4_gpu_stream_expert_timing_note_load_detail(p->prepare_ms,
                                                      elapsed_ms,
                                                      load_modify_ms,
                                                      load_install_ms);
    }
    if (ds4_gpu_stream_expert_pending_load_profile_enabled()) {
        fprintf(stderr,
                "ds4: Metal streaming expert early-load finish layer=%u experts=%u tensors=%u bytes=%.2f GiB wall=%.3f ms\n",
                p->layer,
                p->n_loads,
                p->n_tasks,
                ds4_gpu_gib(read_bytes),
                elapsed_ms);
    }
    return 1;
}

static int ds4_gpu_stream_expert_pending_load_finish(
        ds4_gpu_stream_expert_cache_entry **entries) {
    ds4_gpu_stream_expert_pending_load *p = &g_stream_expert_pending_load;
    if (!p->active) return 1;

    const double start_ms = p->start_ms;
    if (!ds4_gpu_stream_expert_pread_pool_wait()) {
        ds4_gpu_stream_expert_pending_load_release_buffers(p);
        p->active = 0;
        return 0;
    }
    const double elapsed_ms =
        ds4_gpu_stream_expert_pread_pool_elapsed_ms(start_ms);
    p->active = 0;
    const int ok = ds4_gpu_stream_expert_pending_load_install(p,
                                                              entries,
                                                              elapsed_ms);
    ds4_gpu_stream_expert_pending_load_release_buffers(p);
    p->n_tasks = 0;
    p->n_loads = 0;
    p->prepare_ms = 0.0;
    return ok;
}

static void ds4_gpu_stream_expert_pending_load_clear(void) {
    if (!g_stream_expert_pending_load.active) {
        ds4_gpu_stream_expert_pending_load_release_buffers(
                &g_stream_expert_pending_load);
        return;
    }
    (void)ds4_gpu_stream_expert_pending_load_finish(NULL);
}

int ds4_gpu_stream_expert_cache_acquire_layer_lease(
        uint32_t layer,
        uint64_t *lease_id) {
    if (!lease_id) return 0;
    *lease_id = 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!g_ssd_streaming_mode ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        ds4_gpu_stream_expert_cache_configured_budget() == 0 ||
        !ds4_gpu_stream_expert_cache_required_floor_satisfied() ||
        g_stream_expert_cache_lease.active ||
        g_stream_expert_pending_load.active ||
        g_qwen35_stream_pending.state != DS4_QWEN35_STREAM_IO_EMPTY) {
        return 0;
    }

    const uint64_t id = ds4_gpu_stream_expert_cache_lease_next_id();
    g_stream_expert_cache_lease.owner = pthread_self();
    g_stream_expert_cache_lease.id = id;
    g_stream_expert_cache_lease.layer = layer;
    g_stream_expert_cache_lease.domain =
        DS4_GPU_STREAM_EXPERT_LEASE_TARGET;
    g_stream_expert_cache_lease.active = 1;
    *lease_id = id;
    return 1;
}

int ds4_gpu_stream_expert_cache_release_layer_lease(uint64_t lease_id) {
    if (!g_stream_expert_cache_lease.active ||
        g_stream_expert_cache_lease.domain !=
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET ||
        lease_id == 0 ||
        lease_id != g_stream_expert_cache_lease.id ||
        !pthread_equal(g_stream_expert_cache_lease.owner, pthread_self())) {
        /* Leave the lease active on every mismatch. Releasing the wrong
         * layer is less recoverable than failing the enclosing transaction. */
        return 0;
    }

    /* The layer owner must consume or abort its route generation first.  A
     * release here would make staging installation immediately evictable. */
    if (g_qwen35_stream_pending.state != DS4_QWEN35_STREAM_IO_EMPTY) {
        return 0;
    }

    const int pending_ok =
        ds4_gpu_stream_expert_pending_load_finish(NULL);
    /* Most layer schedulers have already ended their batch. Avoid submitting
     * an empty command buffer in that common case, but drain either form of
     * outstanding work before making the entries evictable. */
    const int synchronize_ok =
        !(g_batch_cb || [g_pending_cbs count] != 0) ||
        ds4_gpu_synchronize();
    /* Both drain operations consume their ownership state before reporting an
     * I/O or command-buffer error.  Once the authenticated owner reaches this
     * point, retaining the lease cannot protect any live work; it only poisons
     * every later request by making acquire/reconfigure fail forever.  Revoke
     * it unconditionally, while still propagating either drain failure. */
    ds4_gpu_stream_expert_cache_lease_invalidate();
    return pending_ok && synchronize_ok;
}

#ifdef DS4_TEST_HOOKS
static int ds4_gpu_dspark_support_cache_prune_for_batch(
        uint32_t n_missing) {
    const uint32_t support_budget =
        ds4_gpu_dspark_support_cache_configured_budget();
    const uint32_t parent_budget =
        ds4_gpu_stream_expert_cache_parent_budget(0);
    if (support_budget != DS4_DSPARK_SUPPORT_CACHE_FLOOR ||
        n_missing > DS4_DSPARK_SUPPORT_BATCH_MAX ||
        g_stream_expert_cache_entry_count >
            ds4_gpu_stream_expert_cache_configured_budget()) {
        return 0;
    }

    for (;;) {
        const int support_fits =
            g_dspark_support_cache_entry_count <= support_budget &&
            n_missing <= support_budget -
                g_dspark_support_cache_entry_count;
        const int parent_fits =
            g_stream_expert_cache_entry_count <= UINT32_MAX -
                g_dspark_support_cache_entry_count &&
            g_stream_expert_cache_entry_count +
                g_dspark_support_cache_entry_count <= parent_budget &&
            n_missing <= parent_budget -
                (g_stream_expert_cache_entry_count +
                 g_dspark_support_cache_entry_count);
        if (support_fits && parent_fits) return 1;

        uint32_t victim_stage = UINT32_MAX;
        uint32_t victim_expert = UINT32_MAX;
        uint64_t oldest = UINT64_MAX;
        for (uint32_t stage = 0;
             stage < DS4_DSPARK_SUPPORT_LAYER_COUNT;
             stage++) {
            for (uint32_t expert = 0;
                 expert < DS4_DSPARK_SUPPORT_EXPERT_COUNT;
                 expert++) {
                const ds4_gpu_dspark_support_cache_entry *candidate =
                    &g_dspark_support_cache[stage][expert];
                if (!candidate->valid ||
                    ds4_gpu_dspark_support_lease_pins(stage, expert)) {
                    continue;
                }
                if (victim_stage == UINT32_MAX ||
                    candidate->last_used < oldest) {
                    victim_stage = stage;
                    victim_expert = expert;
                    oldest = candidate->last_used;
                }
            }
        }
        if (victim_stage == UINT32_MAX) return 0;
        const uint32_t before = g_dspark_support_cache_entry_count;
        ds4_gpu_dspark_support_cache_clear_entry(
            victim_stage, victim_expert, 1);
        if (g_dspark_support_cache_entry_count >= before) return 0;
    }
}

static int ds4_gpu_dspark_support_cache_acquire_stage_lease(
        uint32_t stage,
        uint64_t *lease_id) {
    if (!lease_id) return 0;
    *lease_id = 0;
    if ((!g_initialized && !ds4_gpu_init()) ||
        !g_ssd_streaming_mode ||
        stage >= DS4_DSPARK_SUPPORT_LAYER_COUNT ||
        !ds4_gpu_dspark_support_cache_combined_available() ||
        ds4_gpu_stream_expert_cache_parent_budget(0) <
            DS4_DSPARK_COMBINED_CACHE_FLOOR ||
        ds4_gpu_dspark_support_cache_configured_budget() !=
            DS4_DSPARK_SUPPORT_CACHE_FLOOR ||
        ds4_gpu_stream_expert_cache_configured_budget() <
            DS4_DSPARK_TARGET_CACHE_FLOOR ||
        g_stream_expert_cache_lease.active ||
        g_stream_expert_pending_load.active ||
        g_qwen35_stream_pending.state != DS4_QWEN35_STREAM_IO_EMPTY ||
        !ds4_gpu_dspark_support_cache_reconcile_transition(0)) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }

    const uint64_t id = ds4_gpu_stream_expert_cache_lease_next_id();
    g_stream_expert_cache_lease.owner = pthread_self();
    g_stream_expert_cache_lease.id = id;
    g_stream_expert_cache_lease.layer = stage;
    memset(g_stream_expert_cache_lease.support_pins,
           0,
           sizeof(g_stream_expert_cache_lease.support_pins));
    g_stream_expert_cache_lease.last_use_seq = 0;
    g_stream_expert_cache_lease.support_pack =
        (const void *)g_dspark_expert_pack;
    g_stream_expert_cache_lease.support_target_generation =
        g_dspark_support_target_generation;
    g_stream_expert_cache_lease.support_pack_generation =
        g_dspark_support_pack_generation;
    g_stream_expert_cache_lease.support_file_device =
        g_dspark_expert_pack->file_device;
    g_stream_expert_cache_lease.support_file_inode =
        g_dspark_expert_pack->file_inode;
    g_stream_expert_cache_lease.support_file_size =
        g_dspark_expert_pack->file_size;
    g_stream_expert_cache_lease.support_fd = g_dspark_expert_pack->fd;
    g_stream_expert_cache_lease.domain =
        DS4_GPU_STREAM_EXPERT_LEASE_SUPPORT;
    g_stream_expert_cache_lease.active = 1;
    ds4_gpu_stream_expert_counter_add(
        &g_dspark_support_cache_lease_acquires, 1);
    *lease_id = id;
    return 1;
}

static int ds4_gpu_dspark_support_cache_load_stage_lease(
        uint64_t       lease_id,
        const int32_t *expert_ids,
        uint32_t       n_expert_ids,
        uint32_t      *unique_experts) {
    if (unique_experts) *unique_experts = 0;
    if (!unique_experts || !expert_ids || n_expert_ids == 0 ||
        n_expert_ids > DS4_DSPARK_SUPPORT_BATCH_MAX ||
        !ds4_gpu_dspark_support_lease_authenticates(lease_id) ||
        !ds4_gpu_dspark_support_lease_store_matches()) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }

    int32_t ids[DS4_DSPARK_SUPPORT_BATCH_MAX];
    uint64_t previous_pins[DS4_DSPARK_SUPPORT_EXPERT_COUNT / 64u];
    uint64_t requested[DS4_DSPARK_SUPPORT_EXPERT_COUNT / 64u];
    memcpy(previous_pins,
           g_stream_expert_cache_lease.support_pins,
           sizeof(previous_pins));
    memcpy(requested,
           previous_pins,
           sizeof(requested));
    uint32_t n_unique = 0;
    for (uint32_t index = 0; index < n_expert_ids; index++) {
        const int32_t expert = expert_ids[index];
        if (expert < 0 ||
            (uint32_t)expert >= DS4_DSPARK_SUPPORT_EXPERT_COUNT ||
            (uint32_t)expert >= g_dspark_expert_pack->n_expert) {
            ds4_gpu_stream_expert_counter_add(
                &g_dspark_support_cache_lease_failures, 1);
            return 0;
        }
        const uint64_t bit = 1ull << ((uint32_t)expert % 64u);
        uint64_t *word = &requested[(uint32_t)expert / 64u];
        int duplicate = 0;
        for (uint32_t previous = 0; previous < n_unique; previous++) {
            if (ids[previous] == expert) {
                duplicate = 1;
                break;
            }
        }
        if (!duplicate) ids[n_unique++] = expert;
        *word |= bit;
    }
    uint32_t requested_count = 0;
    for (uint32_t word = 0;
         word < DS4_DSPARK_SUPPORT_EXPERT_COUNT / 64u;
         word++) {
        requested_count +=
            (uint32_t)__builtin_popcountll(requested[word]);
    }
    if (requested_count > DS4_DSPARK_SUPPORT_BATCH_MAX) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }

    uint32_t layer_index = 0;
    if (!ds4_gpu_expert_store_layer_index(
            g_dspark_expert_pack,
            g_stream_expert_cache_lease.layer,
            &layer_index)) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }
    const ds4_gpu_qwen35_expert_pack_layer *layer =
        &g_dspark_expert_pack->layers[layer_index];
    if (!layer->valid || layer->record_bytes == 0 ||
        layer->record_bytes > NSUIntegerMax ||
        layer->record_bytes > (uint64_t)[g_device maxBufferLength]) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }
    const uint32_t lease_stage = g_stream_expert_cache_lease.layer;
    const uint64_t data_offset_snapshot = layer->data_offset;
    const uint64_t data_size_snapshot = layer->data_size;
    const uint64_t record_bytes_snapshot = layer->record_bytes;
    const uint64_t file_size_snapshot = g_dspark_expert_pack->file_size;
    const int support_fd_snapshot = g_dspark_expert_pack->fd;

    uint64_t source_offsets[DS4_DSPARK_SUPPORT_BATCH_MAX];
    uint32_t missing_indices[DS4_DSPARK_SUPPORT_BATCH_MAX];
    int32_t task_for_index[DS4_DSPARK_SUPPORT_BATCH_MAX];
    for (uint32_t index = 0;
         index < DS4_DSPARK_SUPPORT_BATCH_MAX;
         index++) {
        task_for_index[index] = -1;
    }
    uint32_t n_missing = 0;
    for (uint32_t index = 0; index < n_unique; index++) {
        uint64_t expert_delta = 0;
        if (!ds4_gpu_qwen35_expert_pack_mul_u64(
                (uint32_t)ids[index], layer->record_bytes, &expert_delta) ||
            !ds4_gpu_qwen35_expert_pack_add_u64(
                layer->data_offset, expert_delta, &source_offsets[index]) ||
            !ds4_gpu_qwen35_expert_pack_range_valid(
                source_offsets[index], layer->record_bytes,
                g_dspark_expert_pack->file_size)) {
            ds4_gpu_stream_expert_counter_add(
                &g_dspark_support_cache_lease_failures, 1);
            return 0;
        }
        ds4_gpu_dspark_support_cache_entry *entry =
            &g_dspark_support_cache[g_stream_expert_cache_lease.layer]
                                   [(uint32_t)ids[index]];
        if (entry->valid &&
            (!entry->buffer ||
             entry->source_fd != g_dspark_expert_pack->fd ||
             entry->source_offset != source_offsets[index] ||
             entry->record_bytes != layer->record_bytes)) {
            ds4_gpu_stream_expert_counter_add(
                &g_dspark_support_cache_lease_failures, 1);
            return 0;
        }
        if (!entry->valid) {
            task_for_index[index] = (int32_t)n_missing;
            missing_indices[n_missing++] = index;
        }
    }

    memcpy(g_stream_expert_cache_lease.support_pins,
           requested,
           sizeof(requested));
    if (!ds4_gpu_dspark_support_cache_prune_for_batch(n_missing)) {
        memcpy(g_stream_expert_cache_lease.support_pins,
               previous_pins,
               sizeof(previous_pins));
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }

    __strong id<MTLBuffer>
        buffers[DS4_DSPARK_SUPPORT_BATCH_MAX] = { nil };
    ds4_gpu_stream_expert_pread_task
        tasks[DS4_DSPARK_SUPPORT_BATCH_MAX] = {0};
    for (uint32_t task = 0; task < n_missing; task++) {
        const uint32_t index = missing_indices[task];
        buffers[task] =
            [g_device newBufferWithLength:(NSUInteger)layer->record_bytes
                                  options:MTLResourceStorageModeShared];
        uint8_t *destination = buffers[task] ?
            (uint8_t *)[buffers[task] contents] : NULL;
        if (!buffers[task] || !destination) {
            memcpy(g_stream_expert_cache_lease.support_pins,
                   previous_pins,
                   sizeof(previous_pins));
            ds4_gpu_stream_expert_counter_add(
                &g_dspark_support_cache_batch_rollbacks, 1);
            ds4_gpu_stream_expert_counter_add(
                &g_dspark_support_cache_lease_failures, 1);
            return 0;
        }
        buffers[task].label = @"ds4_dspark_support_cache_record";
        tasks[task] = (ds4_gpu_stream_expert_pread_task) {
            .offset = source_offsets[index],
            .len = layer->record_bytes,
            .dst = destination,
            .source_fd = support_fd_snapshot,
            .source_offset = source_offsets[index],
            .direct_source = 1,
        };
#ifdef DS4_TEST_HOOKS
        if (g_dspark_support_cache_test_fail_task == (int32_t)task) {
            tasks[task].source_offset = file_size_snapshot;
        }
#endif
    }

    uint64_t read_bytes = 0;
    double read_ms = 0.0;
    const int read_ok = ds4_gpu_stream_expert_pread_tasks(
        tasks, n_missing, &read_bytes, &read_ms);
    uint64_t pread_syscalls = 0;
    for (uint32_t task = 0; task < n_missing; task++) {
        ds4_gpu_stream_expert_counter_add(
            &pread_syscalls, tasks[task].successful_syscalls);
    }
    ds4_gpu_stream_expert_counter_add(
        &g_dspark_support_cache_pread_syscalls, pread_syscalls);
    ds4_gpu_stream_expert_counter_add(
        &g_dspark_support_cache_pread_bytes, read_bytes);
    g_dspark_support_cache_pread_ms += read_ms;
    if (!read_ok) {
        memcpy(g_stream_expert_cache_lease.support_pins,
               previous_pins,
               sizeof(previous_pins));
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_batch_rollbacks, 1);
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }

    uint32_t publish_layer_index = 0;
    const int publish_identity_ok =
        ds4_gpu_dspark_support_lease_store_matches() &&
        ds4_gpu_expert_store_layer_index(
            g_dspark_expert_pack, lease_stage, &publish_layer_index) &&
        publish_layer_index == layer_index &&
        g_dspark_expert_pack->layers[publish_layer_index].valid &&
        g_dspark_expert_pack->layers[publish_layer_index].data_offset ==
            data_offset_snapshot &&
        g_dspark_expert_pack->layers[publish_layer_index].data_size ==
            data_size_snapshot &&
        g_dspark_expert_pack->layers[publish_layer_index].record_bytes ==
            record_bytes_snapshot &&
        g_dspark_expert_pack->file_size == file_size_snapshot &&
        g_dspark_expert_pack->fd == support_fd_snapshot;
    if (!publish_identity_ok) {
        memcpy(g_stream_expert_cache_lease.support_pins,
               previous_pins,
               sizeof(previous_pins));
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_batch_rollbacks, 1);
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }

    for (uint32_t task = 0; task < n_missing; task++) {
        [buffers[task] didModifyRange:
            NSMakeRange(0, (NSUInteger)record_bytes_snapshot)];
    }
    if (requested_count > g_dspark_support_cache_peak_pinned) {
        g_dspark_support_cache_peak_pinned = requested_count;
    }
    for (uint32_t index = 0; index < n_unique; index++) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_clock, 1);
        ds4_gpu_dspark_support_cache_entry *entry =
            &g_dspark_support_cache[lease_stage]
                                   [(uint32_t)ids[index]];
        if (entry->valid) {
            entry->last_used = g_dspark_support_cache_clock;
            ds4_gpu_stream_expert_counter_add(
                &g_dspark_support_cache_hits, 1);
            continue;
        }
        const uint32_t task = (uint32_t)task_for_index[index];
        entry->buffer = buffers[task];
        entry->source_offset = source_offsets[index];
        entry->record_bytes = record_bytes_snapshot;
        entry->last_used = g_dspark_support_cache_clock;
        entry->source_fd = support_fd_snapshot;
        entry->valid = 1;
        g_dspark_support_cache_entry_count++;
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_bytes, record_bytes_snapshot);
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_misses, 1);
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_expert_loads, 1);
    }
    *unique_experts = n_unique;
    return 1;
}

static int ds4_gpu_dspark_support_cache_release_stage_lease(
        uint64_t lease_id) {
    if (!ds4_gpu_dspark_support_lease_authenticates(lease_id)) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
        return 0;
    }

    int drain_ok =
        g_qwen35_stream_pending.state == DS4_QWEN35_STREAM_IO_EMPTY;
    if (!ds4_gpu_stream_expert_pending_load_finish(NULL)) drain_ok = 0;
    const uint64_t last_use_seq =
        g_stream_expert_cache_lease.last_use_seq;
    if (last_use_seq != 0) {
        const double t0 = ds4_gpu_now_ms();
        if (last_use_seq <= g_stream_expert_cache_done_seq) {
            ds4_gpu_stream_expert_counter_add(
                &g_dspark_support_cache_release_already_completed_fences, 1);
        } else {
            ds4_gpu_stream_expert_counter_add(
                &g_dspark_support_cache_release_sync_fences, 1);
            if (!ds4_gpu_synchronize()) drain_ok = 0;
        }
        g_dspark_support_cache_release_fence_ms += ds4_gpu_now_ms() - t0;
    }

    /* An authenticated release consumes the owner state even when a worker or
     * Metal drain reports an error. Keeping it pinned after the ownership has
     * ended would permanently poison every later request. */
    ds4_gpu_stream_expert_cache_lease_invalidate();
    ds4_gpu_stream_expert_counter_add(
        &g_dspark_support_cache_lease_releases, 1);
    if (!drain_ok) {
        ds4_gpu_stream_expert_counter_add(
            &g_dspark_support_cache_lease_failures, 1);
    }
    return drain_ok;
}

typedef struct {
    __strong id<MTLBuffer> address_buffer;
    NSUInteger component_offset[3];
    NSUInteger ids_offset;
    __strong id<MTLBuffer> resources[DS4_DSPARK_SUPPORT_BATCH_MAX];
    uint32_t resource_count;
    uint32_t route_count;
} ds4_gpu_dspark_support_selected_addr_view;

typedef int (*ds4_gpu_dspark_support_selected_addr_encoder)(
        id<MTLCommandBuffer>                            cb,
        const ds4_gpu_dspark_support_selected_addr_view *view,
        void                                            *opaque);

/* Execute one isolated SUPPORT stage transaction.  The three component
 * address tables use the existing selected-address ABI and are keyed by model
 * expert id (0..255); expert_ids preserves the five-by-six route order.  Both
 * remain private so the later DSpark graph need not expose cache entries or
 * Metal resources through a public API.
 *
 * The transaction owns the entire lifetime edge.  Acquisition and a batch
 * load either publish every requested record or none; after a Metal batch is
 * created, even a partially failing encoder is recorded as the lease's last
 * use and fenced before authenticated release removes the pins. */
static int ds4_gpu_dspark_support_selected_addr_transaction(
        uint32_t                                         stage,
        const int32_t                                   *expert_ids,
        uint32_t                                         candidate_rows,
        ds4_gpu_dspark_support_selected_addr_encoder     encode,
        void                                            *opaque) {
    if (!expert_ids || !encode || candidate_rows == 0 ||
        candidate_rows > DS4_DSPARK_SUPPORT_CANDIDATE_ROWS ||
        g_batch_cb || [g_pending_cbs count] != 0 ||
        g_stream_expert_cache_owned_seq != 0) {
        return 0;
    }

    const uint32_t route_count =
        candidate_rows * DS4_DSPARK_SUPPORT_TOP_K;
    uint64_t lease_id = 0;
    uint32_t unique_experts = 0;
    int ok = ds4_gpu_dspark_support_cache_acquire_stage_lease(
        stage, &lease_id);
    if (!ok) return 0;

    ds4_gpu_dspark_support_selected_addr_view view = {0};
    __strong id<MTLCommandBuffer> cb = nil;
    int owned = 0;
    ok = ds4_gpu_dspark_support_cache_load_stage_lease(
        lease_id, expert_ids, route_count, &unique_experts);
    if (!ok || unique_experts == 0 ||
        !ds4_gpu_dspark_support_lease_store_matches()) {
        ok = 0;
        goto release;
    }

    uint32_t layer_index = 0;
    if (!ds4_gpu_expert_store_layer_index(
            g_dspark_expert_pack, stage, &layer_index)) {
        ok = 0;
        goto release;
    }
    const ds4_gpu_qwen35_expert_pack_layer *layer =
        &g_dspark_expert_pack->layers[layer_index];
    const NSUInteger one_table_bytes =
        (NSUInteger)DS4_DSPARK_SUPPORT_EXPERT_COUNT * sizeof(uint64_t);
    if (!layer->valid || layer->record_bytes == 0 ||
        one_table_bytes > NSUIntegerMax / 3u) {
        ok = 0;
        goto release;
    }
    for (uint32_t component = 0; component < 3; component++) {
        if (layer->component_offset[component] > NSUIntegerMax ||
            layer->component_bytes[component] == 0 ||
            layer->component_offset[component] > layer->record_bytes ||
            layer->component_bytes[component] >
                layer->record_bytes - layer->component_offset[component]) {
            ok = 0;
            goto release;
        }
        view.component_offset[component] =
            (NSUInteger)component * one_table_bytes;
    }

    view.address_buffer = [g_device
        newBufferWithLength:DS4_DSPARK_SUPPORT_ADDRESS_VIEW_BYTES
                    options:MTLResourceStorageModeShared];
    if (!view.address_buffer || ![view.address_buffer contents]) {
        ok = 0;
        goto release;
    }
    view.address_buffer.label =
        @"ds4_dspark_support_selected_address_view";
    view.route_count = route_count;
    uint8_t *table_bytes = (uint8_t *)[view.address_buffer contents];
    memset(table_bytes, 0, DS4_DSPARK_SUPPORT_ADDRESS_VIEW_BYTES);
    view.ids_offset = DS4_DSPARK_SUPPORT_COMPONENT_ADDRESS_BYTES;

    for (uint32_t route = 0; route < route_count; route++) {
        const uint32_t expert = (uint32_t)expert_ids[route];
        ds4_gpu_dspark_support_cache_entry *entry =
            &g_dspark_support_cache[stage][expert];
        if (!entry->valid || !entry->buffer ||
            !ds4_gpu_dspark_support_lease_pins(stage, expert) ||
            entry->record_bytes != layer->record_bytes) {
            ok = 0;
            goto release;
        }
        for (uint32_t component = 0; component < 3; component++) {
            uint64_t *addresses = (uint64_t *)(
                table_bytes + view.component_offset[component]);
            const uint64_t address = ds4_gpu_buffer_address(
                entry->buffer,
                (NSUInteger)layer->component_offset[component]);
            if (address == 0 ||
                (addresses[expert] != 0 && addresses[expert] != address)) {
                ok = 0;
                goto release;
            }
            addresses[expert] = address;
        }
        uint32_t resource = 0;
        while (resource < view.resource_count &&
               view.resources[resource] != entry->buffer) {
            resource++;
        }
        if (resource == view.resource_count) {
            if (view.resource_count >=
                DS4_DSPARK_SUPPORT_BATCH_MAX) {
                ok = 0;
                goto release;
            }
            view.resources[view.resource_count++] = entry->buffer;
        }
    }
    memcpy(table_bytes + view.ids_offset,
           expert_ids,
           (size_t)route_count * sizeof(expert_ids[0]));
    [view.address_buffer didModifyRange:
        NSMakeRange(0, DS4_DSPARK_SUPPORT_ADDRESS_VIEW_BYTES)];

    if (!ds4_gpu_begin_commands()) {
        ok = 0;
        goto release;
    }
    cb = ds4_gpu_command_buffer(&owned);
    const uint64_t batch_seq = g_stream_expert_cache_batch_seq;
    /* Protect the batch before handing control to an encoder: it may append a
     * SUPPORT read and then fail.  Post-encode identity checks forbid a future
     * callback from hiding that read behind a commit/split/replacement. */
    const int pre_note_ok = cb && owned == 0 && batch_seq != 0 &&
        ds4_gpu_dspark_support_lease_note_current_batch_use();
    const int encode_ok = pre_note_ok && encode(cb, &view, opaque);
    const int batch_identity_ok =
        g_batch_cb == cb &&
        g_stream_expert_cache_batch_seq == batch_seq;
    const int post_note_ok = batch_identity_ok &&
        ds4_gpu_dspark_support_lease_note_current_batch_use() &&
        ds4_gpu_dspark_support_lease_store_matches();
    ok = ok && encode_ok && post_note_ok;
    if ((!pre_note_ok || !batch_identity_ok) &&
        (g_batch_cb || [g_pending_cbs count] != 0 ||
         g_stream_expert_cache_owned_seq != 0)) {
        /* The callback violated the isolated-transaction contract.  Drain all
         * visible command ownership while the lease is still authenticated;
         * last_use_seq alone may describe the batch that it replaced. */
        if (!ds4_gpu_synchronize()) ok = 0;
    }

release: {
        const int release_ok =
            ds4_gpu_dspark_support_cache_release_stage_lease(lease_id);
        return ok && release_ok;
    }
}
#endif

int ds4_gpu_reconfigure_streaming_expert_cache_budget(uint32_t experts) {
    if (!g_ssd_streaming_mode) return 0;
    if (experts > DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        experts = DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES;
    }
    const uint32_t next_support =
        ds4_gpu_dspark_support_cache_budget_for_parent(experts);
    const uint32_t next_target =
        ds4_gpu_stream_expert_cache_apply_target_caps(
            experts >= next_support ? experts - next_support : 0, 0);
    if (next_target < g_stream_expert_cache_required_floor) {
        return 0;
    }
    if (g_stream_expert_cache_required_floor != 0 &&
        g_stream_expert_cache_mlock_budget_cap_active &&
        g_stream_expert_cache_mlock_budget_cap <
            g_stream_expert_cache_required_floor) {
        return 0;
    }

    const uint32_t previous = g_stream_expert_cache_budget_override;
    const uint32_t previous_support =
        ds4_gpu_dspark_support_cache_budget_for_parent(previous);
    const uint32_t previous_target =
        ds4_gpu_stream_expert_cache_apply_target_caps(
            previous >= previous_support ? previous - previous_support : 0,
            0);
    const int target_over_budget =
        g_stream_expert_cache_entry_count > next_target;
    const int support_over_budget =
        g_dspark_support_cache_entry_count > next_support;
    if (experts == previous &&
        !target_over_budget && !support_over_budget) {
        return ds4_gpu_stream_expert_cache_required_floor_satisfied();
    }
    if (g_stream_expert_cache_lease.active ||
        g_stream_expert_pending_load.active ||
        g_qwen35_stream_pending.state != DS4_QWEN35_STREAM_IO_EMPTY) {
        return 0;
    }

    /* Pending I/O can own destination slots and queued Metal work can still
     * reference resident slots. Drain both before changing the physical
     * cache; otherwise a numerically innocent budget switch becomes a UAF. */
    if (!ds4_gpu_synchronize() ||
        !ds4_gpu_stream_expert_pending_load_finish(NULL) ||
        !ds4_gpu_synchronize()) {
        return 0;
    }

    g_stream_expert_cache_budget_override = experts;
    if (next_target < previous_target || target_over_budget) {
        /* Slabs cannot be partially deallocated. A shrink therefore drops the
         * resident set and recreates smaller slabs lazily, which is the only
         * way to return physical memory now instead of merely lowering an LRU
         * counter. clear_all(0) preserves cumulative cache/I/O statistics and
         * the model-lifetime floor. */
        ds4_gpu_stream_expert_cache_clear_all(0);
    }
    if (next_support < previous_support || support_over_budget) {
        ds4_gpu_dspark_support_cache_clear(0);
    }
    return ds4_gpu_dspark_support_cache_reconcile_transition(0) &&
           ds4_gpu_stream_expert_cache_required_floor_satisfied();
}

static int ds4_gpu_stream_expert_pending_load_matches(
        const void   *model_map,
        uint64_t      model_size,
        uint32_t      layer,
        const int32_t *selected_ids,
        uint32_t      n_total_expert,
        uint32_t      n_selected,
        uint64_t      gate_expert_bytes,
        uint64_t      down_expert_bytes) {
    ds4_gpu_stream_expert_pending_load *p = &g_stream_expert_pending_load;
    if (!p->active ||
        p->model_map != model_map ||
        p->model_size != model_size ||
        p->layer != layer ||
        p->n_total_expert != n_total_expert ||
        p->n_selected != n_selected ||
        p->gate_expert_bytes != gate_expert_bytes ||
        p->down_expert_bytes != down_expert_bytes) {
        return 0;
    }
    for (uint32_t i = 0; i < n_selected; i++) {
        if (p->selected_ids[i] != selected_ids[i]) return 0;
    }
    return 1;
}

static void ds4_gpu_glm_stream_prefetch_rdadvise(uint64_t offset, uint64_t len) {
    if (len == 0) return;

    int source_fd = g_model_fd;
    uint64_t source_offset = offset;
    const int resolved = ds4_gpu_qwen35_expert_pack_resolve(
        offset, len, &source_fd, &source_offset);
    /* Router-ahead is advisory.  With an active expert-major store, never
     * issue an advisory read against the canonical GGUF range when the
     * corresponding physical record cannot be resolved: that would compete
     * with the authoritative expert pread for unrelated pages. */
    if (resolved < 0 || source_fd < 0) return;
#if defined(F_RDADVISE)
    uint64_t pos = source_offset;
    uint64_t rem = len;
    while (rem > 0) {
        const uint64_t chunk64 =
            rem > (uint64_t)INT_MAX ? (uint64_t)INT_MAX : rem;
        if (pos > (uint64_t)LLONG_MAX) break;
        struct radvisory ra;
        ra.ra_offset = (off_t)pos;
        ra.ra_count = (int)chunk64;
        (void)fcntl(source_fd, F_RDADVISE, &ra);
        pos += chunk64;
        rem -= chunk64;
    }
#else
    (void)offset;
    (void)len;
#endif
}

int ds4_gpu_glm_stream_expert_prefetch_hint(
        uint32_t        layer,
        const int32_t  *expert_ids,
        uint32_t        n_experts,
        const void     *model_map,
        uint64_t        model_size,
        uint64_t        gate_offset,
        uint64_t        up_offset,
        uint64_t        down_offset,
        uint64_t        gate_expert_bytes,
        uint64_t        down_expert_bytes) {
    if (!g_ssd_streaming_mode ||
        !expert_ids ||
        n_experts == 0 ||
        n_experts > DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        gate_expert_bytes == 0 ||
        down_expert_bytes == 0) {
        return 0;
    }
    const double t0 = ds4_gpu_now_ms();
    int hinted = 0;
    pthread_mutex_lock(&g_glm_prefetch_mutex);
    g_glm_prefetch_predicted_n[layer] = 0;
    for (uint32_t i = 0; i < n_experts; i++) {
        if (expert_ids[i] < 0 ||
            (uint32_t)expert_ids[i] >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
            continue;
        }
        const uint32_t expert = (uint32_t)expert_ids[i];
        g_glm_prefetch_predicted[layer][g_glm_prefetch_predicted_n[layer]++] =
            (int32_t)expert;
        const uint64_t gate_abs = gate_offset + (uint64_t)expert * gate_expert_bytes;
        const uint64_t up_abs = up_offset + (uint64_t)expert * gate_expert_bytes;
        const uint64_t down_abs = down_offset + (uint64_t)expert * down_expert_bytes;
        const ds4_gpu_stream_expert_cache_entry *e =
            &g_stream_expert_cache[layer][expert];
        if (ds4_gpu_stream_expert_cache_entry_matches(e,
                                                      model_map,
                                                      model_size,
                                                      gate_abs,
                                                      up_abs,
                                                      down_abs,
                                                      gate_expert_bytes,
                                                      down_expert_bytes)) {
            g_glm_prefetch_skip_cached++;
            continue;
        }
        ds4_gpu_glm_stream_prefetch_rdadvise(gate_abs, gate_expert_bytes);
        ds4_gpu_glm_stream_prefetch_rdadvise(up_abs, gate_expert_bytes);
        ds4_gpu_glm_stream_prefetch_rdadvise(down_abs, down_expert_bytes);
        hinted++;
    }
    g_glm_prefetch_hint_experts += (uint64_t)hinted;
    g_glm_prefetch_hint_ms += ds4_gpu_now_ms() - t0;
    pthread_mutex_unlock(&g_glm_prefetch_mutex);
    return hinted;
}

/* Called with the layer's REAL selection to score the last prediction. */
static void ds4_gpu_glm_stream_prefetch_note_selected(
        uint32_t       layer,
        const int32_t *selected_ids,
        uint32_t       n_selected) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER || !selected_ids) return;
    pthread_mutex_lock(&g_glm_prefetch_mutex);
    const uint32_t n_pred = g_glm_prefetch_predicted_n[layer];
    if (n_pred != 0) {
        for (uint32_t i = 0; i < n_selected; i++) {
            g_glm_prefetch_pred_compared++;
            for (uint32_t j = 0; j < n_pred; j++) {
                if (g_glm_prefetch_predicted[layer][j] == selected_ids[i]) {
                    g_glm_prefetch_pred_matched++;
                    break;
                }
            }
        }
        g_glm_prefetch_predicted_n[layer] = 0;
    }
    pthread_mutex_unlock(&g_glm_prefetch_mutex);
}

int ds4_gpu_stream_expert_cache_begin_selected_load(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *selected_ids,
        uint32_t                           n_selected) {
    if (!g_ssd_streaming_mode ||
        getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_EARLY_LOAD") != NULL) {
        return 1;
    }
    if (!table) return 0;
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;
    if (!model_map || !selected_ids ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_selected == 0 ||
        n_selected > DS4_METAL_STREAM_SELECTED_MAX ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes) ||
        ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                  n_total_expert,
                                                  n_selected) == 0) {
        return 1;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;

    const double load_prepare_t0 =
        ds4_gpu_stream_expert_timing_summary_enabled() ?
        ds4_gpu_now_ms() : 0.0;
    const int load_timing = load_prepare_t0 != 0.0;

    if (ds4_gpu_stream_expert_pending_load_matches(model_map,
                                                   model_size,
                                                   layer,
                                                   selected_ids,
                                                   n_total_expert,
                                                   n_selected,
                                                   gate_expert_bytes,
                                                   down_expert_bytes)) {
        return 1;
    }

    ds4_gpu_glm_stream_prefetch_note_selected(layer, selected_ids, n_selected);

    ds4_gpu_stream_expert_pending_load_clear();
    ds4_gpu_stream_expert_pending_load *p = &g_stream_expert_pending_load;
    p->active = 0;
    p->model_map = model_map;
    p->model_size = model_size;
    p->layer = layer;
    p->n_total_expert = n_total_expert;
    p->n_selected = n_selected;
    p->missing_mask = 0;
    p->n_loads = 0;
    p->n_tasks = 0;
    p->gate_expert_bytes = gate_expert_bytes;
    p->down_expert_bytes = down_expert_bytes;
    for (uint32_t i = 0; i < DS4_METAL_STREAM_SELECTED_MAX; i++) {
        p->selected_ids[i] = -1;
        p->load_slots[i] = 0;
        p->source_slots[i] = UINT32_MAX;
        p->gate_abs_offsets[i] = 0;
        p->up_abs_offsets[i] = 0;
        p->down_abs_offsets[i] = 0;
        p->gate_bufs[i] = nil;
        p->up_bufs[i] = nil;
        p->down_bufs[i] = nil;
        p->gate_inners[i] = 0;
        p->up_inners[i] = 0;
        p->down_inners[i] = 0;
    }
    memset(p->tasks, 0, sizeof(p->tasks));

    for (uint32_t i = 0; i < n_selected; i++) {
        if (selected_ids[i] < 0 || (uint32_t)selected_ids[i] >= n_total_expert) {
            fprintf(stderr,
                    "ds4: Metal streaming early-load expert id %d is outside 0..%u\n",
                    selected_ids[i],
                    n_total_expert);
            return 0;
        }
        p->selected_ids[i] = selected_ids[i];
        const uint64_t expert_id = (uint64_t)(uint32_t)selected_ids[i];
        if (expert_id > UINT64_MAX / gate_expert_bytes ||
            expert_id > UINT64_MAX / down_expert_bytes) {
            fprintf(stderr, "ds4: Metal streaming early-load offset overflow\n");
            return 0;
        }
        const uint64_t gate_rel = expert_id * gate_expert_bytes;
        const uint64_t down_rel = expert_id * down_expert_bytes;
        if (gate_rel > UINT64_MAX - gate_offset ||
            gate_rel > UINT64_MAX - up_offset ||
            down_rel > UINT64_MAX - down_offset) {
            fprintf(stderr, "ds4: Metal streaming early-load offset overflow\n");
            return 0;
        }
        p->gate_abs_offsets[i] = gate_offset + gate_rel;
        p->up_abs_offsets[i] = up_offset + gate_rel;
        p->down_abs_offsets[i] = down_offset + down_rel;

        ds4_gpu_stream_expert_cache_entry *e =
            &g_stream_expert_cache[layer][(uint32_t)selected_ids[i]];
        if (ds4_gpu_stream_expert_cache_entry_matches(e,
                                                      model_map,
                                                      model_size,
                                                      p->gate_abs_offsets[i],
                                                      p->up_abs_offsets[i],
                                                      p->down_abs_offsets[i],
                                                      gate_expert_bytes,
                                                      down_expert_bytes)) {
            continue;
        }

        uint32_t source = UINT32_MAX;
        for (uint32_t prev = 0; prev < i; prev++) {
            if (selected_ids[prev] == selected_ids[i] &&
                p->gate_abs_offsets[prev] == p->gate_abs_offsets[i] &&
                p->up_abs_offsets[prev] == p->up_abs_offsets[i] &&
                p->down_abs_offsets[prev] == p->down_abs_offsets[i] &&
                (p->missing_mask & (1u << prev)) != 0) {
                source = p->source_slots[prev] != UINT32_MAX ?
                         p->source_slots[prev] : prev;
                break;
            }
        }
        if (source != UINT32_MAX) {
            p->source_slots[i] = source;
            p->missing_mask |= 1u << i;
            continue;
        }
        p->source_slots[i] = i;
        p->missing_mask |= 1u << i;
        p->load_slots[p->n_loads++] = i;
    }
    if (p->n_loads == 0) return 1;

    const uint32_t cache_budget =
        ds4_gpu_stream_expert_cache_configured_budget();
    uint32_t reserved_entries = g_stream_expert_cache_entry_count;
    ds4_gpu_stream_expert_reusable_buffers
        batch_reuse[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    for (uint32_t i = 0; i < DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED; i++) {
        batch_reuse[i] =
            (ds4_gpu_stream_expert_reusable_buffers){ nil, nil, nil, 0, 0, 0 };
    }
    uint32_t batch_reuse_count = 0;
    if (cache_budget != 0 &&
        reserved_entries >= cache_budget &&
        p->n_loads > 1 &&
        ds4_gpu_stream_expert_batch_reuse_enabled(gate_expert_bytes,
                                                  down_expert_bytes)) {
        const double reuse_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
        batch_reuse_count =
            ds4_gpu_stream_expert_cache_take_reusable_batch(
                    p->n_loads,
                    layer,
                    selected_ids,
                    n_selected,
                    gate_expert_bytes,
                    down_expert_bytes,
                    batch_reuse);
        if (load_timing) {
            ds4_gpu_stream_expert_timing_note_prepare_batch_reuse(
                    ds4_gpu_now_ms() - reuse_t0);
        }
    }
    for (uint32_t load_i = 0; load_i < p->n_loads; load_i++) {
        const uint32_t slot = p->load_slots[load_i];
        const uint32_t expert = (uint32_t)p->selected_ids[slot];
        const int force_reuse =
            cache_budget != 0 && reserved_entries >= cache_budget;

        if (g_stream_expert_cache_required_floor == 0) {
            ds4_gpu_stream_expert_readahead_range(p->gate_abs_offsets[slot],
                                                  gate_expert_bytes);
            ds4_gpu_stream_expert_readahead_range(p->up_abs_offsets[slot],
                                                  gate_expert_bytes);
            ds4_gpu_stream_expert_readahead_range(p->down_abs_offsets[slot],
                                                  down_expert_bytes);
        }

        if (load_i < batch_reuse_count &&
            batch_reuse[load_i].gate_buffer &&
            batch_reuse[load_i].up_buffer &&
            batch_reuse[load_i].down_buffer) {
            p->gate_bufs[load_i] = batch_reuse[load_i].gate_buffer;
            p->up_bufs[load_i] = batch_reuse[load_i].up_buffer;
            p->down_bufs[load_i] = batch_reuse[load_i].down_buffer;
            p->gate_inners[load_i] = batch_reuse[load_i].gate_inner;
            p->up_inners[load_i] = batch_reuse[load_i].up_inner;
            p->down_inners[load_i] = batch_reuse[load_i].down_inner;
        } else {
            const double buffer_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
            const int prepared =
                ds4_gpu_stream_expert_cache_prepare_load_buffers(layer,
                                                                 expert,
                                                                 layer,
                                                                 selected_ids,
                                                                 n_selected,
                                                                 gate_expert_bytes,
                                                                 down_expert_bytes,
                                                                 force_reuse,
                                                                 &p->gate_bufs[load_i],
                                                                 &p->up_bufs[load_i],
                                                                 &p->down_bufs[load_i],
                                                                 &p->gate_inners[load_i],
                                                                 &p->up_inners[load_i],
                                                                 &p->down_inners[load_i]);
            if (load_timing) {
                ds4_gpu_stream_expert_timing_note_prepare_buffer(
                        ds4_gpu_now_ms() - buffer_t0);
            }
            if (!prepared) {
                ds4_gpu_stream_expert_pending_load_release_buffers(p);
                return 0;
            }
        }
        if (!ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
            ds4_gpu_stream_expert_pending_load_release_buffers(p);
            return 0;
        }
        if (!force_reuse && reserved_entries < UINT32_MAX) {
            reserved_entries++;
        }

        if (g_stream_expert_cache_required_floor != 0) {
            ds4_gpu_stream_expert_readahead_range(p->gate_abs_offsets[slot],
                                                  gate_expert_bytes);
            ds4_gpu_stream_expert_readahead_range(p->up_abs_offsets[slot],
                                                  gate_expert_bytes);
            ds4_gpu_stream_expert_readahead_range(p->down_abs_offsets[slot],
                                                  down_expert_bytes);
        }

        uint8_t *gate_dst = (uint8_t *)[p->gate_bufs[load_i] contents] +
                             p->gate_inners[load_i];
        uint8_t *up_dst = (uint8_t *)[p->up_bufs[load_i] contents] +
                           p->up_inners[load_i];
        uint8_t *down_dst = (uint8_t *)[p->down_bufs[load_i] contents] +
                             p->down_inners[load_i];
        if (!gate_dst || !up_dst || !down_dst) {
            ds4_gpu_stream_expert_pending_load_release_buffers(p);
            return 0;
        }
        const double task_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
        if (!ds4_gpu_stream_expert_append_record_tasks(
                p->tasks, DS4_METAL_STREAM_SELECTED_MAX_TASKS, &p->n_tasks,
                p->gate_abs_offsets[slot], p->up_abs_offsets[slot],
                p->down_abs_offsets[slot], gate_expert_bytes,
                down_expert_bytes, gate_dst, up_dst, down_dst,
                ds4_gpu_stream_expert_record_read_plan())) {
            ds4_gpu_stream_expert_pending_load_release_buffers(p);
            return 0;
        }
        if (load_timing) {
            ds4_gpu_stream_expert_timing_note_prepare_task(
                    1,
                    ds4_gpu_now_ms() - task_t0);
        }
    }

    if (!ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
        ds4_gpu_stream_expert_pending_load_release_buffers(p);
        return 0;
    }

    const uint32_t n_workers =
        ds4_gpu_stream_expert_pread_thread_count(p->n_tasks);
    p->start_ms = ds4_gpu_now_ms();
    if (load_timing) {
        p->prepare_ms = p->start_ms - load_prepare_t0;
    }
    if (ds4_gpu_stream_expert_pread_pool_begin(p->tasks,
                                               p->n_tasks,
                                               n_workers)) {
        p->active = 1;
        if (ds4_gpu_stream_expert_pending_load_profile_enabled()) {
            fprintf(stderr,
                    "ds4: Metal streaming expert early-load begin layer=%u experts=%u tensors=%u threads=%u\n",
                    layer,
                    p->n_loads,
                    p->n_tasks,
                    n_workers);
        }
        return 1;
    }

    uint64_t read_bytes = 0;
    double read_ms = 0.0;
    if (!ds4_gpu_stream_expert_pread_tasks(p->tasks,
                                           p->n_tasks,
                                           &read_bytes,
                                           &read_ms)) {
        ds4_gpu_stream_expert_cache_note_pread(
            p->layer,
            0,
            ds4_gpu_stream_expert_pread_successful_syscalls(
                p->tasks, p->n_tasks),
            read_bytes,
            read_ms);
        ds4_gpu_stream_expert_pending_load_release_buffers(p);
        return 0;
    }
    (void)read_bytes;
    if (!ds4_gpu_stream_expert_pending_load_install(p, NULL, read_ms)) {
        ds4_gpu_stream_expert_pending_load_release_buffers(p);
        return 0;
    }
    ds4_gpu_stream_expert_pending_load_release_buffers(p);
    p->n_tasks = 0;
    p->n_loads = 0;
    p->prepare_ms = 0.0;
    return 1;
}

static void ds4_gpu_glm_stream_selected_prefetch_set(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *selected_ids,
        uint32_t                           n_selected) {
    g_glm_stream_selected_prefetch.active = 0;
    if (!table || !selected_ids || n_selected == 0 ||
        n_selected > DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED) {
        return;
    }
    g_glm_stream_selected_prefetch.model_map = table->model_map;
    g_glm_stream_selected_prefetch.model_size = table->model_size;
    g_glm_stream_selected_prefetch.layer = table->layer;
    g_glm_stream_selected_prefetch.n_total_expert = table->n_total_expert;
    g_glm_stream_selected_prefetch.n_selected = n_selected;
    g_glm_stream_selected_prefetch.gate_offset = table->gate_offset;
    g_glm_stream_selected_prefetch.up_offset = table->up_offset;
    g_glm_stream_selected_prefetch.down_offset = table->down_offset;
    g_glm_stream_selected_prefetch.gate_expert_bytes =
        table->gate_expert_bytes;
    g_glm_stream_selected_prefetch.down_expert_bytes =
        table->down_expert_bytes;
    for (uint32_t i = 0; i < n_selected; i++) {
        g_glm_stream_selected_prefetch.selected_ids[i] = selected_ids[i];
    }
    g_glm_stream_selected_prefetch.active = 1;
}

static int ds4_gpu_glm_stream_selected_prefetch_take(
        const void *model_map,
        uint64_t model_size,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t n_selected,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        int32_t *selected_ids_out) {
    if (!selected_ids_out || !g_glm_stream_selected_prefetch.active) return 0;
    ds4_gpu_glm_stream_selected_prefetch *p = &g_glm_stream_selected_prefetch;
    if (p->model_map != model_map ||
        p->model_size != model_size ||
        p->layer != layer ||
        p->n_total_expert != n_total_expert ||
        p->n_selected != n_selected ||
        p->gate_offset != gate_offset ||
        p->up_offset != up_offset ||
        p->down_offset != down_offset ||
        p->gate_expert_bytes != gate_expert_bytes ||
        p->down_expert_bytes != down_expert_bytes) {
        return 0;
    }
    for (uint32_t i = 0; i < n_selected; i++) {
        selected_ids_out[i] = p->selected_ids[i];
    }
    p->active = 0;
    return 1;
}

int ds4_gpu_glm_stream_expert_cache_begin_selected_load_tensor(
        const ds4_gpu_stream_expert_table *table,
        const ds4_gpu_tensor              *selected,
        uint32_t                           n_selected) {
    g_glm_stream_selected_prefetch.active = 0;
    if (!g_ssd_streaming_mode ||
        getenv("DS4_METAL_DISABLE_GLM_STREAMING_EXPERT_EARLY_LOAD") != NULL) {
        return 1;
    }
    if (!table || !selected || n_selected == 0 ||
        n_selected > DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED) {
        return 1;
    }

    const int timing = ds4_gpu_stream_expert_timing_summary_enabled();
    double t0 = timing ? ds4_gpu_now_ms() : 0.0;
    double selected_sync_ms = 0.0;
    double selected_copy_ms = 0.0;
    double selected_bind_ms = 0.0;
    const int had_batch = g_batch_cb != nil;
    if (had_batch) {
        if (ds4_gpu_end_commands() == 0) return 0;
        if (timing) {
            selected_sync_ms = ds4_gpu_now_ms() - t0;
            t0 = ds4_gpu_now_ms();
        }
    }

    int32_t selected_ids[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    for (uint32_t i = 0;
         i < DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED; i++) {
        selected_ids[i] = -1;
    }
    int ok = ds4_gpu_tensor_read(
        selected, 0, selected_ids,
        (uint64_t)n_selected * sizeof(selected_ids[0])) != 0;
    if (timing) {
        selected_copy_ms = ds4_gpu_now_ms() - t0;
        t0 = ds4_gpu_now_ms();
    }
    if (ok) {
        ok = ds4_gpu_stream_expert_cache_begin_selected_load(
            table, selected_ids, n_selected) != 0;
    }
    if (timing) {
        selected_bind_ms = ds4_gpu_now_ms() - t0;
        ds4_gpu_stream_expert_timing_note_selected(selected_sync_ms,
                                                   selected_copy_ms,
                                                   selected_bind_ms);
    }
    if (ok) {
        ds4_gpu_glm_stream_selected_prefetch_set(
            table, selected_ids, n_selected);
    }
    if (had_batch && ds4_gpu_begin_commands() == 0) ok = 0;
    return ok;
}

static int ds4_gpu_stream_expert_cache_load_selected_missing(
        const void    *model_map,
        uint64_t       model_size,
        uint32_t       layer,
        const int32_t *selected_ids,
        uint32_t       n_total_expert,
        uint32_t       n_selected,
        const int32_t *protect_ids,
        uint32_t       n_protect,
        const uint64_t *gate_abs_offsets,
        const uint64_t *up_abs_offsets,
        const uint64_t *down_abs_offsets,
        uint64_t       gate_expert_bytes,
        uint64_t       down_expert_bytes,
        uint32_t       missing_mask,
        ds4_gpu_stream_expert_cache_entry **entries) {
    if (!g_ssd_streaming_mode ||
        !model_map ||
        !selected_ids ||
        !gate_abs_offsets ||
        !up_abs_offsets ||
        !down_abs_offsets ||
        !entries ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_selected == 0 ||
        n_selected > DS4_METAL_STREAM_SELECTED_MAX ||
        (n_protect != 0 && !protect_ids) ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes) ||
        ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                  n_total_expert,
                                                  n_selected) == 0) {
        return 0;
    }
    missing_mask &= (1u << n_selected) - 1u;
    if (missing_mask == 0) return 1;
    if (g_stream_expert_pending_load.active &&
        n_selected <= DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED) {
        if (ds4_gpu_stream_expert_pending_load_matches(model_map,
                                                       model_size,
                                                       layer,
                                                       selected_ids,
                                                       n_total_expert,
                                                       n_selected,
                                                       gate_expert_bytes,
                                                       down_expert_bytes)) {
            if (!ds4_gpu_stream_expert_pending_load_finish(entries)) return 0;
            for (uint32_t i = 0; i < n_selected; i++) {
                if ((missing_mask & (1u << i)) != 0 && entries[i]) {
                    missing_mask &= ~(1u << i);
                }
            }
            if (missing_mask == 0) return 1;
        } else {
            ds4_gpu_stream_expert_pending_load_clear();
        }
    } else if (g_stream_expert_pending_load.active) {
        ds4_gpu_stream_expert_pending_load_clear();
    }

    const int load_timing = ds4_gpu_stream_expert_timing_summary_enabled();
    double load_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
    double load_prepare_ms = 0.0;
    double load_modify_ms = 0.0;
    double load_install_ms = 0.0;

    uint32_t load_slots[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    uint32_t source_slots[DS4_METAL_STREAM_SELECTED_MAX];
    for (uint32_t i = 0; i < DS4_METAL_STREAM_SELECTED_MAX; i++) {
        source_slots[i] = UINT32_MAX;
    }
    uint32_t n_loads = 0;
    for (uint32_t i = 0; i < n_selected; i++) {
        if ((missing_mask & (1u << i)) == 0) continue;
        if (entries[i]) {
            source_slots[i] = i;
            continue;
        }
        if (selected_ids[i] < 0 || (uint32_t)selected_ids[i] >= n_total_expert) {
            fprintf(stderr,
                    "ds4: Metal streaming selected missing expert id %d is outside 0..%u\n",
                    selected_ids[i],
                    n_total_expert);
            return 0;
        }
        uint32_t source = UINT32_MAX;
        for (uint32_t prev = 0; prev < i; prev++) {
            if (selected_ids[prev] == selected_ids[i] &&
                gate_abs_offsets[prev] == gate_abs_offsets[i] &&
                up_abs_offsets[prev] == up_abs_offsets[i] &&
                down_abs_offsets[prev] == down_abs_offsets[i] &&
                (entries[prev] || (missing_mask & (1u << prev)) != 0)) {
                source = source_slots[prev] != UINT32_MAX ?
                         source_slots[prev] : prev;
                break;
            }
        }
        if (source != UINT32_MAX) {
            source_slots[i] = source;
            continue;
        }
        source_slots[i] = i;
        load_slots[n_loads++] = i;
    }
    if (n_loads == 0) {
        for (uint32_t i = 0; i < n_selected; i++) {
            if ((missing_mask & (1u << i)) == 0 || entries[i]) continue;
            const uint32_t source = source_slots[i];
            if (source >= n_selected || !entries[source]) return 0;
            entries[i] = entries[source];
            entries[i]->use_count++;
        }
        return 1;
    }

    __strong id<MTLBuffer>
        gate_bufs[DS4_METAL_STREAM_SELECTED_MAX] = { nil };
    __strong id<MTLBuffer>
        up_bufs[DS4_METAL_STREAM_SELECTED_MAX] = { nil };
    __strong id<MTLBuffer>
        down_bufs[DS4_METAL_STREAM_SELECTED_MAX] = { nil };
    NSUInteger gate_inners[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    NSUInteger up_inners[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    NSUInteger down_inners[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    ds4_gpu_stream_expert_pread_task
        tasks[DS4_METAL_STREAM_SELECTED_MAX_TASKS];
    memset(tasks, 0, sizeof(tasks));
    uint32_t n_tasks = 0;
    const uint32_t cache_budget =
        ds4_gpu_stream_expert_cache_configured_budget();
    uint32_t reserved_entries = g_stream_expert_cache_entry_count;
    ds4_gpu_stream_expert_reusable_buffers
        batch_reuse[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    for (uint32_t i = 0; i < DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED; i++) {
        batch_reuse[i] =
            (ds4_gpu_stream_expert_reusable_buffers){ nil, nil, nil, 0, 0, 0 };
    }
    uint32_t batch_reuse_count = 0;
    if (cache_budget != 0 &&
        reserved_entries >= cache_budget &&
        n_loads > 1 &&
        ds4_gpu_stream_expert_batch_reuse_enabled(gate_expert_bytes,
                                                  down_expert_bytes)) {
        const double reuse_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
        batch_reuse_count =
            ds4_gpu_stream_expert_cache_take_reusable_batch(
                    n_loads,
                    layer,
                    selected_ids,
                    n_selected,
                    gate_expert_bytes,
                    down_expert_bytes,
                    batch_reuse);
        if (load_timing) {
            ds4_gpu_stream_expert_timing_note_prepare_batch_reuse(
                    ds4_gpu_now_ms() - reuse_t0);
        }
    }

    for (uint32_t load_i = 0; load_i < n_loads; load_i++) {
        const uint32_t slot = load_slots[load_i];
        const uint32_t expert = (uint32_t)selected_ids[slot];
        const int force_reuse =
            cache_budget != 0 && reserved_entries >= cache_budget;

        if (g_stream_expert_cache_required_floor == 0) {
            ds4_gpu_stream_expert_readahead_range(gate_abs_offsets[slot],
                                                  gate_expert_bytes);
            ds4_gpu_stream_expert_readahead_range(up_abs_offsets[slot],
                                                  gate_expert_bytes);
            ds4_gpu_stream_expert_readahead_range(down_abs_offsets[slot],
                                                  down_expert_bytes);
        }

        if (load_i < batch_reuse_count &&
            batch_reuse[load_i].gate_buffer &&
            batch_reuse[load_i].up_buffer &&
            batch_reuse[load_i].down_buffer) {
            gate_bufs[load_i] = batch_reuse[load_i].gate_buffer;
            up_bufs[load_i] = batch_reuse[load_i].up_buffer;
            down_bufs[load_i] = batch_reuse[load_i].down_buffer;
            gate_inners[load_i] = batch_reuse[load_i].gate_inner;
            up_inners[load_i] = batch_reuse[load_i].up_inner;
            down_inners[load_i] = batch_reuse[load_i].down_inner;
        } else {
            const double buffer_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
            const int prepared =
                ds4_gpu_stream_expert_cache_prepare_load_buffers(
                        layer,
                        expert,
                        layer,
                        n_protect != 0 ? protect_ids : selected_ids,
                        n_protect != 0 ? n_protect : n_selected,
                        gate_expert_bytes,
                        down_expert_bytes,
                        force_reuse,
                        &gate_bufs[load_i],
                        &up_bufs[load_i],
                        &down_bufs[load_i],
                        &gate_inners[load_i],
                        &up_inners[load_i],
                        &down_inners[load_i]);
            if (load_timing) {
                ds4_gpu_stream_expert_timing_note_prepare_buffer(
                        ds4_gpu_now_ms() - buffer_t0);
            }
            if (!prepared) return 0;
        }
        if (!ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
            return 0;
        }
        if (!force_reuse && reserved_entries < UINT32_MAX) {
            reserved_entries++;
        }
        if (!gate_bufs[load_i] || !up_bufs[load_i] || !down_bufs[load_i]) {
            return 0;
        }

        if (g_stream_expert_cache_required_floor != 0) {
            ds4_gpu_stream_expert_readahead_range(gate_abs_offsets[slot],
                                                  gate_expert_bytes);
            ds4_gpu_stream_expert_readahead_range(up_abs_offsets[slot],
                                                  gate_expert_bytes);
            ds4_gpu_stream_expert_readahead_range(down_abs_offsets[slot],
                                                  down_expert_bytes);
        }

        uint8_t *gate_dst = (uint8_t *)[gate_bufs[load_i] contents] +
                             gate_inners[load_i];
        uint8_t *up_dst = (uint8_t *)[up_bufs[load_i] contents] +
                           up_inners[load_i];
        uint8_t *down_dst = (uint8_t *)[down_bufs[load_i] contents] +
                             down_inners[load_i];
        if (!gate_dst || !up_dst || !down_dst) return 0;

        const double task_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
        if (!ds4_gpu_stream_expert_append_record_tasks(
                tasks, DS4_METAL_STREAM_SELECTED_MAX_TASKS, &n_tasks,
                gate_abs_offsets[slot], up_abs_offsets[slot],
                down_abs_offsets[slot], gate_expert_bytes,
                down_expert_bytes, gate_dst, up_dst, down_dst,
                ds4_gpu_stream_expert_record_read_plan())) {
            return 0;
        }
        if (load_timing) {
            ds4_gpu_stream_expert_timing_note_prepare_task(
                    1,
                    ds4_gpu_now_ms() - task_t0);
        }
    }

    if (!ds4_gpu_stream_expert_cache_required_floor_satisfied()) {
        return 0;
    }

    if (load_timing) {
        const double now_ms = ds4_gpu_now_ms();
        load_prepare_ms = now_ms - load_t0;
        load_t0 = now_ms;
    }

    uint64_t read_bytes = 0;
    double read_ms = 0.0;
    const int ok = ds4_gpu_stream_expert_pread_tasks(tasks,
                                                     n_tasks,
                                                     &read_bytes,
                                                     &read_ms);
    const uint64_t pread_syscalls =
        ds4_gpu_stream_expert_pread_successful_syscalls(tasks, n_tasks);
    if (!ok) {
        ds4_gpu_stream_expert_cache_note_pread(
            layer, 0, pread_syscalls, read_bytes, read_ms);
        return 0;
    }
    if (load_timing) {
        load_t0 = ds4_gpu_now_ms();
    }
    ds4_gpu_stream_expert_cache_note_pread(
        layer, n_loads, pread_syscalls, read_bytes, read_ms);

    for (uint32_t load_i = 0; load_i < n_loads; load_i++) {
        [gate_bufs[load_i] didModifyRange:NSMakeRange(gate_inners[load_i], (NSUInteger)gate_expert_bytes)];
        [up_bufs[load_i] didModifyRange:NSMakeRange(up_inners[load_i], (NSUInteger)gate_expert_bytes)];
        [down_bufs[load_i] didModifyRange:NSMakeRange(down_inners[load_i], (NSUInteger)down_expert_bytes)];
    }
    if (load_timing) {
        const double now_ms = ds4_gpu_now_ms();
        load_modify_ms = now_ms - load_t0;
        load_t0 = now_ms;
    }
    if (getenv("DS4_METAL_STREAMING_EXPERT_PREAD_PROFILE") != NULL) {
        fprintf(stderr,
                "ds4: Metal streaming expert parallel pread layer=%u experts=%u tensors=%u "
                "threads=%u bytes=%.2f GiB wall=%.3f ms\n",
                layer,
                n_loads,
                n_tasks,
                ds4_gpu_stream_expert_pread_thread_count(n_tasks),
                ds4_gpu_gib(read_bytes),
                read_ms);
    }

    for (uint32_t load_i = 0; load_i < n_loads; load_i++) {
        const uint32_t slot = load_slots[load_i];
        const uint32_t expert = (uint32_t)selected_ids[slot];
        ds4_gpu_stream_expert_cache_entry *entry =
            ds4_gpu_stream_expert_cache_install_loaded(model_map,
                                                       model_size,
                                                       layer,
                                                       expert,
                                                       n_total_expert,
                                                       gate_abs_offsets[slot],
                                                       up_abs_offsets[slot],
                                                       down_abs_offsets[slot],
                                                       gate_expert_bytes,
                                                       down_expert_bytes,
                                                       gate_bufs[load_i],
                                                       up_bufs[load_i],
                                                       down_bufs[load_i],
                                                       gate_inners[load_i],
                                                       up_inners[load_i],
                                                       down_inners[load_i]);
        if (!entry) return 0;
        entries[slot] = entry;
    }

    for (uint32_t i = 0; i < n_selected; i++) {
        if ((missing_mask & (1u << i)) == 0 || entries[i]) continue;
        const uint32_t source = source_slots[i];
        if (source >= n_selected || !entries[source]) return 0;
        entries[i] = entries[source];
        entries[i]->use_count++;
    }
    for (uint32_t i = 0; i < n_selected; i++) {
        if ((missing_mask & (1u << i)) != 0 && !entries[i]) return 0;
    }
    if (load_timing) {
        load_install_ms = ds4_gpu_now_ms() - load_t0;
        ds4_gpu_stream_expert_timing_note_load_detail(load_prepare_ms,
                                                      read_ms,
                                                      load_modify_ms,
                                                      load_install_ms);
    }
    return 1;
}

static uint64_t ds4_gpu_qwen35_stream_next_generation(void) {
    g_qwen35_stream_generation++;
    if (g_qwen35_stream_generation == 0) g_qwen35_stream_generation++;
    return g_qwen35_stream_generation;
}

static void ds4_gpu_qwen35_stream_release_staging(
        ds4_gpu_qwen35_stream_pending *p) {
    if (!p) return;
    for (uint32_t i = 0; i < DS4_METAL_QWEN35_STREAM_MAX_EXPERT; i++) {
        if (p->staging_slab_owned[i] && !p->load_installed[i]) {
            bool already_recycled = false;
            for (uint32_t previous = 0; previous < i; previous++) {
                if (p->staging_slab_owned[previous] &&
                    !p->load_installed[previous] &&
                    p->staging_slab_slot[previous] ==
                        p->staging_slab_slot[i]) {
                    already_recycled = true;
                    break;
                }
            }
            if (!already_recycled) {
                /* prepare_load_buffers() transfers a slab slot out of the
                 * cache (or allocates a fresh one) before pread starts.  A
                 * failed/cancelled transaction therefore owns that slot even
                 * though no cache entry can recycle it.  Return it here while
                 * retaining the allocator's normal locked-for-reuse policy. */
                ds4_gpu_stream_expert_slab_push_free_slot(
                    p->staging_slab_slot[i]);
            }
        }
    }
    /* Keep every ownership flag intact through the recycle pass above.  A
     * future layout may alias one staging slot; clearing as we iterate would
     * hide that earlier owner and enqueue the same free slot twice. */
    for (uint32_t i = 0; i < DS4_METAL_QWEN35_STREAM_MAX_EXPERT; i++) {
        p->gate_bufs[i] = nil;
        p->up_bufs[i] = nil;
        p->down_bufs[i] = nil;
        p->gate_inners[i] = 0;
        p->up_inners[i] = 0;
        p->down_inners[i] = 0;
        p->staging_slab_slot[i] = 0;
        p->staging_slab_owned[i] = 0;
        p->load_installed[i] = 0;
    }
}

#ifdef DS4_TEST_HOOKS
/* White-box model-free proof for the failure unwind.  It exercises the same
 * ownership flags used after pread failure: duplicate aliases recycle once,
 * while a slot already transferred into a cache entry is never returned. */
int ds4_gpu_internal_qwen35_stream_staging_rollback_test(void) {
    if (g_stream_expert_cache_free_slot_count >=
        DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        return 0;
    }
    const uint32_t before = g_stream_expert_cache_free_slot_count;
    const uint32_t saved = g_stream_expert_cache_free_slots[before];
    ds4_gpu_qwen35_stream_pending pending = {0};
    pending.staging_slab_owned[0] = 1;
    pending.staging_slab_slot[0] = 7;
    pending.staging_slab_owned[1] = 1;
    pending.staging_slab_slot[1] = 7;
    pending.staging_slab_owned[2] = 1;
    pending.staging_slab_slot[2] = 8;
    pending.load_installed[2] = 1;

    ds4_gpu_qwen35_stream_release_staging(&pending);
    const int ok =
        g_stream_expert_cache_free_slot_count == before + 1u &&
        g_stream_expert_cache_free_slots[before] == 7u &&
        pending.staging_slab_owned[0] == 0 &&
        pending.staging_slab_owned[1] == 0 &&
        pending.staging_slab_owned[2] == 0 &&
        pending.load_installed[2] == 0;
    g_stream_expert_cache_free_slot_count = before;
    g_stream_expert_cache_free_slots[before] = saved;
    return ok;
}

/* White-box proof that an authenticated release cannot poison the engine when
 * a drain reports a consumed pread failure.  The production wait returns false
 * when its pool is unavailable, after pending_load_finish() has already cleared
 * the active record; the lease must be revoked even though release reports the
 * error to its caller. */
int ds4_gpu_internal_qwen35_lease_error_unwind_test(void) {
    if (g_stream_expert_cache_lease.active ||
        g_stream_expert_pending_load.active ||
        g_qwen35_stream_pending.state != DS4_QWEN35_STREAM_IO_EMPTY ||
        g_batch_cb || [g_pending_cbs count] != 0 ||
        g_stream_expert_pread_pool_remaining_workers != 0) {
        return 0;
    }

    const int saved_pool_initialized =
        g_stream_expert_pread_pool_initialized;
    const uint64_t lease_id =
        ds4_gpu_stream_expert_cache_lease_next_id();
    g_stream_expert_cache_lease.owner = pthread_self();
    g_stream_expert_cache_lease.id = lease_id;
    g_stream_expert_cache_lease.layer = 0;
    g_stream_expert_cache_lease.domain =
        DS4_GPU_STREAM_EXPERT_LEASE_TARGET;
    g_stream_expert_cache_lease.active = 1;
    g_stream_expert_pending_load.active = 1;
    g_stream_expert_pread_pool_initialized = 0;

    const int release_ok =
        ds4_gpu_stream_expert_cache_release_layer_lease(lease_id);
    const int ok = !release_ok &&
        !g_stream_expert_cache_lease.active &&
        !g_stream_expert_pending_load.active;
    g_stream_expert_pread_pool_initialized = saved_pool_initialized;
    return ok;
}
#endif

static void hebrus_gpu_qwen35_stream_reset(
        ds4_gpu_qwen35_stream_pending *p) {
    if (!p) return;
    ds4_gpu_qwen35_stream_release_staging(p);
    if (p->selected_ids_heap) free(p->selected_ids);
    p->selected_ids = NULL;
    p->selected_id_count = 0;
    p->selected_ids_heap = 0;
    p->selected_buffer = nil;
    p->state = DS4_QWEN35_STREAM_IO_EMPTY;
    p->generation = 0;
    memset(&p->owner, 0, sizeof(p->owner));
    p->model_map = NULL;
    p->model_size = 0;
    p->layer = 0;
    p->n_tokens = 0;
    p->n_selected = 0;
    p->n_total_expert = 0;
    p->gate_offset = 0;
    p->up_offset = 0;
    p->down_offset = 0;
    p->gate_expert_bytes = 0;
    p->down_expert_bytes = 0;
    p->selected_offset = 0;
    p->selected_bytes = 0;
    p->n_unique = 0;
    p->n_loads = 0;
    p->n_tasks = 0;
    p->max_inflight_reads = 0;
    p->asynchronous = 0;
    p->io_accounted = 0;
    p->start_ms = 0.0;
    memset(p->unique_ids, 0, sizeof(p->unique_ids));
    memset(p->load_unique, 0, sizeof(p->load_unique));
    memset(p->gate_abs_offsets, 0, sizeof(p->gate_abs_offsets));
    memset(p->up_abs_offsets, 0, sizeof(p->up_abs_offsets));
    memset(p->down_abs_offsets, 0, sizeof(p->down_abs_offsets));
    memset(p->staging_slab_slot, 0, sizeof(p->staging_slab_slot));
    memset(p->staging_slab_owned, 0, sizeof(p->staging_slab_owned));
    memset(p->load_installed, 0, sizeof(p->load_installed));
    memset(p->installed, 0, sizeof(p->installed));
    memset(p->tasks, 0, sizeof(p->tasks));
}

/* Hand the synchronized router IDs to the routed-MoE consumer.  Batch routes
 * transfer their heap allocation; a scalar top-8 route copies the pending
 * inline array into caller storage before reset.  Both paths therefore reuse
 * the immutable host copy that already scheduled SSD reads without exposing a
 * pointer into resettable pending state. */
static int hebrus_gpu_qwen35_stream_take_selected_ids(
        ds4_gpu_qwen35_stream_pending *p,
        uint64_t                       expected_count,
        int32_t                       *inline_ids,
        uint64_t                       inline_capacity,
        int32_t                      **selected_ids) {
    if (!selected_ids) return 0;
    *selected_ids = NULL;
    if (!p || expected_count == 0 ||
        p->selected_id_count != expected_count ||
        !p->selected_ids) {
        return 0;
    }
    if (p->selected_ids_heap) {
        *selected_ids = p->selected_ids;
    } else {
        if (!inline_ids || inline_capacity < expected_count) return 0;
        memcpy(inline_ids,
               p->selected_ids,
               (size_t)expected_count * sizeof(inline_ids[0]));
        *selected_ids = inline_ids;
    }
    p->selected_ids = NULL;
    p->selected_id_count = 0;
    p->selected_ids_heap = 0;
    return 1;
}

int hebrus_gpu_internal_qwen35_stream_selected_ids_ownership_test(void) {
    ds4_gpu_qwen35_stream_pending pending = {0};
    pending.selected_id_count = 3;
    pending.selected_ids = malloc(
        (size_t)pending.selected_id_count * sizeof(pending.selected_ids[0]));
    if (!pending.selected_ids) return 0;
    pending.selected_ids_heap = 1;
    pending.selected_ids[0] = 17;
    pending.selected_ids[1] = 5;
    pending.selected_ids[2] = 17;

    int32_t *taken = NULL;
    int ok =
        !hebrus_gpu_qwen35_stream_take_selected_ids(
            &pending, 3, NULL, 0, NULL) &&
        pending.selected_ids != NULL &&
        pending.selected_id_count == 3 &&
        hebrus_gpu_qwen35_stream_take_selected_ids(
            &pending, 3, NULL, 0, &taken);
    hebrus_gpu_qwen35_stream_reset(&pending);
    ok = ok && taken &&
         taken[0] == 17 && taken[1] == 5 && taken[2] == 17;
    free(taken);

    pending.selected_id_count = 2;
    pending.selected_ids = malloc(
        (size_t)pending.selected_id_count * sizeof(pending.selected_ids[0]));
    if (!pending.selected_ids) return 0;
    pending.selected_ids_heap = 1;
    int32_t *mismatch = (int32_t *)(uintptr_t)1;
    ok = ok &&
         !hebrus_gpu_qwen35_stream_take_selected_ids(
             &pending, 3, NULL, 0, &mismatch) &&
         mismatch == NULL &&
         pending.selected_ids != NULL &&
         pending.selected_id_count == 2;
    hebrus_gpu_qwen35_stream_reset(&pending);

    pending.selected_ids = pending.selected_ids_inline;
    pending.selected_id_count =
        sizeof(pending.selected_ids_inline) /
        sizeof(pending.selected_ids_inline[0]);
    for (uint32_t i = 0; i < pending.selected_id_count; i++) {
        pending.selected_ids_inline[i] = (int32_t)(31u - i);
    }
    int32_t copied_ids[8] = { 0 };
    int32_t *inline_ids = (int32_t *)(uintptr_t)1;
    ok = ok &&
         hebrus_gpu_qwen35_stream_take_selected_ids(
             &pending,
             pending.selected_id_count,
             copied_ids,
             sizeof(copied_ids) / sizeof(copied_ids[0]),
             &inline_ids) &&
         inline_ids == copied_ids &&
         copied_ids[0] == 31 && copied_ids[7] == 24 &&
         pending.selected_ids == NULL &&
         pending.selected_id_count == 0;
    hebrus_gpu_qwen35_stream_reset(&pending);

    pending.selected_ids = pending.selected_ids_inline;
    pending.selected_id_count = 8;
    int32_t short_ids[7] = { 0 };
    int32_t *short_result = (int32_t *)(uintptr_t)1;
    ok = ok &&
         !hebrus_gpu_qwen35_stream_take_selected_ids(
             &pending,
             pending.selected_id_count,
             short_ids,
             sizeof(short_ids) / sizeof(short_ids[0]),
             &short_result) &&
         short_result == NULL &&
         pending.selected_ids == pending.selected_ids_inline &&
         pending.selected_id_count == 8;
    hebrus_gpu_qwen35_stream_reset(&pending);
    return ok;
}

enum {
    /* Below eight tokens, stable grouping changes at most 64 Qwen routes or
     * 48 DeepSeek routes. The CPU counting sort and upload are not amortized,
     * and speculative verify (normally 2-4 tokens) should stay on its lean
     * exact path. */
    DS4_METAL_EXPERT_GROUP_MIN_TOKENS = 8,
};

static void ds4_gpu_qwen35_expert_group_invalidate(void) {
    memset(&g_qwen35_expert_group_key, 0,
           sizeof(g_qwen35_expert_group_key));
}

static int ds4_gpu_qwen35_expert_group_ensure_buffer(uint32_t route_count) {
    if (!g_device || route_count == 0) {
        return 0;
    }
    const NSUInteger bytes =
        (NSUInteger)route_count * sizeof(ds4_qwen_expert_group_route);
    if (g_qwen35_expert_group_routes_buffer &&
        g_qwen35_expert_group_routes_capacity >= bytes) {
        return 1;
    }

    /* Round to a 4-KiB page and grow monotonically.  The graph's largest
     * micro-block then pays the allocation once and all smaller decode/prefill
     * shapes reuse it without transient unified-memory pressure. */
    if (bytes > NSUIntegerMax - 4095u) return 0;
    const NSUInteger capacity = (bytes + 4095u) & ~(NSUInteger)4095u;
    id<MTLBuffer> replacement = [g_device
        newBufferWithLength:capacity
        options:MTLResourceStorageModeShared | MTLCPUCacheModeWriteCombined];
    if (!replacement) return 0;
    replacement.label = @"ds4_qwen35_expert_group_routes";
    g_qwen35_expert_group_routes_buffer = replacement;
    g_qwen35_expert_group_routes_capacity = capacity;
    return 1;
}

static int ds4_gpu_expert_group_ensure_route_tiles_buffer(
        uint32_t route_tile_count) {
    if (!g_device || route_tile_count == 0) return 0;
    const NSUInteger bytes =
        (NSUInteger)route_tile_count * sizeof(ds4_expert_group_route_tile);
    if (g_expert_group_route_tiles_buffer &&
        g_expert_group_route_tiles_capacity >= bytes) {
        return 1;
    }
    if (bytes > NSUIntegerMax - 4095u) return 0;
    const NSUInteger capacity = (bytes + 4095u) & ~(NSUInteger)4095u;
    id<MTLBuffer> replacement = [g_device
        newBufferWithLength:capacity
        options:MTLResourceStorageModeShared | MTLCPUCacheModeWriteCombined];
    if (!replacement) return 0;
    replacement.label = @"ds4_expert_group_route_tiles";
    g_expert_group_route_tiles_buffer = replacement;
    g_expert_group_route_tiles_capacity = capacity;
    return 1;
}

static int ds4_gpu_qwen35_expert_group_build(
        const int32_t        *ids,
        const ds4_gpu_tensor *selected,
        uint32_t              layer,
        uint32_t              n_tokens,
        uint32_t              n_selected,
        uint32_t              n_total_expert,
        int                   schedule_request) {
    ds4_gpu_qwen35_expert_group_invalidate();
    if (!ids || !selected ||
        n_tokens < DS4_METAL_EXPERT_GROUP_MIN_TOKENS ||
        (n_selected != 6u && n_selected != 8u) ||
        n_total_expert != 256u ||
        n_tokens > UINT32_MAX / n_selected) {
        return 0;
    }
    const uint32_t route_count = n_tokens * n_selected;
    if (ds4_qwen_expert_group_plan_build(
            &g_qwen35_expert_group_plan,
            ids,
            n_tokens,
            n_selected,
            n_total_expert) != DS4_QWEN_EXPERT_GROUP_OK ||
        !ds4_gpu_qwen35_expert_group_ensure_buffer(route_count)) {
        return 0;
    }
    /* Route tiles are a second, explicitly requested schedule view.  Keeping
     * their allocation and construction here means ordinary Qwen/DeepSeek
     * GROUP builds retain the original four-array planner and single pass. */
    if ((schedule_request & DS4_GPU_EXPERT_SCHEDULE_ROUTE_TILE) != 0 &&
        (ds4_qwen_expert_group_plan_reserve_route_tiles(
             &g_qwen35_expert_group_plan,
             route_count) != DS4_QWEN_EXPERT_GROUP_OK ||
         ds4_qwen_expert_group_plan_retile(
             &g_qwen35_expert_group_plan,
             DS4_EXPERT_GROUP_ROUTE_TILE_SIZE) !=
             DS4_QWEN_EXPERT_GROUP_OK)) {
        return 0;
    }

    const NSUInteger bytes =
        (NSUInteger)route_count * sizeof(ds4_qwen_expert_group_route);
    void *dst = [g_qwen35_expert_group_routes_buffer contents];
    if (!dst) return 0;
    memcpy(dst, g_qwen35_expert_group_plan.grouped_routes, bytes);

    g_qwen35_expert_group_key = (ds4_gpu_qwen35_expert_group_key) {
        .valid = 1,
        .selected_buffer = ds4_gpu_tensor_buffer(selected),
        .selected_offset = ds4_gpu_tensor_offset(selected),
        .selected_bytes = (uint64_t)route_count * sizeof(int32_t),
        .layer = layer,
        .n_tokens = n_tokens,
        .n_selected = n_selected,
        .n_total_expert = n_total_expert,
        .route_count = route_count,
        .route_tile_count = g_qwen35_expert_group_plan.route_tile_count,
        .route_tiles_uploaded = 0,
    };
    return 1;
}

/* Upload route tiles only for the DeepSeek tiled kernel.  Qwen and the plain
 * grouped IQ2/Q4 kernels continue to upload exactly their historical route
 * table and pay no extra Metal allocation or memcpy. */
static int ds4_gpu_expert_group_upload_route_tiles(void) {
    const uint32_t tile_count =
        g_qwen35_expert_group_plan.route_tile_count;
    if (!g_qwen35_expert_group_key.valid || tile_count == 0u ||
        tile_count != g_qwen35_expert_group_key.route_tile_count) {
        return 0;
    }
    if (g_qwen35_expert_group_key.route_tiles_uploaded) return 1;
    if (!ds4_gpu_expert_group_ensure_route_tiles_buffer(tile_count)) return 0;
    void *dst = [g_expert_group_route_tiles_buffer contents];
    if (!dst) return 0;
    memcpy(dst,
           g_qwen35_expert_group_plan.route_tiles,
           (NSUInteger)tile_count * sizeof(ds4_expert_group_route_tile));
    g_qwen35_expert_group_key.route_tiles_uploaded = 1;
    return 1;
}

static int ds4_gpu_qwen35_expert_group_matches(
        const ds4_gpu_tensor *selected,
        uint32_t              layer,
        uint32_t              n_tokens,
        uint32_t              n_selected,
        uint32_t              n_total_expert) {
    if (!selected || !g_qwen35_expert_group_key.valid ||
        n_tokens > UINT32_MAX / n_selected) {
        return 0;
    }
    const uint64_t selected_bytes =
        (uint64_t)n_tokens * n_selected * sizeof(int32_t);
    return g_qwen35_expert_group_key.selected_buffer ==
               ds4_gpu_tensor_buffer(selected) &&
           g_qwen35_expert_group_key.selected_offset ==
               ds4_gpu_tensor_offset(selected) &&
           g_qwen35_expert_group_key.selected_bytes == selected_bytes &&
           g_qwen35_expert_group_key.layer == layer &&
           g_qwen35_expert_group_key.n_tokens == n_tokens &&
           g_qwen35_expert_group_key.n_selected == n_selected &&
           g_qwen35_expert_group_key.n_total_expert == n_total_expert &&
           g_qwen35_expert_group_key.route_count == n_tokens * n_selected &&
           g_qwen35_expert_group_key.route_tile_count ==
               g_qwen35_expert_group_plan.route_tile_count;
}

static int ds4_gpu_qwen35_expert_group_prepare_current(
        const int32_t        *ids,
        const ds4_gpu_tensor *selected,
        uint32_t              layer,
        uint32_t              n_tokens,
        uint32_t              n_selected,
        uint32_t              n_total_expert,
        int                   overlap,
        int                   request_expert_group) {
    if (!request_expert_group ||
        n_tokens < DS4_METAL_EXPERT_GROUP_MIN_TOKENS) {
        return 1;
    }

    /* A positive overlap result proves route_ready built this key from the
     * current router generation.  Without that generation, tensor identity is
     * not a content identity: macro-prefill deliberately reuses the same
     * selected buffer for consecutive chunks in one layer.  Rebuild from the
     * IDs just read instead of accepting a shape-identical stale plan. */
    const bool route_tile_ready =
        (request_expert_group & DS4_GPU_EXPERT_SCHEDULE_ROUTE_TILE) == 0 ||
        g_qwen35_expert_group_plan.route_tile_count > 0u;
    if (overlap > 0 && route_tile_ready &&
        ds4_gpu_qwen35_expert_group_matches(
            selected, layer, n_tokens, n_selected, n_total_expert)) {
        return 1;
    }
    return ds4_gpu_qwen35_expert_group_build(
        ids, selected, layer, n_tokens, n_selected, n_total_expert,
        request_expert_group);
}

static int ds4_gpu_qwen35_stream_owner_matches(
        const ds4_gpu_qwen35_stream_pending *p) {
    return p && p->state != DS4_QWEN35_STREAM_IO_EMPTY &&
           pthread_equal(p->owner, pthread_self());
}

static int ds4_gpu_qwen35_stream_wait_reads(
        ds4_gpu_qwen35_stream_pending *p,
        double                       *elapsed_ms) {
    if (elapsed_ms) *elapsed_ms = 0.0;
    if (!p || p->state == DS4_QWEN35_STREAM_IO_EMPTY) return 0;
    if (p->state == DS4_QWEN35_STREAM_IO_READY || p->n_tasks == 0) {
        return 1;
    }
    if (p->asynchronous && !ds4_gpu_stream_expert_pread_pool_wait()) {
        return 0;
    }

    const double elapsed = p->asynchronous ?
        ds4_gpu_stream_expert_pread_pool_elapsed_ms(p->start_ms) :
        ds4_gpu_now_ms() - p->start_ms;
    uint64_t read_bytes = 0;
    int ok = 1;
    for (uint32_t i = 0; i < p->n_tasks; i++) {
        if (!p->tasks[i].ok) ok = 0;
        if (read_bytes > UINT64_MAX - p->tasks[i].read_bytes) {
            read_bytes = UINT64_MAX;
        } else {
            read_bytes += p->tasks[i].read_bytes;
        }
    }
    if (!p->io_accounted) {
        ds4_gpu_stream_expert_cache_note_pread(
            p->layer,
            ok ? p->n_loads : 0,
            ds4_gpu_stream_expert_pread_successful_syscalls(
                p->tasks, p->n_tasks),
            read_bytes,
            elapsed);
        p->io_accounted = 1;
    }
    if (elapsed_ms) *elapsed_ms = elapsed;
    return ok;
}

static int ds4_gpu_qwen35_stream_finish_internal(
        ds4_gpu_qwen35_stream_pending *p) {
    if (!p || p->state == DS4_QWEN35_STREAM_IO_EMPTY) return 0;
    if (p->state == DS4_QWEN35_STREAM_IO_READY) return 1;

    const int overlap_timing =
        ds4_gpu_stream_expert_timing_summary_enabled();
    double overlap_t0 = overlap_timing ? ds4_gpu_now_ms() : 0.0;
    double elapsed_ms = 0.0;
    if (!ds4_gpu_qwen35_stream_wait_reads(p, &elapsed_ms)) return 0;
    const double overlap_finish_wait_ms =
        overlap_timing ? ds4_gpu_now_ms() - overlap_t0 : 0.0;
    if (overlap_timing) overlap_t0 = ds4_gpu_now_ms();

    /* Workers publish bytes only.  didModifyRange and every logical cache
     * transition remain on the encoder owner, so a completion can never
     * re-enter Metal or evict a resource behind an in-flight command buffer. */
    for (uint32_t load_i = 0; load_i < p->n_loads; load_i++) {
        [p->gate_bufs[load_i]
            didModifyRange:NSMakeRange(p->gate_inners[load_i],
                                       (NSUInteger)p->gate_expert_bytes)];
        [p->up_bufs[load_i]
            didModifyRange:NSMakeRange(p->up_inners[load_i],
                                       (NSUInteger)p->gate_expert_bytes)];
        [p->down_bufs[load_i]
            didModifyRange:NSMakeRange(p->down_inners[load_i],
                                       (NSUInteger)p->down_expert_bytes)];
    }
    const double overlap_finish_modify_ms =
        overlap_timing ? ds4_gpu_now_ms() - overlap_t0 : 0.0;
    if (overlap_timing) overlap_t0 = ds4_gpu_now_ms();

    for (uint32_t load_i = 0; load_i < p->n_loads; load_i++) {
        const uint32_t unique_i = p->load_unique[load_i];
        if (unique_i >= p->n_unique) return 0;
        const uint32_t expert = (uint32_t)p->unique_ids[unique_i];
        if (!ds4_gpu_stream_expert_cache_install_loaded(
                p->model_map,
                p->model_size,
                p->layer,
                expert,
                p->n_total_expert,
                p->gate_abs_offsets[unique_i],
                p->up_abs_offsets[unique_i],
                p->down_abs_offsets[unique_i],
                p->gate_expert_bytes,
                p->down_expert_bytes,
                p->gate_bufs[load_i],
                p->up_bufs[load_i],
                p->down_bufs[load_i],
                p->gate_inners[load_i],
                p->up_inners[load_i],
                p->down_inners[load_i])) {
            return 0;
        }
        p->load_installed[load_i] = 1;
        p->installed[expert] = 1;
    }
    ds4_gpu_qwen35_stream_release_staging(p);
    p->state = DS4_QWEN35_STREAM_IO_READY;
    if (overlap_timing) {
        ds4_gpu_stream_expert_timing_note_overlap_finish(
                p->publish_ms,
                overlap_finish_wait_ms,
                overlap_finish_modify_ms,
                ds4_gpu_now_ms() - overlap_t0);
    }

    if (getenv("DS4_METAL_STREAMING_EXPERT_EARLY_LOAD_PROFILE") != NULL) {
        fprintf(stderr,
                "ds4: Metal routed batch overlap ready generation=%llu "
                "layer=%u unique=%u missing=%u reads=%u async=%u wall=%.3f ms\n",
                (unsigned long long)p->generation,
                p->layer,
                p->n_unique,
                p->n_loads,
                p->max_inflight_reads,
                p->asynchronous,
                elapsed_ms);
    }
    return 1;
}

static void ds4_gpu_qwen35_stream_batch_pending_clear(void) {
    ds4_gpu_qwen35_stream_pending *p = &g_qwen35_stream_pending;
    if (p->state == DS4_QWEN35_STREAM_IO_EMPTY) {
        hebrus_gpu_qwen35_stream_reset(p);
        return;
    }
    if (p->state == DS4_QWEN35_STREAM_IO_READING) {
        (void)ds4_gpu_qwen35_stream_wait_reads(p, NULL);
    }
    hebrus_gpu_qwen35_stream_reset(p);
}

static int ds4_gpu_qwen35_stream_pending_matches(
        const ds4_gpu_stream_expert_table *table,
        const ds4_gpu_tensor              *selected,
        uint32_t                           n_tokens,
        uint32_t                           n_selected) {
    const ds4_gpu_qwen35_stream_pending *p = &g_qwen35_stream_pending;
    if (!table || !selected || p->state == DS4_QWEN35_STREAM_IO_EMPTY) {
        return 0;
    }
    const uint64_t selected_bytes =
        (uint64_t)n_tokens * n_selected * sizeof(int32_t);
    return p->model_map == table->model_map &&
           p->model_size == table->model_size &&
           p->layer == table->layer &&
           p->n_tokens == n_tokens &&
           p->n_selected == n_selected &&
           p->n_total_expert == table->n_total_expert &&
           p->gate_offset == table->gate_offset &&
           p->up_offset == table->up_offset &&
           p->down_offset == table->down_offset &&
           p->gate_expert_bytes == table->gate_expert_bytes &&
           p->down_expert_bytes == table->down_expert_bytes &&
           p->selected_buffer == ds4_gpu_tensor_buffer(selected) &&
           p->selected_offset == ds4_gpu_tensor_offset(selected) &&
           p->selected_bytes == selected_bytes;
}

static int ds4_gpu_qwen35_stream_consume(
        const ds4_gpu_stream_expert_table *table,
        const ds4_gpu_tensor              *selected,
        uint32_t                           n_tokens,
        uint32_t                           n_selected,
        uint8_t                           *installed,
        uint32_t                           installed_count,
        int32_t                           *inline_ids,
        uint64_t                           inline_capacity,
        int32_t                          **selected_ids) {
    ds4_gpu_qwen35_stream_pending *p = &g_qwen35_stream_pending;
    if (selected_ids) *selected_ids = NULL;
    if (p->state == DS4_QWEN35_STREAM_IO_EMPTY) return 0;
    if (!ds4_gpu_qwen35_stream_pending_matches(table,
                                               selected,
                                               n_tokens,
                                               n_selected) ||
        !ds4_gpu_qwen35_stream_owner_matches(p)) {
        return -1;
    }
    /* routed_moe_batch is the natural fallback completion point.  If the C
     * scheduler did not request finish explicitly, publish its already encoded
     * shared expert here before blocking on I/O. */
    if (p->state == DS4_QWEN35_STREAM_IO_READING &&
        p->asynchronous &&
        g_batch_cb) {
        const int overlap_timing =
            ds4_gpu_stream_expert_timing_summary_enabled();
        const double publish_t0 =
            overlap_timing ? ds4_gpu_now_ms() : 0.0;
        if (!ds4_gpu_flush_commands()) return -1;
        if (overlap_timing) {
            p->publish_ms += ds4_gpu_now_ms() - publish_t0;
        }
    } else if (p->state == DS4_QWEN35_STREAM_IO_READING &&
               p->asynchronous) {
        return -1;
    }
    if (!ds4_gpu_qwen35_stream_finish_internal(p)) return -1;
    if (installed) {
        const uint32_t n = installed_count <
            DS4_METAL_QWEN35_STREAM_MAX_EXPERT ? installed_count :
            DS4_METAL_QWEN35_STREAM_MAX_EXPERT;
        memcpy(installed, p->installed, n * sizeof(installed[0]));
    }
    if (hebrus_gpu_stream_expert_qwen35_model()) {
        const uint64_t expected_id_count =
            (uint64_t)n_tokens * n_selected;
        if (!hebrus_gpu_qwen35_stream_take_selected_ids(
                p,
                expected_id_count,
                inline_ids,
                inline_capacity,
                selected_ids)) {
            hebrus_gpu_qwen35_stream_reset(p);
            return -1;
        }
    }
    hebrus_gpu_qwen35_stream_reset(p);
    return 1;
}

/* The cache budget is the frozen memory envelope.  Limit a single pread wave
 * to at most 1/32 of its expert slots (and six experts) so queue depth cannot
 * grow with core count or with a 64-token route containing hundreds of IDs. */
static uint32_t ds4_gpu_qwen35_stream_inflight_limit(
        uint32_t cache_budget,
        uint32_t n_tasks) {
    uint32_t experts = cache_budget / 32u;
    if (experts == 0) experts = 1;
    if (experts > 6u) experts = 6u;
    uint32_t reads = experts * 3u;
    if (reads > DS4_METAL_QWEN35_STREAM_MAX_INFLIGHT_READS) {
        reads = DS4_METAL_QWEN35_STREAM_MAX_INFLIGHT_READS;
    }
    const uint32_t configured = ds4_gpu_stream_expert_pread_thread_limit();
    if (reads > configured) reads = configured;
    if (reads > n_tasks) reads = n_tasks;
    return reads;
}

static uint32_t ds4_gpu_stream_overlap_early_load_limit(
        uint32_t n_selected,
        uint32_t gate_type,
        uint32_t down_type) {
    if (n_selected != 6u ||
        gate_type != DS4_METAL_TENSOR_IQ2_XXS ||
        down_type != DS4_METAL_TENSOR_Q2_K) {
        return UINT32_MAX;
    }
    const char *env =
        getenv("DS4_METAL_DEEPSEEK_PREFILL_IO_OVERLAP_MAX_EXPERTS");
    if (!env || !env[0]) return UINT32_MAX;
    char *end = NULL;
    unsigned long value = strtoul(env, &end, 10);
    if (end == env || *end != '\0' || value == 0ul) {
        return UINT32_MAX;
    }
    return value > 256ul ? 256u : (uint32_t)value;
}

static uint32_t ds4_gpu_stream_overlap_thread_limit(
        uint32_t current,
        uint32_t n_selected,
        uint32_t gate_type,
        uint32_t down_type) {
    if (current <= 1u || n_selected != 6u ||
        gate_type != DS4_METAL_TENSOR_IQ2_XXS ||
        down_type != DS4_METAL_TENSOR_Q2_K) {
        return current;
    }
    const char *env =
        getenv("DS4_METAL_DEEPSEEK_PREFILL_IO_OVERLAP_THREADS");
    if (!env || !env[0]) return current;
    char *end = NULL;
    unsigned long value = strtoul(env, &end, 10);
    if (end == env || *end != '\0' || value < 2ul) return current;
    const uint32_t requested =
        value > UINT32_MAX ? UINT32_MAX : (uint32_t)value;
    return requested < current ? requested : current;
}

int ds4_gpu_stream_io_overlap_capable(
        uint32_t n_tokens,
        uint32_t n_total_expert,
        uint32_t n_selected,
        uint32_t gate_type,
        uint32_t down_type) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
#if TARGET_OS_OSX
    if (@available(macOS 12.0, *)) {
        /* Shared events are created lazily by route_ready(). */
    } else {
        return 0;
    }
#else
    return 0;
#endif
    const int iq2_top6 =
        n_total_expert == 256u &&
        n_selected == 6u &&
        gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
        down_type == DS4_METAL_TENSOR_Q2_K &&
        g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_pipeline != nil &&
        g_moe_mul_mv_addr_q2_k_sum6_pipeline != nil;
    const bool mlx_affine_store =
        g_qwen35_expert_pack.active &&
        g_qwen35_expert_pack.storage_format ==
            DS4_EXPERT_STORE_STORAGE_MLX_AFFINE4 &&
        g_qwen35_expert_pack.group_size == 64u;
    const int qwen_affine_top8 =
        n_total_expert == DS4_METAL_QWEN35_STREAM_MAX_EXPERT &&
        n_selected == DS4_METAL_STREAM_SELECTED_MAX &&
        gate_type == DS4_METAL_TENSOR_Q4_K &&
        down_type == DS4_METAL_TENSOR_Q4_K &&
        mlx_affine_store &&
        ds4_gpu_get_moe_mv_pipeline(
            "kernel_mul_mv_addr_mlx_affine4_64_pair_swiglu_f32", 2) != nil &&
        ds4_gpu_get_moe_mv_pipeline(
            "kernel_mul_mv_addr_mlx_affine4_64_sum8_f32", 2) != nil;
    const int qwen_iq_top8 =
        n_total_expert == DS4_METAL_QWEN35_STREAM_MAX_EXPERT &&
        n_selected == DS4_METAL_STREAM_SELECTED_MAX &&
        ((gate_type == DS4_METAL_TENSOR_IQ2_XS &&
          (down_type == DS4_METAL_TENSOR_IQ3_XXS ||
           down_type == DS4_METAL_TENSOR_IQ4_XS)) ||
         (gate_type == DS4_METAL_TENSOR_IQ3_XXS &&
          down_type == DS4_METAL_TENSOR_IQ4_XS));
    /* Qwen also consumes the same pending ticket in its one-token selected
     * cache path. The batch capability probe starts at two rows, exactly as
     * the previous Qwen-only implementation did. DeepSeek overlap is prefill
     * only and therefore never widens a one-token path. */
    const uint32_t capability_tokens =
        (qwen_affine_top8 || qwen_iq_top8) && n_tokens == 1u ?
            2u : n_tokens;
    return (iq2_top6 || qwen_affine_top8 || qwen_iq_top8) &&
           g_model_fd >= 0 &&
           ds4_gpu_stream_expert_pread_pool_enabled() &&
           ds4_gpu_stream_expert_pread_thread_limit() > 1u &&
           getenv("DS4_MOE_RECORD_SELECTED_IDS") == NULL &&
           getenv("DS4_MOE_REPLAY_SELECTED_IDS") == NULL &&
           getenv("DS4_MOE_RECORD_SELECTED_HOTLIST") == NULL &&
           ds4_gpu_stream_prefill_batch_selected_addr_enabled(
               capability_tokens, n_total_expert, n_selected,
               gate_type, down_type) &&
           ds4_gpu_stream_expert_cache_required_floor_satisfied();
}

int ds4_gpu_stream_selected_addr_capable(
        uint32_t n_tokens,
        uint32_t n_total_expert,
        uint32_t n_selected,
        uint32_t gate_type,
        uint32_t down_type) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    const int iq2_top6 =
        n_total_expert <= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT &&
        n_selected == 6u &&
        gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
        down_type == DS4_METAL_TENSOR_Q2_K &&
        g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_pipeline != nil &&
        g_moe_mul_mv_addr_q2_k_sum6_pipeline != nil;
    const bool mlx_affine_store =
        g_qwen35_expert_pack.active &&
        g_qwen35_expert_pack.storage_format ==
            DS4_EXPERT_STORE_STORAGE_MLX_AFFINE4 &&
        g_qwen35_expert_pack.group_size == 64u;
    const int qwen_affine_top8 =
        n_total_expert == DS4_METAL_QWEN35_STREAM_MAX_EXPERT &&
        n_selected == DS4_METAL_STREAM_SELECTED_MAX &&
        gate_type == DS4_METAL_TENSOR_Q4_K &&
        down_type == DS4_METAL_TENSOR_Q4_K &&
        mlx_affine_store &&
        ds4_gpu_get_moe_mv_pipeline(
            "kernel_mul_mv_addr_mlx_affine4_64_pair_swiglu_f32", 2) != nil &&
        ds4_gpu_get_moe_mv_pipeline(
            "kernel_mul_mv_addr_mlx_affine4_64_sum8_f32", 2) != nil;
    const int qwen_iq_top8 =
        n_total_expert == DS4_METAL_QWEN35_STREAM_MAX_EXPERT &&
        n_selected == DS4_METAL_STREAM_SELECTED_MAX &&
        ((gate_type == DS4_METAL_TENSOR_IQ2_XS &&
          (down_type == DS4_METAL_TENSOR_IQ3_XXS ||
           down_type == DS4_METAL_TENSOR_IQ4_XS)) ||
         (gate_type == DS4_METAL_TENSOR_IQ3_XXS &&
          down_type == DS4_METAL_TENSOR_IQ4_XS));
    return n_tokens > 1u &&
           (iq2_top6 || qwen_affine_top8 || qwen_iq_top8) &&
           ds4_gpu_stream_prefill_batch_selected_addr_enabled(
               n_tokens, n_total_expert, n_selected,
               gate_type, down_type);
}

int ds4_gpu_qwen35_stream_io_overlap_capable(
        uint32_t gate_type,
        uint32_t down_type) {
    return ds4_gpu_stream_io_overlap_capable(
        2u,
        DS4_METAL_QWEN35_STREAM_MAX_EXPERT,
        DS4_METAL_STREAM_SELECTED_MAX,
        gate_type,
        down_type);
}

int ds4_gpu_stream_batch_route_ready_select(
        const ds4_gpu_stream_expert_table *table,
        const ds4_gpu_tensor              *selected,
        uint32_t                           n_tokens,
        uint32_t                           n_selected,
        uint32_t                           gate_type,
        uint32_t                           down_type,
        int                                request_expert_group,
        ds4_gpu_stream_io_ticket          *ticket) {
    if (!ticket) return 0;
    memset(ticket, 0, sizeof(*ticket));
    ds4_gpu_qwen35_expert_group_invalidate();
    if (!ds4_gpu_stream_io_overlap_capable(
            n_tokens, table ? table->n_total_expert : 0u, n_selected,
            gate_type, down_type)) {
        fprintf(stderr,
                "ds4: Metal routed overlap is inapplicable "
                "(tokens=%u total=%u selected=%u gate_type=%u "
                "down_type=%u)\n",
                n_tokens,
                table ? table->n_total_expert : 0u,
                n_selected,
                gate_type,
                down_type);
        return 1;
    }
    if (!table || !selected || !table->model_map ||
        table->model_size == 0 ||
        table->layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        table->n_total_expert != DS4_METAL_QWEN35_STREAM_MAX_EXPERT ||
        (n_selected != 6u &&
         n_selected != DS4_METAL_STREAM_SELECTED_MAX) ||
        n_tokens == 0 ||
        n_tokens > UINT32_MAX / n_selected ||
        table->gate_expert_bytes == 0 ||
        table->down_expert_bytes == 0 ||
        (uint64_t)table->n_total_expert >
            UINT64_MAX / table->gate_expert_bytes ||
        (uint64_t)table->n_total_expert >
            UINT64_MAX / table->down_expert_bytes ||
        g_qwen35_stream_pending.state != DS4_QWEN35_STREAM_IO_EMPTY ||
        g_stream_expert_pending_load.active ||
        !g_batch_cb) {
        fprintf(stderr,
                "ds4: Metal routed overlap rejected invalid runtime state "
                "(tokens=%u layer=%u pending=%u load_active=%d cb=%d)\n",
                n_tokens,
                table ? table->layer : UINT32_MAX,
                (unsigned)g_qwen35_stream_pending.state,
                g_stream_expert_pending_load.active,
                g_batch_cb != nil);
        return 0;
    }

    const uint64_t gate_tensor_bytes =
        (uint64_t)table->n_total_expert * table->gate_expert_bytes;
    const uint64_t down_tensor_bytes =
        (uint64_t)table->n_total_expert * table->down_expert_bytes;
    const uint64_t n_ids = (uint64_t)n_tokens * n_selected;
    const uint64_t selected_bytes = n_ids * sizeof(int32_t);
    if (table->gate_offset > table->model_size ||
        table->up_offset > table->model_size ||
        table->down_offset > table->model_size ||
        gate_tensor_bytes > table->model_size - table->gate_offset ||
        gate_tensor_bytes > table->model_size - table->up_offset ||
        down_tensor_bytes > table->model_size - table->down_offset ||
        selected_bytes > ds4_gpu_tensor_bytes(selected) ||
        n_ids > SIZE_MAX / sizeof(int32_t)) {
        fprintf(stderr,
                "ds4: Metal routed overlap rejected invalid tensor bounds "
                "(tokens=%u ids=%" PRIu64 " selected=%" PRIu64
                "/%" PRIu64 ")\n",
                n_tokens,
                n_ids,
                selected_bytes,
                ds4_gpu_tensor_bytes(selected));
        return 0;
    }

    /* Signal after the router, commit command buffer A and wait only for that
     * event. commit_and_wait opens buffer B immediately; the completed route
     * is now immutable while bounded workers fill staging and the caller
     * encodes the shared expert. */
    const int overlap_timing =
        ds4_gpu_stream_expert_timing_summary_enabled();
    double overlap_route_wait_ms = 0.0;
    double overlap_route_copy_ms = 0.0;
    double overlap_route_plan_ms = 0.0;
    double overlap_t0 = overlap_timing ? ds4_gpu_now_ms() : 0.0;
    uint64_t selected_event = 0;
    if (!ds4_gpu_signal_selected_readback_ready(&selected_event) ||
        !ds4_gpu_commit_and_wait_selected_readback(
            selected_event,
            "routed router-ready overlap")) {
        fprintf(stderr,
                "ds4: Metal routed overlap could not publish router IDs\n");
        return 0;
    }
    if (overlap_timing) {
        overlap_route_wait_ms = ds4_gpu_now_ms() - overlap_t0;
        overlap_t0 = ds4_gpu_now_ms();
    }

    const int retain_selected_ids =
        hebrus_gpu_stream_expert_qwen35_model();
    ds4_gpu_qwen35_stream_pending *p = &g_qwen35_stream_pending;
    hebrus_gpu_qwen35_stream_reset(p);
    int32_t *ids = NULL;
    if (retain_selected_ids) {
        p->selected_id_count = n_ids;
        const uint64_t inline_id_capacity =
            sizeof(p->selected_ids_inline) /
            sizeof(p->selected_ids_inline[0]);
        if (p->selected_id_count <= inline_id_capacity) {
            p->selected_ids = p->selected_ids_inline;
        } else {
            p->selected_ids = malloc(
                (size_t)p->selected_id_count *
                sizeof(p->selected_ids[0]));
            p->selected_ids_heap = p->selected_ids != NULL;
        }
        ids = p->selected_ids;
    } else {
        ids = malloc((size_t)n_ids * sizeof(ids[0]));
    }
    int ok = 0;
    const char *failure = "unknown";
    if (!ids ||
        !ds4_gpu_tensor_read(selected, 0, ids, selected_bytes)) {
        failure = "router ID readback";
        goto done;
    }
    if (overlap_timing) {
        overlap_route_copy_ms = ds4_gpu_now_ms() - overlap_t0;
        overlap_t0 = ds4_gpu_now_ms();
    }

    /* The route is already synchronized for SSD pread planning.  Build the
     * grouping permutation here instead of creating a second command-buffer
     * boundary/readback later in routed MoE. */
    if (request_expert_group &&
        n_tokens >= DS4_METAL_EXPERT_GROUP_MIN_TOKENS &&
        !ds4_gpu_qwen35_expert_group_build(
            ids, selected, table->layer, n_tokens, n_selected,
            table->n_total_expert, request_expert_group)) {
        failure = "expert grouping";
        goto done;
    }

    p->generation = ds4_gpu_qwen35_stream_next_generation();
    p->owner = pthread_self();
    p->model_map = table->model_map;
    p->model_size = table->model_size;
    p->layer = table->layer;
    p->n_tokens = n_tokens;
    p->n_selected = n_selected;
    p->n_total_expert = table->n_total_expert;
    p->gate_offset = table->gate_offset;
    p->up_offset = table->up_offset;
    p->down_offset = table->down_offset;
    p->gate_expert_bytes = table->gate_expert_bytes;
    p->down_expert_bytes = table->down_expert_bytes;
    p->selected_buffer = ds4_gpu_tensor_buffer(selected);
    p->selected_offset = ds4_gpu_tensor_offset(selected);
    p->selected_bytes = selected_bytes;

    bool seen[DS4_METAL_QWEN35_STREAM_MAX_EXPERT] = { false };
    for (uint64_t i = 0; i < n_ids; i++) {
        const int32_t expert = ids[i];
        if (expert < 0 ||
            expert >= (int32_t)DS4_METAL_QWEN35_STREAM_MAX_EXPERT) {
            fprintf(stderr,
                    "ds4: Metal routed overlap expert id %d is outside 0..%u\n",
                    expert,
                    table->n_total_expert - 1u);
            goto done;
        }
        if (!seen[(uint32_t)expert]) {
            seen[(uint32_t)expert] = true;
            p->unique_ids[p->n_unique++] = expert;
        }
    }
    if (p->n_unique == 0 ||
        p->n_unique > ds4_gpu_stream_expert_cache_configured_budget()) {
        failure = "unique-expert budget";
        goto done;
    }

    for (uint32_t unique_i = 0; unique_i < p->n_unique; unique_i++) {
        const uint64_t expert = (uint64_t)(uint32_t)p->unique_ids[unique_i];
        const uint64_t gate_rel = expert * p->gate_expert_bytes;
        const uint64_t down_rel = expert * p->down_expert_bytes;
        p->gate_abs_offsets[unique_i] = p->gate_offset + gate_rel;
        p->up_abs_offsets[unique_i] = p->up_offset + gate_rel;
        p->down_abs_offsets[unique_i] = p->down_offset + down_rel;
    }

    const uint32_t cache_budget =
        ds4_gpu_stream_expert_cache_configured_budget();
    const uint32_t early_load_limit =
        ds4_gpu_stream_overlap_early_load_limit(
            n_selected, gate_type, down_type);
    uint32_t reserved_entries = g_stream_expert_cache_entry_count;
    for (uint32_t unique_i = 0; unique_i < p->n_unique; unique_i++) {
        const uint32_t expert = (uint32_t)p->unique_ids[unique_i];
        ds4_gpu_stream_expert_cache_entry *entry =
            &g_stream_expert_cache[p->layer][expert];
        if (ds4_gpu_stream_expert_cache_entry_matches(
                entry,
                p->model_map,
                p->model_size,
                p->gate_abs_offsets[unique_i],
                p->up_abs_offsets[unique_i],
                p->down_abs_offsets[unique_i],
                p->gate_expert_bytes,
                p->down_expert_bytes)) {
            continue;
        }
        /* DeepSeek may deliberately start only a bounded first wave here.
         * The consumer binds these completed slabs, then lets the established
         * eight-expert loader fetch the remainder while the already-committed
         * shared expert continues on the GPU. This preserves SSD queue shape
         * instead of forcing hundreds of records through one long pool job. */
        if (p->n_loads >= early_load_limit) break;

        const uint32_t load_i = p->n_loads;
        const int force_reuse =
            cache_budget != 0 && reserved_entries >= cache_budget;
        if (!ds4_gpu_stream_expert_cache_prepare_load_buffers(
                p->layer,
                expert,
                p->layer,
                p->unique_ids,
                p->n_unique,
                p->gate_expert_bytes,
                p->down_expert_bytes,
                force_reuse,
                &p->gate_bufs[load_i],
                &p->up_bufs[load_i],
                &p->down_bufs[load_i],
                &p->gate_inners[load_i],
                &p->up_inners[load_i],
                &p->down_inners[load_i])) {
            failure = "staging buffer allocation";
            goto done;
        }
        uint32_t staging_slot = 0;
        if (p->gate_bufs[load_i] == p->up_bufs[load_i] &&
            p->gate_bufs[load_i] == p->down_bufs[load_i] &&
            ds4_gpu_stream_expert_slab_slot_for_buffer(
                p->gate_bufs[load_i], p->gate_inners[load_i],
                &staging_slot)) {
            /* Until install_loaded() succeeds, the pending ticket—not a cache
             * entry—owns this slot.  Persist that transfer so abort and every
             * fail-closed fallback can return it to the slab free list. */
            p->staging_slab_slot[load_i] = staging_slot;
            p->staging_slab_owned[load_i] = 1;
        }
        if (!force_reuse && reserved_entries < UINT32_MAX) reserved_entries++;
        p->load_unique[load_i] = unique_i;
        p->n_loads++;

        uint8_t *gate_dst =
            (uint8_t *)[p->gate_bufs[load_i] contents] +
            p->gate_inners[load_i];
        uint8_t *up_dst =
            (uint8_t *)[p->up_bufs[load_i] contents] +
            p->up_inners[load_i];
        uint8_t *down_dst =
            (uint8_t *)[p->down_bufs[load_i] contents] +
            p->down_inners[load_i];
        if (!gate_dst || !up_dst || !down_dst) {
            failure = "staging buffer mapping";
            goto done;
        }
        if (!ds4_gpu_stream_expert_append_record_tasks(
                p->tasks, DS4_METAL_QWEN35_STREAM_MAX_TASKS, &p->n_tasks,
                p->gate_abs_offsets[unique_i],
                p->up_abs_offsets[unique_i],
                p->down_abs_offsets[unique_i],
                p->gate_expert_bytes, p->down_expert_bytes,
                gate_dst, up_dst, down_dst,
                ds4_gpu_stream_expert_record_read_plan())) {
            failure = "pread task planning";
            goto done;
        }
    }

    p->state = p->n_tasks == 0 ? DS4_QWEN35_STREAM_IO_READY :
                                 DS4_QWEN35_STREAM_IO_READING;
    p->max_inflight_reads = ds4_gpu_qwen35_stream_inflight_limit(
        cache_budget, p->n_tasks);
    p->max_inflight_reads = ds4_gpu_stream_overlap_thread_limit(
        p->max_inflight_reads, n_selected, gate_type, down_type);
    p->start_ms = ds4_gpu_now_ms();
    if (p->n_tasks != 0 && p->max_inflight_reads > 1u &&
        ds4_gpu_stream_expert_pread_pool_begin(p->tasks,
                                               p->n_tasks,
                                               p->max_inflight_reads)) {
        p->asynchronous = 1;
    } else if (p->n_tasks != 0) {
        /* A pool setup failure is an exact synchronous fallback, not a worker
         * allowed to install cache state.  The ticket records that the first
         * full-stack campaign did not obtain real overlap. */
        ds4_gpu_stream_expert_pread_worker_args worker = {
            .tasks = p->tasks,
            .n_tasks = p->n_tasks,
            .worker_index = 0,
            .n_workers = 1,
        };
        p->max_inflight_reads = 1;
        (void)ds4_gpu_stream_expert_pread_worker(&worker);
    }

    ticket->generation = p->generation;
    ticket->unique_experts = p->n_unique;
    ticket->missing_experts = p->n_loads;
    ticket->max_inflight_reads = p->max_inflight_reads;
    ticket->asynchronous = p->asynchronous;
    if (overlap_timing) {
        overlap_route_plan_ms = ds4_gpu_now_ms() - overlap_t0;
        ds4_gpu_stream_expert_timing_note_overlap_route(
                overlap_route_wait_ms,
                overlap_route_copy_ms,
                overlap_route_plan_ms);
    }
    ok = 1;

done:
    if (!retain_selected_ids) free(ids);
    if (!ok) {
        fprintf(stderr,
                "ds4: Metal routed overlap preparation failed at %s "
                "(tokens=%u layer=%u unique=%u loads=%u tasks=%u "
                "budget=%u)\n",
                failure,
                n_tokens,
                table ? table->layer : UINT32_MAX,
                p->n_unique,
                p->n_loads,
                p->n_tasks,
                ds4_gpu_stream_expert_cache_configured_budget());
        ds4_gpu_qwen35_stream_batch_pending_clear();
        memset(ticket, 0, sizeof(*ticket));
    }
    return ok;
}

int ds4_gpu_qwen35_stream_batch_route_ready(
        const ds4_gpu_stream_expert_table *table,
        const ds4_gpu_tensor              *selected,
        uint32_t                           n_tokens,
        uint32_t                           n_selected,
        uint32_t                           gate_type,
        uint32_t                           down_type,
        ds4_gpu_qwen35_stream_io_ticket   *ticket) {
    return ds4_gpu_stream_batch_route_ready_select(
        table, selected, n_tokens, n_selected,
        gate_type, down_type,
        0, ticket);
}

int ds4_gpu_qwen35_stream_batch_route_ready_select(
        const ds4_gpu_stream_expert_table *table,
        const ds4_gpu_tensor              *selected,
        uint32_t                           n_tokens,
        uint32_t                           n_selected,
        uint32_t                           gate_type,
        uint32_t                           down_type,
        int                                request_expert_group,
        ds4_gpu_qwen35_stream_io_ticket   *ticket) {
    return ds4_gpu_stream_batch_route_ready_select(
        table, selected, n_tokens, n_selected,
        gate_type, down_type,
        request_expert_group, ticket);
}

int ds4_gpu_stream_batch_finish(uint64_t generation) {
    ds4_gpu_qwen35_stream_pending *p = &g_qwen35_stream_pending;
    if (generation == 0) return 1;
    if (p->state == DS4_QWEN35_STREAM_IO_EMPTY ||
        p->generation != generation ||
        !ds4_gpu_qwen35_stream_owner_matches(p)) {
        return 0;
    }
    /* Publishing the shared command buffer is what turns CPU pread into real
     * GPU/I/O overlap. The queue preserves shared-before-routed ordering, while
     * the newly opened buffer remains owned by the same encoder thread. */
    if (p->state == DS4_QWEN35_STREAM_IO_READING &&
        p->asynchronous) {
        const int overlap_timing =
            ds4_gpu_stream_expert_timing_summary_enabled();
        const double publish_t0 =
            overlap_timing ? ds4_gpu_now_ms() : 0.0;
        if (!g_batch_cb || !ds4_gpu_flush_commands()) {
            (void)ds4_gpu_qwen35_stream_wait_reads(p, NULL);
            hebrus_gpu_qwen35_stream_reset(p);
            return 0;
        }
        if (overlap_timing) {
            p->publish_ms += ds4_gpu_now_ms() - publish_t0;
        }
    }
    if (ds4_gpu_qwen35_stream_finish_internal(p)) return 1;
    hebrus_gpu_qwen35_stream_reset(p);
    return 0;
}

int ds4_gpu_stream_batch_abort(uint64_t generation) {
    ds4_gpu_qwen35_stream_pending *p = &g_qwen35_stream_pending;
    if (generation == 0) return 1;
    if (p->state == DS4_QWEN35_STREAM_IO_EMPTY ||
        p->generation != generation ||
        !ds4_gpu_qwen35_stream_owner_matches(p)) {
        return 0;
    }
    int ok = 1;
    if (p->state == DS4_QWEN35_STREAM_IO_READING) {
        ok = ds4_gpu_qwen35_stream_wait_reads(p, NULL);
    }
    hebrus_gpu_qwen35_stream_reset(p);
    return ok;
}

int ds4_gpu_qwen35_stream_batch_finish(uint64_t generation) {
    return ds4_gpu_stream_batch_finish(generation);
}

int ds4_gpu_qwen35_stream_batch_abort(uint64_t generation) {
    return ds4_gpu_stream_batch_abort(generation);
}

static void ds4_gpu_stream_expert_cache_clear_layer(uint32_t layer) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return;
    for (uint32_t expert = 0;
         expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
         expert++) {
        ds4_gpu_stream_expert_cache_clear_entry(layer, expert, 0);
    }
    g_stream_expert_cache_layer_count[layer] = 0;
    g_stream_expert_cache_layer_expert_limit[layer] = 0;
    memset(g_stream_expert_cache_layer_occupancy[layer],
           0,
           sizeof(g_stream_expert_cache_layer_occupancy[layer]));
}

static int ds4_gpu_stream_expert_cache_prepare_selected_batch(
        const void    *model_map,
        uint64_t       model_size,
        uint32_t       layer,
        const ds4_gpu_tensor *selected,
        uint32_t       n_tokens,
        uint32_t       n_total_expert,
        uint32_t       n_selected,
        uint64_t       gate_offset,
        uint64_t       up_offset,
        uint64_t       down_offset,
        uint64_t       gate_expert_bytes,
        uint64_t       down_expert_bytes,
        id<MTLBuffer> *gate_addrs,
        id<MTLBuffer> *up_addrs,
        id<MTLBuffer> *down_addrs,
        ds4_gpu_stream_expert_cache_entry **resources,
        uint32_t      *n_resources,
        uint32_t      *unique_out,
        int            request_expert_group) {
    if (!g_ssd_streaming_mode ||
        !model_map ||
        !selected ||
        !gate_addrs ||
        !up_addrs ||
        !down_addrs ||
        !resources ||
        !n_resources ||
        !unique_out ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_tokens == 0 ||
        n_selected == 0 ||
        n_selected > 8 ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        gate_expert_bytes == 0 ||
        down_expert_bytes == 0) {
        return 0;
    }
    if (n_tokens > UINT32_MAX / n_selected) return 0;

    const uint64_t n_ids = (uint64_t)n_tokens * n_selected;
    if (n_ids > SIZE_MAX / sizeof(int32_t)) return 0;
    uint8_t prefetched[DS4_METAL_QWEN35_STREAM_MAX_EXPERT] = { 0 };
    const ds4_gpu_stream_expert_table table = {
        .model_map = model_map,
        .model_size = model_size,
        .layer = layer,
        .n_total_expert = n_total_expert,
        .gate_offset = gate_offset,
        .up_offset = up_offset,
        .down_offset = down_offset,
        .gate_expert_bytes = gate_expert_bytes,
        .down_expert_bytes = down_expert_bytes,
    };
    const int reuse_selected_ids =
        hebrus_gpu_stream_expert_qwen35_model();
    int32_t inline_ids[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    int32_t *ids = NULL;
    const int overlap = ds4_gpu_qwen35_stream_consume(
        &table,
        selected,
        n_tokens,
        n_selected,
        prefetched,
        DS4_METAL_QWEN35_STREAM_MAX_EXPERT,
        inline_ids,
        sizeof(inline_ids) / sizeof(inline_ids[0]),
        &ids);
    if (overlap < 0) return 0;

    const bool profile =
        getenv("DS4_METAL_STREAMING_PREFILL_BATCH_SELECTED_ADDR_PROFILE") != NULL;
    const double t0 = profile ? ds4_gpu_now_ms() : 0.0;
    int ok = 1;
    if (overlap == 0 || !reuse_selected_ids) {
        ids = malloc((size_t)n_ids * sizeof(ids[0]));
        ok = ids &&
             ds4_gpu_tensor_read(selected,
                                 0,
                                 ids,
                                 n_ids * sizeof(ids[0]));
    } else if (!ids) {
        ok = 0;
    }
    const double t_read = profile ? ds4_gpu_now_ms() : 0.0;

    bool seen[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT] = { false };
    uint32_t frequency[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT] = { 0 };
    int32_t unique_ids[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    uint32_t unique_count = 0;
    *n_resources = 0;
    *unique_out = 0;
    if (ok) {
        if (!ds4_gpu_stream_expert_cache_ensure_addr_buffers(layer)) {
            ok = 0;
        }
    }
    if (ok) {
        for (uint64_t i = 0; i < n_ids; i++) {
            const int32_t selected_id = ids[i];
            if (selected_id < 0 || (uint32_t)selected_id >= n_total_expert) {
                fprintf(stderr,
                        "ds4: Metal streaming batch selected expert id %d is outside 0..%u at layer %u\n",
                        selected_id,
                        n_total_expert,
                        layer);
                ok = 0;
                break;
            }
            frequency[(uint32_t)selected_id]++;
            if (!seen[(uint32_t)selected_id]) {
                seen[(uint32_t)selected_id] = true;
                unique_ids[unique_count++] = selected_id;
            }
        }
    }
    if (ok) {
        ds4_gpu_stream_expert_cache_note_frequency_hotness(layer,
                                                           frequency,
                                                           n_total_expert);
    }
    if (ok) {
        const uint32_t cache_budget =
            ds4_gpu_stream_expert_cache_configured_budget();
        if (cache_budget != 0 && unique_count > cache_budget) {
            fprintf(stderr,
                    "ds4: Metal streaming prefill batch selected addr layer=%u "
                    "needs %u unique experts but cache budget is %u\n",
                    layer,
                    unique_count,
                    cache_budget);
            ok = 0;
        }
    }
    if (ok) {
        /* Keep the existing top-8 parallel pread path: deduplication lowers
         * bytes, while groups of eight preserve the SSD queue depth used by
         * scalar Qwen. Loading every unique expert synchronously made the
         * layer-major path I/O-latency bound despite doing much less work. */
        for (uint32_t base = 0; base < unique_count; base += 8u) {
            const uint32_t batch =
                unique_count - base > 8u ? 8u : unique_count - base;
            int32_t batch_ids[DS4_METAL_STREAM_SELECTED_MAX] = {
                -1, -1, -1, -1, -1, -1, -1, -1
            };
            uint64_t gate_abs_offsets[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
            uint64_t up_abs_offsets[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
            uint64_t down_abs_offsets[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
            ds4_gpu_stream_expert_cache_entry
                *batch_entries[DS4_METAL_STREAM_SELECTED_MAX] = { NULL };
            uint32_t missing_mask = 0;

            for (uint32_t i = 0; i < batch; i++) {
                const uint32_t expert = (uint32_t)unique_ids[base + i];
                if ((uint64_t)expert > UINT64_MAX / gate_expert_bytes ||
                    (uint64_t)expert > UINT64_MAX / down_expert_bytes) {
                    fprintf(stderr,
                            "ds4: Metal streaming batch selected expert offset overflow\n");
                    ok = 0;
                    break;
                }
                const uint64_t gate_rel =
                    (uint64_t)expert * gate_expert_bytes;
                const uint64_t down_rel =
                    (uint64_t)expert * down_expert_bytes;
                if (gate_rel > UINT64_MAX - gate_offset ||
                    gate_rel > UINT64_MAX - up_offset ||
                    down_rel > UINT64_MAX - down_offset) {
                    fprintf(stderr,
                            "ds4: Metal streaming batch selected expert offset overflow\n");
                    ok = 0;
                    break;
                }
                batch_ids[i] = (int32_t)expert;
                gate_abs_offsets[i] = gate_offset + gate_rel;
                up_abs_offsets[i] = up_offset + gate_rel;
                down_abs_offsets[i] = down_offset + down_rel;
                if (expert < DS4_METAL_QWEN35_STREAM_MAX_EXPERT &&
                    prefetched[expert]) {
                    /* Installation already counted the first use as a miss.
                     * Bind it directly so overlap does not manufacture an
                     * extra hit compared with synchronous preparation. */
                    batch_entries[i] =
                        &g_stream_expert_cache[layer][expert];
                    if (!ds4_gpu_stream_expert_cache_entry_matches(
                            batch_entries[i],
                            model_map,
                            model_size,
                            gate_abs_offsets[i],
                            up_abs_offsets[i],
                            down_abs_offsets[i],
                            gate_expert_bytes,
                            down_expert_bytes)) {
                        batch_entries[i] = NULL;
                    }
                } else {
                    batch_entries[i] = ds4_gpu_stream_expert_cache_peek(
                        model_map,
                        model_size,
                        layer,
                        expert,
                        n_total_expert,
                        n_selected,
                        gate_abs_offsets[i],
                        up_abs_offsets[i],
                        down_abs_offsets[i],
                        gate_expert_bytes,
                        down_expert_bytes);
                }
                if (!batch_entries[i]) missing_mask |= 1u << i;
            }
            if (!ok) break;
            if (missing_mask != 0 &&
                !ds4_gpu_stream_expert_cache_load_selected_missing(
                    model_map,
                    model_size,
                    layer,
                    batch_ids,
                    n_total_expert,
                    batch,
                    unique_ids,
                    unique_count,
                    gate_abs_offsets,
                    up_abs_offsets,
                    down_abs_offsets,
                    gate_expert_bytes,
                    down_expert_bytes,
                    missing_mask,
                    batch_entries)) {
                ok = 0;
                break;
            }

            for (uint32_t i = 0; i < batch; i++) {
                const uint32_t expert = (uint32_t)batch_ids[i];
                ds4_gpu_stream_expert_cache_entry *entry = batch_entries[i];
                if (!entry) {
                    fprintf(stderr,
                            "ds4: Metal streaming prefill batch selected addr "
                            "failed to load layer=%u expert=%u unique=%u "
                            "budget=%u\n",
                            layer,
                            expert,
                            unique_count,
                            ds4_gpu_stream_expert_cache_configured_budget());
                    ok = 0;
                    break;
                }
                const uint32_t extra_uses =
                    frequency[expert] > 0 ? frequency[expert] - 1u : 0;
                if (extra_uses != 0) {
                    if (entry->use_count > UINT64_MAX - extra_uses) {
                        entry->use_count = UINT64_MAX;
                    } else {
                        entry->use_count += extra_uses;
                    }
                    ds4_gpu_stream_expert_counter_add(
                        &g_stream_expert_cache_hits, extra_uses);
                    if (g_stream_expert_cache_layer_hits[layer] >
                        UINT64_MAX - extra_uses) {
                        g_stream_expert_cache_layer_hits[layer] = UINT64_MAX;
                    } else {
                        g_stream_expert_cache_layer_hits[layer] += extra_uses;
                    }
                }
                resources[*n_resources] = entry;
                (*n_resources)++;
            }
            if (!ok) break;
        }
    }
    if (ok && !ds4_gpu_qwen35_expert_group_prepare_current(
            ids,
            selected,
            layer,
            n_tokens,
            n_selected,
            n_total_expert,
            overlap,
            request_expert_group)) {
        ok = 0;
    }
    if (ids != inline_ids) free(ids);

    if (!ok || *n_resources == 0) {
        ds4_gpu_stream_expert_cache_clear_layer(layer);
        return 0;
    }
    if (!ds4_gpu_stream_expert_cache_addr_buffers(layer,
                                                  gate_addrs,
                                                  up_addrs,
                                                  down_addrs)) {
        ds4_gpu_stream_expert_cache_clear_layer(layer);
        return 0;
    }
    *unique_out = *n_resources;
    if (profile) {
        const double t_done = ds4_gpu_now_ms();
        uint64_t per_expert_bytes = UINT64_MAX;
        uint64_t logical_bytes = UINT64_MAX;
        if (gate_expert_bytes <= (UINT64_MAX - down_expert_bytes) / 2ull) {
            per_expert_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
            if (per_expert_bytes == 0 ||
                *n_resources <= UINT64_MAX / per_expert_bytes) {
                logical_bytes = (uint64_t)(*n_resources) * per_expert_bytes;
            }
        }
        fprintf(stderr,
                "ds4: Metal streaming prefill batch selected addr layer=%u "
                "tokens=%u unique=%u read=%.3f ms wrap=%.3f ms bytes=%.2f GiB\n",
                layer,
                n_tokens,
                *n_resources,
                t_read - t0,
                t_done - t_read,
                ds4_gpu_gib(logical_bytes));
    }
    return 1;
}

int ds4_gpu_stream_expert_cache_seed_selected(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *selected_ids,
        uint32_t                           n_selected) {
    if (!g_ssd_streaming_mode) return 1;
    if (!table) return 0;
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;
    if (!model_map || !selected_ids ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_selected == 0 ||
        n_selected > 6 ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes) ||
        ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                  n_total_expert,
                                                  n_selected) == 0) {
        return 1;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;

    ds4_gpu_stream_expert_cache_note_selected_hotness(layer,
                                                      selected_ids,
                                                      n_selected);
    for (uint32_t i = 0; i < n_selected; i++) {
        if (selected_ids[i] < 0 || (uint32_t)selected_ids[i] >= n_total_expert) {
            fprintf(stderr,
                    "ds4: Metal prefill expert-cache seed selected expert id %d is outside 0..%u\n",
                    selected_ids[i],
                    n_total_expert);
            return 0;
        }
        const uint64_t expert_id = (uint64_t)(uint32_t)selected_ids[i];
        if (expert_id > UINT64_MAX / gate_expert_bytes ||
            expert_id > UINT64_MAX / down_expert_bytes) {
            fprintf(stderr, "ds4: Metal prefill expert-cache seed offset overflow\n");
            return 0;
        }
        const uint64_t gate_rel = expert_id * gate_expert_bytes;
        const uint64_t down_rel = expert_id * down_expert_bytes;
        if (gate_rel > UINT64_MAX - gate_offset ||
            gate_rel > UINT64_MAX - up_offset ||
            down_rel > UINT64_MAX - down_offset) {
            fprintf(stderr, "ds4: Metal prefill expert-cache seed offset overflow\n");
            return 0;
        }

        if (!ds4_gpu_stream_expert_cache_get(model_map,
                                             model_size,
                                             layer,
                                             (uint32_t)selected_ids[i],
                                             n_total_expert,
                                             n_selected,
                                             gate_offset + gate_rel,
                                             up_offset + gate_rel,
                                             down_offset + down_rel,
                                             gate_expert_bytes,
                                             down_expert_bytes)) {
            return 0;
        }
    }
    ds4_gpu_stream_expert_cache_prune_layer(layer,
                                            n_total_expert,
                                            n_selected,
                                            selected_ids,
                                            n_selected);
    ds4_gpu_stream_expert_cache_prune_global(layer,
                                             selected_ids,
                                             n_selected);
    return 1;
}

int ds4_gpu_stream_expert_cache_seed_experts(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *expert_ids,
        const uint32_t                    *expert_priorities,
        uint32_t                           n_experts) {
    if (!g_ssd_streaming_mode) return 1;
    if (!table) return 0;
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;
    if (!model_map || !expert_ids ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_experts == 0 ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes) ||
        ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                  n_total_expert,
                                                  1) == 0) {
        return 1;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;

    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
    uint32_t remaining = n_experts;
    while (remaining != 0) {
        const uint32_t batch =
            remaining > 6u ? 6u : remaining;
        remaining -= batch;

        int32_t selected_ids[6] = { -1, -1, -1, -1, -1, -1 };
        uint64_t gate_abs_offsets[6] = { 0, 0, 0, 0, 0, 0 };
        uint64_t up_abs_offsets[6] = { 0, 0, 0, 0, 0, 0 };
        uint64_t down_abs_offsets[6] = { 0, 0, 0, 0, 0, 0 };
        ds4_gpu_stream_expert_cache_entry *entries[6] = {
            NULL, NULL, NULL, NULL, NULL, NULL
        };
        uint32_t missing_mask = 0;

        for (uint32_t i = 0; i < batch; i++) {
            const int32_t expert = expert_ids[remaining + i];
            const uint32_t priority =
                expert_priorities ? expert_priorities[remaining + i] : 0;
            if (expert < 0 || (uint32_t)expert >= n_total_expert) {
                fprintf(stderr,
                        "ds4: Metal streaming hotlist seed expert id %d is outside 0..%u\n",
                        expert,
                        n_total_expert);
                return 0;
            }
            const uint64_t expert_id = (uint64_t)(uint32_t)expert;
            if (expert_id > UINT64_MAX / gate_expert_bytes ||
                expert_id > UINT64_MAX / down_expert_bytes) {
                fprintf(stderr, "ds4: Metal streaming hotlist seed offset overflow\n");
                return 0;
            }
            const uint64_t gate_rel = expert_id * gate_expert_bytes;
            const uint64_t down_rel = expert_id * down_expert_bytes;
            if (gate_rel > UINT64_MAX - gate_offset ||
                gate_rel > UINT64_MAX - up_offset ||
                down_rel > UINT64_MAX - down_offset) {
                fprintf(stderr, "ds4: Metal streaming hotlist seed offset overflow\n");
                return 0;
            }

            ds4_gpu_stream_expert_cache_note_route_hotness(
                    layer,
                    (uint32_t)expert,
                    priority != 0 ? priority : 1u);
            selected_ids[i] = expert;
            gate_abs_offsets[i] = gate_offset + gate_rel;
            up_abs_offsets[i] = up_offset + gate_rel;
            down_abs_offsets[i] = down_offset + down_rel;
            entries[i] = ds4_gpu_stream_expert_cache_peek(model_map,
                                                          model_size,
                                                          layer,
                                                          (uint32_t)expert,
                                                          n_total_expert,
                                                          batch,
                                                          gate_abs_offsets[i],
                                                          up_abs_offsets[i],
                                                          down_abs_offsets[i],
                                                          gate_expert_bytes,
                                                          down_expert_bytes);
            if (!entries[i]) missing_mask |= 1u << i;
            if (entries[i] && priority != 0 &&
                entries[i]->use_count < (uint64_t)priority) {
                entries[i]->use_count = (uint64_t)priority;
            }
        }

        if (missing_mask != 0 &&
            !ds4_gpu_stream_expert_cache_load_selected_missing(model_map,
                                                               model_size,
                                                               layer,
                                                               selected_ids,
                                                               n_total_expert,
                                                               batch,
                                                               selected_ids,
                                                               batch,
                                                               gate_abs_offsets,
                                                               up_abs_offsets,
                                                               down_abs_offsets,
                                                               gate_expert_bytes,
                                                               down_expert_bytes,
                                                               missing_mask,
                                                               entries)) {
            return 0;
        }
        if (expert_priorities) {
            for (uint32_t i = 0; i < batch; i++) {
                const uint32_t priority = expert_priorities[remaining + i];
                if (entries[i] && priority != 0 &&
                    entries[i]->use_count < (uint64_t)priority) {
                    entries[i]->use_count = (uint64_t)priority;
                }
            }
        }
    }

    const uint32_t protect_n = n_experts < 6u ? n_experts : 6u;
    ds4_gpu_stream_expert_cache_prune_layer(layer,
                                            n_total_expert,
                                            1,
                                            expert_ids,
                                            protect_n);
    ds4_gpu_stream_expert_cache_prune_global(layer,
                                             expert_ids,
                                             protect_n);
    return 1;
}

static uint32_t ds4_gpu_q4_expert_table_group_size(uint32_t n_total_expert) {
    const char *env = getenv("DS4_METAL_Q4_EXPERT_TABLE_GROUP_SIZE");
    if (!env || !env[0]) return 1;
    char *end = NULL;
    unsigned long v = strtoul(env, &end, 10);
    if (end == env || *end != '\0' || v < 2 || v > n_total_expert) {
        return 1;
    }
    return (uint32_t)v;
}

static bool ds4_gpu_q4_table_queue_residency_requested(void) {
    return getenv("DS4_METAL_Q4_TABLE_QUEUE_RESIDENCY_SET") != NULL;
}

static bool ds4_gpu_q4_table_queue_residency_available(void) {
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        return g_queue && [g_queue respondsToSelector:@selector(addResidencySet:)];
    }
#endif
    return false;
}

static bool ds4_gpu_q4_non_streaming_opt_in_enabled(void) {
    return getenv("DS4_METAL_ENABLE_Q4_SELECTED_EXPERT_VIEWS") != NULL ||
           getenv("DS4_METAL_ENABLE_PRO_Q4_SELECTED_EXPERT_VIEWS") != NULL ||
           getenv("DS4_METAL_ENABLE_Q4_EXPERT_TABLE") != NULL ||
           getenv("DS4_METAL_ENABLE_Q4_EXPERT_ADDRESS_TABLE") != NULL ||
           getenv("DS4_METAL_ENABLE_PRO_Q4_EXPERT_TABLE_AUTO") != NULL ||
           getenv("DS4_METAL_ENABLE_PRO_Q4_EXPERT_ADDRESS_AUTO") != NULL;
}

static bool ds4_gpu_q4_selected_paths_allowed(void) {
    if (g_ssd_streaming_mode) return true;
    if (g_glm_model_mode) return false;
    return ds4_gpu_q4_non_streaming_opt_in_enabled();
}

int ds4_gpu_pro_q4_expert_table_auto_available(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    return (g_ssd_streaming_mode ||
            getenv("DS4_METAL_ENABLE_PRO_Q4_EXPERT_TABLE_AUTO") != NULL) &&
           getenv("DS4_METAL_DISABLE_PRO_Q4_EXPERT_TABLE_AUTO") == NULL &&
           getenv("DS4_METAL_DISABLE_Q4_EXPERT_TABLE") == NULL &&
           ds4_gpu_q4_table_queue_residency_available();
}

static bool ds4_gpu_q4_table_queue_residency_enabled(bool auto_queue_residency) {
    return (auto_queue_residency || ds4_gpu_q4_table_queue_residency_requested()) &&
           ds4_gpu_q4_table_queue_residency_available();
}

static bool ds4_gpu_q4_table_model_residency_enabled(void) {
    return getenv("DS4_METAL_Q4_TABLE_MODEL_RESIDENCY_SET") != NULL;
}

static bool ds4_gpu_pro_q4_expert_indirect_shape_supported(
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint64_t gate_tensor_bytes,
        uint64_t down_tensor_bytes) {
    const uint64_t q4_selected_min_tensor_bytes = 2ull * 1024ull * 1024ull * 1024ull;
    return n_total_expert == 384 &&
           n_expert == 6 &&
           gate_tensor_bytes >= q4_selected_min_tensor_bytes &&
           down_tensor_bytes >= q4_selected_min_tensor_bytes;
}

static bool ds4_gpu_pro_q4_expert_table_auto_enabled(
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint64_t gate_tensor_bytes,
        uint64_t down_tensor_bytes) {
    /*
     * This path lets the shader choose among exact per-expert resources.
     * It is only automatic when a Metal queue residency set can make every
     * indirect expert resource visible up front; otherwise the selected
     * exact-slice path remains the fallback.
     */
    return ds4_gpu_pro_q4_expert_indirect_shape_supported(n_total_expert,
                                                          n_expert,
                                                          gate_tensor_bytes,
                                                          down_tensor_bytes) &&
           ds4_gpu_pro_q4_expert_table_auto_available();
}

static bool ds4_gpu_pro_q4_expert_address_auto_enabled(
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint64_t gate_tensor_bytes,
        uint64_t down_tensor_bytes) {
    /*
     * GPU-address expert tables are useful for experiments, but they are not
     * safe as an automatic path unless every indirect expert resource is made
     * visible to Metal. Keep this behind an explicit opt-in while the selected
     * active-slice path remains the correctness/performance baseline.
     */
    return getenv("DS4_METAL_ENABLE_PRO_Q4_EXPERT_ADDRESS_AUTO") != NULL &&
           ds4_gpu_q4_selected_paths_allowed() &&
           ds4_gpu_pro_q4_expert_indirect_shape_supported(n_total_expert,
                                                          n_expert,
                                                          gate_tensor_bytes,
                                                          down_tensor_bytes) &&
           g_moe_mul_mv_addr_q4_k_pair_swiglu_pipeline != nil &&
           g_moe_mul_mv_addr_q4_k_sum6_pipeline != nil &&
           getenv("DS4_METAL_DISABLE_PRO_Q4_EXPERT_TABLE_AUTO") == NULL &&
           getenv("DS4_METAL_DISABLE_PRO_Q4_EXPERT_ADDRESS_AUTO") == NULL &&
           getenv("DS4_METAL_DISABLE_Q4_EXPERT_ADDRESS_TABLE") == NULL &&
           ds4_gpu_q4_table_queue_residency_available();
}

static bool ds4_gpu_q4_table_bind_anchors_enabled(void) {
    return getenv("DS4_METAL_Q4_TABLE_BIND_ANCHORS") != NULL;
}

static int ds4_gpu_use_model_residency_set(id<MTLCommandBuffer> cb) {
    if (!ds4_gpu_q4_table_model_residency_enabled()) return 1;
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        if (cb && g_model_residency_set && [cb respondsToSelector:@selector(useResidencySet:)]) {
            [cb useResidencySet:g_model_residency_set];
            return 1;
        }
    }
#endif
    fprintf(stderr, "ds4: Metal Q4 table model residency set is not available\n");
    return 0;
}

static int ds4_gpu_bind_q4_expert_table_anchors(
        id<MTLComputeCommandEncoder> enc,
        DS4MetalQ4ExpertTable       *table,
        NSUInteger                   first_index,
        NSUInteger                   max_count) {
    if (!ds4_gpu_q4_table_bind_anchors_enabled()) return 1;
    if (!enc || !table || !table.expertBuffers) return 0;

    const NSUInteger count = [table.expertBuffers count];
    if (count > max_count) {
        fprintf(stderr,
                "ds4: Metal Q4 table anchor count %lu exceeds available slots %lu\n",
                (unsigned long)count,
                (unsigned long)max_count);
        return 0;
    }
    for (NSUInteger i = 0; i < count; i++) {
        [enc setBuffer:[table.expertBuffers objectAtIndex:i]
                offset:0
               atIndex:first_index + i];
    }
    return 1;
}

static id ds4_gpu_q4_expert_table_residency_set(NSMutableArray<id<MTLBuffer>> *buffers) {
    if (!buffers || [buffers count] == 0 ||
        getenv("DS4_METAL_Q4_TABLE_RESIDENCY_SET") == NULL ||
        getenv("DS4_METAL_Q4_TABLE_PER_TENSOR_RESIDENCY_SET") == NULL) {
        return nil;
    }
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        MTLResidencySetDescriptor *desc = [[MTLResidencySetDescriptor alloc] init];
        desc.label = @"ds4_q4_expert_table";
        desc.initialCapacity = [buffers count];
        NSError *error = nil;
        id residency_set = [g_device newResidencySetWithDescriptor:desc error:&error];
        if (!residency_set) {
            fprintf(stderr, "ds4: Metal Q4 expert table residency set creation failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            return nil;
        }
        for (id<MTLBuffer> buffer in buffers) {
            [residency_set addAllocation:buffer];
        }
        [residency_set commit];
        [residency_set requestResidency];
        return residency_set;
    }
#endif
    return nil;
}

static void ds4_gpu_q4_residency_add_table(id residency_set,
                                           DS4MetalQ4ExpertTable *table) {
#if TARGET_OS_OSX
    if (!residency_set || !table) return;
    if (@available(macOS 15.0, *)) {
        if (table.argumentBuffer) {
            [residency_set addAllocation:table.argumentBuffer];
        }
        if (table.addressBuffer) {
            [residency_set addAllocation:table.addressBuffer];
        }
        for (id<MTLBuffer> buffer in table.expertBuffers) {
            [residency_set addAllocation:buffer];
        }
    }
#else
    (void)residency_set;
    (void)table;
#endif
}

static id ds4_gpu_q4_expert_layer_residency_set(DS4MetalQ4ExpertTable *gate_table,
                                                DS4MetalQ4ExpertTable *up_table,
                                                DS4MetalQ4ExpertTable *down_table,
                                                bool auto_queue_residency) {
    const bool queue_residency =
        ds4_gpu_q4_table_queue_residency_enabled(auto_queue_residency);
    if (!gate_table || !up_table || !down_table ||
        !g_device || !g_q4_expert_layer_residency_cache ||
        (getenv("DS4_METAL_Q4_TABLE_RESIDENCY_SET") == NULL &&
         !queue_residency)) {
        return nil;
    }
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        NSString *key = [NSString stringWithFormat:@"%p:%p:%p",
                         gate_table, up_table, down_table];
        DS4MetalQ4LayerResidency *cached =
            [g_q4_expert_layer_residency_cache objectForKey:key];
        if (cached) return cached.residencySet;

        const NSUInteger capacity =
            [gate_table.expertBuffers count] +
            [up_table.expertBuffers count] +
            [down_table.expertBuffers count] + 3u;
        MTLResidencySetDescriptor *desc = [[MTLResidencySetDescriptor alloc] init];
        desc.label = @"ds4_q4_expert_layer";
        desc.initialCapacity = capacity;
        NSError *error = nil;
        id residency_set = [g_device newResidencySetWithDescriptor:desc error:&error];
        if (!residency_set) {
            fprintf(stderr,
                    "ds4: Metal Q4 expert layer residency set creation failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            return nil;
        }

        ds4_gpu_q4_residency_add_table(residency_set, gate_table);
        ds4_gpu_q4_residency_add_table(residency_set, up_table);
        ds4_gpu_q4_residency_add_table(residency_set, down_table);
        [residency_set commit];
        [residency_set requestResidency];

        DS4MetalQ4LayerResidency *entry = [DS4MetalQ4LayerResidency new];
        entry.residencySet = residency_set;
        if (queue_residency) {
            [g_queue addResidencySet:residency_set];
            entry.addedToQueue = YES;
        }
        [g_q4_expert_layer_residency_cache setObject:entry forKey:key];
        return residency_set;
    }
#endif
    return nil;
}

static DS4MetalQ4ExpertTable *ds4_gpu_q4_expert_table(
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                tensor_offset,
        uint64_t                expert_bytes,
        uint32_t                n_total_expert,
        id<MTLArgumentEncoder>  encoder);

static DS4MetalQ4ExpertTable *ds4_gpu_q4_expert_address_table(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    tensor_offset,
        uint64_t    expert_bytes,
        uint32_t    n_total_expert);

int ds4_gpu_preload_q4_expert_tables(const void *model_map, uint64_t model_size,
                                     uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
                                     uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
                                     uint32_t n_total_expert) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!model_map || model_size == 0 || gate_expert_bytes == 0 ||
        down_expert_bytes == 0 || n_total_expert == 0) {
        return 0;
    }
    if ((uint64_t)n_total_expert > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)n_total_expert > UINT64_MAX / down_expert_bytes) {
        fprintf(stderr, "ds4: Metal Q4 expert table preload byte size overflow\n");
        return 0;
    }

    const uint64_t gate_tensor_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_tensor_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    const bool address_auto =
        ds4_gpu_pro_q4_expert_address_auto_enabled(n_total_expert,
                                                   6,
                                                   gate_tensor_bytes,
                                                   down_tensor_bytes);
    const bool table_auto =
        ds4_gpu_pro_q4_expert_table_auto_enabled(n_total_expert,
                                                 6,
                                                 gate_tensor_bytes,
                                                 down_tensor_bytes);
    if (!address_auto && !table_auto) {
        return 1;
    }

    if (address_auto) {
        @autoreleasepool {
            DS4MetalQ4ExpertTable *gate_table =
                ds4_gpu_q4_expert_address_table(model_map,
                                                model_size,
                                                gate_offset,
                                                gate_expert_bytes,
                                                n_total_expert);
            DS4MetalQ4ExpertTable *up_table =
                ds4_gpu_q4_expert_address_table(model_map,
                                                model_size,
                                                up_offset,
                                                gate_expert_bytes,
                                                n_total_expert);
            DS4MetalQ4ExpertTable *down_table =
                ds4_gpu_q4_expert_address_table(model_map,
                                                model_size,
                                                down_offset,
                                                down_expert_bytes,
                                                n_total_expert);
            if (!gate_table || !up_table || !down_table) {
                return 0;
            }
            id residency = ds4_gpu_q4_expert_layer_residency_set(gate_table,
                                                                 up_table,
                                                                 down_table,
                                                                 true);
            if (!residency) {
                fprintf(stderr, "ds4: Metal Q4 expert address table preload failed to create queue residency set\n");
                return 0;
            }
        }
        return 1;
    }

    if (!g_moe_table_q4_pair_gate_encoder || !g_moe_table_q4_pair_up_encoder ||
        !g_moe_table_q4_sum_down_encoder) {
        fprintf(stderr, "ds4: Metal Q4 expert table preload missing argument encoders\n");
        return 0;
    }

    @autoreleasepool {
        DS4MetalQ4ExpertTable *gate_table =
            ds4_gpu_q4_expert_table(model_map,
                                    model_size,
                                    gate_offset,
                                    gate_expert_bytes,
                                    n_total_expert,
                                    g_moe_table_q4_pair_gate_encoder);
        DS4MetalQ4ExpertTable *up_table =
            ds4_gpu_q4_expert_table(model_map,
                                    model_size,
                                    up_offset,
                                    gate_expert_bytes,
                                    n_total_expert,
                                    g_moe_table_q4_pair_up_encoder);
        DS4MetalQ4ExpertTable *down_table =
            ds4_gpu_q4_expert_table(model_map,
                                    model_size,
                                    down_offset,
                                    down_expert_bytes,
                                    n_total_expert,
                                    g_moe_table_q4_sum_down_encoder);
        if (!gate_table || !up_table || !down_table) {
            return 0;
        }
        id residency = ds4_gpu_q4_expert_layer_residency_set(gate_table,
                                                             up_table,
                                                             down_table,
                                                             true);
        if (!residency) {
            fprintf(stderr, "ds4: Metal Q4 expert table preload failed to create queue residency set\n");
            return 0;
        }
    }
    return 1;
}

static DS4MetalQ4ExpertTable *ds4_gpu_q4_expert_table(
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                tensor_offset,
        uint64_t                expert_bytes,
        uint32_t                n_total_expert,
        id<MTLArgumentEncoder>  encoder) {
    if (!model_map || !g_device || !g_q4_expert_table_cache || !encoder ||
        model_size == 0 || expert_bytes == 0 ||
        n_total_expert == 0 || n_total_expert > 384) {
        return nil;
    }
    if ((uint64_t)n_total_expert > UINT64_MAX / expert_bytes) {
        fprintf(stderr, "ds4: Metal Q4 expert table byte size overflow\n");
        return nil;
    }
    const uint64_t tensor_bytes = (uint64_t)n_total_expert * expert_bytes;
    if (tensor_offset > model_size || tensor_bytes > model_size - tensor_offset) {
        fprintf(stderr, "ds4: Metal Q4 expert table is outside the mapped model\n");
        return nil;
    }

    const uint32_t table_group_size =
        ds4_gpu_q4_expert_table_group_size(n_total_expert);
    NSString *key = [NSString stringWithFormat:@"%p:%llu:%llu:%llu:%u:%llu:%u",
                     model_map,
                     (unsigned long long)model_size,
                     (unsigned long long)tensor_offset,
                     (unsigned long long)expert_bytes,
                     n_total_expert,
                     (unsigned long long)[encoder encodedLength],
                     table_group_size];
    DS4MetalQ4ExpertTable *cached = [g_q4_expert_table_cache objectForKey:key];
    if (cached) return cached;

    id<MTLBuffer> arg_buffer =
        [g_device newBufferWithLength:[encoder encodedLength]
                               options:MTLResourceStorageModeShared];
    if (!arg_buffer) {
        fprintf(stderr, "ds4: Metal Q4 expert table argument buffer allocation failed\n");
        return nil;
    }
    arg_buffer.label = @"ds4_q4_expert_table";
    [encoder setArgumentBuffer:arg_buffer offset:0];

    NSMutableArray<id<MTLBuffer>> *expert_buffers =
        [NSMutableArray arrayWithCapacity:table_group_size > 1 ?
            (n_total_expert + table_group_size - 1u) / table_group_size :
            n_total_expert];
    if (!expert_buffers) return nil;

    if (table_group_size > 1) {
        for (uint32_t first = 0; first < n_total_expert; first += table_group_size) {
            const uint32_t remaining = n_total_expert - first;
            const uint32_t group_n =
                remaining < table_group_size ? remaining : table_group_size;
            if ((uint64_t)first > UINT64_MAX / expert_bytes ||
                (uint64_t)group_n > UINT64_MAX / expert_bytes) {
                fprintf(stderr, "ds4: Metal Q4 expert table group byte overflow\n");
                return nil;
            }
            const uint64_t rel = (uint64_t)first * expert_bytes;
            const uint64_t group_bytes = (uint64_t)group_n * expert_bytes;
            if (rel > UINT64_MAX - tensor_offset) {
                fprintf(stderr, "ds4: Metal Q4 expert table group offset overflow\n");
                return nil;
            }
            uint64_t inner = 0;
            id<MTLBuffer> group_buf =
                ds4_gpu_wrap_model_range(model_map,
                                         model_size,
                                         tensor_offset + rel,
                                         group_bytes,
                                         &inner);
            if (!group_buf) return nil;
            for (uint32_t j = 0; j < group_n; j++) {
                const uint64_t expert_inner = inner + (uint64_t)j * expert_bytes;
                [encoder setBuffer:group_buf offset:(NSUInteger)expert_inner atIndex:first + j];
            }
            [expert_buffers addObject:group_buf];
        }
    } else {
        for (uint32_t i = 0; i < n_total_expert; i++) {
            const uint64_t rel = (uint64_t)i * expert_bytes;
            if (rel > UINT64_MAX - tensor_offset) {
                fprintf(stderr, "ds4: Metal Q4 expert table offset overflow\n");
                return nil;
            }
            uint64_t inner = 0;
            id<MTLBuffer> expert_buf =
                ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                     model_size,
                                                     tensor_offset + rel,
                                                     expert_bytes,
                                                     &inner);
            if (!expert_buf) return nil;
            [encoder setBuffer:expert_buf offset:(NSUInteger)inner atIndex:i];
            [expert_buffers addObject:expert_buf];
        }
    }
    [arg_buffer didModifyRange:NSMakeRange(0, [encoder encodedLength])];

    if (getenv("DS4_METAL_Q4_EXPERT_TABLE_PROFILE") != NULL) {
        fprintf(stderr,
                "ds4: Metal Q4 expert table: experts=%u group=%u buffers=%lu expert_bytes=%.2f MiB\n",
                n_total_expert,
                table_group_size,
                (unsigned long)[expert_buffers count],
                ds4_gpu_mib(expert_bytes));
    }

    DS4MetalQ4ExpertTable *table = [DS4MetalQ4ExpertTable new];
    table.argumentBuffer = arg_buffer;
    table.expertBuffers = expert_buffers;
    table.residencySet = ds4_gpu_q4_expert_table_residency_set(expert_buffers);
    table.nExpert = n_total_expert;
    table.expertBytes = expert_bytes;
    [g_q4_expert_table_cache setObject:table forKey:key];
    return table;
}

static DS4MetalQ4ExpertTable *ds4_gpu_q4_expert_address_table(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    tensor_offset,
        uint64_t    expert_bytes,
        uint32_t    n_total_expert) {
    if (!model_map || !g_device || !g_q4_expert_table_cache ||
        model_size == 0 || expert_bytes == 0 ||
        n_total_expert == 0 || n_total_expert > 384) {
        return nil;
    }
    if ((uint64_t)n_total_expert > UINT64_MAX / expert_bytes) {
        fprintf(stderr, "ds4: Metal Q4 expert address table byte size overflow\n");
        return nil;
    }
    const uint64_t tensor_bytes = (uint64_t)n_total_expert * expert_bytes;
    if (tensor_offset > model_size || tensor_bytes > model_size - tensor_offset) {
        fprintf(stderr, "ds4: Metal Q4 expert address table is outside the mapped model\n");
        return nil;
    }

    const uint32_t table_group_size =
        ds4_gpu_q4_expert_table_group_size(n_total_expert);
    NSString *key = [NSString stringWithFormat:@"addr:%p:%llu:%llu:%llu:%u:%u",
                     model_map,
                     (unsigned long long)model_size,
                     (unsigned long long)tensor_offset,
                     (unsigned long long)expert_bytes,
                     n_total_expert,
                     table_group_size];
    DS4MetalQ4ExpertTable *cached = [g_q4_expert_table_cache objectForKey:key];
    if (cached) return cached;

    id<MTLBuffer> address_buffer =
        [g_device newBufferWithLength:(NSUInteger)n_total_expert * sizeof(uint64_t)
                               options:MTLResourceStorageModeShared];
    if (!address_buffer) {
        fprintf(stderr, "ds4: Metal Q4 expert address table allocation failed\n");
        return nil;
    }
    address_buffer.label = @"ds4_q4_expert_address_table";
    uint64_t *addresses = (uint64_t *)[address_buffer contents];
    if (!addresses) return nil;

    NSMutableArray<id<MTLBuffer>> *expert_buffers =
        [NSMutableArray arrayWithCapacity:table_group_size > 1 ?
            (n_total_expert + table_group_size - 1u) / table_group_size :
            n_total_expert];
    if (!expert_buffers) return nil;

#if TARGET_OS_OSX
    if (@available(macOS 13.0, *)) {
        for (uint32_t first = 0; first < n_total_expert; first += table_group_size) {
            const uint32_t remaining = n_total_expert - first;
            const uint32_t group_n =
                remaining < table_group_size ? remaining : table_group_size;
            if ((uint64_t)first > UINT64_MAX / expert_bytes ||
                (uint64_t)group_n > UINT64_MAX / expert_bytes) {
                fprintf(stderr, "ds4: Metal Q4 expert address table group byte overflow\n");
                return nil;
            }
            const uint64_t rel = (uint64_t)first * expert_bytes;
            const uint64_t group_bytes = (uint64_t)group_n * expert_bytes;
            if (rel > UINT64_MAX - tensor_offset) {
                fprintf(stderr, "ds4: Metal Q4 expert address table group offset overflow\n");
                return nil;
            }
            uint64_t inner = 0;
            id<MTLBuffer> group_buf = nil;
            if (table_group_size > 1) {
                group_buf = ds4_gpu_wrap_model_range(model_map,
                                                     model_size,
                                                     tensor_offset + rel,
                                                     group_bytes,
                                                     &inner);
            } else {
                group_buf = ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                                 model_size,
                                                                 tensor_offset + rel,
                                                                 expert_bytes,
                                                                 &inner);
            }
            if (!group_buf) return nil;
            const uint64_t base_address = (uint64_t)[group_buf gpuAddress] + inner;
            for (uint32_t j = 0; j < group_n; j++) {
                addresses[first + j] = base_address + (uint64_t)j * expert_bytes;
            }
            [expert_buffers addObject:group_buf];
        }
    } else
#endif
    {
        fprintf(stderr, "ds4: Metal GPU addresses require macOS 13 or newer\n");
        return nil;
    }

    [address_buffer didModifyRange:NSMakeRange(0,
        (NSUInteger)n_total_expert * sizeof(uint64_t))];

    if (getenv("DS4_METAL_Q4_EXPERT_TABLE_PROFILE") != NULL) {
        fprintf(stderr,
                "ds4: Metal Q4 expert address table: experts=%u group=%u buffers=%lu expert_bytes=%.2f MiB\n",
                n_total_expert,
                table_group_size,
                (unsigned long)[expert_buffers count],
                ds4_gpu_mib(expert_bytes));
    }

    DS4MetalQ4ExpertTable *table = [DS4MetalQ4ExpertTable new];
    table.addressBuffer = address_buffer;
    table.expertBuffers = expert_buffers;
    table.nExpert = n_total_expert;
    table.expertBytes = expert_bytes;
    [g_q4_expert_table_cache setObject:table forKey:key];
    return table;
}

static void ds4_gpu_use_q4_expert_table_resources(
        id<MTLCommandBuffer>        cb,
        id<MTLComputeCommandEncoder> enc,
        DS4MetalQ4ExpertTable       *table,
        bool                         queue_residency) {
    if (!enc || !table) return;
    if (table.argumentBuffer) {
        [enc useResource:table.argumentBuffer usage:MTLResourceUsageRead];
    }
    if (table.addressBuffer) {
        [enc useResource:table.addressBuffer usage:MTLResourceUsageRead];
    }
    if (!queue_residency &&
        getenv("DS4_METAL_Q4_TABLE_RESIDENCY_SET") != NULL &&
        table.residencySet &&
        cb &&
        [cb respondsToSelector:@selector(useResidencySet:)]) {
        [cb useResidencySet:table.residencySet];
    }
    if (getenv("DS4_METAL_Q4_TABLE_USE_RESOURCES") == NULL &&
        getenv("DS4_METAL_Q4_ADDR_USE_RESOURCES") == NULL) {
        return;
    }
    const NSUInteger count = [table.expertBuffers count];
    for (NSUInteger base = 0; base < count; base += 64u) {
        const NSUInteger n = count - base < 64u ? count - base : 64u;
        __unsafe_unretained id<MTLResource> resources[64];
        for (NSUInteger i = 0; i < n; i++) {
            resources[i] = [table.expertBuffers objectAtIndex:base + i];
        }
        [enc useResources:resources count:n usage:MTLResourceUsageRead];
    }
}

int ds4_gpu_indexer_score_one_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *index_comp,
        uint32_t                n_comp,
        uint32_t                n_head,
        uint32_t                head_dim,
        float                   scale) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!scores || !q || !weights || !index_comp ||
        n_comp == 0 || n_head == 0 || head_dim == 0) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t q_bytes = (uint64_t)n_head * head_dim * sizeof(float);
        const uint64_t weight_bytes = (uint64_t)n_head * sizeof(float);
        const uint64_t comp_bytes = (uint64_t)n_comp * head_dim * sizeof(float);
        const uint64_t score_bytes = (uint64_t)n_comp * sizeof(float);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> wbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> compbuf = ds4_gpu_tensor_buffer(index_comp);
        id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores);
        if (!qbuf || !wbuf || !compbuf || !scorebuf ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(weights) < weight_bytes ||
            ds4_gpu_tensor_bytes(index_comp) < comp_bytes ||
            ds4_gpu_tensor_bytes(scores) < score_bytes) {
            fprintf(stderr, "ds4: Metal graph indexer score received undersized buffers\n");
            return 0;
        }

        if (n_head == 64 && head_dim == 128) {
            id<MTLComputePipelineState> direct_pipeline =
                ds4_gpu_hot_pipeline(g_dsv4_indexer_score_one_direct_pipeline,
                                        "kernel_dsv4_indexer_score_one_direct");
            if (!direct_pipeline) return 0;

            ds4_gpu_dsv4_indexer_scores_fused_args args = {
                .n_comp = n_comp,
                .n_tokens = 1,
                .n_head = n_head,
                .head_dim = head_dim,
                .pos0 = 0,
                .ratio = 4,
                .q_token_stride = (uint64_t)n_head * head_dim * sizeof(float),
                .q_head_stride = (uint64_t)head_dim * sizeof(float),
                .weights_token_stride = (uint64_t)n_head * sizeof(float),
                .index_row_stride = (uint64_t)head_dim * sizeof(float),
                .score_token_stride = (uint64_t)n_comp * sizeof(float),
                .scale = scale,
            };

            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:direct_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
            [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(index_comp) atIndex:3];
            [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
            [enc setThreadgroupMemoryLength:(128u + 4u) * sizeof(float) atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake(n_comp, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer direct score")) return 0;
            return 1;
        }

        const uint64_t head_score_bytes = (uint64_t)n_comp * n_head * sizeof(float);
        if (!ds4_gpu_ensure_scratch_buffer(&g_indexer_head_scores_buffer,
                                             &g_indexer_head_scores_bytes,
                                             (NSUInteger)head_score_bytes,
                                             "ds4_indexer_head_scores")) {
            return 0;
        }

        ds4_gpu_q8_0_matvec_args dot_args =
            ds4_gpu_make_f32_mv_args(head_dim, n_comp, n_head);
        ds4_gpu_mv_dispatch dot_dispatch =
            ds4_gpu_make_plain_mv_dispatch(head_dim, 1);
        dot_args.nr0 = dot_dispatch.nr0;
        id<MTLComputePipelineState> dot_pipeline =
            ds4_gpu_get_mul_mv_pipeline(dot_dispatch.function_name, dot_dispatch.nsg);
        if (!dot_pipeline) return 0;
        ds4_gpu_dsv4_indexer_weighted_sum_args sum_args = {
            .ne00 = (int64_t)n_comp,
            .ne01 = 1,
            .ne02 = (int64_t)n_head,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)n_comp * sizeof(float),
            .nb02 = (uint64_t)n_comp * sizeof(float),
            .ne10 = (int64_t)n_head,
            .ne11 = 1,
            .nb10 = sizeof(float),
            .nb11 = (uint64_t)n_head * sizeof(float),
            .ne0 = (int64_t)n_comp,
            .ne1 = 1,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_comp * sizeof(float),
            .scale = scale,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:dot_pipeline];
        [enc setBytes:&dot_args length:sizeof(dot_args) atIndex:0];
        [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(index_comp) atIndex:1];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:2];
        [enc setBuffer:g_indexer_head_scores_buffer offset:0 atIndex:3];
        if (dot_dispatch.smem) {
            [enc setThreadgroupMemoryLength:dot_dispatch.smem atIndex:0];
        }
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + (NSUInteger)dot_dispatch.nr0 - 1u) / (NSUInteger)dot_dispatch.nr0,
                                              n_head,
                                              1)
             threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)dot_dispatch.nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_indexer_weighted_sum_pipeline];
        [enc setBytes:&sum_args length:sizeof(sum_args) atIndex:0];
        [enc setBuffer:g_indexer_head_scores_buffer offset:0 atIndex:1];
        [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:3];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + 255u) / 256u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer score")) return 0;
    }

    return 1;
}

static int ds4_gpu_indexer_scores_batch_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *index_comp,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                pos0,
        uint32_t                n_head,
        uint32_t                head_dim,
        uint32_t                ratio,
        float                   scale) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!scores || !q || !weights || !index_comp ||
        n_comp == 0 || n_tokens == 0 || n_head == 0 || head_dim == 0 || ratio == 0) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * head_dim * sizeof(float);
        const uint64_t weight_bytes = (uint64_t)n_tokens * n_head * sizeof(float);
        const uint64_t comp_bytes = (uint64_t)n_comp * head_dim * sizeof(float);
        const uint64_t score_bytes = (uint64_t)n_comp * n_tokens * sizeof(float);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> wbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> compbuf = ds4_gpu_tensor_buffer(index_comp);
        id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores);
        if (!qbuf || !wbuf || !compbuf || !scorebuf ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(weights) < weight_bytes ||
            ds4_gpu_tensor_bytes(index_comp) < comp_bytes ||
            ds4_gpu_tensor_bytes(scores) < score_bytes) {
            fprintf(stderr, "ds4: Metal graph indexer prefill scores received undersized buffers\n");
            return 0;
        }
        if (head_dim != 128) {
            fprintf(stderr, "ds4: Metal fused DS4 indexer scores expect 128-wide rows\n");
            return 0;
        }
        /*
         * The NAX/TensorOps score builder is a prefill-only win.  At small
         * batches and in one-token decode the setup cost is not amortized, so
         * those paths keep the older direct/tiled score kernels.
         */
        const bool use_nax = ds4_gpu_mpp_available() && n_tokens >= 16u;
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline(
            use_nax ? "kernel_dsv4_indexer_scores_nax" :
            (g_quality_mode ? "kernel_dsv4_indexer_scores_tiled_f32"
                            : "kernel_dsv4_indexer_scores_tiled"));
        if (!pipeline) return 0;

        ds4_gpu_dsv4_indexer_scores_fused_args args = {
            .n_comp = n_comp,
            .n_tokens = n_tokens,
            .n_head = n_head,
            .head_dim = head_dim,
            .pos0 = pos0,
            .ratio = ratio,
            .q_token_stride = (uint64_t)n_head * head_dim * sizeof(float),
            .q_head_stride = (uint64_t)head_dim * sizeof(float),
            .weights_token_stride = (uint64_t)n_head * sizeof(float),
            .index_row_stride = (uint64_t)head_dim * sizeof(float),
            .score_token_stride = (uint64_t)n_comp * sizeof(float),
            .scale = scale,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(index_comp) atIndex:3];
        [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
        if (use_nax) {
            const NSUInteger q_shared = 16u * 32u;
            const NSUInteger k_shared = 32u * 128u;
            const NSUInteger dot_shared = 16u * 32u;
            [enc setThreadgroupMemoryLength:(q_shared + k_shared) * sizeof(uint16_t) +
                                            dot_shared * sizeof(float) atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + 31u) / 32u,
                                                  ((NSUInteger)n_tokens + 15u) / 16u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        } else if (g_quality_mode) {
            const NSUInteger q_shared = 8u * 128u;
            const NSUInteger k_shared = 32u * 128u;
            const NSUInteger dot_shared = 8u * 32u;
            [enc setThreadgroupMemoryLength:(q_shared + k_shared + dot_shared) * sizeof(float) atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + 31u) / 32u,
                                                  ((NSUInteger)n_tokens + 7u) / 8u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
        } else {
            const NSUInteger q_shared = 8u * 128u;
            const NSUInteger k_shared = 32u * 128u;
            const NSUInteger dot_shared = 8u * 32u;
            [enc setThreadgroupMemoryLength:(q_shared + k_shared) * sizeof(uint16_t) +
                                            dot_shared * sizeof(float) atIndex:0];
            [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + 31u) / 32u,
                                                  ((NSUInteger)n_tokens + 7u) / 8u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer prefill scores")) return 0;
    }

    return 1;
}

int ds4_gpu_indexer_scores_prefill_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *index_comp,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                n_head,
        uint32_t                head_dim,
        uint32_t                ratio,
        float                   scale) {
    return ds4_gpu_indexer_scores_batch_tensor(scores,
                                                 q,
                                                 weights,
                                                 index_comp,
                                                 n_comp,
                                                 n_tokens,
                                                 0,
                                                 n_head,
                                                 head_dim,
                                                 ratio,
                                                 scale);
}

