        [enc setBuffer:dt_bias_buf offset:(NSUInteger)dt_bias_inner atIndex:4];
        [enc setBuffer:log_decay_buf offset:ds4_gpu_tensor_offset(log_decay) atIndex:5];
        [enc setBuffer:beta_buf offset:ds4_gpu_tensor_offset(beta) atIndex:6];
        [enc dispatchThreadgroups:MTLSizeMake(((NSUInteger)count + nth - 1u) / nth, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "Qwen delta controls")) return 0;
    }
    return 1;
}

int ds4_gpu_qwen35_gated_delta_controls_tensor(
        ds4_gpu_tensor       *log_decay,
        ds4_gpu_tensor       *beta,
        const ds4_gpu_tensor *alpha_logit,
        const ds4_gpu_tensor *beta_logit,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              ssm_a_offset,
        uint64_t              dt_bias_offset,
        uint32_t              n_value_head) {
    return ds4_gpu_qwen35_gated_delta_controls_batch_tensor(
        log_decay, beta, alpha_logit, beta_logit, model_map, model_size,
        ssm_a_offset, dt_bias_offset, 1u, n_value_head);
}

int ds4_gpu_qwen35_gqa_decode_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *query,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              n_kv,
        uint32_t              n_query_head,
        uint32_t              n_kv_head,
        uint32_t              head_dim) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !query || !key_cache || !value_cache || n_kv == 0 ||
        n_query_head == 0 || n_kv_head == 0 || head_dim == 0 ||
        n_query_head % n_kv_head != 0) {
        return 0;
    }

    const uint64_t query_values = (uint64_t)n_query_head * head_dim;
    const uint64_t cache_rows = (uint64_t)n_kv * n_kv_head;
    if (cache_rows > UINT64_MAX / head_dim) return 0;
    const uint64_t cache_values = cache_rows * head_dim;
    uint64_t query_bytes = 0, cache_bytes = 0;
    if (!ds4_gpu_qwen35_f32_bytes(query_values, &query_bytes) ||
        !ds4_gpu_qwen35_f32_bytes(cache_values, &cache_bytes)) {
        return 0;
    }

    @autoreleasepool {
        bool parallel_gqa =
            n_kv >= 256u &&
            getenv("DS4_QWEN_DISABLE_PARALLEL_GQA_DECODE") == NULL;
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline(
            parallel_gqa
                ? "kernel_qwen35_gqa_decode_parallel_f32"
                : "kernel_qwen35_gqa_decode_f32");
        NSUInteger width = pipeline ? pipeline.threadExecutionWidth : 0u;
        if (parallel_gqa &&
            (width == 0u ||
             ((NSUInteger)head_dim + width - 1u) / width > 8u)) {
            parallel_gqa = false;
            pipeline = ds4_gpu_get_pipeline("kernel_qwen35_gqa_decode_f32");
            width = pipeline ? pipeline.threadExecutionWidth : 0u;
        }
        id<MTLBuffer> query_buf = ds4_gpu_tensor_buffer(query);
        id<MTLBuffer> key_buf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> value_buf = ds4_gpu_tensor_buffer(value_cache);
        id<MTLBuffer> out_buf = ds4_gpu_tensor_buffer(out);
        if (!pipeline || !query_buf || !key_buf || !value_buf || !out_buf ||
            ds4_gpu_tensor_bytes(query) < query_bytes ||
            ds4_gpu_tensor_bytes(key_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(out) < query_bytes) {
            fprintf(stderr, "ds4: Metal Qwen GQA received undersized buffers\n");
            return 0;
        }

        if (width == 0 || head_dim > NSUIntegerMax - (width - 1u)) return 0;
        const NSUInteger preferred =
            (((NSUInteger)head_dim + width - 1u) / width) * width;
        NSUInteger nsg = 0;
        const NSUInteger nth =
            ds4_gpu_qwen35_reduction_threads(pipeline, preferred, &nsg);
        if (nth < head_dim || nth != preferred) return 0;
        if (parallel_gqa &&
            nsg > (NSUIntegerMax - 1u) / ((NSUInteger)head_dim + 2u)) {
            return 0;
        }
        const NSUInteger scratch_f32 = parallel_gqa
            ? nsg * ((NSUInteger)head_dim + 2u) + 1u
            : nsg + 4u;
        const uint64_t head_bytes = (uint64_t)head_dim * sizeof(float);
        const uint64_t token_bytes = (uint64_t)n_kv_head * head_bytes;
        ds4_gpu_qwen35_gqa_decode_args args = {
            .n_kv = n_kv,
            .n_query_head = n_query_head,
            .n_kv_head = n_kv_head,
            .head_dim = head_dim,
            .query_head_stride = head_bytes,
            .query_dim_stride = sizeof(float),
            .key_token_stride = token_bytes,
            .key_head_stride = head_bytes,
            .key_dim_stride = sizeof(float),
            .value_token_stride = token_bytes,
            .value_head_stride = head_bytes,
            .value_dim_stride = sizeof(float),
            .output_head_stride = head_bytes,
            .output_dim_stride = sizeof(float),
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:query_buf offset:ds4_gpu_tensor_offset(query) atIndex:1];
        [enc setBuffer:key_buf offset:ds4_gpu_tensor_offset(key_cache) atIndex:2];
        [enc setBuffer:value_buf offset:ds4_gpu_tensor_offset(value_cache) atIndex:3];
        [enc setBuffer:out_buf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [enc setThreadgroupMemoryLength:
             ds4_gpu_qwen35_threadgroup_f32_bytes(scratch_f32) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(n_query_head, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(
                cb, owned, parallel_gqa ? "Qwen parallel GQA" : "Qwen GQA")) {
            return 0;
        }
    }
    return 1;
}

int ds4_gpu_qwen35_gqa_prefill_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *query,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              position0,
        uint32_t              n_token,
        uint32_t              n_query_head,
        uint32_t              n_kv_head,
        uint32_t              head_dim) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !query || !key_cache || !value_cache || n_token == 0 ||
        n_query_head == 0 || n_kv_head == 0 || head_dim == 0 ||
        n_query_head % n_kv_head != 0 ||
        position0 > UINT32_MAX - n_token) {
        return 0;
    }

    const uint64_t query_row_values =
        (uint64_t)n_query_head * head_dim;
    const uint64_t cache_token_values =
        (uint64_t)n_kv_head * head_dim;
    const uint64_t n_kv = (uint64_t)position0 + n_token;
    if (query_row_values > UINT64_MAX / n_token ||
        cache_token_values > UINT64_MAX / n_kv) {
        return 0;
    }
    uint64_t query_bytes = 0, cache_bytes = 0;
    if (!ds4_gpu_qwen35_f32_bytes(
            query_row_values * n_token, &query_bytes) ||
        !ds4_gpu_qwen35_f32_bytes(
            cache_token_values * n_kv, &cache_bytes)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_pipeline("kernel_qwen35_gqa_prefill_f32");
        id<MTLBuffer> query_buf = ds4_gpu_tensor_buffer(query);
        id<MTLBuffer> key_buf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> value_buf = ds4_gpu_tensor_buffer(value_cache);
        id<MTLBuffer> out_buf = ds4_gpu_tensor_buffer(out);
        if (!pipeline || !query_buf || !key_buf || !value_buf || !out_buf ||
            ds4_gpu_tensor_bytes(query) < query_bytes ||
            ds4_gpu_tensor_bytes(key_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(out) < query_bytes) {
            fprintf(stderr,
                    "ds4: Metal Qwen GQA prefill received undersized buffers\n");
            return 0;
        }

        const NSUInteger width = pipeline.threadExecutionWidth;
        if (width == 0 || head_dim > NSUIntegerMax - (width - 1u)) return 0;
        const NSUInteger preferred =
            (((NSUInteger)head_dim + width - 1u) / width) * width;
        NSUInteger nsg = 0;
        const NSUInteger nth =
            ds4_gpu_qwen35_reduction_threads(pipeline, preferred, &nsg);
        if (nth < head_dim || nth != preferred) return 0;
        const uint64_t head_bytes = (uint64_t)head_dim * sizeof(float);
        const uint64_t query_token_bytes =
            (uint64_t)n_query_head * head_bytes;
        const uint64_t cache_token_bytes =
            (uint64_t)n_kv_head * head_bytes;
        ds4_gpu_qwen35_gqa_prefill_args args = {
            .position0 = position0,
            .n_token = n_token,
            .n_query_head = n_query_head,
            .n_kv_head = n_kv_head,
            .head_dim = head_dim,
            .reserved = 0,
            .query_token_stride = query_token_bytes,
            .query_head_stride = head_bytes,
            .query_dim_stride = sizeof(float),
            .key_token_stride = cache_token_bytes,
            .key_head_stride = head_bytes,
            .key_dim_stride = sizeof(float),
            .value_token_stride = cache_token_bytes,
            .value_head_stride = head_bytes,
            .value_dim_stride = sizeof(float),
            .output_token_stride = query_token_bytes,
            .output_head_stride = head_bytes,
            .output_dim_stride = sizeof(float),
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:query_buf offset:ds4_gpu_tensor_offset(query) atIndex:1];
        [enc setBuffer:key_buf offset:ds4_gpu_tensor_offset(key_cache) atIndex:2];
        [enc setBuffer:value_buf offset:ds4_gpu_tensor_offset(value_cache) atIndex:3];
        [enc setBuffer:out_buf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [enc setThreadgroupMemoryLength:
             ds4_gpu_qwen35_threadgroup_f32_bytes(nsg + 4u) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(n_query_head, n_token, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "Qwen GQA prefill")) {
            return 0;
        }
    }
    return 1;
}

enum {
    DS4_QWEN35_GQA_REUSE_QUERY_PER_KV = 8,
    DS4_QWEN35_GQA_REUSE_CONTEXT_LANES = 2,
    DS4_QWEN35_GQA_REUSE_SIMDGROUPS =
        DS4_QWEN35_GQA_REUSE_QUERY_PER_KV *
        DS4_QWEN35_GQA_REUSE_CONTEXT_LANES,
    DS4_QWEN35_GQA_REUSE_DIMS_PER_LANE = 8,
    /* Below one 64-token scheduler micro-block, dispatch consolidation costs
     * more than sharing a tiny K/V frontier.  Keeping the old kernel here is
     * also the explicit short-context fallback promised by the runtime plan. */
    DS4_QWEN35_GQA_REUSE_MIN_CONTEXT = 64,
    DS4_QWEN35_GQA_SPLIT_K_MIN_CONTEXT = 2048,
    DS4_QWEN35_GQA_SPLIT_K_CONTEXT_LANES = 32,
    DS4_QWEN35_GQA_SPLIT_K_CHUNK = 32,
    DS4_QWEN35_GQA_FLASH_NQPTG = 8,
    DS4_QWEN35_GQA_FLASH_NCPSG = 64,
    DS4_QWEN35_GQA_FLASH_NSG = 4,
    DS4_QWEN35_GQA_FLASH_MAX_TOKENS = 65536,
};

/* The non-vector kernel exposes dynamic memory as a half array even when a
 * specialization stores F32 Q/O/S regions in it.  Mirror the shader layout in
 * half elements and keep overflow checks here so capability and dispatch use
 * exactly the same byte count.  The direct Qwen specialization uses same-type
 * F32 K/V loads, so the dequantization scratch at the tail of the generic
 * layout is compile-time dead and is intentionally not included. */
static int ds4_gpu_qwen35_gqa_flash_shared_bytes(
        uint32_t    head_dim,
        NSUInteger *bytes_out) {
    if (!bytes_out || head_dim != 256u) return 0;

    const NSUInteger q_storage = sizeof(float) / sizeof(uint16_t);
    const NSUInteger o_storage = sizeof(float) / sizeof(uint16_t);
    const NSUInteger s_storage = sizeof(float) / sizeof(uint16_t);
    const NSUInteger padded_v = ds4_gpu_align_up_ns(head_dim, 64u);
    const NSUInteger score_elems =
        2u * (NSUInteger)DS4_QWEN35_GQA_FLASH_NCPSG;
    if (padded_v < head_dim ||
        (NSUInteger)head_dim > NSUIntegerMax / q_storage ||
        padded_v > NSUIntegerMax / o_storage ||
        score_elems > NSUIntegerMax / s_storage) {
        return 0;
    }

    const NSUInteger q_elems = q_storage * (NSUInteger)head_dim;
    const NSUInteger o_elems = o_storage * padded_v;
    const NSUInteger s_elems = s_storage * score_elems;
    if (q_elems > NSUIntegerMax - o_elems ||
        q_elems + o_elems > NSUIntegerMax - s_elems) {
        return 0;
    }
    const NSUInteger per_query = q_elems + o_elems + s_elems;
    if (per_query > NSUIntegerMax / DS4_QWEN35_GQA_FLASH_NQPTG) {
        return 0;
    }
    const NSUInteger half_elems =
        per_query * DS4_QWEN35_GQA_FLASH_NQPTG;
    if (half_elems > (NSUIntegerMax - 15u) / sizeof(uint16_t)) return 0;
    *bytes_out = ds4_gpu_align_up_ns(
        half_elems * sizeof(uint16_t), 16u);
    return 1;
}

static int ds4_gpu_qwen35_pipeline_supports_dispatch(
        id<MTLComputePipelineState> pipeline,
        NSUInteger                  threads,
        NSUInteger                  dynamic_threadgroup_bytes) {
    if (!pipeline || pipeline.threadExecutionWidth != 32u ||
        pipeline.maxTotalThreadsPerThreadgroup < threads) {
        return 0;
    }
    const NSUInteger maximum = [g_device maxThreadgroupMemoryLength];
    const NSUInteger static_bytes = pipeline.staticThreadgroupMemoryLength;
    return static_bytes <= maximum &&
           dynamic_threadgroup_bytes <= maximum - static_bytes;
}

static int ds4_gpu_qwen35_gqa_reuse_pipeline(
        const char                  *name,
        uint32_t                     n_query_head,
        uint32_t                     n_kv_head,
        uint32_t                     head_dim,
        id<MTLComputePipelineState> *pipeline_out,
        NSUInteger                  *threads_out,
        NSUInteger                  *scratch_f32_out) {
    if (!name || !pipeline_out || !threads_out || !scratch_f32_out ||
        n_kv_head == 0u ||
        n_kv_head > UINT32_MAX / DS4_QWEN35_GQA_REUSE_QUERY_PER_KV ||
        head_dim == 0u ||
        n_query_head !=
            n_kv_head * DS4_QWEN35_GQA_REUSE_QUERY_PER_KV) {
        return 0;
    }

    id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline(name);
    const NSUInteger width = pipeline ? pipeline.threadExecutionWidth : 0u;
    if (width == 0u ||
        width > NSUIntegerMax / DS4_QWEN35_GQA_REUSE_SIMDGROUPS ||
        head_dim > width * DS4_QWEN35_GQA_REUSE_DIMS_PER_LANE) {
        return 0;
    }
    const NSUInteger threads =
        width * DS4_QWEN35_GQA_REUSE_SIMDGROUPS;
    if (pipeline.maxTotalThreadsPerThreadgroup < threads) return 0;

    /* Shader layout: two K rows + two V rows + 16 partial output rows +
     * 16 maxima + 16 denominators.  Check both arithmetic and the concrete
     * device budget here, so a strict campaign can reject an unsupported GPU
     * before any stateful graph dispatch occurs. */
    if ((NSUInteger)head_dim > (NSUIntegerMax - 32u) / 20u) return 0;
    const NSUInteger scratch_f32 = (NSUInteger)head_dim * 20u + 32u;
    const NSUInteger scratch_bytes =
        ds4_gpu_qwen35_threadgroup_f32_bytes(scratch_f32);
    if (scratch_bytes > [g_device maxThreadgroupMemoryLength]) return 0;

    *pipeline_out = pipeline;
    *threads_out = threads;
    *scratch_f32_out = scratch_f32;
    return 1;
}

int ds4_gpu_qwen35_gqa_reuse_capable(
        uint32_t n_query_head,
        uint32_t n_kv_head,
        uint32_t head_dim) {
    if (n_query_head != 16u || n_kv_head != 2u || head_dim != 256u) {
        return 0;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;
    @autoreleasepool {
        id<MTLComputePipelineState> decode_pipeline = nil;
        id<MTLComputePipelineState> exact_prefill_pipeline = nil;
        NSUInteger decode_threads = 0u, decode_scratch = 0u;
        NSUInteger exact_prefill_threads = 0u, exact_prefill_scratch = 0u;
        const int32_t cache_token_values =
            (int32_t)(n_kv_head * head_dim);
        id<MTLComputePipelineState> flash_no_pad_pipeline =
            ds4_gpu_get_flash_attn_pipeline(
                "kernel_flash_attn_ext_f32_dk256_dv256",
                false, false, false, false, false, false,
                cache_token_values, cache_token_values,
                DS4_QWEN35_GQA_FLASH_NSG);
        id<MTLComputePipelineState> flash_pad_pipeline =
            ds4_gpu_get_flash_attn_pipeline(
                "kernel_flash_attn_ext_f32_dk256_dv256",
                false, false, false, false, true, false,
                cache_token_values, cache_token_values,
                DS4_QWEN35_GQA_FLASH_NSG);
        id<MTLComputePipelineState> pad_pipeline =
            ds4_gpu_get_pipeline("kernel_qwen35_gqa_prefill_pad_kv_f32");
        const NSUInteger flash_threads =
            32u * DS4_QWEN35_GQA_FLASH_NSG;
        NSUInteger flash_shared_bytes = 0u;
        return ds4_gpu_qwen35_gqa_reuse_pipeline(
                   "kernel_qwen35_gqa_decode_reuse8_f32",
                   n_query_head, n_kv_head, head_dim,
                   &decode_pipeline, &decode_threads, &decode_scratch) &&
               ds4_gpu_qwen35_gqa_reuse_pipeline(
                   "kernel_qwen35_gqa_prefill_reuse8_f32",
                   n_query_head, n_kv_head, head_dim,
                   &exact_prefill_pipeline, &exact_prefill_threads,
                   &exact_prefill_scratch) &&
               ds4_gpu_qwen35_gqa_flash_shared_bytes(
                   head_dim, &flash_shared_bytes) &&
               ds4_gpu_qwen35_pipeline_supports_dispatch(
                   flash_no_pad_pipeline, flash_threads,
                   flash_shared_bytes) &&
               ds4_gpu_qwen35_pipeline_supports_dispatch(
                   flash_pad_pipeline, flash_threads,
                   flash_shared_bytes) &&
               ds4_gpu_qwen35_pipeline_supports_dispatch(
                   pad_pipeline, head_dim, 0u);
    }
}

/* Long-context Qwen split-K preserves the production F32 token-major K/V
 * cache and gives every query head its own FlashAttention row. */
static int ds4_gpu_qwen35_gqa_decode_split_k_f32_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *query,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              n_kv,
        uint32_t              n_query_head,
        uint32_t              n_kv_head,
        uint32_t              head_dim) {
    if (!out || !query || !key_cache || !value_cache ||
        n_kv < DS4_QWEN35_GQA_SPLIT_K_MIN_CONTEXT ||
        n_query_head != 16u || n_kv_head != 2u || head_dim != 256u) {
        return 0;
    }

    const uint64_t head_bytes = (uint64_t)head_dim * sizeof(float);
    const uint64_t query_bytes = (uint64_t)n_query_head * head_bytes;
    const uint64_t token_bytes = (uint64_t)n_kv_head * head_bytes;
    if ((uint64_t)n_kv > UINT64_MAX / token_bytes) return 0;
    const uint64_t cache_bytes = (uint64_t)n_kv * token_bytes;

    id<MTLBuffer> query_buf = ds4_gpu_tensor_buffer(query);
    id<MTLBuffer> key_buf = ds4_gpu_tensor_buffer(key_cache);
    id<MTLBuffer> value_buf = ds4_gpu_tensor_buffer(value_cache);
    id<MTLBuffer> out_buf = ds4_gpu_tensor_buffer(out);
    if (!query_buf || !key_buf || !value_buf || !out_buf ||
        ds4_gpu_tensor_bytes(query) < query_bytes ||
        ds4_gpu_tensor_bytes(key_cache) < cache_bytes ||
        ds4_gpu_tensor_bytes(value_cache) < cache_bytes ||
        ds4_gpu_tensor_bytes(out) < query_bytes) {
        fprintf(stderr, "ds4: Metal Qwen split-K GQA received undersized buffers\n");
        return 0;
    }

    const uint32_t nwg = DS4_QWEN35_GQA_SPLIT_K_CONTEXT_LANES;
    const uint32_t ncpsg = DS4_QWEN35_GQA_SPLIT_K_CHUNK;
    uint32_t nsg = ds4_gpu_flash_attn_vec_nsg(n_kv, nwg, ncpsg);
    /* Full-F32 query staging increases the resource footprint relative to the
     * existing F16 vector kernel. Two SIMD groups keep dk256 within the M5
     * pipeline's executable threadgroup limit while the 32 context partitions
     * still expose ample long-context parallelism. */
    if (nsg > 2u) nsg = 2u;
    const int32_t token_stride_f32 =
        (int32_t)(token_bytes / sizeof(float));
    const bool has_kvpad = (n_kv % ncpsg) != 0u;
    id<MTLComputePipelineState> vec_pipeline =
        ds4_gpu_get_flash_attn_vec_pipeline(
            "kernel_flash_attn_ext_vec_f32_dk256_dv256",
            false, false, false, false, has_kvpad,
            token_stride_f32, token_stride_f32,
            (int32_t)nsg, (int32_t)nwg);
    id<MTLComputePipelineState> reduce_pipeline =
        ds4_gpu_get_flash_attn_reduce_pipeline((int32_t)head_dim,
                                                (int32_t)nwg);
    id<MTLComputePipelineState> pad_pipeline = has_kvpad
        ? ds4_gpu_get_pipeline("kernel_qwen35_gqa_split_k_pad_f32")
        : nil;
    const NSUInteger vec_threads = 32u * (NSUInteger)nsg;
    const NSUInteger reduce_threads = 32u * (NSUInteger)nwg;
    if (!vec_pipeline || !reduce_pipeline || (has_kvpad && !pad_pipeline) ||
        vec_pipeline.maxTotalThreadsPerThreadgroup < vec_threads ||
        reduce_pipeline.maxTotalThreadsPerThreadgroup < reduce_threads) {
        fprintf(stderr,
                "ds4: Metal Qwen split-K pipeline unsupported "
                "(nsg=%u vec_threads=%llu/%llu reduce_threads=%llu/%llu)\n",
                nsg,
                (unsigned long long)vec_threads,
                (unsigned long long)(vec_pipeline
                    ? vec_pipeline.maxTotalThreadsPerThreadgroup : 0u),
                (unsigned long long)reduce_threads,
                (unsigned long long)(reduce_pipeline
                    ? reduce_pipeline.maxTotalThreadsPerThreadgroup : 0u));
        return 0;
    }

    const NSUInteger nrows = (NSUInteger)n_query_head;
    const NSUInteger tmp_bytes =
        nrows * (NSUInteger)head_dim * (NSUInteger)nwg * sizeof(float) +
        nrows * (2u * (NSUInteger)nwg) * sizeof(float);
    /* The vec kernel's existing pad ABI stores K heads consecutively, then V
     * heads.  A persistent zero buffer avoids the generic row-copy pad kernel,
     * whose row-width assumption is not valid for token-major Qwen caches. */
    const NSUInteger pad_bytes = has_kvpad
        ? 2u * (NSUInteger)ncpsg * (NSUInteger)token_bytes *
              (NSUInteger)n_kv_head
        : 1u;
    if (!ds4_gpu_ensure_scratch_buffer(&g_flash_attn_tmp_buffer,
                                         &g_flash_attn_tmp_bytes,
                                         tmp_bytes,
                                         "ds4_flash_attn_tmp") ||
        !ds4_gpu_ensure_qwen35_gqa_split_k_pad(pad_bytes)) {
        return 0;
    }

    ds4_gpu_flash_attn_vec_args vec_args = {
        .ne01 = 1,
        .ne02 = (int32_t)n_query_head,
        .ne03 = 1,
        .nb01 = query_bytes,
        .nb02 = head_bytes,
        .nb03 = query_bytes,
        .ne11 = (int32_t)n_kv,
        .ne_12_2 = (int32_t)n_kv_head,
        .ne_12_3 = 1,
        .ns10 = token_stride_f32,
        .nb11 = token_bytes,
        .nb12 = head_bytes,
        .nb13 = cache_bytes,
        .ns20 = token_stride_f32,
        .nb21 = token_bytes,
        .nb22 = head_bytes,
        .nb23 = cache_bytes,
        .ne31 = 1,
        .ne32 = 1,
        .ne33 = 1,
        .nb31 = 0,
        .nb32 = 0,
        .nb33 = 0,
        .ne1 = (int32_t)n_query_head,
        .ne2 = 1,
        .ne3 = 1,
        .scale = 1.0f / sqrtf((float)head_dim),
        .max_bias = 0.0f,
        .m0 = 0.0f,
        .m1 = 0.0f,
        .n_head_log2 = 0,
        .logit_softcap = 0.0f,
    };
    const NSUInteger shared_elems =
        (2u * ds4_gpu_align_up_ns(head_dim, 128u) + 4u * ncpsg +
         2u * ds4_gpu_align_up_ns(head_dim, 128u)) * nsg;
    const NSUInteger shared_bytes =
        ds4_gpu_align_up_ns(shared_elems * (sizeof(float) / 2u), 16u);

    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    if (!cb) return 0;
    if (has_kvpad) {
        ds4_gpu_qwen35_gqa_decode_args pad_args = {
            .n_kv = n_kv,
            .n_query_head = n_query_head,
            .n_kv_head = n_kv_head,
            .head_dim = head_dim,
            .query_head_stride = head_bytes,
            .query_dim_stride = sizeof(float),
            .key_token_stride = token_bytes,
            .key_head_stride = head_bytes,
            .key_dim_stride = sizeof(float),
            .value_token_stride = token_bytes,
            .value_head_stride = head_bytes,
            .value_dim_stride = sizeof(float),
            .output_head_stride = head_bytes,
            .output_dim_stride = sizeof(float),
        };
        id<MTLComputeCommandEncoder> pad_enc = ds4_gpu_compute_encoder(cb);
        if (!pad_enc) return 0;
        [pad_enc setComputePipelineState:pad_pipeline];
        [pad_enc setBytes:&pad_args length:sizeof(pad_args) atIndex:0];
        [pad_enc setBuffer:key_buf
                    offset:ds4_gpu_tensor_offset(key_cache) atIndex:1];
        [pad_enc setBuffer:value_buf
                    offset:ds4_gpu_tensor_offset(value_cache) atIndex:2];
        [pad_enc setBuffer:g_qwen35_gqa_split_k_pad_buffer
                    offset:0 atIndex:3];
        [pad_enc dispatchThreadgroups:MTLSizeMake(n_kv_head, 2u, 1u)
              threadsPerThreadgroup:MTLSizeMake(head_dim, 1u, 1u)];
        ds4_gpu_end_compute_encoder(cb, pad_enc);
    }
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    if (!enc) return 0;
    [enc setComputePipelineState:vec_pipeline];
    [enc setBytes:&vec_args length:sizeof(vec_args) atIndex:0];
    [enc setBuffer:query_buf offset:ds4_gpu_tensor_offset(query) atIndex:1];
    [enc setBuffer:key_buf offset:ds4_gpu_tensor_offset(key_cache) atIndex:2];
    [enc setBuffer:value_buf offset:ds4_gpu_tensor_offset(value_cache) atIndex:3];
    [enc setBuffer:g_qwen35_gqa_split_k_pad_buffer offset:0 atIndex:4];
    [enc setBuffer:g_qwen35_gqa_split_k_pad_buffer offset:0 atIndex:5];
    [enc setBuffer:g_qwen35_gqa_split_k_pad_buffer offset:0 atIndex:6];
    [enc setBuffer:g_flash_attn_tmp_buffer offset:0 atIndex:7];
    [enc setThreadgroupMemoryLength:shared_bytes atIndex:0];
    [enc dispatchThreadgroups:MTLSizeMake(1u, n_query_head, nwg)
         threadsPerThreadgroup:MTLSizeMake(32u, nsg, 1u)];
    ds4_gpu_end_compute_encoder(cb, enc);

    ds4_gpu_flash_attn_reduce_args reduce_args = {
        .nrows = (int32_t)nrows,
    };
    enc = ds4_gpu_compute_encoder(cb);
    if (!enc) return 0;
    [enc setComputePipelineState:reduce_pipeline];
    [enc setBytes:&reduce_args length:sizeof(reduce_args) atIndex:0];
    [enc setBuffer:g_flash_attn_tmp_buffer offset:0 atIndex:1];
    [enc setBuffer:out_buf offset:ds4_gpu_tensor_offset(out) atIndex:2];
    [enc dispatchThreadgroups:MTLSizeMake(nrows, 1u, 1u)
         threadsPerThreadgroup:MTLSizeMake(reduce_threads, 1u, 1u)];
    ds4_gpu_end_compute_encoder(cb, enc);

    if (!ds4_gpu_finish_command_buffer(cb, owned, "Qwen split-K F32 GQA")) {
        return 0;
    }
    return 1;
}

int ds4_gpu_qwen35_gqa_decode_select_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *query,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              n_kv,
        uint32_t              n_query_head,
        uint32_t              n_kv_head,
        uint32_t              head_dim,
        int                   request_reuse,
        int                  *reuse_used) {
    if (reuse_used) *reuse_used = DS4_GPU_QWEN35_GQA_PATH_LEGACY;
    if (!request_reuse) {
        return ds4_gpu_qwen35_gqa_decode_tensor(
            out, query, key_cache, value_cache, n_kv,
            n_query_head, n_kv_head, head_dim);
    }
    if (n_kv >= DS4_QWEN35_GQA_SPLIT_K_MIN_CONTEXT) {
        static int logged;
        if (!logged) {
            fprintf(stderr,
                    "ds4: Qwen split-K F32 GQA enabled at 2048+ context "
                    "(32 context workgroups, F32 KV)\n");
            logged = 1;
        }
        const int ok = ds4_gpu_qwen35_gqa_decode_split_k_f32_tensor(
            out, query, key_cache, value_cache, n_kv,
            n_query_head, n_kv_head, head_dim);
        if (ok) {
            if (reuse_used) {
                *reuse_used = DS4_GPU_QWEN35_GQA_PATH_EXACT_REUSE;
            }
            return 1;
        }
        static int fallback_logged;
        if (!fallback_logged) {
            fprintf(stderr,
                    "ds4: Qwen split-K F32 GQA unavailable; using the "
                    "legacy GQA decode path\n");
            fallback_logged = 1;
        }
    }
    if (n_kv < DS4_QWEN35_GQA_SPLIT_K_MIN_CONTEXT) {
        return ds4_gpu_qwen35_gqa_decode_tensor(
            out, query, key_cache, value_cache, n_kv,
            n_query_head, n_kv_head, head_dim);
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;

    @autoreleasepool {
        id<MTLComputePipelineState> pipeline = nil;
        NSUInteger nth = 0u, scratch_f32 = 0u;
        if (!ds4_gpu_qwen35_gqa_reuse_pipeline(
                "kernel_qwen35_gqa_decode_reuse8_f32",
                n_query_head, n_kv_head, head_dim,
                &pipeline, &nth, &scratch_f32)) {
            return ds4_gpu_qwen35_gqa_decode_tensor(
                out, query, key_cache, value_cache, n_kv,
                n_query_head, n_kv_head, head_dim);
        }
        if (!out || !query || !key_cache || !value_cache || n_kv == 0u) {
            return 0;
        }

        const uint64_t query_values = (uint64_t)n_query_head * head_dim;
        const uint64_t cache_rows = (uint64_t)n_kv * n_kv_head;
        if (cache_rows > UINT64_MAX / head_dim) return 0;
        const uint64_t cache_values = cache_rows * head_dim;
        uint64_t query_bytes = 0u, cache_bytes = 0u;
        if (!ds4_gpu_qwen35_f32_bytes(query_values, &query_bytes) ||
            !ds4_gpu_qwen35_f32_bytes(cache_values, &cache_bytes)) {
            return 0;
        }

        id<MTLBuffer> query_buf = ds4_gpu_tensor_buffer(query);
        id<MTLBuffer> key_buf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> value_buf = ds4_gpu_tensor_buffer(value_cache);
        id<MTLBuffer> out_buf = ds4_gpu_tensor_buffer(out);
        if (!query_buf || !key_buf || !value_buf || !out_buf ||
            ds4_gpu_tensor_bytes(query) < query_bytes ||
            ds4_gpu_tensor_bytes(key_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(out) < query_bytes) {
            fprintf(stderr,
                    "ds4: Metal Qwen GQA reuse received undersized buffers\n");
            return 0;
        }

        const uint64_t head_bytes = (uint64_t)head_dim * sizeof(float);
        const uint64_t token_bytes = (uint64_t)n_kv_head * head_bytes;
        ds4_gpu_qwen35_gqa_decode_args args = {
            .n_kv = n_kv,
            .n_query_head = n_query_head,
            .n_kv_head = n_kv_head,
            .head_dim = head_dim,
            .query_head_stride = head_bytes,
            .query_dim_stride = sizeof(float),
            .key_token_stride = token_bytes,
            .key_head_stride = head_bytes,
            .key_dim_stride = sizeof(float),
            .value_token_stride = token_bytes,
            .value_head_stride = head_bytes,
            .value_dim_stride = sizeof(float),
            .output_head_stride = head_bytes,
            .output_dim_stride = sizeof(float),
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:query_buf offset:ds4_gpu_tensor_offset(query) atIndex:1];
        [enc setBuffer:key_buf offset:ds4_gpu_tensor_offset(key_cache) atIndex:2];
        [enc setBuffer:value_buf offset:ds4_gpu_tensor_offset(value_cache) atIndex:3];
        [enc setBuffer:out_buf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [enc setThreadgroupMemoryLength:
             ds4_gpu_qwen35_threadgroup_f32_bytes(scratch_f32) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(n_kv_head, 1u, 1u)
             threadsPerThreadgroup:MTLSizeMake(nth, 1u, 1u)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned,
                                           "Qwen GQA K/V reuse")) {
            return 0;
        }
    }
    if (reuse_used) {
        *reuse_used = DS4_GPU_QWEN35_GQA_PATH_EXACT_REUSE;
    }
    return 1;
}

/*
 * Qwen's production cache is token-major F32:
 *   [token][kv_head][head_dim]
 *
 * The generic non-vector FlashAttention kernel understands grouped query
 * attention through ne_12_2.  Its Qwen specialization reads the persistent
 * F32 K/V cache directly, so there is no context-sized conversion or staging
 * allocation.  Resident and SSD execution use exactly the same attention
 * tensors and arithmetic; only expert-weight residency differs.
 *
 * A Qwen-specific pad kernel repacks only the final partial 64-key tile, so the
 * fast path covers arbitrary prompt lengths without converting the persistent
 * cache layout.  Causality is implicit in the FlashAttention kernel; avoiding
 * the dense F16 [query][key] mask keeps auxiliary storage linear in context.
 */
static int ds4_gpu_qwen35_gqa_prefill_flash_f32_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *query,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              position0,
        uint32_t              n_token,
        uint32_t              n_query_head,
        uint32_t              n_kv_head,
        uint32_t              head_dim) {
    if (!out || !query || !key_cache || !value_cache ||
        n_token == 0u || n_token > DS4_QWEN35_GQA_FLASH_MAX_TOKENS ||
        n_query_head != 16u || n_kv_head != 2u || head_dim != 256u ||
        position0 > UINT32_MAX - n_token) {
        return 0;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;
    const uint32_t n_kv = position0 + n_token;
    if (n_kv < DS4_QWEN35_GQA_FLASH_NCPSG || n_kv > INT32_MAX) return 0;

    NSUInteger shared_bytes = 0u;
    if (!ds4_gpu_qwen35_gqa_flash_shared_bytes(
            head_dim, &shared_bytes)) {
        return 0;
    }

    const uint64_t query_values =
        (uint64_t)n_token * n_query_head * head_dim;
    const uint64_t cache_values =
        (uint64_t)n_kv * n_kv_head * head_dim;
    if (query_values > UINT64_MAX / sizeof(float) ||
        cache_values > UINT64_MAX / sizeof(float)) {
        return 0;
    }
    const uint64_t query_bytes = query_values * sizeof(float);
    const uint64_t cache_bytes = cache_values * sizeof(float);
    const uint64_t cache_head_bytes =
        (uint64_t)head_dim * sizeof(float);
    const uint64_t cache_token_bytes =
        (uint64_t)n_kv_head * cache_head_bytes;

    const NSUInteger nblk1 =
        ((NSUInteger)n_token + DS4_QWEN35_GQA_FLASH_NQPTG - 1u) /
        DS4_QWEN35_GQA_FLASH_NQPTG;
    const bool has_kvpad =
        (n_kv % DS4_QWEN35_GQA_FLASH_NCPSG) != 0u;
    const NSUInteger pad_kv_region_bytes = has_kvpad
        ? (NSUInteger)cache_token_bytes * DS4_QWEN35_GQA_FLASH_NCPSG *
              n_kv_head
        : 0u;
    const NSUInteger pad_bytes = has_kvpad
        ? 2u * pad_kv_region_bytes
        : 1u;

    id<MTLBuffer> query_buf = ds4_gpu_tensor_buffer(query);
    id<MTLBuffer> key_buf = ds4_gpu_tensor_buffer(key_cache);
    id<MTLBuffer> value_buf = ds4_gpu_tensor_buffer(value_cache);
    id<MTLBuffer> out_buf = ds4_gpu_tensor_buffer(out);
    if (!query_buf || !key_buf || !value_buf || !out_buf ||
        ds4_gpu_tensor_bytes(query) < query_bytes ||
        ds4_gpu_tensor_bytes(key_cache) < cache_bytes ||
        ds4_gpu_tensor_bytes(value_cache) < cache_bytes ||
        ds4_gpu_tensor_bytes(out) < query_bytes ||
        !ds4_gpu_ensure_scratch_buffer(&g_flash_attn_pad_buffer,
                                         &g_flash_attn_pad_bytes,
                                         pad_bytes,
                                         "ds4_qwen_flash_attn_pad") ||
        !ds4_gpu_ensure_scratch_buffer(&g_flash_attn_blk_buffer,
                                         &g_flash_attn_blk_bytes,
                                         1u,
                                         "ds4_qwen_flash_attn_blk")) {
        return 0;
    }

    const int32_t cache_token_values =
        (int32_t)(n_kv_head * head_dim);
    const uint32_t nsg = DS4_QWEN35_GQA_FLASH_NSG;
    id<MTLComputePipelineState> attn_pipeline =
        ds4_gpu_get_flash_attn_pipeline(
            "kernel_flash_attn_ext_f32_dk256_dv256",
            false, false, false, false, has_kvpad, false,
            cache_token_values, cache_token_values, (int32_t)nsg);
    id<MTLComputePipelineState> pad_kv_pipeline = has_kvpad
        ? ds4_gpu_get_pipeline("kernel_qwen35_gqa_prefill_pad_kv_f32")
        : nil;
    const NSUInteger threads = 32u * (NSUInteger)nsg;
    if (!ds4_gpu_qwen35_pipeline_supports_dispatch(
            attn_pipeline, threads, shared_bytes) ||
        (has_kvpad && !ds4_gpu_qwen35_pipeline_supports_dispatch(
            pad_kv_pipeline, head_dim, 0u))) {
        return 0;
    }

    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    if (!cb) return -1;

    if (has_kvpad) {
        ds4_gpu_qwen35_gqa_decode_args pad_kv_args = {
            .n_kv = n_kv,
            .n_query_head = n_query_head,
            .n_kv_head = n_kv_head,
            .head_dim = head_dim,
            .query_head_stride = 0u,
            .query_dim_stride = 0u,
            .key_token_stride = cache_token_bytes,
            .key_head_stride = cache_head_bytes,
            .key_dim_stride = sizeof(float),
            .value_token_stride = cache_token_bytes,
            .value_head_stride = cache_head_bytes,
            .value_dim_stride = sizeof(float),
            .output_head_stride = 0u,
            .output_dim_stride = 0u,
        };
        id<MTLComputeCommandEncoder> pad_enc = ds4_gpu_compute_encoder(cb);
        if (!pad_enc) return -1;
        [pad_enc setComputePipelineState:pad_kv_pipeline];
        [pad_enc setBytes:&pad_kv_args length:sizeof(pad_kv_args) atIndex:0];
        [pad_enc setBuffer:key_buf
                    offset:ds4_gpu_tensor_offset(key_cache) atIndex:1];
        [pad_enc setBuffer:value_buf
                    offset:ds4_gpu_tensor_offset(value_cache) atIndex:2];
        [pad_enc setBuffer:g_flash_attn_pad_buffer offset:0u atIndex:3];
        [pad_enc dispatchThreadgroups:MTLSizeMake(n_kv_head, 2u, 1u)
              threadsPerThreadgroup:MTLSizeMake(head_dim, 1u, 1u)];
        ds4_gpu_end_compute_encoder(cb, pad_enc);
    }

    const uint64_t query_head_bytes =
        (uint64_t)head_dim * sizeof(float);
    const uint64_t query_token_bytes =
        (uint64_t)n_query_head * query_head_bytes;
    ds4_gpu_flash_attn_vec_args args = {
        .ne01 = (int32_t)n_token,
        .ne02 = (int32_t)n_query_head,
        .ne03 = 1,
        .nb01 = query_token_bytes,
        .nb02 = query_head_bytes,
        .nb03 = query_bytes,
        .ne11 = (int32_t)n_kv,
        .ne_12_2 = (int32_t)n_kv_head,
        .ne_12_3 = 1,
        .ns10 = cache_token_values,
        .nb11 = cache_token_bytes,
        .nb12 = cache_head_bytes,
        .nb13 = cache_bytes,
        .ns20 = cache_token_values,
        .nb21 = cache_token_bytes,
        .nb22 = cache_head_bytes,
        .nb23 = cache_bytes,
        .ne31 = (int32_t)n_token,
        .ne32 = 1,
        .ne33 = 1,
        .nb31 = 0u,
        .nb32 = 0u,
        .nb33 = 0u,
        .ne1 = (int32_t)n_query_head,
        .ne2 = (int32_t)n_token,
        .ne3 = 1,
        .scale = 1.0f / sqrtf((float)head_dim),
        .max_bias = 0.0f,
        .m0 = 0.0f,
        .m1 = 0.0f,
        .n_head_log2 = 0,
        .logit_softcap = 0.0f,
        .causal_q_offset_plus_one = (int32_t)position0 + 1,
    };
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    if (!enc) return -1;
    [enc setComputePipelineState:attn_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:query_buf offset:ds4_gpu_tensor_offset(query) atIndex:1];
    [enc setBuffer:key_buf offset:ds4_gpu_tensor_offset(key_cache) atIndex:2];
    [enc setBuffer:value_buf offset:ds4_gpu_tensor_offset(value_cache) atIndex:3];
    [enc setBuffer:g_flash_attn_pad_buffer offset:0u atIndex:4];
    [enc setBuffer:query_buf offset:ds4_gpu_tensor_offset(query) atIndex:5];
    [enc setBuffer:g_flash_attn_pad_buffer offset:0u atIndex:6];
    [enc setBuffer:g_flash_attn_blk_buffer offset:0u atIndex:7];
    [enc setBuffer:out_buf offset:ds4_gpu_tensor_offset(out) atIndex:8];
    [enc setThreadgroupMemoryLength:shared_bytes atIndex:0];
    [enc dispatchThreadgroups:MTLSizeMake(nblk1, n_query_head, 1u)
         threadsPerThreadgroup:MTLSizeMake(32u, nsg, 1u)];
    ds4_gpu_end_compute_encoder(cb, enc);

    return ds4_gpu_finish_command_buffer(cb, owned,
                                          "Qwen direct-F32 FlashAttention")
        ? 1 : -1;
}

int ds4_gpu_qwen35_gqa_prefill_select_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *query,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              position0,
        uint32_t              n_token,
        uint32_t              n_query_head,
        uint32_t              n_kv_head,
        uint32_t              head_dim,
        int                   request_reuse,
        int                  *reuse_used) {
    if (reuse_used) *reuse_used = DS4_GPU_QWEN35_GQA_PATH_LEGACY;
    /* request_reuse=0 is the strict oracle lane.  Do not even compile or
     * allocate Flash resources on that path: tests use it to establish the
     * reference output independently of optimized-pipeline availability. */
    if (!request_reuse) {
        return ds4_gpu_qwen35_gqa_prefill_tensor(
            out, query, key_cache, value_cache, position0, n_token,
            n_query_head, n_kv_head, head_dim);
    }

    const int flash_status = ds4_gpu_qwen35_gqa_prefill_flash_f32_tensor(
        out, query, key_cache, value_cache, position0, n_token,
        n_query_head, n_kv_head, head_dim);
    if (flash_status < 0) {
        /* Once a Flash command buffer has been acquired, an error is terminal.
         * Retrying an exact kernel could hide a partial output write. */
        return 0;
    }
    if (flash_status > 0) {
        static int logged[2];
        const unsigned mode = g_ssd_streaming_mode ? 1u : 0u;
        if (!logged[mode]) {
            fprintf(stderr,
                    "ds4: Qwen %s direct-F32 prefill FlashAttention enabled "
                    "(implicit causal mask, constant auxiliary memory)\n",
                    mode ? "SSD" : "resident");
            logged[mode] = 1;
        }
        if (reuse_used) {
            *reuse_used = DS4_GPU_QWEN35_GQA_PATH_FLASH_F32;
        }
        return 1;
    }
    if (n_token == 0u ||
        position0 > UINT32_MAX - n_token ||
        position0 + n_token < DS4_QWEN35_GQA_REUSE_MIN_CONTEXT) {
        return ds4_gpu_qwen35_gqa_prefill_tensor(
            out, query, key_cache, value_cache, position0, n_token,
            n_query_head, n_kv_head, head_dim);
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;

    @autoreleasepool {
        id<MTLComputePipelineState> pipeline = nil;
        NSUInteger nth = 0u, scratch_f32 = 0u;
        if (!ds4_gpu_qwen35_gqa_reuse_pipeline(
                "kernel_qwen35_gqa_prefill_reuse8_f32",
                n_query_head, n_kv_head, head_dim,
                &pipeline, &nth, &scratch_f32)) {
            return ds4_gpu_qwen35_gqa_prefill_tensor(
                out, query, key_cache, value_cache, position0, n_token,
                n_query_head, n_kv_head, head_dim);
        }
        if (!out || !query || !key_cache || !value_cache) return 0;

        const uint64_t query_row_values =
            (uint64_t)n_query_head * head_dim;
        const uint64_t cache_token_values =
            (uint64_t)n_kv_head * head_dim;
        const uint64_t n_kv = (uint64_t)position0 + n_token;
        if (query_row_values > UINT64_MAX / n_token ||
            cache_token_values > UINT64_MAX / n_kv) {
            return 0;
        }
        uint64_t query_bytes = 0u, cache_bytes = 0u;
        if (!ds4_gpu_qwen35_f32_bytes(
                query_row_values * n_token, &query_bytes) ||
            !ds4_gpu_qwen35_f32_bytes(
                cache_token_values * n_kv, &cache_bytes)) {
            return 0;
        }

        id<MTLBuffer> query_buf = ds4_gpu_tensor_buffer(query);
        id<MTLBuffer> key_buf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> value_buf = ds4_gpu_tensor_buffer(value_cache);
        id<MTLBuffer> out_buf = ds4_gpu_tensor_buffer(out);
        if (!query_buf || !key_buf || !value_buf || !out_buf ||
            ds4_gpu_tensor_bytes(query) < query_bytes ||
            ds4_gpu_tensor_bytes(key_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(out) < query_bytes) {
            fprintf(stderr,
                    "ds4: Metal Qwen GQA prefill reuse received undersized buffers\n");
            return 0;
        }

        const uint64_t head_bytes = (uint64_t)head_dim * sizeof(float);
        const uint64_t query_token_bytes =
            (uint64_t)n_query_head * head_bytes;
        const uint64_t cache_token_bytes =
            (uint64_t)n_kv_head * head_bytes;
        ds4_gpu_qwen35_gqa_prefill_args args = {
            .position0 = position0,
            .n_token = n_token,
            .n_query_head = n_query_head,
            .n_kv_head = n_kv_head,
            .head_dim = head_dim,
            .reserved = 0u,
            .query_token_stride = query_token_bytes,
            .query_head_stride = head_bytes,
            .query_dim_stride = sizeof(float),
            .key_token_stride = cache_token_bytes,
            .key_head_stride = head_bytes,
            .key_dim_stride = sizeof(float),
            .value_token_stride = cache_token_bytes,
            .value_head_stride = head_bytes,
            .value_dim_stride = sizeof(float),
            .output_token_stride = query_token_bytes,
            .output_head_stride = head_bytes,
            .output_dim_stride = sizeof(float),
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:query_buf offset:ds4_gpu_tensor_offset(query) atIndex:1];
        [enc setBuffer:key_buf offset:ds4_gpu_tensor_offset(key_cache) atIndex:2];
        [enc setBuffer:value_buf offset:ds4_gpu_tensor_offset(value_cache) atIndex:3];
        [enc setBuffer:out_buf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [enc setThreadgroupMemoryLength:
             ds4_gpu_qwen35_threadgroup_f32_bytes(scratch_f32) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(n_kv_head, n_token, 1u)
             threadsPerThreadgroup:MTLSizeMake(nth, 1u, 1u)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned,
                                           "Qwen prefill GQA K/V reuse")) {
            return 0;
        }
    }
    if (reuse_used) {
        *reuse_used = DS4_GPU_QWEN35_GQA_PATH_EXACT_REUSE;
    }
    return 1;
}

int ds4_gpu_qwen35_router_softmax_top8_batch_tensor(
        ds4_gpu_tensor       *selected,
        ds4_gpu_tensor       *selected_weight,
        const ds4_gpu_tensor *logits,
        uint32_t              n_token) {
    enum {
        QWEN35_ROUTER_EXPERTS = 256,
        QWEN35_ROUTER_SELECTED = 8,
        QWEN35_ROUTER_MAX_SIMDGROUP = 32,
        QWEN35_ROUTER_PARALLEL_SCRATCH_F32 =
            QWEN35_ROUTER_EXPERTS +
            2 * QWEN35_ROUTER_MAX_SIMDGROUP +
            2 * QWEN35_ROUTER_SELECTED + 1,
    };
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || !selected_weight || !logits || n_token == 0) return 0;

    const uint64_t logits_bytes =
        (uint64_t)n_token * QWEN35_ROUTER_EXPERTS * sizeof(float);
    const uint64_t selected_bytes =
        (uint64_t)n_token * QWEN35_ROUTER_SELECTED * sizeof(int32_t);
    const uint64_t selected_weight_bytes =
        (uint64_t)n_token * QWEN35_ROUTER_SELECTED * sizeof(float);

    @autoreleasepool {
        bool parallel_router =
            getenv("DS4_QWEN_DISABLE_PARALLEL_ROUTER") == NULL;
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline(
            parallel_router
                ? "kernel_qwen35_router_softmax_top8_f32"
                : "kernel_qwen35_router_softmax_top8_serial_f32");
        if (parallel_router &&
            (!pipeline || pipeline.threadExecutionWidth == 0u ||
             (QWEN35_ROUTER_EXPERTS + pipeline.threadExecutionWidth - 1u) /
                     pipeline.threadExecutionWidth >
                 QWEN35_ROUTER_MAX_SIMDGROUP)) {
            pipeline = ds4_gpu_get_pipeline(
                "kernel_qwen35_router_softmax_top8_serial_f32");
            parallel_router = false;
        }
        id<MTLBuffer> logits_buf = ds4_gpu_tensor_buffer(logits);
        id<MTLBuffer> selected_buf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> selected_weight_buf =
            ds4_gpu_tensor_buffer(selected_weight);
        if (!pipeline || !logits_buf || !selected_buf ||
            !selected_weight_buf ||
            pipeline.maxTotalThreadsPerThreadgroup < QWEN35_ROUTER_EXPERTS ||
            ds4_gpu_tensor_bytes(logits) < logits_bytes ||
            ds4_gpu_tensor_bytes(selected) < selected_bytes ||
            ds4_gpu_tensor_bytes(selected_weight) < selected_weight_bytes) {
            fprintf(stderr,
                    "ds4: Metal Qwen top-8 router received undersized buffers "
                    "or an unsupported threadgroup limit\n");
            return 0;
        }

        ds4_gpu_qwen35_router_top8_args args = {
            .n_token = n_token,
            .reserved = 0,
            .logits_token_stride =
                (uint64_t)QWEN35_ROUTER_EXPERTS * sizeof(float),
            .logits_stride = sizeof(float),
            .selected_token_stride =
                (uint64_t)QWEN35_ROUTER_SELECTED * sizeof(int32_t),
            .selected_stride = sizeof(int32_t),
            .selected_weight_token_stride =
                (uint64_t)QWEN35_ROUTER_SELECTED * sizeof(float),
            .selected_weight_stride = sizeof(float),
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:logits_buf
                offset:ds4_gpu_tensor_offset(logits)
               atIndex:1];
        [enc setBuffer:selected_buf
                offset:ds4_gpu_tensor_offset(selected)
               atIndex:2];
        [enc setBuffer:selected_weight_buf
                offset:ds4_gpu_tensor_offset(selected_weight)
               atIndex:3];
        [enc setThreadgroupMemoryLength:
             ds4_gpu_qwen35_threadgroup_f32_bytes(
                 parallel_router
                     ? QWEN35_ROUTER_PARALLEL_SCRATCH_F32
                     : QWEN35_ROUTER_EXPERTS)
                                  atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake(n_token, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(QWEN35_ROUTER_EXPERTS, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned,
                                           "Qwen top-8 router")) {
            return 0;
        }
    }
    return 1;
}

int ds4_gpu_qwen35_router_softmax_top8_tensor(
        ds4_gpu_tensor       *selected,
        ds4_gpu_tensor       *selected_weight,
        const ds4_gpu_tensor *logits) {
    return ds4_gpu_qwen35_router_softmax_top8_batch_tensor(
        selected, selected_weight, logits, 1u);
}

typedef struct {
    uint32_t width;
    uint32_t rows;
    uint32_t layer;
    uint32_t n_threads;
    float    scale;
} ds4_gpu_directional_steering_project_args;

int ds4_gpu_directional_steering_project_tensor(
        ds4_gpu_tensor       *x,
        const ds4_gpu_tensor *directions,
        uint32_t                layer,
        uint32_t                width,
        uint32_t                rows,
        float                   scale) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!x || !directions || width == 0 || rows == 0 || scale == 0.0f) return 0;

    @autoreleasepool {
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_pipeline("kernel_dsv4_directional_steering_project_f32");
        if (!pipeline) return 0;

        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> dbuf = ds4_gpu_tensor_buffer(directions);
        const uint64_t x_bytes = (uint64_t)width * rows * sizeof(float);
        const uint64_t dir_bytes = (uint64_t)(layer + 1u) * width * sizeof(float);
        if (!xbuf || !dbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(directions) < dir_bytes) {
            fprintf(stderr, "ds4: Metal directional steering received undersized buffers\n");
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        NSUInteger nth = pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > 256u) nth = 256u;
        while (nth > width && nth > 1u) nth >>= 1;
        if (nth == 0) nth = 1;

        ds4_gpu_directional_steering_project_args args = {
            .width = width,
            .rows = rows,
            .layer = layer,
            .n_threads = (uint32_t)nth,
            .scale = scale,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setBuffer:dbuf offset:ds4_gpu_tensor_offset(directions) atIndex:2];
        [enc setThreadgroupMemoryLength:nth * sizeof(float) atIndex:0];
        [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "directional steering")) return 0;
    }

    return 1;
}

static NSUInteger ds4_gpu_bin_threads(uint32_t width, id<MTLComputePipelineState> pipeline) {
    NSUInteger nth_max = pipeline.maxTotalThreadsPerThreadgroup;
    if (nth_max > 256u) nth_max = 256u;
    NSUInteger nth = 1u;
    while (2u * nth < (NSUInteger)width && nth < nth_max) nth *= 2u;
    return nth ? nth : 1u;
}

static int ds4_gpu_encode_unary_f32_rows(
        id<MTLCommandBuffer>        cb,
        id<MTLComputePipelineState> pipeline,
        id<MTLBuffer>               src,
        NSUInteger                  src_off,
        id<MTLBuffer>               dst,
        NSUInteger                  dst_off,
        uint32_t                    width,
        uint32_t                    rows,
        int                         c4,
        float                       min,
        float                       max) {
    if (!cb || !pipeline || !src || !dst || width == 0 || rows == 0) return 0;
    if (c4 && (width & 3u) != 0) return 0;

    ds4_gpu_unary_args args = ds4_gpu_make_unary_rows_args(width, rows, c4, 0.0f, 0.0f);
    args.min = min;
    args.max = max;

    NSUInteger nth_max = pipeline.maxTotalThreadsPerThreadgroup;
    if (nth_max > 256u) nth_max = 256u;
    NSUInteger nth = (NSUInteger)args.ne00;
    if (nth > nth_max) nth = nth_max;
    if (nth == 0) nth = 1u;
    const NSUInteger nk0 = ((NSUInteger)args.ne00 + nth - 1u) / nth;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:src offset:src_off atIndex:1];
    [enc setBuffer:dst offset:dst_off atIndex:2];
    [enc dispatchThreadgroups:MTLSizeMake(nk0 * (NSUInteger)args.ne01,
                                          (NSUInteger)args.ne02,
                                          (NSUInteger)args.ne03)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_bin_f32_rows(
        id<MTLCommandBuffer>        cb,
        id<MTLComputePipelineState> pipeline,
        const ds4_gpu_bin_args   *args,
        id<MTLBuffer>               a,
        NSUInteger                  a_off,
        id<MTLBuffer>               b,
        NSUInteger                  b_off,
        id<MTLBuffer>               out,
        NSUInteger                  out_off) {
    if (!cb || !pipeline || !args || !a || !b || !out || args->ne0 <= 0 || args->ne1 <= 0) {
        return 0;
    }

    const NSUInteger nth = ds4_gpu_bin_threads((uint32_t)args->ne0, pipeline);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBytes:args length:sizeof(*args) atIndex:0];
    [enc setBuffer:a offset:a_off atIndex:1];
    [enc setBuffer:b offset:b_off atIndex:2];
    [enc setBuffer:out offset:out_off atIndex:3];
    [enc dispatchThreadgroups:MTLSizeMake((NSUInteger)args->ne1,
                                          (NSUInteger)args->ne2,
                                          (NSUInteger)args->ne3)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static ds4_gpu_bin_args ds4_gpu_make_bin_rowwise_scalar_args(uint32_t width, uint32_t rows) {
    const uint64_t lhs_row_bytes = (uint64_t)width * sizeof(float);
    const uint64_t rhs_row_bytes = sizeof(float);
    return (ds4_gpu_bin_args) {
        .ne00 = (int32_t)width,
        .ne01 = (int32_t)rows,
        .ne02 = 1,
        .ne03 = 1,
        .nb00 = sizeof(float),
        .nb01 = lhs_row_bytes,
        .nb02 = (uint64_t)rows * lhs_row_bytes,
        .nb03 = (uint64_t)rows * lhs_row_bytes,
        .ne10 = 1,
        .ne11 = (int32_t)rows,
        .ne12 = 1,
        .ne13 = 1,
        .nb10 = sizeof(float),
        .nb11 = rhs_row_bytes,
        .nb12 = (uint64_t)rows * rhs_row_bytes,
        .nb13 = (uint64_t)rows * rhs_row_bytes,
        .ne0 = (int32_t)width,
        .ne1 = (int32_t)rows,
        .ne2 = 1,
        .ne3 = 1,
        .nb0 = sizeof(float),
        .nb1 = lhs_row_bytes,
        .nb2 = (uint64_t)rows * lhs_row_bytes,
        .nb3 = (uint64_t)rows * lhs_row_bytes,
        .offs = 0,
        .o1 = { 0 },
    };
}

static ds4_gpu_mul_mv_id_args ds4_gpu_make_mul_mv_id_args(
        uint32_t src0_cols,
        uint32_t src0_rows,
        uint32_t src0_experts,
        uint64_t src0_row_bytes,
        uint64_t src0_expert_bytes,
        uint32_t src1_expert_rows,
        uint32_t selected_experts,
        uint32_t n_tokens,
        uint32_t nr0) {
    const uint64_t src1_row_bytes = (uint64_t)src0_cols * sizeof(float);
    const uint64_t src0_blocks = src0_cols / 256u;
    const uint64_t src0_block_bytes = src0_blocks ? src0_row_bytes / src0_blocks : 1u;
    return (ds4_gpu_mul_mv_id_args) {
        .nei0 = (int32_t)selected_experts,
        .nei1 = (int32_t)n_tokens,
        .nbi1 = (uint64_t)selected_experts * sizeof(int32_t),
        .ne00 = (int32_t)src0_cols,
        .ne01 = (int32_t)src0_rows,
        .ne02 = (int32_t)src0_experts,
        .nb00 = src0_block_bytes,
        .nb01 = src0_row_bytes,
        .nb02 = src0_expert_bytes,
        .ne10 = (int32_t)src0_cols,
        .ne11 = (int32_t)src1_expert_rows,
        .ne12 = (int32_t)n_tokens,
        .ne13 = 1,
        .nb10 = sizeof(float),
        .nb11 = src1_row_bytes,
        .nb12 = (uint64_t)src1_expert_rows * src1_row_bytes,
        .ne0 = (int32_t)src0_rows,
        .ne1 = (int32_t)selected_experts,
        .nb1 = (uint64_t)src0_rows * sizeof(float),
        .nr0 = (int32_t)nr0,
    };
}

static ds4_gpu_mul_mm_id_map_args ds4_gpu_make_mul_mm_id_map_args(
        uint32_t src0_cols,
        uint32_t src0_experts,
        uint32_t src1_expert_rows,
        uint32_t selected_experts,
        uint32_t n_tokens) {
    const uint64_t src1_row_bytes = (uint64_t)src0_cols * sizeof(float);
    return (ds4_gpu_mul_mm_id_map_args) {
        .ne02 = (int32_t)src0_experts,
        .ne10 = (int32_t)src0_cols,
        .ne11 = (int32_t)src1_expert_rows,
        .nb11 = src1_row_bytes,
        .nb12 = (uint64_t)src1_expert_rows * src1_row_bytes,
        .ne21 = (int32_t)n_tokens,
        .ne20 = (int32_t)selected_experts,
        .nb21 = (uint64_t)selected_experts * sizeof(int32_t),
    };
}

static ds4_gpu_mul_mm_id_args ds4_gpu_make_mul_mm_id_args(
        uint32_t src0_cols,
        uint32_t src0_rows,
        uint32_t src0_experts,
        uint64_t src0_row_bytes,
        uint64_t src0_expert_bytes,
        uint32_t src1_expert_rows,
        uint32_t selected_experts,
        uint32_t n_tokens) {
    return ds4_gpu_make_mul_mm_id_args_src1_size(src0_cols,
                                                   src0_rows,
                                                   src0_experts,
                                                   src0_row_bytes,
                                                   src0_expert_bytes,
                                                   src1_expert_rows,
                                                   selected_experts,
                                                   n_tokens,
                                                   sizeof(float));
}

static ds4_gpu_mul_mm_id_args ds4_gpu_make_mul_mm_id_args_src1_size(
        uint32_t src0_cols,
        uint32_t src0_rows,
        uint32_t src0_experts,
        uint64_t src0_row_bytes,
        uint64_t src0_expert_bytes,
        uint32_t src1_expert_rows,
        uint32_t selected_experts,
        uint32_t n_tokens,
        uint32_t src1_elem_size) {
    const uint64_t src1_row_bytes = (uint64_t)src0_cols * src1_elem_size;
    return (ds4_gpu_mul_mm_id_args) {
        .ne00 = (int32_t)src0_cols,
        .ne02 = (int32_t)src0_experts,
        .nb01 = src0_row_bytes,
        .nb02 = src0_expert_bytes,
        .nb03 = (uint64_t)src0_experts * src0_expert_bytes,
        .ne11 = (int32_t)src1_expert_rows,
        .nb10 = src1_elem_size,
        .nb11 = src1_row_bytes,
        .nb12 = (uint64_t)src1_expert_rows * src1_row_bytes,
        .nb13 = (uint64_t)n_tokens * (uint64_t)src1_expert_rows * src1_row_bytes,
        .ne20 = (int32_t)selected_experts,
        .ne21 = (int32_t)n_tokens,
        .ne0 = (int32_t)src0_rows,
        .ne1 = (int32_t)selected_experts,
        .r2 = 1,
        .r3 = 1,
    };
}

static uint32_t ds4_gpu_routed_mv_nr0(uint32_t type) {
    switch (type) {
    case DS4_METAL_TENSOR_Q4_K:
    case DS4_METAL_TENSOR_Q6_K:
    case DS4_METAL_TENSOR_IQ4_XS:  return 2;
    case DS4_METAL_TENSOR_Q2_K:
    case DS4_METAL_TENSOR_Q5_K:
    case DS4_METAL_TENSOR_IQ2_XXS:
    case DS4_METAL_TENSOR_IQ2_XS:
    case DS4_METAL_TENSOR_IQ3_XXS: return 4;
    default:                       return 0;
    }
}

static uint32_t ds4_gpu_routed_block_bytes(uint32_t type) {
    switch (type) {
    case DS4_METAL_TENSOR_Q2_K:    return 84;
    case DS4_METAL_TENSOR_Q4_K:    return 144;
    case DS4_METAL_TENSOR_Q5_K:    return 176;
    case DS4_METAL_TENSOR_Q6_K:    return 210;
    case DS4_METAL_TENSOR_IQ2_XXS: return 66;
    case DS4_METAL_TENSOR_IQ2_XS:  return 74;
    case DS4_METAL_TENSOR_IQ3_XXS: return 98;
    case DS4_METAL_TENSOR_IQ4_XS:  return 136;
    default:                       return 0;
    }
}

static const char *ds4_gpu_metal_tensor_type_name(uint32_t type) {
    switch (type) {
    case DS4_METAL_TENSOR_IQ2_XXS: return "iq2_xxs";
    case DS4_METAL_TENSOR_IQ2_XS:  return "iq2_xs";
    case DS4_METAL_TENSOR_IQ3_XXS: return "iq3_xxs";
    case DS4_METAL_TENSOR_IQ4_XS:  return "iq4_xs";
    case DS4_METAL_TENSOR_Q2_K:    return "q2_k";
    case DS4_METAL_TENSOR_Q4_K:    return "q4_k";
    case DS4_METAL_TENSOR_Q5_K:    return "q5_k";
    case DS4_METAL_TENSOR_Q6_K:    return "q6_k";
    default:                       return "unknown";
    }
}

static const char *ds4_gpu_trim_env_value(const char *env, size_t *len_out) {
    if (len_out) *len_out = 0;
    if (!env) return NULL;

    while (isspace((unsigned char)*env)) env++;
    size_t n = strlen(env);
    while (n > 0 && isspace((unsigned char)env[n - 1])) n--;
    if (len_out) *len_out = n;
    return env;
}

static bool ds4_gpu_profile_layer_value_match(const char *env, uint32_t layer_index) {
    size_t env_len = 0;
    env = ds4_gpu_trim_env_value(env, &env_len);
    if (!env || env_len == 0) return true;
    if (ds4_gpu_env_value_eq(env, env_len, "all")) return true;

    const char *p = env;
    const char *end_env = env + env_len;
    while (p < end_env) {
        while (p < end_env && (*p == ' ' || *p == '\t' || *p == ',')) p++;
        if (p >= end_env) break;

        char *end = NULL;
        const unsigned long first = strtoul(p, &end, 10);
        if (end == p || end > end_env || first > UINT32_MAX) return false;

        unsigned long last = first;
        p = end;
        if (p < end_env && *p == '-') {
            p++;
            last = strtoul(p, &end, 10);
            if (end == p || end > end_env || last > UINT32_MAX) return false;
            p = end;
        }

        if (first <= layer_index && layer_index <= last) return true;
        while (p < end_env && (*p == ' ' || *p == '\t')) p++;
        if (p < end_env && *p != ',') return false;
    }
    return false;
}

static bool ds4_gpu_stage_profile_enabled_for_layer(const char *flag_env_name,
                                                    const char *layer_env_name,
                                                    uint32_t    layer_index) {
    size_t flag_len = 0;
    const char *flag = ds4_gpu_trim_env_value(getenv(flag_env_name), &flag_len);
    if (!flag) return false;

    size_t layer_len = 0;
    const char *layer = ds4_gpu_trim_env_value(getenv(layer_env_name), &layer_len);
    const bool has_layer_filter = layer && layer_len != 0;

    if (flag_len != 0) {
        if (ds4_gpu_env_value_eq(flag, flag_len, "0") ||
            ds4_gpu_env_value_eq(flag, flag_len, "false") ||
            ds4_gpu_env_value_eq(flag, flag_len, "no") ||
            ds4_gpu_env_value_eq(flag, flag_len, "off")) {
            return false;
        }
        if (!has_layer_filter &&
            !ds4_gpu_env_value_eq(flag, flag_len, "1") &&
            !ds4_gpu_env_value_eq(flag, flag_len, "true") &&
            !ds4_gpu_env_value_eq(flag, flag_len, "yes") &&
            !ds4_gpu_env_value_eq(flag, flag_len, "on") &&
            !ds4_gpu_env_value_eq(flag, flag_len, "all")) {
            return ds4_gpu_profile_layer_value_match(flag, layer_index);
        }
    }

    return ds4_gpu_profile_layer_value_match(layer, layer_index);
}

static NSUInteger ds4_gpu_routed_mv_smem(uint32_t type) {
    switch (type) {
    case DS4_METAL_TENSOR_IQ2_XXS:
        return 256u * sizeof(uint64_t) + 128u * sizeof(uint8_t);
    case DS4_METAL_TENSOR_IQ2_XS:
        return 512u * sizeof(uint64_t) + 128u * sizeof(uint8_t);
    case DS4_METAL_TENSOR_IQ3_XXS:
        return 256u * sizeof(uint32_t) + 128u * sizeof(uint8_t);
    case DS4_METAL_TENSOR_IQ4_XS:
        return 32u * sizeof(float);
    default:
        return 0;
    }
}

