        (output_row_tile == 4u &&
         (threadgroup_bytes == DS4_METAL_DEEPSEEK_IQ2_ROUTE_TILE_R4_SMEM ||
          threadgroup_bytes == DS4_METAL_DEEPSEEK_IQ2_ROUTE_TILE_DECODE_SMEM ||
          threadgroup_bytes == DS4_METAL_DEEPSEEK_IQ2_ROUTE_TILE_STAGED_SMEM)) ||
