            }
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        if ((use_q4_expert_address_table || use_q4_expert_table) &&
            !ds4_gpu_use_model_residency_set(cb)) {
