                ok = ds4_gpu_encode_mul_mv_group_q4_sum6(cb,
                                                          g_moe_mul_mv_group_q4_k_sum6_pipeline,
                                                          &down_args,
                                                          &group_args,
                                                          down_group_buf,
                                                          (NSUInteger)down_group_inner,
                                                          midbuf,
                                                          ds4_gpu_tensor_offset(mid),
                                                          outbuf,
                                                          ds4_gpu_tensor_offset(out),
                                                          selectedbuf,
                                                          ds4_gpu_tensor_offset(selected),
                                                          down_smem,
                                                          2);
                first_group = false;
            }
        } else if (ok && use_q4_expert_address_table) {
            ok = ds4_gpu_encode_mul_mv_addr_q4_sum6(cb,
                                                    g_moe_mul_mv_addr_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_table,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_expert_table) {
            ok = ds4_gpu_encode_mul_mv_table_q4_sum6(cb,
                                                    g_moe_mul_mv_table_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_table,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2,
                                                    q4_table_queue_residency);
        } else if (ok && use_q4_group6_experts) {
            ok = ds4_gpu_encode_mul_mv_group6_sum6(cb,
                                                    g_moe_mul_mv_group6_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group6_bufs,
                                                    down_group6_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_group8_experts) {
            ok = ds4_gpu_encode_mul_mv_group8_sum6(cb,
                                                    g_moe_mul_mv_group8_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group8_bufs,
                                                    down_group8_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_group24_experts) {
            ok = ds4_gpu_encode_mul_mv_group24_sum6(cb,
                                                    g_moe_mul_mv_group24_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group24_bufs,
                                                    down_group24_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_qwen_iq_selected_slots) {
            id<MTLComputePipelineState> slots_pipeline =
                ds4_gpu_routed_slots6_pipeline(down_type);
            ok = slots_pipeline != nil &&
                 ds4_gpu_encode_mul_mv_slots6(
                     cb,
                     slots_pipeline,
                     &down_args,
                     down_slot_bufs,
                     down_slot_offsets,
                     midbuf,
                     ds4_gpu_tensor_offset(mid),
                     down_dst,
                     down_dst_off,
                     down_smem,
                     2);
        } else if (ok && (use_q4_gather_slots || use_selected_slots)) {
            if (use_stream_expert_addr_table) {
                if (mlx_affine_store) {
                    id<MTLComputePipelineState> address_sum_pipeline =
                        ds4_gpu_get_moe_mv_pipeline(
                            "kernel_mul_mv_addr_mlx_affine4_64_sum8_f32",
                            2);
                    /* Qwen executes top-8 as two four-route halves.  The
                     * IQ2 sum6 encoder intentionally rejects that geometry;
                     * keep affine dispatch on the 1..8-route wrapper. */
                    ok = address_sum_pipeline &&
                        ds4_gpu_encode_mul_mv_addr_q4_sum8_stream(
                            cb,
                            address_sum_pipeline,
                            &down_args,
                            stream_slot_entries,
                            n_expert,
                            stream_down_addr_buf,
                            midbuf,
                            ds4_gpu_tensor_offset(mid),
                            outbuf,
                            ds4_gpu_tensor_offset(out),
                            selected_exec_buf,
                            selected_exec_off,
                            down_smem,
                            2);
                } else if (down_type == DS4_METAL_TENSOR_IQ2_XXS) {
                    ok = ds4_gpu_encode_mul_mv_addr_iq2(cb,
                                                        g_moe_mul_mv_addr_iq2_xxs_pipeline,
                                                        &down_args,
                                                        stream_slot_entries,
                                                        n_expert,
                                                        stream_down_addr_buf,
                                                        midbuf,
                                                        ds4_gpu_tensor_offset(mid),
                                                        down_dst,
                                                        down_dst_off,
                                                        selected_exec_buf,
                                                        selected_exec_off,
                                                        down_smem,
                                                        2,
                                                        false);
                } else if (use_stream_expert_masked_addr_table) {
                    ds4_gpu_stream_expert_split_args split_args = {
                        .active_mask = 0x3fu,
                        .accumulate = 0u,
                    };
                    ok = ds4_gpu_encode_mul_mv_addr_q2_sum6_masked(cb,
                                                                   g_moe_mul_mv_addr_q2_k_sum6_masked_pipeline,
                                                                   &down_args,
                                                                   &split_args,
                                                                   stream_slot_entries,
                                                                   stream_down_addr_buf,
                                                                   midbuf,
                                                                   ds4_gpu_tensor_offset(mid),
                                                                   outbuf,
                                                                   ds4_gpu_tensor_offset(out),
                                                                   selected_exec_buf,
                                                                   selected_exec_off,
                                                                   down_smem,
                                                                   2);
                } else {
                    ok = ds4_gpu_encode_mul_mv_addr_q2_sum6(cb,
                                                             g_moe_mul_mv_addr_q2_k_sum6_pipeline,
                                                             &down_args,
                                                             stream_slot_entries,
                                                             n_expert,
                                                             stream_down_addr_buf,
                                                             midbuf,
                                                             ds4_gpu_tensor_offset(mid),
                                                             outbuf,
                                                             ds4_gpu_tensor_offset(out),
                                                             selected_exec_buf,
                                                             selected_exec_off,
                                                             down_smem,
                                                             2);
                }
            } else {
                ok = (!use_stream_expert_cache ||
                      ds4_gpu_stream_expert_cache_mark_entries_inflight(
                              stream_slot_entries,
                              n_expert,
                              0)) &&
                     ds4_gpu_encode_mul_mv_slots6_sum6(cb,
                                                       slots_sum6_pipeline,
                                                       &down_args,
                                                       down_slot_bufs,
                                                       down_slot_offsets,
                                                       midbuf,
                                                       ds4_gpu_tensor_offset(mid),
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       down_smem,
                                                       2);
            }
        } else if (ok && direct_down_sum) {
            ok = ds4_gpu_encode_mul_mv_id_sum6(cb,
                                                 down_sum6_pipeline,
                                                 &down_args,
                                                 down_buf,
                                                 (NSUInteger)down_inner,
                                                 midbuf,
                                                 ds4_gpu_tensor_offset(mid),
                                                 outbuf,
                                                 ds4_gpu_tensor_offset(out),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 down_smem,
                                                 2);
        } else if (ok) {
            ok = ds4_gpu_encode_mul_mv_id(cb,
                                                 down_mv_pipeline,
                                                 &down_args,
                                                 down_buf,
                                                 (NSUInteger)down_inner,
                                                 midbuf,
                                                 ds4_gpu_tensor_offset(mid),
                                                 down_dst,
                                                 down_dst_off,
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 down_smem,
                                                 2,
                                                 false);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("down");
        if (ok && n_expert > 1 && !direct_down_sum &&
            !selected_slots_down_sum && !stream_expert_split_completed) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       down_dst,
                                                       down_dst_off,
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       n_tokens);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("sum");
        if (!ok) return 0;

        if (!ds4_gpu_finish_command_buffer(cb, owned, "routed tensor MoE")) return 0;
        if (q4_grouped_boundary || q4_exact_boundary || q4_table_boundary) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                return 0;
            }
        }
#undef DS4_METAL_PROFILE_MOE_ONE_STAGE
    }

    return 1;
}

int ds4_gpu_routed_moe_one_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                layer_index,
        bool                    force_resident) {
    return ds4_gpu_routed_moe_one_tensor_impl(out,
                                               gate,
                                               up,
                                               mid,
                                               experts,
                                               model_map,
                                               model_size,
                                               gate_offset,
                                               up_offset,
                                               down_offset,
                                               gate_type,
                                               down_type,
                                               gate_expert_bytes,
                                               gate_row_bytes,
                                               down_expert_bytes,
                                               down_row_bytes,
                                               expert_in_dim,
                                               expert_mid_dim,
                                               out_dim,
                                               selected,
                                               weights,
                                               n_total_expert,
                                               n_expert,
                                               clamp,
                                               x,
                                               layer_index,
                                               force_resident,
                                               true,
                                               NULL);
}

int ds4_gpu_qwen35_routed_moe_top8_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *partial0,
        ds4_gpu_tensor       *partial1,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected_top8,
        const ds4_gpu_tensor *weights_top8,
        const ds4_gpu_tensor *selected_half0,
        const ds4_gpu_tensor *selected_half1,
        const ds4_gpu_tensor *weights_half0,
        const ds4_gpu_tensor *weights_half1,
        uint32_t                n_total_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                layer_index,
        bool                    trusted_gpu_route) {
    const uint32_t n_half = DS4_METAL_STREAM_SELECTED_MAX / 2u;
    const uint64_t half_selected_bytes =
        (uint64_t)n_half * sizeof(int32_t);
    const uint64_t half_weight_bytes =
        (uint64_t)n_half * sizeof(float);
    const uint64_t top8_selected_bytes =
        (uint64_t)DS4_METAL_STREAM_SELECTED_MAX * sizeof(int32_t);
    const uint64_t top8_weight_bytes =
        (uint64_t)DS4_METAL_STREAM_SELECTED_MAX * sizeof(float);
    const uint64_t x_bytes = (uint64_t)expert_in_dim * sizeof(float);
    const uint64_t half_mid_bytes =
        (uint64_t)n_half * expert_mid_dim * sizeof(float);
    const uint64_t half_expert_out_bytes =
        (uint64_t)n_half * out_dim * sizeof(float);
    const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);

    /* Keep every reject below free of route/cache/output mutations. In
     * particular, validate all eight IDs before launching early SSD I/O. */
    if (!out || !partial0 || !partial1 || !gate || !up || !mid || !experts ||
        !model_map || !selected_top8 || !weights_top8 ||
        !selected_half0 || !selected_half1 ||
        !weights_half0 || !weights_half1 || !x ||
        out == partial0 || out == partial1 || partial0 == partial1 ||
        ds4_gpu_routed_mv_nr0(gate_type) == 0 ||
        ds4_gpu_routed_mv_nr0(down_type) == 0 ||
        gate_expert_bytes == 0 || gate_row_bytes == 0 ||
        down_expert_bytes == 0 || down_row_bytes == 0 ||
        expert_in_dim == 0 || expert_mid_dim == 0 || out_dim == 0 ||
        (expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0 ||
        n_total_expert < 128u ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        layer_index >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        (uint64_t)n_total_expert > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)n_total_expert > UINT64_MAX / down_expert_bytes ||
        ds4_gpu_tensor_bytes(selected_top8) < top8_selected_bytes ||
        ds4_gpu_tensor_bytes(weights_top8) < top8_weight_bytes ||
        ds4_gpu_tensor_bytes(selected_half0) < half_selected_bytes ||
        ds4_gpu_tensor_bytes(selected_half1) < half_selected_bytes ||
        ds4_gpu_tensor_bytes(weights_half0) < half_weight_bytes ||
        ds4_gpu_tensor_bytes(weights_half1) < half_weight_bytes ||
        ds4_gpu_tensor_bytes(x) < x_bytes ||
        ds4_gpu_tensor_bytes(gate) < half_mid_bytes ||
        ds4_gpu_tensor_bytes(up) < half_mid_bytes ||
        ds4_gpu_tensor_bytes(mid) < half_mid_bytes ||
        ds4_gpu_tensor_bytes(experts) < half_expert_out_bytes ||
        ds4_gpu_tensor_bytes(partial0) < out_bytes ||
        ds4_gpu_tensor_bytes(partial1) < out_bytes ||
        ds4_gpu_tensor_bytes(out) < out_bytes) {
        return 0;
    }

    id<MTLBuffer> selected_parent_buf =
        ds4_gpu_tensor_buffer(selected_top8);
    id<MTLBuffer> weights_parent_buf =
        ds4_gpu_tensor_buffer(weights_top8);
    const NSUInteger selected_parent_off =
        ds4_gpu_tensor_offset(selected_top8);
    const NSUInteger weights_parent_off =
        ds4_gpu_tensor_offset(weights_top8);
    if (!selected_parent_buf || !weights_parent_buf ||
        ds4_gpu_tensor_buffer(selected_half0) != selected_parent_buf ||
        ds4_gpu_tensor_buffer(selected_half1) != selected_parent_buf ||
        ds4_gpu_tensor_buffer(weights_half0) != weights_parent_buf ||
        ds4_gpu_tensor_buffer(weights_half1) != weights_parent_buf ||
        selected_parent_off > NSUIntegerMax - half_selected_bytes ||
        weights_parent_off > NSUIntegerMax - half_weight_bytes ||
        ds4_gpu_tensor_offset(selected_half0) != selected_parent_off ||
        ds4_gpu_tensor_offset(selected_half1) !=
            selected_parent_off + half_selected_bytes ||
        ds4_gpu_tensor_offset(weights_half0) != weights_parent_off ||
        ds4_gpu_tensor_offset(weights_half1) !=
            weights_parent_off + half_weight_bytes) {
        return 0;
    }

    const uint64_t gate_tensor_bytes =
        (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_tensor_bytes =
        (uint64_t)n_total_expert * down_expert_bytes;
    uint32_t store_storage = DS4_EXPERT_STORE_STORAGE_GGML;
    uint64_t store_component_bytes[3] = {
        gate_expert_bytes, gate_expert_bytes, down_expert_bytes,
    };
    uint64_t store_record_bytes =
        gate_expert_bytes * 2u + down_expert_bytes;
    const bool have_store_codec =
        ds4_gpu_qwen35_expert_pack_layer_codec(
            layer_index, &store_storage, store_component_bytes,
            &store_record_bytes) != 0;
    const bool mlx_affine_store =
        have_store_codec &&
        store_storage == DS4_EXPERT_STORE_STORAGE_MLX_AFFINE4;
    const uint32_t gate_block_bytes =
        ds4_gpu_routed_block_bytes(gate_type);
    const uint32_t down_block_bytes =
        ds4_gpu_routed_block_bytes(down_type);
    const uint64_t expected_gate_row_bytes =
        ((uint64_t)expert_in_dim / 256ull) * gate_block_bytes;
    const uint64_t expected_down_row_bytes =
        ((uint64_t)expert_mid_dim / 256ull) * down_block_bytes;
    const bool routed_extent_valid =
        gate_block_bytes != 0 && down_block_bytes != 0 &&
        gate_row_bytes == expected_gate_row_bytes &&
        down_row_bytes == expected_down_row_bytes &&
        (uint64_t)expert_mid_dim <= UINT64_MAX / gate_row_bytes &&
        (uint64_t)out_dim <= UINT64_MAX / down_row_bytes &&
        gate_expert_bytes ==
            (uint64_t)expert_mid_dim * gate_row_bytes &&
        down_expert_bytes == (uint64_t)out_dim * down_row_bytes;
    if (!routed_extent_valid ||
        gate_offset > model_size ||
        up_offset > model_size ||
        down_offset > model_size ||
        gate_tensor_bytes > model_size - gate_offset ||
        gate_tensor_bytes > model_size - up_offset ||
        down_tensor_bytes > model_size - down_offset) {
        return 0;
    }

    if (!g_initialized && !ds4_gpu_init()) return 0;
    const bool resident_path_ready = mlx_affine_store
        ? (ds4_gpu_get_moe_mv_pipeline(
               "kernel_mul_mv_id_mlx_affine4_64_f32", 2) != nil &&
           ds4_gpu_get_moe_mv_pipeline(
               "kernel_mul_mv_id_mlx_affine4_64_pair_swiglu_f32", 2) != nil)
        : (ds4_gpu_routed_mv_pipeline(gate_type) != nil &&
           ds4_gpu_routed_mv_pipeline(down_type) != nil);
    const bool qwen_iq_store =
        (gate_type == DS4_METAL_TENSOR_IQ2_XS &&
         (down_type == DS4_METAL_TENSOR_IQ3_XXS ||
          down_type == DS4_METAL_TENSOR_IQ4_XS)) ||
        (gate_type == DS4_METAL_TENSOR_IQ3_XXS &&
         down_type == DS4_METAL_TENSOR_IQ4_XS);
    const bool streaming_path_ready =
        !g_ssd_streaming_mode ||
        (mlx_affine_store
             ? (ds4_gpu_get_moe_mv_pipeline(
                    "kernel_mul_mv_addr_mlx_affine4_64_pair_swiglu_f32",
                    2) != nil &&
                ds4_gpu_get_moe_mv_pipeline(
                    "kernel_mul_mv_addr_mlx_affine4_64_sum8_f32",
                    2) != nil)
             : (qwen_iq_store &&
                ds4_gpu_routed_slots6_pipeline(gate_type) != nil &&
                ds4_gpu_routed_slots6_pipeline(down_type) != nil));
    if (g_quality_mode ||
        getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL ||
        getenv("DS4_METAL_DISABLE_ROUTED_PAIR_SWIGLU_FUSION") != NULL ||
        !resident_path_ready || !streaming_path_ready) {
        fprintf(stderr,
                "ds4: Metal Qwen top-8 requires the validated %s/%s %s path\n",
                ds4_gpu_metal_tensor_type_name(gate_type),
                ds4_gpu_metal_tensor_type_name(down_type),
                g_ssd_streaming_mode ? "SSD selected-slot" : "resident tensor");
        return 0;
    }

    const uint32_t cache_budget =
        ds4_gpu_stream_expert_cache_configured_budget();
    const uint32_t locked_cache_budget =
        ds4_gpu_stream_expert_cache_locked_budget();
    if (g_stream_expert_cache_required_floor != 0 &&
        locked_cache_budget < g_stream_expert_cache_required_floor) {
        fprintf(stderr,
                "ds4: Metal Qwen top-8 configured cache %u is below the "
                "required %u-expert floor\n",
                locked_cache_budget,
                g_stream_expert_cache_required_floor);
        return 0;
    }

    /* The production resident graph feeds this call directly from the GPU
     * top-8 router. The id-based routed kernels consume that tensor
     * themselves, so a host readback would only validate an invariant already
     * guaranteed by the router and would split the token into one command
     * buffer per layer. Preserve host readback for SSD cache selection
     * and for explicit trace/replay/hotlist observability. */
    const bool resident_gpu_route =
        !g_ssd_streaming_mode &&
        trusted_gpu_route &&
        g_batch_cb != nil &&
        getenv("DS4_MOE_RECORD_SELECTED_IDS") == NULL &&
        getenv("DS4_MOE_REPLAY_SELECTED_IDS") == NULL &&
        getenv("DS4_MOE_RECORD_SELECTED_HOTLIST") == NULL;
    if (resident_gpu_route) {
        if (g_qwen35_resident_gpu_route_calls != UINT64_MAX) {
            g_qwen35_resident_gpu_route_calls++;
        }
        return ds4_gpu_routed_moe_one_tensor_impl(
                   out,
                   gate,
                   up,
                   mid,
                   experts,
                   model_map,
                   model_size,
                   gate_offset,
                   up_offset,
                   down_offset,
                   gate_type,
                   down_type,
                   gate_expert_bytes,
                   gate_row_bytes,
                   down_expert_bytes,
                   down_row_bytes,
                   expert_in_dim,
                   expert_mid_dim,
                   out_dim,
                   selected_top8,
                   weights_top8,
                   n_total_expert,
                   DS4_METAL_STREAM_SELECTED_MAX,
                   clamp,
                   x,
                   layer_index,
                   true,
                   false,
                   NULL);
    }

    const ds4_gpu_stream_expert_table stream_table = {
        .model_map = model_map,
        .model_size = model_size,
        .layer = layer_index,
        .n_total_expert = n_total_expert,
        .gate_offset = gate_offset,
        .up_offset = up_offset,
        .down_offset = down_offset,
        .gate_expert_bytes = gate_expert_bytes,
        .down_expert_bytes = down_expert_bytes,
    };
    const bool qwen_overlap_generation =
        g_ssd_streaming_mode &&
        ds4_gpu_qwen35_stream_pending_matches(
            &stream_table,
            selected_top8,
            1u,
            DS4_METAL_STREAM_SELECTED_MAX);
    if (g_ssd_streaming_mode &&
        g_qwen35_stream_pending.state != DS4_QWEN35_STREAM_IO_EMPTY &&
        !qwen_overlap_generation) {
        /* Never let the generic scalar loader race a stale generation that
         * still owns cache staging and the single bounded pread queue. */
        return 0;
    }
    uint8_t prefetched[DS4_METAL_QWEN35_STREAM_MAX_EXPERT] = { 0 };
    int32_t selected_ids[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    int32_t *overlap_selected_ids = NULL;
    if (qwen_overlap_generation &&
        ds4_gpu_qwen35_stream_consume(
            &stream_table,
            selected_top8,
            1u,
            DS4_METAL_STREAM_SELECTED_MAX,
            prefetched,
            DS4_METAL_QWEN35_STREAM_MAX_EXPERT,
            selected_ids,
            sizeof(selected_ids) / sizeof(selected_ids[0]),
            &overlap_selected_ids) <= 0) {
        return 0;
    }
    if (qwen_overlap_generation &&
        overlap_selected_ids != selected_ids) {
        return 0;
    }

    const bool selected_timing =
        ds4_gpu_stream_expert_timing_summary_enabled();
    const double selected_t0 = selected_timing ? ds4_gpu_now_ms() : 0.0;
    const int replayed = ds4_gpu_moe_selected_trace_replay(
            selected_ids,
            DS4_METAL_STREAM_SELECTED_MAX);
    if (replayed < 0) return 0;
    if (replayed == 0) {
        const int had_batch = g_batch_cb != nil;
        if (!qwen_overlap_generation && had_batch &&
            ds4_gpu_end_commands() == 0) {
            return 0;
        }
        if (!g_ssd_streaming_mode &&
            g_qwen35_resident_host_readbacks != UINT64_MAX) {
            g_qwen35_resident_host_readbacks++;
        }
        const int read_ok = qwen_overlap_generation ||
            ds4_gpu_tensor_read(selected_top8,
                                0,
                                selected_ids,
                                top8_selected_bytes);
        const int restart_ok = qwen_overlap_generation ||
            !had_batch || ds4_gpu_begin_commands() != 0;
        if (!read_ok || !restart_ok) return 0;
    }
    const double selected_read_ms = selected_timing ?
        ds4_gpu_now_ms() - selected_t0 : 0.0;
    const double selected_bind_t0 = selected_timing ?
        ds4_gpu_now_ms() : 0.0;

    uint64_t gate_abs_offsets[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    uint64_t up_abs_offsets[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    uint64_t down_abs_offsets[DS4_METAL_STREAM_SELECTED_MAX] = { 0 };
    uint32_t unique_selected = 0;
    for (uint32_t i = 0; i < DS4_METAL_STREAM_SELECTED_MAX; i++) {
        const int32_t selected_id = selected_ids[i];
        if (selected_id < 0 || (uint32_t)selected_id >= n_total_expert) {
            fprintf(stderr,
                    "ds4: Metal Qwen top-8 expert id %d is outside 0..%u\n",
                    selected_id,
                    n_total_expert);
            return 0;
        }
        bool duplicate = false;
        for (uint32_t prev = 0; prev < i; prev++) {
            if (selected_ids[prev] == selected_id) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) unique_selected++;

        const uint64_t expert_id = (uint64_t)(uint32_t)selected_id;
        const uint64_t gate_rel = expert_id * gate_expert_bytes;
        const uint64_t down_rel = expert_id * down_expert_bytes;
        if (gate_rel > UINT64_MAX - gate_offset ||
            gate_rel > UINT64_MAX - up_offset ||
            down_rel > UINT64_MAX - down_offset) {
            return 0;
        }
        gate_abs_offsets[i] = gate_offset + gate_rel;
        up_abs_offsets[i] = up_offset + gate_rel;
        down_abs_offsets[i] = down_offset + down_rel;
    }

    if (replayed != 0 && !g_ssd_streaming_mode) {
        /* The resident executor consumes the GPU selected-ID tensor directly.
         * Validate the complete replay first, then update the route tensor so
         * a malformed trace cannot mutate caller-owned input on failure. */
        const int had_batch = g_batch_cb != nil;
        if (had_batch && ds4_gpu_end_commands() == 0) return 0;
        const int write_ok = ds4_gpu_tensor_write(
            (ds4_gpu_tensor *)selected_top8,
            0,
            selected_ids,
            top8_selected_bytes);
        const int restart_ok = !had_batch || ds4_gpu_begin_commands() != 0;
        if (!write_ok || !restart_ok) return 0;
    }

    if (!g_ssd_streaming_mode) {
        int ok = ds4_gpu_moe_selected_trace_record(
                     selected_ids,
                     DS4_METAL_STREAM_SELECTED_MAX) &&
                 ds4_gpu_moe_selected_hotlist_record(
                     layer_index,
                     selected_ids,
                     DS4_METAL_STREAM_SELECTED_MAX,
                     n_total_expert);
        if (ok) {
            ok = ds4_gpu_routed_moe_one_tensor_impl(
                     partial0,
                     gate,
                     up,
                     mid,
                     experts,
                     model_map,
                     model_size,
                     gate_offset,
                     up_offset,
                     down_offset,
                     gate_type,
                     down_type,
                     gate_expert_bytes,
                     gate_row_bytes,
                     down_expert_bytes,
                     down_row_bytes,
                     expert_in_dim,
                     expert_mid_dim,
                     out_dim,
                     selected_half0,
                     weights_half0,
                     n_total_expert,
                     n_half,
                     clamp,
                     x,
                     layer_index,
                     true,
                     false,
                     NULL);
        }
        if (ok) {
            ok = ds4_gpu_routed_moe_one_tensor_impl(
                     partial1,
                     gate,
                     up,
                     mid,
                     experts,
                     model_map,
                     model_size,
                     gate_offset,
                     up_offset,
                     down_offset,
                     gate_type,
                     down_type,
                     gate_expert_bytes,
                     gate_row_bytes,
                     down_expert_bytes,
                     down_row_bytes,
                     expert_in_dim,
                     expert_mid_dim,
                     out_dim,
                     selected_half1,
                     weights_half1,
                     n_total_expert,
                     n_half,
                     clamp,
                     x,
                     layer_index,
                     true,
                     false,
                     NULL);
        }
        if (ok) ok = ds4_gpu_add_tensor(out, partial0, partial1, out_dim);
        return ok;
    }

    if (cache_budget < unique_selected ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes)) {
        fprintf(stderr,
                "ds4: Metal Qwen top-8 needs cache capacity for %u unique experts\n",
                unique_selected);
        return 0;
    }

    ds4_gpu_stream_expert_cache_entry
        *entries[DS4_METAL_STREAM_SELECTED_MAX] = { NULL };
    uint32_t preexisting_mask = 0;
    for (uint32_t i = 0; i < DS4_METAL_STREAM_SELECTED_MAX; i++) {
        ds4_gpu_stream_expert_cache_entry *entry =
            &g_stream_expert_cache[layer_index][(uint32_t)selected_ids[i]];
        if (ds4_gpu_stream_expert_cache_entry_matches(
                entry,
                model_map,
                model_size,
                gate_abs_offsets[i],
                up_abs_offsets[i],
                down_abs_offsets[i],
                gate_expert_bytes,
                down_expert_bytes) &&
            !prefetched[(uint32_t)selected_ids[i]]) {
            preexisting_mask |= 1u << i;
        }
    }
    uint32_t missing_mask = 0;
    int ok = qwen_overlap_generation ||
        ds4_gpu_stream_expert_cache_begin_selected_load(
            &stream_table,
            selected_ids,
            DS4_METAL_STREAM_SELECTED_MAX);
    bool prefetched_seen[DS4_METAL_QWEN35_STREAM_MAX_EXPERT] = { false };
    for (uint32_t i = 0; ok && i < DS4_METAL_STREAM_SELECTED_MAX; i++) {
        const uint32_t expert = (uint32_t)selected_ids[i];
        if (prefetched[expert]) {
            entries[i] = &g_stream_expert_cache[layer_index][expert];
            if (!ds4_gpu_stream_expert_cache_entry_matches(
                    entries[i],
                    model_map,
                    model_size,
                    gate_abs_offsets[i],
                    up_abs_offsets[i],
                    down_abs_offsets[i],
                    gate_expert_bytes,
                    down_expert_bytes)) {
                entries[i] = NULL;
            } else if (prefetched_seen[expert]) {
                /* A duplicate top-8 slot shares the installed miss.  Match
                 * synchronous accounting: one miss and another logical use,
                 * not a fabricated cache hit. */
                entries[i]->use_count++;
            }
            prefetched_seen[expert] = true;
        } else if ((preexisting_mask & (1u << i)) != 0) {
            entries[i] = ds4_gpu_stream_expert_cache_peek(
                    model_map,
                    model_size,
                    layer_index,
                    expert,
                    n_total_expert,
                    DS4_METAL_STREAM_SELECTED_MAX,
                    gate_abs_offsets[i],
                    up_abs_offsets[i],
                    down_abs_offsets[i],
                    gate_expert_bytes,
                    down_expert_bytes);
        } else {
            /* A one-thread/disabled pread pool completes early-load inline.
             * Bind that freshly installed miss without reclassifying it as a
             * hit; the async path remains absent here and is finished below. */
            ds4_gpu_stream_expert_cache_entry *entry =
                &g_stream_expert_cache[layer_index]
                                      [(uint32_t)selected_ids[i]];
            if (ds4_gpu_stream_expert_cache_entry_matches(
                    entry,
                    model_map,
                    model_size,
                    gate_abs_offsets[i],
                    up_abs_offsets[i],
                    down_abs_offsets[i],
                    gate_expert_bytes,
                    down_expert_bytes)) {
                entries[i] = entry;
            }
        }
        if (!entries[i]) missing_mask |= 1u << i;
    }
    if (ok && missing_mask != 0) {
        ok = ds4_gpu_stream_expert_cache_load_selected_missing(
                model_map,
                model_size,
                layer_index,
                selected_ids,
                n_total_expert,
                DS4_METAL_STREAM_SELECTED_MAX,
                selected_ids,
                DS4_METAL_STREAM_SELECTED_MAX,
                gate_abs_offsets,
                up_abs_offsets,
                down_abs_offsets,
                gate_expert_bytes,
                down_expert_bytes,
                missing_mask,
                entries);
    }
    for (uint32_t i = 0; ok && i < DS4_METAL_STREAM_SELECTED_MAX; i++) {
        ok = ds4_gpu_stream_expert_cache_entry_matches(
                entries[i],
                model_map,
                model_size,
                gate_abs_offsets[i],
                up_abs_offsets[i],
                down_abs_offsets[i],
                gate_expert_bytes,
                down_expert_bytes);
    }

    if (ok) {
        ds4_gpu_stream_expert_cache_note_token(layer_index);
        ds4_gpu_stream_expert_cache_note_selected_hotness(
                layer_index,
                selected_ids,
                DS4_METAL_STREAM_SELECTED_MAX);
        ok = ds4_gpu_moe_selected_trace_record(
                    selected_ids,
                    DS4_METAL_STREAM_SELECTED_MAX) &&
             ds4_gpu_moe_selected_hotlist_record(
                    layer_index,
                    selected_ids,
                    DS4_METAL_STREAM_SELECTED_MAX,
                    n_total_expert);
    }
    if (ok) {
        ds4_gpu_stream_expert_cache_prune_layer(
                layer_index,
                n_total_expert,
                DS4_METAL_STREAM_SELECTED_MAX,
                selected_ids,
                DS4_METAL_STREAM_SELECTED_MAX);
        ds4_gpu_stream_expert_cache_prune_global(
                layer_index,
                selected_ids,
                DS4_METAL_STREAM_SELECTED_MAX);
    }
    if (ok && selected_timing) {
        ds4_gpu_stream_expert_timing_note_selected(
                0.0,
                selected_read_ms,
                ds4_gpu_now_ms() - selected_bind_t0);
    }

    ds4_gpu_qwen_selected_plan plans[2] = {
        { .n_selected = n_half },
        { .n_selected = n_half },
    };
    for (uint32_t half = 0; half < 2; half++) {
        for (uint32_t i = 0; i < n_half; i++) {
            const uint32_t slot = half * n_half + i;
            plans[half].selected_ids[i] = selected_ids[slot];
            plans[half].entries[i] = entries[slot];
        }
    }

    if (ok) {
        ok = ds4_gpu_routed_moe_one_tensor_impl(partial0,
                                                 gate,
                                                 up,
                                                 mid,
                                                 experts,
                                                 model_map,
                                                 model_size,
                                                 gate_offset,
                                                 up_offset,
                                                 down_offset,
                                                 gate_type,
                                                 down_type,
                                                 gate_expert_bytes,
                                                 gate_row_bytes,
                                                 down_expert_bytes,
                                                 down_row_bytes,
                                                 expert_in_dim,
                                                 expert_mid_dim,
                                                 out_dim,
                                                 selected_half0,
                                                 weights_half0,
                                                 n_total_expert,
                                                 n_half,
                                                 clamp,
                                                 x,
                                                 layer_index,
                                                 false,
                                                 false,
                                                 &plans[0]);
    }
    if (ok) {
        ok = ds4_gpu_routed_moe_one_tensor_impl(partial1,
                                                 gate,
                                                 up,
                                                 mid,
                                                 experts,
                                                 model_map,
                                                 model_size,
                                                 gate_offset,
                                                 up_offset,
                                                 down_offset,
                                                 gate_type,
                                                 down_type,
                                                 gate_expert_bytes,
                                                 gate_row_bytes,
                                                 down_expert_bytes,
                                                 down_row_bytes,
                                                 expert_in_dim,
                                                 expert_mid_dim,
                                                 out_dim,
                                                 selected_half1,
                                                 weights_half1,
                                                 n_total_expert,
                                                 n_half,
                                                 clamp,
                                                 x,
                                                 layer_index,
                                                 false,
                                                 false,
                                                 &plans[1]);
    }
    if (ok) ok = ds4_gpu_add_tensor(out, partial0, partial1, out_dim);

    return ok;
}

void ds4_gpu_internal_qwen35_resident_route_stats_reset(void) {
    g_qwen35_resident_gpu_route_calls = 0;
    g_qwen35_resident_host_readbacks = 0;
}

void ds4_gpu_internal_qwen35_resident_route_stats_add(uint64_t calls) {
    if (UINT64_MAX - g_qwen35_resident_gpu_route_calls < calls) {
        g_qwen35_resident_gpu_route_calls = UINT64_MAX;
    } else {
        g_qwen35_resident_gpu_route_calls += calls;
    }
}

uint64_t ds4_gpu_internal_qwen35_resident_gpu_route_calls(void) {
    return g_qwen35_resident_gpu_route_calls;
}

uint64_t ds4_gpu_internal_qwen35_resident_host_readbacks(void) {
    return g_qwen35_resident_host_readbacks;
}

void ds4_gpu_internal_qwen35_gdn128_stats_reset(void) {
    g_qwen35_gdn128_parallel_calls = 0;
}

uint64_t ds4_gpu_internal_qwen35_gdn128_parallel_calls(void) {
    return g_qwen35_gdn128_parallel_calls;
}

static int ds4_gpu_internal_qwen35_expert_pack_pwrite_all(
        int fd,
        const uint8_t *src,
        uint64_t len,
        uint64_t offset) {
    if (fd < 0 || !src || len == 0 ||
        offset > (uint64_t)LLONG_MAX ||
        len > (uint64_t)LLONG_MAX - offset) {
        return 0;
    }
    uint64_t pos = 0;
    while (pos < len) {
        const uint64_t rem = len - pos;
        const size_t want = rem > (uint64_t)SSIZE_MAX ?
            (size_t)SSIZE_MAX : (size_t)rem;
        ssize_t nwritten;
        do {
            nwritten = pwrite(fd,
                              src + pos,
                              want,
                              (off_t)(offset + pos));
        } while (nwritten < 0 && errno == EINTR);
        if (nwritten <= 0) return 0;
        pos += (uint64_t)nwritten;
    }
    return 1;
}

#ifdef DS4_TEST_HOOKS
static uint32_t ds4_gpu_bf16_round_f32_oracle(uint32_t bits) {
    const uint32_t magnitude = bits & UINT32_C(0x7fffffff);
    if (magnitude >= UINT32_C(0x7f800000)) {
        if (magnitude == UINT32_C(0x7f800000)) return bits;
        return (bits & UINT32_C(0xffff0000)) | UINT32_C(0x00400000);
    }
    return (bits + UINT32_C(0x00007fff) + ((bits >> 16u) & 1u)) &
           UINT32_C(0xffff0000);
}

int ds4_gpu_internal_bf16_round_f32_test(void) {
    static const struct {
        uint32_t input;
        uint32_t expected;
    } cases[] = {
        {UINT32_C(0x00000000), UINT32_C(0x00000000)}, // +0
        {UINT32_C(0x80000000), UINT32_C(0x80000000)}, // -0
        {UINT32_C(0x3f808000), UINT32_C(0x3f800000)}, // even tie down
        {UINT32_C(0x3f818000), UINT32_C(0x3f820000)}, // odd tie up
        {UINT32_C(0xbf808000), UINT32_C(0xbf800000)}, // negative even tie
        {UINT32_C(0xbf818000), UINT32_C(0xbf820000)}, // negative odd tie
        {UINT32_C(0x00008000), UINT32_C(0x00000000)}, // subnormal even tie
        {UINT32_C(0x00008001), UINT32_C(0x00010000)}, // above subnormal tie
        {UINT32_C(0x007fffff), UINT32_C(0x00800000)}, // F32 subnormal edge
        {UINT32_C(0x00800000), UINT32_C(0x00800000)}, // F32 min normal
        {UINT32_C(0x7f7f0000), UINT32_C(0x7f7f0000)}, // max BF16 finite
        {UINT32_C(0x7f7fffff), UINT32_C(0x7f800000)}, // +finite overflow
        {UINT32_C(0xff7fffff), UINT32_C(0xff800000)}, // -finite overflow
        {UINT32_C(0x7f800000), UINT32_C(0x7f800000)}, // +inf
        {UINT32_C(0xff800000), UINT32_C(0xff800000)}, // -inf
        {UINT32_C(0x7f800001), UINT32_C(0x7fc00000)}, // low-payload sNaN
        {UINT32_C(0xff812345), UINT32_C(0xffc10000)}, // signed NaN payload
        {UINT32_C(0x7fcabcde), UINT32_C(0x7fca0000)}, // retained qNaN payload
    };
    enum { CASE_COUNT = sizeof(cases) / sizeof(cases[0]) };
    const uint64_t payload_bytes = (uint64_t)CASE_COUNT * sizeof(uint32_t);
    const uint64_t parent_bytes = payload_bytes + 2u * sizeof(uint32_t);
    uint32_t input[CASE_COUNT + 2u];
    uint32_t unchanged[CASE_COUNT + 2u];
    uint32_t actual[CASE_COUNT + 2u];
    input[0] = UINT32_C(0xdeadbeef);
    input[CASE_COUNT + 1u] = UINT32_C(0xfeedface);
    int ok = 1;
    for (uint32_t i = 0; i < CASE_COUNT; i++) {
        input[i + 1u] = cases[i].input;
        if (ds4_gpu_bf16_round_f32_oracle(cases[i].input) !=
            cases[i].expected) {
            ok = 0;
        }
    }
    memcpy(unchanged, input, sizeof(input));

    ds4_gpu_tensor *parent = ds4_gpu_tensor_alloc(parent_bytes);
    ds4_gpu_tensor *payload = parent ? ds4_gpu_tensor_view(
        parent, sizeof(uint32_t), payload_bytes) : NULL;
    ds4_gpu_tensor *undersized = parent ? ds4_gpu_tensor_view(
        parent, sizeof(uint32_t), payload_bytes - 1u) : NULL;
    ds4_gpu_tensor *misaligned = parent ? ds4_gpu_tensor_view(
        parent, 1u, payload_bytes) : NULL;
    ok = ok && parent && payload && undersized && misaligned &&
         ds4_gpu_tensor_write(parent, 0, input, sizeof(input));

    // One in-place operand makes inter-tensor overlap inapplicable.  The
    // adjacent live sentinels instead prove that the encoded view is isolated.
    if (ok) {
        ok = ds4_gpu_bf16_round_f32_tensor(NULL, CASE_COUNT) == 0 &&
             ds4_gpu_bf16_round_f32_tensor(payload, 0) == 0 &&
             ds4_gpu_bf16_round_f32_tensor(undersized, CASE_COUNT) == 0 &&
             ds4_gpu_bf16_round_f32_tensor(misaligned, CASE_COUNT) == 0 &&
             ds4_gpu_bf16_round_f32_tensor(payload, UINT64_MAX) == 0 &&
             ds4_gpu_tensor_read(parent, 0, actual, sizeof(actual)) &&
             memcmp(actual, unchanged, sizeof(actual)) == 0;
    }

    int began = 0;
    if (ok) {
        began = ds4_gpu_begin_commands();
        ok = began &&
             ds4_gpu_bf16_round_f32_tensor(payload, CASE_COUNT) != 0;
    }
    if (began && ds4_gpu_commands_active()) {
        const int end_ok = ds4_gpu_end_commands();
        ok = end_ok && ok;
    }
    if (ok) {
        ok = ds4_gpu_tensor_read(parent, 0, actual, sizeof(actual)) &&
             actual[0] == input[0] &&
             actual[CASE_COUNT + 1u] == input[CASE_COUNT + 1u];
    }
    for (uint32_t i = 0; ok && i < CASE_COUNT; i++) {
        const uint32_t expected =
            ds4_gpu_bf16_round_f32_oracle(cases[i].input);
        if (actual[i + 1u] != expected) {
            fprintf(stderr,
                    "ds4: BF16 Metal regression case %u got 0x%08x expected 0x%08x\n",
                    i, actual[i + 1u], expected);
            ok = 0;
        }
    }

    ds4_gpu_tensor_free(misaligned);
    ds4_gpu_tensor_free(undersized);
    ds4_gpu_tensor_free(payload);
    ds4_gpu_tensor_free(parent);
    return ok;
}

static float ds4_gpu_dspark_attention_test_bf16(float value) {
    uint32_t bits = 0;
    memcpy(&bits, &value, sizeof(bits));
    bits = ds4_gpu_bf16_round_f32_oracle(bits);
    memcpy(&value, &bits, sizeof(value));
    return value;
}

static uint32_t ds4_gpu_dspark_attention_test_bf16_order(uint32_t bits) {
    const uint32_t high = bits >> 16u;
    return (high & UINT32_C(0x8000))
        ? UINT32_C(0x8000) - (high & UINT32_C(0x7fff))
        : UINT32_C(0x8000) + high;
}

static void ds4_gpu_dspark_q_head_norm_cpu_reference(
        float       *out,
        const float *input,
        uint32_t     rows,
        float        eps) {
    enum {
        N_HEAD = 64,
        HEAD_DIM = 512,
        N_THREADS = 256,
    };
    for (uint32_t row = 0; row < rows; row++) {
        for (uint32_t head = 0; head < N_HEAD; head++) {
            const uint64_t base =
                ((uint64_t)row * N_HEAD + head) * HEAD_DIM;
            float reduction[N_THREADS];
            for (uint32_t tid = 0; tid < N_THREADS; tid++) {
                const float source0 = input[base + tid];
                const float source1 = input[base + tid + N_THREADS];
                const float square0 = ds4_gpu_dspark_attention_test_bf16(
                    source0 * source0);
                const float square1 = ds4_gpu_dspark_attention_test_bf16(
                    source1 * source1);
                reduction[tid] = square0 + square1;
            }
            for (uint32_t stride = N_THREADS / 2u;
                 stride != 0u;
                 stride >>= 1u) {
                for (uint32_t tid = 0; tid < stride; tid++) {
                    reduction[tid] += reduction[tid + stride];
                }
            }
            const float mean = ds4_gpu_dspark_attention_test_bf16(
                reduction[0] * (1.0f / (float)HEAD_DIM));
            const float added = ds4_gpu_dspark_attention_test_bf16(
                mean + eps);
            const float inverse_rms =
                ds4_gpu_dspark_attention_test_bf16(1.0f / sqrtf(added));
            for (uint32_t dim = 0; dim < HEAD_DIM; dim++) {
                out[base + dim] = ds4_gpu_dspark_attention_test_bf16(
                    input[base + dim] * inverse_rms);
            }
        }
    }
}

typedef enum {
    DS4_GPU_DSPARK_Q_NORM_SKIP_SQUARE = 0,
    DS4_GPU_DSPARK_Q_NORM_SKIP_MEAN,
    DS4_GPU_DSPARK_Q_NORM_SKIP_ADD_EPS,
    DS4_GPU_DSPARK_Q_NORM_SKIP_RSQRT,
    DS4_GPU_DSPARK_Q_NORM_SKIP_FINAL,
    DS4_GPU_DSPARK_Q_NORM_SKIP_COUNT,
} ds4_gpu_dspark_q_norm_mutation;

static void ds4_gpu_dspark_q_head_norm_mutation_control(
        float       *out,
        const float *input,
        uint32_t     rows,
        float        eps,
        ds4_gpu_dspark_q_norm_mutation mutation) {
    enum {
        N_HEAD = 64,
        HEAD_DIM = 512,
    };
    for (uint32_t row = 0; row < rows; row++) {
        for (uint32_t head = 0; head < N_HEAD; head++) {
            const uint64_t base =
                ((uint64_t)row * N_HEAD + head) * HEAD_DIM;
            float reduction[HEAD_DIM / 2u];
            for (uint32_t tid = 0; tid < HEAD_DIM / 2u; tid++) {
                float square0 =
                    input[base + tid] * input[base + tid];
                float square1 = input[base + tid + HEAD_DIM / 2u] *
                                input[base + tid + HEAD_DIM / 2u];
                if (mutation != DS4_GPU_DSPARK_Q_NORM_SKIP_SQUARE) {
                    square0 = ds4_gpu_dspark_attention_test_bf16(square0);
                    square1 = ds4_gpu_dspark_attention_test_bf16(square1);
                }
                reduction[tid] = square0 + square1;
            }
            for (uint32_t stride = HEAD_DIM / 4u;
                 stride != 0u;
                 stride >>= 1u) {
                for (uint32_t tid = 0; tid < stride; tid++) {
                    reduction[tid] += reduction[tid + stride];
                }
            }
            float mean = reduction[0] * (1.0f / (float)HEAD_DIM);
            if (mutation != DS4_GPU_DSPARK_Q_NORM_SKIP_MEAN) {
                mean = ds4_gpu_dspark_attention_test_bf16(mean);
            }
            float added = mean + eps;
            if (mutation != DS4_GPU_DSPARK_Q_NORM_SKIP_ADD_EPS) {
                added = ds4_gpu_dspark_attention_test_bf16(added);
            }
            float inverse_rms = 1.0f / sqrtf(added);
            if (mutation != DS4_GPU_DSPARK_Q_NORM_SKIP_RSQRT) {
                inverse_rms =
                    ds4_gpu_dspark_attention_test_bf16(inverse_rms);
            }
            for (uint32_t dim = 0; dim < HEAD_DIM; dim++) {
                float result = input[base + dim] * inverse_rms;
                if (mutation != DS4_GPU_DSPARK_Q_NORM_SKIP_FINAL) {
                    result = ds4_gpu_dspark_attention_test_bf16(result);
                }
                out[base + dim] = result;
            }
        }
    }
}

int ds4_gpu_internal_dspark_q_head_norm_bf16_test(void) {
    enum {
        ROWS = 5,
        N_HEAD = 64,
        HEAD_DIM = 512,
    };
    if (!g_initialized && !ds4_gpu_init()) return 0;

    const float eps = 1.0e-6f;
    const uint64_t values = (uint64_t)ROWS * N_HEAD * HEAD_DIM;
    const uint64_t payload_bytes = values * sizeof(float);
    const uint64_t parent_bytes = payload_bytes + 2u * sizeof(uint32_t);
    uint32_t *input_words = malloc((size_t)parent_bytes);
    uint32_t *actual_words = malloc((size_t)parent_bytes);
    uint32_t *rerun_words = malloc((size_t)parent_bytes);
    float *input = malloc((size_t)payload_bytes);
    float *expected = malloc((size_t)payload_bytes);
    float *mutation_output = malloc((size_t)payload_bytes);
    int ok = input_words && actual_words && rerun_words && input && expected &&
             mutation_output;
    if (!ok) goto cleanup_host;

    input_words[0] = UINT32_C(0xdeadbeef);
    input_words[values + 1u] = UINT32_C(0xfeedface);
    for (uint32_t row = 0; row < ROWS; row++) {
        for (uint32_t head = 0; head < N_HEAD; head++) {
            const float scale = ldexpf(1.0f, -4 * (int)(head & 3u));
            for (uint32_t dim = 0; dim < HEAD_DIM; dim++) {
                const int centered =
                    (int)((17u * dim + 13u * head + 19u * row) % 257u) -
                    128;
                const uint64_t index =
                    ((uint64_t)row * N_HEAD + head) * HEAD_DIM + dim;
                float value = ds4_gpu_dspark_attention_test_bf16(
                    (float)centered * (1.0f / 64.0f) * scale);
                /* This constant head makes publication of mean+eps visible
                 * after the following BF16 rsqrt and final multiply. */
                if (head == 0u) {
                    const uint32_t targeted_bits = UINT32_C(0x384a0000);
                    memcpy(&value, &targeted_bits, sizeof(value));
                }
                uint32_t bits = 0;
                input[index] = value;
                memcpy(&bits, &value, sizeof(bits));
                input_words[index + 1u] = bits;
            }
        }
    }
    ds4_gpu_dspark_q_head_norm_cpu_reference(
        expected, input, ROWS, eps);
    uint32_t targeted_output_bits = 0;
    memcpy(&targeted_output_bits, expected, sizeof(targeted_output_bits));
    if (targeted_output_bits != UINT32_C(0x3d440000)) ok = 0;

    static const uint64_t expected_mutation_differences[
        DS4_GPU_DSPARK_Q_NORM_SKIP_COUNT] = {
        845u, 9002u, 2560u, 44394u, 147461u,
    };
    uint64_t mutation_differences[DS4_GPU_DSPARK_Q_NORM_SKIP_COUNT] = {0};
    for (uint32_t mutation = 0;
         mutation < DS4_GPU_DSPARK_Q_NORM_SKIP_COUNT;
         mutation++) {
        ds4_gpu_dspark_q_head_norm_mutation_control(
            mutation_output, input, ROWS, eps,
            (ds4_gpu_dspark_q_norm_mutation)mutation);
        for (uint64_t i = 0; i < values; i++) {
            uint32_t expected_bits = 0;
            uint32_t mutation_bits = 0;
            memcpy(&expected_bits, expected + i, sizeof(expected_bits));
            memcpy(&mutation_bits, mutation_output + i,
                   sizeof(mutation_bits));
            if (expected_bits != mutation_bits) {
                mutation_differences[mutation]++;
            }
        }
        if (mutation_differences[mutation] !=
            expected_mutation_differences[mutation]) {
            ok = 0;
        }
    }

    ds4_gpu_tensor *parent = ok ? ds4_gpu_tensor_alloc(parent_bytes) : NULL;
    ds4_gpu_tensor *payload = parent ? ds4_gpu_tensor_view(
        parent, sizeof(uint32_t), payload_bytes) : NULL;
    ds4_gpu_tensor *undersized = parent ? ds4_gpu_tensor_view(
        parent, sizeof(uint32_t), payload_bytes - 1u) : NULL;
    ds4_gpu_tensor *misaligned = parent ? ds4_gpu_tensor_view(
        parent, 1u, payload_bytes) : NULL;
    ok = ok && parent && payload && undersized && misaligned &&
         ds4_gpu_tensor_write(parent, 0, input_words, parent_bytes);

    if (ok) {
        uint32_t invalid_bits = UINT32_C(0x7fc00000);
        float invalid_nan = 0.0f;
        float invalid_inf = 0.0f;
        memcpy(&invalid_nan, &invalid_bits, sizeof(invalid_nan));
        invalid_bits = UINT32_C(0x7f800000);
        memcpy(&invalid_inf, &invalid_bits, sizeof(invalid_inf));
        ok = ds4_gpu_dspark_q_head_norm_bf16_tensor(NULL, ROWS, eps) == 0 &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(payload, 0, eps) == 0 &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(payload, 4u, eps) == 0 &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(
                 undersized, ROWS, eps) == 0 &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(
                 misaligned, ROWS, eps) == 0 &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(
                 payload, UINT32_MAX, eps) == 0 &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(
                 payload, ROWS, 0.0f) == 0 &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(
                 payload, ROWS, invalid_nan) == 0 &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(
                 payload, ROWS, invalid_inf) == 0 &&
             ds4_gpu_tensor_read(
                 parent, 0, actual_words, parent_bytes) &&
             memcmp(actual_words, input_words, (size_t)parent_bytes) == 0;
    }

    /* An owned command buffer created before a failed encoder acquisition is
     * still committed and waited.  No batch or partial tensor publication may
     * escape that failure. */
    if (ok) {
        g_dspark_q_head_norm_test_fail_encoder = 1;
        const int injected_result =
            ds4_gpu_dspark_q_head_norm_bf16_tensor(payload, ROWS, eps);
        g_dspark_q_head_norm_test_fail_encoder = 0;
        ok = injected_result == 0 && !ds4_gpu_commands_active() &&
             ds4_gpu_tensor_read(
                 parent, 0, actual_words, parent_bytes) &&
             memcmp(actual_words, input_words, (size_t)parent_bytes) == 0;
    }

    /* A failed encode inside an externally owned batch does not close that
     * batch.  The caller can drain it, and the tensor still remains intact. */
    int failure_batch_began = 0;
    if (ok) {
        failure_batch_began = ds4_gpu_begin_commands();
        g_dspark_q_head_norm_test_fail_encoder = 1;
        const int injected_result = failure_batch_began
            ? ds4_gpu_dspark_q_head_norm_bf16_tensor(payload, ROWS, eps)
            : 1;
        g_dspark_q_head_norm_test_fail_encoder = 0;
        const int remained_active = ds4_gpu_commands_active();
        int end_ok = 0;
        if (remained_active) end_ok = ds4_gpu_end_commands();
        ok = failure_batch_began && injected_result == 0 &&
             remained_active && end_ok &&
             ds4_gpu_tensor_read(
                 parent, 0, actual_words, parent_bytes) &&
             memcmp(actual_words, input_words, (size_t)parent_bytes) == 0;
    }

    int began = 0;
    if (ok) {
        began = ds4_gpu_begin_commands();
        ok = began &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(
                 payload, ROWS, eps) != 0;
    }
    if (began && ds4_gpu_commands_active()) {
        const int end_ok = ds4_gpu_end_commands();
        ok = end_ok && ok;
    }
    if (ok) {
        ok = ds4_gpu_tensor_read(parent, 0, actual_words, parent_bytes) &&
             actual_words[0] == input_words[0] &&
             actual_words[values + 1u] == input_words[values + 1u];
    }
    for (uint64_t i = 0; ok && i < values; i++) {
        uint32_t expected_bits = 0;
        memcpy(&expected_bits, expected + i, sizeof(expected_bits));
        if (actual_words[i + 1u] != expected_bits) {
            fprintf(stderr,
                    "ds4: DSpark Q-head BF16 norm mismatch at %llu: "
                    "got 0x%08x expected 0x%08x\n",
                    (unsigned long long)i,
                    actual_words[i + 1u], expected_bits);
            ok = 0;
        }
    }

    /* A second independently committed run must be byte-identical. */
    if (ok) {
        ok = ds4_gpu_tensor_write(parent, 0, input_words, parent_bytes) &&
             ds4_gpu_dspark_q_head_norm_bf16_tensor(
                 payload, ROWS, eps) != 0 &&
             ds4_gpu_tensor_read(parent, 0, rerun_words, parent_bytes) &&
             memcmp(rerun_words, actual_words, (size_t)parent_bytes) == 0;
    }
    fprintf(stderr,
            "ds4: DSpark Q-head BF16 norm rows=%u mutations="
            "square:%llu mean:%llu add-eps:%llu rsqrt:%llu final:%llu "
            "deterministic=%s\n",
            ROWS,
            (unsigned long long)
                mutation_differences[DS4_GPU_DSPARK_Q_NORM_SKIP_SQUARE],
            (unsigned long long)
                mutation_differences[DS4_GPU_DSPARK_Q_NORM_SKIP_MEAN],
            (unsigned long long)
                mutation_differences[DS4_GPU_DSPARK_Q_NORM_SKIP_ADD_EPS],
            (unsigned long long)
                mutation_differences[DS4_GPU_DSPARK_Q_NORM_SKIP_RSQRT],
            (unsigned long long)
                mutation_differences[DS4_GPU_DSPARK_Q_NORM_SKIP_FINAL],
            ok ? "yes" : "no");

    ds4_gpu_tensor_free(misaligned);
    ds4_gpu_tensor_free(undersized);
    ds4_gpu_tensor_free(payload);
    ds4_gpu_tensor_free(parent);

cleanup_host:
    free(mutation_output);
    free(expected);
    free(input);
    free(rerun_words);
    free(actual_words);
    free(input_words);
    return ok;
}

static int ds4_gpu_dspark_attention_cpu_reference(
        float       *out,
        const float *q,
        const float *kv,
        const float *sinks,
        uint32_t     n_keys,
        uint32_t     n_head) {
    if (!out || !q || !kv || !sinks || n_keys == 0 || n_head == 0) {
        return 0;
    }
    const uint32_t head_dim = DS4_GPU_DSPARK_ATTENTION_HEAD_DIM;
    double *scores = malloc((size_t)n_keys * sizeof(*scores));
    double *acc = malloc((size_t)head_dim * sizeof(*acc));
    if (!scores || !acc) {
        free(scores);
        free(acc);
        return 0;
    }
    const double scale = 1.0 / sqrt((double)head_dim);
    for (uint32_t qr = 0;
         qr < DS4_GPU_DSPARK_ATTENTION_QUERY_ROWS;
         qr++) {
        for (uint32_t h = 0; h < n_head; h++) {
            const float *qrow = q +
                ((uint64_t)qr * n_head + h) * head_dim;
            double maximum = (double)sinks[h];
            for (uint32_t k = 0; k < n_keys; k++) {
                const float *kvrow = kv + (uint64_t)k * head_dim;
                double dot = 0.0;
                for (uint32_t d = 0; d < head_dim; d++) {
                    dot += (double)qrow[d] * (double)kvrow[d];
                }
                scores[k] = dot * scale;
                if (scores[k] > maximum) maximum = scores[k];
            }
            double denominator = exp((double)sinks[h] - maximum);
            memset(acc, 0, (size_t)head_dim * sizeof(*acc));
            for (uint32_t k = 0; k < n_keys; k++) {
                const double weight = exp(scores[k] - maximum);
                const float *kvrow = kv + (uint64_t)k * head_dim;
                denominator += weight;
                for (uint32_t d = 0; d < head_dim; d++) {
                    acc[d] += weight * (double)kvrow[d];
                }
            }
            float *dst = out +
                ((uint64_t)qr * n_head + h) * head_dim;
            for (uint32_t d = 0; d < head_dim; d++) {
                dst[d] = (float)(acc[d] / denominator);
            }
        }
    }
    free(scores);
    free(acc);
    return 1;
}

static int ds4_gpu_dspark_attention_cpu_official_reference(
        float       *out,
        const float *q,
        const float *kv,
        const float *sinks,
        uint32_t     n_keys,
        uint32_t     n_head) {
    if (!out || !q || !kv || !sinks || n_keys == 0 ||
        n_keys > 133u || n_head != DS4_GPU_DSPARK_ATTENTION_HEADS) {
        return 0;
    }
    const uint32_t head_dim = DS4_GPU_DSPARK_ATTENTION_HEAD_DIM;
    float *scores = malloc((size_t)n_keys * sizeof(*scores));
    float *acc = malloc((size_t)head_dim * sizeof(*acc));
    if (!scores || !acc) {
        free(scores);
        free(acc);
        return 0;
    }
    const float scale = 1.0f / sqrtf((float)head_dim);
    for (uint32_t qr = 0;
         qr < DS4_GPU_DSPARK_ATTENTION_QUERY_ROWS;
         qr++) {
        for (uint32_t h = 0; h < n_head; h++) {
            const float *qrow = q +
                ((uint64_t)qr * n_head + h) * head_dim;
            for (uint32_t key = 0; key < n_keys; key++) {
                const float *kvrow = kv + (uint64_t)key * head_dim;
                float lanes[32] = {0};
                for (uint32_t lane = 0; lane < 32u; lane++) {
                    for (uint32_t d = lane; d < head_dim; d += 32u) {
                        lanes[lane] = fmaf(qrow[d], kvrow[d], lanes[lane]);
                    }
                }
                for (uint32_t stride = 16u; stride != 0; stride >>= 1u) {
                    for (uint32_t lane = 0; lane < stride; lane++) {
                        lanes[lane] += lanes[lane + stride];
                    }
                }
                scores[key] = lanes[0] * scale;
            }

            float running_max = -FLT_MAX;
            float running_sum = 0.0f;
            memset(acc, 0, (size_t)head_dim * sizeof(*acc));
            for (uint32_t block = 0; block < n_keys; block += 64u) {
                const uint32_t end = block + 64u < n_keys
                    ? block + 64u : n_keys;
                const float previous_max = running_max;
                for (uint32_t key = block; key < end; key++) {
                    running_max = fmaxf(running_max, scores[key]);
                }
                const float block_scale = block == 0u
                    ? 0.0f : expf(previous_max - running_max);
                float block_sum = 0.0f;
                for (uint32_t key = block; key < end; key++) {
                    const float weight = expf(scores[key] - running_max);
                    block_sum += weight;
                    scores[key] =
                        ds4_gpu_dspark_attention_test_bf16(weight);
                }
                running_sum = running_sum * block_scale + block_sum;
                for (uint32_t d = 0; d < head_dim; d++) {
                    acc[d] *= block_scale;
                }
                for (uint32_t key = block; key < end; key++) {
                    const float weight = scores[key];
                    const float *kvrow = kv + (uint64_t)key * head_dim;
                    for (uint32_t d = 0; d < head_dim; d++) {
                        acc[d] += weight * kvrow[d];
                    }
                }
            }
            const float denominator = running_sum +
                expf(sinks[h] - running_max);
            float *dst = out +
                ((uint64_t)qr * n_head + h) * head_dim;
            for (uint32_t d = 0; d < head_dim; d++) {
                dst[d] = ds4_gpu_dspark_attention_test_bf16(
                    acc[d] / denominator);
            }
        }
    }
    free(scores);
    free(acc);
    return 1;
}

static int ds4_gpu_dspark_two_source_attention_case(
        const void *model_map,
        uint64_t    model_size,
        uint32_t    committed_count,
        uint32_t    committed_start,
        const char *label,
        float      *max_abs_out) {
    enum { N_HEAD = DS4_GPU_DSPARK_ATTENTION_HEADS };
    const uint32_t cap = DS4_GPU_DSPARK_ATTENTION_RING_CAP;
    const uint32_t dim = DS4_GPU_DSPARK_ATTENTION_HEAD_DIM;
    const uint32_t draft = DS4_GPU_DSPARK_ATTENTION_DRAFT_ROWS;
    const uint32_t query_rows = DS4_GPU_DSPARK_ATTENTION_QUERY_ROWS;
    const uint32_t n_keys = committed_count + draft;
    const uint64_t ring_values = (uint64_t)cap * dim;
    const uint64_t draft_values = (uint64_t)draft * dim;
    const uint64_t q_values = (uint64_t)query_rows * N_HEAD * dim;
    const uint64_t staged_values = (uint64_t)n_keys * dim;
    const uint64_t ring_bytes = ring_values * sizeof(float);
    const uint64_t draft_bytes = draft_values * sizeof(float);
    const uint64_t q_bytes = q_values * sizeof(float);

    float *ring = malloc((size_t)ring_bytes);
    float *ring_before = malloc((size_t)ring_bytes);
    float *draft_kv = malloc((size_t)draft_bytes);
    float *draft_before = malloc((size_t)draft_bytes);
    float *q = malloc((size_t)q_bytes);
    float *staged = malloc((size_t)staged_values * sizeof(float));
    float *staged_chronological =
        malloc((size_t)staged_values * sizeof(float));
    float *expected = malloc((size_t)q_bytes);
    float *expected_official = malloc((size_t)q_bytes);
    float *expected_chronological = malloc((size_t)q_bytes);
    float *actual = malloc((size_t)q_bytes);
    float *unchanged = malloc((size_t)q_bytes);
    int ok = ring && ring_before && draft_kv && draft_before && q && staged &&
             staged_chronological && expected && expected_official &&
             expected_chronological && actual && unchanged;
    if (!ok) goto cleanup_host;

    for (uint64_t i = 0; i < ring_values; i++) {
        ring[i] = ds4_gpu_dspark_attention_test_bf16(
            -0.42f + 0.000003f * (float)(i % 65521u));
    }
    for (uint32_t logical = 0; logical < committed_count; logical++) {
        const uint32_t physical = (committed_start + logical) % cap;
        for (uint32_t d = 0; d < dim; d++) {
            const float value =
                0.17f * sinf((float)(logical + 1u) * 0.071f +
                             (float)(d + 3u) * 0.013f) +
                0.06f * cosf((float)(logical + 5u) * 0.037f -
                             (float)(d + 7u) * 0.009f);
            ring[(uint64_t)physical * dim + d] =
                ds4_gpu_dspark_attention_test_bf16(value);
        }
    }
    /* The pinned top-k list observes physical slots, not oldest-token order. */
    memcpy(staged, ring, (size_t)committed_count * dim * sizeof(float));
    for (uint32_t logical = 0; logical < committed_count; logical++) {
        const uint32_t physical = (committed_start + logical) % cap;
        memcpy(staged_chronological + (uint64_t)logical * dim,
               ring + (uint64_t)physical * dim,
               (size_t)dim * sizeof(float));
    }
    for (uint32_t row = 0; row < draft; row++) {
        for (uint32_t d = 0; d < dim; d++) {
            const float value =
                -0.11f * cosf((float)(row + 2u) * 0.19f +
                              (float)(d + 1u) * 0.017f) +
                 0.03f * sinf((float)(row + 9u) * 0.11f -
                              (float)(d + 4u) * 0.007f);
            draft_kv[(uint64_t)row * dim + d] =
                ds4_gpu_dspark_attention_test_bf16(value);
            staged[((uint64_t)committed_count + row) * dim + d] =
                draft_kv[(uint64_t)row * dim + d];
            staged_chronological[
                ((uint64_t)committed_count + row) * dim + d] =
                draft_kv[(uint64_t)row * dim + d];
        }
    }
    for (uint32_t row = 0; row < query_rows; row++) {
        for (uint32_t h = 0; h < N_HEAD; h++) {
            for (uint32_t d = 0; d < dim; d++) {
                const float value =
                    0.12f * sinf((float)(row + 1u) * 0.23f +
                                 (float)(h + 2u) * 0.31f +
                                 (float)(d + 1u) * 0.011f) -
                    0.04f * cosf((float)(row + h + 3u) * 0.17f -
                                 (float)(d + 5u) * 0.005f);
                q[((uint64_t)row * N_HEAD + h) * dim + d] =
                    ds4_gpu_dspark_attention_test_bf16(value);
            }
        }
    }
    memcpy(ring_before, ring, (size_t)ring_bytes);
    memcpy(draft_before, draft_kv, (size_t)draft_bytes);
    for (uint64_t i = 0; i < q_values; i++) unchanged[i] = 13.25f;
    const float *sinks = (const float *)model_map;
    ok = ds4_gpu_dspark_attention_cpu_reference(
             expected, q, staged, sinks, n_keys, N_HEAD) &&
         ds4_gpu_dspark_attention_cpu_official_reference(
             expected_official, q, staged, sinks, n_keys, N_HEAD) &&
         ds4_gpu_dspark_attention_cpu_official_reference(
             expected_chronological, q, staged_chronological,
             sinks, n_keys, N_HEAD);
    if (ok && committed_count == cap && committed_start != 0u) {
        /* The fixture must distinguish the pinned physical 64-row blocks from
         * an accidentally chronological rotation after ring wrap. */
        uint64_t order_different = 0;
        uint32_t order_max_ulp = 0;
        for (uint64_t i = 0; i < q_values; i++) {
            uint32_t physical_bits = 0;
            uint32_t chronological_bits = 0;
            memcpy(&physical_bits, expected_official + i,
                   sizeof(physical_bits));
            memcpy(&chronological_bits, expected_chronological + i,
                   sizeof(chronological_bits));
            const uint32_t physical_order =
                ds4_gpu_dspark_attention_test_bf16_order(physical_bits);
            const uint32_t chronological_order =
                ds4_gpu_dspark_attention_test_bf16_order(
                    chronological_bits);
            const uint32_t ulp = physical_order > chronological_order
                ? physical_order - chronological_order
                : chronological_order - physical_order;
            if (ulp != 0) order_different++;
            if (ulp > order_max_ulp) order_max_ulp = ulp;
        }
        fprintf(stderr,
                "ds4: DSpark wrap physical-vs-chronological "
                "different=%llu max_bf16_ulp=%u\n",
                (unsigned long long)order_different, order_max_ulp);
        ok = order_different != 0 && order_max_ulp > 1u;
    }

    ds4_gpu_tensor *ring_gpu = ok
        ? ds4_gpu_tensor_alloc(ring_bytes) : NULL;
    ds4_gpu_tensor *draft_gpu = ok
        ? ds4_gpu_tensor_alloc(draft_bytes) : NULL;
    ds4_gpu_tensor *q_gpu = ok ? ds4_gpu_tensor_alloc(q_bytes) : NULL;
    ds4_gpu_tensor *heads_gpu = ok
        ? ds4_gpu_tensor_alloc(q_bytes) : NULL;
    ds4_gpu_tensor *short_ring = ring_gpu
        ? ds4_gpu_tensor_view(ring_gpu, 0, ring_bytes - 1u) : NULL;
    ok = ok && ring_gpu && draft_gpu && q_gpu && heads_gpu && short_ring &&
         ds4_gpu_tensor_write(ring_gpu, 0, ring, ring_bytes) &&
         ds4_gpu_tensor_write(draft_gpu, 0, draft_kv, draft_bytes) &&
         ds4_gpu_tensor_write(q_gpu, 0, q, q_bytes) &&
         ds4_gpu_tensor_write(heads_gpu, 0, unchanged, q_bytes);

    /* Every rejection happens before an encoder can write an output.  The
     * alias cases use otherwise correctly sized tensors, so they exercise the
     * range policy rather than falling through an undersized check. */
    if (ok) {
        ok = ds4_gpu_dspark_attention_two_source_f32_tensor(
                 NULL, model_map, model_size, 0, q_gpu, ring_gpu, draft_gpu,
                 committed_count, cap, committed_start, N_HEAD, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu,
                 draft_gpu, 0, cap, committed_start, N_HEAD, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu,
                 draft_gpu, 1u, cap, 0u, N_HEAD, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu,
                 draft_gpu, cap + 1u, cap, committed_start, N_HEAD, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu,
                 draft_gpu, committed_count, cap - 1u, committed_start,
                 N_HEAD, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu,
                 draft_gpu, committed_count, cap, cap, N_HEAD, dim) == 0 &&
             (committed_count == cap ||
              ds4_gpu_dspark_attention_two_source_f32_tensor(
                  heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu,
                  draft_gpu, committed_count, cap, 1u,
                  N_HEAD, dim) == 0) &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, short_ring,
                 draft_gpu, committed_count, cap, committed_start,
                 N_HEAD, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 q_gpu, model_map, model_size, 0, q_gpu, ring_gpu, draft_gpu,
                 committed_count, cap, committed_start, N_HEAD, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu, q_gpu,
                 committed_count, cap, committed_start, N_HEAD, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu,
                 draft_gpu, committed_count, cap, committed_start,
                 N_HEAD, dim - 1u) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0, q_gpu, ring_gpu,
                 draft_gpu, committed_count, cap, committed_start,
                 N_HEAD - 1u, dim) == 0 &&
             ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, model_size - 1u,
                 q_gpu, ring_gpu, draft_gpu, committed_count, cap,
                 committed_start, N_HEAD, dim) == 0 &&
             ds4_gpu_tensor_read(heads_gpu, 0, actual, q_bytes) &&
             memcmp(actual, unchanged, (size_t)q_bytes) == 0 &&
             ds4_gpu_tensor_read(ring_gpu, 0, ring, ring_bytes) &&
             memcmp(ring, ring_before, (size_t)ring_bytes) == 0 &&
             ds4_gpu_tensor_read(draft_gpu, 0, draft_kv, draft_bytes) &&
             memcmp(draft_kv, draft_before, (size_t)draft_bytes) == 0;
    }

    int began = 0;
    if (ok && committed_count < cap) {
        began = ds4_gpu_begin_commands();
        ok = began != 0;
    }
    if (ok) {
        ok = ds4_gpu_dspark_attention_two_source_f32_tensor(
                 heads_gpu, model_map, model_size, 0,
                 q_gpu, ring_gpu, draft_gpu,
                 committed_count, cap, committed_start, N_HEAD, dim) != 0;
    }
    if (began && ds4_gpu_commands_active()) {
        ok = ds4_gpu_end_commands() != 0 && ok;
    }
    if (ok) {
        ok = ds4_gpu_tensor_read(heads_gpu, 0, actual, q_bytes) &&
             ds4_gpu_tensor_read(ring_gpu, 0, ring, ring_bytes) &&
             memcmp(ring, ring_before, (size_t)ring_bytes) == 0 &&
             ds4_gpu_tensor_read(draft_gpu, 0, draft_kv, draft_bytes) &&
             memcmp(draft_kv, draft_before, (size_t)draft_bytes) == 0;
    }

    float max_abs = 0.0f;
    float max_abs_math = 0.0f;
    uint64_t adjacent_ulp_lanes = 0;
    uint32_t max_bf16_ulp = 0;
    uint64_t worst = 0;
    uint64_t worst_math = 0;
    for (uint64_t i = 0; ok && i < q_values; i++) {
        uint32_t actual_bits = 0;
        uint32_t expected_bits = 0;
        memcpy(&actual_bits, actual + i, sizeof(actual_bits));
        memcpy(&expected_bits, expected_official + i,
               sizeof(expected_bits));
        const float error = fabsf(actual[i] - expected_official[i]);
        const float math_error = fabsf(actual[i] - expected[i]);
        if (!isfinite(actual[i]) || error > max_abs) {
            max_abs = error;
            worst = i;
        }
        if (math_error > max_abs_math) {
            max_abs_math = math_error;
            worst_math = i;
        }
        const uint32_t actual_order =
            ds4_gpu_dspark_attention_test_bf16_order(actual_bits);
        const uint32_t expected_order =
            ds4_gpu_dspark_attention_test_bf16_order(expected_bits);
        const uint32_t ulp = actual_order > expected_order
            ? actual_order - expected_order
            : expected_order - actual_order;
        if (ulp != 0) adjacent_ulp_lanes++;
        if (ulp > max_bf16_ulp) max_bf16_ulp = ulp;
        if ((actual_bits & UINT32_C(0x0000ffff)) != 0 || ulp > 1u) {
            fprintf(stderr,
                    "ds4: DSpark %s official BF16 mismatch at %llu: got "
                    "0x%08x expected 0x%08x ulp=%u\n",
                    label, (unsigned long long)i,
                    actual_bits, expected_bits, ulp);
            ok = 0;
        }
    }
    fprintf(stderr,
            "ds4: DSpark %s attention max_abs official=%.9g "
            "max_bf16_ulp=%u adjacent_lanes=%llu stable-f32=%.9g "
            "official-worst=%llu stable-worst=%llu\n",
            label, max_abs, max_bf16_ulp,
            (unsigned long long)adjacent_ulp_lanes, max_abs_math,
            (unsigned long long)worst,
            (unsigned long long)worst_math);
    if (max_abs_out) *max_abs_out = max_abs;

    ds4_gpu_tensor_free(short_ring);
    ds4_gpu_tensor_free(heads_gpu);
    ds4_gpu_tensor_free(q_gpu);
    ds4_gpu_tensor_free(draft_gpu);
    ds4_gpu_tensor_free(ring_gpu);

cleanup_host:
    free(unchanged);
    free(actual);
    free(expected_chronological);
    free(expected_official);
    free(expected);
    free(staged_chronological);
    free(staged);
    free(q);
    free(draft_before);
    free(draft_kv);
    free(ring_before);
    free(ring);
    return ok;
}

static void *g_dspark_attention_test_model_map;

int ds4_gpu_internal_dspark_two_source_attention_test(void) {
    const long page_long = sysconf(_SC_PAGESIZE);
    if (page_long <= 0 || (!g_initialized && !ds4_gpu_init())) return 0;
    const size_t page = (size_t)page_long;
    if (!g_dspark_attention_test_model_map) {
        void *mapping = mmap(NULL, page, PROT_READ | PROT_WRITE,
                             MAP_PRIVATE | MAP_ANON, -1, 0);
        if (mapping == MAP_FAILED) return 0;
        g_dspark_attention_test_model_map = mapping;
    }
    void *model_map = g_dspark_attention_test_model_map;
    float *sinks = model_map;
    for (uint32_t h = 0; h < DS4_GPU_DSPARK_ATTENTION_HEADS; h++) {
        sinks[h] = -0.19f + 0.007f * (float)h;
    }
    int ok = ds4_gpu_set_model_map(model_map, page) != 0;
    float no_wrap_max_abs = 0.0f;
    float wrap_max_abs = 0.0f;
    if (ok) {
        /* Before the ring fills, visible physical slots are 0..count-1. */
        ok = ds4_gpu_dspark_two_source_attention_case(
            model_map, page, 27u, 0u, "partial",
            &no_wrap_max_abs);
    }
    if (ok) {
        /* A full ring whose oldest token is slot 125 must still be consumed
         * in pinned physical slot order, followed by the five draft rows. */
        ok = ds4_gpu_dspark_two_source_attention_case(
            model_map, page, 128u, 125u, "wrap",
            &wrap_max_abs);
    }
    fprintf(stderr,
            "ds4: DSpark two-source official BF16 max_abs "
            "partial=%.9g wrap=%.9g max_bf16_ulp_threshold=1\n",
            no_wrap_max_abs, wrap_max_abs);
    /* The Metal no-copy view owns no deallocator. Keep this one test page
     * mapped until process exit so the remainder of --metal-kernels retains
     * its device state and counters. */
    return ok;
}

/* -------------------------------------------------------------------------
 * Final-0731 stage-zero physical white box (compact 32/32/4 fixture).
 *
 * This is intentionally test-hook-only.  It regenerates the synthetic model
 * payload at runtime and drives the real Metal primitives while retaining
 * every official publication in a distinct tensor.  No product caller can
 * reach it while the three-stage graph remains fail-closed.
 * ------------------------------------------------------------------------- */

enum {
    DS4_DSPARK_PHYSICAL_ROWS = 5,
    DS4_DSPARK_PHYSICAL_HC = 4,
    DS4_DSPARK_PHYSICAL_HIDDEN = 32,
    DS4_DSPARK_PHYSICAL_Q_RANK = 32,
    DS4_DSPARK_PHYSICAL_HEADS = 64,
    DS4_DSPARK_PHYSICAL_HEAD_DIM = 512,
    DS4_DSPARK_PHYSICAL_ROPE = 64,
    DS4_DSPARK_PHYSICAL_GROUPS = 8,
    DS4_DSPARK_PHYSICAL_OUTPUT_RANK = 4,
    DS4_DSPARK_PHYSICAL_RING_CAP = 128,
    DS4_DSPARK_PHYSICAL_HC_MIX = 24,
    DS4_DSPARK_PHYSICAL_ALIGNMENT = 64,
    DS4_DSPARK_PHYSICAL_Q8_BLOCK = 32,
    DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES = 34,
    DS4_DSPARK_PHYSICAL_MODEL_BYTES = 1281856,
};

typedef struct {
    uint64_t hc_function;
    uint64_t hc_scale;
    uint64_t hc_base;
    uint64_t attention_norm;
    uint64_t q_a;
    uint64_t q_a_norm;
    uint64_t q_b;
    uint64_t kv;
    uint64_t kv_norm;
    uint64_t sinks;
    uint64_t output_a;
    uint64_t output_b;
} ds4_gpu_dspark_physical_offsets;

typedef struct {
    ds4_gpu_tensor *hidden_source;
    ds4_gpu_tensor *hidden_input;
    ds4_gpu_tensor *hc_plain_norm;
    ds4_gpu_tensor *hc_mix;
    ds4_gpu_tensor *hc_split;
    ds4_gpu_tensor *hc_pre_output;
    ds4_gpu_tensor *attention_normalized;
    ds4_gpu_tensor *q_a;
    ds4_gpu_tensor *q_a_normalized;
    ds4_gpu_tensor *q_b;
    ds4_gpu_tensor *q_head_normalized;
    ds4_gpu_tensor *q_roped;
    ds4_gpu_tensor *kv_projected;
    ds4_gpu_tensor *kv_normalized;
    ds4_gpu_tensor *kv_roped;
    ds4_gpu_tensor *kv_stored;
    ds4_gpu_tensor *ring;
    ds4_gpu_tensor *attention_output;
    ds4_gpu_tensor *attention_inverse_roped;
    ds4_gpu_tensor *output_a;
    ds4_gpu_tensor *output_b;
    ds4_gpu_tensor *hc_post_output;
    ds4_gpu_tensor *published_parent;
    ds4_gpu_tensor *published;
} ds4_gpu_dspark_physical_tensors;

typedef enum {
    DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE = 0,
    DS4_GPU_DSPARK_PHYSICAL_FAIL_Q_HEAD_ENCODER,
    DS4_GPU_DSPARK_PHYSICAL_FAIL_BEFORE_PUBLISH,
} ds4_gpu_dspark_physical_failure;

static uint64_t ds4_gpu_dspark_physical_align(uint64_t value) {
    return (value + DS4_DSPARK_PHYSICAL_ALIGNMENT - 1u) &
           ~(uint64_t)(DS4_DSPARK_PHYSICAL_ALIGNMENT - 1u);
}

static int ds4_gpu_dspark_physical_append(
        uint64_t *cursor,
        uint64_t  bytes,
        uint64_t *offset) {
    if (!cursor || !offset ||
        *cursor > UINT64_MAX - (DS4_DSPARK_PHYSICAL_ALIGNMENT - 1u)) {
        return 0;
    }
    const uint64_t aligned = ds4_gpu_dspark_physical_align(*cursor);
    if (aligned > DS4_DSPARK_PHYSICAL_MODEL_BYTES ||
        bytes > DS4_DSPARK_PHYSICAL_MODEL_BYTES - aligned) {
        return 0;
    }
    *offset = aligned;
    *cursor = aligned + bytes;
    return 1;
}

static int ds4_gpu_dspark_physical_layout(
        ds4_gpu_dspark_physical_offsets *offsets) {
    if (!offsets) return 0;
    uint64_t cursor = 0;
    const uint64_t q8_row32 = DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES;
    const uint64_t q8_row4096 =
        (DS4_DSPARK_PHYSICAL_GROUPS * DS4_DSPARK_PHYSICAL_HEAD_DIM /
         DS4_DSPARK_PHYSICAL_Q8_BLOCK) *
        DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES;
    return
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_HC_MIX *
                     DS4_DSPARK_PHYSICAL_HC *
                     DS4_DSPARK_PHYSICAL_HIDDEN * sizeof(uint16_t),
            &offsets->hc_function) &&
        ds4_gpu_dspark_physical_append(
            &cursor, 3u * sizeof(float), &offsets->hc_scale) &&
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_HC_MIX * sizeof(float),
            &offsets->hc_base) &&
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_HIDDEN * sizeof(float),
            &offsets->attention_norm) &&
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_Q_RANK * q8_row32,
            &offsets->q_a) &&
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_Q_RANK * sizeof(float),
            &offsets->q_a_norm) &&
        ds4_gpu_dspark_physical_append(
            &cursor,
            DS4_DSPARK_PHYSICAL_HEADS * DS4_DSPARK_PHYSICAL_HEAD_DIM *
                q8_row32,
            &offsets->q_b) &&
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_HEAD_DIM * q8_row32,
            &offsets->kv) &&
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_HEAD_DIM * sizeof(float),
            &offsets->kv_norm) &&
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_HEADS * sizeof(float),
            &offsets->sinks) &&
        ds4_gpu_dspark_physical_append(
            &cursor,
            DS4_DSPARK_PHYSICAL_GROUPS *
                DS4_DSPARK_PHYSICAL_OUTPUT_RANK * q8_row4096,
            &offsets->output_a) &&
        ds4_gpu_dspark_physical_append(
            &cursor, DS4_DSPARK_PHYSICAL_HIDDEN * q8_row32,
            &offsets->output_b) &&
        cursor == DS4_DSPARK_PHYSICAL_MODEL_BYTES;
}

static void ds4_gpu_dspark_physical_q8_one(
        uint8_t *payload,
        uint32_t width,
        uint32_t selector,
        int      sign) {
    const uint32_t block = selector / DS4_DSPARK_PHYSICAL_Q8_BLOCK;
    const uint32_t lane = selector % DS4_DSPARK_PHYSICAL_Q8_BLOCK;
    uint8_t *packed = payload +
        (uint64_t)block * DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES;
    /* IEEE F16 2^-8, followed by one signed +/-127 code. */
    packed[0] = 0x00u;
    packed[1] = 0x1cu;
    packed[2u + lane] = (uint8_t)(int8_t)(sign < 0 ? -127 : 127);
    (void)width;
}

static int ds4_gpu_dspark_physical_generate_model(
        uint8_t                            *model,
        uint64_t                            model_bytes,
        ds4_gpu_dspark_physical_offsets    *offsets) {
    if (!model || model_bytes != DS4_DSPARK_PHYSICAL_MODEL_BYTES ||
        !ds4_gpu_dspark_physical_layout(offsets)) {
        return 0;
    }
    memset(model, 0, (size_t)model_bytes);

    uint16_t *hc = (uint16_t *)(model + offsets->hc_function);
    for (uint32_t row = 0; row < DS4_DSPARK_PHYSICAL_HC_MIX; row++) {
        const uint32_t column = (row * 17u + 3u) %
            (DS4_DSPARK_PHYSICAL_HC * DS4_DSPARK_PHYSICAL_HIDDEN);
        hc[(uint64_t)row * DS4_DSPARK_PHYSICAL_HC *
           DS4_DSPARK_PHYSICAL_HIDDEN + column] =
            (row & 1u) == 0u ? UINT16_C(0x3000) : UINT16_C(0xac00);
    }

    float *hc_scale = (float *)(model + offsets->hc_scale);
    hc_scale[0] = 0.25f;
    hc_scale[1] = 0.125f;
    hc_scale[2] = 0.0625f;
    float *hc_base = (float *)(model + offsets->hc_base);
    for (uint32_t i = 0; i < DS4_DSPARK_PHYSICAL_HC_MIX; i++) {
        hc_base[i] = (float)((int32_t)(i % 7u) - 3) / 16.0f;
    }
    float *attention_norm = (float *)(model + offsets->attention_norm);
    for (uint32_t i = 0; i < DS4_DSPARK_PHYSICAL_HIDDEN; i++) {
        attention_norm[i] = (float)(i % 11u + 8u) / 16.0f;
    }

    uint8_t *q_a = model + offsets->q_a;
    for (uint32_t row = 0; row < DS4_DSPARK_PHYSICAL_Q_RANK; row++) {
        ds4_gpu_dspark_physical_q8_one(
            q_a + (uint64_t)row * DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES,
            DS4_DSPARK_PHYSICAL_HIDDEN,
            row,
            (row & 1u) == 0u ? 1 : -1);
    }
    float *q_a_norm = (float *)(model + offsets->q_a_norm);
    for (uint32_t i = 0; i < DS4_DSPARK_PHYSICAL_Q_RANK; i++) {
        q_a_norm[i] = 1.0f;
    }

    uint8_t *q_b = model + offsets->q_b;
    for (uint32_t row = 0;
         row < DS4_DSPARK_PHYSICAL_HEADS *
               DS4_DSPARK_PHYSICAL_HEAD_DIM;
         row++) {
        const uint32_t head = row / DS4_DSPARK_PHYSICAL_HEAD_DIM;
        const uint32_t dim = row % DS4_DSPARK_PHYSICAL_HEAD_DIM;
        const uint32_t selector = (head + dim) %
            DS4_DSPARK_PHYSICAL_Q_RANK;
        const int sign = ((((dim >> (head % 7u)) ^ head) & 1u) == 0u)
            ? 1 : -1;
        ds4_gpu_dspark_physical_q8_one(
            q_b + (uint64_t)row * DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES,
            DS4_DSPARK_PHYSICAL_Q_RANK, selector, sign);
    }

    uint8_t *kv = model + offsets->kv;
    for (uint32_t row = 0; row < DS4_DSPARK_PHYSICAL_HEAD_DIM; row++) {
        ds4_gpu_dspark_physical_q8_one(
            kv + (uint64_t)row * DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES,
            DS4_DSPARK_PHYSICAL_HIDDEN,
            row % DS4_DSPARK_PHYSICAL_HIDDEN, 1);
    }
    float *kv_norm = (float *)(model + offsets->kv_norm);
    for (uint32_t i = 0; i < DS4_DSPARK_PHYSICAL_HEAD_DIM; i++) {
        kv_norm[i] = (float)(i % 11u + 8u) / 512.0f;
    }
    float *sinks = (float *)(model + offsets->sinks);
    for (uint32_t i = 0; i < DS4_DSPARK_PHYSICAL_HEADS; i++) {
        sinks[i] = (float)(-1.5 + (double)i / 24.0);
    }

    const uint32_t output_group_dim =
        DS4_DSPARK_PHYSICAL_GROUPS * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t output_a_row_bytes =
        (uint64_t)(output_group_dim / DS4_DSPARK_PHYSICAL_Q8_BLOCK) *
        DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES;
    uint8_t *output_a = model + offsets->output_a;
    for (uint32_t row = 0;
         row < DS4_DSPARK_PHYSICAL_GROUPS *
               DS4_DSPARK_PHYSICAL_OUTPUT_RANK;
         row++) {
        const uint32_t group = row / DS4_DSPARK_PHYSICAL_OUTPUT_RANK;
        const uint32_t rank = row % DS4_DSPARK_PHYSICAL_OUTPUT_RANK;
        const uint32_t selector =
            (group * 521u + rank * 977u + 37u) % output_group_dim;
        ds4_gpu_dspark_physical_q8_one(
            output_a + (uint64_t)row * output_a_row_bytes,
            output_group_dim, selector, (row & 1u) == 0u ? 1 : -1);
    }

    uint8_t *output_b = model + offsets->output_b;
    for (uint32_t row = 0; row < DS4_DSPARK_PHYSICAL_HIDDEN; row++) {
        ds4_gpu_dspark_physical_q8_one(
            output_b + (uint64_t)row * DS4_DSPARK_PHYSICAL_Q8_BLOCK_BYTES,
            DS4_DSPARK_PHYSICAL_GROUPS * DS4_DSPARK_PHYSICAL_OUTPUT_RANK,
            (row * 13u + 5u) %
                (DS4_DSPARK_PHYSICAL_GROUPS *
                 DS4_DSPARK_PHYSICAL_OUTPUT_RANK),
            row % 3u == 0u ? -1 : 1);
    }
    return 1;
}

static void ds4_gpu_dspark_physical_free_tensors(
        ds4_gpu_dspark_physical_tensors *t) {
    if (!t) return;
#define DS4_DSPARK_PHYSICAL_FREE(name) \
    do { ds4_gpu_tensor_free(t->name); t->name = NULL; } while (0)
    DS4_DSPARK_PHYSICAL_FREE(published);
    DS4_DSPARK_PHYSICAL_FREE(published_parent);
    DS4_DSPARK_PHYSICAL_FREE(hc_post_output);
    DS4_DSPARK_PHYSICAL_FREE(output_b);
    DS4_DSPARK_PHYSICAL_FREE(output_a);
    DS4_DSPARK_PHYSICAL_FREE(attention_inverse_roped);
    DS4_DSPARK_PHYSICAL_FREE(attention_output);
    DS4_DSPARK_PHYSICAL_FREE(ring);
    DS4_DSPARK_PHYSICAL_FREE(kv_stored);
    DS4_DSPARK_PHYSICAL_FREE(kv_roped);
    DS4_DSPARK_PHYSICAL_FREE(kv_normalized);
    DS4_DSPARK_PHYSICAL_FREE(kv_projected);
    DS4_DSPARK_PHYSICAL_FREE(q_roped);
    DS4_DSPARK_PHYSICAL_FREE(q_head_normalized);
    DS4_DSPARK_PHYSICAL_FREE(q_b);
    DS4_DSPARK_PHYSICAL_FREE(q_a_normalized);
    DS4_DSPARK_PHYSICAL_FREE(q_a);
    DS4_DSPARK_PHYSICAL_FREE(attention_normalized);
    DS4_DSPARK_PHYSICAL_FREE(hc_pre_output);
    DS4_DSPARK_PHYSICAL_FREE(hc_split);
    DS4_DSPARK_PHYSICAL_FREE(hc_mix);
    DS4_DSPARK_PHYSICAL_FREE(hc_plain_norm);
    DS4_DSPARK_PHYSICAL_FREE(hidden_input);
    DS4_DSPARK_PHYSICAL_FREE(hidden_source);
#undef DS4_DSPARK_PHYSICAL_FREE
}

static int ds4_gpu_dspark_physical_alloc_tensors(
        ds4_gpu_dspark_physical_tensors *t) {
    if (!t) return 0;
    memset(t, 0, sizeof(*t));
    const uint64_t hidden_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN;
    const uint64_t hidden_bytes = hidden_values * sizeof(float);
    const uint64_t rank_bytes =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_Q_RANK *
        sizeof(float);
    const uint64_t row_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HIDDEN;
    const uint64_t row_bytes = row_values * sizeof(float);
    const uint64_t mix_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC_MIX;
    const uint64_t mix_bytes = mix_values * sizeof(float);
    const uint64_t q_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEADS *
        DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t q_bytes = q_values * sizeof(float);
    const uint64_t kv_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t kv_bytes = kv_values * sizeof(float);
    const uint64_t ring_bytes =
        DS4_DSPARK_PHYSICAL_RING_CAP *
        DS4_DSPARK_PHYSICAL_HEAD_DIM * sizeof(float);
    const uint64_t output_a_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_GROUPS *
        DS4_DSPARK_PHYSICAL_OUTPUT_RANK;
    const uint64_t output_a_bytes = output_a_values * sizeof(float);
    const uint64_t published_parent_bytes =
        hidden_bytes + 2u * sizeof(uint32_t);

#define DS4_DSPARK_PHYSICAL_ALLOC(name, bytes_) \
    do { \
        t->name = ds4_gpu_tensor_alloc((bytes_)); \
        if (!t->name) goto fail; \
    } while (0)
    DS4_DSPARK_PHYSICAL_ALLOC(hidden_source, hidden_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(hidden_input, hidden_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(hc_plain_norm, hidden_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(hc_mix, mix_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(hc_split, mix_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(hc_pre_output, row_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(attention_normalized, row_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(q_a, rank_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(q_a_normalized, rank_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(q_b, q_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(q_head_normalized, q_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(q_roped, q_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(kv_projected, kv_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(kv_normalized, kv_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(kv_roped, kv_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(kv_stored, kv_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(ring, ring_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(attention_output, q_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(attention_inverse_roped, q_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(output_a, output_a_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(output_b, row_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(hc_post_output, hidden_bytes);
    DS4_DSPARK_PHYSICAL_ALLOC(published_parent, published_parent_bytes);
    t->published = ds4_gpu_tensor_view(
        t->published_parent, sizeof(uint32_t), hidden_bytes);
    if (!t->published) goto fail;
#undef DS4_DSPARK_PHYSICAL_ALLOC
    return 1;

fail:
#undef DS4_DSPARK_PHYSICAL_ALLOC
    ds4_gpu_dspark_physical_free_tensors(t);
    return 0;
}

static int ds4_gpu_dspark_physical_tensors_overlap(
        const ds4_gpu_tensor *a,
        uint64_t              a_bytes,
        const ds4_gpu_tensor *b,
        uint64_t              b_bytes) {
    if (!a || !b || a_bytes == 0 || b_bytes == 0 ||
        ds4_gpu_tensor_buffer(a) != ds4_gpu_tensor_buffer(b)) {
        return 0;
    }
    const uint64_t a_offset = ds4_gpu_tensor_offset(a);
    const uint64_t b_offset = ds4_gpu_tensor_offset(b);
    if (a_bytes > UINT64_MAX - a_offset ||
        b_bytes > UINT64_MAX - b_offset) {
        return 1;
    }
    return a_offset < b_offset + b_bytes &&
        b_offset < a_offset + a_bytes;
}

static int ds4_gpu_dspark_physical_preflight(
        const ds4_gpu_dspark_physical_tensors *t,
        const ds4_gpu_dspark_physical_offsets *offsets,
        uint64_t                               model_size) {
    if (!t || !offsets || model_size != DS4_DSPARK_PHYSICAL_MODEL_BYTES) {
        return 0;
    }
    ds4_gpu_dspark_physical_offsets canonical = {0};
    if (!ds4_gpu_dspark_physical_layout(&canonical) ||
        memcmp(offsets, &canonical, sizeof(canonical)) != 0) {
        return 0;
    }
    const uint64_t hidden =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN * sizeof(float);
    const uint64_t row =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HIDDEN *
        sizeof(float);
    const uint64_t mix =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC_MIX *
        sizeof(float);
    const uint64_t rank =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_Q_RANK *
        sizeof(float);
    const uint64_t q =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEADS *
        DS4_DSPARK_PHYSICAL_HEAD_DIM * sizeof(float);
    const uint64_t kv =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM *
        sizeof(float);
    const uint64_t ring =
        DS4_DSPARK_PHYSICAL_RING_CAP * DS4_DSPARK_PHYSICAL_HEAD_DIM *
        sizeof(float);
    const uint64_t output_a =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_GROUPS *
        DS4_DSPARK_PHYSICAL_OUTPUT_RANK * sizeof(float);
    const struct {
        const ds4_gpu_tensor *tensor;
        uint64_t bytes;
    } entries[] = {
        {t->hidden_source, hidden},
        {t->hidden_input, hidden},
        {t->hc_plain_norm, hidden},
        {t->hc_mix, mix},
        {t->hc_split, mix},
        {t->hc_pre_output, row},
        {t->attention_normalized, row},
        {t->q_a, rank},
        {t->q_a_normalized, rank},
        {t->q_b, q},
        {t->q_head_normalized, q},
        {t->q_roped, q},
        {t->kv_projected, kv},
        {t->kv_normalized, kv},
        {t->kv_roped, kv},
        {t->kv_stored, kv},
        {t->ring, ring},
        {t->attention_output, q},
        {t->attention_inverse_roped, q},
        {t->output_a, output_a},
        {t->output_b, row},
        {t->hc_post_output, hidden},
        {t->published, hidden},
    };
    for (size_t i = 0; i < sizeof(entries) / sizeof(entries[0]); i++) {
        if (!entries[i].tensor ||
            ds4_gpu_tensor_bytes(entries[i].tensor) < entries[i].bytes) {
            return 0;
        }
        for (size_t j = 0; j < i; j++) {
            if (ds4_gpu_dspark_physical_tensors_overlap(
                    entries[i].tensor, entries[i].bytes,
                    entries[j].tensor, entries[j].bytes)) {
                return 0;
            }
        }
    }
    return 1;
}

static int ds4_gpu_dspark_physical_execute(
        ds4_gpu_dspark_physical_tensors       *t,
        const void                            *model_map,
        uint64_t                               model_size,
        const ds4_gpu_dspark_physical_offsets *offsets,
        uint32_t                               committed_count,
        uint32_t                               committed_start,
        ds4_gpu_dspark_physical_failure        failure) {
    if (!model_map ||
        !ds4_gpu_dspark_physical_preflight(t, offsets, model_size) ||
        (int)failure < (int)DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE ||
        failure > DS4_GPU_DSPARK_PHYSICAL_FAIL_BEFORE_PUBLISH ||
        !((committed_count == 2u && committed_start == 0u) ||
          (committed_count == DS4_DSPARK_PHYSICAL_RING_CAP &&
           committed_start == 2u))) {
        return 0;
    }
    const uint32_t position0 = committed_count == 2u ? 2u : 130u;
    const uint64_t hidden_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN;
    const uint64_t hidden_bytes = hidden_values * sizeof(float);
    const uint64_t row_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HIDDEN;
    const uint64_t q_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEADS *
        DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t output_a_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_GROUPS *
        DS4_DSPARK_PHYSICAL_OUTPUT_RANK;
#ifdef DS4_TEST_HOOKS
    memset(&g_dspark_q8_dispatch_capture, 0,
           sizeof(g_dspark_q8_dispatch_capture));
    g_dspark_q8_dispatch_capture.enabled = 1;
#endif
    int began = ds4_gpu_begin_commands();
    if (!began) {
#ifdef DS4_TEST_HOOKS
        g_dspark_q8_dispatch_capture.enabled = 0;
#endif
        return 0;
    }
    int ok = 1;

#define DS4_DSPARK_PHYSICAL_STEP(expr_) \
    do { if (ok && !(expr_)) ok = 0; } while (0)
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_tensor_copy(
        t->hidden_input, 0, t->hidden_source, 0, hidden_bytes));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->hidden_input, hidden_values));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_rms_norm_plain_rows_tensor(
        t->hc_plain_norm,
        t->hidden_input,
        DS4_DSPARK_PHYSICAL_HC * DS4_DSPARK_PHYSICAL_HIDDEN,
        DS4_DSPARK_PHYSICAL_ROWS,
        1.0e-6f));
    /* Exact compact dispatch: n_tok=5,in=128 selects the F16-weight,
     * F32-activation mul_mv_ext r1=5 kernel; it does not half-stage RHS. */
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_matmul_f16_tensor(
        t->hc_mix,
        model_map,
        model_size,
        offsets->hc_function,
        DS4_DSPARK_PHYSICAL_HC * DS4_DSPARK_PHYSICAL_HIDDEN,
        DS4_DSPARK_PHYSICAL_HC_MIX,
        t->hc_plain_norm,
        DS4_DSPARK_PHYSICAL_ROWS));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_hc_split_sinkhorn_tensor(
        t->hc_split,
        t->hc_mix,
        model_map,
        model_size,
        offsets->hc_scale,
        offsets->hc_base,
        DS4_DSPARK_PHYSICAL_HC,
        20u,
        1.0e-6f));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_hc_weighted_sum_split_tensor(
        t->hc_pre_output,
        t->hidden_input,
        t->hc_split,
        DS4_DSPARK_PHYSICAL_HIDDEN,
        DS4_DSPARK_PHYSICAL_HC));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->hc_pre_output, row_values));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_rms_norm_weight_rows_tensor(
        t->attention_normalized,
        t->hc_pre_output,
        model_map,
        model_size,
        offsets->attention_norm,
        DS4_DSPARK_PHYSICAL_HIDDEN,
        DS4_DSPARK_PHYSICAL_ROWS,
        1.0e-6f));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->attention_normalized, row_values));

    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_matmul_q8_0_tensor(
        t->q_a,
        model_map,
        model_size,
        offsets->q_a,
        DS4_DSPARK_PHYSICAL_HIDDEN,
        DS4_DSPARK_PHYSICAL_Q_RANK,
        t->attention_normalized,
        DS4_DSPARK_PHYSICAL_ROWS));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->q_a,
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_Q_RANK));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_rms_norm_weight_rows_tensor(
        t->q_a_normalized,
        t->q_a,
        model_map,
        model_size,
        offsets->q_a_norm,
        DS4_DSPARK_PHYSICAL_Q_RANK,
        DS4_DSPARK_PHYSICAL_ROWS,
        1.0e-6f));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->q_a_normalized,
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_Q_RANK));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_matmul_q8_0_tensor(
        t->q_b,
        model_map,
        model_size,
        offsets->q_b,
        DS4_DSPARK_PHYSICAL_Q_RANK,
        DS4_DSPARK_PHYSICAL_HEADS * DS4_DSPARK_PHYSICAL_HEAD_DIM,
        t->q_a_normalized,
        DS4_DSPARK_PHYSICAL_ROWS));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->q_b, q_values));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_tensor_copy(
        t->q_head_normalized, 0, t->q_b, 0, q_values * sizeof(float)));
    if (ok && failure == DS4_GPU_DSPARK_PHYSICAL_FAIL_Q_HEAD_ENCODER) {
        g_dspark_q_head_norm_test_fail_encoder = 1;
    }
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_dspark_q_head_norm_bf16_tensor(
        t->q_head_normalized, DS4_DSPARK_PHYSICAL_ROWS, 1.0e-6f));
    g_dspark_q_head_norm_test_fail_encoder = 0;
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_tensor_copy(
        t->q_roped, 0, t->q_head_normalized, 0,
        q_values * sizeof(float)));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_rope_tail_tensor(
        t->q_roped,
        DS4_DSPARK_PHYSICAL_ROWS,
        DS4_DSPARK_PHYSICAL_HEADS,
        DS4_DSPARK_PHYSICAL_HEAD_DIM,
        DS4_DSPARK_PHYSICAL_ROPE,
        position0,
        0u,
        false,
        10000.0f,
        1.0f,
        0.0f,
        1.0f,
        32.0f,
        1.0f));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->q_roped, q_values));

    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_matmul_q8_0_tensor(
        t->kv_projected,
        model_map,
        model_size,
        offsets->kv,
        DS4_DSPARK_PHYSICAL_HIDDEN,
        DS4_DSPARK_PHYSICAL_HEAD_DIM,
        t->attention_normalized,
        DS4_DSPARK_PHYSICAL_ROWS));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->kv_projected,
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_rms_norm_weight_rows_tensor(
        t->kv_normalized,
        t->kv_projected,
        model_map,
        model_size,
        offsets->kv_norm,
        DS4_DSPARK_PHYSICAL_HEAD_DIM,
        DS4_DSPARK_PHYSICAL_ROWS,
        1.0e-6f));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->kv_normalized,
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_tensor_copy(
        t->kv_roped, 0, t->kv_normalized, 0,
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM *
            sizeof(float)));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_rope_tail_tensor(
        t->kv_roped,
        DS4_DSPARK_PHYSICAL_ROWS,
        1u,
        DS4_DSPARK_PHYSICAL_HEAD_DIM,
        DS4_DSPARK_PHYSICAL_ROPE,
        position0,
        0u,
        false,
        10000.0f,
        1.0f,
        0.0f,
        1.0f,
        32.0f,
        1.0f));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->kv_roped,
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_tensor_copy(
        t->kv_stored, 0, t->kv_roped, 0,
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM *
            sizeof(float)));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_dsv4_fp8_kv_quantize_tensor(
        t->kv_stored,
        DS4_DSPARK_PHYSICAL_ROWS,
        DS4_DSPARK_PHYSICAL_HEAD_DIM,
        DS4_DSPARK_PHYSICAL_ROPE));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->kv_stored,
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM));

    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_dspark_attention_two_source_f32_tensor(
        t->attention_output,
        model_map,
        model_size,
        offsets->sinks,
        t->q_roped,
        t->ring,
        t->kv_stored,
        committed_count,
        DS4_DSPARK_PHYSICAL_RING_CAP,
        committed_start,
        DS4_DSPARK_PHYSICAL_HEADS,
        DS4_DSPARK_PHYSICAL_HEAD_DIM));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_tensor_copy(
        t->attention_inverse_roped, 0, t->attention_output, 0,
        q_values * sizeof(float)));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_rope_tail_tensor(
        t->attention_inverse_roped,
        DS4_DSPARK_PHYSICAL_ROWS,
        DS4_DSPARK_PHYSICAL_HEADS,
        DS4_DSPARK_PHYSICAL_HEAD_DIM,
        DS4_DSPARK_PHYSICAL_ROPE,
        position0,
        0u,
        true,
        10000.0f,
        1.0f,
        0.0f,
        1.0f,
        32.0f,
        1.0f));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->attention_inverse_roped, q_values));

    for (uint32_t row = 0; ok && row < DS4_DSPARK_PHYSICAL_ROWS; row++) {
        const uint64_t head_row_bytes =
            (uint64_t)DS4_DSPARK_PHYSICAL_HEADS *
            DS4_DSPARK_PHYSICAL_HEAD_DIM * sizeof(float);
        const uint64_t low_row_bytes =
            (uint64_t)DS4_DSPARK_PHYSICAL_GROUPS *
            DS4_DSPARK_PHYSICAL_OUTPUT_RANK * sizeof(float);
        ds4_gpu_tensor *heads_row = ds4_gpu_tensor_view(
            t->attention_inverse_roped,
            (uint64_t)row * head_row_bytes,
            head_row_bytes);
        ds4_gpu_tensor *low_row = ds4_gpu_tensor_view(
            t->output_a,
            (uint64_t)row * low_row_bytes,
            low_row_bytes);
        if (!heads_row || !low_row ||
            !ds4_gpu_attention_output_low_q8_tensor(
                low_row,
                model_map,
                model_size,
                offsets->output_a,
                DS4_DSPARK_PHYSICAL_GROUPS *
                    DS4_DSPARK_PHYSICAL_HEAD_DIM,
                DS4_DSPARK_PHYSICAL_OUTPUT_RANK,
                DS4_DSPARK_PHYSICAL_GROUPS,
                heads_row)) {
            ok = 0;
        }
        ds4_gpu_tensor_free(low_row);
        ds4_gpu_tensor_free(heads_row);
    }
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->output_a, output_a_values));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_matmul_q8_0_tensor(
        t->output_b,
        model_map,
        model_size,
        offsets->output_b,
        DS4_DSPARK_PHYSICAL_GROUPS * DS4_DSPARK_PHYSICAL_OUTPUT_RANK,
        DS4_DSPARK_PHYSICAL_HIDDEN,
        t->output_a,
        DS4_DSPARK_PHYSICAL_ROWS));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->output_b, row_values));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_hc_expand_split_tensor(
        t->hc_post_output,
        t->output_b,
        t->hidden_input,
        t->hc_split,
        DS4_DSPARK_PHYSICAL_HIDDEN,
        DS4_DSPARK_PHYSICAL_HC));
    DS4_DSPARK_PHYSICAL_STEP(ds4_gpu_bf16_round_f32_tensor(
        t->hc_post_output, hidden_values));

#undef DS4_DSPARK_PHYSICAL_STEP

    /* Drain every compute before encoding the publication.  A completion
     * failure therefore cannot leave a partially updated public shadow. */
    if (ds4_gpu_commands_active()) {
        const int finish_ok = ds4_gpu_end_commands();
        if (!finish_ok) ok = 0;
    }
    if (ok && failure == DS4_GPU_DSPARK_PHYSICAL_FAIL_BEFORE_PUBLISH) {
        ok = 0;
    }
    if (ok) {
        /* Encode the shadow copy in a fresh batch, separate from every
         * compute above, and synchronously drain it before reporting success. */
        ok = ds4_gpu_begin_commands() &&
             ds4_gpu_tensor_copy(
                 t->published, 0, t->hc_post_output, 0, hidden_bytes);
        if (ds4_gpu_commands_active()) {
            const int publish_ok = ds4_gpu_end_commands();
            if (!publish_ok) ok = 0;
        }
    }
#ifdef DS4_TEST_HOOKS
    g_dspark_q8_dispatch_capture.enabled = 0;
#endif
    return ok;
}

static void ds4_gpu_dspark_physical_sha256(
        const void *bytes,
        size_t      length,
        char        hex[CC_SHA256_DIGEST_LENGTH * 2u + 1u]) {
    unsigned char digest[CC_SHA256_DIGEST_LENGTH];
    CC_SHA256(bytes, (CC_LONG)length, digest);
    for (size_t i = 0; i < CC_SHA256_DIGEST_LENGTH; i++) {
        snprintf(hex + 2u * i, 3u, "%02x", digest[i]);
    }
    hex[CC_SHA256_DIGEST_LENGTH * 2u] = '\0';
}

static int ds4_gpu_dspark_physical_sha_matches(
        const void *bytes,
        size_t      length,
        const char *expected,
        const char *label) {
    char actual[CC_SHA256_DIGEST_LENGTH * 2u + 1u];
    ds4_gpu_dspark_physical_sha256(bytes, length, actual);
    if (strcmp(actual, expected) == 0) return 1;
    fprintf(stderr,
            "ds4: DSpark physical %s SHA mismatch got=%s expected=%s\n",
            label, actual, expected);
    return 0;
}

static int ds4_gpu_dspark_physical_tensor_sha_matches(
        const ds4_gpu_tensor *tensor,
        uint64_t              bytes,
        const char           *expected,
        const char           *label,
        int                   require_bf16) {
    if (!tensor || bytes == 0 || bytes > SIZE_MAX) return 0;
    uint32_t *values = malloc((size_t)bytes);
    if (!values) return 0;
    int ok = ds4_gpu_tensor_read(tensor, 0, values, bytes) &&
        ds4_gpu_dspark_physical_sha_matches(
            values, (size_t)bytes, expected, label);
    if (ok && require_bf16) {
        const uint64_t count = bytes / sizeof(uint32_t);
        for (uint64_t i = 0; i < count; i++) {
            const uint32_t magnitude = values[i] & UINT32_C(0x7fffffff);
            if ((values[i] & UINT32_C(0x0000ffff)) != 0u ||
                magnitude >= UINT32_C(0x7f800000)) {
                fprintf(stderr,
                        "ds4: DSpark physical %s lane %llu is not finite "
                        "BF16-in-F32: 0x%08x\n",
                        label, (unsigned long long)i, values[i]);
                ok = 0;
                break;
            }
        }
    }
    free(values);
    return ok;
}

static int ds4_gpu_dspark_physical_check_exact_boundaries(
        const ds4_gpu_dspark_physical_tensors *t,
        uint32_t                               committed_count) {
    const uint64_t hidden_bytes =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN * sizeof(float);
    const uint64_t row_bytes =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HIDDEN *
        sizeof(float);
    const uint64_t rank_bytes =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_Q_RANK *
        sizeof(float);
    const uint64_t q_bytes =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEADS *
        DS4_DSPARK_PHYSICAL_HEAD_DIM * sizeof(float);
    const uint64_t kv_bytes =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM *
        sizeof(float);
    const uint64_t output_a_bytes =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_GROUPS *
        DS4_DSPARK_PHYSICAL_OUTPUT_RANK * sizeof(float);
    int ok =
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->hidden_input, hidden_bytes,
            "84b3088e8ba5e270e498bb24ace221c1790a6bedd88eb65351143894366eb870",
            "hidden_input", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->hc_pre_output, row_bytes,
            "ff7b9064c8d35fbc6410e40cac370530dfe492b52e6ffde5c9711d1810092ba3",
            "hc_pre_output", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->attention_normalized, row_bytes,
            "79395379438bf9bdfbf7d56687c193f78ca8db594b3f49a93a496a9de95d3022",
            "attention_normalized", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->q_a, rank_bytes,
            "31ae0c918831c05069b5d78191269416fd97152d2bcfb4ccdbeb12f5c35f2764",
            "q_a", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->q_a_normalized, rank_bytes,
            "e68b314d4beada722e99ab0fc07451cde2c44ff5c28779b8ad82928b8524e37d",
            "q_a_normalized", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->q_b, q_bytes,
            "a21ff121b34184f686f9b1e987bec618f32403ffdafb09514be8a3c104e9c8ba",
            "q_b", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->q_head_normalized, q_bytes,
            "3a16369a4b7563951550e33128a19482b558cdd39d8ec0e1b206ef5fd93be1de",
            "q_head_normalized", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->kv_projected, kv_bytes,
            "748c0b94b250ff8569e9ae06c0ce24de624f301d5dbf13c163ef13aaf80259a1",
            "kv_projected", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->kv_normalized, kv_bytes,
            "fd61dd84c3db71d59d4aeaf85f3f74bf3b74544c7d743d421a28ce747fb87c3a",
            "kv_normalized", 1);
    if (!ok) return 0;

    if (committed_count == 2u) {
        return
            ds4_gpu_dspark_physical_tensor_sha_matches(
                t->kv_stored, kv_bytes,
                "3905eb6d3b0ee06cbdab1f52914f425483e1549cbfebcb68b33c2c8e1d42c03a",
                "C=2 kv_stored", 1) &&
            ds4_gpu_dspark_physical_tensor_sha_matches(
                t->attention_output, q_bytes,
                "4e040df2c259d4f07383a32661e76e7e751d4fb2f2cf6dc18a6a297af1a86484",
                "C=2 attention_output", 1) &&
            ds4_gpu_dspark_physical_tensor_sha_matches(
                t->output_a, output_a_bytes,
                "0abb6633e98af7ddccbb1b1468e469e7c79febb9e954457bc0643f5cb712d130",
                "C=2 output_a", 1) &&
            ds4_gpu_dspark_physical_tensor_sha_matches(
                t->output_b, row_bytes,
                "5596c4de9d19abb8802a1315682c231c03f8db1368e888f17884d5e80239f35f",
                "C=2 output_b", 1) &&
            ds4_gpu_dspark_physical_tensor_sha_matches(
                t->hc_post_output, hidden_bytes,
                "6405889c5b0a836a19700880ea80e1d617deb0b83e784dbf937c015baf289135",
                "C=2 hc_post_output", 1);
    }
    return
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->kv_stored, kv_bytes,
            "754aef76ba986691af72a92819b9563fa191aa7501af41dccc9928e1167b6380",
            "C=128 kv_stored", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->output_a, output_a_bytes,
            "9ee20059b62050e73231bbe74396983e6483337533f37a21bed7744f50fe425e",
            "C=128 output_a", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->output_b, row_bytes,
            "2d169b04ad0e5c20670e5a39daf149f93fbdb3684a3eea772fd8cf26cd7d352b",
            "C=128 output_b", 1) &&
        ds4_gpu_dspark_physical_tensor_sha_matches(
            t->hc_post_output, hidden_bytes,
            "f73b649e92b56e39f3ffe71710800793afff8fb7433a849851613d4555180b9f",
            "C=128 hc_post_output", 1);
}

static int ds4_gpu_dspark_physical_check_host_scales(
        const ds4_gpu_tensor *kv_roped) {
    enum { GROUPS = 7 };
    const uint64_t kv_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t kv_bytes = kv_values * sizeof(float);
    float *kv = malloc((size_t)kv_bytes);
    float scales[DS4_DSPARK_PHYSICAL_ROWS * GROUPS];
    if (!kv) return 0;
    int ok = ds4_gpu_tensor_read(kv_roped, 0, kv, kv_bytes);
    for (uint32_t row = 0; ok && row < DS4_DSPARK_PHYSICAL_ROWS; row++) {
        for (uint32_t group = 0; group < GROUPS; group++) {
            float amax = 1.0e-4f;
            for (uint32_t lane = 0; lane < 64u; lane++) {
                const float value = kv[(uint64_t)row *
                    DS4_DSPARK_PHYSICAL_HEAD_DIM + group * 64u + lane];
                amax = fmaxf(amax, fabsf(value));
            }
            scales[row * GROUPS + group] =
                exp2f(ceilf(log2f(amax / 448.0f)));
        }
    }
    if (ok) {
        ok = ds4_gpu_dspark_physical_sha_matches(
            scales,
            sizeof(scales),
            "57c0e9e040e2ecb200d5b6695df6c53edb9c166cc4552aa32614fbeaeadb6b46",
            "kv_nonrope_scales host reference");
    }
    free(kv);
    return ok;
}

static int ds4_gpu_dspark_physical_compare_bf16_envelope(
        const char  *label,
        const float *actual,
        const float *expected,
        uint64_t     values,
        uint64_t     expected_differences);

static void ds4_gpu_dspark_physical_rope_reference(
        float       *output,
        const float *input,
        uint32_t     position0,
        uint32_t     n_head,
        int          inverse) {
    const uint64_t values =
        DS4_DSPARK_PHYSICAL_ROWS * n_head *
        DS4_DSPARK_PHYSICAL_HEAD_DIM;
    memcpy(output, input, (size_t)values * sizeof(float));
    for (uint32_t row = 0; row < DS4_DSPARK_PHYSICAL_ROWS; row++) {
        const float position = (float)(position0 + row);
        for (uint32_t head = 0; head < n_head; head++) {
            const uint64_t base =
                ((uint64_t)row * n_head + head) *
                DS4_DSPARK_PHYSICAL_HEAD_DIM +
                (DS4_DSPARK_PHYSICAL_HEAD_DIM - DS4_DSPARK_PHYSICAL_ROPE);
            for (uint32_t pair = 0;
                 pair < DS4_DSPARK_PHYSICAL_ROPE / 2u;
                 pair++) {
                const float frequency = 1.0f / powf(
                    10000.0f,
                    (float)(2u * pair) /
                        (float)DS4_DSPARK_PHYSICAL_ROPE);
                const float angle = position * frequency;
                const float cosine = cosf(angle);
                const float sine = inverse ? -sinf(angle) : sinf(angle);
                const float first = input[base + 2u * pair];
                const float second = input[base + 2u * pair + 1u];
                output[base + 2u * pair] =
                    ds4_gpu_dspark_attention_test_bf16(
                        first * cosine - second * sine);
                output[base + 2u * pair + 1u] =
                    ds4_gpu_dspark_attention_test_bf16(
                        first * sine + second * cosine);
            }
        }
    }
}

static int ds4_gpu_dspark_physical_check_forward_rope_envelope(
        const ds4_gpu_dspark_physical_tensors *t,
        uint32_t                               committed_count) {
    const uint64_t q_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEADS *
        DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t kv_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t q_bytes = q_values * sizeof(float);
    const uint64_t kv_bytes = kv_values * sizeof(float);
    float *q_input = malloc((size_t)q_bytes);
    float *q_actual = malloc((size_t)q_bytes);
    float *q_expected = malloc((size_t)q_bytes);
    float *kv_input = malloc((size_t)kv_bytes);
    float *kv_actual = malloc((size_t)kv_bytes);
    float *kv_expected = malloc((size_t)kv_bytes);
    int ok = q_input && q_actual && q_expected &&
        kv_input && kv_actual && kv_expected &&
        ds4_gpu_tensor_read(t->q_head_normalized, 0, q_input, q_bytes) &&
        ds4_gpu_tensor_read(t->q_roped, 0, q_actual, q_bytes) &&
        ds4_gpu_tensor_read(t->kv_normalized, 0, kv_input, kv_bytes) &&
        ds4_gpu_tensor_read(t->kv_roped, 0, kv_actual, kv_bytes);
    if (ok) {
        const uint32_t position0 = committed_count == 2u ? 2u : 130u;
        ds4_gpu_dspark_physical_rope_reference(
            q_expected, q_input, position0,
            DS4_DSPARK_PHYSICAL_HEADS, 0);
        ds4_gpu_dspark_physical_rope_reference(
            kv_expected, kv_input, position0, 1u, 0);
        ok = ds4_gpu_dspark_physical_compare_bf16_envelope(
                 committed_count == 2u
                    ? "C=2 q_roped"
                    : "C=128 q_roped",
                 q_actual, q_expected, q_values,
                 committed_count == 2u ? 0u : UINT64_MAX) &&
             ds4_gpu_dspark_physical_compare_bf16_envelope(
                 committed_count == 2u
                    ? "C=2 kv_roped"
                    : "C=128 kv_roped",
                 kv_actual, kv_expected, kv_values,
                 committed_count == 2u ? 0u : UINT64_MAX);
    }
    free(kv_expected);
    free(kv_actual);
    free(kv_input);
    free(q_expected);
    free(q_actual);
    free(q_input);
    return ok;
}

static int ds4_gpu_dspark_physical_compare_bf16_envelope(
        const char  *label,
        const float *actual,
        const float *expected,
        uint64_t     values,
        uint64_t     expected_differences) {
    uint64_t differences = 0;
    uint64_t first_difference = UINT64_MAX;
    uint64_t worst_lane = UINT64_MAX;
    uint32_t max_code_distance = 0;
    float max_abs = 0.0f;
    for (uint64_t i = 0; i < values; i++) {
        uint32_t actual_bits = 0;
        uint32_t expected_bits = 0;
        memcpy(&actual_bits, actual + i, sizeof(actual_bits));
        memcpy(&expected_bits, expected + i, sizeof(expected_bits));
        const uint32_t actual_magnitude =
            actual_bits & UINT32_C(0x7fffffff);
        if ((actual_bits & UINT32_C(0x0000ffff)) != 0u ||
            actual_magnitude >= UINT32_C(0x7f800000)) {
            fprintf(stderr,
                    "ds4: DSpark physical %s lane %llu is not finite "
                    "BF16-in-F32: 0x%08x\n",
                    label, (unsigned long long)i, actual_bits);
            return 0;
        }
        const uint32_t actual_order =
            ds4_gpu_dspark_attention_test_bf16_order(actual_bits);
        const uint32_t expected_order =
            ds4_gpu_dspark_attention_test_bf16_order(expected_bits);
        const uint32_t distance = actual_order > expected_order
            ? actual_order - expected_order
            : expected_order - actual_order;
        if (distance != 0u) {
            if (first_difference == UINT64_MAX) first_difference = i;
            differences++;
        }
        if (distance > max_code_distance) {
            max_code_distance = distance;
            worst_lane = i;
        }
        max_abs = fmaxf(max_abs, fabsf(actual[i] - expected[i]));
        if (distance > 1u) {
            fprintf(stderr,
                    "ds4: DSpark physical %s lane %llu exceeds one BF16 "
                    "code: got=0x%08x expected=0x%08x distance=%u\n",
                    label, (unsigned long long)i,
                    actual_bits, expected_bits, distance);
            return 0;
        }
    }
    if (differences == 0u) {
        fprintf(stderr,
                "ds4: DSpark physical %s adjacent_bf16=0 max_code=0 "
                "max_abs=%.9g first=N/A worst=N/A\n",
                label, max_abs);
    } else {
        fprintf(stderr,
                "ds4: DSpark physical %s adjacent_bf16=%llu max_code=%u "
                "max_abs=%.9g first=%llu worst=%llu\n",
                label, (unsigned long long)differences, max_code_distance,
                max_abs,
                (unsigned long long)first_difference,
                (unsigned long long)worst_lane);
    }
    return expected_differences == UINT64_MAX ||
        differences == expected_differences;
}

static int ds4_gpu_dspark_physical_check_hc_expand_envelope(
        const ds4_gpu_dspark_physical_tensors *t) {
    const uint64_t hidden_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN;
    float hidden[DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
                 DS4_DSPARK_PHYSICAL_HIDDEN];
    float branch[DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HIDDEN];
    float split[DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC_MIX];
    float actual[DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
                 DS4_DSPARK_PHYSICAL_HIDDEN];
    float expected[DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
                   DS4_DSPARK_PHYSICAL_HIDDEN];
    int ok = ds4_gpu_tensor_read(t->hidden_input, 0, hidden,
                                 sizeof(hidden)) &&
        ds4_gpu_tensor_read(t->output_b, 0, branch, sizeof(branch)) &&
        ds4_gpu_tensor_read(t->hc_split, 0, split, sizeof(split)) &&
        ds4_gpu_tensor_read(t->hc_post_output, 0, actual, sizeof(actual));
    uint64_t asymmetric_pairs = 0;
    for (uint32_t row = 0; ok && row < DS4_DSPARK_PHYSICAL_ROWS; row++) {
        const float *row_split =
            split + row * DS4_DSPARK_PHYSICAL_HC_MIX;
        const float *post = row_split + DS4_DSPARK_PHYSICAL_HC;
        const float *comb = row_split + 2u * DS4_DSPARK_PHYSICAL_HC;
        for (uint32_t dst = 0; dst < DS4_DSPARK_PHYSICAL_HC; dst++) {
            for (uint32_t src = dst + 1u;
                 src < DS4_DSPARK_PHYSICAL_HC;
                 src++) {
                if (comb[dst * DS4_DSPARK_PHYSICAL_HC + src] !=
                    comb[src * DS4_DSPARK_PHYSICAL_HC + dst]) {
                    asymmetric_pairs++;
                }
            }
        }
        for (uint32_t dst = 0; dst < DS4_DSPARK_PHYSICAL_HC; dst++) {
            for (uint32_t dim = 0;
                 dim < DS4_DSPARK_PHYSICAL_HIDDEN;
                 dim++) {
                float acc = branch[row * DS4_DSPARK_PHYSICAL_HIDDEN + dim] *
                    post[dst];
                for (uint32_t src = 0;
                     src < DS4_DSPARK_PHYSICAL_HC;
                     src++) {
                    const float residual = hidden[
                        (row * DS4_DSPARK_PHYSICAL_HC + src) *
                            DS4_DSPARK_PHYSICAL_HIDDEN + dim];
                    acc = fmaf(comb[dst * DS4_DSPARK_PHYSICAL_HC + src],
                               residual, acc);
                }
                expected[
                    (row * DS4_DSPARK_PHYSICAL_HC + dst) *
                        DS4_DSPARK_PHYSICAL_HIDDEN + dim] =
                    ds4_gpu_dspark_attention_test_bf16(acc);
            }
        }
    }
    if (ok) {
        fprintf(stderr,
                "ds4: DSpark physical HC expand asymmetric_pairs=%llu\n",
                (unsigned long long)asymmetric_pairs);
        ok = asymmetric_pairs != 0u;
    }
    return ok && ds4_gpu_dspark_physical_compare_bf16_envelope(
        "HC expand from physical split", actual, expected,
        hidden_values, 0u);
}

static int ds4_gpu_dspark_physical_check_attention_envelope(
        const ds4_gpu_dspark_physical_tensors *t,
        const void                            *model_map,
        const ds4_gpu_dspark_physical_offsets *offsets,
        uint32_t                               committed_count) {
    const uint64_t q_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEADS *
        DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t q_bytes = q_values * sizeof(float);
    const uint64_t ring_values =
        DS4_DSPARK_PHYSICAL_RING_CAP * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t kv_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint32_t n_keys = committed_count + DS4_DSPARK_PHYSICAL_ROWS;
    const uint64_t staged_values =
        (uint64_t)n_keys * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    float *q = malloc((size_t)q_bytes);
    float *ring = malloc((size_t)ring_values * sizeof(float));
    float *kv = malloc((size_t)kv_values * sizeof(float));
    float *staged = malloc((size_t)staged_values * sizeof(float));
    float *actual_attention = malloc((size_t)q_bytes);
    float *expected_attention = malloc((size_t)q_bytes);
    float *actual_inverse = malloc((size_t)q_bytes);
    float *expected_inverse_local = malloc((size_t)q_bytes);
    float *expected_inverse_end_to_end = malloc((size_t)q_bytes);
    int ok = q && ring && kv && staged && actual_attention &&
        expected_attention && actual_inverse && expected_inverse_local &&
        expected_inverse_end_to_end &&
        ds4_gpu_tensor_read(t->q_roped, 0, q, q_bytes) &&
        ds4_gpu_tensor_read(t->ring, 0, ring,
                            ring_values * sizeof(float)) &&
        ds4_gpu_tensor_read(t->kv_stored, 0, kv,
                            kv_values * sizeof(float)) &&
        ds4_gpu_tensor_read(t->attention_output, 0,
                            actual_attention, q_bytes) &&
        ds4_gpu_tensor_read(t->attention_inverse_roped, 0,
                            actual_inverse, q_bytes);
    if (ok) {
        memcpy(staged, ring,
               (size_t)committed_count *
                   DS4_DSPARK_PHYSICAL_HEAD_DIM * sizeof(float));
        memcpy(staged +
                   (uint64_t)committed_count *
                       DS4_DSPARK_PHYSICAL_HEAD_DIM,
               kv,
               (size_t)kv_values * sizeof(float));
        const float *sinks = (const float *)((const uint8_t *)model_map +
                                             offsets->sinks);
        ok = ds4_gpu_dspark_attention_cpu_official_reference(
            expected_attention,
            q,
            staged,
            sinks,
            n_keys,
            DS4_DSPARK_PHYSICAL_HEADS);
    }
    if (ok) {
        ds4_gpu_dspark_physical_rope_reference(
            expected_inverse_local,
            actual_attention,
            committed_count == 2u ? 2u : 130u,
            DS4_DSPARK_PHYSICAL_HEADS,
            1);
        ds4_gpu_dspark_physical_rope_reference(
            expected_inverse_end_to_end,
            expected_attention,
            committed_count == 2u ? 2u : 130u,
            DS4_DSPARK_PHYSICAL_HEADS,
            1);
        /* Metal pow/trigonometry and host libm can straddle a BF16 rounding
         * boundary.  Report the platform-specific lane count but require each
         * lane to be finite BF16 and at most one code away.  The local inverse
         * comparison starts from the physical attention result, separating
         * inverse-RoPE drift from end-to-end attention drift.  Exact pre-RoPE
         * q-head/KV normalization, KV-store, output-A/B, and HC-output checks
         * retain hard data-flow anchors. */
        ok = ds4_gpu_dspark_physical_compare_bf16_envelope(
                 committed_count == 2u
                    ? "C=2 attention_output"
                    : "C=128 attention_output",
                 actual_attention,
                 expected_attention,
                 q_values,
                 UINT64_MAX) &&
             ds4_gpu_dspark_physical_compare_bf16_envelope(
                 committed_count == 2u
                    ? "C=2 inverse_rope local"
                    : "C=128 inverse_rope local",
                 actual_inverse,
                 expected_inverse_local,
                 q_values,
                 UINT64_MAX) &&
             ds4_gpu_dspark_physical_compare_bf16_envelope(
                 committed_count == 2u
                    ? "C=2 inverse_rope end-to-end"
                    : "C=128 inverse_rope end-to-end",
                 actual_inverse,
                 expected_inverse_end_to_end,
                 q_values,
                 UINT64_MAX);
    }
    free(expected_inverse_end_to_end);
    free(expected_inverse_local);
    free(actual_inverse);
    free(expected_attention);
    free(actual_attention);
    free(staged);
    free(kv);
    free(ring);
    free(q);
    return ok;
}

static int ds4_gpu_dspark_physical_check_model_payloads(
        const uint8_t                         *model,
        const ds4_gpu_dspark_physical_offsets *o) {
    const struct {
        const char *label;
        uint64_t offset;
        uint64_t bytes;
        const char *sha;
    } payloads[] = {
        {"hc_function_weight", o->hc_function, 6144u,
         "4ccb8dccef22e4ea75135b33950e1c1d0b27962b83c2149c92ca059622054b99"},
        {"hc_scale", o->hc_scale, 12u,
         "59727b504e27a54d55b2183e4d218ffc4388e9ad46bc149b3fb59b5228349fc2"},
        {"hc_base", o->hc_base, 96u,
         "6810f80a9ad75534de871ddf2477436f611481a1433311f2eceb5a9401e15511"},
        {"attention_norm_weight", o->attention_norm, 128u,
         "d5aa67b0772c9b552f4fbb972085cae582b2c0b47e8f1e38fbadac8638e83771"},
        {"q_a_weight", o->q_a, 1088u,
         "425cea3fa14fe7a5a38d1456908c9152c1d29a67899e9dc34a73d8d5c0d9e688"},
        {"q_a_norm_weight", o->q_a_norm, 128u,
         "b638277a8690e175a9137feff1e43c067f9faf4e2f600caf468fb05b0403b717"},
        {"q_b_weight", o->q_b, 1114112u,
         "383b935ecc401de51e2dbb90c847276664f1bf2dd52642c43217aa83c0e138ed"},
        {"kv_weight", o->kv, 17408u,
         "fedfb98e161898f5d182a7f6d4405b4e80eb5721aede2c1352ed14d651819f0c"},
        {"kv_norm_weight", o->kv_norm, 2048u,
         "1a397dca862f8f5b132e0a5a72de5e81e26ce975c92f95c5cf6498ef733882f0"},
        {"attention_sinks", o->sinks, 256u,
         "c50a37025f0389dc726442d3f2876da4f1e83a6e413dc1985ca28237d8e1bebc"},
        {"output_a_weight", o->output_a, 139264u,
         "640796379d715fd577dd23b5cbd4367e4ef5f6c48e3e7b18b039ac87241bda79"},
        {"output_b_weight", o->output_b, 1088u,
         "da9e31cab8b4fd9bc7e8b2b91f9fa7219c8668eac54ba64739511b39d4fb837d"},
    };
    for (size_t i = 0; i < sizeof(payloads) / sizeof(payloads[0]); i++) {
        if (!ds4_gpu_dspark_physical_sha_matches(
                model + payloads[i].offset,
                (size_t)payloads[i].bytes,
                payloads[i].sha,
                payloads[i].label)) {
            return 0;
        }
    }
    return 1;
}

static int ds4_gpu_dspark_physical_check_dispatch(
        const ds4_gpu_dspark_physical_offsets *o) {
    if (g_dspark_q8_dispatch_capture.count != 9u) {
        fprintf(stderr,
                "ds4: DSpark physical Q8 dispatch count=%u expected=9\n",
                g_dspark_q8_dispatch_capture.count);
        return 0;
    }
    const ds4_gpu_dspark_q8_dispatch_record expected[] = {
        {o->q_a, DS4_GPU_DSPARK_Q8_PATH_GENERIC_MM_HALF_STAGED,
         32u, 32u, 5u, 0u},
        {o->q_b, DS4_GPU_DSPARK_Q8_PATH_GENERIC_MM_HALF_STAGED,
         32u, 32768u, 5u, 0u},
        {o->kv, DS4_GPU_DSPARK_Q8_PATH_GENERIC_MM_HALF_STAGED,
         32u, 512u, 5u, 0u},
        {o->output_a, DS4_GPU_DSPARK_Q8_PATH_DIRECT_GROUPED_MV_F32,
         4096u, 4u, 1u, 8u},
        {o->output_a, DS4_GPU_DSPARK_Q8_PATH_DIRECT_GROUPED_MV_F32,
         4096u, 4u, 1u, 8u},
        {o->output_a, DS4_GPU_DSPARK_Q8_PATH_DIRECT_GROUPED_MV_F32,
         4096u, 4u, 1u, 8u},
        {o->output_a, DS4_GPU_DSPARK_Q8_PATH_DIRECT_GROUPED_MV_F32,
         4096u, 4u, 1u, 8u},
        {o->output_a, DS4_GPU_DSPARK_Q8_PATH_DIRECT_GROUPED_MV_F32,
         4096u, 4u, 1u, 8u},
        {o->output_b, DS4_GPU_DSPARK_Q8_PATH_GENERIC_MM_HALF_STAGED,
         32u, 32u, 5u, 0u},
    };
    for (size_t i = 0; i < sizeof(expected) / sizeof(expected[0]); i++) {
        const ds4_gpu_dspark_q8_dispatch_record *actual =
            &g_dspark_q8_dispatch_capture.records[i];
        if (actual->weight_offset != expected[i].weight_offset ||
            actual->path != expected[i].path ||
            actual->in_dim != expected[i].in_dim ||
            actual->out_dim != expected[i].out_dim ||
            actual->n_tok != expected[i].n_tok ||
            actual->n_groups != expected[i].n_groups) {
            fprintf(stderr,
                    "ds4: DSpark physical Q8 dispatch[%zu] drifted: "
                    "offset=%llu path=%u in=%u out=%u tok=%u groups=%u\n",
                    i, (unsigned long long)actual->weight_offset,
                    actual->path, actual->in_dim, actual->out_dim,
                    actual->n_tok, actual->n_groups);
            return 0;
        }
    }
    return 1;
}

static void ds4_gpu_dspark_physical_hidden_source(float *hidden);
static void ds4_gpu_dspark_physical_ring_source(
        float    *ring,
        uint32_t  committed_count);

static int ds4_gpu_dspark_physical_prepare_case(
        ds4_gpu_dspark_physical_tensors *t,
        float                           *hidden,
        float                           *ring,
        uint32_t                        *published_words,
        uint32_t                         committed_count) {
    const uint64_t hidden_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN;
    const uint64_t hidden_bytes = hidden_values * sizeof(float);
    const uint64_t ring_values =
        DS4_DSPARK_PHYSICAL_RING_CAP * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t ring_bytes = ring_values * sizeof(float);
    ds4_gpu_dspark_physical_hidden_source(hidden);
    ds4_gpu_dspark_physical_ring_source(ring, committed_count);
    for (uint64_t i = 0; i < hidden_values + 2u; i++) {
        published_words[i] = UINT32_C(0x7fc12345);
    }
    const char *ring_sha = committed_count == 2u
        ? "e27748d96d6d36cd5b12f42a710eb76d0e29b27c774fc11d153e9536d4526c9d"
        : "d085299feb54f6010b64b7a7550dbb3b90d4c03c800de9384db0aa2fa36ea338";
    return
        ds4_gpu_dspark_physical_sha_matches(
            hidden,
            (size_t)hidden_bytes,
            "e15d38302793fb96779672dcc38a99ef59b0de2f07ea25c17c348d37335dad57",
            "raw hidden") &&
        ds4_gpu_dspark_physical_sha_matches(
            ring, (size_t)ring_bytes, ring_sha,
            committed_count == 2u ? "C=2 raw ring" : "C=128 raw ring") &&
        ds4_gpu_tensor_write(t->hidden_source, 0, hidden, hidden_bytes) &&
        ds4_gpu_tensor_write(t->ring, 0, ring, ring_bytes) &&
        ds4_gpu_tensor_write(
            t->published_parent, 0, published_words,
            hidden_bytes + 2u * sizeof(uint32_t));
}

static int ds4_gpu_dspark_physical_check_shadow_and_ring(
        const ds4_gpu_dspark_physical_tensors *t,
        const uint32_t                        *published_before,
        uint32_t                              *published_after,
        const float                           *ring_before,
        float                                 *ring_after,
        int                                    expect_publication) {
    const uint64_t hidden_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN;
    const uint64_t hidden_bytes = hidden_values * sizeof(float);
    const uint64_t parent_bytes = hidden_bytes + 2u * sizeof(uint32_t);
    const uint64_t ring_bytes =
        DS4_DSPARK_PHYSICAL_RING_CAP * DS4_DSPARK_PHYSICAL_HEAD_DIM *
        sizeof(float);
    float *hc_post = expect_publication
        ? malloc((size_t)hidden_bytes) : NULL;
    if (ds4_gpu_commands_active() ||
        !ds4_gpu_tensor_read(
            t->published_parent, 0, published_after, parent_bytes) ||
        !ds4_gpu_tensor_read(t->ring, 0, ring_after, ring_bytes) ||
        published_after[0] != UINT32_C(0x7fc12345) ||
        published_after[hidden_values + 1u] != UINT32_C(0x7fc12345) ||
        memcmp(ring_after, ring_before, (size_t)ring_bytes) != 0) {
        free(hc_post);
        return 0;
    }
    const int unchanged = memcmp(
        published_after, published_before, (size_t)parent_bytes) == 0;
    int ok = expect_publication
        ? hc_post != NULL &&
          ds4_gpu_tensor_read(
              t->hc_post_output, 0, hc_post, hidden_bytes) &&
          memcmp(published_after + 1u, hc_post,
                 (size_t)hidden_bytes) == 0
        : unchanged;
    free(hc_post);
    return ok;
}

static int ds4_gpu_dspark_physical_boundary_signature(
        const ds4_gpu_dspark_physical_tensors *t,
        char signature[CC_SHA256_DIGEST_LENGTH * 2u + 1u]) {
    const uint64_t hidden =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN * sizeof(float);
    const uint64_t row =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HIDDEN *
        sizeof(float);
    const uint64_t rank =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_Q_RANK *
        sizeof(float);
    const uint64_t q =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEADS *
        DS4_DSPARK_PHYSICAL_HEAD_DIM * sizeof(float);
    const uint64_t kv =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HEAD_DIM *
        sizeof(float);
    const uint64_t output_a =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_GROUPS *
        DS4_DSPARK_PHYSICAL_OUTPUT_RANK * sizeof(float);
    const struct {
        const ds4_gpu_tensor *tensor;
        uint64_t bytes;
    } entries[] = {
        {t->hidden_input, hidden}, {t->hc_pre_output, row},
        {t->attention_normalized, row}, {t->q_a, rank},
        {t->q_a_normalized, rank}, {t->q_b, q},
        {t->q_head_normalized, q}, {t->q_roped, q},
        {t->kv_projected, kv}, {t->kv_normalized, kv},
        {t->kv_roped, kv}, {t->kv_stored, kv},
        {t->attention_output, q}, {t->attention_inverse_roped, q},
        {t->output_a, output_a}, {t->output_b, row},
        {t->hc_post_output, hidden},
    };
    uint64_t total = 0;
    for (size_t i = 0; i < sizeof(entries) / sizeof(entries[0]); i++) {
        total += entries[i].bytes;
    }
    if (total > SIZE_MAX) return 0;
    uint8_t *all = malloc((size_t)total);
    if (!all) return 0;
    uint64_t cursor = 0;
    int ok = 1;
    for (size_t i = 0;
         ok && i < sizeof(entries) / sizeof(entries[0]);
         i++) {
        ok = ds4_gpu_tensor_read(
            entries[i].tensor, 0, all + cursor, entries[i].bytes);
        cursor += entries[i].bytes;
    }
    if (ok) ds4_gpu_dspark_physical_sha256(all, (size_t)total, signature);
    free(all);
    return ok;
}

static void ds4_gpu_dspark_physical_hidden_source(float *hidden) {
    for (uint32_t token = 0; token < DS4_DSPARK_PHYSICAL_ROWS; token++) {
        for (uint32_t lane = 0; lane < DS4_DSPARK_PHYSICAL_HC; lane++) {
            for (uint32_t dim = 0; dim < DS4_DSPARK_PHYSICAL_HIDDEN; dim++) {
                const uint64_t index =
                    ((uint64_t)token * DS4_DSPARK_PHYSICAL_HC + lane) *
                    DS4_DSPARK_PHYSICAL_HIDDEN + dim;
                const float base = 0.25f +
                    (float)((token * 17u + lane * 11u + dim * 7u) % 17u) /
                    64.0f;
                const float dust = ((token + lane + dim) & 1u) == 0u
                    ? 1.0f / 4096.0f : -1.0f / 4096.0f;
                hidden[index] = base + dust;
            }
        }
    }
}

static void ds4_gpu_dspark_physical_ring_source(
        float    *ring,
        uint32_t  committed_count) {
    const uint64_t values =
        DS4_DSPARK_PHYSICAL_RING_CAP * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    memset(ring, 0, (size_t)values * sizeof(float));
    const uint32_t generated = committed_count == 2u ? 2u : 130u;
    for (uint32_t token = 0; token < generated; token++) {
        const uint32_t physical = token % DS4_DSPARK_PHYSICAL_RING_CAP;
        for (uint32_t dim = 0; dim < DS4_DSPARK_PHYSICAL_HEAD_DIM; dim++) {
            ring[(uint64_t)physical * DS4_DSPARK_PHYSICAL_HEAD_DIM + dim] =
                (float)((token * 19u + dim * 29u) % 113u + 16u) /
                4096.0f;
        }
    }
}

static void *g_dspark_stage0_physical_model_map;
static size_t g_dspark_stage0_physical_model_mapped_bytes;
static void *g_dspark_hc_sigmoid_test_model_map;
static size_t g_dspark_hc_sigmoid_test_model_bytes;

static int ds4_gpu_dspark_physical_model(
        uint8_t                            **model_out,
        ds4_gpu_dspark_physical_offsets     *offsets) {
    if (!model_out || !offsets ||
        !ds4_gpu_dspark_physical_layout(offsets)) {
        return 0;
    }
    const long page_long = sysconf(_SC_PAGESIZE);
    if (page_long <= 0) return 0;
    const size_t page = (size_t)page_long;
    const size_t mapped_bytes =
        (DS4_DSPARK_PHYSICAL_MODEL_BYTES + page - 1u) / page * page;
    if (!g_dspark_stage0_physical_model_map) {
        uint8_t *mapping = mmap(NULL, mapped_bytes,
                                PROT_READ | PROT_WRITE,
                                MAP_PRIVATE | MAP_ANON, -1, 0);
        if (mapping == MAP_FAILED) return 0;
        ds4_gpu_dspark_physical_offsets generated = {0};
        const int generated_ok =
            ds4_gpu_dspark_physical_generate_model(
                mapping, DS4_DSPARK_PHYSICAL_MODEL_BYTES, &generated) &&
            memcmp(&generated, offsets, sizeof(generated)) == 0 &&
            ds4_gpu_dspark_physical_sha_matches(
                mapping,
                DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                "1388a4a205ae61c59a25df4a03af312e2dea1fb13d35f6503362f06dd0ee1492",
                "model blob") &&
            ds4_gpu_dspark_physical_check_model_payloads(mapping, offsets);
        if (!generated_ok ||
            mprotect(mapping, mapped_bytes, PROT_READ) != 0) {
            (void)munmap(mapping, mapped_bytes);
            return 0;
        }
        /* Metal model buffers use newBufferWithBytesNoCopy.  Keep this
         * read-only mapping alive until process exit; unmapping it while a
         * cached view exists would leave a dangling GPU-visible address. */
        g_dspark_stage0_physical_model_map = mapping;
        g_dspark_stage0_physical_model_mapped_bytes = mapped_bytes;
    }
    if (g_dspark_stage0_physical_model_mapped_bytes != mapped_bytes) {
        return 0;
    }
    *model_out = g_dspark_stage0_physical_model_map;
    return 1;
}

static int ds4_gpu_dspark_physical_sigmoid_vectors(
        const uint8_t *physical_model) {
    enum { ROWS = 4, MIX = 24, VALUES = 14 };
    const long page_long = sysconf(_SC_PAGESIZE);
    if (!physical_model || page_long <= 0 || ds4_gpu_commands_active()) {
        return 0;
    }
    const size_t page = (size_t)page_long;
    if (!g_dspark_hc_sigmoid_test_model_map) {
        float *mapping = mmap(NULL, page, PROT_READ | PROT_WRITE,
                              MAP_PRIVATE | MAP_ANON, -1, 0);
        if (mapping == MAP_FAILED) return 0;
        memset(mapping, 0, page);
        mapping[0] = 1.0f;
        mapping[1] = 1.0f;
        mapping[2] = 1.0f;
        if (mprotect(mapping, page, PROT_READ) != 0) {
            (void)munmap(mapping, page);
            return 0;
        }
        g_dspark_hc_sigmoid_test_model_map = mapping;
        g_dspark_hc_sigmoid_test_model_bytes = page;
    }
    if (g_dspark_hc_sigmoid_test_model_bytes != page) return 0;

    static const float inputs[VALUES] = {
        -0.0f, 0.0f,
        -1.0f, 1.0f,
        -10.0f, 10.0f,
        -20.0f, 20.0f,
        -88.0f, 88.0f,
        -90.0f, 90.0f,
        -100.0f, 100.0f,
    };
    float mixes[ROWS * MIX] = {0};
    float actual[ROWS * MIX] = {0};
    for (uint32_t i = 0; i < VALUES; i++) {
        mixes[(i / DS4_DSPARK_PHYSICAL_HC) * MIX +
              i % DS4_DSPARK_PHYSICAL_HC] = inputs[i];
    }
    ds4_gpu_tensor *mix = ds4_gpu_tensor_alloc(sizeof(mixes));
    ds4_gpu_tensor *out = ds4_gpu_tensor_alloc(sizeof(actual));
    int ok = mix && out &&
        ds4_gpu_tensor_write(mix, 0, mixes, sizeof(mixes)) &&
        ds4_gpu_set_model_map(
            g_dspark_hc_sigmoid_test_model_map, page) &&
        ds4_gpu_hc_split_sinkhorn_tensor(
            out,
            mix,
            g_dspark_hc_sigmoid_test_model_map,
            page,
            0u,
            64u,
            DS4_DSPARK_PHYSICAL_HC,
            1u,
            0.0f) &&
        ds4_gpu_tensor_read(out, 0, actual, sizeof(actual));
    float max_abs = 0.0f;
    for (uint32_t i = 0; ok && i < VALUES; i++) {
        const float got = actual[
            (i / DS4_DSPARK_PHYSICAL_HC) * MIX +
            i % DS4_DSPARK_PHYSICAL_HC];
        const double magnitude = fabs((double)inputs[i]);
        const double e = exp(-magnitude);
        const float expected = (float)(inputs[i] < 0.0f
            ? e / (1.0 + e) : 1.0 / (1.0 + e));
        const float error = fabsf(got - expected);
        if (!isfinite(got) || got < 0.0f || got > 1.0f ||
            error > 2.0e-6f) {
            fprintf(stderr,
                    "ds4: DSpark HC stable sigmoid vector[%u] x=%.9g "
                    "got=%.9g expected=%.9g error=%.9g\n",
                    i, inputs[i], got, expected, error);
            ok = 0;
            break;
        }
        max_abs = fmaxf(max_abs, error);
    }
    for (uint32_t pair = 0; ok && pair < VALUES / 2u; pair++) {
        const uint32_t negative_i = pair * 2u;
        const uint32_t positive_i = negative_i + 1u;
        const float negative = actual[
            (negative_i / DS4_DSPARK_PHYSICAL_HC) * MIX +
            negative_i % DS4_DSPARK_PHYSICAL_HC];
        const float positive = actual[
            (positive_i / DS4_DSPARK_PHYSICAL_HC) * MIX +
            positive_i % DS4_DSPARK_PHYSICAL_HC];
        if (fabsf((negative + positive) - 1.0f) > 2.0e-6f) {
            ok = 0;
        }
    }
    fprintf(stderr,
            "ds4: DSpark HC stable sigmoid vectors n=%u max_abs=%.9g "
            "finite/range/symmetry=%s\n",
            VALUES, max_abs, ok ? "yes" : "no");
    const int restore_ok = ds4_gpu_set_model_map(
        physical_model, DS4_DSPARK_PHYSICAL_MODEL_BYTES);
    ds4_gpu_tensor_free(out);
    ds4_gpu_tensor_free(mix);
    return ok && restore_ok;
}

static int ds4_gpu_dspark_physical_run_success(
        ds4_gpu_dspark_physical_tensors       *t,
        const uint8_t                         *model,
        const ds4_gpu_dspark_physical_offsets *offsets,
        float                                 *hidden,
        float                                 *ring,
        uint32_t                              *published_words,
        uint32_t                              *published_actual,
        float                                 *ring_actual,
        uint32_t                               committed_count,
        char                                  *signature) {
    const uint32_t committed_start = committed_count == 2u ? 0u : 2u;
    int ok = ds4_gpu_dspark_physical_prepare_case(
                 t, hidden, ring, published_words, committed_count) &&
             ds4_gpu_dspark_physical_execute(
                 t,
                 model,
                 DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 offsets,
                 committed_count,
                 committed_start,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             ds4_gpu_dspark_physical_check_shadow_and_ring(
                 t, published_words, published_actual,
                 ring, ring_actual, 1) &&
             ds4_gpu_dspark_physical_check_host_scales(t->kv_roped) &&
             ds4_gpu_dspark_physical_check_hc_expand_envelope(t) &&
             ds4_gpu_dspark_physical_check_forward_rope_envelope(
                 t, committed_count) &&
             ds4_gpu_dspark_physical_check_attention_envelope(
                 t, model, offsets, committed_count) &&
             ds4_gpu_dspark_physical_check_exact_boundaries(
                 t, committed_count) &&
             ds4_gpu_dspark_physical_check_dispatch(offsets);
    if (ok && signature) {
        ok = ds4_gpu_dspark_physical_boundary_signature(t, signature);
    }
    return ok;
}

int ds4_gpu_internal_dspark_stage_zero_physical_test(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    uint8_t *model = NULL;
    ds4_gpu_dspark_physical_offsets offsets = {0};
    ds4_gpu_dspark_physical_tensors tensors = {0};
    const uint64_t hidden_values =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_HC *
        DS4_DSPARK_PHYSICAL_HIDDEN;
    const uint64_t hidden_bytes = hidden_values * sizeof(float);
    const uint64_t rank_bytes =
        DS4_DSPARK_PHYSICAL_ROWS * DS4_DSPARK_PHYSICAL_Q_RANK *
        sizeof(float);
    const uint64_t ring_values =
        DS4_DSPARK_PHYSICAL_RING_CAP * DS4_DSPARK_PHYSICAL_HEAD_DIM;
    const uint64_t ring_bytes = ring_values * sizeof(float);
    float *hidden = malloc((size_t)hidden_bytes);
    float *ring = malloc((size_t)ring_bytes);
    uint32_t *published_words = malloc(
        (size_t)(hidden_bytes + 2u * sizeof(uint32_t)));
    uint32_t *published_actual = malloc(
        (size_t)(hidden_bytes + 2u * sizeof(uint32_t)));
    float *ring_actual = malloc((size_t)ring_bytes);
    char c128_first[CC_SHA256_DIGEST_LENGTH * 2u + 1u] = {0};
    char c128_second[CC_SHA256_DIGEST_LENGTH * 2u + 1u] = {0};
    int ok = hidden && ring && published_words && published_actual &&
        ring_actual &&
        ds4_gpu_dspark_physical_model(&model, &offsets) &&
        ds4_gpu_dspark_physical_alloc_tensors(&tensors) &&
        ds4_gpu_set_model_map(model, DS4_DSPARK_PHYSICAL_MODEL_BYTES) &&
        ds4_gpu_dspark_physical_sigmoid_vectors(model);

    /* Reject invalid admission metadata, a truncated model, a non-canonical
     * weight offset, and aliased publications before any command is encoded. */
    if (ok) {
        ds4_gpu_dspark_physical_offsets bad_offsets = offsets;
        bad_offsets.q_a++;
        ds4_gpu_dspark_physical_tensors alias = tensors;
        alias.q_a = alias.attention_normalized;
        ds4_gpu_dspark_physical_tensors null_tensor = tensors;
        null_tensor.q_a = NULL;
        ds4_gpu_dspark_physical_tensors undersized = tensors;
        undersized.q_a = ds4_gpu_tensor_view(
            tensors.q_a, 0, rank_bytes - sizeof(float));
        memset(&g_dspark_q8_dispatch_capture, 0,
               sizeof(g_dspark_q8_dispatch_capture));
        ok = ds4_gpu_dspark_physical_prepare_case(
                 &tensors, hidden, ring, published_words, 2u) &&
             undersized.q_a &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, NULL, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 2u, 0u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 3u, 0u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 2u, 1u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 2u, 0u,
                 (ds4_gpu_dspark_physical_failure)-1) &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 2u, 0u,
                 (ds4_gpu_dspark_physical_failure)
                     (DS4_GPU_DSPARK_PHYSICAL_FAIL_BEFORE_PUBLISH + 1)) &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, model,
                 DS4_DSPARK_PHYSICAL_MODEL_BYTES - 1u,
                 &offsets, 2u, 0u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &bad_offsets, 2u, 0u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             !ds4_gpu_dspark_physical_execute(
                 &alias, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 2u, 0u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             !ds4_gpu_dspark_physical_execute(
                 &null_tensor, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 2u, 0u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             !ds4_gpu_dspark_physical_execute(
                 &undersized, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 2u, 0u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE) &&
             !g_dspark_q8_dispatch_capture.enabled &&
             g_dspark_q8_dispatch_capture.count == 0u &&
             ds4_gpu_dspark_physical_check_shadow_and_ring(
                 &tensors, published_words, published_actual,
                 ring, ring_actual, 0);
        ds4_gpu_tensor_free(undersized.q_a);
    }

    /* A caller-owned command batch is never stolen or drained. */
    if (ok) {
        const uint64_t parent_bytes =
            hidden_bytes + 2u * sizeof(uint32_t);
        int caller_began = 0;
        int rejected = 0;
        int caller_still_active = 0;
        int unchanged_while_active = 0;
        int caller_finished = 0;
        ok = ds4_gpu_dspark_physical_prepare_case(
            &tensors, hidden, ring, published_words, 2u);
        if (ok) caller_began = ds4_gpu_begin_commands();
        if (caller_began) {
            rejected = !ds4_gpu_dspark_physical_execute(
                &tensors, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                &offsets, 2u, 0u,
                DS4_GPU_DSPARK_PHYSICAL_FAIL_NONE);
            caller_still_active = ds4_gpu_commands_active() &&
                !g_dspark_q8_dispatch_capture.enabled &&
                g_dspark_q8_dispatch_capture.count == 0u;
            unchanged_while_active =
                ds4_gpu_tensor_read(
                    tensors.published_parent, 0,
                    published_actual, parent_bytes) &&
                memcmp(published_actual, published_words,
                       (size_t)parent_bytes) == 0 &&
                ds4_gpu_tensor_read(
                    tensors.ring, 0, ring_actual, ring_bytes) &&
                memcmp(ring_actual, ring, (size_t)ring_bytes) == 0;
            if (ds4_gpu_commands_active()) {
                caller_finished = ds4_gpu_end_commands();
            }
        }
        ok = ok && caller_began && rejected && caller_still_active &&
            unchanged_while_active && caller_finished &&
            !ds4_gpu_commands_active();
    }

    /* Both injected failures must drain the batch owned by execute without changing
     * either the public shadow or the committed KV ring. */
    if (ok) {
        ok = ds4_gpu_dspark_physical_prepare_case(
                 &tensors, hidden, ring, published_words, 2u) &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 2u, 0u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_Q_HEAD_ENCODER) &&
             !g_dspark_q8_dispatch_capture.enabled &&
             ds4_gpu_dspark_physical_check_shadow_and_ring(
                 &tensors, published_words, published_actual,
                 ring, ring_actual, 0);
    }
    if (ok) {
        ok = ds4_gpu_dspark_physical_prepare_case(
                 &tensors, hidden, ring, published_words, 128u) &&
             !ds4_gpu_dspark_physical_execute(
                 &tensors, model, DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 &offsets, 128u, 2u,
                 DS4_GPU_DSPARK_PHYSICAL_FAIL_BEFORE_PUBLISH) &&
             !g_dspark_q8_dispatch_capture.enabled &&
             ds4_gpu_dspark_physical_check_shadow_and_ring(
                 &tensors, published_words, published_actual,
                 ring, ring_actual, 0);
    }

    if (ok) {
        ok = ds4_gpu_dspark_physical_run_success(
            &tensors, model, &offsets,
            hidden, ring, published_words, published_actual, ring_actual,
            2u, NULL);
    }
    if (ok) {
        ok = ds4_gpu_dspark_physical_run_success(
            &tensors, model, &offsets,
            hidden, ring, published_words, published_actual, ring_actual,
            128u, c128_first);
    }
    if (ok) {
        ok = ds4_gpu_dspark_physical_run_success(
                 &tensors, model, &offsets,
                 hidden, ring, published_words, published_actual,
                 ring_actual, 128u, c128_second) &&
             strcmp(c128_first, c128_second) == 0;
        if (!ok && strcmp(c128_first, c128_second) != 0) {
            fprintf(stderr,
                    "ds4: DSpark physical C=128 rerun signature drifted "
                    "first=%s second=%s\n",
                    c128_first, c128_second);
        }
    }
    if (ok) {
        ok = ds4_gpu_dspark_physical_sha_matches(
                 model,
                 DS4_DSPARK_PHYSICAL_MODEL_BYTES,
                 "1388a4a205ae61c59a25df4a03af312e2dea1fb13d35f6503362f06dd0ee1492",
                 "model blob after physical runs") &&
             ds4_gpu_dspark_physical_check_model_payloads(model, &offsets);
    }

    ds4_gpu_dspark_physical_free_tensors(&tensors);
    free(ring_actual);
    free(published_actual);
    free(published_words);
    free(ring);
    free(hidden);
    return ok;
}

static int ds4_gpu_dspark_capture_hc_mean_row(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        uint32_t              active_tokens,
        uint32_t              token_index);

typedef enum {
    DS4_GPU_DSPARK_HISTORY_TEST_FAIL_NONE = 0,
    DS4_GPU_DSPARK_HISTORY_TEST_FAIL_CAPTURE_AFTER_FIRST_BLIT,
    DS4_GPU_DSPARK_HISTORY_TEST_FAIL_PUBLISH_AFTER_FIRST_BLIT,
} ds4_gpu_dspark_history_test_failure;

static ds4_gpu_dspark_history_test_failure
    g_dspark_history_test_failure =
        DS4_GPU_DSPARK_HISTORY_TEST_FAIL_NONE;

int ds4_gpu_internal_dspark_dual_store_test(void) {
    const uint64_t file_size = 16u * 1024u;
    const uint64_t model_size = 1024u * 1024u;
    const uint64_t gate_offset = 300u * 1024u;
    const uint64_t up_offset = 301u * 1024u;
    const uint64_t down_offset = 302u * 1024u;
    char path[] = "/tmp/ds4-dspark-dual-store.XXXXXX";
    int fd = mkstemp(path);
    if (fd < 0) return 0;
    (void)unlink(path);
    int ok = ftruncate(fd, (off_t)file_size) == 0 &&
             (g_initialized || ds4_gpu_init());

    const ds4_gpu_expert_store_layer_v2 target = {
        .layer = 0,
        .data_offset = 4096,
        .data_size = 45,
        .record_bytes = 15,
        .component_offset = {0, 3, 8},
        .component_bytes = {3, 5, 7},
    };
    const ds4_gpu_expert_store_layer_v2 support = {
        .layer = 0,
        .data_offset = 8192,
        .data_size = 45,
        .record_bytes = 15,
        .component_offset = {0, 3, 8},
        .component_bytes = {3, 5, 7},
    };
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_TARGET, fd, file_size, 1, 3,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, &target) &&
             g_dspark_expert_pack == NULL;
    }
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, fd, file_size, 1, 3,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, &support) &&
             ds4_gpu_expert_store_v2_bind_layer_for_store(
                 DS4_GPU_EXPERT_STORE_TARGET, 0, model_size,
                 gate_offset, up_offset, down_offset) &&
             ds4_gpu_expert_store_v2_bind_layer_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, 0, model_size,
                 gate_offset, up_offset, down_offset);
    }

    uint64_t target_span = 0;
    uint64_t support_span = 0;
    uint64_t span_size = 0;
    int target_fd = -1;
    int support_fd = -1;
    uint64_t target_source = 0;
    uint64_t support_source = 0;
    if (ok) {
        ok = ds4_gpu_expert_store_v2_layer_span_for_store(
                 DS4_GPU_EXPERT_STORE_TARGET, 0, model_size,
                 &target_span, &span_size) &&
             span_size == target.data_size &&
             ds4_gpu_expert_store_v2_layer_span_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, 0, model_size,
                 &support_span, &span_size) &&
             span_size == support.data_size &&
             target_span == target.data_offset &&
             support_span == support.data_offset &&
             target_span != support_span &&
             ds4_gpu_qwen35_expert_pack_resolve_for_store(
                 DS4_GPU_EXPERT_STORE_TARGET,
                 gate_offset + 2u * target.component_bytes[0],
                 target.component_bytes[0], &target_fd, &target_source) == 1 &&
             ds4_gpu_qwen35_expert_pack_resolve_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT,
                 gate_offset + 2u * support.component_bytes[0],
                 support.component_bytes[0], &support_fd, &support_source) == 1 &&
             target_fd == fd && support_fd == fd &&
             target_source == target.data_offset + 2u * target.record_bytes &&
             support_source == support.data_offset + 2u * support.record_bytes &&
             target_source != support_source;
    }
    if (ok) {
        uint64_t target_after_clear = 0;
        uint64_t target_after_clear_size = 0;
        int target_after_clear_fd = -1;
        uint64_t target_after_clear_source = 0;
        ds4_gpu_expert_store_v2_clear_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT);
        ok = g_dspark_expert_pack == NULL &&
             !ds4_gpu_expert_store_v2_layer_span_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, 0, model_size,
                 &support_span, &span_size) &&
             ds4_gpu_expert_store_v2_layer_span_for_store(
                 DS4_GPU_EXPERT_STORE_TARGET, 0, model_size,
                 &target_after_clear, &target_after_clear_size) &&
             target_after_clear == target.data_offset &&
             target_after_clear_size == target.data_size &&
             ds4_gpu_qwen35_expert_pack_resolve_for_store(
                 DS4_GPU_EXPERT_STORE_TARGET,
                 gate_offset + 2u * target.component_bytes[0],
                 target.component_bytes[0], &target_after_clear_fd,
                 &target_after_clear_source) == 1 &&
             target_after_clear_fd == fd &&
             target_after_clear_source == target_source;
    } else {
        ds4_gpu_expert_store_v2_clear_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT);
    }
    ds4_gpu_expert_store_v2_clear_for_store(DS4_GPU_EXPERT_STORE_TARGET);
    close(fd);
    return ok;
}

enum {
    DS4_DSPARK_SUPPORT_TEST_TARGET_BASE = 64 * 1024,
    DS4_DSPARK_SUPPORT_TEST_SUPPORT_BASE = 3 * 1024 * 1024,
    DS4_DSPARK_SUPPORT_TEST_LAYER_STRIDE = 64 * 1024,
    DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE = 20 * 1024,
};

static int ds4_gpu_internal_dspark_support_bind_target_for_test(
        uint32_t n_layer,
        uint64_t model_size) {
    for (uint32_t layer = 0; layer < n_layer; layer++) {
        const uint64_t base = DS4_DSPARK_SUPPORT_TEST_TARGET_BASE +
            (uint64_t)layer * DS4_DSPARK_SUPPORT_TEST_LAYER_STRIDE;
        if (!ds4_gpu_expert_store_v2_bind_layer_for_store(
                DS4_GPU_EXPERT_STORE_TARGET, layer, model_size,
                base,
                base + DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE,
                base + 2u * DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE)) {
            return 0;
        }
    }
    return 1;
}

static int ds4_gpu_internal_dspark_support_bind_support_for_test(
        uint64_t model_size) {
    for (uint32_t stage = 0;
         stage < DS4_DSPARK_SUPPORT_LAYER_COUNT;
         stage++) {
        const uint64_t base = DS4_DSPARK_SUPPORT_TEST_SUPPORT_BASE +
            (uint64_t)stage * DS4_DSPARK_SUPPORT_TEST_LAYER_STRIDE;
        if (!ds4_gpu_expert_store_v2_bind_layer_for_store(
                DS4_GPU_EXPERT_STORE_SUPPORT, stage, model_size,
                base,
                base + DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE,
                base + 2u * DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE)) {
            return 0;
        }
    }
    return 1;
}

static int ds4_gpu_internal_dspark_support_populate_target_for_test(
        uint32_t count,
        const void *model_identity,
        uint64_t model_size,
        id<MTLBuffer> buffer) {
    if (!model_identity || !buffer || count > 512u ||
        g_stream_expert_cache_entry_count > count) {
        return 0;
    }
    for (uint32_t index = g_stream_expert_cache_entry_count;
         index < count;
         index++) {
        const uint32_t layer = index / DS4_DSPARK_SUPPORT_EXPERT_COUNT;
        const uint32_t expert = index % DS4_DSPARK_SUPPORT_EXPERT_COUNT;
        const ds4_gpu_qwen35_expert_pack_layer *binding =
            &g_qwen35_expert_pack.layers[layer];
        if (!binding->valid ||
            !ds4_gpu_stream_expert_cache_install_loaded(
                model_identity, model_size, layer, expert,
                DS4_DSPARK_SUPPORT_EXPERT_COUNT,
                binding->gate_offset + expert,
                binding->up_offset + expert,
                binding->down_offset + expert,
                1, 1, buffer, buffer, buffer, 0, 1, 2)) {
            return 0;
        }
    }
    return g_stream_expert_cache_entry_count == count;
}

typedef struct {
    __strong id<MTLBuffer> input;
    __strong id<MTLBuffer> output;
    const int32_t *route_ids;
    uint32_t stage;
    uint32_t candidate_rows;
    int fail_after_consumer;
    int host_address_order_ok;
} ds4_gpu_dspark_support_selected_addr_test_context;

static float ds4_gpu_dspark_support_selected_addr_test_half(
        uint16_t bits) {
    const uint32_t exponent = (bits >> 10u) & 0x1fu;
    const uint32_t mantissa = bits & 0x03ffu;
    if (exponent == 0) {
        return ldexpf((float)mantissa, -24);
    }
    return ldexpf(1.0f + (float)mantissa / 1024.0f,
                  (int)exponent - 15);
}

static float ds4_gpu_dspark_support_selected_addr_test_expected(
        uint32_t stage,
        uint32_t expert,
        uint32_t component) {
    static const uint16_t component_base[3] = {
        0x3800u, 0x3c00u, 0x4000u,
    };
    const uint16_t scale_bits = component_base[component] +
        (uint16_t)(stage * 257u + expert);
    /* qs=0 chooses grid[0] (eight +8 values) and sign[0] (all positive).
     * With a 256-wide all-one input, the admitted IQ2 kernel returns 256*d. */
    return 256.0f *
        ds4_gpu_dspark_support_selected_addr_test_half(scale_bits);
}

/* Lifetime/addressability probe only.  It deliberately reuses the qualified
 * production IQ2 selected-address matvec; it does not claim DSpark MoE numeric
 * parity.  The host check proves that sparse expert-keyed tables preserve the
 * separate route list, while the Metal dispatch dereferences the same records. */
static int ds4_gpu_dspark_support_selected_addr_test_encode(
        id<MTLCommandBuffer>                             cb,
        const ds4_gpu_dspark_support_selected_addr_view *view,
        void                                             *opaque) {
    ds4_gpu_dspark_support_selected_addr_test_context *context =
        (ds4_gpu_dspark_support_selected_addr_test_context *)opaque;
    if (!cb || !view || !context || !context->input || !context->output ||
        !context->route_ids ||
        context->candidate_rows == 0 ||
        context->candidate_rows > DS4_DSPARK_SUPPORT_CANDIDATE_ROWS ||
        view->route_count !=
            context->candidate_rows * DS4_DSPARK_SUPPORT_TOP_K ||
        [view->address_buffer length] !=
            DS4_DSPARK_SUPPORT_ADDRESS_VIEW_BYTES ||
        DS4_DSPARK_SUPPORT_ADDRESS_VIEW_BYTES >
            DS4_DSPARK_SUPPORT_ADDRESS_TABLE_PAGE_BYTES ||
        view->component_offset[0] != 0 ||
        view->component_offset[1] !=
            DS4_DSPARK_SUPPORT_EXPERT_COUNT * sizeof(uint64_t) ||
        view->component_offset[2] !=
            2u * DS4_DSPARK_SUPPORT_EXPERT_COUNT * sizeof(uint64_t) ||
        view->ids_offset != DS4_DSPARK_SUPPORT_COMPONENT_ADDRESS_BYTES ||
        memcmp((const uint8_t *)[view->address_buffer contents] +
                   view->ids_offset,
               context->route_ids,
               (size_t)view->route_count * sizeof(context->route_ids[0])) != 0) {
        return 0;
    }

    uint64_t selected_words[DS4_DSPARK_SUPPORT_EXPERT_COUNT / 64u] = {0};
    const uint8_t *table_bytes =
        (const uint8_t *)[view->address_buffer contents];
    const ds4_gpu_qwen35_expert_pack_layer *layer =
        &g_dspark_expert_pack->layers[context->stage];
    context->host_address_order_ok = 1;
    for (uint32_t route = 0; route < view->route_count; route++) {
        const uint32_t expert = (uint32_t)context->route_ids[route];
        selected_words[expert / 64u] |= 1ull << (expert % 64u);
        const ds4_gpu_dspark_support_cache_entry *entry =
            &g_dspark_support_cache[context->stage][expert];
        const uint8_t *record = (const uint8_t *)[entry->buffer contents];
        static const uint16_t component_base[3] = {
            0x3800u, 0x3c00u, 0x4000u,
        };
        if (!record) {
            context->host_address_order_ok = 0;
        } else {
            for (uint32_t component = 0; component < 3; component++) {
                uint16_t sentinel = 0;
                memcpy(&sentinel, record + component * 66u,
                       sizeof(sentinel));
                const uint16_t expected =
                    component_base[component] +
                    (uint16_t)(context->stage * 257u + expert);
                if (sentinel != expected) {
                    context->host_address_order_ok = 0;
                }
            }
        }
        for (uint32_t component = 0; component < 3; component++) {
            const uint64_t *addresses = (const uint64_t *)(
                table_bytes + view->component_offset[component]);
            const uint64_t expected = ds4_gpu_buffer_address(
                entry->buffer,
                (NSUInteger)layer->component_offset[component]);
            if (addresses[expert] != expected || expected == 0) {
                context->host_address_order_ok = 0;
            }
        }
    }
    for (uint32_t expert = 0;
         expert < DS4_DSPARK_SUPPORT_EXPERT_COUNT;
         expert++) {
        const int selected =
            (selected_words[expert / 64u] &
                (1ull << (expert % 64u))) != 0;
        for (uint32_t component = 0; component < 3; component++) {
            const uint64_t *addresses = (const uint64_t *)(
                table_bytes + view->component_offset[component]);
            if (!selected && addresses[expert] != 0) {
                context->host_address_order_ok = 0;
            }
        }
    }
    if (!context->host_address_order_ok ||
        !g_moe_mul_mv_addr_iq2_xxs_pipeline) {
        return 0;
    }

    const ds4_gpu_mul_mv_id_args args =
        ds4_gpu_make_mul_mv_id_args(
            256, 1, DS4_DSPARK_SUPPORT_EXPERT_COUNT,
            66, 66, 1, DS4_DSPARK_SUPPORT_TOP_K,
            context->candidate_rows, 4);
    for (uint32_t component = 0; component < 3; component++) {
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        if (!enc) return 0;
        [enc setComputePipelineState:g_moe_mul_mv_addr_iq2_xxs_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:view->address_buffer
                offset:view->component_offset[component]
               atIndex:1];
        [enc setBuffer:context->input offset:0 atIndex:2];
        [enc setBuffer:context->output
                offset:(NSUInteger)component * view->route_count *
                    sizeof(float)
               atIndex:3];
        [enc setBuffer:view->address_buffer
                offset:view->ids_offset
               atIndex:4];
        [enc useResource:view->address_buffer usage:MTLResourceUsageRead];
        for (uint32_t resource = 0;
             resource < view->resource_count;
             resource++) {
            [enc useResource:view->resources[resource]
                       usage:MTLResourceUsageRead];
        }
        [enc setThreadgroupMemoryLength:
            ds4_gpu_routed_mv_smem(DS4_METAL_TENSOR_IQ2_XXS)
                                atIndex:0];
        [enc dispatchThreadgroups:
                 MTLSizeMake(1, 1, view->route_count)
             threadsPerThreadgroup:MTLSizeMake(32, 2, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (component == 0 && context->fail_after_consumer) return 0;
    }
    return 1;
}

static int ds4_gpu_internal_dspark_support_selected_addr_test(void) {
    const float untouched = -1234567.0f;
    const uint32_t target_entries_before =
        g_stream_expert_cache_entry_count;
    const uint64_t target_hits_before = g_stream_expert_cache_hits;
    const uint64_t target_misses_before = g_stream_expert_cache_misses;
    const uint64_t target_evictions_before = g_stream_expert_cache_evictions;
    const uint64_t target_pread_bytes_before =
        g_stream_expert_cache_pread_bytes;
    int32_t distinct[DS4_DSPARK_SUPPORT_BATCH_MAX];
    for (uint32_t route = 0; route < 27; route++) {
        distinct[route] = (int32_t)route;
    }
    distinct[27] = 29;
    distinct[28] = 30;
    distinct[29] = 255;
    const int32_t duplicates[DS4_DSPARK_SUPPORT_BATCH_MAX] = {
        255, 0, 29, 30, 255, 0,
        29, 30, 0, 255, 29, 30,
        0, 29, 255, 30, 0, 29,
        30, 255, 29, 0, 30, 255,
        255, 30, 29, 0, 255, 30,
    };
    const int32_t invalid[DS4_DSPARK_SUPPORT_TOP_K] = {
        0, 29, 30, 255, 256, 0,
    };
    const NSUInteger input_bytes =
        DS4_DSPARK_SUPPORT_CANDIDATE_ROWS * 256u * sizeof(float);
    const NSUInteger output_bytes =
        3u * DS4_DSPARK_SUPPORT_BATCH_MAX * sizeof(float);
    id<MTLBuffer> input = [g_device newBufferWithLength:input_bytes
                                                options:MTLResourceStorageModeShared];
    id<MTLBuffer> output = [g_device newBufferWithLength:output_bytes
                                                 options:MTLResourceStorageModeShared];
    if (!input || !output) {
        fprintf(stderr, "ds4: DSpark SUPPORT selected-address test allocation failed\n");
        return 0;
    }
    for (uint32_t value = 0;
         value < input_bytes / sizeof(float);
         value++) {
        ((float *)[input contents])[value] = 1.0f;
    }
    [input didModifyRange:NSMakeRange(0, input_bytes)];
    ds4_gpu_dspark_support_cache_clear(0);

    ds4_gpu_dspark_support_selected_addr_test_context context = {
        .input = input,
        .output = output,
        .route_ids = invalid,
        .stage = 1,
        .candidate_rows = 1,
    };
    if (ds4_gpu_dspark_support_selected_addr_transaction(
            context.stage, invalid, context.candidate_rows,
            ds4_gpu_dspark_support_selected_addr_test_encode, &context) ||
        g_stream_expert_cache_lease.active || g_batch_cb ||
        g_dspark_support_cache_entry_count != 0) {
        fprintf(stderr, "ds4: DSpark SUPPORT selected-address invalid-route unwind failed\n");
        return 0;
    }

    for (uint32_t value = 0;
         value < output_bytes / sizeof(float);
         value++) {
        ((float *)[output contents])[value] = untouched;
    }
    [output didModifyRange:NSMakeRange(0, output_bytes)];
    context.route_ids = duplicates;
    context.candidate_rows = DS4_DSPARK_SUPPORT_CANDIDATE_ROWS;
    context.fail_after_consumer = 1;
    context.host_address_order_ok = 0;
    const uint64_t failed_fences_before =
        g_dspark_support_cache_release_sync_fences;
    if (ds4_gpu_dspark_support_selected_addr_transaction(
            context.stage, duplicates, context.candidate_rows,
            ds4_gpu_dspark_support_selected_addr_test_encode, &context) ||
        !context.host_address_order_ok ||
        g_stream_expert_cache_lease.active || g_batch_cb ||
        g_dspark_support_cache_release_sync_fences !=
            failed_fences_before + 1u) {
        fprintf(stderr, "ds4: DSpark SUPPORT selected-address partial-consumer unwind failed\n");
        return 0;
    }
    for (uint32_t route = 0;
         route < DS4_DSPARK_SUPPORT_BATCH_MAX;
         route++) {
        const float gate_value = ((const float *)[output contents])[route];
        const float expected =
            ds4_gpu_dspark_support_selected_addr_test_expected(
                context.stage, (uint32_t)duplicates[route], 0);
        if (gate_value != expected ||
            ((const float *)[output contents])[
                DS4_DSPARK_SUPPORT_BATCH_MAX + route] != untouched ||
            ((const float *)[output contents])[
                2u * DS4_DSPARK_SUPPORT_BATCH_MAX + route] != untouched) {
            fprintf(stderr,
                    "ds4: DSpark SUPPORT selected-address partial output failed route=%u got=%g expected=%g\n",
                    route, gate_value, expected);
            return 0;
        }
    }

    for (uint32_t value = 0;
         value < output_bytes / sizeof(float);
         value++) {
        ((float *)[output contents])[value] = untouched;
    }
    [output didModifyRange:NSMakeRange(0, output_bytes)];
    context.route_ids = distinct;
    context.fail_after_consumer = 0;
    context.host_address_order_ok = 0;
    const uint64_t success_fences_before =
        g_dspark_support_cache_release_sync_fences;
    if (!ds4_gpu_dspark_support_selected_addr_transaction(
            context.stage, distinct, context.candidate_rows,
            ds4_gpu_dspark_support_selected_addr_test_encode, &context) ||
        !context.host_address_order_ok ||
        g_stream_expert_cache_lease.active || g_batch_cb ||
        g_dspark_support_cache_release_sync_fences !=
            success_fences_before + 1u ||
        ds4_gpu_dspark_support_lease_pinned_count() != 0) {
        fprintf(stderr, "ds4: DSpark SUPPORT selected-address success transaction failed\n");
        return 0;
    }
    for (uint32_t route = 0;
         route < DS4_DSPARK_SUPPORT_BATCH_MAX;
         route++) {
        const float gate_value = ((const float *)[output contents])[route];
        const float up_value = ((const float *)[output contents])[
            DS4_DSPARK_SUPPORT_BATCH_MAX + route];
        const float down_value = ((const float *)[output contents])[
            2u * DS4_DSPARK_SUPPORT_BATCH_MAX + route];
        const uint32_t expert = (uint32_t)distinct[route];
        if (gate_value !=
                ds4_gpu_dspark_support_selected_addr_test_expected(
                    context.stage, expert, 0) ||
            up_value !=
                ds4_gpu_dspark_support_selected_addr_test_expected(
                    context.stage, expert, 1) ||
            down_value !=
                ds4_gpu_dspark_support_selected_addr_test_expected(
                    context.stage, expert, 2)) {
            fprintf(stderr,
                    "ds4: DSpark SUPPORT selected-address output failed route=%u expert=%u got=(%g,%g,%g) expected=(%g,%g,%g)\n",
                    route, expert, gate_value, up_value, down_value,
                    ds4_gpu_dspark_support_selected_addr_test_expected(
                        context.stage, expert, 0),
                    ds4_gpu_dspark_support_selected_addr_test_expected(
                        context.stage, expert, 1),
                    ds4_gpu_dspark_support_selected_addr_test_expected(
                        context.stage, expert, 2));
            return 0;
        }
    }
    const int telemetry_ok = g_dspark_support_cache_entry_count ==
               DS4_DSPARK_SUPPORT_CACHE_FLOOR - 1u &&
           g_stream_expert_cache_entry_count == target_entries_before &&
           g_stream_expert_cache_hits == target_hits_before &&
           g_stream_expert_cache_misses == target_misses_before &&
           g_stream_expert_cache_evictions == target_evictions_before &&
           g_stream_expert_cache_pread_bytes == target_pread_bytes_before;
    if (!telemetry_ok) {
        fprintf(stderr, "ds4: DSpark SUPPORT selected-address TARGET telemetry isolation failed\n");
    }
    return telemetry_ok;
}

typedef struct {
    uint64_t lease_id;
    int result;
} ds4_gpu_dspark_support_wrong_owner_args;

static void *ds4_gpu_dspark_support_wrong_owner_release(void *opaque) {
    ds4_gpu_dspark_support_wrong_owner_args *args =
        (ds4_gpu_dspark_support_wrong_owner_args *)opaque;
    args->result =
        ds4_gpu_dspark_support_cache_release_stage_lease(args->lease_id);
    return NULL;
}

static int ds4_gpu_internal_dspark_support_lease_behavior_test(
        int                                  support_fd,
        uint64_t                             file_size,
        uint64_t                             model_size,
        const ds4_gpu_expert_store_layer_v2 *support_layers) {
    unsigned step = 0;
    uint64_t lease = 0;
    uint64_t target_lease = 0;
    uint64_t previous_lease = 0;
    uint64_t competing_lease = 0;
    uint32_t unique = 0;
    int32_t ids[DS4_DSPARK_SUPPORT_BATCH_MAX];
    id<MTLBuffer> event_result = nil;
    id<MTLBlitCommandEncoder> event_blit = nil;
    id<MTLBuffer> sync_result = nil;
    id<MTLBlitCommandEncoder> sync_blit = nil;

#define DS4_DSPARK_SUPPORT_TEST_REQUIRE(condition) \
    do { \
        if (!(condition)) { \
            step = __LINE__; \
            goto failed; \
        } \
    } while (0)

    ds4_gpu_dspark_support_cache_clear(1);
    ds4_gpu_set_streaming_expert_cache_budget(289);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !ds4_gpu_dspark_support_cache_acquire_stage_lease(0, &lease) &&
        lease == 0);
    ds4_gpu_set_streaming_expert_cache_budget(290);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_acquire_stage_lease(0, &lease) &&
        lease != 0);
    previous_lease = lease;

    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !ds4_gpu_stream_expert_cache_release_layer_lease(lease) &&
        g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_SUPPORT);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !ds4_gpu_dspark_support_cache_release_stage_lease(lease + 1u) &&
        g_stream_expert_cache_lease.active &&
        !ds4_gpu_dspark_support_cache_acquire_stage_lease(
            1, &competing_lease) &&
        competing_lease == 0);

    ds4_gpu_dspark_support_wrong_owner_args wrong_owner = {
        .lease_id = lease,
        .result = 1,
    };
    pthread_t wrong_thread;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        pthread_create(&wrong_thread, NULL,
                       ds4_gpu_dspark_support_wrong_owner_release,
                       &wrong_owner) == 0);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        pthread_join(wrong_thread, NULL) == 0 &&
        !wrong_owner.result && g_stream_expert_cache_lease.active);

    const uint32_t saved_parent = g_stream_expert_cache_budget_override;
    const uint32_t saved_floor = g_stream_expert_cache_required_floor;
    const uint64_t saved_support_generation =
        g_dspark_support_pack_generation;
    ds4_gpu_set_streaming_expert_cache_budget(289);
    ds4_gpu_set_streaming_expert_cache_required_floor(1);
    ds4_gpu_expert_store_v2_clear_for_store(DS4_GPU_EXPERT_STORE_SUPPORT);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        g_stream_expert_cache_budget_override == saved_parent &&
        g_stream_expert_cache_required_floor == saved_floor &&
        g_dspark_expert_pack &&
        g_dspark_support_pack_generation == saved_support_generation &&
        !ds4_gpu_grow_streaming_expert_cache_budget(320) &&
        !ds4_gpu_reconfigure_streaming_expert_cache_budget(289) &&
        !ds4_gpu_expert_store_v2_enable_resident() &&
        !ds4_gpu_expert_store_v2_install_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT, support_fd, file_size,
            DS4_DSPARK_SUPPORT_LAYER_COUNT,
            DS4_DSPARK_SUPPORT_EXPERT_COUNT,
            DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers) &&
        !ds4_gpu_expert_store_v2_bind_layer_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT, 0, model_size,
            DS4_DSPARK_SUPPORT_TEST_SUPPORT_BASE,
            DS4_DSPARK_SUPPORT_TEST_SUPPORT_BASE +
                DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE,
            DS4_DSPARK_SUPPORT_TEST_SUPPORT_BASE +
                2u * DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE));

    const int32_t duplicates[] = {3, 3, 4, 4};
    const uint32_t target_entries_before =
        g_stream_expert_cache_entry_count;
    const uint64_t target_hits_before = g_stream_expert_cache_hits;
    const uint64_t target_misses_before = g_stream_expert_cache_misses;
    const uint64_t target_evictions_before = g_stream_expert_cache_evictions;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, duplicates,
            (uint32_t)(sizeof(duplicates) / sizeof(duplicates[0])),
            &unique) &&
        unique == 2 &&
        ds4_gpu_dspark_support_lease_pinned_count() == 2 &&
        g_dspark_support_cache_entry_count == 2);

    const int32_t invalid[] = {5, 256, 6};
    const uint32_t support_entries_before_invalid =
        g_dspark_support_cache_entry_count;
    const uint64_t support_pread_before_invalid =
        g_dspark_support_cache_pread_bytes;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, invalid,
            (uint32_t)(sizeof(invalid) / sizeof(invalid[0])), &unique) &&
        unique == 0 &&
        g_dspark_support_cache_entry_count ==
            support_entries_before_invalid &&
        g_dspark_support_cache_pread_bytes == support_pread_before_invalid);

    for (uint32_t expert = 0;
         expert < DS4_DSPARK_SUPPORT_BATCH_MAX;
         expert++) {
        ids[expert] = (int32_t)expert;
    }
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, ids, DS4_DSPARK_SUPPORT_BATCH_MAX, &unique) &&
        unique == DS4_DSPARK_SUPPORT_BATCH_MAX &&
        ds4_gpu_dspark_support_lease_pinned_count() ==
            DS4_DSPARK_SUPPORT_BATCH_MAX &&
        g_dspark_support_cache_entry_count ==
            DS4_DSPARK_SUPPORT_BATCH_MAX);
    const int32_t thirty_first = 30;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, &thirty_first, 1, &unique) &&
        unique == 0 &&
        ds4_gpu_dspark_support_lease_pinned_count() ==
            DS4_DSPARK_SUPPORT_BATCH_MAX &&
        g_stream_expert_cache_entry_count == target_entries_before &&
        g_stream_expert_cache_hits == target_hits_before &&
        g_stream_expert_cache_misses == target_misses_before &&
        g_stream_expert_cache_evictions == target_evictions_before);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_release_stage_lease(lease));
    lease = 0;

    const uint64_t saved_expert_bytes =
        g_stream_expert_cache_expert_bytes;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_stream_expert_cache_acquire_layer_lease(
            0, &target_lease) &&
        target_lease != 0);
    ds4_gpu_set_streaming_expert_cache_required_floor(saved_floor);
    ds4_gpu_set_streaming_expert_cache_expert_bytes(
        saved_expert_bytes + 1u);
    ds4_gpu_set_glm_model(false);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !g_glm_model_mode &&
        g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
        g_stream_expert_cache_required_floor == saved_floor &&
        g_stream_expert_cache_expert_bytes == saved_expert_bytes + 1u &&
        ds4_gpu_grow_streaming_expert_cache_budget(320) &&
        g_stream_expert_cache_budget_override == 320 &&
        ds4_gpu_expert_store_v2_bind_layer_for_store(
            DS4_GPU_EXPERT_STORE_TARGET, 0, model_size,
            DS4_DSPARK_SUPPORT_TEST_TARGET_BASE,
            DS4_DSPARK_SUPPORT_TEST_TARGET_BASE +
                DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE,
            DS4_DSPARK_SUPPORT_TEST_TARGET_BASE +
                2u * DS4_DSPARK_SUPPORT_TEST_COMPONENT_STRIDE));
    ds4_gpu_set_streaming_expert_cache_expert_bytes(saved_expert_bytes);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        g_stream_expert_cache_expert_bytes == saved_expert_bytes &&
        ds4_gpu_stream_expert_cache_release_layer_lease(target_lease));
    target_lease = 0;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_reconfigure_streaming_expert_cache_budget(290));

    ds4_gpu_dspark_support_cache_clear(0);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_acquire_stage_lease(2, &lease));
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, ids, DS4_DSPARK_SUPPORT_BATCH_MAX - 1u, &unique) &&
        unique == DS4_DSPARK_SUPPORT_BATCH_MAX - 1u &&
        ds4_gpu_dspark_support_lease_pinned_count() ==
            DS4_DSPARK_SUPPORT_BATCH_MAX - 1u &&
        g_dspark_support_cache_entry_count ==
            DS4_DSPARK_SUPPORT_BATCH_MAX - 1u);
    const int32_t failed_thirtieth = 29;
    const uint64_t rollbacks_before =
        g_dspark_support_cache_batch_rollbacks;
    g_dspark_support_cache_test_fail_task = 0;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, &failed_thirtieth, 1, &unique) &&
        unique == 0 &&
        ds4_gpu_dspark_support_lease_pinned_count() ==
            DS4_DSPARK_SUPPORT_BATCH_MAX - 1u &&
        g_dspark_support_cache_entry_count ==
            DS4_DSPARK_SUPPORT_BATCH_MAX - 1u &&
        !g_dspark_support_cache[2][29].valid &&
        g_dspark_support_cache_batch_rollbacks == rollbacks_before + 1u);
    g_dspark_support_cache_test_fail_task = -1;
    const int32_t replacement_thirtieth = 30;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, &replacement_thirtieth, 1, &unique) &&
        unique == 1 &&
        ds4_gpu_dspark_support_lease_pinned_count() ==
            DS4_DSPARK_SUPPORT_BATCH_MAX &&
        g_dspark_support_cache_entry_count ==
            DS4_DSPARK_SUPPORT_BATCH_MAX &&
        g_dspark_support_cache[2][30].valid &&
        ds4_gpu_dspark_support_cache_release_stage_lease(lease));
    lease = 0;

    const int32_t old_ids[] = {200, 201};
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_acquire_stage_lease(0, &lease) &&
        ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, old_ids,
            (uint32_t)(sizeof(old_ids) / sizeof(old_ids[0])), &unique) &&
        ds4_gpu_dspark_support_cache_release_stage_lease(lease));
    lease = 0;
    const uint64_t evictions_before = g_dspark_support_cache_evictions;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_acquire_stage_lease(2, &lease) &&
        ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, ids, DS4_DSPARK_SUPPORT_BATCH_MAX, &unique) &&
        unique == DS4_DSPARK_SUPPORT_BATCH_MAX &&
        g_dspark_support_cache_entry_count ==
            DS4_DSPARK_SUPPORT_CACHE_FLOOR &&
        g_dspark_support_cache_evictions == evictions_before + 2u &&
        !g_dspark_support_cache[0][200].valid &&
        g_dspark_support_cache[0][201].valid);

    event_result = [g_device newBufferWithLength:3
                                         options:MTLResourceStorageModeShared];
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(event_result != nil);
    memset([event_result contents], 0, 3);
    [event_result didModifyRange:NSMakeRange(0, 3)];
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(ds4_gpu_begin_commands() != 0);
    ds4_gpu_close_batch_encoder();
    event_blit = [g_batch_cb blitCommandEncoder];
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(event_blit != nil);
    [event_blit copyFromBuffer:g_dspark_support_cache[2][0].buffer
                  sourceOffset:0
                      toBuffer:event_result
             destinationOffset:0
                          size:3];
    [event_blit endEncoding];
    g_batch_has_work = YES;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_lease_note_current_batch_use());
    const uint64_t already_completed_fences_before =
        g_dspark_support_cache_release_already_completed_fences;
    uint64_t event_value = 0;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_signal_selected_readback_ready(&event_value) &&
        ds4_gpu_commit_and_wait_selected_readback(
            event_value, "DSpark SUPPORT lease test") &&
        ds4_gpu_dspark_support_cache_release_stage_lease(lease) &&
        g_dspark_support_cache_release_already_completed_fences ==
            already_completed_fences_before + 1u &&
        ((const uint8_t *)[event_result contents])[0] == 2u);
    lease = 0;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(ds4_gpu_synchronize());

    ds4_gpu_dspark_support_cache_clear(0);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_acquire_stage_lease(1, &lease));
    const int32_t sync_id = 7;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_load_stage_lease(
            lease, &sync_id, 1, &unique));
    sync_result = [g_device newBufferWithLength:3
                                        options:MTLResourceStorageModeShared];
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(sync_result != nil);
    memset([sync_result contents], 0, 3);
    [sync_result didModifyRange:NSMakeRange(0, 3)];
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(ds4_gpu_begin_commands() != 0);
    ds4_gpu_close_batch_encoder();
    sync_blit = [g_batch_cb blitCommandEncoder];
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(sync_blit != nil);
    [sync_blit copyFromBuffer:g_dspark_support_cache[1][7].buffer
                 sourceOffset:0
                     toBuffer:sync_result
            destinationOffset:0
                         size:3];
    [sync_blit endEncoding];
    g_batch_has_work = YES;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_lease_note_current_batch_use());
    const uint64_t sync_fences_before =
        g_dspark_support_cache_release_sync_fences;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_release_stage_lease(lease) &&
        g_dspark_support_cache_release_sync_fences ==
            sync_fences_before + 1u &&
        ((const uint8_t *)[sync_result contents])[0] ==
            8u);
    lease = 0;

    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_dspark_support_cache_acquire_stage_lease(0, &lease));
    const int saved_pool_initialized =
        g_stream_expert_pread_pool_initialized;
    g_stream_expert_pending_load.active = 1;
    g_stream_expert_pread_pool_initialized = 0;
    const int failed_release_ok =
        ds4_gpu_dspark_support_cache_release_stage_lease(lease);
    g_stream_expert_pread_pool_initialized = saved_pool_initialized;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !failed_release_ok &&
        !g_stream_expert_cache_lease.active &&
        !g_stream_expert_pending_load.active);
    lease = 0;

    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !ds4_gpu_dspark_support_cache_release_stage_lease(previous_lease));

    const uint64_t generation_before_clear =
        g_dspark_support_pack_generation;
    ds4_gpu_expert_store_v2_clear_for_store(DS4_GPU_EXPERT_STORE_SUPPORT);
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        !g_dspark_expert_pack &&
        g_dspark_support_pack_generation != generation_before_clear);
    const uint64_t generation_after_clear =
        g_dspark_support_pack_generation;
    DS4_DSPARK_SUPPORT_TEST_REQUIRE(
        ds4_gpu_expert_store_v2_install_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT, support_fd, file_size,
            DS4_DSPARK_SUPPORT_LAYER_COUNT,
            DS4_DSPARK_SUPPORT_EXPERT_COUNT,
            DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers) &&
        g_dspark_support_pack_generation != generation_after_clear &&
        ds4_gpu_internal_dspark_support_bind_support_for_test(model_size) &&
        ds4_gpu_dspark_support_cache_combined_available() &&
        ds4_gpu_internal_dspark_support_selected_addr_test());

#undef DS4_DSPARK_SUPPORT_TEST_REQUIRE
    return 1;

failed:
    g_dspark_support_cache_test_fail_task = -1;
    if (target_lease != 0 && g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
        pthread_equal(g_stream_expert_cache_lease.owner, pthread_self())) {
        (void)ds4_gpu_stream_expert_cache_release_layer_lease(target_lease);
    }
    if (lease != 0 && g_stream_expert_cache_lease.active &&
        pthread_equal(g_stream_expert_cache_lease.owner, pthread_self())) {
        if (g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_SUPPORT) {
            (void)ds4_gpu_dspark_support_cache_release_stage_lease(lease);
        } else {
            (void)ds4_gpu_stream_expert_cache_release_layer_lease(lease);
        }
    }
    fprintf(stderr,
            "ds4: DSpark SUPPORT lease behavior test failed at line %u\n",
            step);
#undef DS4_DSPARK_SUPPORT_TEST_REQUIRE
    return 0;
}

int ds4_gpu_internal_dspark_support_cache_test(void) {
    enum {
        FILE_SIZE = 4 * 1024 * 1024,
        MODEL_SIZE = 4 * 1024 * 1024,
        IQ2_BLOCK_BYTES = 66,
        RECORD_BYTES = 3 * IQ2_BLOCK_BYTES,
        TARGET_LAYER_COUNT = DS4_DSPARK_TARGET_LAYER_COUNT,
        TARGET_RECORD_BYTES = RECORD_BYTES,
        TARGET_LAYER_BYTES =
            DS4_DSPARK_SUPPORT_EXPERT_COUNT * TARGET_RECORD_BYTES,
        SUPPORT_LAYER_BYTES =
            DS4_DSPARK_SUPPORT_EXPERT_COUNT * RECORD_BYTES,
    };
    char path[] = "/tmp/ds4-dspark-support-cache.XXXXXX";
    char other_path[] = "/tmp/ds4-dspark-support-other.XXXXXX";
    int fd = -1;
    int target_fd = -1;
    int support_fd = -1;
    int other_fd = -1;
    uint8_t *support_bytes = NULL;
    int ok = (!g_initialized && !ds4_gpu_init()) || g_initialized;
    if (!ok || g_qwen35_expert_pack.active || g_dspark_expert_pack) {
        return 0;
    }

    fd = mkstemp(path);
    if (fd < 0) return 0;
    (void)unlink(path);
    ok = ftruncate(fd, FILE_SIZE) == 0;
    if (ok) {
        target_fd = fcntl(fd, F_DUPFD_CLOEXEC, 0);
        support_fd = fcntl(fd, F_DUPFD_CLOEXEC, 0);
        other_fd = mkstemp(other_path);
        if (other_fd >= 0) (void)unlink(other_path);
        ok = target_fd >= 0 && support_fd >= 0 &&
             target_fd != support_fd && other_fd >= 0 &&
             ftruncate(other_fd, FILE_SIZE) == 0;
    }

    ds4_gpu_expert_store_layer_v2 target_layers[TARGET_LAYER_COUNT];
    memset(target_layers, 0, sizeof(target_layers));
    for (uint32_t layer = 0; layer < TARGET_LAYER_COUNT; layer++) {
        target_layers[layer].layer = layer;
        target_layers[layer].data_offset = 256u * 1024u +
            (uint64_t)layer * TARGET_LAYER_BYTES;
        target_layers[layer].data_size = TARGET_LAYER_BYTES;
        target_layers[layer].record_bytes = TARGET_RECORD_BYTES;
        target_layers[layer].component_offset[0] = 0;
        target_layers[layer].component_offset[1] = IQ2_BLOCK_BYTES;
        target_layers[layer].component_offset[2] = 2u * IQ2_BLOCK_BYTES;
        target_layers[layer].component_bytes[0] = IQ2_BLOCK_BYTES;
        target_layers[layer].component_bytes[1] = IQ2_BLOCK_BYTES;
        target_layers[layer].component_bytes[2] = IQ2_BLOCK_BYTES;
    }
    ds4_gpu_expert_store_layer_v2 support_layers[
        DS4_DSPARK_SUPPORT_LAYER_COUNT];
    memset(support_layers, 0, sizeof(support_layers));
    for (uint32_t stage = 0;
         stage < DS4_DSPARK_SUPPORT_LAYER_COUNT;
         stage++) {
        support_layers[stage].layer = stage;
        support_layers[stage].data_offset = 4096u +
            (uint64_t)stage * SUPPORT_LAYER_BYTES;
        support_layers[stage].data_size = SUPPORT_LAYER_BYTES;
        support_layers[stage].record_bytes = RECORD_BYTES;
        support_layers[stage].component_offset[0] = 0;
        support_layers[stage].component_offset[1] = IQ2_BLOCK_BYTES;
        support_layers[stage].component_offset[2] = 2u * IQ2_BLOCK_BYTES;
        support_layers[stage].component_bytes[0] = IQ2_BLOCK_BYTES;
        support_layers[stage].component_bytes[1] = IQ2_BLOCK_BYTES;
        support_layers[stage].component_bytes[2] = IQ2_BLOCK_BYTES;
    }

    support_bytes = malloc(
        (size_t)SUPPORT_LAYER_BYTES * DS4_DSPARK_SUPPORT_LAYER_COUNT);
    if (!support_bytes) ok = 0;
    for (uint32_t stage = 0;
         ok && stage < DS4_DSPARK_SUPPORT_LAYER_COUNT;
         stage++) {
        uint8_t *stage_bytes = support_bytes +
            (size_t)stage * SUPPORT_LAYER_BYTES;
        for (uint32_t expert = 0;
             expert < DS4_DSPARK_SUPPORT_EXPERT_COUNT;
             expert++) {
            uint8_t *record = stage_bytes + expert * RECORD_BYTES;
            memset(record, 0, RECORD_BYTES);
            static const uint16_t component_base[3] = {
                0x3800u, 0x3c00u, 0x4000u,
            };
            for (uint32_t component = 0; component < 3; component++) {
                const uint16_t sentinel =
                    component_base[component] +
                    (uint16_t)(stage * 257u + expert);
                memcpy(record + component * IQ2_BLOCK_BYTES,
                       &sentinel,
                       sizeof(sentinel));
            }
        }
        ok = ds4_gpu_internal_qwen35_expert_pack_pwrite_all(
            fd, stage_bytes, SUPPORT_LAYER_BYTES,
            support_layers[stage].data_offset);
    }

    ds4_gpu_set_ssd_streaming(true);
    ds4_gpu_set_streaming_expert_cache_required_floor(
        DS4_DSPARK_TARGET_CACHE_FLOOR);
    ds4_gpu_set_streaming_expert_cache_budget(0);
    if (ok) {
        ok = ds4_gpu_stream_expert_cache_parent_budget(0) == 0 &&
             ds4_gpu_stream_expert_cache_configured_budget() == 0 &&
             ds4_gpu_dspark_support_cache_get_for_test(0, 0) == NULL &&
             ds4_gpu_dspark_support_cache_configured_budget() == 0;
    }
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_TARGET, target_fd, FILE_SIZE,
                 TARGET_LAYER_COUNT,
                 DS4_DSPARK_SUPPORT_EXPERT_COUNT,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, target_layers) &&
             ds4_gpu_internal_dspark_support_bind_target_for_test(
                 TARGET_LAYER_COUNT, MODEL_SIZE) &&
             ds4_gpu_dspark_support_cache_get_for_test(0, 0) == NULL &&
             ds4_gpu_dspark_support_cache_configured_budget() == 0;
    }
    /* A TARGET lease must not inherit the SUPPORT-only model-mode guard.
     * Exercise a real false->true->false toggle while SUPPORT is absent, so
     * combined availability and reconcile rollback cannot mask the result. */
    uint64_t target_mode_lease = 0;
    ds4_gpu_set_streaming_expert_cache_budget(290);
    if (ok) {
        ok = !g_glm_model_mode &&
             !ds4_gpu_dspark_support_cache_combined_available() &&
             ds4_gpu_stream_expert_cache_acquire_layer_lease(
                 0, &target_mode_lease) &&
             target_mode_lease != 0;
    }
    ds4_gpu_set_glm_model(true);
    const int target_mode_true_ok = target_mode_lease != 0 &&
        g_glm_model_mode &&
        g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
        g_stream_expert_cache_lease.id == target_mode_lease;
    ds4_gpu_set_glm_model(false);
    const int target_mode_false_ok = target_mode_lease != 0 &&
        !g_glm_model_mode &&
        g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
        g_stream_expert_cache_lease.id == target_mode_lease;
    const int target_mode_release_ok = target_mode_lease != 0 &&
        ds4_gpu_stream_expert_cache_release_layer_lease(target_mode_lease);
    if (ok) {
        ok = target_mode_true_ok && target_mode_false_ok &&
             target_mode_release_ok;
    }
    target_mode_lease = 0;
    ds4_gpu_set_streaming_expert_cache_budget(0);
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, other_fd, FILE_SIZE,
                 DS4_DSPARK_SUPPORT_LAYER_COUNT,
                 DS4_DSPARK_SUPPORT_EXPERT_COUNT,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers) &&
             ds4_gpu_internal_dspark_support_bind_support_for_test(
                 MODEL_SIZE) &&
             !ds4_gpu_dspark_support_cache_combined_available() &&
             ds4_gpu_dspark_support_cache_configured_budget() == 0 &&
             ds4_gpu_dspark_support_cache_get_for_test(0, 0) == NULL;
    }
    if (g_dspark_expert_pack) {
        ds4_gpu_expert_store_v2_clear_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT);
    }
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, support_fd, FILE_SIZE,
                 DS4_DSPARK_SUPPORT_LAYER_COUNT,
                 DS4_DSPARK_SUPPORT_EXPERT_COUNT,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers) &&
             ds4_gpu_internal_dspark_support_bind_support_for_test(
                 MODEL_SIZE + 1) &&
             !ds4_gpu_dspark_support_cache_combined_available() &&
             ds4_gpu_dspark_support_cache_configured_budget() == 0;
    }
    if (g_dspark_expert_pack) {
        ds4_gpu_expert_store_v2_clear_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT);
    }
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, support_fd, FILE_SIZE,
                 DS4_DSPARK_SUPPORT_LAYER_COUNT,
            DS4_DSPARK_SUPPORT_EXPERT_COUNT,
            DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers) &&
             ds4_gpu_internal_dspark_support_bind_support_for_test(
                 MODEL_SIZE) &&
             ds4_gpu_dspark_support_cache_combined_available() &&
             ds4_gpu_stream_expert_cache_parent_budget(0) == 0 &&
             ds4_gpu_stream_expert_cache_configured_budget() == 0 &&
             ds4_gpu_dspark_support_cache_configured_budget() == 0 &&
             g_stream_expert_cache_slab_count == 0 &&
             g_stream_expert_cache_slab_total_slots == 0 &&
             g_stream_expert_cache_entry_count == 0 &&
             g_dspark_support_cache_entry_count == 0;
    }
    if (ok) {
        uint64_t saved_record_bytes[DS4_DSPARK_SUPPORT_LAYER_COUNT];
        for (uint32_t stage = 0;
             stage < DS4_DSPARK_SUPPORT_LAYER_COUNT; stage++) {
            saved_record_bytes[stage] =
                g_dspark_expert_pack->layers[stage].record_bytes;
            g_dspark_expert_pack->layers[stage].record_bytes =
                saved_record_bytes[stage] + 1u;
        }
        ok = !ds4_gpu_dspark_support_cache_combined_available();
        for (uint32_t stage = 0;
             stage < DS4_DSPARK_SUPPORT_LAYER_COUNT; stage++) {
            g_dspark_expert_pack->layers[stage].record_bytes =
                saved_record_bytes[stage];
        }
        ok = ok && ds4_gpu_dspark_support_cache_combined_available();
    }
    if (ok) {
        g_qwen35_expert_pack.n_layer = TARGET_LAYER_COUNT + 1;
        g_qwen35_expert_pack.bound_layers = TARGET_LAYER_COUNT + 1;
        ok = !ds4_gpu_dspark_support_cache_combined_available();
        g_qwen35_expert_pack.n_layer = TARGET_LAYER_COUNT;
        g_qwen35_expert_pack.bound_layers = TARGET_LAYER_COUNT;
    }

    id<MTLBuffer> target_buffer =
        [g_device newBufferWithLength:3 options:MTLResourceStorageModeShared];
    if (target_buffer) {
        memset([target_buffer contents], 0, 3);
        [target_buffer didModifyRange:NSMakeRange(0, 3)];
    }

    /* SUPPORT teardown is independent of a live TARGET owner. Reintroducing
     * SUPPORT may build its descriptor while that lease is active, but the
     * final bind must roll SUPPORT back because combined activation cannot
     * reconcile across an owned TARGET cache. */
    ds4_gpu_set_streaming_expert_cache_budget(290);
    if (ok) {
        ok = target_buffer &&
             ds4_gpu_dspark_support_cache_combined_available() &&
             ds4_gpu_internal_dspark_support_populate_target_for_test(
                 1, support_bytes, MODEL_SIZE, target_buffer);
    }
    const ds4_gpu_qwen35_expert_pack_state
        target_descriptor_before_support_lease = g_qwen35_expert_pack;
    const uint64_t target_generation_before_support_lease =
        g_target_expert_pack_generation;
    const uint32_t target_entries_before_support_lease =
        g_stream_expert_cache_entry_count;
    const uint64_t target_bytes_before_support_lease =
        g_stream_expert_cache_bytes;
    const uint8_t target_entry_valid_before_support_lease =
        g_stream_expert_cache[0][0].valid;
    id<MTLBuffer> target_entry_buffer_before_support_lease =
        g_stream_expert_cache[0][0].gate_buffer;
    uint64_t support_teardown_target_lease = 0;
    if (ok) {
        ok = ds4_gpu_stream_expert_cache_acquire_layer_lease(
                 0, &support_teardown_target_lease) &&
             support_teardown_target_lease != 0;
    }
    ds4_gpu_expert_store_v2_clear_for_store(
        DS4_GPU_EXPERT_STORE_SUPPORT);
    const int support_reinstall_during_target_lease = ok &&
        !g_dspark_expert_pack &&
        g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
        g_stream_expert_cache_lease.id == support_teardown_target_lease &&
        ds4_gpu_expert_store_v2_install_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT, support_fd, FILE_SIZE,
            DS4_DSPARK_SUPPORT_LAYER_COUNT,
            DS4_DSPARK_SUPPORT_EXPERT_COUNT,
            DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers);
    const int support_bind_during_target_lease =
        support_reinstall_during_target_lease &&
        ds4_gpu_internal_dspark_support_bind_support_for_test(MODEL_SIZE);
    const int support_activation_rollback_ok =
        support_reinstall_during_target_lease &&
        !support_bind_during_target_lease &&
        !g_dspark_expert_pack &&
        !ds4_gpu_dspark_support_cache_combined_available() &&
        g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
        g_stream_expert_cache_lease.id == support_teardown_target_lease &&
        g_target_expert_pack_generation ==
            target_generation_before_support_lease &&
        memcmp(&g_qwen35_expert_pack,
               &target_descriptor_before_support_lease,
               sizeof(g_qwen35_expert_pack)) == 0 &&
        g_stream_expert_cache_entry_count ==
            target_entries_before_support_lease &&
        g_stream_expert_cache_bytes == target_bytes_before_support_lease &&
        g_stream_expert_cache[0][0].valid ==
            target_entry_valid_before_support_lease &&
        g_stream_expert_cache[0][0].gate_buffer ==
            target_entry_buffer_before_support_lease;
    const int support_teardown_target_release_ok =
        support_teardown_target_lease != 0 &&
        g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
        ds4_gpu_stream_expert_cache_release_layer_lease(
            support_teardown_target_lease);
    if (ok) {
        ok = support_activation_rollback_ok &&
             support_teardown_target_release_ok &&
             ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, support_fd, FILE_SIZE,
                 DS4_DSPARK_SUPPORT_LAYER_COUNT,
                 DS4_DSPARK_SUPPORT_EXPERT_COUNT,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers) &&
             ds4_gpu_internal_dspark_support_bind_support_for_test(
                 MODEL_SIZE) &&
             ds4_gpu_dspark_support_cache_combined_available();
    }

    /* TARGET replacement follows the established model-teardown path even
     * when its owner still holds a token: it revokes that token, clears the
     * old cache, and publishes a fresh descriptor generation. */
    const uint64_t target_generation_before_reinstall =
        g_target_expert_pack_generation;
    uint64_t target_reinstall_lease = 0;
    if (ok) {
        ok = g_stream_expert_cache_entry_count == 1 &&
             ds4_gpu_stream_expert_cache_acquire_layer_lease(
                 0, &target_reinstall_lease) &&
             target_reinstall_lease != 0;
    }
    const int target_reinstall_ok = ok &&
        ds4_gpu_expert_store_v2_install_for_store(
            DS4_GPU_EXPERT_STORE_TARGET, target_fd, FILE_SIZE,
            TARGET_LAYER_COUNT,
            DS4_DSPARK_SUPPORT_EXPERT_COUNT,
            DS4_EXPERT_STORE_STORAGE_GGML, 0, target_layers);
    const int stale_target_release_failed = target_reinstall_lease != 0 &&
        !ds4_gpu_stream_expert_cache_release_layer_lease(
            target_reinstall_lease);
    if (ok) {
        ok = target_reinstall_ok && stale_target_release_failed &&
             !g_stream_expert_cache_lease.active &&
             g_target_expert_pack_generation !=
                 target_generation_before_reinstall &&
             g_qwen35_expert_pack.active &&
             g_qwen35_expert_pack.fd == target_fd &&
             g_qwen35_expert_pack.n_layer == TARGET_LAYER_COUNT &&
             g_qwen35_expert_pack.n_expert ==
                 DS4_DSPARK_SUPPORT_EXPERT_COUNT &&
             g_qwen35_expert_pack.bound_layers == 0 &&
             g_qwen35_expert_pack.model_size == 0 &&
             !g_qwen35_expert_pack.layers[0].valid &&
             g_qwen35_expert_pack.layers[0].data_offset ==
                 target_layers[0].data_offset &&
             g_stream_expert_cache_entry_count == 0 &&
             g_stream_expert_cache_bytes == 0 &&
             g_dspark_expert_pack &&
             !ds4_gpu_dspark_support_cache_combined_available() &&
             ds4_gpu_internal_dspark_support_bind_target_for_test(
                 TARGET_LAYER_COUNT, MODEL_SIZE);
    }
    if (g_dspark_expert_pack) {
        ds4_gpu_expert_store_v2_clear_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT);
    }
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, support_fd, FILE_SIZE,
                 DS4_DSPARK_SUPPORT_LAYER_COUNT,
                 DS4_DSPARK_SUPPORT_EXPERT_COUNT,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers) &&
             ds4_gpu_internal_dspark_support_bind_support_for_test(
                 MODEL_SIZE) &&
             ds4_gpu_dspark_support_cache_combined_available();
    }

    /* A false->true combined transition cannot resize an existing TARGET
     * slab. Prove that it rolls model mode back without touching TARGET, then
     * prove the same activation succeeds once the test explicitly tears the
     * slab down. */
    const uint64_t reconcile_sync_before_mode =
        g_dspark_reconcile_synchronize_calls;
    ds4_gpu_set_glm_model(true);
    ds4_gpu_set_streaming_expert_cache_budget(290);
    __strong id<MTLBuffer> late_gate = nil;
    __strong id<MTLBuffer> late_up = nil;
