    ds4_gpu_dspark_support_cache_entry *stage0_hit = stage0 ?
        ds4_gpu_dspark_support_cache_get_for_test(0, 7) : NULL;
    ds4_gpu_dspark_support_cache_entry *stage1 = stage0_hit ?
