            (const uint8_t *)[stage1->buffer contents] : NULL;
        ok = stage0 && stage0_hit == stage0 && stage1 &&
             stage0_buffer != stage1->buffer &&
             stage0_contents && stage1_contents &&
             stage0_contents[0] == 7u &&
