             g_dspark_support_cache_hits == 0 &&
             g_dspark_support_cache_misses == 0 &&
             g_qwen35_expert_pack.active &&
             ds4_gpu_stream_expert_cache_configured_budget() == 320 &&
             ds4_gpu_dspark_support_cache_configured_budget() == 0;
