    ds4_gpu_set_streaming_expert_cache_budget(290);
    if (ok) {
        ok = ds4_gpu_internal_dspark_support_populate_target_for_test(
                 260, support_bytes, MODEL_SIZE, target_buffer) &&
             ds4_gpu_expert_store_v2_install_for_store(
