    ds4_gpu_stream_expert_cache_clear_all(0);
    if (ok) {
        ok = ds4_gpu_dspark_support_cache_get_for_test(0, 23) != NULL;
    }
    g_stream_expert_cache_mlock_budget_cap = 259;
    g_stream_expert_cache_mlock_budget_cap_active = 1;
    if (ok) {
        ok = ds4_gpu_stream_expert_cache_configured_budget() == 259 &&
             ds4_gpu_dspark_support_cache_configured_budget() == 31 &&
             ds4_gpu_stream_expert_cache_parent_budget(0) == 290 &&
             g_dspark_support_cache_entry_count == 1;
    }
    uint64_t cap_target_lease = 0;
    if (ok) {
        ok = ds4_gpu_stream_expert_cache_acquire_layer_lease(
            0, &cap_target_lease);
    }
    g_stream_expert_cache_mlock_budget_cap = 258;
    ds4_gpu_dspark_support_cache_target_cap_changed();
    const int cap_invariants_ok = cap_target_lease != 0 &&
        g_stream_expert_cache_lease.active &&
        g_stream_expert_cache_lease.domain ==
            DS4_GPU_STREAM_EXPERT_LEASE_TARGET &&
        g_stream_expert_cache_lease.id == cap_target_lease &&
        ds4_gpu_stream_expert_cache_configured_budget() == 258 &&
        ds4_gpu_dspark_support_cache_configured_budget() == 0 &&
        ds4_gpu_stream_expert_cache_parent_budget(0) == 258 &&
        g_dspark_support_cache_entry_count == 0 &&
        g_stream_expert_cache_entry_count <=
            ds4_gpu_stream_expert_cache_parent_budget(0);
    const int cap_release_ok = cap_target_lease != 0 ?
        ds4_gpu_stream_expert_cache_release_layer_lease(cap_target_lease) : 0;
    if (ok) {
        ok = cap_invariants_ok && cap_release_ok &&
             !ds4_gpu_reconfigure_streaming_expert_cache_budget(290);
    }
    g_stream_expert_cache_mlock_budget_cap = 259;
    if (ok) {
        ok = ds4_gpu_reconfigure_streaming_expert_cache_budget(289) &&
             g_stream_expert_cache_budget_override == 289;
    }
    g_stream_expert_cache_mlock_budget_cap = 258;
    ds4_gpu_dspark_support_cache_target_cap_changed();
    if (ok) {
        ok = !ds4_gpu_grow_streaming_expert_cache_budget(290) &&
             g_stream_expert_cache_budget_override == 289;
    }
    g_stream_expert_cache_mlock_budget_cap = 259;
    if (ok) {
        ok = ds4_gpu_grow_streaming_expert_cache_budget(290) &&
             ds4_gpu_stream_expert_cache_configured_budget() == 259 &&
             ds4_gpu_dspark_support_cache_configured_budget() == 31;
    }

    /* TARGET clear invalidates the pairing generation and clears SUPPORT.
     * Reinstalling an identical-looking TARGET cannot revive the old SUPPORT
     * descriptor; SUPPORT must be installed and bound again. */
    if (ok) {
        ok = ds4_gpu_dspark_support_cache_get_for_test(1, 41) != NULL;
    }
    const uint64_t target_generation_before_clear =
        g_target_expert_pack_generation;
    ds4_gpu_expert_store_v2_clear_for_store(DS4_GPU_EXPERT_STORE_TARGET);
    if (ok) {
        ok = g_dspark_expert_pack &&
             g_dspark_support_cache_entry_count == 0 &&
             ds4_gpu_dspark_support_cache_configured_budget() == 0 &&
             g_target_expert_pack_generation !=
                 target_generation_before_clear;
    }
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_TARGET, target_fd, FILE_SIZE,
                 TARGET_LAYER_COUNT,
                 DS4_DSPARK_SUPPORT_EXPERT_COUNT,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, target_layers) &&
             ds4_gpu_internal_dspark_support_bind_target_for_test(
                 TARGET_LAYER_COUNT, MODEL_SIZE) &&
             ds4_gpu_dspark_support_cache_configured_budget() == 0 &&
             ds4_gpu_dspark_support_cache_get_for_test(1, 41) == NULL;
    }
    if (ok) {
        ok = ds4_gpu_expert_store_v2_install_for_store(
                 DS4_GPU_EXPERT_STORE_SUPPORT, support_fd, FILE_SIZE,
                 DS4_DSPARK_SUPPORT_LAYER_COUNT,
                 DS4_DSPARK_SUPPORT_EXPERT_COUNT,
                 DS4_EXPERT_STORE_STORAGE_GGML, 0, support_layers) &&
             ds4_gpu_internal_dspark_support_bind_support_for_test(
                 MODEL_SIZE) &&
             ds4_gpu_dspark_support_cache_get_for_test(1, 41) != NULL;
    }
    if (ok) {
        ok = ds4_gpu_internal_dspark_support_lease_behavior_test(
            support_fd, FILE_SIZE, MODEL_SIZE, support_layers);
    }

    if (g_dspark_expert_pack) {
        ds4_gpu_expert_store_v2_clear_for_store(
            DS4_GPU_EXPERT_STORE_SUPPORT);
    }
    if (g_qwen35_expert_pack.active) {
        ds4_gpu_expert_store_v2_clear_for_store(
            DS4_GPU_EXPERT_STORE_TARGET);
    }
    ds4_gpu_set_streaming_expert_cache_budget(0);
    ds4_gpu_set_ssd_streaming(false);
    free(support_bytes);
    if (other_fd >= 0) close(other_fd);
    if (support_fd >= 0) close(support_fd);
    if (target_fd >= 0) close(target_fd);
    close(fd);
    return ok;
}

enum {
    DS4_DSPARK_HISTORY_TEST_WIDTH = 4096,
    DS4_DSPARK_HISTORY_TEST_HC = 4,
    DS4_DSPARK_HISTORY_TEST_ROWS = 128,
    DS4_DSPARK_HISTORY_TEST_SOURCE_ROWS = 140,
    DS4_DSPARK_HISTORY_TEST_VERIFY_ROWS = 4,
};

static float ds4_gpu_dspark_history_test_expected(
        uint64_t absolute_row,
        uint32_t dim) {
    return (float)absolute_row * 0.125f + 0.75f +
           (float)((int32_t)(dim % 257u) - 128) * 0.0009765625f;
}

static void ds4_gpu_dspark_history_test_fill_hc(
        float *out,
        uint64_t absolute_start,
        uint32_t rows) {
    for (uint32_t row = 0; row < rows; row++) {
        for (uint32_t hc = 0; hc < DS4_DSPARK_HISTORY_TEST_HC; hc++) {
            for (uint32_t dim = 0;
                 dim < DS4_DSPARK_HISTORY_TEST_WIDTH; dim++) {
                out[((uint64_t)row * DS4_DSPARK_HISTORY_TEST_HC + hc) *
                    DS4_DSPARK_HISTORY_TEST_WIDTH + dim] =
                    ds4_gpu_dspark_history_test_expected(
                        absolute_start + row, dim) - 0.75f +
                    (float)hc * 0.5f;
            }
        }
    }
}

static void ds4_gpu_dspark_history_test_fill_means(
        float *out,
        uint64_t absolute_start,
        uint32_t rows) {
    for (uint32_t row = 0; row < rows; row++) {
        for (uint32_t dim = 0;
             dim < DS4_DSPARK_HISTORY_TEST_WIDTH; dim++) {
            out[(uint64_t)row * DS4_DSPARK_HISTORY_TEST_WIDTH + dim] =
                ds4_gpu_dspark_history_test_expected(
                    absolute_start + row, dim);
        }
    }
}

/* Invoke the exact production device helper inside one graph-shaped command
 * batch. The helper releases its multi-row views before this fence, matching
 * the batch_attn_cur lifetime in ds4.c. */
static int ds4_gpu_dspark_history_test_encode_capture(
        ds4_gpu_tensor *current,
        ds4_gpu_tensor *history,
        ds4_gpu_tensor *scratch,
        ds4_gpu_tensor *source,
        uint32_t active_tokens,
        uint32_t input_skip,
        uint32_t retained_rows,
        uint32_t first_physical_row,
        uint32_t first_rows,
        uint32_t second_rows) {
    int ok = ds4_gpu_begin_commands();
    if (ok) {
        ok = ds4_gpu_dspark_capture_history_tensor(
            current, history, scratch, source,
            active_tokens, input_skip, retained_rows,
            first_physical_row, first_rows, second_rows);
    }
    if (ds4_gpu_commands_active()) {
        const int end_ok = ds4_gpu_end_commands();
        ok = end_ok && ok;
    }
    return ok;
}

static int ds4_gpu_dspark_history_test_encode_publication(
        ds4_gpu_tensor *current,
        ds4_gpu_tensor *history,
        ds4_gpu_tensor *candidate,
        uint32_t committed_rows,
        uint32_t first_physical_row,
        uint32_t first_rows,
        uint32_t second_rows) {
    int ok = ds4_gpu_begin_commands();
    if (ok) {
        ok = ds4_gpu_dspark_publish_history_tensor(
            current, history, candidate, committed_rows,
            first_physical_row, first_rows, second_rows);
    }
    if (ds4_gpu_commands_active()) {
        const int end_ok = ds4_gpu_end_commands();
        ok = end_ok && ok;
    }
    return ok;
}

static int ds4_gpu_dspark_history_test_verify(
        ds4_gpu_tensor *ring,
        ds4_gpu_tensor *current,
        uint64_t frontier,
        uint32_t count,
        uint64_t current_absolute,
        float *ring_host,
        float *current_host) {
    const uint64_t row_bytes =
        (uint64_t)DS4_DSPARK_HISTORY_TEST_WIDTH * sizeof(float);
    const uint64_t ring_bytes =
        (uint64_t)DS4_DSPARK_HISTORY_TEST_ROWS * row_bytes;
    if (!ring || !current || !ring_host || !current_host || count == 0 ||
        count > DS4_DSPARK_HISTORY_TEST_ROWS || frontier < count ||
        !ds4_gpu_tensor_read(ring, 0, ring_host, ring_bytes) ||
        !ds4_gpu_tensor_read(current, 0, current_host, row_bytes)) {
        return 0;
    }
    for (uint64_t absolute = frontier - count;
         absolute < frontier; absolute++) {
        const float *row = ring_host +
            (absolute % DS4_DSPARK_HISTORY_TEST_ROWS) *
                DS4_DSPARK_HISTORY_TEST_WIDTH;
        for (uint32_t dim = 0;
             dim < DS4_DSPARK_HISTORY_TEST_WIDTH; dim++) {
            if (fabsf(row[dim] - ds4_gpu_dspark_history_test_expected(
                                      absolute, dim)) > 1.0e-6f) {
                return 0;
            }
        }
    }
    for (uint32_t dim = 0;
         dim < DS4_DSPARK_HISTORY_TEST_WIDTH; dim++) {
        if (fabsf(current_host[dim] -
                  ds4_gpu_dspark_history_test_expected(
                      current_absolute, dim)) > 1.0e-6f) {
            return 0;
        }
    }
    return 1;
}

int ds4_gpu_internal_dspark_history_test(void) {
    const uint64_t row_values = DS4_DSPARK_HISTORY_TEST_WIDTH;
    const uint64_t row_bytes = row_values * sizeof(float);
    const uint64_t hc_row_values =
        (uint64_t)DS4_DSPARK_HISTORY_TEST_HC * row_values;
    const uint64_t source_values =
        (uint64_t)DS4_DSPARK_HISTORY_TEST_SOURCE_ROWS * hc_row_values;
    const uint64_t source_bytes = source_values * sizeof(float);
    const uint64_t ring_values =
        (uint64_t)DS4_DSPARK_HISTORY_TEST_ROWS * row_values;
    const uint64_t ring_bytes = ring_values * sizeof(float);
    const uint64_t verify_values =
        (uint64_t)DS4_DSPARK_HISTORY_TEST_VERIFY_ROWS * row_values;
    const uint64_t verify_bytes = verify_values * sizeof(float);
    if (!g_initialized && !ds4_gpu_init()) return 0;

    uint64_t live_bytes_before = 0;
    pthread_mutex_lock(&g_tensor_mu);
    live_bytes_before = g_tensor_alloc_live_bytes;
    pthread_mutex_unlock(&g_tensor_mu);

    float *source_host = malloc((size_t)source_bytes);
    float *ring_host = malloc((size_t)ring_bytes);
    float *ring_snapshot = malloc((size_t)ring_bytes);
    float *current_host = malloc((size_t)row_bytes);
    float *current_snapshot = malloc((size_t)row_bytes);
    float *candidate_host = malloc((size_t)verify_bytes);
    ds4_gpu_tensor *source = ds4_gpu_tensor_alloc(source_bytes);
    ds4_gpu_tensor *scratch = ds4_gpu_tensor_alloc(ring_bytes);
    ds4_gpu_tensor *ring = ds4_gpu_tensor_alloc(ring_bytes);
    ds4_gpu_tensor *current = ds4_gpu_tensor_alloc(row_bytes);
    ds4_gpu_tensor *candidate = ds4_gpu_tensor_alloc(verify_bytes);
    ds4_gpu_tensor *candidate_short = ds4_gpu_tensor_alloc(
        verify_bytes - sizeof(float));
    int ok = source_host && ring_host && ring_snapshot && current_host &&
             current_snapshot && candidate_host && source && scratch && ring &&
             current && candidate && candidate_short;
    uint64_t frontier = 0;

    /* The checked production geometry for start=0,n=140 retains rows 12..139
     * and crosses the ring boundary in two blits: physical 12..127 then 0..11. */
    if (ok) {
        ds4_gpu_dspark_history_test_fill_hc(
            source_host, 0u, DS4_DSPARK_HISTORY_TEST_SOURCE_ROWS);
        ok = ds4_gpu_tensor_write(source, 0, source_host, source_bytes) &&
             ds4_gpu_dspark_history_test_encode_capture(
                 current, ring, scratch, source, 140u,
                 12u, 128u, 12u, 116u, 12u);
        frontier = 140u;
    }
    if (ok) {
        ok = ds4_gpu_dspark_history_test_verify(
            ring, current, frontier, 128u, 139u,
            ring_host, current_host);
    }

    /* Short chunk accumulation uses the same shared multi-row helper. */
    if (ok) {
        ds4_gpu_dspark_history_test_fill_hc(source_host, frontier, 3u);
        ok = ds4_gpu_tensor_write(
                 source, 0, source_host, 3u * hc_row_values * sizeof(float)) &&
             ds4_gpu_dspark_history_test_encode_capture(
                 current, ring, scratch, source, 3u,
                 0u, 3u, 12u, 3u, 0u);
        frontier += 3u;
    }
    if (ok) {
        ok = ds4_gpu_dspark_history_test_verify(
            ring, current, frontier, 128u, frontier - 1u,
            ring_host, current_host);
    }

    /* Single decode uses direct HC mean into current plus one ring blit. */
    if (ok) {
        ds4_gpu_dspark_history_test_fill_hc(source_host, frontier, 1u);
        ok = ds4_gpu_tensor_write(
                 source, 0, source_host, hc_row_values * sizeof(float)) &&
             ds4_gpu_dspark_history_test_encode_capture(
                 current, ring, scratch, source, 1u,
                 0u, 1u, 15u, 1u, 0u);
        frontier += 1u;
    }
    if (ok) {
        ok = ds4_gpu_dspark_history_test_verify(
            ring, current, frontier, 128u, frontier - 1u,
            ring_host, current_host);
    }

    /* Full and partial verifier publications call the exact production blit
     * helper. Unaccepted rows remain only in candidate storage. */
    if (ok) {
        ds4_gpu_dspark_history_test_fill_means(candidate_host, frontier, 4u);
        ok = ds4_gpu_tensor_write(candidate, 0, candidate_host, verify_bytes) &&
             ds4_gpu_dspark_history_test_encode_publication(
                 current, ring, candidate, 4u, 16u, 4u, 0u);
        frontier += 4u;
    }
    if (ok) {
        ok = ds4_gpu_dspark_history_test_verify(
            ring, current, frontier, 128u, frontier - 1u,
            ring_host, current_host);
    }
    if (ok) {
        ds4_gpu_dspark_history_test_fill_means(candidate_host, frontier, 4u);
        ok = ds4_gpu_tensor_write(candidate, 0, candidate_host, verify_bytes) &&
             ds4_gpu_dspark_history_test_encode_publication(
                 current, ring, candidate, 2u, 20u, 2u, 0u);
        frontier += 2u;
    }
    if (ok) {
        ok = ds4_gpu_dspark_history_test_verify(
            ring, current, frontier, 128u, frontier - 1u,
            ring_host, current_host);
        if (ok) {
            memcpy(ring_snapshot, ring_host, (size_t)ring_bytes);
            memcpy(current_snapshot, current_host, (size_t)row_bytes);
        }
    }

    /* Invalid geometry/resources are rejected before encoding a blit. */
    if (ok) {
        ok = !ds4_gpu_dspark_capture_history_tensor(
                 current, ring, scratch, source,
                 3u, 1u, 3u, 22u, 3u, 0u) &&
             !ds4_gpu_dspark_publish_history_tensor(
                 current, ring, candidate, 0u, 22u, 1u, 0u) &&
             !ds4_gpu_dspark_publish_history_tensor(
                 current, ring, candidate, 2u, 127u, 2u, 0u) &&
             !ds4_gpu_dspark_publish_history_tensor(
                 current, ring, candidate_short, 4u, 22u, 4u, 0u) &&
             ds4_gpu_tensor_read(ring, 0, ring_host, ring_bytes) &&
             ds4_gpu_tensor_read(current, 0, current_host, row_bytes) &&
             memcmp(ring_host, ring_snapshot, (size_t)ring_bytes) == 0 &&
             memcmp(current_host, current_snapshot, (size_t)row_bytes) == 0;
    }

    /* Test-only injections fire after the first valid blit. The shared helper
     * returns failure; production host state selfchecks exercise the matching
     * fail-closed metadata transition. Partial device bytes are not published. */
    if (ok) {
        ds4_gpu_dspark_history_test_fill_hc(source_host, frontier, 3u);
        ok = ds4_gpu_tensor_write(
                 source, 0, source_host, 3u * hc_row_values * sizeof(float)) &&
             ds4_gpu_begin_commands();
        g_dspark_history_test_failure =
            DS4_GPU_DSPARK_HISTORY_TEST_FAIL_CAPTURE_AFTER_FIRST_BLIT;
        const int capture_rejected = ok &&
            !ds4_gpu_dspark_capture_history_tensor(
                current, ring, scratch, source,
                3u, 0u, 3u, 22u, 3u, 0u);
        const int capture_sync = ds4_gpu_commands_active() ?
            ds4_gpu_synchronize() : 0;
        ok = ok && capture_rejected && capture_sync &&
             g_dspark_history_test_failure ==
                 DS4_GPU_DSPARK_HISTORY_TEST_FAIL_NONE;
    }
    if (ok) {
        ds4_gpu_dspark_history_test_fill_means(candidate_host, frontier, 4u);
        ok = ds4_gpu_tensor_write(candidate, 0, candidate_host, verify_bytes) &&
             ds4_gpu_begin_commands();
        g_dspark_history_test_failure =
            DS4_GPU_DSPARK_HISTORY_TEST_FAIL_PUBLISH_AFTER_FIRST_BLIT;
        const int publish_rejected = ok &&
            !ds4_gpu_dspark_publish_history_tensor(
                current, ring, candidate, 2u, 22u, 2u, 0u);
        const int publish_sync = ds4_gpu_commands_active() ?
            ds4_gpu_synchronize() : 0;
        ok = ok && publish_rejected && publish_sync &&
             g_dspark_history_test_failure ==
                 DS4_GPU_DSPARK_HISTORY_TEST_FAIL_NONE;
    }

    ds4_gpu_tensor_free(candidate_short);
    ds4_gpu_tensor_free(candidate);
    ds4_gpu_tensor_free(current);
    ds4_gpu_tensor_free(ring);
    ds4_gpu_tensor_free(scratch);
    ds4_gpu_tensor_free(source);
    free(candidate_host);
    free(current_snapshot);
    free(current_host);
    free(ring_snapshot);
    free(ring_host);
    free(source_host);
    pthread_mutex_lock(&g_tensor_mu);
    ok = g_tensor_alloc_live_bytes == live_bytes_before && ok;
    pthread_mutex_unlock(&g_tensor_mu);
    return ok;
}
int ds4_gpu_internal_dspark_hc_mean_test(void) {
    enum {
        N_EMBD = 4096,
        N_HC = 4,
        N_TOKEN = 3,
        N_STAGE = 3,
        VIEW_PAD = 64,
    };
    NSString *pipeline_key = @"kernel_dsv4_hc_mean";
    if ([g_pipeline_cache objectForKey:pipeline_key] != nil) return 0;
    uint64_t live_bytes_before = 0;
    pthread_mutex_lock(&g_tensor_mu);
    live_bytes_before = g_tensor_alloc_live_bytes;
    pthread_mutex_unlock(&g_tensor_mu);

    const uint64_t input_count = (uint64_t)N_TOKEN * N_HC * N_EMBD;
    const uint64_t output_count = (uint64_t)N_TOKEN * N_EMBD;
    const uint64_t input_row_count = (uint64_t)N_HC * N_EMBD;
    const uint64_t input_row_bytes = input_row_count * sizeof(float);
    const uint64_t capture_count = N_EMBD;
    const uint64_t capture_bytes = capture_count * sizeof(float);
    float *input = malloc((size_t)N_STAGE * input_count * sizeof(*input));
    float *output = calloc((size_t)output_count, sizeof(*output));
    float *capture = calloc((size_t)N_STAGE * capture_count, sizeof(*capture));
    if (!input || !output || !capture) {
        free(capture);
        free(input);
        free(output);
        return 0;
    }
    for (uint32_t stage = 0; stage < N_STAGE; stage++) {
        float *stage_input = input + (uint64_t)stage * input_count;
        for (uint32_t token = 0; token < N_TOKEN; token++) {
            for (uint32_t hc = 0; hc < N_HC; hc++) {
                for (uint32_t dim = 0; dim < N_EMBD; dim++) {
                    stage_input[(token * N_HC + hc) * N_EMBD + dim] =
                        (float)stage * 17.0f + (float)token * 0.25f +
                        (float)hc * 1.5f +
                        ((float)((int32_t)(dim % 257u) - 128)) * 0.03125f;
                }
            }
        }
    }

    const uint64_t input_bytes = input_count * sizeof(*input);
    const uint64_t output_bytes = output_count * sizeof(*output);
    ds4_gpu_tensor *source = ds4_gpu_tensor_alloc(input_bytes);
    ds4_gpu_tensor *mean = ds4_gpu_tensor_alloc(output_bytes);
    ds4_gpu_tensor *alias = source ?
        ds4_gpu_tensor_view(source, 0, output_bytes) : NULL;
    ds4_gpu_tensor *undersized = ds4_gpu_tensor_alloc(input_bytes - sizeof(float));
    ds4_gpu_tensor *bad_shape = ds4_gpu_tensor_alloc(output_bytes - sizeof(float));
    ds4_gpu_tensor *stage_storage[N_STAGE] = {NULL, NULL, NULL};
    ds4_gpu_tensor *stage_source[N_STAGE] = {NULL, NULL, NULL};
    ds4_gpu_tensor *stage_capture[N_STAGE] = {NULL, NULL, NULL};
    for (uint32_t stage = 0; stage < N_STAGE; stage++) {
        stage_storage[stage] = ds4_gpu_tensor_alloc(input_bytes + VIEW_PAD);
        stage_source[stage] = stage_storage[stage] ?
            ds4_gpu_tensor_view(stage_storage[stage], VIEW_PAD, input_bytes) :
            NULL;
        stage_capture[stage] = ds4_gpu_tensor_alloc(capture_bytes);
    }
    ds4_gpu_tensor *capture_alias = stage_source[0] ?
        ds4_gpu_tensor_view(stage_source[0],
                            (uint64_t)(N_TOKEN - 1u) * input_row_bytes,
                            capture_bytes) : NULL;
    ds4_gpu_tensor *capture_short = ds4_gpu_tensor_alloc(
        capture_bytes - sizeof(float));
    ds4_gpu_tensor *capture_long = ds4_gpu_tensor_alloc(
        capture_bytes + sizeof(float));
    ds4_gpu_tensor *capture_input_short = ds4_gpu_tensor_alloc(
        input_bytes - sizeof(float));

    int ok = source && mean &&
             alias && undersized && bad_shape && capture_alias &&
             capture_short && capture_long && capture_input_short &&
             stage_storage[0] && stage_storage[1] && stage_storage[2] &&
             stage_source[0] && stage_source[1] && stage_source[2] &&
             stage_capture[0] && stage_capture[1] && stage_capture[2] &&
             ds4_gpu_tensor_write(source, 0, input, input_bytes) &&
             !ds4_gpu_hc_mean_tensor(alias, source, N_EMBD, N_HC) &&
             !ds4_gpu_hc_mean_tensor(mean, undersized, N_EMBD, N_HC) &&
             !ds4_gpu_hc_mean_tensor(bad_shape, source, N_EMBD, N_HC) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 NULL, stage_source[0], N_TOKEN, N_TOKEN - 1u) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 stage_capture[0], NULL, N_TOKEN, N_TOKEN - 1u) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 capture_short, stage_source[0], N_TOKEN, N_TOKEN - 1u) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 capture_long, stage_source[0], N_TOKEN, N_TOKEN - 1u) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 stage_capture[0], capture_input_short,
                 N_TOKEN, N_TOKEN - 1u) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 capture_alias, stage_source[0], N_TOKEN, N_TOKEN - 1u) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 stage_capture[0], stage_source[0], 0, 0) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 stage_capture[0], stage_source[0], N_TOKEN, N_TOKEN) &&
             !ds4_gpu_dspark_capture_hc_mean_row(
                 stage_capture[0], stage_source[0], UINT32_MAX,
                 UINT32_MAX - 1u) &&
             [g_pipeline_cache objectForKey:pipeline_key] == nil &&
             ds4_gpu_hc_mean_tensor(mean, source, N_EMBD, N_HC) &&
             ds4_gpu_tensor_read(mean, 0, output, output_bytes) &&
             [g_pipeline_cache objectForKey:pipeline_key] != nil;
    for (uint32_t token = 0; ok && token < N_TOKEN; token++) {
        for (uint32_t dim = 0; dim < N_EMBD; dim++) {
            const float expected =
                (float)token * 0.25f + 2.25f +
                ((float)((int32_t)(dim % 257u) - 128)) * 0.03125f;
            if (fabsf(output[token * N_EMBD + dim] - expected) > 1.0e-6f) {
                ok = 0;
                break;
            }
        }
    }

    /* Graph ownership maps completed target layers 40/41/42 to slots 0/1/2.
     * Exercise the single-row primitive against three independent sources and
     * a nonzero token index; production decode uses index zero, while batched
     * prefill uses ds4_gpu_hc_mean_tensor for its retained suffix. */
    const uint32_t target_layer[N_STAGE] = {40, 41, 42};
    for (uint32_t stage = 0; ok && stage < N_STAGE; stage++) {
        ok = target_layer[stage] == 40u + stage &&
             ds4_gpu_tensor_write(
                 stage_source[stage], 0,
                 input + (uint64_t)stage * input_count,
                 input_bytes);
    }
    if (ok) ok = ds4_gpu_begin_commands();
    for (uint32_t stage = 0; ok && stage < N_STAGE; stage++) {
        ok = ds4_gpu_dspark_capture_hc_mean_row(
            stage_capture[stage], stage_source[stage],
            N_TOKEN, N_TOKEN - 1u);
    }
    if (ds4_gpu_commands_active()) {
        const int end_ok = ds4_gpu_end_commands();
        ok = end_ok && ok;
    }
    for (uint32_t stage = 0; ok && stage < N_STAGE; stage++) {
        ok = ds4_gpu_tensor_read(
            stage_capture[stage], 0,
            capture + (uint64_t)stage * capture_count,
            capture_bytes);
        for (uint32_t dim = 0; ok && dim < N_EMBD; dim++) {
            const float expected =
                (float)stage * 17.0f + (float)(N_TOKEN - 1u) * 0.25f +
                2.25f +
                ((float)((int32_t)(dim % 257u) - 128)) * 0.03125f;
            if (fabsf(capture[(uint64_t)stage * capture_count + dim] -
                       expected) > 1.0e-6f) {
                ok = 0;
            }
        }
    }

    /* A later decode token overwrites only its selected stage row. */
    for (uint32_t hc = 0; hc < N_HC; hc++) {
        for (uint32_t dim = 0; dim < N_EMBD; dim++) {
            input[(uint64_t)hc * N_EMBD + dim] =
                -23.0f + (float)hc * 0.5f +
                ((float)((int32_t)(dim % 193u) - 96)) * 0.015625f;
        }
    }
    if (ok) {
        ok = ds4_gpu_tensor_write(
                 stage_source[0], 0, input, input_row_bytes) &&
             ds4_gpu_begin_commands() &&
             ds4_gpu_dspark_capture_hc_mean_row(
                 stage_capture[0], stage_source[0], 1, 0);
    }
    if (ds4_gpu_commands_active()) {
        const int end_ok = ds4_gpu_end_commands();
        ok = end_ok && ok;
    }
    if (ok) {
        ok = ds4_gpu_tensor_read(
            stage_capture[0], 0, capture, capture_bytes);
    }
    for (uint32_t dim = 0; ok && dim < N_EMBD; dim++) {
        const float expected =
            -23.0f + 0.75f +
            ((float)((int32_t)(dim % 193u) - 96)) * 0.015625f;
        if (fabsf(capture[dim] - expected) > 1.0e-6f) ok = 0;
    }

    ds4_gpu_tensor_free(capture_input_short);
    ds4_gpu_tensor_free(capture_long);
    ds4_gpu_tensor_free(capture_short);
    ds4_gpu_tensor_free(capture_alias);
    for (uint32_t stage = 0; stage < N_STAGE; stage++) {
        ds4_gpu_tensor_free(stage_capture[stage]);
        ds4_gpu_tensor_free(stage_source[stage]);
        ds4_gpu_tensor_free(stage_storage[stage]);
    }
    ds4_gpu_tensor_free(bad_shape);
    ds4_gpu_tensor_free(undersized);
    ds4_gpu_tensor_free(alias);
    ds4_gpu_tensor_free(mean);
    ds4_gpu_tensor_free(source);
    pthread_mutex_lock(&g_tensor_mu);
    ok = g_tensor_alloc_live_bytes == live_bytes_before && ok;
    pthread_mutex_unlock(&g_tensor_mu);
    free(capture);
    free(output);
    free(input);
    return ok;
}
#endif

int ds4_gpu_internal_qwen35_expert_pack_test(void) {
    const uint64_t file_size = 16u * 1024u;
    const uint64_t model_size = 1024u * 1024u;
    char pack_path[] = "/tmp/ds4-expert-store-v2-metal.XXXXXX";
    int pack_fd = -1;
    int installed = 0;
    int ok = 0;
    int source_fd = -1;
    uint64_t source_offset = 0;
    id<MTLBuffer> resident_buffer = nil;
    uint64_t resident_gate_inner = 0;
    uint64_t resident_up_inner = 0;
    uint64_t resident_down_inner = 0;
    uint64_t resident_stride = 0;
    __strong id<MTLBuffer> resident_buffers_before[2] = {nil, nil};

    if ((!g_initialized && !ds4_gpu_init()) ||
        g_qwen35_expert_pack.active) {
        return 0;
    }

    pack_fd = mkstemp(pack_path);
    if (pack_fd < 0) goto cleanup;
    (void)unlink(pack_path);
    if (ftruncate(pack_fd, (off_t)file_size) != 0) goto cleanup;

    /* Exercise sparse real layer ids and per-layer record geometry. Layer 5
     * starts after a 4 KiB gap, proving lookup, translation, and resident
     * mapping use the embedded v2 descriptor. */
    ds4_gpu_expert_store_layer_v2 v2_layers[2] = {
        {
            .layer = 3,
            .data_offset = 4096,
            .data_size = 45,
            .record_bytes = 15,
            .component_offset = {0, 3, 8},
            .component_bytes = {3, 5, 7},
        },
        {
            .layer = 5,
            .data_offset = 8192,
            .data_size = 48,
            .record_bytes = 16,
            .component_offset = {0, 4, 8},
            .component_bytes = {4, 4, 8},
        },
    };
    ds4_gpu_expert_store_layer_v2 overlapping[2];
    memcpy(overlapping, v2_layers, sizeof(overlapping));
    overlapping[1].data_offset = overlapping[0].data_offset;
    const uint8_t v2_gate[4] = {0x41, 0x42, 0x43, 0x44};
    const uint8_t v2_up[4] = {0x51, 0x52, 0x53, 0x54};
    const uint8_t v2_down[8] = {
        0x61, 0x62, 0x63, 0x64, 0x65, 0x66, 0x67, 0x68,
    };
    const uint64_t v2_record_offset = 8192 + 2u * 16u;
    const uint64_t v2_gate_offset = 320u * 1024u;
    const uint64_t v2_up_offset = 321u * 1024u;
    const uint64_t v2_down_offset = 322u * 1024u;
    if (ds4_gpu_expert_store_v2_install(
            pack_fd, file_size, 2, 3,
            DS4_EXPERT_STORE_STORAGE_GGML, 0, overlapping)) {
        goto cleanup;
    }
    if (!ds4_gpu_internal_qwen35_expert_pack_pwrite_all(
            pack_fd, v2_gate, sizeof(v2_gate), v2_record_offset) ||
        !ds4_gpu_internal_qwen35_expert_pack_pwrite_all(
            pack_fd, v2_up, sizeof(v2_up), v2_record_offset + 4) ||
        !ds4_gpu_internal_qwen35_expert_pack_pwrite_all(
            pack_fd, v2_down, sizeof(v2_down), v2_record_offset + 8)) {
        goto cleanup;
    }
    if (!ds4_gpu_expert_store_v2_install(
            pack_fd, file_size, 2, 3,
            DS4_EXPERT_STORE_STORAGE_GGML, 0, v2_layers)) {
        goto cleanup;
    }
    installed = 1;
    if (!ds4_gpu_expert_store_v2_bind_layer(
            3, model_size, 300u * 1024u, 301u * 1024u, 302u * 1024u) ||
        !ds4_gpu_expert_store_v2_bind_layer(
            5, model_size, v2_gate_offset, v2_up_offset, v2_down_offset)) {
        goto cleanup;
    }
    uint64_t v2_span_offset = 0;
    uint64_t v2_span_size = 0;
    if (!ds4_gpu_expert_store_v2_layer_span(
            5, model_size, &v2_span_offset, &v2_span_size) ||
        v2_span_offset != v2_layers[1].data_offset ||
        v2_span_size != v2_layers[1].data_size ||
        ds4_gpu_expert_store_v2_layer_span(
            4, model_size, &v2_span_offset, &v2_span_size)) {
        goto cleanup;
    }
    if (ds4_gpu_qwen35_expert_pack_resolve(
            v2_gate_offset + 2u * sizeof(v2_gate), sizeof(v2_gate),
            &source_fd, &source_offset) != 1 ||
        source_fd != pack_fd || source_offset != v2_record_offset ||
        ds4_gpu_qwen35_expert_pack_resolve(
            v2_up_offset + 2u * sizeof(v2_up), sizeof(v2_up),
            &source_fd, &source_offset) != 1 ||
        source_offset != v2_record_offset + 4 ||
        ds4_gpu_qwen35_expert_pack_resolve(
            v2_down_offset + 2u * sizeof(v2_down), sizeof(v2_down),
            &source_fd, &source_offset) != 1 ||
        source_offset != v2_record_offset + 8 ||
        ds4_gpu_qwen35_expert_pack_resolve(
            v2_gate_offset + 2u * sizeof(v2_gate), sizeof(v2_gate) - 1,
            &source_fd, &source_offset) != -1) {
        goto cleanup;
    }
    uint8_t v2_record[16] = {0};
    ds4_gpu_stream_expert_pread_task v2_tasks[3] = {0};
    uint32_t v2_n_tasks = 0;
    uint64_t v2_read_bytes = 0;
    double v2_read_ms = 0.0;
    if (!ds4_gpu_stream_expert_append_record_tasks(
            v2_tasks, 3, &v2_n_tasks,
            v2_gate_offset + 2u * sizeof(v2_gate),
            v2_up_offset + 2u * sizeof(v2_up),
            v2_down_offset + 2u * sizeof(v2_down),
            sizeof(v2_gate), sizeof(v2_down),
            v2_record,
            v2_record + sizeof(v2_gate),
            v2_record + sizeof(v2_gate) + sizeof(v2_up),
            DS4_GPU_STREAM_EXPERT_RECORD_FULL) ||
        v2_n_tasks != 1 || !v2_tasks[0].direct_source ||
        !ds4_gpu_stream_expert_pread_tasks(
            v2_tasks, v2_n_tasks, &v2_read_bytes, &v2_read_ms) ||
        v2_read_bytes != sizeof(v2_record) ||
        v2_tasks[0].successful_syscalls != 1 ||
        memcmp(v2_record, v2_gate, sizeof(v2_gate)) != 0 ||
        memcmp(v2_record + sizeof(v2_gate), v2_up, sizeof(v2_up)) != 0 ||
        memcmp(v2_record + sizeof(v2_gate) + sizeof(v2_up),
               v2_down, sizeof(v2_down)) != 0 ||
        !ds4_gpu_expert_store_v2_enable_resident()) {
        goto cleanup;
    }
    /* Resident enable is idempotent: the second call must reuse the exact
     * mappings and no-copy Metal buffers rather than mmap the pack again. */
    void *resident_maps_before[2] = {
        g_qwen35_expert_pack.resident_maps[0],
        g_qwen35_expert_pack.resident_maps[1],
    };
    uint64_t resident_map_bytes_before[2] = {
        g_qwen35_expert_pack.resident_map_bytes[0],
        g_qwen35_expert_pack.resident_map_bytes[1],
    };
    resident_buffers_before[0] =
        g_qwen35_expert_pack_resident_buffers[0];
    resident_buffers_before[1] =
        g_qwen35_expert_pack_resident_buffers[1];
    if (!ds4_gpu_expert_store_v2_enable_resident() ||
        !g_qwen35_expert_pack.resident_active) {
        goto cleanup;
    }
    for (uint32_t layer = 0; layer < 2; layer++) {
        if (g_qwen35_expert_pack.resident_maps[layer] !=
                resident_maps_before[layer] ||
            g_qwen35_expert_pack.resident_map_bytes[layer] !=
                resident_map_bytes_before[layer] ||
            g_qwen35_expert_pack_resident_buffers[layer] !=
                resident_buffers_before[layer]) {
            goto cleanup;
        }
    }
    memset(v2_record, 0, sizeof(v2_record));
    memset(v2_tasks, 0, sizeof(v2_tasks));
    v2_n_tasks = 0;
    v2_read_bytes = 0;
    v2_read_ms = 0.0;
    if (!ds4_gpu_stream_expert_append_record_tasks(
            v2_tasks, 3, &v2_n_tasks,
            v2_gate_offset + 2u * sizeof(v2_gate),
            v2_up_offset + 2u * sizeof(v2_up),
            v2_down_offset + 2u * sizeof(v2_down),
            sizeof(v2_gate), sizeof(v2_down),
            v2_record,
            v2_record + sizeof(v2_gate),
            v2_record + sizeof(v2_gate) + sizeof(v2_up),
            DS4_GPU_STREAM_EXPERT_RECORD_BALANCED3) ||
        v2_n_tasks != 3 ||
        !v2_tasks[0].direct_source ||
        !v2_tasks[1].direct_source ||
        !v2_tasks[2].direct_source ||
        v2_tasks[0].source_offset != v2_record_offset ||
        v2_tasks[1].source_offset !=
            v2_tasks[0].source_offset + v2_tasks[0].len ||
        v2_tasks[2].source_offset !=
            v2_tasks[1].source_offset + v2_tasks[1].len ||
        v2_tasks[0].dst != v2_record ||
        v2_tasks[1].dst != v2_record + v2_tasks[0].len ||
        v2_tasks[2].dst !=
            v2_record + v2_tasks[0].len + v2_tasks[1].len ||
        v2_tasks[0].len + v2_tasks[1].len + v2_tasks[2].len !=
            sizeof(v2_record) ||
        !ds4_gpu_stream_expert_pread_tasks(
            v2_tasks, v2_n_tasks, &v2_read_bytes, &v2_read_ms) ||
        v2_read_bytes != sizeof(v2_record) ||
        v2_tasks[0].successful_syscalls != 1 ||
        v2_tasks[1].successful_syscalls != 1 ||
        v2_tasks[2].successful_syscalls != 1 ||
        memcmp(v2_record, v2_gate, sizeof(v2_gate)) != 0 ||
        memcmp(v2_record + sizeof(v2_gate), v2_up, sizeof(v2_up)) != 0 ||
        memcmp(v2_record + sizeof(v2_gate) + sizeof(v2_up),
               v2_down, sizeof(v2_down)) != 0) {
        goto cleanup;
    }
    memset(v2_record, 0, sizeof(v2_record));
    memset(v2_tasks, 0, sizeof(v2_tasks));
    v2_n_tasks = 0;
    v2_read_bytes = 0;
    v2_read_ms = 0.0;
    if (!ds4_gpu_stream_expert_append_record_tasks(
            v2_tasks, 3, &v2_n_tasks,
            v2_gate_offset + 2u * sizeof(v2_gate),
            v2_up_offset + 2u * sizeof(v2_up),
            v2_down_offset + 2u * sizeof(v2_down),
            sizeof(v2_gate), sizeof(v2_down),
            v2_record,
            v2_record + sizeof(v2_gate),
            v2_record + sizeof(v2_gate) + sizeof(v2_up),
            HEBRUS_GPU_STREAM_EXPERT_RECORD_PAIRED2) ||
        v2_n_tasks != 2 ||
        !v2_tasks[0].direct_source ||
        !v2_tasks[1].direct_source ||
        v2_tasks[0].source_offset != v2_record_offset ||
        v2_tasks[1].source_offset !=
            v2_record_offset + sizeof(v2_gate) + sizeof(v2_up) ||
        v2_tasks[0].dst != v2_record ||
        v2_tasks[1].dst !=
            v2_record + sizeof(v2_gate) + sizeof(v2_up) ||
        v2_tasks[0].len != sizeof(v2_gate) + sizeof(v2_up) ||
        v2_tasks[1].len != sizeof(v2_down) ||
        !ds4_gpu_stream_expert_pread_tasks(
            v2_tasks, v2_n_tasks, &v2_read_bytes, &v2_read_ms) ||
        v2_read_bytes != sizeof(v2_record) ||
        v2_tasks[0].successful_syscalls != 1 ||
        v2_tasks[1].successful_syscalls != 1 ||
        memcmp(v2_record, v2_gate, sizeof(v2_gate)) != 0 ||
        memcmp(v2_record + sizeof(v2_gate), v2_up, sizeof(v2_up)) != 0 ||
        memcmp(v2_record + sizeof(v2_gate) + sizeof(v2_up),
               v2_down, sizeof(v2_down)) != 0) {
        goto cleanup;
    }
    resident_buffer = nil;
    resident_gate_inner = 0;
    resident_up_inner = 0;
    resident_down_inner = 0;
    resident_stride = 0;
    const uint64_t v2_expected_inner =
        v2_layers[1].data_offset % (uint64_t)sysconf(_SC_PAGESIZE);
    if (!ds4_gpu_qwen35_expert_pack_resident_layer(
            5, model_size, v2_gate_offset, v2_up_offset, v2_down_offset,
            &resident_buffer, &resident_gate_inner, &resident_up_inner,
            &resident_down_inner, &resident_stride) ||
        !resident_buffer || resident_gate_inner != v2_expected_inner ||
        resident_up_inner != v2_expected_inner + 4 ||
        resident_down_inner != v2_expected_inner + 8 ||
        resident_stride != 16 ||
        memcmp((const uint8_t *)resident_buffer.contents +
                   resident_gate_inner + 2u * resident_stride,
               v2_gate, sizeof(v2_gate)) != 0) {
        goto cleanup;
    }
    ds4_gpu_expert_store_v2_clear();
    installed = 0;
    ok = 1;

cleanup:
    if (installed) ds4_gpu_expert_store_v2_clear();
    if (pack_fd >= 0) close(pack_fd);
    return ok;
}

typedef struct {
    uint8_t scales[16];
    uint8_t qs[64];
    uint16_t d;
    uint16_t dmin;
} ds4_gpu_internal_expert_store_q2_block;

static void ds4_gpu_internal_expert_store_fill_q2(
        uint8_t *component,
        uint32_t role,
        uint32_t n_expert,
        uint32_t n_row) {
    const uint64_t expert_bytes =
        (uint64_t)n_row * sizeof(ds4_gpu_internal_expert_store_q2_block);
    for (uint32_t expert = 0; expert < n_expert; expert++) {
        for (uint32_t row = 0; row < n_row; row++) {
            ds4_gpu_internal_expert_store_q2_block *block =
                (ds4_gpu_internal_expert_store_q2_block *)(
                    component + (uint64_t)expert * expert_bytes +
                    (uint64_t)row * sizeof(*block));
            for (uint32_t index = 0; index < 16; index++) {
                block->scales[index] = (uint8_t)(
                    1u + ((role * 5u + expert * 3u + row + index) % 7u));
            }
            for (uint32_t index = 0; index < 64; index++) {
                block->qs[index] = (uint8_t)(
                    17u + role * 53u + expert * 29u + row * 7u + index * 11u);
            }
            block->d = 0x2c00u;
            block->dmin = 0u;
        }
    }
}

int ds4_gpu_internal_expert_store_v2_kernel_test(void) {
    enum {
        N_EXPERT = 3,
        N_SELECTED = 2,
        N_TOKEN = 96,
        IN_DIM = 256,
        MID_DIM = 256,
        OUT_DIM = 256,
    };
    const uint64_t page = 16384u;
    const uint64_t row_bytes =
        sizeof(ds4_gpu_internal_expert_store_q2_block);
    const uint64_t expert_bytes = (uint64_t)MID_DIM * row_bytes;
    const uint64_t component_bytes = (uint64_t)N_EXPERT * expert_bytes;
    const uint64_t record_bytes = expert_bytes * 3u;
    const uint64_t payload_bytes = record_bytes * N_EXPERT;
    const uint64_t gate_offset = page;
    const uint64_t up_offset = gate_offset + component_bytes;
    const uint64_t down_offset = up_offset + component_bytes;
    const uint64_t file_size = gate_offset + payload_bytes + page;
    const uint64_t batch_values = (uint64_t)N_TOKEN * OUT_DIM;
    const uint64_t batch_mid_values =
        (uint64_t)N_TOKEN * N_SELECTED * MID_DIM;

    char canonical_path[] = "/tmp/ds4-expert-canonical-q2.XXXXXX";
    char native_path[] = "/tmp/ds4-expert-native-q2.XXXXXX";
    int canonical_fd = -1;
    int native_fd = -1;
    void *canonical_map = MAP_FAILED;
    void *native_map = MAP_FAILED;
    uint8_t *components[3] = {NULL, NULL, NULL};
    uint8_t *native_payload = NULL;
    float *batch_x_values = NULL;
    int32_t *batch_selected_values = NULL;
    float *batch_weight_values = NULL;
    float *baseline_scalar = NULL;
    float *baseline_grouped = NULL;
    float *native_scalar = NULL;
    float *native_grouped = NULL;
    ds4_gpu_tensor *out = NULL;
    ds4_gpu_tensor *mid = NULL;
    ds4_gpu_tensor *x = NULL;
    ds4_gpu_tensor *selected = NULL;
    ds4_gpu_tensor *weights = NULL;
    ds4_gpu_tensor *batch_out = NULL;
    ds4_gpu_tensor *batch_mid = NULL;
    ds4_gpu_tensor *batch_x = NULL;
    ds4_gpu_tensor *batch_selected = NULL;
    ds4_gpu_tensor *batch_weights = NULL;
    float baseline_one[OUT_DIM];
    float native_one[OUT_DIM];
    int ok = 0;
    const char *stage = "setup";

    if (sizeof(ds4_gpu_internal_expert_store_q2_block) != 84u ||
        down_offset + component_bytes != gate_offset + payload_bytes) {
        return 0;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;
    ds4_gpu_expert_store_v2_clear();
    ds4_gpu_set_glm_model(true);
    ds4_gpu_set_ssd_streaming(false);
    ds4_gpu_set_glm_streaming_prefill_full_layer(false);

    stage = "create fixtures";
    canonical_fd = mkstemp(canonical_path);
    native_fd = mkstemp(native_path);
    if (canonical_fd < 0 || native_fd < 0 ||
        ftruncate(canonical_fd, (off_t)file_size) != 0 ||
        ftruncate(native_fd, (off_t)file_size) != 0) {
        goto cleanup;
    }
    (void)unlink(canonical_path);
    (void)unlink(native_path);

    for (uint32_t role = 0; role < 3; role++) {
        components[role] = malloc((size_t)component_bytes);
        if (!components[role]) goto cleanup;
        ds4_gpu_internal_expert_store_fill_q2(
            components[role], role, N_EXPERT, MID_DIM);
        if (!ds4_gpu_internal_qwen35_expert_pack_pwrite_all(
                canonical_fd,
                components[role],
                component_bytes,
                gate_offset + (uint64_t)role * component_bytes)) {
            goto cleanup;
        }
    }
    native_payload = malloc((size_t)payload_bytes);
    if (!native_payload) goto cleanup;
    for (uint32_t expert = 0; expert < N_EXPERT; expert++) {
        for (uint32_t role = 0; role < 3; role++) {
            memcpy(native_payload + (uint64_t)expert * record_bytes +
                                    (uint64_t)role * expert_bytes,
                   components[role] + (uint64_t)expert * expert_bytes,
                   (size_t)expert_bytes);
        }
    }
    if (!ds4_gpu_internal_qwen35_expert_pack_pwrite_all(
            native_fd,
            native_payload,
            payload_bytes,
            gate_offset)) {
        goto cleanup;
    }

    stage = "map fixtures";
    canonical_map = mmap(NULL, (size_t)file_size, PROT_READ,
                         MAP_PRIVATE, canonical_fd, 0);
    native_map = mmap(NULL, (size_t)file_size, PROT_READ,
                      MAP_PRIVATE, native_fd, 0);
    if (canonical_map == MAP_FAILED || native_map == MAP_FAILED) goto cleanup;

    stage = "allocate tensors";
    out = ds4_gpu_tensor_alloc((uint64_t)OUT_DIM * sizeof(float));
    mid = ds4_gpu_tensor_alloc(
        (uint64_t)N_SELECTED * MID_DIM * sizeof(float));
    x = ds4_gpu_tensor_alloc((uint64_t)IN_DIM * sizeof(float));
    selected = ds4_gpu_tensor_alloc(
        (uint64_t)N_SELECTED * sizeof(int32_t));
    weights = ds4_gpu_tensor_alloc(
        (uint64_t)N_SELECTED * sizeof(float));
    batch_out = ds4_gpu_tensor_alloc(batch_values * sizeof(float));
    batch_mid = ds4_gpu_tensor_alloc(batch_mid_values * sizeof(float));
    batch_x = ds4_gpu_tensor_alloc(
        (uint64_t)N_TOKEN * IN_DIM * sizeof(float));
    batch_selected = ds4_gpu_tensor_alloc(
        (uint64_t)N_TOKEN * N_SELECTED * sizeof(int32_t));
    batch_weights = ds4_gpu_tensor_alloc(
        (uint64_t)N_TOKEN * N_SELECTED * sizeof(float));
    if (!out || !mid || !x || !selected || !weights || !batch_out ||
        !batch_mid || !batch_x || !batch_selected || !batch_weights) {
        goto cleanup;
    }

    batch_x_values = malloc((size_t)N_TOKEN * IN_DIM * sizeof(float));
    batch_selected_values = malloc(
        (size_t)N_TOKEN * N_SELECTED * sizeof(int32_t));
    batch_weight_values = malloc(
        (size_t)N_TOKEN * N_SELECTED * sizeof(float));
    baseline_scalar = malloc((size_t)batch_values * sizeof(float));
    baseline_grouped = malloc((size_t)batch_values * sizeof(float));
    native_scalar = malloc((size_t)batch_values * sizeof(float));
    native_grouped = malloc((size_t)batch_values * sizeof(float));
    if (!batch_x_values || !batch_selected_values || !batch_weight_values ||
        !baseline_scalar || !baseline_grouped || !native_scalar ||
        !native_grouped) {
        goto cleanup;
    }

    float x_values[IN_DIM];
    const int32_t selected_values[N_SELECTED] = {0, 2};
    const float weight_values[N_SELECTED] = {0.4f, 0.6f};
    for (uint32_t index = 0; index < IN_DIM; index++) {
        x_values[index] = ((int32_t)(index % 19u) - 9) * 0.001f;
    }
    for (uint32_t token = 0; token < N_TOKEN; token++) {
        for (uint32_t index = 0; index < IN_DIM; index++) {
            batch_x_values[(uint64_t)token * IN_DIM + index] =
                ((int32_t)((index + token * 7u) % 23u) - 11) * 0.00075f;
        }
        batch_selected_values[(uint64_t)token * N_SELECTED] =
            (int32_t)(token % N_EXPERT);
        batch_selected_values[(uint64_t)token * N_SELECTED + 1u] =
            (int32_t)((token + 2u) % N_EXPERT);
        batch_weight_values[(uint64_t)token * N_SELECTED] = 0.35f;
        batch_weight_values[(uint64_t)token * N_SELECTED + 1u] = 0.65f;
    }
    if (!ds4_gpu_tensor_write(x, 0, x_values, sizeof(x_values)) ||
        !ds4_gpu_tensor_write(selected, 0, selected_values,
                              sizeof(selected_values)) ||
        !ds4_gpu_tensor_write(weights, 0, weight_values,
                              sizeof(weight_values)) ||
        !ds4_gpu_tensor_write(batch_x, 0, batch_x_values,
                              (uint64_t)N_TOKEN * IN_DIM * sizeof(float)) ||
        !ds4_gpu_tensor_write(batch_selected, 0, batch_selected_values,
                              (uint64_t)N_TOKEN * N_SELECTED *
                                  sizeof(int32_t)) ||
        !ds4_gpu_tensor_write(batch_weights, 0, batch_weight_values,
                              (uint64_t)N_TOKEN * N_SELECTED *
                                  sizeof(float)) ||
        !ds4_gpu_set_model_map(canonical_map, file_size)) {
        goto cleanup;
    }

    stage = "canonical scalar";
    ds4_gpu_set_quality(true);
    if (!ds4_gpu_tensor_fill_f32(out, 0.0f, OUT_DIM) ||
        !ds4_gpu_tensor_fill_f32(batch_out, 0.0f, batch_values) ||
        !ds4_gpu_glm_routed_moe_one_tensor(
            out, mid, canonical_map, file_size,
            gate_offset, up_offset, down_offset,
            DS4_METAL_TENSOR_Q2_K, DS4_METAL_TENSOR_Q2_K,
            DS4_METAL_TENSOR_Q2_K,
            expert_bytes, row_bytes, expert_bytes, row_bytes,
            expert_bytes, row_bytes,
            IN_DIM, MID_DIM, OUT_DIM,
            selected, weights, N_EXPERT, N_SELECTED, 3, x, true) ||
        !ds4_gpu_tensor_read(out, 0, baseline_one, sizeof(baseline_one)) ||
        !ds4_gpu_glm_routed_moe_batch_tensor(
            batch_out, batch_mid, canonical_map, file_size,
            gate_offset, up_offset, down_offset,
            DS4_METAL_TENSOR_Q2_K, DS4_METAL_TENSOR_Q2_K,
            DS4_METAL_TENSOR_Q2_K,
            expert_bytes, row_bytes, expert_bytes, row_bytes,
            expert_bytes, row_bytes,
            IN_DIM, MID_DIM, OUT_DIM,
            batch_selected, batch_weights, N_EXPERT, N_SELECTED, 3,
            batch_x, N_TOKEN, N_SELECTED * MID_DIM) ||
        !ds4_gpu_tensor_read(batch_out, 0, baseline_scalar,
                             batch_values * sizeof(float))) {
        goto cleanup;
    }

    stage = "canonical grouped";
    ds4_gpu_set_quality(false);
    if (!ds4_gpu_glm_routed_moe_batch_grouped_available(
            DS4_METAL_TENSOR_Q2_K,
            DS4_METAL_TENSOR_Q2_K,
            DS4_METAL_TENSOR_Q2_K,
            N_SELECTED,
            N_TOKEN) ||
        !ds4_gpu_tensor_fill_f32(batch_out, 0.0f, batch_values) ||
        !ds4_gpu_glm_routed_moe_batch_tensor(
            batch_out, batch_mid, canonical_map, file_size,
            gate_offset, up_offset, down_offset,
            DS4_METAL_TENSOR_Q2_K, DS4_METAL_TENSOR_Q2_K,
            DS4_METAL_TENSOR_Q2_K,
            expert_bytes, row_bytes, expert_bytes, row_bytes,
            expert_bytes, row_bytes,
            IN_DIM, MID_DIM, OUT_DIM,
            batch_selected, batch_weights, N_EXPERT, N_SELECTED, 3,
            batch_x, N_TOKEN, N_SELECTED * MID_DIM) ||
        !ds4_gpu_tensor_read(batch_out, 0, baseline_grouped,
                             batch_values * sizeof(float))) {
        goto cleanup;
    }

    stage = "install native store";
    const ds4_gpu_expert_store_layer_v2 layer = {
        .layer = 3,
        .data_offset = gate_offset,
        .data_size = payload_bytes,
        .record_bytes = record_bytes,
        .component_offset = {0, expert_bytes, expert_bytes * 2u},
        .component_bytes = {expert_bytes, expert_bytes, expert_bytes},
    };
    if (!ds4_gpu_expert_store_v2_install(
            native_fd, file_size, 1, N_EXPERT,
            DS4_EXPERT_STORE_STORAGE_GGML, 0, &layer) ||
        !ds4_gpu_expert_store_v2_bind_layer(
            3, file_size, gate_offset, up_offset, down_offset) ||
        !ds4_gpu_set_model_map(native_map, file_size) ||
        !ds4_gpu_expert_store_v2_enable_resident()) {
        goto cleanup;
    }

    stage = "native read policy";
    ds4_gpu_stream_expert_pread_task policy_tasks[3] = {0};
    uint32_t policy_task_count = 0;
    if (!ds4_gpu_stream_expert_glm_full_record_default() ||
        ds4_gpu_stream_expert_record_read_plan() !=
            DS4_GPU_STREAM_EXPERT_RECORD_FULL ||
        !ds4_gpu_stream_expert_append_record_tasks(
            policy_tasks,
            3,
            &policy_task_count,
            gate_offset,
            up_offset,
            down_offset,
            expert_bytes,
            expert_bytes,
            native_payload,
            native_payload + expert_bytes,
            native_payload + expert_bytes * 2u,
            ds4_gpu_stream_expert_record_read_plan()) ||
        policy_task_count != 1u ||
        !policy_tasks[0].direct_source ||
        policy_tasks[0].len != record_bytes) {
        goto cleanup;
    }

    stage = "native scalar";
    ds4_gpu_set_quality(true);
    if (!ds4_gpu_tensor_fill_f32(out, 0.0f, OUT_DIM) ||
        !ds4_gpu_tensor_fill_f32(batch_out, 0.0f, batch_values) ||
        !ds4_gpu_glm_routed_moe_one_tensor(
            out, mid, native_map, file_size,
            gate_offset, up_offset, down_offset,
            DS4_METAL_TENSOR_Q2_K, DS4_METAL_TENSOR_Q2_K,
            DS4_METAL_TENSOR_Q2_K,
            expert_bytes, row_bytes, expert_bytes, row_bytes,
            expert_bytes, row_bytes,
            IN_DIM, MID_DIM, OUT_DIM,
            selected, weights, N_EXPERT, N_SELECTED, 3, x, true) ||
        !ds4_gpu_tensor_read(out, 0, native_one, sizeof(native_one)) ||
        !ds4_gpu_glm_routed_moe_batch_tensor(
            batch_out, batch_mid, native_map, file_size,
            gate_offset, up_offset, down_offset,
            DS4_METAL_TENSOR_Q2_K, DS4_METAL_TENSOR_Q2_K,
            DS4_METAL_TENSOR_Q2_K,
            expert_bytes, row_bytes, expert_bytes, row_bytes,
            expert_bytes, row_bytes,
            IN_DIM, MID_DIM, OUT_DIM,
            batch_selected, batch_weights, N_EXPERT, N_SELECTED, 3,
            batch_x, N_TOKEN, N_SELECTED * MID_DIM) ||
        !ds4_gpu_tensor_read(batch_out, 0, native_scalar,
                             batch_values * sizeof(float))) {
        goto cleanup;
    }

    stage = "native grouped";
    ds4_gpu_set_quality(false);
    ds4_gpu_set_ssd_streaming(true);
    ds4_gpu_set_glm_streaming_prefill_full_layer(true);
    if (!ds4_gpu_tensor_fill_f32(batch_out, 0.0f, batch_values) ||
        !ds4_gpu_glm_routed_moe_batch_tensor(
            batch_out, batch_mid, native_map, file_size,
            gate_offset, up_offset, down_offset,
            DS4_METAL_TENSOR_Q2_K, DS4_METAL_TENSOR_Q2_K,
            DS4_METAL_TENSOR_Q2_K,
            expert_bytes, row_bytes, expert_bytes, row_bytes,
            expert_bytes, row_bytes,
            IN_DIM, MID_DIM, OUT_DIM,
            batch_selected, batch_weights, N_EXPERT, N_SELECTED, 3,
            batch_x, N_TOKEN, N_SELECTED * MID_DIM) ||
        !ds4_gpu_tensor_read(batch_out, 0, native_grouped,
                             batch_values * sizeof(float))) {
        goto cleanup;
    }

    stage = "compare outputs";
    float max_abs = 0.0f;
    float max_one_delta = 0.0f;
    float max_scalar_delta = 0.0f;
    float max_grouped_delta = 0.0f;
    for (uint32_t index = 0; index < OUT_DIM; index++) {
        if (!isfinite(baseline_one[index]) || !isfinite(native_one[index])) {
            goto cleanup;
        }
        max_abs = fmaxf(max_abs, fabsf(baseline_one[index]));
        max_one_delta = fmaxf(
            max_one_delta, fabsf(baseline_one[index] - native_one[index]));
    }
    for (uint64_t index = 0; index < batch_values; index++) {
        if (!isfinite(baseline_scalar[index]) ||
            !isfinite(baseline_grouped[index]) ||
            !isfinite(native_scalar[index]) ||
            !isfinite(native_grouped[index])) {
            goto cleanup;
        }
        max_abs = fmaxf(max_abs, fabsf(baseline_scalar[index]));
        max_scalar_delta = fmaxf(
            max_scalar_delta,
            fabsf(baseline_scalar[index] - native_scalar[index]));
        max_grouped_delta = fmaxf(
            max_grouped_delta,
            fabsf(baseline_grouped[index] - native_grouped[index]));
    }
    if (!(max_abs > 1.0e-8f) || max_one_delta > 1.0e-6f ||
        max_scalar_delta > 1.0e-6f || max_grouped_delta > 2.0e-4f) {
        fprintf(stderr,
                "ds4: ExpertMajor kernel mismatch one=%g scalar=%g grouped=%g max=%g\n",
                max_one_delta,
                max_scalar_delta,
                max_grouped_delta,
                max_abs);
        goto cleanup;
    }
    ok = 1;

cleanup:
    if (!ok) {
        fprintf(stderr, "ds4: ExpertMajor kernel test failed at %s\n", stage);
    }
    ds4_gpu_set_glm_streaming_prefill_full_layer(false);
    ds4_gpu_set_ssd_streaming(false);
    ds4_gpu_set_quality(false);
    ds4_gpu_expert_store_v2_clear();
    ds4_gpu_tensor_free(out);
    ds4_gpu_tensor_free(mid);
    ds4_gpu_tensor_free(x);
    ds4_gpu_tensor_free(selected);
    ds4_gpu_tensor_free(weights);
    ds4_gpu_tensor_free(batch_out);
    ds4_gpu_tensor_free(batch_mid);
    ds4_gpu_tensor_free(batch_x);
    ds4_gpu_tensor_free(batch_selected);
    ds4_gpu_tensor_free(batch_weights);
    ds4_gpu_cleanup();
    if (g_glm_model_mode) {
        fprintf(stderr, "ds4: ExpertMajor kernel test leaked GLM mode through cleanup\n");
        ok = 0;
    }
    if (canonical_map != MAP_FAILED) {
        (void)munmap(canonical_map, (size_t)file_size);
    }
    if (native_map != MAP_FAILED) {
        (void)munmap(native_map, (size_t)file_size);
    }
    if (canonical_fd >= 0) close(canonical_fd);
    if (native_fd >= 0) close(native_fd);
    free(native_payload);
    for (uint32_t role = 0; role < 3; role++) free(components[role]);
    free(batch_x_values);
    free(batch_selected_values);
    free(batch_weight_values);
    free(baseline_scalar);
    free(baseline_grouped);
    free(native_scalar);
    free(native_grouped);
    return ok;
}

int ds4_gpu_internal_qwen35_expert_group_test(void) {
    enum {
        N_TOKEN = 64,
        N_ROUTE = 8,
        N_EXPERT = 256,
        WIDTH = 4,
        ROUTE_COUNT = N_TOKEN * N_ROUTE,
        CANONICAL_VALUE_COUNT = ROUTE_COUNT * WIDTH,
        REDUCED_VALUE_COUNT = N_TOKEN * WIDTH,
    };
    if (!g_initialized && !ds4_gpu_init()) return 0;

    int32_t *ids = calloc(ROUTE_COUNT, sizeof(ids[0]));
    ds4_qwen_expert_group_route *first_routes = calloc(
        ROUTE_COUNT, sizeof(first_routes[0]));
    uint32_t *grouped_bits = calloc(CANONICAL_VALUE_COUNT,
                                    sizeof(grouped_bits[0]));
    uint32_t *expected_bits = calloc(CANONICAL_VALUE_COUNT,
                                     sizeof(expected_bits[0]));
    uint32_t *actual_bits = calloc(CANONICAL_VALUE_COUNT,
                                   sizeof(actual_bits[0]));
    float *expected_reduced = calloc(REDUCED_VALUE_COUNT,
                                     sizeof(expected_reduced[0]));
    float *actual_reduced = calloc(REDUCED_VALUE_COUNT,
                                   sizeof(actual_reduced[0]));
    ds4_gpu_tensor *selected = ds4_gpu_tensor_alloc(
        ROUTE_COUNT * sizeof(ids[0]));
    if (!ids || !first_routes || !grouped_bits || !expected_bits || !actual_bits ||
        !selected ||
        !expected_reduced || !actual_reduced) {
        free(ids);
        free(first_routes);
        free(grouped_bits);
        free(expected_bits);
        free(actual_bits);
        free(expected_reduced);
        free(actual_reduced);
        ds4_gpu_tensor_free(selected);
        return 0;
    }

    /* First install a different route under the same tensor identity, layer,
     * and shape used below.  A shape-only cache key will still match after the
     * tensor is overwritten, which reproduces consecutive 64-token chunks in
     * the layer-major macro-prefill loop. */
    for (uint32_t canonical = 0; canonical < ROUTE_COUNT; canonical++) {
        ids[canonical] = (int32_t)(canonical % N_EXPERT);
    }
    int ok = ds4_gpu_tensor_write(
                 selected, 0, ids, ROUTE_COUNT * sizeof(ids[0])) &&
             ds4_gpu_qwen35_expert_group_prepare_current(
                 ids, selected, 7u, N_TOKEN, N_ROUTE, N_EXPERT, 0, 1);
    if (ok) {
        memcpy(first_routes,
               g_qwen35_expert_group_plan.grouped_routes,
               ROUTE_COUNT * sizeof(first_routes[0]));
    }

    /* The second half deliberately duplicates the first half of each token.
     * This proves duplicate expert IDs remain separate weighted routes while
     * still providing a long 512-route permutation.  This is the second
     * consecutive route written into the same selected tensor. */
    for (uint32_t token = 0; token < N_TOKEN; token++) {
        for (uint32_t slot = 0; slot < N_ROUTE; slot++) {
            const uint32_t local = slot & 3u;
            ids[token * N_ROUTE + slot] =
                (int32_t)((token * 29u + local * 11u) % N_EXPERT);
        }
    }

    if (ok) {
        ok = ds4_gpu_tensor_write(
                 selected, 0, ids, ROUTE_COUNT * sizeof(ids[0])) &&
             /* Prove the old implementation's key would have looked valid. */
             ds4_gpu_qwen35_expert_group_matches(
                 selected, 7u, N_TOKEN, N_ROUTE, N_EXPERT) &&
             /* overlap=0 must nevertheless rebuild from the new IDs. */
             ds4_gpu_qwen35_expert_group_prepare_current(
                 ids, selected, 7u, N_TOKEN, N_ROUTE, N_EXPERT, 0, 1) &&
             memcmp(first_routes,
                    g_qwen35_expert_group_plan.grouped_routes,
                    ROUTE_COUNT * sizeof(first_routes[0])) != 0;
    }
    if (ok) {
        for (uint32_t grouped = 0; grouped < ROUTE_COUNT; grouped++) {
            const ds4_qwen_expert_group_route route =
                g_qwen35_expert_group_plan.grouped_routes[grouped];
            if (route.canonical_index >= ROUTE_COUNT ||
                route.expert != (uint32_t)ids[route.canonical_index] ||
                route.token_row != route.canonical_index / N_ROUTE ||
                route.route_slot != route.canonical_index % N_ROUTE ||
                g_qwen35_expert_group_plan
                    .canonical_to_grouped[route.canonical_index] != grouped) {
                ok = 0;
                break;
            }
        }
    }
    if (ok) {
        for (uint32_t grouped = 0; grouped < ROUTE_COUNT; grouped++) {
            const uint32_t canonical =
                g_qwen35_expert_group_plan.grouped_routes[grouped]
                    .canonical_index;
            for (uint32_t column = 0; column < WIDTH; column++) {
                /* Binary fractions keep the eight-slot expected reduction
                 * exact, so memcmp detects ordering/scatter bugs rather than
                 * platform-specific decimal rounding. */
                float value =
                    (float)((int32_t)(canonical % 31u) - 15) / 32.0f +
                    (float)column / 256.0f;
                uint32_t bits = 0;
                memcpy(&bits, &value, sizeof(bits));
                grouped_bits[grouped * WIDTH + column] = bits;
                expected_bits[canonical * WIDTH + column] = bits;
            }
        }
        /* Include signed zero in the bit-preserving scatter contract. */
        const uint32_t signed_zero_canonical = 117u;
        const uint32_t signed_zero_grouped =
            g_qwen35_expert_group_plan
                .canonical_to_grouped[signed_zero_canonical];
        grouped_bits[signed_zero_grouped * WIDTH + 3u] = 0x80000000u;
        expected_bits[signed_zero_canonical * WIDTH + 3u] = 0x80000000u;

        for (uint32_t token = 0; token < N_TOKEN; token++) {
            for (uint32_t column = 0; column < WIDTH; column++) {
                float sum = 0.0f;
                for (uint32_t slot = 0; slot < N_ROUTE; slot++) {
                    float value = 0.0f;
                    const uint32_t bits =
                        expected_bits[((token * N_ROUTE + slot) * WIDTH) +
                                      column];
                    memcpy(&value, &bits, sizeof(value));
                    sum += value;
                }
                expected_reduced[token * WIDTH + column] = sum;
            }
        }
    }

    ds4_gpu_tensor *grouped = ok ? ds4_gpu_tensor_alloc(
        sizeof(grouped_bits[0]) * CANONICAL_VALUE_COUNT) : NULL;
    ds4_gpu_tensor *canonical = ok ? ds4_gpu_tensor_alloc(
        sizeof(actual_bits[0]) * CANONICAL_VALUE_COUNT) : NULL;
    ds4_gpu_tensor *reduced = ok ? ds4_gpu_tensor_alloc(
        sizeof(actual_reduced[0]) * REDUCED_VALUE_COUNT) : NULL;
    ok = ok && grouped && canonical && reduced &&
         ds4_gpu_tensor_write(grouped, 0, grouped_bits,
                              sizeof(grouped_bits[0]) *
                                  CANONICAL_VALUE_COUNT) &&
         ds4_gpu_tensor_fill_f32(canonical, 12345.0f,
                                 CANONICAL_VALUE_COUNT) &&
         ds4_gpu_tensor_fill_f32(reduced, -12345.0f,
                                 REDUCED_VALUE_COUNT);

    @autoreleasepool {
        id<MTLComputePipelineState> scatter_pipeline = ok ?
            ds4_gpu_get_pipeline(
                "kernel_qwen35_expert_group_scatter_test_f32") : nil;
        id<MTLComputePipelineState> reduce_pipeline = ok ?
            ds4_gpu_get_pipeline(
                "kernel_qwen35_expert_group_reduce_test_f32") : nil;
        ok = ok && scatter_pipeline && reduce_pipeline;
        int owned = 0;
        id<MTLCommandBuffer> cb = ok ? ds4_gpu_command_buffer(&owned) : nil;
        ok = ok && cb;
        const ds4_gpu_qwen35_expert_group_test_args args = {
            .route_count = ROUTE_COUNT,
            .n_tokens = N_TOKEN,
            .routes_per_token = N_ROUTE,
            .width = WIDTH,
        };
        if (ok) {
            id<MTLComputeCommandEncoder> enc =
                ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:scatter_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:g_qwen35_expert_group_routes_buffer
                    offset:0 atIndex:1];
            [enc setBuffer:ds4_gpu_tensor_buffer(grouped)
                    offset:ds4_gpu_tensor_offset(grouped) atIndex:2];
            [enc setBuffer:ds4_gpu_tensor_buffer(canonical)
                    offset:ds4_gpu_tensor_offset(canonical) atIndex:3];
            [enc dispatchThreads:MTLSizeMake(CANONICAL_VALUE_COUNT, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:reduce_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:ds4_gpu_tensor_buffer(canonical)
                    offset:ds4_gpu_tensor_offset(canonical) atIndex:1];
            [enc setBuffer:ds4_gpu_tensor_buffer(reduced)
                    offset:ds4_gpu_tensor_offset(reduced) atIndex:2];
            [enc dispatchThreads:MTLSizeMake(REDUCED_VALUE_COUNT, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
            ok = ds4_gpu_finish_command_buffer(
                cb, owned, "Qwen expert-group contract test");
            if (ok && !owned) ok = ds4_gpu_synchronize();
        }
    }

    if (ok) {
        ok = ds4_gpu_tensor_read(canonical, 0, actual_bits,
                                 sizeof(actual_bits[0]) *
                                     CANONICAL_VALUE_COUNT) &&
             ds4_gpu_tensor_read(reduced, 0, actual_reduced,
                                 sizeof(actual_reduced[0]) *
                                     REDUCED_VALUE_COUNT) &&
             memcmp(actual_bits, expected_bits,
                    sizeof(actual_bits[0]) * CANONICAL_VALUE_COUNT) == 0 &&
             memcmp(actual_reduced, expected_reduced,
                    sizeof(actual_reduced[0]) * REDUCED_VALUE_COUNT) == 0;
    }

    /* The schedule implementation predates DeepSeek support and retains its
     * public Qwen name, so explicitly exercise the top-6 geometry here. This
     * catches accidental reintroduction of a top-8-only host gate while the
     * pipeline check proves the matching IQ2 Metal entry point was compiled. */
    if (ok) {
        enum {
            DEEPSEEK_ROUTE = 6,
            DEEPSEEK_ROUTE_COUNT = N_TOKEN * DEEPSEEK_ROUTE,
        };
        for (uint32_t canonical_index = 0;
             canonical_index < DEEPSEEK_ROUTE_COUNT;
             canonical_index++) {
            ids[canonical_index] = (int32_t)(
                (canonical_index * 37u + canonical_index / DEEPSEEK_ROUTE) %
                N_EXPERT);
        }
        if (!g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_grouped_pipeline) {
            g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_grouped_pipeline =
                ds4_gpu_get_moe_mv_pipeline(
                    "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_grouped_f32",
                    2);
        }
        /* Resolve every lazy experimental entry point here.  Model benchmarks
         * provide the numeric parity proof; this isolated test ensures a
         * future Metal refactor cannot leave an opt-in path uncompiled until a
         * user reaches it on a large model. */
        const bool lazy_pipelines_available =
            ds4_gpu_get_pipeline(
                "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_f32") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_r8_f32") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_decode_f32") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_f32") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_staged_f32") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_staged_f32") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mm_id_iq2_xxs_pair_swiglu_f16") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mm_id_iq2_xxs_pair_swiglu_f16_n16") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mm_id_q4_K_pair_swiglu_f16") != nil &&
            ds4_gpu_get_pipeline(
                "kernel_mul_mm_id_q4_K_pair_swiglu_f16_n16") != nil;
        ok = lazy_pipelines_available &&
             g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_grouped_pipeline != nil &&
             ds4_gpu_tensor_write(
                 selected, 0, ids,
                 DEEPSEEK_ROUTE_COUNT * sizeof(ids[0])) &&
             ds4_gpu_qwen35_expert_group_prepare_current(
                 ids, selected, 9u, N_TOKEN, DEEPSEEK_ROUTE, N_EXPERT, 0,
                 DS4_GPU_EXPERT_SCHEDULE_GROUP |
                 DS4_GPU_EXPERT_SCHEDULE_ROUTE_TILE) &&
             g_qwen35_expert_group_plan.routes_per_token == DEEPSEEK_ROUTE &&
             g_qwen35_expert_group_plan.route_count == DEEPSEEK_ROUTE_COUNT &&
             g_qwen35_expert_group_plan.route_tile_count > 0u;
        uint32_t tiled_routes = 0;
        for (uint32_t tile_index = 0;
             ok &&
             tile_index < g_qwen35_expert_group_plan.route_tile_count;
             tile_index++) {
            const ds4_expert_group_route_tile tile =
                g_qwen35_expert_group_plan.route_tiles[tile_index];
            if (tile.route_begin != tiled_routes ||
                tile.route_count == 0u ||
                tile.route_count > DS4_EXPERT_GROUP_ROUTE_TILE_SIZE ||
                tile.route_begin + tile.route_count > DEEPSEEK_ROUTE_COUNT) {
                ok = 0;
                break;
            }
            for (uint32_t local = 0; local < tile.route_count; local++) {
                if (g_qwen35_expert_group_plan
                        .grouped_routes[tile.route_begin + local].expert !=
                    tile.expert) {
                    ok = 0;
                    break;
                }
            }
            tiled_routes += tile.route_count;
        }
        ok = ok && tiled_routes == DEEPSEEK_ROUTE_COUNT;
        for (uint32_t grouped_index = 0;
             ok && grouped_index < DEEPSEEK_ROUTE_COUNT;
             grouped_index++) {
            const ds4_qwen_expert_group_route route =
                g_qwen35_expert_group_plan.grouped_routes[grouped_index];
            if (route.canonical_index >= DEEPSEEK_ROUTE_COUNT ||
                route.expert != (uint32_t)ids[route.canonical_index] ||
                route.token_row !=
                    route.canonical_index / DEEPSEEK_ROUTE ||
                route.route_slot !=
                    route.canonical_index % DEEPSEEK_ROUTE) {
                ok = 0;
            }
        }
    }

    ds4_gpu_tensor_free(grouped);
    ds4_gpu_tensor_free(canonical);
    ds4_gpu_tensor_free(reduced);
    ds4_gpu_tensor_free(selected);
    free(ids);
    free(first_routes);
    free(grouped_bits);
    free(expected_bits);
    free(actual_bits);
    free(expected_reduced);
    free(actual_reduced);
    ds4_gpu_qwen35_expert_group_invalidate();
    return ok;
}

int ds4_gpu_qwen35_routed_moe_batch_select_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                layer_index,
        uint32_t                n_tokens,
        bool                   *mid_is_f16,
        int                     request_expert_group,
        int                    *expert_group_used) {
    if (expert_group_used) *expert_group_used = 0;
    int selected_expert_group_used = 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !x || !model_map || !selected || !weights ||
        n_tokens == 0 || n_total_expert == 0 || n_expert == 0 || n_expert > 8) {
        return 0;
    }
    if (gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        gate_row_bytes == 0 || down_row_bytes == 0) {
        return 0;
    }
    if ((expert_in_dim % 256u) != 0 || (expert_mid_dim % 256u) != 0) return 0;
    if ((uint64_t)n_total_expert > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)n_total_expert > UINT64_MAX / down_expert_bytes) {
        fprintf(stderr, "ds4: Metal routed batch MoE tensor byte size overflow\n");
        return 0;
    }
    const uint64_t gate_tensor_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_tensor_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    uint32_t store_storage = DS4_EXPERT_STORE_STORAGE_GGML;
    uint64_t store_component_bytes[3] = {
        gate_expert_bytes, gate_expert_bytes, down_expert_bytes,
    };
