            use_mlx_affine_stream_mm_id;
        /*
         * MTP verification is neither normal decode nor large prefill: the
         * target model must verify a tiny suffix (usually 2 tokens) in one
         * layer-major pass.  For that shape the prefill expert-major GEMM path
         * is too large, but the decode pair kernels are exactly the right
         * primitive: they read the same activation once and compute routed
         * gate/up together for every selected expert row.  Keep this limited to
         * tiny batches so ordinary prefill keeps using the higher-throughput
         * grouped matmul path.
         */
        const bool use_tiny_pair_mv =
            !mlx_affine_store &&
            !g_quality_mode &&
            (n_tokens <= 4u || use_qwen_resident_prefill_pair_mv) &&
            !use_q4_batch_expert_table &&
            !use_mm_id &&
            ((gate_type == DS4_METAL_TENSOR_IQ2_XXS && g_moe_mul_mv_id_iq2_xxs_pair_pipeline) ||
             (gate_type == DS4_METAL_TENSOR_Q4_K && g_moe_mul_mv_id_q4_k_pair_pipeline));
        ds4_gpu_mul_mm_id_map_args gate_map_args = { 0 };
        ds4_gpu_mul_mm_id_args gate_mm_args = { 0 };
        ds4_gpu_mul_mm_id_args down_mm_args = { 0 };
        id<MTLComputePipelineState> map_pipeline = nil;
        /*
         * The grouped routed-MoE matmul loads activation tiles as half before
         * using SIMD-group MMA.  Store the SwiGLU/route-weight intermediate in
         * that same precision so the down projection avoids a large F32 mid
         * write/read. --quality keeps the older F32 intermediate.
         */
        const bool request_mid_f16 =
            !g_quality_mode &&
            !use_q4_batch_expert_table &&
            (!use_stream_batch_selected_addr || use_stream_mm_id);
        const bool use_mm_id_pair_swiglu =
            use_mm_id &&
            request_mid_f16 &&
            ((mlx_affine_store &&
              n_total_expert == 256u &&
             n_expert == 8u &&
              n_tokens < 2048u) ||
             (gate_type == DS4_METAL_TENSOR_IQ2_XXS &&
              down_type == DS4_METAL_TENSOR_Q2_K &&
              n_expert == 6) ||
             (gate_type == DS4_METAL_TENSOR_Q4_K &&
              down_type == DS4_METAL_TENSOR_Q4_K &&
              n_total_expert == 256u &&
              n_expert == 8 &&
              /* The paired accumulator kernel wins through 1K tokens.  At
               * the resident 2K cap, two ordinary N32 routed MMs recover
               * enough occupancy to beat it by about one percent. */
              n_tokens < 2048u)) &&
            /* The fused kernel is algebraically the same gate/up + SwiGLU +
             * route-weight sequence as the split path, but reads the input
             * activation once and never writes the two large F32 temporaries.
             * Keep one disable-only switch for numerical/perf bisects. */
            getenv("DS4_METAL_DISABLE_MOE_MM_ID_PAIR_SWIGLU") == NULL &&
            getenv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") == NULL &&
            getenv("DS4_METAL_GRAPH_DUMP_PREFIX") == NULL;
        const bool use_mlx_affine_nax =
            mlx_affine_store &&
            use_mm_id &&
            ds4_gpu_mpp_available() &&
            n_tokens >= 2048u;
        const NSUInteger mm_id_threadgroup_bytes = 8192u;
        if (use_mm_id || use_stream_mm_id) {
            gate_map_args =
                ds4_gpu_make_mul_mm_id_map_args(expert_in_dim, n_total_expert, 1, n_expert, n_tokens);
            gate_mm_args =
                ds4_gpu_make_mul_mm_id_args(expert_in_dim, expert_mid_dim, n_total_expert,
                                              gate_row_bytes,
                                              store_component_bytes[0],
                                              1, n_expert, n_tokens);
            down_mm_args =
                ds4_gpu_make_mul_mm_id_args_src1_size(expert_mid_dim, out_dim, n_total_expert,
                                                        down_row_bytes,
                                                        store_component_bytes[2],
                                                        n_expert, n_expert, n_tokens,
                                                        request_mid_f16 ? sizeof(uint16_t) : sizeof(float));
            if (use_expert_major) {
                gate_mm_args.nb02 = expert_major_stride;
                gate_mm_args.nb03 =
                    (uint64_t)n_total_expert * expert_major_stride;
                down_mm_args.nb02 = expert_major_stride;
                down_mm_args.nb03 =
                    (uint64_t)n_total_expert * expert_major_stride;
            }

            map_pipeline = ds4_gpu_get_pipeline(
                use_qwen_iq_compact_mm ?
                    "kernel_mul_mm_id_map0_compact_qwen8" :
                    ds4_gpu_mul_mm_id_map0_name(n_expert));
            if (use_mlx_affine_stream_mm_id) {
                gate_mm_pipeline = ds4_gpu_get_mul_mm_id_pipeline(
                    "kernel_mul_mm_id_addr_mlx_affine4_64_f32", false);
                up_mm_pipeline = gate_mm_pipeline;
                down_mm_pipeline = ds4_gpu_get_mul_mm_id_pipeline(
                    request_mid_f16
                        ? "kernel_mul_mm_id_addr_mlx_affine4_64_f16"
                        : "kernel_mul_mm_id_addr_mlx_affine4_64_f32",
                    false);
            } else if (mlx_affine_store) {
                gate_mm_pipeline = use_mlx_affine_nax
                    ? ds4_gpu_get_pipeline(
                          "kernel_mul_mm_id_mlx_affine4_64_nax_f32")
                    : ds4_gpu_get_mul_mm_id_pipeline(
                          "kernel_mul_mm_id_mlx_affine4_64_f32", false);
                up_mm_pipeline = gate_mm_pipeline;
                down_mm_pipeline = use_mlx_affine_nax
                    ? ds4_gpu_get_pipeline(
                          request_mid_f16
                              ? "kernel_mul_mm_id_mlx_affine4_64_nax_f16"
                              : "kernel_mul_mm_id_mlx_affine4_64_nax_f32")
                    : ds4_gpu_get_mul_mm_id_pipeline(
                          request_mid_f16
                              ? "kernel_mul_mm_id_mlx_affine4_64_f16"
                              : "kernel_mul_mm_id_mlx_affine4_64_f32",
                          false);
            } else if (use_qwen_iq_stream_mm_id) {
                gate_mm_pipeline =
                    ds4_gpu_routed_mm_addr_pipeline(gate_type);
                up_mm_pipeline = gate_mm_pipeline;
                down_mm_pipeline = request_mid_f16 ?
                    ds4_gpu_routed_mm_addr_f16_rhs_pipeline(down_type) :
                    ds4_gpu_routed_mm_addr_pipeline(down_type);
            } else {
                gate_mm_pipeline = use_qwen_iq_compact_mm ?
                    ds4_gpu_qwen_compact_mm_pipeline(gate_type, false) :
                    ds4_gpu_routed_mm_pipeline(gate_type);
                up_mm_pipeline = gate_mm_pipeline;
                down_mm_pipeline = use_qwen_iq_compact_mm ?
                    ds4_gpu_qwen_compact_mm_pipeline(
                        down_type, request_mid_f16) :
                    (request_mid_f16 ?
                        ds4_gpu_routed_mm_f16_rhs_pipeline(down_type) :
                        ds4_gpu_routed_mm_pipeline(down_type));
            }
            if (use_mm_id_pair_swiglu) {
                /* Qwen's Q4 pair doubles the accumulator set relative to the
                 * ordinary routed MM.  A 16-route tile preserves occupancy on
                 * Apple GPUs, while DeepSeek IQ2 keeps its established N32
                 * default unless explicitly opted into the narrower tile. */
                const bool request_pair_n16 =
                    (gate_type == DS4_METAL_TENSOR_Q4_K ||
                     getenv("DS4_METAL_ENABLE_MOE_MM_ID_PAIR_NR16") != NULL) &&
                    getenv("DS4_METAL_DISABLE_MOE_MM_ID_PAIR_NR16") == NULL;
                pair_swiglu_mm_tile_n = request_pair_n16 ? 16u : 32u;
                const bool q4_pair =
                    gate_type == DS4_METAL_TENSOR_Q4_K;
                pair_swiglu_mm_pipeline = ds4_gpu_get_pipeline(
                    mlx_affine_store
                        ? (request_pair_n16
                               ? "kernel_mul_mm_id_mlx_affine4_64_pair_swiglu_f16_n16"
                               : "kernel_mul_mm_id_mlx_affine4_64_pair_swiglu_f16")
                        : q4_pair ?
                        (request_pair_n16 ?
                            "kernel_mul_mm_id_q4_K_pair_swiglu_f16_n16" :
                            "kernel_mul_mm_id_q4_K_pair_swiglu_f16") :
                        (request_pair_n16 ?
                            "kernel_mul_mm_id_iq2_xxs_pair_swiglu_f16_n16" :
                            "kernel_mul_mm_id_iq2_xxs_pair_swiglu_f16"));
            }
            if (!map_pipeline || !gate_mm_pipeline || !up_mm_pipeline ||
                !down_mm_pipeline ||
                (use_mm_id_pair_swiglu && !pair_swiglu_mm_pipeline)) {
                fprintf(stderr,
                        "ds4: Metal routed batch pipeline unavailable layer=%u "
                        "codec=%u map=%d gate=%d up=%d down=%d pair=%d\n",
                        layer_index,
                        store_storage,
                        map_pipeline != nil,
                        gate_mm_pipeline != nil,
                        up_mm_pipeline != nil,
                        down_mm_pipeline != nil,
                        !use_mm_id_pair_swiglu ||
                            pair_swiglu_mm_pipeline != nil);
                return 0;
            }
        }
        if (use_stream_batch_selected_addr) {
            const int had_batch = g_batch_cb != nil;
            const ds4_gpu_stream_expert_table overlap_table = {
                .model_map = model_map,
                .model_size = model_size,
                .layer = layer_index,
                .n_total_expert = n_total_expert,
                .gate_offset = gate_offset,
                .up_offset = up_offset,
                .down_offset = down_offset,
                .gate_expert_bytes = store_component_bytes[0],
                .down_expert_bytes = store_component_bytes[2],
            };
            const bool stream_overlap_generation =
                use_stream_batch_selected_addr &&
                ds4_gpu_qwen35_stream_pending_matches(
                    &overlap_table,
                    selected,
                    n_tokens,
                    n_expert);
            if (had_batch && !stream_overlap_generation &&
                ds4_gpu_end_commands() == 0) {
                return 0;
            }
            g_stream_prefill_batch_selected_addr_building++;
            if (!ds4_gpu_stream_expert_cache_prepare_selected_batch(
                        model_map,
                        model_size,
                        layer_index,
                        selected,
                        n_tokens,
                        n_total_expert,
                        n_expert,
                        gate_offset,
                        up_offset,
                        down_offset,
                        store_component_bytes[0],
                        store_component_bytes[2],
                        &stream_gate_addr_buf,
                        &stream_up_addr_buf,
                        &stream_down_addr_buf,
                        stream_resources,
                        &stream_resource_count,
                        &stream_unique,
                        stream_expert_schedule_request)) {
                g_stream_prefill_batch_selected_addr_building--;
                return 0;
            }
            g_stream_prefill_batch_selected_addr_building--;
            if (stream_unique == 0) {
                ds4_gpu_stream_expert_cache_clear_layer(layer_index);
                fprintf(stderr,
                        "ds4: Metal streaming prefill batch selected addr layer=%u "
                        "produced no resident experts\n",
                        layer_index);
                return 0;
            }
            for (uint32_t i = 0; i < stream_resource_count; i++) {
                ds4_gpu_stream_expert_cache_entry *entry = stream_resources[i];
                if (!entry ||
                    !entry->valid ||
                    !entry->gate_buffer ||
                    !entry->up_buffer ||
                    !entry->down_buffer) {
                    fprintf(stderr,
                            "ds4: Metal streaming prefill batch selected addr layer=%u "
                            "lost resident expert resource %u/%u during preparation\n",
                            layer_index,
                            i,
                            stream_resource_count);
                    ds4_gpu_stream_expert_cache_clear_layer(layer_index);
                    return 0;
                }
            }
            if (had_batch && !stream_overlap_generation &&
                ds4_gpu_begin_commands() == 0) {
                fprintf(stderr,
                        "ds4: Metal streaming prefill batch selected addr layer=%u "
                        "failed to reopen command batch after preparation\n",
                        layer_index);
                ds4_gpu_stream_expert_cache_clear_layer(layer_index);
                return 0;
            }
        }

        const bool stream_expert_group_matches =
            stream_expert_schedule_request != 0 &&
            ds4_gpu_qwen35_expert_group_matches(
                selected, layer_index, n_tokens, n_expert, n_total_expert);
        id<MTLComputePipelineState> stream_group_pipeline = nil;
        id<MTLComputePipelineState> stream_tile_pipeline = nil;
        const bool deepseek_expert_tile_decode_shared =
            deepseek_expert_tile_requested &&
            getenv("DS4_METAL_ENABLE_DEEPSEEK_EXPERT_TILE_DECODE_SHARED") != NULL &&
            getenv("DS4_METAL_DISABLE_DEEPSEEK_EXPERT_TILE_DECODE_SHARED") == NULL;
        const bool deepseek_expert_tile_row8 =
            deepseek_expert_tile_requested &&
            !deepseek_expert_tile_decode_shared &&
            getenv("DS4_METAL_ENABLE_DEEPSEEK_EXPERT_TILE_ROW8") != NULL &&
            getenv("DS4_METAL_DISABLE_DEEPSEEK_EXPERT_TILE_ROW8") == NULL;
        const bool deepseek_expert_tile_staged =
            deepseek_expert_tile_requested &&
            !deepseek_expert_tile_decode_shared &&
            !deepseek_expert_tile_row8 &&
            getenv("DS4_METAL_ENABLE_DEEPSEEK_EXPERT_TILE_STAGED") != NULL &&
            getenv("DS4_METAL_DISABLE_DEEPSEEK_EXPERT_TILE_STAGED") == NULL;
        const bool deepseek_expert_tile_pair =
            deepseek_expert_tile_requested &&
            !deepseek_expert_tile_decode_shared &&
            !deepseek_expert_tile_row8 &&
            getenv("DS4_METAL_ENABLE_DEEPSEEK_EXPERT_TILE_PAIR") != NULL &&
            getenv("DS4_METAL_DISABLE_DEEPSEEK_EXPERT_TILE_PAIR") == NULL;
        const uint32_t deepseek_expert_tile_output_rows =
            deepseek_expert_tile_row8 ? 8u : 4u;
        const uint32_t deepseek_expert_tile_routes =
            deepseek_expert_tile_pair ? 2u : 4u;
        const NSUInteger deepseek_expert_tile_smem =
            deepseek_expert_tile_decode_shared ?
                DS4_METAL_DEEPSEEK_IQ2_ROUTE_TILE_DECODE_SMEM :
            deepseek_expert_tile_row8 ?
                DS4_METAL_DEEPSEEK_IQ2_ROUTE_TILE_R8_SMEM :
            deepseek_expert_tile_staged ?
                DS4_METAL_DEEPSEEK_IQ2_ROUTE_TILE_STAGED_SMEM :
                DS4_METAL_DEEPSEEK_IQ2_ROUTE_TILE_R4_SMEM;
        bool deepseek_expert_tile_plan_shape_ok = true;
        if (deepseek_expert_tile_pair && stream_expert_group_matches) {
            deepseek_expert_tile_plan_shape_ok =
                ds4_qwen_expert_group_plan_retile(
                    &g_qwen35_expert_group_plan,
                    2u) == DS4_QWEN_EXPERT_GROUP_OK;
            if (deepseek_expert_tile_plan_shape_ok) {
                g_qwen35_expert_group_key.route_tile_count =
                    g_qwen35_expert_group_plan.route_tile_count;
                g_qwen35_expert_group_key.route_tiles_uploaded = 0;
            }
        }
        const bool deepseek_expert_tile_plan_reusable =
            stream_expert_group_matches &&
            deepseek_expert_tile_plan_shape_ok &&
            g_qwen35_expert_group_key.route_tile_count > 0u &&
            g_qwen35_expert_group_key.route_tile_count <=
                g_qwen35_expert_group_key.route_count;
        if (deepseek_expert_tile_requested &&
            deepseek_expert_tile_plan_reusable) {
            /* This experimental pipeline is intentionally lazy: models and
             * machines that never request it pay no startup compilation or
             * pipeline-memory cost. */
            if (deepseek_expert_tile_decode_shared) {
                if (!g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_decode_pipeline) {
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_decode_pipeline =
                        ds4_gpu_get_pipeline(
                            "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_decode_f32");
                }
                stream_tile_pipeline =
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_decode_pipeline;
            } else if (deepseek_expert_tile_row8) {
                if (!g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_r8_pipeline) {
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_r8_pipeline =
                        ds4_gpu_get_pipeline(
                            "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_r8_f32");
                }
                stream_tile_pipeline =
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_r8_pipeline;
            } else if (deepseek_expert_tile_pair &&
                       deepseek_expert_tile_staged) {
                if (!g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_staged_pipeline) {
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_staged_pipeline =
                        ds4_gpu_get_pipeline(
                            "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_staged_f32");
                }
                stream_tile_pipeline =
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_staged_pipeline;
            } else if (deepseek_expert_tile_pair) {
                if (!g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_pipeline) {
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_pipeline =
                        ds4_gpu_get_pipeline(
                            "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_f32");
                }
                stream_tile_pipeline =
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pair_pipeline;
            } else if (deepseek_expert_tile_staged) {
                if (!g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_staged_pipeline) {
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_staged_pipeline =
                        ds4_gpu_get_pipeline(
                            "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_staged_f32");
                }
                stream_tile_pipeline =
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_staged_pipeline;
            } else {
                if (!g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pipeline) {
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pipeline =
                        ds4_gpu_get_pipeline(
                            "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_f32");
                }
                stream_tile_pipeline =
                    g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_tiled_pipeline;
            }
        }
        const bool use_deepseek_stream_expert_tile =
            deepseek_expert_tile_requested &&
            use_iq2_batch_selected_addr &&
            deepseek_expert_tile_plan_reusable &&
            ds4_gpu_expert_group_upload_route_tiles() &&
            g_expert_group_route_tiles_buffer != nil &&
            stream_tile_pipeline != nil;
        if (use_deepseek_stream_expert_tile &&
            getenv("DS4_METAL_DEEPSEEK_EXPERT_TILE_PROFILE") != NULL) {
            const double reuse =
                (double)g_qwen35_expert_group_key.route_count /
                (double)g_qwen35_expert_group_key.route_tile_count;
            fprintf(stderr,
                    "ds4: DeepSeek expert-tile layer=%u tokens=%u routes=%u "
                    "tiles=%u routes_per_tile=%.3f tile_capacity=%u "
                    "rows_per_group=%u staged=%u unique=%u\n",
                    layer_index,
                    n_tokens,
                    g_qwen35_expert_group_key.route_count,
                    g_qwen35_expert_group_key.route_tile_count,
                    reuse,
                    deepseek_expert_tile_routes,
                    deepseek_expert_tile_output_rows,
                    deepseek_expert_tile_staged ? 1u : 0u,
                    stream_unique);
        }
        const bool use_qwen_stream_expert_group =
            qwen_expert_group_requested &&
            use_qwen_q4_batch_selected_addr &&
            stream_expert_group_matches &&
            (stream_group_pipeline =
                g_moe_mul_mv_addr_q4_k_pair_swiglu_grouped_pipeline) != nil;
        if (deepseek_expert_group_requested &&
            !use_deepseek_stream_expert_tile &&
            stream_expert_group_matches &&
            !g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_grouped_pipeline) {
            g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_grouped_pipeline =
                ds4_gpu_get_moe_mv_pipeline(
                    "kernel_mul_mv_addr_iq2_xxs_pair_swiglu_grouped_f32",
                    2);
        }
        const bool use_deepseek_stream_expert_group =
            deepseek_expert_group_requested &&
            !use_deepseek_stream_expert_tile &&
            use_iq2_batch_selected_addr &&
            stream_expert_group_matches &&
            (stream_group_pipeline =
                g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_grouped_pipeline) != nil;
        const bool use_stream_expert_group =
            use_qwen_stream_expert_group ||
            use_deepseek_stream_expert_group;
        /* A schedule request is an optimization, not a correctness
         * prerequisite.  If a lazy experimental pipeline is unavailable,
         * encode the exact pre-existing selected-address path and report the
         * precise used mask.  ds4.c rejects that fallback for explicit A/B
         * requests, while an automatic policy may safely keep serving. */
        const bool use_resident_expert_group =
            qwen_expert_group_requested &&
            !g_ssd_streaming_mode && use_mm_id;
        const int actual_expert_schedule =
            use_deepseek_stream_expert_tile ?
                (DS4_GPU_EXPERT_SCHEDULE_GROUP |
                 DS4_GPU_EXPERT_SCHEDULE_ROUTE_TILE) :
            (use_stream_expert_group ||
             use_resident_expert_group) ?
                DS4_GPU_EXPERT_SCHEDULE_GROUP : 0;

        if (use_expert_major) {
            if (n_expert > 1 && (!expertsbuf ||
                ds4_gpu_tensor_bytes(experts) < down_scratch_bytes)) {
                if (!ds4_gpu_ensure_scratch_buffer(
                        &g_moe_down_scratch_buffer,
                        &g_moe_down_scratch_bytes,
                        (NSUInteger)down_scratch_bytes,
                        "ds4_moe_down_scratch")) {
                    return 0;
                }
            }
            gate_buf = expert_major_buffer;
            up_buf = expert_major_buffer;
            down_buf = expert_major_buffer;
            gate_inner = expert_major_gate_inner;
            up_inner = expert_major_up_inner;
            down_inner = expert_major_down_inner;
        } else if (use_q4_batch_expert_table) {
            gate_table = ds4_gpu_q4_expert_table(model_map,
                                                 model_size,
                                                 gate_offset,
                                                 gate_expert_bytes,
                                                 n_total_expert,
                                                 g_moe_table_q4_pair_gate_encoder);
            up_table = ds4_gpu_q4_expert_table(model_map,
                                               model_size,
                                               up_offset,
                                               gate_expert_bytes,
                                               n_total_expert,
                                               g_moe_table_q4_pair_up_encoder);
            down_table = ds4_gpu_q4_expert_table(model_map,
                                                 model_size,
                                                 down_offset,
                                                 down_expert_bytes,
                                                 n_total_expert,
                                                 g_moe_table_q4_sum_down_encoder);
            if (!gate_table || !up_table || !down_table) {
                return 0;
            }
            q4_table_layer_residency =
                ds4_gpu_q4_expert_layer_residency_set(gate_table,
                                                       up_table,
                                                       down_table,
                                                       q4_batch_expert_table_auto);
            if ((q4_batch_table_queue_residency ||
                 getenv("DS4_METAL_Q4_TABLE_RESIDENCY_SET") != NULL) &&
                !q4_table_layer_residency &&
                !ds4_gpu_q4_table_model_residency_enabled()) {
                fprintf(stderr, "ds4: Metal Q4 batch expert table residency set is not available\n");
                return 0;
            }
        } else if (use_stream_batch_selected_addr) {
            if (n_expert > 1 && (!expertsbuf ||
                ds4_gpu_tensor_bytes(experts) < down_scratch_bytes)) {
                if (!ds4_gpu_ensure_scratch_buffer(&g_moe_down_scratch_buffer,
                                                   &g_moe_down_scratch_bytes,
                                                   (NSUInteger)down_scratch_bytes,
                                                   "ds4_moe_down_scratch")) {
                    ds4_gpu_stream_expert_cache_clear_layer(layer_index);
                    return 0;
                }
            }
        } else {
            if (n_expert > 1 && (!expertsbuf ||
                ds4_gpu_tensor_bytes(experts) < down_scratch_bytes)) {
                if (!ds4_gpu_ensure_scratch_buffer(&g_moe_down_scratch_buffer,
                                                   &g_moe_down_scratch_bytes,
                                                   (NSUInteger)down_scratch_bytes,
                                                   "ds4_moe_down_scratch")) {
                    return 0;
                }
            }
            gate_buf = ds4_gpu_wrap_model_range(model_map,
                                                model_size,
                                                gate_offset,
                                                gate_tensor_bytes,
                                                &gate_inner);
            up_buf = ds4_gpu_wrap_model_range(model_map,
                                              model_size,
                                              up_offset,
                                              gate_tensor_bytes,
                                              &up_inner);
            down_buf = ds4_gpu_wrap_model_range(model_map,
                                                model_size,
                                                down_offset,
                                                down_tensor_bytes,
                                                &down_inner);
            if (!gate_buf || !up_buf || !down_buf) return 0;
        }

        const bool q4_batch_table_boundary =
            use_q4_batch_expert_table &&
            g_batch_cb != nil &&
            getenv("DS4_METAL_Q4_TABLE_RESIDENCY_SET") != NULL &&
            !q4_batch_table_queue_residency &&
            getenv("DS4_METAL_DISABLE_Q4_TABLE_BOUNDARY") == NULL;
        if (q4_batch_table_boundary) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                return 0;
            }
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        if (use_q4_batch_expert_table && !ds4_gpu_use_model_residency_set(cb)) {
            return 0;
        }
        if (!q4_batch_table_queue_residency &&
            q4_table_layer_residency &&
            [cb respondsToSelector:@selector(useResidencySet:)]) {
            [cb useResidencySet:q4_table_layer_residency];
        }
        const bool moe_stage_profile =
            g_batch_cb != nil &&
            ds4_gpu_stage_profile_enabled_for_layer("DS4_METAL_MOE_STAGE_PROFILE",
                                                    "DS4_METAL_MOE_STAGE_PROFILE_LAYER",
                                                    layer_index);
        const char *moe_stage_filter = getenv("DS4_METAL_MOE_STAGE_PROFILE_FILTER");
        const char *moe_path =
            use_mm_id_pair_swiglu && pair_swiglu_mm_tile_n == 16u ?
                "mm_id_pair_swiglu_n16" :
            use_mm_id_pair_swiglu ? "mm_id_pair_swiglu_n32" :
            use_mlx_affine_nax ? "mlx_affine_nax" :
            use_expert_major ? "expert_major" :
            use_q4_batch_expert_table ? "q4_table_pair_swiglu" :
            use_deepseek_stream_expert_tile &&
                deepseek_expert_tile_decode_shared ?
                "deepseek_iq2_expert_tile_decode_stream_addr" :
            use_deepseek_stream_expert_tile && deepseek_expert_tile_row8 ?
                "deepseek_iq2_expert_tile_r8_stream_addr" :
            use_deepseek_stream_expert_tile && deepseek_expert_tile_pair &&
                deepseek_expert_tile_staged ?
                "deepseek_iq2_expert_tile_pair_staged_stream_addr" :
            use_deepseek_stream_expert_tile && deepseek_expert_tile_pair ?
                "deepseek_iq2_expert_tile_pair_stream_addr" :
            use_deepseek_stream_expert_tile && deepseek_expert_tile_staged ?
                "deepseek_iq2_expert_tile_staged_stream_addr" :
            use_deepseek_stream_expert_tile ?
                "deepseek_iq2_expert_tile_stream_addr" :
            use_deepseek_stream_expert_group ?
                "deepseek_iq2_expert_group_stream_addr" :
            use_qwen_stream_expert_group ?
                "qwen_q4_expert_group_stream_addr" :
            use_qwen_iq_stream_mm_id ?
                "qwen_iq_mm_id_stream_addr" :
            use_qwen_iq_compact_mm ?
                "qwen_iq_compact_mm" :
            use_qwen_q4_batch_selected_addr ? "qwen_q4_batch_stream_addr" :
            use_iq2_batch_selected_addr ? "iq2_batch_stream_addr" :
            use_mm_id ? "mm_id" :
            (use_tiny_pair_mv ? "tiny_pair_mv" : "mv");
        double moe_stage_t0 = moe_stage_profile ? ds4_gpu_now_ms() : 0.0;
        if (moe_stage_profile) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                return 0;
            }
            cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            moe_stage_t0 = ds4_gpu_now_ms();
        }
#define DS4_METAL_PROFILE_MOE_STAGE(name) do { \
            if (ok && moe_stage_profile) { \
                if (ds4_gpu_end_commands() == 0) { \
                    ok = 0; \
                } else { \
                    const char *stage_name = (name); \
                    const double now_ms = ds4_gpu_now_ms(); \
                    const int print_stage = \
                        !moe_stage_filter || !moe_stage_filter[0] || \
                        strstr(stage_name, moe_stage_filter) != NULL; \
                    if (print_stage) { \
                        fprintf(stderr, \
                                "ds4: Metal routed MoE stage layer=%u tokens=%u pairs=%u experts=%u " \
                                "gate=%s down=%s path=%s mid=%s %s=%.3f ms\n", \
                                layer_index, n_tokens, pair_rows, n_expert, \
                                ds4_gpu_metal_tensor_type_name(gate_type), \
                                ds4_gpu_metal_tensor_type_name(down_type), \
                                moe_path, \
                                request_mid_f16 ? "f16" : "f32", \
                                stage_name, now_ms - moe_stage_t0); \
                    } \
                    moe_stage_t0 = now_ms; \
                    if (ds4_gpu_begin_commands() == 0) { \
                        ok = 0; \
                    } else { \
                        cb = ds4_gpu_command_buffer(&owned); \
                        if (!cb) ok = 0; \
                    } \
                } \
            } \
        } while (0)

        const NSUInteger gate_smem =
            mlx_affine_store ? 0u : ds4_gpu_routed_mv_smem(gate_type);
        const NSUInteger down_smem =
            mlx_affine_store ? 0u : ds4_gpu_routed_mv_smem(down_type);
        id<MTLComputePipelineState> down_sum6_pipeline = nil;
        if (down_type == DS4_METAL_TENSOR_Q2_K) {
            down_sum6_pipeline = g_moe_mul_mv_id_q2_k_sum6_pipeline;
        } else if (down_type == DS4_METAL_TENSOR_Q4_K) {
            down_sum6_pipeline = g_moe_mul_mv_id_q4_k_sum6_pipeline;
        }
        const bool direct_down_sum =
            !g_quality_mode &&
            !use_q4_batch_expert_table &&
            !use_mm_id &&
            n_expert == 6 &&
            n_tokens <= 4u &&
            down_sum6_pipeline != nil;
        const bool affine_pair_writes_mid =
            mlx_affine_store &&
            ((!use_stream_batch_selected_addr && !use_mm_id) ||
             (use_stream_batch_selected_addr &&
              !use_mlx_affine_stream_mm_id));
        int ok = 0;
        if (use_stream_batch_selected_addr) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim,
                .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float),
                .write_clamped = 0,
                .clamp_value = clamp,
            };
            if (use_stream_mm_id) {
                ok = ds4_gpu_encode_mul_mm_id_map(
                    cb,
                    map_pipeline,
                    &gate_map_args,
                    &gate_mm_args,
                    selectedbuf,
                    ds4_gpu_tensor_offset(selected));
            }
            if (use_qwen_iq_batch_selected_addr) {
                ok = ok &&
                    ds4_gpu_encode_mul_mm_id_addr_mapped_tile(
                        cb,
                        gate_mm_pipeline,
                        &gate_mm_args,
                        stream_gate_addr_buf,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        gatebuf,
                        ds4_gpu_tensor_offset(gate),
                        mm_id_threadgroup_bytes,
                        stream_resources,
                        stream_resource_count,
                        0) &&
                    ds4_gpu_encode_mul_mm_id_addr_mapped_tile(
                        cb,
                        up_mm_pipeline,
                        &gate_mm_args,
                        stream_up_addr_buf,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        upbuf,
                        ds4_gpu_tensor_offset(up),
                        mm_id_threadgroup_bytes,
                        stream_resources,
                        stream_resource_count,
                        1);
            } else if (use_qwen_q4_batch_selected_addr) {
                if (use_mlx_affine_stream_mm_id) {
                    ok = ok &&
                        ds4_gpu_encode_mul_mm_id_addr_mapped_tile(
                            cb, gate_mm_pipeline, &gate_mm_args,
                            stream_gate_addr_buf,
                            xbuf, ds4_gpu_tensor_offset(x),
                            gatebuf, ds4_gpu_tensor_offset(gate),
                            mm_id_threadgroup_bytes,
                            stream_resources, stream_resource_count, 0) &&
                        ds4_gpu_encode_mul_mm_id_addr_mapped_tile(
                            cb, up_mm_pipeline, &gate_mm_args,
                            stream_up_addr_buf,
                            xbuf, ds4_gpu_tensor_offset(x),
                            upbuf, ds4_gpu_tensor_offset(up),
                            mm_id_threadgroup_bytes,
                            stream_resources, stream_resource_count, 1);
                } else if (use_qwen_stream_expert_group) {
                    ok = ds4_gpu_encode_mul_mv_addr_pair_swiglu_grouped_stream(
                            cb,
                            stream_group_pipeline,
                            &gate_args,
                            &act_args,
                            stream_resources,
                            stream_resource_count,
                            stream_gate_addr_buf,
                            stream_up_addr_buf,
                            xbuf,
                            ds4_gpu_tensor_offset(x),
                            gatebuf,
                            ds4_gpu_tensor_offset(gate),
                            upbuf,
                            ds4_gpu_tensor_offset(up),
                            midbuf,
                            ds4_gpu_tensor_offset(mid),
                            g_qwen35_expert_group_routes_buffer,
                            g_qwen35_expert_group_key.route_count,
                            weightsbuf,
                            ds4_gpu_tensor_offset(weights),
                            gate_smem,
                            2);
                } else {
                    id<MTLComputePipelineState> pair_pipeline =
                        mlx_affine_store
                            ? ds4_gpu_get_moe_mv_pipeline(
                                "kernel_mul_mv_addr_mlx_affine4_64_pair_swiglu_f32",
                                2)
                            : g_moe_mul_mv_addr_q4_k_pair_swiglu_pipeline;
                    ok = ds4_gpu_encode_mul_mv_addr_q4_pair_swiglu_stream(
                            cb,
                            pair_pipeline,
                            &gate_args,
                            &act_args,
                            stream_resources,
                            stream_resource_count,
                            stream_gate_addr_buf,
                            stream_up_addr_buf,
                            xbuf,
                            ds4_gpu_tensor_offset(x),
                            gatebuf,
                            ds4_gpu_tensor_offset(gate),
                            upbuf,
                            ds4_gpu_tensor_offset(up),
                            midbuf,
                            ds4_gpu_tensor_offset(mid),
                            selectedbuf,
                            ds4_gpu_tensor_offset(selected),
                            weightsbuf,
                            ds4_gpu_tensor_offset(weights),
                            gate_smem,
                            2,
                            false);
                }
            } else if (use_deepseek_stream_expert_tile) {
                ok = ds4_gpu_encode_mul_mv_addr_iq2_pair_swiglu_tiled_stream(
                        cb,
                        stream_tile_pipeline,
                        &gate_args,
                        &act_args,
                        stream_resources,
                        stream_resource_count,
                        stream_gate_addr_buf,
                        stream_up_addr_buf,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        gatebuf,
                        ds4_gpu_tensor_offset(gate),
                        upbuf,
                        ds4_gpu_tensor_offset(up),
                        midbuf,
                        ds4_gpu_tensor_offset(mid),
                        g_qwen35_expert_group_routes_buffer,
                        g_qwen35_expert_group_key.route_count,
                        g_expert_group_route_tiles_buffer,
                        g_qwen35_expert_group_key.route_tile_count,
                        weightsbuf,
                        ds4_gpu_tensor_offset(weights),
                        deepseek_expert_tile_output_rows,
                        deepseek_expert_tile_smem,
                        deepseek_expert_tile_routes);
            } else if (use_deepseek_stream_expert_group) {
                ok = ds4_gpu_encode_mul_mv_addr_pair_swiglu_grouped_stream(
                        cb,
                        stream_group_pipeline,
                        &gate_args,
                        &act_args,
                        stream_resources,
                        stream_resource_count,
                        stream_gate_addr_buf,
                        stream_up_addr_buf,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        gatebuf,
                        ds4_gpu_tensor_offset(gate),
                        upbuf,
                        ds4_gpu_tensor_offset(up),
                        midbuf,
                        ds4_gpu_tensor_offset(mid),
                        g_qwen35_expert_group_routes_buffer,
                        g_qwen35_expert_group_key.route_count,
                        weightsbuf,
                        ds4_gpu_tensor_offset(weights),
                        gate_smem,
                        2);
            } else {
                ok = ds4_gpu_encode_mul_mv_addr_iq2_pair_swiglu(
                        cb,
                        g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_pipeline,
                        &gate_args,
                        &act_args,
                        stream_resources,
                        stream_resource_count,
                        stream_gate_addr_buf,
                        stream_up_addr_buf,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        gatebuf,
                        ds4_gpu_tensor_offset(gate),
                        upbuf,
                        ds4_gpu_tensor_offset(up),
                        midbuf,
                        ds4_gpu_tensor_offset(mid),
                        selectedbuf,
                        ds4_gpu_tensor_offset(selected),
                        weightsbuf,
                        ds4_gpu_tensor_offset(weights),
                        gate_smem,
                        2,
                        false);
            }
            if (!ok) {
                fprintf(stderr,
                        "ds4: Metal streaming prefill batch selected addr layer=%u "
                        "failed to encode gate/up path tokens=%u unique=%u\n",
                        layer_index,
                        n_tokens,
                        stream_unique);
            }
        } else if (use_q4_batch_expert_table) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim,
                .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float),
                .write_clamped = 0,
                .clamp_value = clamp,
            };
            ok = ds4_gpu_encode_mul_mv_table_q4_pair_swiglu(cb,
                                                            g_moe_mul_mv_table_q4_k_pair_swiglu_pipeline,
                                                            &gate_args,
                                                            &act_args,
                                                            gate_table,
                                                            up_table,
                                                            xbuf,
                                                            ds4_gpu_tensor_offset(x),
                                                            gatebuf,
                                                            ds4_gpu_tensor_offset(gate),
                                                            upbuf,
                                                            ds4_gpu_tensor_offset(up),
                                                            midbuf,
                                                            ds4_gpu_tensor_offset(mid),
                                                            selectedbuf,
                                                            ds4_gpu_tensor_offset(selected),
                                                            weightsbuf,
                                                            ds4_gpu_tensor_offset(weights),
                                                            gate_smem,
                                                            2,
                                                            false,
                                                            q4_batch_table_queue_residency);
        } else if (mlx_affine_store && !use_mm_id) {
            id<MTLComputePipelineState> pair_pipeline =
                ds4_gpu_get_moe_mv_pipeline(
                    "kernel_mul_mv_id_mlx_affine4_64_pair_swiglu_f32", 2);
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim,
                .rows = pair_rows,
                .gate_row_stride =
                    (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride =
                    (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride =
                    (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float),
                .write_clamped = 0,
                .clamp_value = clamp,
            };
            ok = pair_pipeline &&
                 ds4_gpu_encode_mul_mv_id_pair_swiglu(
                     cb, pair_pipeline, &gate_args, &act_args,
                     gate_buf, (NSUInteger)gate_inner,
                     up_buf, (NSUInteger)up_inner,
                     xbuf, ds4_gpu_tensor_offset(x),
                     gatebuf, ds4_gpu_tensor_offset(gate),
                     upbuf, ds4_gpu_tensor_offset(up),
                     midbuf, ds4_gpu_tensor_offset(mid),
                     selectedbuf, ds4_gpu_tensor_offset(selected),
                     weightsbuf, ds4_gpu_tensor_offset(weights),
                     gate_smem, 2, false);
        } else if (use_mm_id) {
            /*
             * The routed pair ids are the same for gate, up, and down. Build
             * the expert-major work map once, then reuse it for all three
             * batched expert matmuls.
             */
            ok = use_qwen_iq_compact_mm ?
                ds4_gpu_encode_mul_mm_id_compact_qwen_map(
                    cb,
                    map_pipeline,
                    &gate_map_args,
                    &gate_mm_args,
                    selectedbuf,
                    ds4_gpu_tensor_offset(selected)) :
                ds4_gpu_encode_mul_mm_id_map(
                    cb,
                    map_pipeline,
                    &gate_map_args,
                    &gate_mm_args,
                    selectedbuf,
                    ds4_gpu_tensor_offset(selected));
            DS4_METAL_PROFILE_MOE_STAGE("map");
            if (ok && use_mm_id_pair_swiglu) {
                ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                    .width = expert_mid_dim,
                    .rows = pair_rows,
                    .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                    .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                    .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(uint16_t),
                    .weight_stride = sizeof(float),
                    .write_clamped = 0,
                    .clamp_value = clamp,
                };
                ok = ds4_gpu_encode_mul_mm_id_pair_swiglu_f16(cb,
                                                                   pair_swiglu_mm_pipeline,
                                                                   &gate_mm_args,
                                                                   &act_args,
                                                                   pair_swiglu_mm_tile_n,
                                                                   gate_buf,
                                                                   (NSUInteger)gate_inner,
                                                                   up_buf,
                                                                   (NSUInteger)up_inner,
                                                                   xbuf,
                                                                   ds4_gpu_tensor_offset(x),
                                                                   midbuf,
                                                                   ds4_gpu_tensor_offset(mid),
                                                                   weightsbuf,
                                                                   ds4_gpu_tensor_offset(weights));
                DS4_METAL_PROFILE_MOE_STAGE("gate_up_fused");
            } else if (ok) {
                ok = use_qwen_iq_compact_mm ?
                    ds4_gpu_encode_mul_mm_id_compact_qwen_mapped(
                        cb,
                        gate_mm_pipeline,
                        &gate_mm_args,
                        gate_buf,
                        (NSUInteger)gate_inner,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        gatebuf,
                        ds4_gpu_tensor_offset(gate),
                        mm_id_threadgroup_bytes,
                        false) :
                    ds4_gpu_encode_mul_mm_id_mapped_tile(
                        cb,
                        gate_mm_pipeline,
                        &gate_mm_args,
                        gate_buf,
                        (NSUInteger)gate_inner,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        gatebuf,
                        ds4_gpu_tensor_offset(gate),
                        mm_id_threadgroup_bytes);
                DS4_METAL_PROFILE_MOE_STAGE("gate");
            }
            if (ok && !use_mm_id_pair_swiglu) {
                ok = use_qwen_iq_compact_mm ?
                    ds4_gpu_encode_mul_mm_id_compact_qwen_mapped(
                        cb,
                        up_mm_pipeline,
                        &gate_mm_args,
                        up_buf,
                        (NSUInteger)up_inner,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        upbuf,
                        ds4_gpu_tensor_offset(up),
                        mm_id_threadgroup_bytes,
                        false) :
                    ds4_gpu_encode_mul_mm_id_mapped_tile(
                        cb,
                        up_mm_pipeline,
                        &gate_mm_args,
                        up_buf,
                        (NSUInteger)up_inner,
                        xbuf,
                        ds4_gpu_tensor_offset(x),
                        upbuf,
                        ds4_gpu_tensor_offset(up),
                        mm_id_threadgroup_bytes);
                DS4_METAL_PROFILE_MOE_STAGE("up");
            }
        } else if (use_tiny_pair_mv) {
            id<MTLComputePipelineState> pair_pipeline =
                gate_type == DS4_METAL_TENSOR_IQ2_XXS ?
                    g_moe_mul_mv_id_iq2_xxs_pair_pipeline :
                    g_moe_mul_mv_id_q4_k_pair_pipeline;
            ok = ds4_gpu_encode_mul_mv_id_pair(cb,
                                                 pair_pipeline,
                                                 &gate_args,
                                                 gate_buf,
                                                 (NSUInteger)gate_inner,
                                                 up_buf,
                                                 (NSUInteger)up_inner,
                                                 xbuf,
                                                 ds4_gpu_tensor_offset(x),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 gate_smem,
                                                 2,
                                                 false);
        } else {
            ok = ds4_gpu_encode_mul_mv_id(cb,
                                                  gate_mv_pipeline,
                                                  &gate_args,
                                                  gate_buf,
                                                  (NSUInteger)gate_inner,
                                                  xbuf,
                                                  ds4_gpu_tensor_offset(x),
                                                  gatebuf,
                                                  ds4_gpu_tensor_offset(gate),
                                                  selectedbuf,
                                                  ds4_gpu_tensor_offset(selected),
                                                  gate_smem,
                                                  2,
                                                  false) &&
                 ds4_gpu_encode_mul_mv_id(cb,
                                                  gate_mv_pipeline,
                                                  &gate_args,
                                                  up_buf,
                                                  (NSUInteger)up_inner,
                                                  xbuf,
                                                  ds4_gpu_tensor_offset(x),
                                                  upbuf,
                                                  ds4_gpu_tensor_offset(up),
                                                  selectedbuf,
                                                  ds4_gpu_tensor_offset(selected),
                                                  gate_smem,
                                                  2,
                                                  false);
        }
        DS4_METAL_PROFILE_MOE_STAGE("gate_up");
        const bool use_fused_activation = !g_quality_mode && !use_q4_batch_expert_table;
        const bool use_mid_f16 =
            (use_mm_id || use_stream_mm_id) &&
            use_fused_activation &&
            request_mid_f16;
        if (mid_is_f16) *mid_is_f16 = use_mid_f16;
        if (ok && affine_pair_writes_mid) {
            /* The affine pair kernel already wrote weighted SwiGLU rows. */
        } else if (ok && use_stream_batch_selected_addr &&
            !use_stream_mm_id) {
            /* The address-table pair kernel already wrote weighted SwiGLU rows into mid. */
        } else if (ok && use_q4_batch_expert_table) {
            /* The table pair kernel already wrote weighted SwiGLU rows into mid. */
        } else if (ok && use_mm_id_pair_swiglu) {
            /* The fused batch mm_id pair kernel already wrote weighted f16 SwiGLU rows into mid. */
        } else if (ok && use_fused_activation) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                    gatebuf,
                                                    ds4_gpu_tensor_offset(gate),
                                                    upbuf,
                                                    ds4_gpu_tensor_offset(up),
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    weightsbuf,
                                                    ds4_gpu_tensor_offset(weights),
                                                    expert_mid_dim,
                                                    pair_rows,
                                                    clamp,
                                                    use_mid_f16);
        } else if (ok && clamp > 1.0e-6f) {
            ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 g_unary_clamp_pipeline,
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 expert_mid_dim,
                                                 pair_rows,
                                                 0,
                                                 -FLT_MAX,
                                                 clamp);
            if (ok) {
                ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                     g_unary_silu_pipeline,
                                                     gatebuf,
                                                     ds4_gpu_tensor_offset(gate),
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     expert_mid_dim,
                                                     pair_rows,
                                                     1,
                                                     0.0f,
                                                     0.0f);
            }
            if (ok) {
                ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 g_unary_clamp_pipeline,
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 expert_mid_dim,
                                                 pair_rows,
                                                 0,
                                                 -clamp,
                                                 clamp);
            }
            if (ok) {
                ds4_gpu_bin_args mul_args =
                    ds4_gpu_make_bin_same_rows_args(expert_mid_dim, pair_rows);
                ok = ds4_gpu_encode_bin_f32_rows(cb,
                                                   g_mul_pipeline,
                                                   &mul_args,
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid));
            }
        } else if (ok) {
            ok = ds4_gpu_encode_swiglu_flat(cb,
                                              gatebuf,
                                              ds4_gpu_tensor_offset(gate),
                                              upbuf,
                                              ds4_gpu_tensor_offset(up),
                                              midbuf,
                                              ds4_gpu_tensor_offset(mid),
                                              (uint32_t)((uint64_t)pair_rows * expert_mid_dim));
        }
        if (ok && !use_fused_activation && !use_q4_batch_expert_table &&
            !affine_pair_writes_mid) {
            ds4_gpu_bin_args weight_args =
                ds4_gpu_make_bin_rowwise_scalar_args(expert_mid_dim, pair_rows);
            ok = ds4_gpu_encode_bin_f32_rows(cb,
                                               g_bin_mul_scalar_pipeline,
                                               &weight_args,
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid),
                                               weightsbuf,
                                               ds4_gpu_tensor_offset(weights),
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid));
        }
        DS4_METAL_PROFILE_MOE_STAGE("activation_weight");

        id<MTLBuffer> down_dst = n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
        NSUInteger down_dst_off = n_expert == 1 ? ds4_gpu_tensor_offset(out) :
            (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
        if (ok) {
            if (use_stream_batch_selected_addr) {
                if (use_stream_mm_id) {
                    ok = ds4_gpu_encode_mul_mm_id_addr_mapped_tile(
                            cb,
                            down_mm_pipeline,
                            &down_mm_args,
                            stream_down_addr_buf,
                            midbuf,
                            ds4_gpu_tensor_offset(mid),
                            down_dst,
                            down_dst_off,
                            mm_id_threadgroup_bytes,
                            stream_resources,
                            stream_resource_count,
                            2);
                } else if (use_qwen_q4_batch_selected_addr) {
                    id<MTLComputePipelineState> sum_pipeline =
                        mlx_affine_store
                            ? ds4_gpu_get_moe_mv_pipeline(
                                "kernel_mul_mv_addr_mlx_affine4_64_sum8_f32",
                                2)
                            : g_moe_mul_mv_addr_q4_k_sum6_pipeline;
                    ok = ds4_gpu_encode_mul_mv_addr_q4_sum8_stream(
                            cb,
                            sum_pipeline,
                            &down_args,
                            stream_resources,
                            stream_resource_count,
                            stream_down_addr_buf,
                            midbuf,
                            ds4_gpu_tensor_offset(mid),
                            outbuf,
                            ds4_gpu_tensor_offset(out),
                            selectedbuf,
                            ds4_gpu_tensor_offset(selected),
                            down_smem,
                            2);
                } else {
                    ok = ds4_gpu_encode_mul_mv_addr_q2_sum6(
                            cb,
                            g_moe_mul_mv_addr_q2_k_sum6_pipeline,
                            &down_args,
                            stream_resources,
                            stream_resource_count,
                            stream_down_addr_buf,
                            midbuf,
                            ds4_gpu_tensor_offset(mid),
                            outbuf,
                            ds4_gpu_tensor_offset(out),
                            selectedbuf,
                            ds4_gpu_tensor_offset(selected),
                            down_smem,
                            2);
                }
                if (!ok) {
                    fprintf(stderr,
                            "ds4: Metal streaming prefill batch selected addr layer=%u "
                            "failed to encode down path tokens=%u unique=%u\n",
                            layer_index,
                            n_tokens,
                            stream_unique);
                }
            } else if (use_q4_batch_expert_table) {
                ok = ds4_gpu_encode_mul_mv_table_q4_sum6(cb,
                                                         g_moe_mul_mv_table_q4_k_sum6_pipeline,
                                                         &down_args,
                                                         down_table,
                                                         midbuf,
                                                         ds4_gpu_tensor_offset(mid),
                                                         outbuf,
                                                         ds4_gpu_tensor_offset(out),
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         down_smem,
                                                         2,
                                                         q4_batch_table_queue_residency);
            } else if (direct_down_sum) {
                ok = ds4_gpu_encode_mul_mv_id_sum6(cb,
                                                     down_sum6_pipeline,
                                                     &down_args,
                                                     down_buf,
                                                     (NSUInteger)down_inner,
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     outbuf,
                                                     ds4_gpu_tensor_offset(out),
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     down_smem,
                                                     2);
            } else if (use_mm_id) {
                ok = use_qwen_iq_compact_mm ?
                    ds4_gpu_encode_mul_mm_id_compact_qwen_mapped(
                        cb,
                        down_mm_pipeline,
                        &down_mm_args,
                        down_buf,
                        (NSUInteger)down_inner,
                        midbuf,
                        ds4_gpu_tensor_offset(mid),
                        down_dst,
                        down_dst_off,
                        mm_id_threadgroup_bytes,
                        true) :
                    ds4_gpu_encode_mul_mm_id_mapped_tile(
                        cb,
                        down_mm_pipeline,
                        &down_mm_args,
                        down_buf,
                        (NSUInteger)down_inner,
                        midbuf,
                        ds4_gpu_tensor_offset(mid),
                        down_dst,
                        down_dst_off,
                        mm_id_threadgroup_bytes);
            } else {
                ok = ds4_gpu_encode_mul_mv_id(cb,
                                                     down_mv_pipeline,
                                                     &down_args,
                                                     down_buf,
                                                     (NSUInteger)down_inner,
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     down_dst,
                                                     down_dst_off,
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     down_smem,
                                                     2,
                                                     false);
            }
        }
        DS4_METAL_PROFILE_MOE_STAGE("down");
        if (ok &&
            n_expert > 1 &&
            !direct_down_sum &&
            !use_q4_batch_expert_table &&
            ((!use_stream_batch_selected_addr &&
              use_mm_id) ||
             (use_stream_batch_selected_addr && use_stream_mm_id))) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       down_dst,
                                                       down_dst_off,
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       n_tokens);
        }
        DS4_METAL_PROFILE_MOE_STAGE("sum");
        if (!ok) {
            fprintf(stderr,
                    "ds4: Metal routed batch MoE failed before submit layer=%u tokens=%u "
                    "gate=%s down=%s path=%s\n",
                    layer_index,
                    n_tokens,
                    ds4_gpu_metal_tensor_type_name(gate_type),
                    ds4_gpu_metal_tensor_type_name(down_type),
                    moe_path);
            return 0;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "routed batch MoE")) {
            if (use_stream_batch_selected_addr) {
                ds4_gpu_stream_expert_cache_clear_layer(layer_index);
            }
            return 0;
        }
        if (use_stream_batch_selected_addr) {
            if (!owned) {
                if (ds4_gpu_end_commands() == 0) {
                    ds4_gpu_stream_expert_cache_clear_layer(layer_index);
                    return 0;
                }
                if (ds4_gpu_begin_commands() == 0) {
                    fprintf(stderr,
                            "ds4: Metal streaming prefill batch selected addr layer=%u "
                            "failed to reopen command batch after execution\n",
                            layer_index);
                    return 0;
                }
            }
        }
        if (q4_batch_table_boundary) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                return 0;
            }
        }
        selected_expert_group_used = actual_expert_schedule;
#undef DS4_METAL_PROFILE_MOE_STAGE
    }

    if (expert_group_used) {
        *expert_group_used = selected_expert_group_used;
    }
    return 1;
}

int ds4_gpu_routed_moe_batch_select_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                layer_index,
        uint32_t                n_tokens,
        bool                   *mid_is_f16,
        int                     schedule_request,
        int                    *schedule_used) {
    return ds4_gpu_qwen35_routed_moe_batch_select_tensor(
        out, gate, up, mid, experts,
        model_map, model_size,
        gate_offset, up_offset, down_offset,
        gate_type, down_type,
        gate_expert_bytes, gate_row_bytes,
        down_expert_bytes, down_row_bytes,
        expert_in_dim, expert_mid_dim, out_dim,
        selected, weights,
        n_total_expert, n_expert, clamp, x,
        layer_index, n_tokens, mid_is_f16,
        schedule_request, schedule_used);
}

